COLLDATA("mujamawsat","ur",[[5695,"سیدنا ابو عبد الرحمن رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم اور سیدہ عائشہ منی اینجا کو ایک کپڑے میں نماز پڑھتے ہوئے دیکھا، اس کا نصف نبی علینا پر تھا اور نصف سیدہ عائشہ بولی لوہا پر تھا۔ اس حدیث کو عبد الملک بن ابی سلیمان سے صرف علی بن ہاشم نے روایت کیا۔ اس میں ضرار بن صرد کا تفرد ہے۔ یہ ابو: عبد الرحمن سے صرف اسی اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٢/٥٠)، مجمع البحرين (٦٩٢)، اس میں ضرار بن صرد ضعیف۔"}],[5696,"سیدہ عائشہ مولی الہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم اپنے اعتکاف کی جگہ سے اپنا سر مبارک میری طرف باہر نکالتے تھے، پس میں اسے دھو دیتی تھی جبکہ میں حائضہ ہوتی تھی۔ اس حدیث کو حماد سے صرف محمد بن ابان نے روایت کیا، اس میں عبد الحمید بن صالح کا تفرد ہے۔","",{"k":"صحیح بخاری، رقم: ٢٠٣١ صحیح مسلم (٢٩٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ معتکف آدمی سر یا بدن دھو سکتا ہے، (٢) معلوم ہوا کہ اعتکاف کی حالت میں بیوی اپنے شوہر کی خدمت کر سکتی ہے، اگر چہ وہ حائضہ بھی ہو، (٣) یہ بھی معلوم ہوا کہ روزے کی حالت میں جسم اور لباس کی نظافت کا اہتمام بھی کرنا چاہیے۔ ٥٦٩٧"}],[5697,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، رسول اللہ نے جب رکوع سے سر اٹھاتے تو فرماتے تھے: ((سمع اللہ لمن حمدہ) اور ہم سجدہ نہیں کرتے تھے حتی کہ ہم آپ صلی اللہ علیہ وسلم کو زمین پر سجدہ ریز ) دیکھ لیتے تھے۔ اس حدیث کو اشعث بن سوار سے صرف حفص نے روایت کیا، اس میں محمد بن عبد اللہ اور ابن نمیر کا تفرد ہے۔","",{"k":"کر صحیح بخاری (٦٩٠)، صحيح مسلم (٤٧٤)۔","f":"میں جانا چاہیے۔ مذکورہ حدیث سے معلوم ہوا کہ جب امام سجدے میں چلا جائے تو پھر مقتدی کو سجدے ٥٦٩٨"}],[5698,"نافع نے بیان کیا، میں نے سیدنا عبد اللہ ابن عمر نی لینے کو دیکھا کہ ایک آدمی نے ان کے پہلو میں چھینک ماری تو اس نے کہا: ((الحمد لله وسلام علی رسول الله)) تو سیدنا عبداللہ ابن عم رضی اللہ عنہ علیہ وسلم نے فرمایا: میں بھی کہتا ہوں: ((السلام على رسول الله، لیکن رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس طرح حکم نہیں فرمایا، رسول اللہ ہے ہم نے ہمیں حکم فرمایا کہ جب ہم چھینک ماریں تو ہم کہیں: ((الحمد لله على كل حال)) ”ہر حال میں اللہ کا شکر ہے۔“ اس حدیث کو سعید بن عبد العزیز سے صرف الولید بن مسلم نے روایت کیا۔ اس میں سہیل بن صالح کا تفرد ہے۔: ٥٦٩٩","",{"k":"يرو قال الشيخ الالباني: حسن . سنن ترمذی (٢٧٣٨)۔","f":"٨° (١) مذکورہ حدیث سے معلوم ہوا کہ ہر کام میں اتباع رسول ملے تعلیم ہی ضروری ہے۔ (١) نبی مکرم طلیے علیم کا ادب و احترام یہی ہے کہ آپ صلی اللہ علیہ وسلم کے حکموں کی متابعت کی جائے، (٣) چھینک آنے پر ((الحمد لله على كل حال کہنا جائز ہے، اسی طرح ایک حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کہ جب تم میں سے کسی کو چھینک آئے تو اسے چاہیے کہ الحمد للہ کہے اور ( سننے والا ) اس کا بھائی یا اس کا ساتھی اس کے لیے (( يرحمك الله )) کہے تو چھینکنے والا کہے: (( يهديكم الله ويصلح بالكم)) الله تعالیٰ تمہیں ہدایت دے اور تمہارے حال کی اصلاح فرمائے۔“ (بخاری، کتاب الادب، رقم: ٦٢٢٤)"}],[5699,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے کہ بنو ہاشم کے کچھ افراد آئے۔ جب رسول اللہ علیم نے انہیں دیکھا تو آپ ملنے ہیم کا چہرہ سرخ ہو گیا اور آنکھوں میں آنسو بھر آئے۔ ہم نے عرض کیا: اللہ کے رسول! ہم آپ صلی اللہ علیہ وسلم کے چہرے پر ناپسندیدگی کے آثار دیکھ رہے ہیں۔ آپ ملنے سلیم نے فرمایا: ”ہم اہل بیت کے لیے اللہ تعالیٰ نے دنیا پر آخرت کا انتخاب کیا ہے، میرے اہل بیت میرے بعد عنقریب انتشار کا شکار ہو جائیں گے، حتی کہ ادھر مشرق کی طرف سے کچھ لوگ آئیں گے اور کالے جھنڈوں والے آئیں گے، وہ حق مانگیں گے لیکن انہیں دیا نہیں جائے گا، وہ پھر حق مانگیں گے لیکن انہیں دیا نہیں جائے گا، آپ ملنے سے تم نے دو یا تین بار فرمایا پس وہ قتال کریں گے تو وہ جو مانگیں گے انہیں دیا جائے گا، وہ قبول نہیں کریں گے حتی کہ وہ اسے میرے اہل بیت میں سے ایک آدمی کے حوالے کریں گے، وہ اسے عدل سے بھر دے گا جس طرح انہوں نے اسے ظلم سے بھرا تھا، پس جو اس زمانے کو پالے تو وہ ان کے پاس جائے خواہ برف پرسرین کے بل چل کر آئے۔ اس حدیث کو صباح المزنی سے صرف ابواحمد نے روایت کیا۔ اس میں اس کے بیٹے کا تفرد ہے۔","",{"k":"سنن ابن ماجه کتاب الفتن باب خروج المهدی (٤٠٨٢)، قال الشيخ الالباني: ضعيف۔"}],[5700,"سیدہ عائشہ بین النہا سے روایت ہے کہ نبی ملت علی فجر کی نماز کے علاوہ ہر نماز کے بعد دو رکعتیں پڑھا کرتے تھے اور فجر کی نماز میں انہیں اس سے پہلے پڑھا کرتے تھے۔‘ اس حدیث کو ابوالضحیٰ سے صرف حبیب بن حسان نے روایت کیا۔ اس میں ابو احمد کا تفرد ہے۔ ٥٧٠١","",{"k":"مجمع الزوائد (٢/٢٣٣)، بن ابی الاشہرس ضعیف ہے ۔ مجمع البحرين، رقم: ٣٠. اس میں حبیب بن حسان۔"}],[5701,"سیدہ عائش مولی این جا نے فرمایا: ”نبی نے علی یم مغرب کی نماز جلد پڑھتے تھے اور جس وقت سورج غروب ہو جاتا تو آپ صلی اللہ علیہ وسلم افطار کرتے تھے۔ اس حدیث کو عمارہ بن عمیر سے صرف حبیب بن حسان نے روایت کیا، اس میں ابو احمد کا تفرد ہے۔: فائد مذکورہ حدیث سے معلوم ہوا کہ مغرب کی نماز اور روزے کو جلدی افطار کرنا چاہیے۔","",{"k":"صحيح مسلم (١٠٩٩)، سنن ابو داود (٢٣٥٤)، سنن ترمذی (٧٠٢)۔"}],[5702,"سیدنا جابر رنی اہلیہ نے بیان کیا، رسول اللہ تعلیم نے فرمایا: ” اپنے کپڑے لپیٹ کر رکھا کرو، ان کی ارواح ان کی طرف لوٹ آتی ہیں، کیونکہ شیطان جب لپٹا ہوا کپڑا دیکھتا ہے تو وہ اسے نہیں پہنتا اور جب اسے بکھرا ہوا پاتا ہے تو اسے پہن لیتا ہے۔“ اس حدیث کو ابو الزبیر سے صرف عمر بن موسی بن وجیہ نے روایت کیا اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ ٥٧٠٣","",{"k":"مجمع الزوائد (١٣٨/٥)، سلسة ضعيفه (٢٨٠١)، مجمع البحرين (٤٢٤٤)، ضعيف الجامع الصغير (٩١٥)۔"}],[5703,"سیدنا ابو ہریرہ رضی اللہ عنہ کے بارے میں نبی صلی اللہ علیہ وسلم سے مرفوع روایت کرتے ہیں، آپ ملل علیم نے روندی جانے والی مورتیوں کے بارے میں رخصت دی اور جو مورتیاں نصب کی جائیں انہیں ناپسند کیا۔ اس حدیث کو محمد بن سیرین سے صرف سلیمان بن ارقم نے روایت کیا۔ ٥٧٠٤","",{"k":"مجمع الزوائد (١٧٧/٥)، اس میں سلمان بن ارقم ضعیف ہے۔۔"}],[5704,"سیدنا ابو درداءرضی المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے لیے آٹا نہیں چھانا جاتا تھا اور آپ کے لیے صرف ایک ہی قمیض تھی۔ یہ حدیث سیدنا ابو درداءرضی اللہ سے صرف اسی اسناد سے مروی ہے۔ اس میں یونس بن بکیر کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٣١٢)، ضعیف ترغیب و ترهيب (١٩٠٥)، مجمع البحرين (٥١٣٥)، قال الشيخ الالباني: موضوع۔"}],[5705,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”تم میں سے کسی کا پیٹ پیپ سے بھر جائے تو وہ اس کے لیے اس سے بہتر ہے کہ وہ شعروں سے بھرے۔“","",{"k":"صحیح بخاری (٦١٥٥)، مسلم (٢٢٥٧)۔"}],[5706,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم عرفات کے میدان میں تھے اور آپ لئے علیم ہاتھ اٹھا کر دعا کر رہے تھے، اونٹنی کی مہار گر گئی تو آپ صلی اللہ علیہ وسلم نے اسے پکڑ لیا اور پھر ہاتھ اٹھائے، نبی علیہ اسلام کے اصحاب نے کہا: یہ آہ وزاری اور تضرع ہے۔\"","",{"k":"مجمع الزوائد (١٧١/١٠)، مجمع البحرين، رقم: (٤٦٣٠)، اسناده حسن۔"}],[5707,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں، میں نے نبی مالم کو فرماتے ہوئے سنا جبکہ آپ صلی اللہ علیہ وسلم مدینہ میں تھے اے اللہ! مکہ میں جو برکت ہے اس سے دگنی اس (مدینہ ) میں فرما۔“ اس حدیث کو زہری سے صرف اسامہ بن زید نے روایت کیا۔اس میں عبد اللہ بن موی التیمی کا تفرد ہے۔","",{"k":"بن موس التيمي عبد الله صحیح بخاری، تنفى الخبث (١٨٨٥)، صحیح مسلم (١٣٦٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جس طرح مکہ مکرمہ حرمت والا ہے، اسی طرح مدینہ منورہ بھی حرمت والا ہے۔ یہ بھی معلوم ہوا کہ مکہ مکرمہ کی نسبت مدینہ منورہ میں دو گنا زیادہ برکت ہے۔ ایک دوسری حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: بے شک ابراہیم علینا نے مکہ کو حرمت والا قرار دیا اور میں مدینہ منورہ کو حرمت والا قرار دیتا ہوں۔ (مسلم، رقم: ) معلوم ہوا کہ مکہ کوسیدنا ابراہیم کالینام کی دعا اور مدینہ کو محمد مالتعلیم کی دعا کے باعث حرمت والا قرار دیا گیا۔"}],[5708,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص علم اس لیے حاصل کرتا ہے کہ وہ اس کے ذریعے علماء پر فخر کرے یا اس کے ذریعے نادانوں سے مناظرہ و جھگڑا کرے یا اس کے ذریعے لوگوں کو اپنی طرف متوجہ کرے تو وہ جہنمی ہے۔ اس حدیث کو قتادہ سے صرف شیبان نے روایت کیا، اس میں سلیمان بن زیاد الواسطی کا تفرد ہے اور انس روی لینے سے صرف اسی اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (١/١٨٧)، سنن ترمذی (٢٦٥٤)، سنن ابن ماجه (٢٦٠)، مجمع البحرين (٣٠٥)، قال الشيخ الالباني: حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ علم اللہ ذوالجلال کی رضا کے لیے حاصل کرنا چاہیے اور اخلاص ہو دنیاوی مقصد نہ ہو۔ کیونکہ جو شخص بغیر اخلاص کے علم حاصل کرتا ہے، اس کا مقصد عام طور پر یہی ہوتا ہے کہ علم حاصل کر کے اپنے متعلق کہنا کہ میں سب سے زیادہ علم رکھتا ہوں، ایسا شخص علم حاصل کرتا ہے تو اس کی نیت خراب ہوتی ہے اور نیت کی خرابی کی وجہ سے یہ جہنم کی سزا کا مستحق ہوگا۔ ٥٧٠٩"}],[5709,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کبیرہ گناہ سات ہیں، اللہ کے ساتھ شریک ٹھہرانا، اس جان کو ناحق قتل کرنا جسے اللہ نے حرام قرار دیا ہے، پاک دامن عورت ভ پر تہمت لگانا، میدان جہاد سے فراد ہونا، یتیم کا مال کھانا اور ہجرت کے بعد پھر دارالکفر واپس چلے جانا۔“ یہ حدیث سیدنا ابوسعید خدری رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے، اس میں ابو بلال کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/١٠٧)، مجمع البحرين (١٢٦)۔","f":"مذکورہ حدیث میں کبیرہ سات گناہوں کا تذکرہ ہے، اس کا مطلب ہرگز یہ نہیں کہ صرف سات ہیں بلکہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما علیہ وسلم نے فرمایا: وہ ستر تک ہیں اور ان میں سے زیادہ قریب سات تک ہیں۔ امام طبری ہراللہ نے اس روایت کو اِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ ﴾ کے تحت اپنی تفسیر میں نقل کیا ہے۔ کبیرہ گناہ کس کو کہتے ہیں؟ جس سے اللہ ذوالجلال اور اس کے رسول ملے ہم نے کتاب وسنت میں منع کیا ہے اور سلف صالحین نے بھی اس کا ذکر کیا ہے، بعض کہتے ہیں کہ ہر وہ گناہ جس کے بارے میں دنیا میں حد ہے یا آخرت میں وعید ہے، اسے کبیرہ گناہ کہتے ہیں اور اللہ ذوالجلال فرماتے ہیں: إن تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيَأْتِكُمْ وَنُدْخِلُكُمْ مُدْخَلا كَرِيمًا (النساء: ٣١) اور اگر تم ان بڑے بڑے گناہوں سے جن سے تمہیں منع کیا گیا ہے، باز رہو تو ہم ضرور تمہارے چھوٹے چھوٹے گناہ معاف کر دیں گے اور تمہیں ایک باعزت جگہ میں داخل کریں گے۔“ معلوم ہوا کہ کبیرہ گناہوں سے بچنے والوں کے لیے جنت ہے۔ مذکورہ بالا حدیث میں جن سات کبیرہ گناہوں کا تذکرہ ہے ان میں سے:\n(١) شرک یہ سب سے بڑا گناہ ہے اس کی دو اقسام ہیں۔ (١) اللہ ذوالجلال کے ساتھ کسی کو شریک بنایا جائے اور اس کے سوا اس کی پوجا کی جائے، جیسے حجر، شجر، سورج، چاند، نبی، بزرگ یا فرشتہ وغیرہ تو ایسے مشرک آدمی کو اللہ ذوالجلال نے معاف نہیں کرنا۔ فَمَنْ كَانَ يَرْجُوا لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبَّةٍ أَحَدًا (الكهف: ١١٠) پس جو شخص اپنے رب سے ملاقات کی امید رکھتا ہے اسے چاہیے کہ وہ نیک عمل کرے اور اپنے رب کی عبادت میں کسی کو شریک نہ کرے۔“\n(٢) کسی مسلمان کو ناحق قتل کرنا، ارشاد باری تعالیٰ ہے: وَ مَنْ يَقْتُلْ مُؤْمِنًا مُتَعَيْدًا فَجَزَآؤُهُ جَهَنَّمُ خَلِدًا فِيْهَا وَغَضِبَ اللهُ عَلَيْهِ وَ لَعَنَهُ وَ اعدَّ لَهُ عَذَابًا عَظِيمًا (النساء: ٩٣) \"جو شخص کسی مومن شخص کو جان بوجھ کر مار ڈالے تو اس کی سزا جہنم ہے، جہاں وہ ہمیشہ رہے گا اور اس پر اللہ کا غضب ہوا اور اس نے اس پر لعنت کی اور اس کے لیے بڑا عذاب تیار کر رکھا ہے۔“\n(٣) پاک دامن عورتوں پر زنا کی تہمت لگانا بھی کبیرہ گناہ ہے۔ اللہ ذوالجلال فرماتے ہیں: اِنَّ الَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ لُعِنُوا فِي الدُّنْيَا وَالآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ هِ يَوْمَ تَشْهَدُ عَلَيْهِمْ الْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ (النور: ٢٣ - ٢٤) وہ لوگ جو پاک دامن بھولی بھالی ایمان دار عورتوں پر زنا کی تہمت لگاتے ہیں، ان پر دنیا و آخرت دونوں میں لعنت ہو گی اور انہیں بڑا عذاب ہو گا جس دن ان کی زبانیں ان کے ہاتھ اور ان کے پاؤں ان کے خلاف ان کے اعمال کی گواہی دیں گے۔\n(٤) میدان جہاد سے فرار ہونا بھی کبیرہ گناہ ہے لیکن جو قتال کے لیے پینترا بدلنے والا یا اپنی جماعت کی طرف پلٹ کر آنے والا ہو اس کو مفرور من القتال میں سے شمار نہیں کیا گیا۔ جیسا کہ ارشاد باری تعالیٰ ہے: وَمَنْ يُوَلِهِمْ يَوْمَئِذٍ دُبُرَةٌ إِلَّا مُتَحَرِّفًا لِقِتَالِ اَوْ مُتَحَيَّزًا إِلَى فِئَةٍ فَقَدْ بَاءَ بِغَضَبٍ مِّنَ اللهِ وَمَأْوِيهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ﴾ (الانفال: ١٦)\n(٥) سود بھی کبیرہ گناہوں میں سے ہے، سود کھانا کھلانا، گواہی دینا،لکھنا یہ تمام برابر کے گناہ ہیں اور سودی کے ساتھ اللہ ذوالجلال کا اعلان جنگ ہے اور اس کا انجام بھی بدترین ہے۔ جیسا کہ ارشاد باری تعالیٰ ہے: الَّذِينَ يَأْكُلُونَ الرَّبُوا لَا يَقُومُونَ إِلَّا كَمَا يَقُوْمُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَنُ مِنَ الْمَسِ ذلِكَ بِأَنَّهُمْ قَالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرَّبُوا ﴾ (البقره: ٢٧٥) وہ لوگ جو سود کھاتے ہیں وہ (قیامت کے دن ) اس شخص کی طرح (اپنے پاؤں پر ) کھڑے نہ ہو سکیں گے جسے شیطان نے چھو کر دیوانہ کر دیا ہو، یہ انہیں اس بات کی سزا ہے کہ انہوں نے کہا، خرید و فروخت بھی سود ہی کی طرح ہے۔“\n(٦) مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ مال یتیم کو کھانا بھی کبیرہ گناہ ہے بلکہ ایسے لوگوں کے متعلق اللہ تعالیٰ نے فرمایا: ﴿إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْبَثْمى ظُلْمًا إِنَّمَا يَأْكُلُوْنَ فِي بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا (النسا: ١٠) ”بے شک وہ لوگ جو ظلم سے یتیموں کا مال کھاتے ہیں تو وہ صرف اپنے پیٹوں میں آگ بھرتے ہیں اور عنقریب وہ جہنم میں داخل ہوں گے۔“\n(٧) ہجرت کر کے دوبارہ دارالکفر میں واپس چلے جانا بھی کبیرہ گناہ ہے، اکثر روایات میں ہجرت کر کے دوبارہ دارالکفر میں جانے کی بجائے جادو کا تذکرہ ہے۔"}],[5710,"سیدنا عبد اللہ ابن عباس نیلی جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سخنی کے گناہ سے دور رہو، کیونکہ اس سے جب بھی لغزش ہوتی ہے تو اللہ تعالیٰ اس کے ہاتھوں کو پکڑنے والا ہے۔“ یہ حدیث ابن عباس رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے، اس میں محمد بن عبید اللہ الجد عانی کا تفرد ہے۔ ٥٧١١","",{"k":"مجمع الزوائد (٦/٢٨٥)، ضعیف ترغیب و ترهیب (١٥٦٧)، مجمع البحرين (٢٤٧٠)، ضعيف الجامع الصغير (٢٣٩٠)۔"}],[5711,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: ”بنو امیہ میں سے کوئی ایک سال بادشاہ نہیں ہو گا، مگر العباس کا بیٹا دو سال بادشاہ بنا۔ ان کے ہم نشینوں میں سے ایک آدمی نے ان سے کہا: ابو حمزہ! کیا یہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہے؟ انہوں نے کہا: ہاں، وہ اسی طرح تھے جس طرح تم یہاں ہو۔ یہ حدیث انس بن مالک نہیں اللہ سے صرف اسی اسناد سے مروی ہے، اس میں بکر بن یونس بن بکیر کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥/١٩٠)، مجمع البحرين رقم: ٢٥٢١ . اس میں بکر بن یونس بن بکر شیبانی ضعیف ہے۔ ٥٧١٢۔"}],[5712,"عمی نے بیان کیا، میں نے سیدنا نعمان بن بشیر رضی اللہ عنہما کو کوفہ کے منبر پر خطاب کرتے ہوئے سنا، جس وقت معاویہ رضی اللہ عنہما نے انہیں ہمارا حکمران مقرر کیا تھا: لوگو! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”لوگو! انگور سے شراب بنتی ہے، منقی سے شراب بنتی ہے، کجھور سے شراب بنتی ہے، شہد سے شراب بنتی ہے اور میں ہر نشہ آور چیز سے منع کرتا ہوں۔“ اس حدیث کو زہری سے صرف محمد بن اسحاق نے اور محمد سے صرف محمد بن سلمہ نے روایت کیا، اس میں محمد بن الحارث الحرانی کا تفرد ہے۔","",{"k":"سنن ابو داود (٣٦٧٦)، سنن ترمذى (١٨٧٢)، قال الشيخ الالبانی۔","f":"مذکورہ حدیث کا ہرگز یہ مطلب نہیں کہ ان کے علاوہ چیزوں سے بنائی گئی شراب حرام نہیں، بلکہ اس لیے ان کا تذکرہ فرمایا کہ ان چیزوں سے عرب میں عام شراب بنائی جاتی تھی۔ پھر حدیث کے آخر میں وضاحت فرمادی کہ شراب کسی چیز سے بھی بنے، اگر نشہ آور ہے تو خمر ہے اور حرام ہے۔ ٥٧١٣"}],[5713,"سیدہ عائشہ منی انا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تم انہیں بالا خانوں میں ٹھہراؤ نہ انہیں کتابت سکھاؤ، انہیں سوت کا تنا اور سورۃ النور سکھاؤ۔ اس حدیث کو ہشام بن عروہ سے صرف شعیب بن اسحاق نے روایت کیا۔ اس میں محمد بن ابراہیم کا تفرد ہے۔","",{"k":"مجمع الزوائد (٤/٩٦)، مجمع البحرين (٢٠١٨)، سلسله ضعیفه (٢٠١٧)، اسناده ضعيف۔"}],[5714,"سیدنا عبد اللہ رضی اللہ عنہ نے بیان کیا، غزوہ بدر میں رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کی تعداد تین سو تھی۔“ اس حدیث کو عاصم سے صرف حماد بن سلمہ نے اور حماد سے صرف ابو درداء رضی اللہ عنہ نے روایت کیا،","",{"k":"مجمع الزوائد (٩٣/٦)، مجمع البحرين (٢٧٦٢)، اسناده ضعيف۔","f":"اس میں الحمانی کا تفرد ہے۔ اد مذکورہ روایت ضعیف ہے۔ نیز یہ روایت اس لیے بھی قابل حجت نہیں ہے کہ دوسری صحیح احادیث کے بھی خلاف ہے۔ صحیح بخاری میں ہے سیدنا براء بن عازب رضی اللہ عنہما سے مروی ہے، ہم رسول اللہ صلی اللہ علیہ وسلم کے صحابہ اس پر گفتگو کیا کرتے تھے کہ بدر کے مجاہدین کی تعداد اتنی ہی تھی جتنی حضرت طالوت کے مجاہدین کی تھی، وہ کہ جنہوں نے حضرت طالوت کے ہمراہ دریا پار کیا تھا، اس دریا کو سوائے مومن کے کسی نے پار نہیں کیا تھا، یہ لوگ تین سو تیرہ تھے۔ (بخاری، کتاب المغازی، رقم: ٣٩٥٨): صحیح بخاری ہی میں ہے کہ سیدنا براء بن عازب نیل الیہ کی روایت کے مطابق مہاجرین کی تعداد ساٹھ سے ذرا اوپر تھی اور انصار کی تعداد دو سو چالیس سے ذرا زیادہ تھی۔ (بخاری، کتاب المغازی، رقم: ٣٩٥٦)"}],[5715,"سیدنا ابن مسعود رضی اللہ عنہ نے مرفوعاً روایت کیا، فرمایا: ”جو رات کے وقت سورۃ البقرہ کی آخری دو آیتیں پڑھ لیتا ہے وہ اس کے لیے کافی ہو جاتی ہیں۔ اس حدیث کو عاصم سے صرف شریک نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ سورۂ بقرہ کی آخری دو آیات آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَّبِّهِ الخ ) تک رات کو سوتے وقت ان کی تلاوت کرنا مسنون ہے۔ حدیث میں ہے کہ کافی ہو جائے گی، اس کا مطلب امام شوکانی اللہ فرماتے ہیں کہ یہ دونوں آیات انسان کے لیے اس رات کو تہجد سے کفایت کریں گی، یا اسے قراءت قرآن کی بجائے کافی ہوں گی، یا اعتقاد سے متعلق کفایت کریں گی کیوں کہ یہ دونوں آیات پر اجمالاً ایمان و اعمال مشتمل ہیں یا اسے برائی اور ناپسندیدہ چیز سے بچائیں گی یا شیطان کے شر سے یا جن وانس کے شرسے کفایت کریں گی جو اسے دیگر نیکیوں سے ثواب ملتا ہے اس کے بجائے کافی ہوں گی۔“ ان سارے امور کو مراد لینے سے کوئی مانع نہیں ہے اور اس کی تائید اس سے ہوتی ہے جو علم المعانی والبیان میں مقرر ہے کہ متعلق کا حذف عموم کا","",{"k":"کر صحیح بخاری، رقم۔","f":"دیتا ہے گویا کہ فرمایا، اس کے لیے ہر شر سے اور ہر اس چیز سے کافی ہوں گی جس سے وہ ڈرتا ہے اور اللہ تعالیٰ کا فضل بڑا وسیع ہے۔ (تحفة الذاکرین: ص٩٩) الشيخ عبد العزیز بن عبد الله بن باز ر اللہ نے فرمایا: اس کا مطلب یہ ہے کہ یہ دونوں آیتیں ہر بری چیز سے وہ موذی ہو یا کوئی اور محفوظ رکھتی ہیں۔ (رسالة في حكم السحر والكهانة لابن باز) علامہ ابن قیم رحمہ اللہ فرماتے ہیں: ((الصحيح كفتاه من شر ما يوذيه)) (الوابل الصيب لابن قيم ص:٤٥) صحیح مفہوم یہ ہے کہ یہ دونوں آیتیں موذی چیز کے شر سے محفوظ رکھتی ہیں۔"}],[5716,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ نبی سے تم نے فرمایا: ”جس مسلمان کے تین بچے فوت ہو جائیں تو اللہ تعالیٰ اپنی رحمت کے فضل سے اس کے والدین کو جنت میں داخل فرمائے گا۔“ اس حدیث کو علی بن زید اور ابو عمران الجونی سے صرف حماد بن سلمہ نے اور حماد سے صرف عمرو بن عاصم نے روایت کیا۔ اس میں الحسین بن عبد الاول کا تفرد ہے۔","",{"k":"سنن نسائی (١٨٧٣)، سنن ابن ماجه (١٦٠٥)، قال الشيخ الألباني: صحيح۔"}],[5717,"سیدنا انس رضی اللہ عنہ نے بیان کیا، عقیل اور طالب ابو طالب کے وارث بنے۔ علی فضل اللی ان کے وارث نہ بنے، سیدنا علی ضیل الیہ نے فرمایا: اسی وجہ سے ہم نے وادی گھائی سے اپنا حصہ ترک کیا ہے۔“ اس حدیث کو سفیان سے صرف المعافی بن عمران نے روایت کیا۔ خاندن سیدنا اسامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مسلمان کافر کا وارث نہیں ہوسکتا اور نہ ہی کا فر مسلمان کا وارث ہو سکتا ہے۔ (صحیح بخاری، رقم: لیے ملی کہ ابو طالب کی وفات کے موقع پر یہ مسلمان نہیں تھے جبکہ سیدنا علی ضیا اللہ مسلمان تھے۔ اس لیے ان کو وراثت نہ ملی۔ ٥٧١٨","",{"k":"٥٧١٧ مجمع الزوائد (٢٢٩/٤)، مجمع البحرين (٢٢١٠)، اسناده حسن۔"}],[5718,"سیدنا ابو ہریرہ اور سیدنا ابوسعید خدری والی جا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”مومن دوسرے مومن کے لیے عمارت کی طرح ہے وہ ایک دوسرے کو مضبوط کرتا ہے۔‘“ اس حدیث کو سفیان سے صرف عبد الملک بن ابی کریمہ نے روایت کیا۔ اس میں علی بن بہرام کا تفرد ہے۔","",{"k":"٠ مجمع الزوائد (١٩١/٨)، صحیح مسلم (٢٥٨٥)، صحیح بخاری، مجمع البحرين (٢٩٠٨)۔","f":"قانون کے مذکورہ حدیث میں مسلمانوں کو اجتماعیت کا سبق دیا جا رہا ہے، ہر مسلمان اسلامی معاشرے کی ایک اینٹ ہے جس طرح عمارت میں مضبوطی ایک اینٹ کی دوسری اینٹ سے ہوتی ہے اسی طرح ایک ایمان دار کے لیے لازم ہے کہ وہ دوسرے ایمان دار کا مددگار بنے۔ جس طرح اینٹیں مل کر ایک دوسرے کی تقویت کا باعث ہوتی ہیں، اسی طرح ایک مسلمان کو چاہیے کہ اپنے بھائی مسلمان کی مدد کرے، خواہ وہ مسلمان مومن کتنا ہی دور کیوں نہ ہو، اگر چہ وہ دوسرے ملک میں ہی رہتا ہو جہاں تک ہو سکے اس کی مدد کرے۔خصوصاً اس وقت جب کافران کو ستائیں تو ایک مومن کے لیے دنیا کے تمام مومنوں کو لڑنا چاہیے۔ بخاری ومسلم میں ہے کہ سیدنا نعمان بن بشیر رضی اللہ عنہما سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مومنوں کی مثال آپس میں ایک دوسرے کے ساتھ محبت کرنے میں اور ایک دوسرے کے ساتھ رحم کرنے میں اور ایک دوسرے کے ساتھ شفقت و نرمی کرنے میں جسم کی طرح ہے جب اس کا کوئی ایک عضو درد کرتا ہے تو اس کا سارا جسم اس کی وجہ سے بیداری اور بخار میں مبتلا رہتا ہے۔ (صحیح بخاری، کتاب الادب، رقم: ٦٠١١، صحیح مسلم، رقم: ٢٥٨٦) ٥٧١٩"}],[5719,"سیدنا عمرو بن شعیب نے اپنے والد سے انہوں نے اپنے دادا سے روایت کیا، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے کعبہ کی طرف دیکھا تو فرمایا: ”اللہ نے تجھے عزت و اکرام اور عظمت عطا کی ہے، جبکہ مومن کی حرمت تم سے بڑھ کر ہے۔“","",{"k":"غاية المرام (٣٣٥)، مجمع البحرين (٨٤)۔","f":"مذکورہ حدیث مومن کی حرمت اور عظمت واضح کرتی ہے۔ (٢) یہ بھی معلوم ہوا کہ مومن کی حرمت بیت اللہ شریف سے زیادہ ہے ایک دوسری حدیث میں ہے، رسول اللہ صلی اللہ علیہ وسلم نے بیت اللہ شریف کو مخاطب ہو کر فرمایا: تو کس قدر عظیم ہے اور تیری خوشبو کتنی پاکیزہ ہے، تیرا احترام کتنا عظیم ہے، قسم ہے اس ذات کی جس کے ہاتھ میں محمد علت تعلیم کی جان ہے! اللہ کے ہاں مومن کی حرمت تیری حرمت سے بڑھ کر ہے، یعنی اس کے مال اور جان کی حرمت اور یہ کہ اس کے بارے میں بدگمانی کرنا بھی حرام ہے۔: (ابن ماجه رقم: ٣٩٣٢، بیهقی شعب الایمان: ٢٩٦/٥)"}],[5720,"سیدنا عبد اللہ بن مسعود ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قرآن سیکھو اور اسے دوسروں کو سکھاؤ، فرائض ( علم میراث) سیکھو اور اسے دوسروں کو سکھاؤ، بے شک میری روح قبض ہونے والی ہے اور ہوسکتا ہے کہ دو آدمی میراث میں اختلاف کریں اور وہ اپنے درمیان فیصلہ کرنے والا کوئی شخص نہ پائیں۔“ اس حدیث کو شریک سے صرف علی بن الحکم الا ودی نے روایت کیا۔","",{"k":"سنن دار قطنی (٨١/٤، ٨٢، ٤٥، ٤٦)۔"}],[5721,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”عشا کے بعد صرف نمازی اور مسافر کو بات چیت کرنے اور بیدار رہنے کی اجازت ہے۔‘ اس حدیث کو سفیان بن عیینہ سے صرف ابراہیم بن یوسف الصیر فی نے روایت کیا۔","",{"k":"مجمع الزوائد (١/٣١٧)، سنن ترمذی (١٦٩)، مجمع البحرين رقم : ٥٦٨ قال الشيخ الالباني: صحيح۔","f":"عام حالات میں تو یہ ہے کہ عشا کے بعد سو جانا چاہیے،عشا کے بعد جا گنا اور گپ وغیرہ لگانا درست نہیں ہے، لیکن بعض افراد کے لیے شریعت میں گفتگو کرنے اور جاگنے کا جواز ہے۔ جیسا کہ مذکورہ بالا حدیث میں ہے کہ نمازی اور مسافر کے لیے۔ اسی طرح دوسری احادیث سے ثابت ہوتا ہے کہ مہمان کے لیے بیدار ہونا یا بیوی سے گفتگو کرنا یا مسئلے مسائل کی باتیں کرنا علمی مجلس وغیرہ، جیسا کہ امام بخاری ہراللہ نے اپنی صحیح میں باب باندھ کر ثابت کیا ہے: ((باب السمر في الخير بعد العشاء، باب السمر مع الاهل الضيف)) (صحیح بخاری، رقم"}],[5722,"سیدنا علی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو بندہ جوتے پہن کر، موزے پہن کر اور کپڑے پہن کر طلب علم کے لیے روانہ ہوتا ہے تو وہ جس وقت اپنے گھر کی چوکھٹ سے قدم باہر رکھتا ہے تو اللہ اس کے گناہ معاف کر دیتا ہے۔“ یہ حدیث سیدنا علی رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں اسماعیل بن بیٹی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/١٣٣)، ضعیف ترغیب و ترهیب (٧٢)، مجمع البحرين، رقم: ١٨٣ قال الشيخ الالباني موضوع۔"}],[5723,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان کو گالی دینا فسق اور اسے قتل کرنا کفر ہے۔ اس حدیث کو ابن سیرین سے صرف ابو ہلال نے روایت کیا۔ اس میں محمد بن الحسن کا تفرد ہے۔ یہ سیدنا ابو ہریرہ یا لینے سے صرف اسی اسناد سے مروی ہے۔ ٥٧٢٤","",{"k":"سنن ابن ماجه (٣٩٤٠)، قال الشيخ الالباني: حسن صحيح۔"}],[5724,"سیدنا مسور بن مخرمہ رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم کے پاس کچھ قبائیں آئیں تو آپ نے انہیں اپنے اصحاب میں تقسیم فرما دیا تو ابو مخرمہ نے مجھے کہا: ہمیں ان کے پاس لے چلو ہوسکتا ہے کہ وہ ان میں سے ہمیں کچھ عنایت فرمائیں، پس وہ دروازے تک پہنچے تو کہا: میں حاضر ہوں، پس نبی صلی اللہ علیہ وسلم نے اس کی آواز سنی تو آپ صلی اللہ علیہ وسلم ایک قبالیے باہر تشریف لائے، گویا کہ میں آپ کی طرف دیکھ رہا ہوں میرے والد کو قبا کے محاسن دکھا رہے ہیں اور فرما رہے ہیں، میں نے یہ تمہارے لیے چھپا کر رکھ لی تھی۔“ صالح بن حاتم نے بیان کیا، میں نے اپنے والد سے کہا: نبی صلی اللہ علیہ وسلم نے یہ مخرمہ کے لیے کیوں کیا؟ انہوں نے کہا: گویا کہ اس کی زبان سے بچنے کے لیے۔ اس حدیث کو ایوب سے صرف حاتم بن وردان نے روایت کیا۔","",{"k":"صحیح بخاری (٣١٢٧)، صحیح مسلم (١٠٥٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسلمان بادشاہ کو یا امام کو غیر مسلم تحائف بھیجیں تو ان کا لینا امام کو درست ہے۔ یہ بھی معلوم ہوا کہ امام کو اختیار ہے کسی کو تحائف دے یا نہ دے۔ مذکورہ حدیث سے رسول اللہ علیم کی سخاوت کا بھی اثبات ہوتا ہے اور اپنے صحابہ کرام کا خیال رکھنا اور ان کی دلجوئی اور مدارت کا بھی خیال رکھنا اور ان کے مزاج کے بھی آگاہی رکھنا۔ ٥٧٢٥"}],[5725,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”ہر آسان، نرم سہل مزاج آدمی جہنم پر حرام ہے۔“ اس حدیث کو محمد بن سیرین سے صرف وہب بن حکیم نے روایت کیا، اس میں جمہور بن منصور کا تفرد ہے۔","",{"k":"مجمع الزوائد (٧٨/٤)، مجمع البحرين (١٩٥٨)۔"}],[5726,"سیدنا جابر نبی یا لیلین نے بیان کیا، عرض کیا گیا: اللہ کے رسول! نحوست کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”برے اخلاق۔“ یہ حدیث سیدنا جابر رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے، اس میں الفضل بن عیسی کا تفرد ہے۔","",{"k":"البحرين، رقم: ٣٠٠٢ مجمع الزوائد (٢٨/٨)، ضعیف ترغیب و ترهیب (١٦٠٩)، مجمع۔"}],[5727,"سیدنا عبداللہ ابن عمر بنی اہلیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے اشج عبد القیس سے فرمایا: ”تم میں دو خصلتیں ہیں اللہ تعالیٰ انہیں پسند کرتا ہے: حلم اور وقار “ اس حدیث کو فضیل بن عیاض سے صرف یحی بن طلحہ نے روایت کیا۔ ٥٧٢٨","",{"k":"مجمع البحرين (٣٩٢٤)۔"}],[5728,"سیدنا عبد اللہ بن مسعود ضیا اللہ نے بیان کیا، ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے عرض کیا: اللہ کے رسول! میرے اہل وعیال، والدہ اور والد ہیں، ان میں سے میری صلہ رحمی اور حسن سلوک کا زیادہ حق دار کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہاری والدہ، تمہارا والد، تمہاری بہن، تمہارا بھائی پھر ि قریبی رشتہ دار اور پھر اس کے بعد والا قریبی رشتے دار “ اس حدیث کو الشعمی سے صرف السری بن اسماعیل نے روایت کیا اور سیدنا عبد اللہ ابن مسعود رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ ٥٧٢٩","",{"k":"مجمع الزوائد (١٤٢/٨)، مجمع البحرين (٢٨٣٦)۔"}],[5729,"سیدنا ابو ہریرہ اللہ سے روایت ہے کہ نبی سے ہم نے فرمایا: ”اگر میں کسی کو خلیل جگری دوست ) بناتا تو میں ابو بکر کو خلیل بناتا “ اس حدیث کو داود الاودی سے صرف محبوب بن محرز نے روایت کیا۔","",{"k":"کر مجمع الزوائد (٩/٤٧)، مجمع البحرين (٣٦١١)۔"}],[5730,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سورہ اخلاص تہائی قرآن کے برابر ہے۔ اس حدیث کو جبریر بن حازم سے صرف یزید بن ہارون نے روایت کیا۔","",{"k":"سنن ابن ماجه (٣٧٨٨)، قال الشيخ الالباني: صحيح . ٥٧٣١۔"}],[5731,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صل علی ایم کو سبز رنگ سب سے زیادہ پسند تھا۔ اس حدیث کو قتادہ سے صرف سعید بن بشیر نے روایت کیا، اس مین ابراہیم بن المنذرکا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ سبز رنگ کے کپڑے پہننا جائز ہے۔ قرآن مجید نے اہل جنت کے ریشم کے سبز لباس کا ذکر فرمایا ہے: عَالِيَهُمْ ثِيَابُ سُندُس خُضْرٌ وَاسْتَبْرَقٌ ﴾ (الدهر: ٢١) ان کے اوپر باریک ریشم اور گاڑھے ریشم کے سبز کپڑے ہوں گے۔“ مگر سبز یا کسی اور رنگ کو بطور شعار و علامت ہمیشہ کے لیے اختیار کر لینا قطعا صحیح نہیں۔ صرف سفید رنگ کی ترغیب ثابت ہے۔ ٥٧٣٢","",{"k":"كر مجمع الزوائد (١٣٢/٥)، سلسله صحيحة (٢٠٥٤)، مجمع البحرين (٤٢١٥)، صحيح الجامع الصغير (٤٦٢٣)، اسناده صحيح۔"}],[5732,"سیدنا انس رضی اللہ عنہ نے بیان کیا، نبی ملت علی ایم کے پاس پسوؤں کا ذکر کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ تو نماز کے لیے جگاتے ہیں۔ اس حدیث کو قتادہ سے صرف سعید بن بشیر اور سوید بن ابو حاتم نے روایت کیا اور سعید بن بشیر سے صرف الولید بن مسلم نے روایت کیا۔. ٥٧٣٣","",{"k":"مجمع الزوائد (٨٠٨)، مجمع البحرين (٣١٤٧)، اس میں سعید بن بشیر ضعیف ہے۔۔"}],[5733,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے پاس سے ایک یہودی کا جنازہ گزرا تو آپ صلی اللہ علیہ وسلم کھڑے ہو گئے، آپ صلی اللہ علیہ وسلم سے عرض کیا گیا: وہ تو ایک یہودی کا جنازہ ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہم تو تمہارے فرشتے بھائیوں کے لیے کھڑے ہوئے ہیں۔“ اس حدیث کو قتادہ سے صرف حماد بن سلمہ نے روایت کیا۔ اس میں بیٹی بن عباد کا تفرد ہے۔","",{"k":"مستدرك حاكم (١/٣٨٧)۔"}],[5734,"سیدنا انس رضی اللہ عنہ نے بیان کیا، جب رسول اللہ طل علایم بیمار ہوئے آپ صلی اللہ علیہ وسلم نے ابو بکر نیل اللہ کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں، رسول اللہ صلی اللہ علیہ وسلم نے افاقہ محسوس کیا تو آپ صلی اللہ علیہ وسلم ایک کپڑے میں لیٹے ہوئے لوگوں کے ساتھ ابوبکر رضی اللہ عنہ کے پیچھے کھڑے ہو گئے","",{"k":"سنن ترمذی (٣٦٣)، قال الشيخ الالباني: حسن۔"}],[5735,"سیدنا انس بنی اللہ نے بیان کیا، رسول اللہ علی کیانی نے فرمایا: ” جب تم فیصلہ کرو تو عدل کرو، جب تم قتل کرو تو اچھی طرح ( اذیت پہنچائے بغیر) قتل کرو، کیونکہ اللہ عز وجل محسن ہے وہ احسان پسند فرماتا ہے۔“ ان حدیثوں کو قتادہ سے صرف عمران القطان نے روایت کیا، ان دونوں میں محمد بن بلال کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٠٠/٥)، مجمع البحرين (٢٥٥٢)، صحيح الجامع الصغير (٤٩٤٠)، اسناده حسن۔","f":"مذکورہ حدیث میں ایک تو عدل کرنے کا حکم ہے۔\n(١) عدل کے مشہور معنی انصاف کرنے کے ہیں، یعنی اپنوں اور بیگانوں سب کے ساتھ انصاف کیا جائے کسی کے ساتھ دشمنی یا عناد یا محبت یا قرابت کی وجہ سے انصاف کے تقاضے مجروح نہ ہوں۔ قرآن مجید میں ہے کہ: وَلَا يَجْرِمَنَّكُمْ شَنَانُ قَوْمٍ عَلَى أَلَّا تَعْدِلُوا اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوى ﴾ (المائده: ٨) کسی قوم کی عداوت تمہیں خلاف عدل پر آمادہ نہ کر دے، عدل کیا کرو جو پرہیز گاری کے زیادہ قریب ہے۔“\n(٢) دوسرا حکم شریعت نے یہ دیا ہے کہ قتل کرنا ہے تو اچھی طرح کرنا ہے، یہ قتل کا حکم عام ہے اس سے مراد یہ کہ موذی جانور کا قتل کرنا یا کسی دشمن کو میدان جنگ میں یا کسی مجرم کو قتل کرنا تو اسی طرح جانور کونشانہ بنا کر باندھ کر مارنا نا جائز ہے۔ تاہم کچھ صورتیں مخصوص ہیں۔ مثلاً سولی چڑھانا، قصاص لینا یا شادی شدہ زانی کو پتھر مار مار کر قتل کرنا، لیکن قتل کے بعد نعش کا مثلہ کرنا جائز نہیں ہے۔ اچھی طرح کا مطلب یہ ہے کہ تلوار کے ایک وار سے ہی اس کا سرتن سے جدا کر دو، یہ نہیں کہ پہلے ہاتھ کاٹ دیئے، پھر پیر، پھر ناک، پھر کان وغیرہ۔ یہ راحت نہیں بلکہ اذیت ہے تو اسلام نے اس سے منع فرمایا ہے۔ ٥٧٣٦"}],[5736,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، جب نبی سلام کی بیٹی رقیہ بنایا جانے وفات پائی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہمارے سلف صالح عثمان بن مظعون رضی اللہ عنہ کے ساتھ مل جا۔‘ اس حدیث کو قتادہ سے صرف صالح المری نے روایت کیا۔ اس میں یونس بن محمد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٥/٩)، مسند احمد (١/٢٣٧)، مجمع البحرين (٣٨٥٩)، اسناده ضعيف۔"}],[5737,"سیدنا انس بن مالک نبی اللہ نے بیان کیا، رسول اللہ ملے عام قیام فرماتے، حتی کہ آپ صلی اللہ علیہ وسلم کے قدم سوج گئے، آپ صلی اللہ علیہ وسلم سے عرض کیا گیا: کیا اللہ تعالیٰ نے آپ کی تمام اگلی پچھلی لغزشیں معاف نہیں کر دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا میں شکر گزار بندہ نہ بنوں؟“ اس حدیث کو مسعر عن قتادہ عن انس کی سند سے صرف عبد اللہ بن عون نے محمد بن بشر سے روایت کیا اور ان کے علاوہ دوسروں نے محمد بن بشر عن مسعر عن زياد بن علاقه عن المغيرة بن شعبہ کی سند سے روایت کیا اور ابو قتادہ الحرانی نے اسے مسعر عن علی بن اقمر، عن ابی جحیفہ کی سند سے روایت کیا اور سیف بن محمد بن اخت سفیان نے اسے زیاد بن علاقہ عن المغیرہ بن شعبہ کی سند سے روایت کیا۔","",{"k":"وَرَوَاهُ أَبُو قَتَادَةَ الْحَرَّانِيُّ: عَنْ مِسْعَرٍ، عَنْ عَلِيِّ بْنِ الْأَقْمَرِ، عَنْ أَبِي جُحَيْفَةَ، وَرَوَاهُ سَيْفُ بْنُ مُحَمَّدِ ابْنِ أُخْتِ سُفْيَانَ، عَنْ زِيَادِ بْنِ عِلاقَةَ، عَنِ الْمُغِيرَةِ بْن شُعْبَةَ . مجمع الزوائد (٢/٢٧٤)، مجمع البحرين (١١١٩)، اسناده صحیح۔"}],[5738,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، جب ہم برص کے مریض کو ہاتھ لگاتے والله تھے تو ہم وضو کیا کرتے تھے۔“ یہ حدیث سیدنا عبداللہ ابن مسعود بنی اہلیہ سے صرف اسی اسناد سے مروی ہے، اس میں محمد بن عبد اللہ بن نمیر کا تفرد ہے، ہم نے اسے صرف حضرمی سے لکھا ہے، ان سے عبد اللہ بن احمد بن حنبل نے لکھا ہے۔ ٥٧٣٩",""],[5739,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مثلہ سے منع فرمایا ہے۔ اس حدیث کو ابو یکی الفتات سے صرف محمد بن ابان نے روایت کیا ہے، اس میں عبدالحمید بن صالح کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (٢٥٢/٦)، مجمع البحرين (٢٤٢٤)۔"}],[5740,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (استقبال رمضان کے لیے ) رمضان سے پہلے روزہ نہ رکھو اور اس (رمضان کے چاند ) کو دیکھ کر روزہ رکھو اور اس (شوال کے چاند ) کو دیکھ کر روزہ رکھنا بند کر دو، اگر مطلع ابر آلود ہو تو تمیں کی گنتی مکمل کر لو۔“ اس حدیث کو اشعث سے صرف ابو الاحوص نے اور ابو الاحوص سے صرف خلف بن تمیم نے روایت کیا۔اس میں صالح بن زیاد کا تفرد ہے۔ ٥٧٤١","",{"k":"سنن ابو داود (٢٣٢٧)، سنن ترمذی (٦٨٨)، قال الشيخ الالباني: صحيح۔"}],[5741,"سیدہ عائشہ بنی سنہا نے بیان کیا، رسول اللہ علیم نے فرمایا: ” تم کسی چیز کو مخصوص نہ کر لو، کیونکہ میں صرف اسی چیز کو حلال قرار دیتا ہوں جسے اللہ نے اپنی کتاب میں حلال قرار دیا ہے اور میں صرف: اسی چیز کو حرام قرار دیتا ہوں جسے اللہ نے اپنی کتاب میں حرام قرار دیا ہے۔“ اس حدیث کو یحی بن سعید سے صرف علی بن عاصم نے روایت کیا۔ اس میں الزعفرانی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/١٧٥)، مجمع البحرين (٢٦٥)، اسناده ضعيف۔"}],[5742,"سیدہ عائشہ صلی علیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جنت میں ایک گھر ہے، اسے بیت السخاء کہا جاتا ہے۔ اس حدیث کو اوزاعی سے صرف بقیہ نے روایت کیا، اس میں جمد ر بن عبد اللہ الرجی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/١٣١)، ضعیف ترغیب و ترهیب (١٥٦٣)، مجمع البحرين (١٤١٩)، قال الشيخ الالباني : منكر۔"}],[5743,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدہ ام سلمہ بنی النیہا سے شادی کی تو آپ نے کھجور اور گھی سے ولیمہ کیا۔ اس حدیث کو حمید سے صرف شریک نے روایت کیا۔","",{"k":"مجمع الزوائد (٥٠/٤)، مجمع البحرين (١٨٩٥)، اسناده ضعیف۔","f":".. سیدنا انس بن مالک نبی اللہ سے مروی ہے کہ نبی مکرم ملے تم نے سیدہ صفیہ بنی الجھا کے نکاح میں ستو اور کھجور سے ولیمہ کیا تھا۔ (ابو داؤد، رقم: ٣٧٤٤) معلوم ہوا کہ ضروری نہیں کہ شادی میں گوشت ہی پکایا جائے بلکہ جو بھی میسر ہو پیش کر دینا چاہیے۔"}],[5744,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے ایک اونٹ خریدا اور انہوں نے مدینے تک اس کی سواری کو مستثنیٰ قرار دیا۔ اس حدیث کو منصور سے صرف شریک نے روایت کیا۔ اس میں محمد بن الحسن التل کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ کسی چیز کو فروخت کرتے وقت شرط لگا لینا درست ہے۔ مثلاً دکان، مکان فروخت کرتے، ایک ماہ یا دو ماہ اس میں رہائش کی یا سودا رکھنے کی شرط لگا لینا جائز ہے جیسا کہ سیدنا جابر بیانیہ نے شرط لگائی تھی، جمہور اس کے جواز کے قائل ہیں۔ امام مالک ہراللہ نے کہا ہے کہ سواری کی شرط صرف اس صورت میں لگائی جاسکتی ہے کہ جب سفر تین دن سے کم ہو جبکہ امام شافعی اور امام ابو حنیفہ عبدالنا مطلق طور پر اس شرط کو نا جائز قرار دیتے ہیں۔ دلائل سے زیادہ قومی موقف جمہور کا لگتا ہے۔:٥٧٤٥","",{"k":"صحیح بخاری (٢٩٦٧)، صحيح مسلم (٧١٥)۔"}],[5745,"سيدنا سہل بن حنیف رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے جس کے لیے میر منزل نہ ہوگا وہ جنت میں بہت آہستہ آہستہ ہی داخل ہو گا۔“ ایک آدمی نے عرض کیا: اللہ کے رسول! ہم میں سے ہر ایک کے لیے میر منزل نہیں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم میں سے کسی کے لیے یہ میر منزل نہیں کہ وہ اپنے مسلمان بھائی کو مفقود پاتا ہے؟“ ٥٧٤٦","",{"k":"مجمع الزوائد (٣/١٣)، مجمع البحرين (١٢٥١)، اسناده ضعيف۔"}],[5746,"سیدنا سہل بن حنیف رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”شادی کرو، کیونکہ میں تمہاری کثرت کی وجہ سے دیگر امتوں پر فخر کروں گا اور نامکمل پیدا ہونے والا بچہ غصے سے بھرا ہوا جنت کے دروازے پر دیکھا جائے گا تو اسے کہا جائے گا: داخل ہو جا، وہ کہے گا: ( میں داخل نہیں ہوں گا) حتی کہ میرے والدین داخل ہوں۔“ یہ دونوں حدیثیں سہل بن حنیف سے صرف اسی اسناد سے مروی ہیں۔ ان دونوں میں عبد العظیم بن حبیب کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم دوسری صحیح حدیث سے ثابت ہے کہ نبی مکرم ملے ہم نے اپنے ایک صحابی کو فرمایا کہ ایسی عورت سے شادی کرو جو بہت محبت کرنے والی اور بہت بچے جننے والی ہو۔ بلاشبہ میں تمہاری کثرت سے دیگر امتوں پر فخر کرنے والا ہوں۔(ابو داؤد، رقم: ٢٠٥٠)",""],[5747,"سیدہ عائشہ رضی عنہا نے بیان کیا، میں نے دھوپ میں پانی گرم کیا تو میں اسے نبی صلی اللہ علیہ وسلم کے پاس لائی تا کہ آپ لے کہ تم اس سے وضوء فرمائیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! ایسے نہ کرو، کیونکہ اس سے برص کا مرض پیدا ہوتا ہے۔ اس حدیث کو ہشام بن عروہ سے صرف محمد بن مروان نے روایت کیا اور نبی صلی اللہ علیہ وسلم سے صرف اس اسناد سے روایت کی جاتی ہے۔","",{"k":"مجمع الزوائد (١/٢١٧)، مجمع البحرین (٣٧٧)، اس میں محمد بن مروان السدی متروک متہم بالوضع ہے۔۔"}],[5748,"سيدنا سعيد بن المسیب نے بیان کیا، میں نے ایک دن عبد اللہ بن عمر رضی اللہ عنہما کو مسلمانوں کی ایک جماعت میں سنا، ان میں سیدنا عبداللہ ابن عمر رضی اللہ عنہما بھی تھے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو اپنا عمل لوگوں کو سناتا ہے، اللہ قیامت کے دن اس کے متعلق اپنی مخلوق کو سنا دے گا اور اسے ذلیل و حقیر بنا دے گا۔ پس میں نے سیدنا عبداللہ ابن عمر رضی اللہ عنہما کو آنسو بہاتے ہوئے دیکھا۔ اس حدیث کو سعید بن مسیب سے صرف عبد الکریم بن مالک نے روایت کیا۔ اس میں سلیمان بن ابی داود کا تفرد ہے۔","",{"k":"صحیح ترغیب و ترهيب (٢٥)، مجمع الزوائد (١٠/٢٢٢)، مسند احمد (٢/١٦٢)، مجمع البحرين (٤٩٤٣)، معجم کبیر طبرانی (٣٠١/١١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ ریا کاری، قیامت والے دن ذلت و رسوائی کا باعث ہو گی، بلکہ قیامت والے دن سب سے پہلے جن لوگوں کا محاسبہ ہو گا وہ ریا کار ہی ہوں گے، جیسا کہ مسلم میں ہے کہ قیامت والے دن جن کا سب سے پہلے فیصلہ کیا جائے گا۔ ان میں سے شہید، عالم اور سخی۔ (مسلم: ١٩٠٥) . ٥٧٤٩"}],[5749,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، ابو القاسم علینا نے فرمایا: ”ان کا نام الخضر اس لیے رکھا گیا، کہ وہ سوکھی زمین پر کھڑے ہوئے تو وہ سرسبز لہلہانے لگی۔“ اس حدیث کو عکرمہ سے صرف ہلال بن مرداس نے روایت کیا، اس میں الحکم بن ظہیر کا تفرد ہے۔","",{"k":"صحیح بخاری، مع موسى عليهما السلام (٣٤٠٢)، سنن ترمذی (٣١٥١)۔","f":"سیدنا خضر عالیندا کا نام بلیا بن ملکان بن فالح بن عابر بن شالخ بن ارفشخذ بن سام بن نوح علیہ سلام ہے۔ (فتح الباری: ٥٣٥/٦، شرح حدیث: ٣٤٠٢) جو مذکورہ حدیث میں ہے کہ ان کے بیٹھنے سے زمین کا سرسبز ہونا ان کی کرامت تھی اولیاء اللہ کی کرامت برحق ہے بشرطیکہ صحیح طور پر ثابت ہو۔ (شرح صحیح بخاری، مترجم مولنا داود راز اللہ، شرح حدیث ٣٤٠٢) ٥٧٥٠"}],[5750,"سیدنا ابو ثابت یعلی بن مرہ صلی اہلیہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے بالشت برابر زمین چوری کی یا اس کی خیانت کی، وہ قیامت کے دن اسے ساتوں زمینوں تک اٹھائے ہوئے آئے گا۔ اس حدیث کو اسماعیل بن ابی خالد کے حوالے سے قرہ سے صرف زید بن ابی انیسہ نے روایت کیا۔","",{"k":"مجمع البحرين (٢٠٩٩)۔"}],[5751,"سیدنا عمران بن حصین رضی اللہ عنہ نے بیان کیا، رسول اللہ ملے عام جب کسی لشکر کو بھیجنے کا ارادہ فرماتے تو اسے صبح صبح روانہ کرتے تھے اور آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! میری امت کے لیے اس کے اول وقت میں برکت فرما۔ اس حدیث کو قتادہ سے صرف المسعودی نے روایت کیا، اس میں المعلی بن ترکہ کا تفرد ہے، یہ سیدنا عمران بن حصین فضل اللہ سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٦٥/٤)، سنن ابو داود كتاب الجهاد (٢٦٠٦)، مجمع البحرين (١٩٤٨)، اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سفر کے لیے صبح صبح نکلنا مستحب ہے اسی طرح تجارت کے لیے یا کوئی اور کام کے لیے صبح صبح نکلنا زیادہ مفید اور بابرکت ہوتا ہے، کیونکہ اس وقت انسان تازہ دم ہوتا ہے اور اس کی قوت عمل وافر ہوتی ہے۔ سیدنا صر رضی اللہ عنہ تھے، یہ اپنی تجارت کا سامان دن کے ابتدائی حصے میں بھیجا کرتے تھے پس (اس کی برکت سے ) تو نگر ہو گئے اور ان کا مال بہت ہو گیا۔ (ابو داؤد، رقم: ٢٦٠٦) ٨٠٨٠/ - لله قَالَ: ٥٧٥٥٢"}],[5752,"سیدنا عبد الله رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی علی ایم نے فرمایا: ” میں نے ارادہ کیا کہ میں سیدنا بلال رضی اللہ عنہ کو حکم دوں، وہ نماز کے لیے اقامت کہے، پھر میں ان لوگوں کی طرف چلا جاؤں جو اذان سنتے ہیں لیکن وہ نماز کے لیے نہیں آتے تو میں انہیں ان کے گھروں سمیت جلا دوں۔“ اس حدیث کو ابوحمزہ سے صرف القاسم بن بیٹی نے روایت کیا۔ اس میں مقدم بن محمد کا تفرد ہے۔","",{"k":"الْقَاسِم بن : صحيح مسلم، رقم: مجمع الزوائد (٢/٤٣)۔"}],[5753,"سیدنا عبد اللہ بن مسعود ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس شخص کا بچہ فوت ہو جائے، وہ بیٹا ہو یا بیٹی، اطاعت کی ہو یا اطاعت نہ کی ہو، وہ راضی ہوا ہو یا راضی نہ ہوا ہو،صبر کیا یا صبر نہ کیا، اس کے لیے ثواب صرف جنت ہی ہے۔ سیدنا عبداللہ ابن مسعود رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عمر والا ودی کا تفرد ہے۔ ٥٧٥٤","",{"k":"مجمع الزوائد (٣/١٠)، مجمع البحرين (١٢٤٨)، اسناده ضعيف۔"}],[5754,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تین چیزیں مہلک ہیں اور تین چیزیں نجات دینے والی ہیں، تین چیزیں کفارہ ہیں اور تین درجات ہیں، رہیں مہلک چیزیں: ایسا بخل جس کی اطاعت کی جائے، خواہش جس کی اتباع کی جائے اور خود پسندی، رہی نجات دینے والی: تو غصے اور خوشی میں عدل، فقر و تو نگری میں اعتدال، پوشیدہ اور علانیہ طور پر اللہ کا ڈر، رہے کفارات: تو نماز کے بعد دوسری نماز کا انتظار، سخت سردی میں خوب اچھی طرح وضو کرنا، باجماعت نماز ادا کرنے کے لیے چل کر جانا، رہے درجات: تو کھانا کھلانا، سلام عام کرنا اور رات کے وقت نماز پڑھنا جبکہ لوگ سورہے ہوتے ہیں۔“ اس حدیث کو سعید بن جبیر سے صرف عطاء بن دینار نے اور عطاء سے صرف ابن لہیعہ نے روایت کیا۔ اس میں الولید بن عبد الواحد کا تفرد ہے۔ سیدنا عبد اللہ ابن عمر ضیا المیہ سے صرف اسی اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (١/٩٤)، مجمع البحرين (١٤٢)۔"}],[5755,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم سورۃ البقرۃ، سورۃ آل عمران اور سورۃ النساء نہ کہا کرو اور اسی طرح سارا قرآن ( کسی سورت کا اس طرح نام نہ لو )، بلکہ کہا کرو: وہ سورت جس میں البقرۃ (گائے ) کا ذکر ہے، وہ سورت جس میں آل عمران کا ذکر ہے اور اسی طرح سے سارا قرآن۔“ اس حدیث کو موسی بن انس سے صرف عیسی بن میمون نے روایت کیا۔ اس میں خلف بن ہشام کا تفرد ہے اور سیدنا انس رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ ٥٧٥٦","",{"k":"مجمع الزوائد: ٧/ . ١٦٠، مجمع البحرين (٣٤٥٠)، اسناده ضعيف۔"}],[5756,"سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی بن ابی طالب رضی اللہ عنہ اور سیدنا خالد بن ولید نبی اللہ کو کسی مہم پر بھیجا اور فرمایا: \"اگر قتال ہوا تو علی تمہارے امیر ہوں گے۔“ انہیں فتح نصیب ہوئی، ان کے ہاتھ قیدی لگے، سیدنا علی بنی اہلیہ نے خوبصورت لونڈی لی تاکہ وہ اسے رسول الله علیم کی طرف بھیجیں، تو سیدنا خالد رضی اللہ عنہ نے انکار کر دیا اور کہا: میں اسے رسول اللہ علیم کی خدمت میں بھیجوں گا، جب انہوں نے انہیں منع کیا، تو سیدنا خالد رضی اللہ عنہ دیے، پس انہوں نے سیدنا بریدہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا۔ سیدنا بریدہ رضی لینہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جبکہ آپ ملنے کی تم اپنا سر دھو رہے تھے، میں نے آپ صلی اللہ علیہ وسلم کے پاس سیدنا علی ضیا الیہ کے بارے میں باتیں کیں اور جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے تو ہم آپ صلی اللہ علیہ وسلم کی طرف اپنی نگاہیں نہیں اٹھاتے تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بریدہ! ٹھہرو میں نے اپنا سر رسول اللہ صلی اللہ علیہ وسلم کی طرف اٹھایا تو آپ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدلا ہوا تھا، جب میں نے یہ کیفیت دیکھی تو میں نے کہا: میں اللہ تعالیٰ کے غصے اور اللہ کے رسول علیم کے غصے سے اللہ کی پناہ چاہتا ہوں۔ سیدنا بریدہ بیانیہ نے بیان کیا، اللہ کی قسم! میں نے رسول اللہ صلی اللہ علیہ وسلم کی جو حالت دیکھی تو اس کے بعد میں ان (علی رضی اللہ عنہ سے کبھی بغض نہیں رکھوں گا۔“۔ اس حدیث کو عطیہ سے صرف اس کے بیٹے عمرو نے روایت کیا۔","",{"k":"صحیح بخاری (٥٢٥٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سیدنا علی رضی اللہ عنہ سے بغض رکھنا اہل ایمان کی شان نہیں ہے۔ ((اللهم انى احب عليا كما امر رسول الله صلی اللہ علیہ وسلم سیدنا علی ضیا اللہ اور سیدنا خالد رضی اللہ عنہ کو نبی معظم صلی اللہ علیہ وسلم نے یمن کی طرف بھیجا تھا، اللہ ذوالجلال نے ان کو کامیابی عطا کی۔ علامہ وحید الزماں شرح بخاری میں لکھتے ہیں: کہ سیدنا بریدہ نیا ہی کو یہ گمان ہوا کہ سیدنا علی بنی امیہ نے مال غنیمت میں خیانت کی ہے حالانکہ انہوں نے خمس میں سے ایک لونڈی لے لی جو سب قیدیوں میں عمدہ تھی یہ خیانت نہ تھی کیونکہ شمس اللہ تعالیٰ اور رسول ملے ایم کا حصہ تھا اور سیدنا علی نبی ال یہی اس کے بڑے حق دار تھے اور شاید نبی مکرم ملے تم نے ان کو تقسیم کے لیے اختیار بھی دیا ہو گا۔ اب استبراء سے قبل لونڈی سے جماع کرنا تو وہ اس وجہ سے ہو گا کہ وہ لونڈی باکرہ ہوگی اور باکرہ کے لیے بعض کے نزدیک استبراء لازم نہیں۔"}],[5757,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، کہ وہ اللہ کے نبی اللے تعلیم کے پاس موجود تھے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جس شخص کو دس یا اس سے زائد افراد کا امیر بنایا جائے وہ قیامت کے دن اس حال میں آئے گا کہ اس کا ہاتھ اس کی گردن سے بندھا ہو گا، اگر وہ محسن ہوا تو اس کا ہاتھ کھول دیا جائے گا اور اگر وہ برا سلوک کرنے والا ہوا تو اس کے ہاتھ کو مزید باندھ دیا جائے گا۔“ اس حدیث کو عطیہ سے صرف اس کے بیٹے عمر و اور عیسی بن المسیب نے روایت کیا۔","",{"k":"مجمع الزوائد (٢٠٦/٥)، مجمع البحرين (٢٦٠٣)، اسناده ضعيف . ٥٧٥٧۔"}],[5758,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، انصار نے آپس میں کہا: اگر ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے مال جمع کریں تو آپ نے اپنا ہاتھ کشادہ کیا، آپ کے اور ہمارے درمیان کوئی حائل نہ ہوگا؟ انہوں نے عرض کیا: اللہ کے رسول! ہم نے ارادہ کیا کہ ہم آپ صلی اللہ علیہ وسلم کے لیے اپنے اموال میں سے جمع کریں تو اللہ عزوجل نے یہ آیت: \" کہہ دیجئے: میں اس پر قریبی رشتہ داروں کی مودت کے سوا تم سے کسی اجر کا سوال نہیں کرتا۔“ نازل فرمائی، پس وہ اختلاف کرتے ہوئے (آپ کے پاس سے) باہر آئے، انہوں نے کہا: کیا تم نے نہیں دیکھا کہ رسول اللہ من سلیم نے کیا فرمایا ہے؟ ان میں سے کسی نے کہا: آپ نے یہ اس لیے فرمایا ہے کہ ہم آپ کے اہل بیت کا دفاع کریں اور ان کی مدد کریں تو اللہ عزوجل نے یہ آیت: ” کیا وہ کہتے ہیں اس نے اللہ پر جھوٹ باندھا ہے۔“ یہاں تک: وہی ہے جو اپنے بندوں کی طرف سے تو بہ قبول کرتا ہے۔ نازل فرمائی، پس اس حکم سے انہیں تو بہ کے لیے اشارہ فرمایا اور یہاں تک آیت نازل فرمائی: ”وہ ان لوگوں سے قبول کرتا ہے جو ایمان لائے اور نیک عمل کیے اور وہ اپنے فضل سے انہیں مزید عطا فرمائے گا۔“ وہ لوگ جنہوں نے یہ کہا: یہ کہ وہ اللہ کے حضور تو بہ کرتے ہیں اور اس سے مغفرت طلب کرتے ہیں۔“ اس حدیث کو عثمان بن ابی الیقظان سے صرف نصیر بن زیاد نے روایت کیا۔ اس میں حسین بن الاشقر کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠٦/٧)، مجمع البحرين (٣٣٩٠)، اسناده ضعيف۔"}],[5759,"سیدنا ابو موسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے مجھ پر عمداً جھوٹ بولا وہ اپنا ٹھکانا جہنم میں بنا لے۔“ اس حدیث کو سعید بن ابی بردہ سے صرف خالد بن نافع نے روایت کیا۔","",{"k":"مجمع الزوائد (١٤٦/١)، مجمع البحرين (٢٩٤)۔"}],[5760,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے گدھوں کے گوشت سے منع فرمایا اور گھوڑوں کے گوشت کھانے کا حکم فرمایا۔ اس حدیث کو جابر بن زید سے صرف سماک نے اور سماک سے صرف عمر بن عبید نے روایت کیا۔ اس میں محمد بن عبید کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥/٤٧)، مجمع البحرين (٤٠٨٧)، اسناده حسن۔"}],[5761,"الشعمی سے روایت ہے سیدنا عبد اللہ بن عباس نبی اللہ بیان کرتے تھے کہ محم م علیکم نے اپنے رب کو دو مرتبہ دیکھا ہے! ایک دفعہ اپنی آنکھ سے اور ایک مرتبہ اپنے دل سے۔ اس حدیث کو مجالد۔ صرف اس کے بیٹے اسماعیل نے روایت کیا ہے۔ ٥٧٦٢","",{"k":"مجمع الزوائد (١/٧٩)، مجمع البحرین (٦٣)، اسناده ضعيف۔"}],[5762,"سیدنا عبد اللہ بن ابی اوفی ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے اپنے رب سے درخواست کی کہ جو بھی میری اہلیہ بنے وہ میرے ساتھ جنت میں ہو، پس اس نے میری یہ درخواست قبول فرمائی۔ اس حدیث کو اسماعیل بن ابی خالد سے صرف عمار بن سیف نے اور عمار سے صرف قبیصہ نے روایت کیا۔ اس میں اس کے بیٹے کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٠١٠)، مجمع البحرين رقم ٣٩٦٢ سنده ضعيف۔"}],[5763,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اس پر خوش ہو کہ تم ایک چوتھائی جنتی ہو؟ تو انہوں نے اللہ اکبر کہا، پھر آپ نے فرمایا: ” کیا تم اس پر خوش ہو کہ جنتیوں کا ایک تہائی تم ہو؟“ پس انہوں نے اللہ اکبر کہا، پھر آپ نے فرمایا: ” کیا تم اس پر خوش ہو کہ نصف جنتی تم ہو؟“ پس انہوں نے اللہ اکبر کہا تو رسول اللہ ملتے ہی ایم نے فرمایا: قیامت کے دن لوگوں کی ایک سو میں صفیں ہوں گی، ان میں سے میری امت کی اتنی صفیں ہوں گی۔ اس حدیث کو عبد اللہ بن عیسی سے صرف محمد بن شرحبیل نے روایت کیا۔ اس میں بیجی الحمانی کا تفرد ہے۔ مائدین کے مذکورہ حدیث سے معلوم ہوا کہ جنت میں جانے والوں میں سب سے زیادہ تعداد امت محمدیہ علی صاحبھا الصلوۃ والسلام کی ہوگی۔","",{"k":"لم سنن ترمذى (٢٥٤٦)، قال الشيخ الالباني: صحيح۔"}],[5764,"سیدنا ابو ہریرہ ضیا علینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سورۃ البقرہ سیکھو، کیونکہ اس کا سیکھنا باعث برکت اور اسے ترک کرنا باعث حسرت ہے، جادوگر اسے نہیں سیکھ سکتے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن قرآن بدلے ہوئے آدمی کی طرح آئے گا، وہ اپنے پڑھنے والے سے کہے گا: کیا تم مجھے پہچانتے ہو؟ میں وہ ہوں جو تجھے رات کو ( تہجد کے وقت ) بیدار رکھتا تھا اور سخت دھوپ میں تجھے پیاسا رکھتا تھا، ہر تاجر اپنی تجارت کے پیچھے ہے، جبکہ میں آج تمہاری خاطر ہر تاجر کے پیچھے ہوں، پس بادشاہت اس کے دائیں ہاتھ میں دی جائے گی اور دوام اس کے بائیں ہاتھ میں دیا جائے گا اور وقار کا تاج اس کے سر پر رکھا جائے گا، اس کے والدین کو جوڑے پہنائے جائیں گے جو دنیا اور اس کی تمام چیزوں سے زیادہ قیمتی ہوں گے، وہ عرض کریں گے: رب جی! یہ ہمارے لیے کہاں سے آئے ہیں؟ تو انہیں بتایا جائے گا: تمہارے بیٹے کے قرآن پڑھنے کی وجہ سے اور صاحب قرآن سے قیامت کے دن کہا جائے گا: پڑھ اور درجات چڑھتا جا اور اسی طرح ترتیل کے ساتھ پڑھ جس طرح تو دنیا میں ترتیل کے ساتھ پڑھا کرتا تھا اور پڑھتے پڑھتے جب تم آخری آیت پڑھو گے تو وہی تمہاری منزل ہوگی۔ اس حدیث کو عبد اللہ بن عیسی سے صرف شریک نے اور شریک سے صرف یزید بن ہارون اور یحیی الحمانی نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا سورۂ بقرہ کی تلاوت کرنے اور سیکھنے کی وجہ سے گھر میں خیر و برکت ہوتی ہے اور سورہ بقرہ کی تلاوت ترک کرنے سے گھر خیر و برکت سے محروم ہو جاتا ہے اور سورہ بقرہ پر کوئی جادوگر غالب نہیں آ سکتا۔ (٢) مذکورہ بالا روایت سے صاحب قرآن اور اس کے والدین کی بھی فضیلت ثابت ہوتی ہے۔ مذکورہ بالا حدیث میں صاحب قرآن کی یہ صفت بیان کی گئی ہے کہ وہ رات کے قیام کو نیند پر ترجیح دیتا ہے، دوسرا دن کو روزہ رکھتا ہے۔ یہ بھی معلوم ہوا کہ قرآن مجید ٹھہر ٹھہر کر پڑھنا چاہیے۔ علامہ عبدا لرحمان مبارکپوری تحفتہ الاحوذی میں کہتے ہیں: کہ امام خطابی نے کہا: بعض آثار سے ثابت ہوتا ہے کہ جنت کے درجات کی تعداد قرآن مجید کی آیتوں کے برابر ہے۔ قاری سے کہا جائے گا: کہ جتنا قرآن آپ پڑھتے تھے اتنے درجات چڑھ جاؤ، جو قرآن کا مکمل قاری ہو گا وہ جنت کے منتہی درجے تک پہنچ جائے گا۔ ٥٧٦٥","",{"k":"مجمع الزوائد (١٦٣/٧)، سلسلة صحيحة (٨٢٩)، مجمع البحرين (٣٤٦٩)۔"}],[5765,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جنت کے سو درجے ہیں، ہر دو درجوں کے درمیان پانچ سو سال کی مسافت ہے۔“ اس حدیث کو محمد بن جمادہ سے صرف شریک نے روایت کیا۔","",{"k":"مجمع الزوائد (١٠/٢٢)، مجمع البحرين (٤٨٧١)، اسناده ضعيف۔"}],[5766,"سیدنا بریدہ بیانیہ نے بیان کیا، رسول اللہ نے یمن کے لیے لحد تیار کی گئی اور اس پر کچی اینٹیں لگائی گئیں اور آپ کو قبلے کی جانب سے اتارا گیا۔ اس حدیث کو علقمہ بن مرثد سے صرف ابو بردہ نے روایت کیا۔ فاندن کو مذکورہ روایت ضعیف ہے تاہم روایت کا پہلا حصہ دوسری حدیث سے ثابت ہے، جیسا کہ سیدنا سعد بن ابی وقاص رضی اللہ عنہ نے کہا: میرے لیے بغلی قبر بنانا اور مجھ پر کچی اینٹیں چننا، جیسا کہ رسول اللہ عمل علم کے ساتھ کیا گیا۔ (مسلم، کتاب الجنائز، رقم: ٩٦٦، مسند احمد: ١٦٩/١) قبر کے قبلہ رخ گڑھے کو لحد کہتے ہیں جہاں سے میت کو قبر میں اتارا جاتا ہے۔ روایت کا دوسرا حصہ ضعیف ہے۔ دیکھئے: (ضعیف ابن ماجه، رقم: ٣٤٠) تاہم اہل سنت کا طریقہ یہ ہے کہ میت کو قبر کے پچھلے ( یعنی نچلے حصے سے داخل کیا جائے۔سیدنا عبد اللہ بن یزید رضی اللہ عنہ نے ایک میت کو قبر کے پاؤں کی جانب سے داخل کیا اور فرمایا: یہ سنت طریقہ (صحيح ابو داؤد، رقم: ٢٧٥٠) سیدنا عبد اللہ ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی مکرم اے علی تم کو آپ صلی اللہ علیہ وسلم کے سر کی جانب (یعنی قبر کے پاؤں کی جانب سے داخل کیا گیا۔ (مسند شافعی: ١/ ٢١٥) ٥٧٦٧","",{"k":"مجمع الزوائد (٤٢/٣)، مجمع البحرين (١٣٠٧)، اسناده ضعیف۔"}],[5767,"سیدنا عبد اللہ فی اللیلین نے بیان کیا، میں نے بے شمار مرتبہ رسول اللہ مانے تعلیم کو مغرب کے بعد دو رکعتوں میں اور فجر سے پہلے دو رکعتوں میں سورۃ الکافرون اور سورۃ الاخلاص پڑھتے ہوئے سنا۔“ اس حدیث کو عاصم سے صرف عبد الملک بن الولید بن معدان اور الحسین بن واقد نے روایت کیا۔","",{"k":"سنن ترمذی (٤٢١)، قال الشيخ الالبانی: حسن صحيح۔","f":"مذکورہ بالا حدیث سے معلوم ہوا کہ مغرب اور فجر کی سنتوں میں مذکورہ بالا سورتیں پڑھنا منسون ہے اور ہر مسلمان کو سنت نبوی پر عمل کرنے کی فضیلت حاصل کرنا چاہیے، کیونکہ ان دونوں سورتوں میں توحید علمی اور توحید عملی کو اللہ تعالیٰ کے لیے خالص کیا گیا ہے۔ معلوم ہوا کہ فجر کی سنتوں میں نبی معظم ملے یکم پڑھتے تو آپ دن کا آغاز اللہ کی توحید سے کرتے تھے اور مغرب کی سنتوں میں پڑھتے، اس کا مطلب یہ ہے کہ آپ دن کے عمل کا اختتام بھی اللہ کی توحید پر کرتے تھے۔"}],[5768,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے رخساروں کی سفیدی دیکھ رہا ہوں، آپ دائیں طرف سلام پھیرتے تو فرماتے: السلام علیکم ورحمة الله وبركاته اور بائیں طرف سلام پھیرتے تو فرماتے: السلام علیکم ورحمۃ اللہ“ اس حدیث کو عاصم کے حوالے سے زر سے صرف عبد الملک بن الولید بن معدان نے روایت کیا۔ ٥٧٦٩","",{"k":"ابو داود كتاب الصلاة (٩٩٦)، سنن ترمذی (٢٩٥)، قال الشيخ الالباني: صحيح (٩١٤)۔"}],[5769,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، کہ آپ ملنے دی کنم اپنے قول کے شروع میں اور آخر پر یہ دعائیں پڑھا کرتے تھے: ”اے اللہ! ہمارے معاملات درست فرما، سلامتی کی راہوں کی طرف ہماری راہنمائی فرما، ہمیں تاریکیوں سے نکال کر روشنی کی طرف لا، ظاہری و باطنی بے حیائی ہم سے دور فرما، ہماری سماعت و بصارت، ہماری ازواج و اولاد اور ہماری معاش میں برکت فرما، (اپنی رحمت کے ساتھ ) ہم پر رجوع فرما، بے شک تو توبہ قبول فرمانے والا بہت رحم کرنے والا ہے، اے اللہ! اپنی نعمتوں پر ہمیں شکر کرنے والا اور تعریف کرنے والا بنا۔ اس حدیث کو داود الاودی سے صرف الولید بن القاسم نے روایت کیا۔ مذکورہ روایت ضعیف ہے، اس میں داؤد بن یزید الاودی، ضعیف ہے۔ تاہم سنن ابی داود میں صحیح سند کے ساتھ مذکورہ بالا کلمات سے ملتے جلتے الفاظ ہیں۔ سیدنا عبد اللہ بن مسعود بھی اللہ فرماتے ہیں کہ رسول اللہ نے ہمیں کئی طرح کے کلمات سکھاتے تھے، مگر جس اہتمام سے کلمات تشہد تعلیم فرماتے تھے، دیگر میں ایسے نہ ہوتا تھا۔","",{"k":"کر مجمع الزوائد (١٨٢/١٠)، مجمع البحرين (٤٦٨٦)، اس میں داود بن یزید الا ودی ضعیف ہے۔۔","f":"٥٧٧٠"}],[5770,"سیدنا عبد اللہ فی اللہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے اللہ تعالیٰ کے فرمان: ”وہ انہیں پورا پورا اجر دے گا اور اپنے فضل سے انہیں مزید دے گا۔“ کی تفسیر میں فرمایا: ”دنیا میں جن کے ساتھ کوئی احسان کیا گیا ہوگا وہ ایسے لوگوں کے لیے شفاعت کریں گے جن پر جہنم واجب ہو چکی ہوگی اور انہوں نے ان کے ساتھ کوئی احسان کیا ہوگا۔“ اس حدیث کو اعمش سے صرف اسماعیل الکندی نے روایت کیا، اس میں بقیہ کا تفرد ہے۔ ٥٧٧١","",{"k":"مجمع الزوائد (١٦/٧)، مجمع البحرين (٣٣١١)، اسناده ضعيف۔"}],[5771,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عرب کے ایک آدمی سے فرمایا: ”جب تم پر کوئی رغبت یا خوف نازل ہوتا ہے تو تم کس کی پناہ لیتے ہو؟“ انہوں نے عرض کیا: اللہ کی پناہ لیتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: پس جب وہ تمہاری دعائیں قبول فرما لیتا ہے تو پھر تم کس کی طرف لوٹتے ہو؟“ انہوں نے عرض کیا: اس کی طرف جسے آپ سے یکم جانتے ہیں، آپ سے تم نے فرمایا: تم جو جانتے ہو عمل نہیں کرتے اور جو عمل کرتے ہو وہ جانتے نہیں، تین بار فرمایا۔“","",{"k":"مجمع الزوائد (١٠/١٥٢)، مجمع البحرين (٤٦٢٩)، اسناده ضعيف۔"}],[5772,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”خواتین اور خوشبو مجھے عزیز بنا دی گئی ہیں اور میری آنکھوں کی ٹھنڈک نماز میں رکھ دی گئی ہے۔“ اس حدیث کو اوزاعی سے صرف الہقل نے روایت کیا، اس میں یحیی بن عثمان کا تفرد ہے۔","",{"k":"٥٧٧٢ الالباني: حسن صحيح سنن نسائی (٣٩٣٩)، قال الشيخ۔"}],[5773,"سیدہ عائشہ علی النیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن کو کوئی کانٹا چھتا ہے یا اس سے کوئی کم یا زیادہ تکلیف پہنچتی ہے تو اس کے بدلے میں اللہ اس کا گناہ معاف کر دیتا ہے اور اس کا ایک درجہ بلند کر دیتا ہے۔ اس حدیث کو حبیب بن حسان سے صرف ابواحمد الزبیری نے روایت کیا۔","",{"k":"صحيح مسلم (٢٥٧٢)، سنن ترمذی (٩٦٥)۔","f":"مذکورہ حدیث میں مومنوں کو بہت بڑی خوشخبری سنائی گئی ہے کہ مومن بندے کو بیماریوں اور دوسری تکلیفوں اور پریشانیوں کو ( جو اس دنیوی زندگی کا گویا لازمہ ہیں ) اپنے لیے اللہ ذوالجلال کا غضب اور قہر کا سبب نہ سمجھیں، اللہ تعالیٰ سے صحیح تعلق رکھنے والے بندوں کے لیے ان میں بڑی خیر ہے اور رحمت کا بڑا سامان ہے ان کے ذریعے گناہوں کی صفائی اور تطہیر ہوتی ہے۔ صحابہ کرام بی ایم جو نیکیوں کے حریص تھے، بیماریوں پر صبر کرنے والے اور بیماری پر اللہ ذوالجلال سے نیکی کی امید رکھتے تھے۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا کہ بخار سے زیادہ مجھے کوئی مرض پسند نہیں کیونکہ وہ میرے ہر عضو میں داخل ہو جاتا ہے اور اللہ تعالیٰ ہر عضو کو اجر میں سے اس کا حصہ عطا فرماتا ہے۔ (ادب المفرد: ٥٠٣۔ شیخ الالبانی اللہ نے اس کو صحیح کہا ہے۔)"}],[5774,"سیدہ عائشہ منی تنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”معزز لوگوں کی لغزشوں سے درگزر کرو۔“ ٥٧٧٥","",{"k":"مجمع الزوائد (٦/٢٨٥)، مجمع البحرين (٢٤٧٢)، اسناده ضعيف۔"}],[5775,"اسی استاد سے مروی ہے، آپ نے فرمایا: ”باہم تحائف کا تبادلہ کرو تم محبت میں بڑھ جاؤ گے۔“ ان دونوں حدیثوں کو عبید اللہ بن العیز ار سے صرف المثنی ابو حاتم نے اور ان دونوں کو المثنی سے صرف محمد بن سلیمان بن داود اور ریحان بن سعید نے روایت کیا۔","",{"k":"مجمع الزوائد (١٤٩/٤)، ضعيف الجامع الصغير (٢٤٩١)، مجمع البحرين (٢٠٥٤)، اسناده ضعيف۔"}],[5776,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ سیدنا عبد الرحمان بن عوف رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے جبکہ انہوں نے زعفران کی خوشبو لگائی ہوئی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: یہ رنگ کیسا ہے، کیا تم نے شادی کر لی ہے؟ انہوں نے عرض کیا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم نے ولیمہ کیا ہے؟“ انہوں نے عرض کیا: نہیں، رسول اللہ صلی اللہ علیہ وسلم نے (گٹھلی کے برابر ) سونے کا ٹکڑا ان کی طرف پھینکا اور فرمایا: ”ولیمہ کرو خواہ ایک بکری کا ہو۔“ اس حدیث کو الز ہری سے صرف عبد الرحمن الملمیکی نے اور عبد الرحمن سے صرف فردوسی نے روایت کیا، اس میں ابوکریب کا تفرد ہے۔ فائد مذکورہ حدیث سے معلوم ہوا کہ ولیمہ کرنا واجب ہے کیونکہ نبی معظم صلی اللہ علیہ وسلم نے حکم دیا ہے۔ نیز وجوب ولیمہ کی تائید اس بات سے ہوتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جتنے بھی نکاح کیسے، سب میں ولیمہ کیا اور عہد رسالت میں ایسا کوئی نکاح معروف نہیں جس میں ولیمہ نہ کیا گیا ہو۔ (حافظ ابن حجر ہراللہ، فتح الباری: ١٣٨/٩) الشیخ عبد الرحمان مبارکپوری جمالله: (تحفة الاحوذى ٢٢٤/٤) اور امام ابن حزم اللہ: (محلی بالاثار: ٩/ ٢٠) نے ولیمہ کو واجب قرار دیا ہے، البتہ سعودی مستقل فتوی کمیٹی نے یہ فتویٰ دیا ہے کہ ولیمہ کرنا مسنون ہے، شرعاً اس کی ترغیب دلائی گئی ہے۔ (فتاوی اللجنة الدائمة: ٩١/١٩) مذکورہ حدیث میں جو بکری کے ساتھ ولیمہ کا ذکر ہے اس کا مطلب یہ نہیں کہ بکری سے کم کسی چیز کا ولیمہ .: درست نہیں، بلکہ حقیقت یہ ہے کہ ولیمہ کرنا واجب تو ہے لیکن اس میں اہتمام دعوت شوہر کی حیثیت پر ہے۔","",{"k":"مجمع الزوائد (٥٤/٤)، صحیح بخاری، مسلم (١٤٢٧)، ابو داود (٢١٠٩)، مجمع البحرین (١٨٩٢)۔"}],[5777,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھتے تو آپ صلی اللہ علیہ وسلم اپنے پاؤں کے نیچے کوئی چیز نہیں رکھتے تھے، البتہ ایک دن بارش ہوئی تو آپ صلی اللہ علیہ وسلم نے اپنے پاؤں کے نیچے چھڑے کی چٹائی رکھی۔ اس حدیث کو مقدام بن شریح سے صرف قیس نے روایت کیا۔ اس میں ابراہیم الصینی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٦٠٢)، مجمع البحرين (٧٠٨)، اسناده ضعيف۔"}],[5778,"سیدنا عبد اللہ فی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ن سے سوال کیا گیا: تو نگری کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں کے پاس جو کچھ ہے اس سے نا امید و بے نیاز ہو جانا۔“ اس حدیث کو عاصم سے صرف ابو بکر بن عیاش نے روایت کیا، اس میں ابراہیم بن سلمہ بن زیاد کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (٢٨٩/١٠)، مجمع البحرين (١٨٥٠)، اسناده ضعيف۔"}],[5779,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ” دوقسم کی آنکھیں جہنم کی آگ نہیں دیکھیں گی: اللہ کے ڈر سے رونے والی آنکھ اور اللہ کی راہ میں پہرہ دینے والی آنکھ۔“ اس حدیث کو شبیب بن بشر سے صرف اسرائیل روایت کرتا ہے، اس میں زافر بن سلیمان کا تفرد ہے۔ مذکورہ حدیث میں اللہ ذوالجلال کی عظمت و جلالت کے تصور سے رونے اور جہاد میں","",{"k":"♦، مجمع الزوائد (٢٩١/٥)، سنن ترمذی (١٦٣٩)، قال الشيخ الالباني: صحيح، مجمع البحرين (٢٦٣٥)۔","f":"الله پہرہ دینے والوں کی فضیلت کا بیان ہے۔ ایک دوسری حدیث میں ہے سیدنا ابو ہریرہ فی لیہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: وہ آدمی جہنم میں داخل نہیں ہو گا جو اللہ کے ڈر سے رو پڑا، یہاں تک کہ دودھ تھنوں میں واپس چلا جائے اور کسی آدمی پر اللہ کی راہ کا گرد و غبار اور جہنم کا دھواں اکٹھا نہیں ہوگا۔ (ترمذی، رقم: ١٦٣٢، اسنادہ صحیح معلوم ہوا کہ جس طرح تھنوں سے نکلا ہوا دودھ تھنوں میں واپس نہیں جاسکتا، اسی طرح اللہ کے ڈر سے رونے والا شخص اور جہاد کے میدان میں گرد و غبار سے آلودہ ہونے والا مجاہد جہنم سے محفوظ رہیں گے۔ ٥٧٨٠"}],[5780,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” لذتوں کو توڑ دینے والی: یعنی موت کو کثرت سے یاد کرو، کیونکہ جو بہتات میں ہو وہ اسے قلیل کر دیتی ہے اور جو قلیل میں ہو وہ اسے ٹکڑے ٹکڑے کر دیتی ہے۔ اس حدیث کو عبید اللہ بن عمر سے صرف ابو عامر الاسدی نے روایت کیا۔ اس میں منجاب کا تفرد ہے اور سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے صرف اسی اسناد سے مروی ہے۔ ٥٧٨١","",{"k":"مجمع الزوائد (١٠/٣١٢)، ضعیف ترغیب و ترهيب (١٩٤٢)، مجمع البحرين (٥٠٧٦)۔"}],[5781,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ آدمی لوگوں کے درمیان سوئے اور یہ کہ وہ شارع عام میں بھی نہ سوئے۔ یہ حدیث سیدنا جابر نبی الیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں ابو بلال کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠٣٨)، مجمع البحرين (٣٠٦٦)، اسناده ضعيف۔"}],[5782,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول الله علیم نے فرمایا: اللہ اس ستر سالہ شخص کو نا پسند فرماتا ہے جو اپنی چال ڈھال میں ہیں سال کی ہیئت ظاہر کرتا ہے۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اسی اسناد سے مروی ہے۔ اس میں موسی بن محمد بن ابراہیم کا تفرد ہے۔: ٥٧٨٣","",{"k":"مجمع الزوائد (١٠/٢٧٤)، مجمع البحرين (٥٠٨٧)، اسناده ضعيف۔"}],[5783,"سیدہ عائشہ بنی الجھا نے بیان کیا، میں رسول اللہ صل علی ایم کے کپڑے سے منی کھرچ دیا کرتی تھی۔ اس حدیث کو ابو سفانہ سے صرف برد بن ابی زیاد نے روایت کیا۔ اس میں عبر بن القاسم کا تفرد ہے۔ ٥٧٨٤","",{"k":"معجم کبیر طبرانی (١٧/١٨٧)، م الزوائد: ١/ ٢٧٩ . مجمع۔"}],[5784,"سیدنا ابو ہریرہ نبی الیہ نے بیان کیا، رسول اللہ سلیم نے فرمایا: ”جو شخص رمضان کے روزے رکھتا ہے اور غسل کر کے عید گاہ جاتا ہے اور اس کو صدقہ کے ساتھ آخری عمل کرتا ہے تو جب وہ واپس آتا ہے تو اس کے گناہ بخش دیے جاتے ہیں۔“ اس حدیث کو قتادہ سے صرف ایوب بن خوط نے روایت کیا۔ اس میں نصر بن حماد کا تفرد ہے۔ ٥٧٨٥","",{"k":"مجمع الزوائد (٢/٢٠١)، کنز العمال (٢٣٧٣٣)، مجمع البحرين (١٠٠٠)، اسناده ضعیف۔"}],[5785,"سیدنا عبد اللہ اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اپنے مرض وفات میں سورۃ اخلاص پڑھتا ہے وہ قبر میں آزمایا نہیں جائے گا، قبر اسے نہیں دبائے گی۔ قیامت کے دن فرشتے اسے ہاتھوں سے پکڑ لیں گے حتی کہ اسے پل صرط سے گزار کر جنت تک پہنچا دیں گے۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اسی اسناد سے مروی ہے، اس میں ابو الحارث الوراق کا تفرد ہے اور یزید بن عبد اللہ، وہ یزید بن عبد اللہ بن الشخیر ہیں۔ ٥٧٨٦","",{"k":"مجمع الزوائد (١٤٨/٧)، سلسلة ضعيفة (٣٠١)، مجمع البحرين، رقم: و، و (٣٤٢٨)، اسناده ضعیف، اس میں ابو حارث نصر بن حماد متروک ہے ۔۔"}],[5786,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں سے کوئی سجدہ کرے تو وہ اپنی ہتھیلیاں زمین پر لگائے، امید ہے کہ اللہ قیامت کے دن اس سے طوق کھول دے گا۔“ اس حدیث کو زہری سے صرف ابن ابی ذئب نے روایت کیا، اس میں عبید النحاس کا تفرد ہے۔ ٥٧٨٧","",{"k":"مجمع الزوائد (٢/١٢٦)، سلسلة ضعيفة (٢٦٢٤)، مجمع البحرين (٨٤٠)، ضعيف الجامع الصغير (٥٤٢)، اسناده ضعيف۔"}],[5787,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن الفت کرتا ہے اور اس سے الفت کی جاتی ہے اور جو الفت کرتا ہے نہ اس سے الفت کی جاتی ہے اس میں کوئی خیر نہیں، لوگوں کو زیادہ","",{"k":"مسند احمد (٢/٤٠٠)، مجمع الزوائد (٩٧/٨)، سلسلة ضعيفة (٤٢٦)، مجمع البحرين (١٠٦)۔","f":"پہنچانے والا ہی بہترین شخص ہے۔“ اس حدیث کو ابن جریج سے صرف عبد الملک بن ابی کریمہ نے روایت کیا۔ اس میں علی بن بہرام کا تفرد ہے۔ فائدة مذکورہ حدیث سے معلوم ہوا کہ اُنس مومن کی صفت ہے، لوگ مومن سے مانوس ہوتے ہیں اور وہ لوگوں سے مانوس ہوتا ہے۔ اس کی مثال آپ اس طرح سمجھئے کہ جو مسجد کا قاری، امام، خطیب، خوش اخلاق، عالم باعمل ہو، بلا امتیاز نمازیوں کی قدر کرتا ہو تو ایسے فرد کو لوگوں کی طرف سے مودت و محبت اور احترام و: اکرام نصیب ہوتا ہے جبکہ اس کے برعکس صورتحال لوگوں کے دلوں میں منافرت پیدا کرتی ہے۔"}],[5788,"سیدنا براء بن عازب رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”موزوں پر مسح کرنے کے بارے میں مسافر کے لیے تین دن اور تین راتیں اور مقیم کے لیے ایک دن اور ایک رات کی رخصت ہے۔ اس حدیث کو ابو اسحاق سے صرف الصحى بن الاشعث نے روایت کیا۔ اس میں موسی بن الحسین کا تفرد ہے۔","",{"k":"٥٧٨٩ مجمع الزوائد (١/٢٦١)، مجمع البحرين (٤٦٨)۔"}],[5789,"سیدنا ابولیلی با لینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں ایک ایسے شخص کو پرچم عطا کروں گا، جو اللہ اور اس کے رسول ملے علیم سے محبت کرتا ہے اور اللہ اور اس کا رسول اس سے محبت کرتے ہیں۔ پس آپ صلی اللہ علیہ وسلم نے وہ پر چم سیدنا علی رضی اللہ عنہ کو عطا فرمایا۔ اس حدیث کو عبد الملک بن ابی سلیمان سے صرف علی بن ہاشم نے روایت کیا۔ اس میں ضرار بن صرد کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (١٢٦/٩)، مجمع البحرين (٣٧٠٨)، اسناده ضعیف، اس میں ضرار بن صرد ضعیف ہے۔۔"}],[5790,"سیدنا ابولیلی یا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کوئی بندہ مومن نہیں ہو سکتا حتی کہ میں اسے اس کی جان سے زیادہ محبوب ہو جاؤں، میرا اہل اسے اپنے اہل سے زیادہ محبوب ہو جائے، میری عترت اسے اس کی اپنی عترت سے زیادہ محبوب ہو جائے اور میری ذات اسے اپنی ذات سے زیادہ محبوب ہو جائے۔ اس حدیث کو الحکم سے صرف ابن ابی لیلی نے اور ابن ابی لیلی سے صرف سعید بن عمرو السکونی نے روایت کیا۔ ٥٧٩١","",{"k":"مجمع الزوائد (١/٩١)، مجمع البحرين (٩٣)، اسناده ضعیف۔"}],[5791,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی نے عام ان کی مسجد میں داخل ہوئے تو آپ سے تم نے پانی نوش فرمایا جبکہ آپ صلی اللہ علیہ وسلم کھڑے تھے۔“ اس حدیث کو حمید سے صرف شریک نے روایت کیا۔","",{"k":"مجمع الزوائد (٢/٥)، مجمع البحرين (٤١٣٦)، اسناده ضعيف۔"}],[5792,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دو افراد کا کھانا چار کے لیے کافی ہو جاتا ہے اور چار افراد کا کھانا آٹھ کے لیے کافی ہو جاتا ہے۔“ اس حدیث کو عمرو بن دینار قہرمان آل الزبیر سے صرف عمر بن فرقد نے روایت کیا۔ اس میں عبد الصمد بن سلیمان عبد الصمد بن نصر اور عمر بن فرقد بصری کا تفرد ہے۔ ٥٧٩٣","",{"k":"مجمع البحرين (٤٠٢٧)۔"}],[5793,"سیدنا علی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے بہترین لوگ وہ ہیں جو ان میں سے تند مزاج ہیں کہ جب انہیں غصہ آتا ہے تو ٹھنڈا بھی ہو جاتا ہے۔“ یہ حدیث سیدنا علی رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن عثمان الفراء کا تفرد ہے۔ ٥٧٩٤","",{"k":"البحرين، رقم: ٣٠٠٦ ضعيف الجامع الصغير (٢٨٦٤)، سلسله ضعیفه (٢٩)، مجمع۔"}],[5794,"سیدنا ابن سریع تمیمی یا اللہ نے بیان کیا، میں اللہ کے نبی صلی اللہ علیہ وسلم ن کی خدمت میں حاضر ہوا تو میں نے عرض کیا، اللہ کے نبی! میں نے اشعار کہے ہیں، میں نے ان میں اللہ کی شنا بیان کی ہے اور آپ صلی اللہ علیہ وسلم کی مدح بیان کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ر ہے وہ (اشعار ) جن میں تم نے اللہ کی ثنا بیان کی ہے وہ مجھے سناؤ اور جو تم نے میری مدح بیان کی ہے اسے چھوڑ دو۔ پس میں آپ صلی اللہ علیہ وسلم کو اشعار سنانے لگا تو ایک دراز قد شخص اندر آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ٹھہر جاؤ! جب وہ باہر چلا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: سناؤ میں آپ صلی اللہ علیہ وسلم کو اشعار سنانے لگا، میں سنا ہی رہا تھا کہ وہ پھر آ گیا: تو آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ٹھہر جاؤ! جب وہ آدمی باہر نکل گیا تو آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ”سناؤ! میں نے عرض کیا: اللہ کے نبی! یہ کون ہے؟ کہ جب وہ اندر آیا تو آپ ملنے سلیم نے کہا: رک جائے اور جب وہ چلا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ایم نے فرمایا: یہ عمر تھے، کسی چیز میں باطل کا کچھ حصہ نہیں۔ “ اس حدیث کو زہری سے صرف ابراہیم بن سعد نے روایت کیا۔ اس میں معمر بن بکار کا تفرد ہے۔ ٥٧٩٥","",{"k":"طبرانی کبیر (١/٢٨٧، ٨٤٤)، حلية الأولياء (١/٤٢)، اسنادہ ضعیف اس میں معمر بن بکارسعد منکر ہے۔۔"}],[5795,"سیدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عز وجل نے فرمایا: ”میری خاطر سخاوت کرنے والوں کے لیے میری محبت واجب ہوگئی اور میری خاطر باہم میل ملاقات کرنے والوں کے لیے میری محبت واجب ہو گئی۔ اس حدیث کو عبد الملک بن ابی سلیمان سے صرف ابو بکر النہشلی نے روایت کیا۔ اس میں عبد الحمید بن صالح کا تفرد ہے۔ ناندن: مذکورہ حدیث سے معلوم ہوا کہ ہر اچھے کام میں اللہ ذوالجلال کی رضامندی ضروری ہے، لیکن جو کام اللہ ذوالجلال کی رضا کے لیے نہ کیا جائے، وہ کام کتنا بھی اچھا اور بڑا کیوں نہ ہو اس کا","",{"k":"مسند احمد (٢٣٣/٥)، صحیح ترغیب و ترهيب (٣٠٢٠)، مجمع البحرين (٤٩٩٣)۔","f":"نہیں، بلکہ قیامت کے دن وہ عمل گرد و غبار کی طرح اڑا دیا جائے گا اور اس کو جہنم میں پھینک دیا جائے گا۔ جیسا کہ ارشاد باری تعالی ہے: هَلْ أَنكَ حَدِيثُ الْغَاشِيَةِ ٥ وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ، عَامِلَةٌ نَاصِبَةٌ ﴾ (الغاشيه: ١، ٢، ٣) مذکورہ بالا حدیث سے اللہ ذوالجلال کی رضا کے لیے خرچ کرنے اور ملاقات کرنے والوں کی فضیلت بھی واضح ہے ہے۔"}],[5796,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدنا سہیل بن عمرو ضیا لینے سے آب زمزم کا ہدیہ طلب کیا۔ اس حدیث کو ابن محصن وہ ابن عبدالرحمن بن محصن المقری، مکہ والوں کے قراء میں سے ہیں یہ صرف عبد اللہ بن مومل نے اور عبد اللہ بن مؤمل سے صرف ہشیم نے روایت کیا۔ اس میں سفیان بن بشر الکوفی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/٢٨٩)، مجمع البحرين (١٧٤٢)، اسناده ضعيف۔"}],[5797,"سیدہ عائشہ نیا نیا نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جو شخص صف میں شگاف پر کرتا ہے، اس کے بدلے میں اللہ اس کا ایک درجہ بلند کر دیتا ہے اور اس کے لیے جنت میں ایک گھر بنا دیتا ہے۔“ اس حدیث کو المقبمر ی سے صرف ابن ابی ذئب نے اور ابن ابی ذئب سے صرف مسلم بن خالد نے روایت کیا۔ اس میں احمد بن محمد القو اس کا تفرد ہے۔ ٥٧٩٨","",{"k":"مجمع الزوائد (٢/٩٤)، مجمع البحرين، رقم: ٧٥٩ اسنادہ ضعیف اس میں مسلم بن خالد زنجی ضعیف راوی ہے۔۔"}],[5798,"سیدنا علی ضیا الہ سے روایت ہے کہ نبی ملاے علی تم نے سیدنا سعد رضی اللہ عنہ کے لیے اپنے والدین جمع فرمائے (اور کہا: تیر چلاؤ میرے والدین تم پر فدا ہوں)۔ اس حدیث کو سفیان بن عیینہ سے صرف حسین الجعفی نے روایت کیا۔ اس میں عبد اللہ بن عمر کا تفرد ہے۔ ٥٧٩٩","",{"k":"صحیح بخاری (٤٠٥٨)، سنن ترمذی (٢٨٢٨، ٢٨٢٩)، سنن ابن ماجه (١٢٩)۔"}],[5799,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارا گھر تمہارے لیے کافی ہونا چاہیے، اپنی خطائیں یاد کر کے رویا کرو اور اپنی زبان پر قابو رکھ۔“ اس حدیث کو القاسم بن عبد الرحمن سے صرف المسعودی نے اور المسعودی سے صرف جابر بن نوح نے روایت کیا۔ اس میں محمد بن جعفر الفید ی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٢/١٠)، مجمع البحرين (٥١٠٣)، اسناده ضعیف اس میں جابر بن نوح حمانی ضعیف ہے ۔۔","f":"مذکورہ روایت ضعیف ہے۔ اس میں جابر بن نوح الحمانی ضعیف ہے۔ تا ہم دوسری صحیح حدیث میں ہے سیدنا عقبہ بن عامر رضا یہ بیان کرتے ہیں کہ میں نے عرض کیا۔ اللہ کے رسول! نجات کس طرح ممکن ہے؟ آپ میم نے فرمایا: اپنی زبان کو قابو میں رکھو، تمہارا گھر تمہیں اپنے اندر سمالے (یعنی تمہارا فارغ وقت گھر کے اندر ہی گزرے ) اور اپنی غلطیوں پر خوب روؤ۔ (ترمذی، ابواب الزهد، رقم: ٣٤٠٦) معلوم ہوا کہ زبان کی حفاظت کرنا ذریعہ نجات ہے، کیونکہ لوگوں سے میل جول اور گپ شپ میں انسان کے دین کو بہت خطرات لاحق رہتے ہیں، اس لیے زیادہ اختلاط کی بجائے گھر میں اللہ کی اطاعت اور ذکر وفکر اور تلاوت وغیرہ میں اپنے فارغ اوقات کو صرف کرنا بہت بہتر ہے۔ اسی طرح تنہائیوں میں اپنی خطاؤں اور لغزشوں پر رونا بھی اللہ ذوالجلال کو بہت پسندیدہ ہے۔ ٥٨٠٠"}],[5800,"سیدہ عائشہ بنی النیہا نے بیان کیا، نبی صلی اللہ علیہ وسلم کے عہد میں ایک عورت کو طلاق دی گئی، پس اس نے تیس دن انتظار کیا، پھر وہ نبی ملنے سلیم کے پاس آئی تو آپ میم نے فرمایا: ” اپنی فکر آپ کر لے یعنی شادی کرلے۔ اس حدیث کو ابراہیم بن مہاجر کے حوالے سے عامر بن سعد سے صرف ابو جعفر الرازی یحیی بن ماہان نے روایت کیا۔ اس میں حاتم بن اسماعیل کا تفرد ہے۔ ٥٨٠١","",{"k":"مجمع الزوائد (٦/٥)، مجمع البحرين (٢٣٩٣)، اسناده ضعیف۔"}],[5801,"سیدنا سہل بن سعد رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میں اور قیامت ان دو (انگلیوں) کی طرح بھیجے گئے ہیں۔“ اس حدیث کو زہری سے صرف سفیان بن عیینہ نے روایت کیا۔ اس میں ضرار بن صرد کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٣١٥)، صحیح مسلم كتاب الجمعة (٦٧)۔","f":"مذکورہ حدیث میں قرب قیامت کی طرف اشارہ ہے یعنی\n(١) جس طرح یہ انگلیاں ایک دوسرے سے ملی ہوئی ہیں، اسی طرح قیامت کا بھی فاصلہ قریب ہے۔\n(٢) یا جس طرح درمیان انگلی شہادت والی انگلی سے بڑی ہے اتنا فاصلہ رہ گیا ہے۔ اب سوال پیدا ہوتا ہے کا اتنے سال گزرنے کے باوجود قیامت نہیں آئی، حدیث میں اشارہ تو یہ ہے کہ قیامت قریب ہے۔ اس کا جواب یہ ہے کہ آپ ملے لیکن یہ بتلانا چاہتے ہیں کہ گزر جانے والے طویل عرصہ کی نسبت اتنا وقت باقی رہ گیا ہے جتنی درمیان والی انگلی انگشت شہادت سے بڑی ہے۔ مزید دیکھئے تفصیل کے لیے (فتح الباری: ٥٥٢/٩)\n(٣) یہ بھی معلوم ہوتا ہے کہ جس طرح شہادت والی انگلی اور درمیان والی انگلی کے درمیان کوئی اور انگلی نہیں ہے۔ اسی طرح خاتم الرسل ملے مے کے بعد قیامت سے پہلے کسی کو نبی بنا کر مبعوث نہیں کیا جائے گا۔ ٨٠٢"}],[5802,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب ہم میں سے ستر آدمی جمعہ کے لیے جاتے ہیں تو وہ موسی علی نام کے ان ستر آدمیوں کی طرح ہیں جو اپنے رب کی طرف (کوہ طور پر ) وفد بن کر گئے تھے، یا وہ ان سے بھی افضل ہیں۔ اس حدیث کو وائل بن داود سے صرف خالد بن یزید القسری نے روایت کیا۔ اس میں احمد بن بکر البالسی کا تفرد ہے۔ ٥٨٠٣",""],[5803,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم مغرب کے بعد تشریف فرما تھے اور آپ صلی اللہ علیہ وسلم کے ساتھ آپ صلی اللہ علیہ وسلم کے اصحاب بھی تھے، کہ اچانک آپ صلی اللہ علیہ وسلم کے پاس سے ایک قافلہ گزرا، ان کو چلانے والا پڑھ رہا تھا اور ان کا قائد حدی خوانی کر رہا تھا۔ پس جب رسول اللہ صلی اللہ علیہ وسلم نے انہیں دیکھا تو آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور چادر کے بغیر دوڑ پڑے۔ صحابہ کرام نے عرض کیا: اللہ کے رسول! ہم کافی ہیں، آپ نہ جائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے چھوڑ دو، ان کے معاملے میں میری طرف جو وحی کی گئی ہے وہ میں انہیں پہنچاؤں گا۔ پس آپ صلی اللہ علیہ وسلم ان سے جا ملے تو آپ صلی اللہ علیہ وسلم نے فرمایا: تم اس وقت کہاں جا رہے ہو؟“ انہوں نے عرض کیا: ہم یمن جانا چاہتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ” اس وقت تمہارا رات کو سفر کرنا کیسا؟ بے شک آسمان میں اللہ تعالیٰ کے لیے عظیم بادشاہ ہے، وہ اسے زمین کی طرف بھیجتا ہے، پس تم رات کے وقت سفر نہ SSDRESS کرو، تم ایک قدم بھی نہ چلو، ہاں آدمی اپنے پیٹ میں اور اپنے مثانے میں پیشاب وغیرہ پاتا ہے جو کہ ایک لازمی امر ہے اس کے لیے وہ کوئی قدم اٹھا سکتا ہے، اس کے علاوہ قدم بھی نہ اٹھاؤ۔ رہا تو اے لوگوں کو چلانے والے! تم عرب کے کلام سے بعض رجزیہ اشعار یاد کرو، جب تم سواری پر ہو تو انہیں پڑھا کرو اور تم سرشام کوچ کیا کرو، کیونکہ اللہ عزوجل کے کچھ فرشتے مامور ہیں، وہ مسافر کے لیے زمین کو اس طرح لپیٹتے ہیں جس طرح کا پیاں رجسٹر لیٹے جاتے ہیں اور صبح کے بعد لوگ حمد بیان کریں اور تمہارے ساتھ کوئی شاعر ہو نہ کوئی کا ہن اور نہ ہی تمہارے ساتھ کوئی گم شدہ جانور ہو۔ اگر تم منافع، سلامتی اور اچھی ہم نشینی چاہتے ہو تو کسی سائل کو واپس نہ کرو، پس میرے لیے عجیب ہے کہ میں کس طرح سو جاؤں جس وقت تمام آنکھیں سو جاتی ہیں، بے شک اللہ عز وجل اور اس کے رسول تمہیں اس وقت سفر کرنے سے منع فرماتے ہیں۔ اس حدیث کو الشعمی کے آزاد کردہ غلام سلیم سے صرف احمد بن القاسم نخعی نے روایت کیا۔ اس میں احمد بن مصرف بن عمرو کا تفرد ہے۔ ٥٨٠٤","",{"k":"مجمع الزوائد (٣/٢١٥)، اسناده ضعيف۔"}],[5804,"سیدنا حذیفہ ضیا اللہ بیان کرتے ہیں، رسول اللہ صلی اللہ علیہ وسلم کی روح قبض کی گئی تو اللہ تعالیٰ نے سیدنا ابوبکر ضی اللہ کو خلیفہ بنایا، پھر سیدنا ابو بکر بنی ان کی روح قبض کی گئی تو اللہ تعالیٰ نے سیدنا عمر رضی لینے کو خلیفہ بنایا، پھر سیدنا عمر ضیا الیہ نے وفات پائی تو اللہ تعالیٰ نے سیدنا عثمان بنی اہلیہ کو خلیفہ بنایا۔ “ اس حدیث کو ابن ابجر سے صرف اس کے بیٹے نے روایت کیا۔ اس میں ابواسامہ کا تفرد ہے۔","",{"k":"دوو مجمع الزوائد: ٥ / ١٨٢ اسناده صحيح۔","f":"پیچھے بھی احادیث گزر چکی ہیں کہ صحابہ کرام آپس میں فرمایا کرتے تھے کہ نبی معظم نے علی ام کے بعد سیدنا ابو بکر نی اللہ افضل ہیں، ان کے بعد سیدنا عمر ضیا اللہ ان کے بعد سیدنا عثمان رضی اللہ عنہ اور اللہ ذوالجلال نے ان کو خلافت بھی اسی ترتیب سے دی، اگر پہلے خلافت مل جاتی سیدنا عثمان یا اللہ کو تو پھر شیخین ایلیا کو نہیں ملی تھی کیونکہ سیدنا عثمان خان کی زندگی میں ہی شیخین دنیا سے تشریف لے گئے تھے تو اللہ ذوالجلال نے ترتیب سے ان کو خلافت عطا کی۔ ٥٨٠٥"}],[5805,"سیدہ عائشہ منی انہما سے روایت ہے کہ نبی سے ہم آخری دو رکعتوں میں سورۃ الفاتحہ پڑھا کرتے تھے یعنی: ظہر وعصر کی آخری دو رکعتوں میں۔“ اس حدیث کو اشعث سے صرف سنان بن ہارون نے روایت کیا، اس میں عون بن سلام کا تفرد ہے اور یہ سیدہ عائشہ منی اشیا سے صرف اس اسناد سے مروی ہے۔","",{"k":"کر معجم کبیر طبرانی (١٩٦/٨)، مجمع الزوائد (١١٧/٢)۔"}],[5806,"سیدنا عبداللہ ابن عباس رزنی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اسلام کا آغاز اجنبیت سے ہوا اور وہ اجنبیت کی طرف لوٹ جائے گا، پس ان اجنبیوں کے لیے خوش خبری ہے۔ بے شک قیامت سے پہلے تاریک رات کے ٹکروں کی طرح فتنے ہوں گے، ان میں آدمی شام کو مومن ہوگا اور صبح کو کافر ہوگا، صبح کو مومن ہو گا اور شام کو کافر ہو گا، لوگ دنیا کے مال ومتاع کی خاطر اپنا دین بیچ دیں گے۔“ اس حدیث کولیث سے صرف جریر نے روایت کیا۔ اس میں صالح بن عبد اللہ التر مندی کا تفرد ہے۔ یہ سیدنا عبداللہ ابن عباس ریلی لی جا سے صرف اس اسناد سے مروی ہے۔ ٥٨٠٧","",{"k":"مجمع الزوائد (٢٧٨/٧)۔"}],[5807,"سیدنا ابو ہریرہ روی لینہ نے بیان کیا، رسول اللہ السلام نے فرمایا: ”جب صدقہ وصول کرنے والا تمہارے پاس آئے تو وہ خوش ہو کر واپس جائے۔ اس حدیث کو عاصم سے صرف محمد بن فضیل نے روایت کیا۔ اس میں محمد بن طریف کا تفرد ہے اور سیدنا ابو ہریرہ مول لینے سے صرف اسی اسناد سے مروی ہے۔","",{"k":"کر مجمع الزوائد (٨٢/٣)، مسند احمد (٣٦١/٤)، اسناده صحيح۔","f":"مذکورہ حدیث کا مطلب یہ ہے کہ صدقہ لینے والے کو کسی طرح کی زکاۃ کی وصولی میں رکاوٹ نہیں ہونی چاہیے، اس سے بات کرنی ہے نرمی سے تکرار نہیں کرنا چاہیے جو زکاۃ بنتی ہے اس کو خوشی سے ادا کرو، اسی طرح زکاۃ لینے والے کو بھی چاہیے کہ وہ زیادتی نہ کرے، اگر زیادتی کرے تو وہ اللہ کے ہاں مجرم ہوگا اور اس کی شکایت بھی حاکم اعلیٰ سے کی جاسکتی ہے۔"}],[5808,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے انصار کو بلایا تا کہ ان کے نام بحرین لکھ دیں تو انہوں نے عرض کیا: نہیں، مگر یہ کہ آپ ملے لی تاہم اس کے مثل ہمارے مہاجر بھائیوں کے نام بھی لکھیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” تم میرے بعد دیکھو گے کہ دوسرے لوگوں کو بلا استحقاق تم پر ترجیح دی جائے گی پس صبر کرنا حتی کہ تم مجھ سے آملو۔“","",{"k":"صحیح بخاری (٢٣٧٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ\n(١) حکومت کے پاس اگر کچھ فالتو زمین ہو تو وہ عوام میں سے کسی کو بھی اس کی قومی خدمات کے صلہ میں دے سکتی ہے۔\n(٢) نبی معظم منعیم نے انصار کو ہدایت فرمائی کہ وہ فتنوں کے دور میں جب عام حق تلفی دیکھیں خاص طور پر اپنے بارے میں ناسازگار حالات ان کے سامنے آئیں تو ان کو چاہیے کہ صبر وشکر سے کام لیں۔ ٥٨٠٩"}],[5809,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: ایک اعرابی آیا تو اس نے مسجد کے کونے میں پیشاب کر دیا، لوگوں نے اسے زور زور سے آوازیں دیں تو نبی صلی اللہ علیہ وسلم نے انہیں روک دیا، پھر آپ صلی اللہ علیہ وسلم نے پانی کا ڈول منگایا اور اس کے پیشاب پر بہا دیا گیا۔ اس حدیث کو القاسم بن معن سے صرف القاسم بن الحکم العرنی نے روایت کیا۔","",{"k":"صحیح بخاری (٢٢١)، صحيح مسلم (٩٩/٢٨٤)۔"}],[5810,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، جب رسول الله تعلیم کی بیٹی سیدہ زینب بنایا ہوا فوت ہوئیں تو رسول اللہ ملنے کے نام پر غم کے آثار نمایاں تھے۔ پھر وہ کیفیت ختم ہوئی تو ہم نے عرض کیا: اللہ کے رسول! ہم نے آپ ملنے سے ایم کی ایسی کیفیت دیکھی جو ہم نے پہلے نہیں دیکھی، آپ ملٹیم نے فرمایا: ” میں نے سیدہ زینب بنی الجھا، اس کے ضعف اور قبر کے دبانے کو یاد کیا۔ پس وہ ان پر آسان کر دیا گیا ہے، پھر بھی اس (قبر) نے انہیں ایسا دبایا ہے کہ وہ دونوں کناروں تک پہنچ گئی ہے۔ اس حدیث کو سعید بن مسروق سے صرف زکریا بن سلام نے روایت کیا۔ اس میں اسحاق بن سلیمان کا تفرد ہے۔: ٥٨١١","",{"k":"مجمع الزوائد (٣/٥٠)، سنده منقطع . يرو۔"}],[5811,"سیدنا عبد اللہ رضی اللہ عنہ نے بیان کیا، میں ان سورتوں کو جانتا ہوں جن کے مضامین ملتے جلتے ہیں اور رسول اللہ لے لیا ہم انہیں نمازوں میں پڑھا کرتے تھے: سورة الذاريات، الطور، النجم القمر الرحمان، الواقعه، نون، الحاقه المعارج، المزمل، القيامة، الدهر، المرسلات النباء، النازعات عبس، المطففین اور سورۃ التکویر۔ اس حدیث کو سلمہ بن کہیل سے صرف ان کے بیٹوں محمد اور بیٹی نے روایت کیا۔ اس میں محمد سے حسان بن ابراہیم کا تفرد ہے۔ ٥٨١٢","",{"k":"معجم کبیر طبرانی (٣٤٨/٨)۔"}],[5812,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صل علی تم نے فرمایا: ” نیک آدمی کا خواب اللہ کی طرف سے خوشخبری ہے اور وہ نبوت کا چھیالیسواں حصہ ہے۔“ میں نے اسے سیدنا عبداللہ ابن عباس والی تنہا سے بیان کیا تو انہوں نے کہا: العباس بن عبد المطلب رضی اللہ عنہما نے بیان کیا، رسول اللہ ملے سلیم نے فرمایا: وہ نبوت کا پچاسواں حصہ ہے۔ یہ حدیث العباس بنی الیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں علی بن حکیم کا تفرد ہے۔ ٥٨١٣","",{"k":"کر مجمع الزوائد (١٧٦/٧)، ضعيف الجامع الصغير (٣٠٧٩)۔"}],[5813,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، وہ پرچم جو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو عطا کیا وہ سفید تھا۔ اس حدیث کو قتادہ سے صرف عمر بن موسی نے اور عمر سے صرف الولید بن عبد الواحد نے روایت کیا۔ اس میں محفوظ بن بحر کا تفرد ہے۔ ٥٨١٤","",{"k":"اسنادہ ضعیف . اس میں عمر بن موسی بن وجیہ ضعیف ہے ۔۔"}],[5814,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم قضائے حاجت کے لیے باہر تشریف لے گئے، میں آپ صلی اللہ علیہ وسلم کے لیے پانی لے کر گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں اس کے متعلق کس نے کہا ہے؟ میں نے عرض کیا: کسی نے بھی مجھے اس کا حکم نہیں دیا، آپ میم نے فرمایا: تم نے اچھا کیا، جنت کی بشارت ہو۔ پھر علی ضیا اللہ آئے، میں نے انہیں جنت کی بشارت دی۔“ اس حدیث کو عمرو بن مرہ کے حوالے سے ابراہیم سے صرف ابو مریم نے روایت کیا اور اعمش و ابو الجحاف نے اسے عمرو بن مرہ عن عبد اللہ بن سلمہ بن عبیدہ عن عبد اللہ کی سند سے روایت کیا ہے۔","",{"k":"بْنِ سَلَمَةَ، عَنْ عُبَيْدَةَ، عَنْ عَبْدِ اللَّهِ . معجم کبیر طبرانی (٩/٩)، سنده ضعيف جدا۔"}],[5815,"سیدنا خالد بن ولید رضی اللہ عنہ نے بیان کیا، میں نے نبی علم کو فرماتے ہوئے سنا: ”ہر امت کا ایک امین ہوتا ہے اور اس امت کا امین ابو عبیدہ بن الجراح ہے۔“ یہ حدیث خالد بن ولید سے صرف اس اسناد سے مروی ہے۔ اس میں مقدم بن محمد کا تفرد ہے۔ ٥٨١٦","",{"k":"مجمع الزوائد (٣٤٨/٩)۔"}],[5816,"سیدنا ابو ہریرہ رضی یا علینہ نے بیان کیا، ہم نے غزوہ احد کا تذکرہ کیا جبکہ نبی صلی اللہ علیہ وسلم کھڑے نماز پڑھ رہے تھے۔ جب آپ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو ہماری طرف متوجہ ہو کر فرمایا: ” کیا میں تمہیں غزوہ احد کے بارے میں نہ بتاؤں؟ میں نے دیکھا کہ میری دائیں جانب جبریل عالی نام تھے اور بائیں جانب طلحہ تھے۔‘ اس حدیث کو عیسی بن طلحہ سے طلحہ بن بیٹی نے اور طلحہ بن بیٹی سے صرف ابن ادریس نے روایت کیا۔ اس میں القعقاع بن زکریا کا تفرد ہے۔: ٥٨١٧","",{"k":"مجمع الزوائد (١٥١/٩)، ضیعف الجامع الصغير (٤٧٠٤)۔"}],[5817,"سیدنا جابر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”میری امت کے دو گروہ ایسے ہیں جو میری شفاعت سے محروم رہیں گے، مرجہ اور قدریہ۔ اس حدیث کو شریک سے صرف القاسم بن العلاء نے روایت کیا۔","",{"k":"الزوائد: ٠٩/٧ مجمع ٢٠، اسناده ضعيف۔"}],[5818,"سیدنا ابو ہریرہ ضیا اللہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جو شخص کسی میت کی طرف سے حج کرتا ہے تو حج کرنے والے کو بھی اس کے مثل ثواب ملتا ہے، جو کسی روزہ دار کو روزہ افطار کراتا ہے تو اس کو بھی اتنا ہی ثواب ملتا ہے اور جو کسی نیکی کی طرف راہنمائی کرتا ہے تو اس کو بھی نیکی کرنے والے کے برابر ثواب ملتا ہے۔ اس حدیث کو ابن جریج سے صرف عبد الملک بن ابی کریمہ نے روایت کیا۔ اس میں علی بن بہرام کا تفرد ہے۔",""],[5819,"سیدنا عبد الرحمان بن سمرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ تعلیم نے فرمایا: ”جس نے ان دونوں ( والدین ) کی قسم پوری کی، ان کے قرض کی ادائیگی کی اور ان کے لیے گالی کا سبب نہ بنا تو وہ اچھا سلوک کرنے والا لکھ دیا جاتا ہے خواہ وہ نافرمان ہو اور جس نے ان کی قسم پوری کی، نہ ان کا قرض ادا کیا اور ان کے لیے گالی کا سبب بنا تو وہ نافرمان لکھا جاتا ہے خواہ وہ ان (والدین) کی زندگی میں اچھا سلوک کرنے والا تھا۔“ یہ حدیث سیدنا عبد الرحمن بن سمرہ بنی الیہ سے صرف اس اسناد سے مروی ہے۔ اس میں حفص بن غیاث کا تفرد ہے۔","",{"k":"مجمع الزوائد: ٨ / ١٥٠ . ٠/٨ ١٠۔"}],[5820,"سیدنا معاویہ بن ابی سفیان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اس حال میں فوت ہو کہ اس پر کوئی امام نہ ہو تو وہ جاہلیت کی موت مرتا ہے۔‘ اس حدیث کو اعمش سے صرف ابو بکر بن عیاش نے روایت کیا، اس میں الاسود بن عامر شاذان کا تفرد ہے اور شاذان کے علاوہ دیگر نے اسے ابوبکر بن عیاش کے حوالے سے عاصم بن بہدلہ سے روایت کیا ہے۔ مذکورہ حدیث میں مسلمانوں کو جماعت کے ساتھ رہنے کی ترغیب دی جا رہی ہے کہ وہ حاکم وقت کے خلاف بغاوت نہ کریں بلکہ حاکم وقت کی جائز کاموں میں اطاعت کریں۔ مذکورہ بالا روایت میں جو امام کا تذکرہ ہے اس سے مراد حاکم وقت ہے جو ملک کا امیر اور حاکم ہوتا ہے جس کا امام نہ ہوا تو وہ جاہلیت کی موت مرا۔ یہ اس لیے فرمایا کہ اسلام سے قبل امیر کی اطاعت کا کوئی تصور نہیں تھا۔ بلکہ اس میں وہ اپنی عار اور ذلت محسوس کرتے تھے۔ اسلام نے اس طوائف الملو کی کا خاتمہ کر کے انہیں نظم وضبط کا پابند بنایا اور اطاعت امیر کی تاکید کی۔ ٢١ ٥٨","",{"k":"مجمع الزوائد (٥/٢٢٨)، مسند احمد (٤/٩٦)، ابن حبان (٤٥٧٣)، قال شعیب الارناؤط، حديث صحيح۔"}],[5821,"سیدنا ابو بکرہ رضی اللہ عنہ نے بیان کیا، جس وقت جبریل علینا نے ( آب زم زم سے ) نبی ملنے کی یمن کا دل دھویا تھا تو اس وقت انہوں نے آپ صلی اللہ علیہ وسلم کے ختنے بھی کیے تھے۔“ یہ حدیث ابو بکرہ رضی نہیں صرف اسی اسناد سے مروی ہے، اس میں عبد الرحمن بن عیینہ کا تفرد ہے۔ ހނ","",{"k":"مجمع الزوائد (٢٢٧/٨)۔","f":"قال الهيثمي جماله فيه عبد الرحمان بن عيينه، ومسلمة بن محارب ولم اعرفها وبقية رجاله ثقات"}],[5822,"سیدنا عمار بن یاسر رضی اللہ عنہ یہ بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ ارشاد فرمایا: تو فرمایا: ” آج کون سا دن ہے؟ ہم نے عرض کیا: قربانی کا دن ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ” یہ کون سا مہینہ ہے؟“ ہم نے عرض کیا: ذوالحجہ، حرمت والا مہینہ، آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ کون سا شہر ہے؟“ ہم نے عرض کیا: حرمت والا شہر ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارے خون ( جانیں) تمہارے اموال اور تمہاری عزتیں تم پر اس طرح حرام ہیں جس طرح تمہارے اس دن کی، تمہارے اس مہینے میں اور تمہارے اس شہر میں حرمت ہے، جو یہاں موجود ہے وہ ان احکام کو اس تک پہنچا دے جو یہاں موجود نہیں۔“ یہ حدیث سیدنا عمار بن یاسر رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عبد الرحمن بن عمرو بن جبلہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٩٨/٧)۔"}],[5823,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”جبریل علیہ اسلام نے مجھے فرمایا: ”روئے زمین پر فرعون مجھے انتہائی ناپسندیدہ تھا، جب وہ اپنے منہ سے ایمان لایا تو میں اس اندیشے کے پیش نظر اس کے منہ میں کیچڑ بھرنے لگا کہ کہیں رحمت اسے پہنچ نہ جائے۔“","",{"k":"مجمع الزوائد (٧/٣٩)۔","f":"مرتے وقت انسان کا ایمان لانا یا عذاب آجانے کے بعد ایمان لانا فائدہ مند نہیں ہوگا۔ ارشاد باری تعالیٰ ہے: وَ جُوَزْنَا بِبَنِي إِسْرَاءِ يْلَ الْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ بَغْيًا وَ عَدْوًا حَتَّى إِذَا أَدْرَكَهُ الْغَرَقُ قَالَ مَنْ لا إلهَ إِلَّا الَّذِى أَمَنَتْ بِهِ بَنُوا إِسْرَاءِ يْلَ وَآنَا مِنَ الْمُسْلِمِينَ (يونس: ٩٠) اور ہم نے بنی اسرائیل کو دریا سے پار کر دیا، پھر ان کے پیچھے پیچھے فرعون اپنے لشکر کے ساتھ ظلم اور زیادتی کے ارادہ سے چلا یہاں تک کہ جب ڈوبنے لگا تو کہنے لگا کہ میں ایمان لاتا ہوں جس پر بنی اسرائیل ایمان لائے ہیں، اس کے سوا کوئی معبود نہیں اور میں مسلمانوں میں سے ہوں۔“ سیدنا جبریل عالینام کو اللہ ذوالجلال کی رحمت کی امید تھی کہ ممکن ہے کہ اللہ ذوالجلال اس پر رحمت ہی نہ کر دے اور اس کو معاف کر دے اس لیے انہوں نے اس کے منہ میں کیچڑ داخل کر دیا۔"}],[5824,"سیدنا ابو موسی رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اے اللہ! تو مجھے معاف کر دے، جو کچھ میں نے پہلے کیا اور جو کچھ بعد میں کیا، جو میں نے چھپ کر کیا اور جو کچھ علانیہ کیا اور جسے تو مجھ سے بہتر جانتا ہے تو ہی آگے لے جانے والا ہے تو ہی پیچھے کرنے والا ہے اور تو ہر چیز پر قادر ہے۔“ اس حدیث کو نصیر بن الاشعث سے صرف عنبہ نے روایت کیا۔ اس میں اس کے بیٹے کا اس سے تفرد ہے۔","",{"k":"مسند احمد (٣٩١/٤)، مجمع الزوائد (١٠/٢١٢)، سنن ابو داؤد (١٠.٩)۔","f":"سیدنا علی نبی الیہ سے روایت ہے کہ رسول اللہ ملے لیکن جب نماز کے لیے کھڑے ہوتے تو تشہد اور سلام کے مابین آخر میں یہ کلمات پڑھتے تھے: نه دنده ((اللهم اغفرلى ما قدمت وما اخرت وما أسررت وما اعلنت وما اسرفت وما انت اعلم به منى انت المقدم وانت المؤخر لا اله الا انت)) (مسلم، كتاب صلاة المسافرین: ٧٧١)"}],[5825,"ابو اسحاق تمیم نے سیدنا عمر ضیا اللہ سے روایت کیا کہ انہوں نے حجر اسود کو بوسہ دیا اور کہا: میں خوب جانتا ہوں کہ تو ایک پتھر ہے تو کسی نفع و نقصان کا اختیار نہیں رکھتا، اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو تجھے بوسہ دیتے ہوئے نہ دیکھا ہوتا تو میں تجھے بوسہ نہ دیتا۔ اس حدیث کو ابو اسحاق سے صرف شریک نے روایت کیا۔ اس میں ابو بلال کا تفرد ہے۔ ٥٨٢٦","",{"k":"صحیح بخاری (١٥٩٧)، مسلم (١٢٧٠)۔"}],[5826,"سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”میری امت میں ایک آدمی ہو گا وہ موت کے بعد باتیں کرے گا۔“ اس حدیث کو منصور سے صرف شریک نے روایت کیا۔ اس میں ابراہیم بن الحسن التعلمی کا تفرد ہے۔ ٨٢٧","",{"k":"مجمع الزوائد (٢٩٤/٨)، اسناده ضعيف۔"}],[5827,"محمد بن سیرین نے بیان کیا، سیدنا عقبہ بن عامر رضی اللہ عنہ مسلمہ بن مخلد رضی اللہ عنہ کے پاس گئے جبکہ وہ مصر کے حکمران تھے، ان کے اور دربان کے درمیان کوئی مسئلہ تھا، پس جب اس نے انہیں اجازت دی تو وہ ان (مسلمہ) کے پاس گئے تو انہوں نے کہا: میں زیارت کے لیے آنے والے اپنے بھائی کو خوش آمدید کہتا ہوں۔ اس پر انہوں نے کہا: میں آپ کے پاس زیارت کرنے کے لیے نہیں آیا، میں تو ایک حدیث کے لیے آیا ہوں، جسے آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔“","",{"k":"اسناده صحيح . صحیح ترغیب و ترهیب (٣٣٣٦)، مسند احمد (١٠٤/٤)۔","f":"معلوم ہوا صحابہ کرام احادیث رسول کی تعلیم کے لیے دور دراز کا سفر کیا کرتے تھے۔ (٢) طلب حدیث کے لیے نکلنا اور سفر کی صعوبتیں برداشت کرنا باعث فضیلت ہے خیر القرون میں اس کی بے شمار مثالیں موجود ہیں۔ ٥٨٢٨"}],[5828,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ” جسے کوئی چیز عمری کے طور پر دی جائے تو وہ اس کے لیے ہے اور اس کی اولاد کے لیے ہے۔“ اس حدیث کو محمد بن عمر و سے صرف ابو بکر بن عیاش نے روایت کیا۔ اس میں احمد بن یونس کا تفرد ہے۔ ٥٨٢٩","",{"k":"مُحَمَّدِ سنن نسائی (٣٧٤٠)، سنن ابن ماجه (٢٣٧٩)، قال الشيخ الالباني: صحيح. الله۔"}],[5829,"سیدنا عبداللہ ابن عم رضی اللہ عنہ نے فرمایا: یعنی دوران سفر دو رکعتیں کم نہیں بلکہ پوری نماز ہے۔ خاندن مذکورہ حدیث سے معلوم ہوا کہ دوران سفر دو رکعت نماز پڑھنا ہی پوری نماز ہے۔ ایک دوسری حدیث میں ہے، سیدنا عبد اللہ بن عمر ضیا المیہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی سکھائی ہوئی باتوں میں سے یہ بھی ہے کہ بے شک اللہ تعالیٰ نے ہمیں یہ حکم دیا ہے کہ ہم دوران سفر صرف دو رکعت نماز ادا کریں، (صحیح،نسائی، رقم: ٤٤٣، ابن خزیمه، رقم: (٩٤٦) ایک دوسری روایت میں ہے کہ سیدنا عمر رضی اللہ عنہ فرماتے ہیں کہ نبی معظم صلی اللہ علیہ وسلم دوران سفر دو رکعتوں سے زیادہ نہیں پڑھتے تھے اور سیدنا ابو بکر،سیدنا عمر، سیدنا عثمان بنی ادم کا بھی یہی طرز عمل تھا۔ (صحیح بخاری، کتاب الجمعة، رقم: ١١٠٢، صحیح مسلم، رقم: ٦٨٩) ٥٨٣٠","",{"k":"مجمع الزوائد (٢٥٩/١١)۔"}],[5830,"سیدنا ابو بکر صدیق رضی اللہ عنہ نے بیان کیا، مجھے بتایا گیا ہے کہ فرعون کے سامنے کے دانت ٹوٹے ہوئے تھے۔“","",{"k":"و ه و، ه، مجمع الزوائد (٧/٣٩)، مجمع البحرين (٣٣٣٧)۔","f":"حاظ میشمی اللہ فرماتے ہیں: کہ مذکورہ حدیث کے راوی نعیم بن یحیی کو میں نہیں جانتا۔ ٥٨٣١"}],[5831,"سیدنا سعد رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے میرے علاوہ کسی اور کے لیے کبھی اپنے والدین جمع نہیں فرمائے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \" ( سعد!) تیر چلاؤ، میرے والدین تم پر فدا ہوں۔“ ان احادیث کو نعیم بن یحیی السعیدی الکوفی سے صرف احمد بن یونس نے روایت کیا۔","",{"k":"کر صحیح بخاری (٤٠٥٧)، سنن ترمذی (٢٨٣٠)، سنن ابن ماجه (١٣٠، ٥٦٢٧)۔"}],[5832,"سیدنا ابو عبد الله الجد لی نے بیان کیا، سیدہ ام سلمہ منی اشیا نے مجھ سے کہا: کیا تمہاری موجودگی میں منبروں پر رسول اللہ صلی علی ایم کو برا بھلا کہا جاتا ہے؟ میں نے کہا: سبحان اللہ! رسول اللہ صلی اللہ علیہ وسلم کو کیسے برا بھلا کہا جا سکتا ہے؟ انہوں نے فرمایا: کیا سیدنا علی بن ابی طالب نیل اللہ اور ان سے محبت کرنے والوں کو برا بھلا نہیں کہا جاتا؟ میں گواہی دیتی ہوں کہ رسول اللہ صلی اللہ علیہ وسلم ان سے محبت کرتے تھے۔“ اس حدیث کو السد ی سے صرف عیسی بن عبد الرحمن السلمی نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کرام کو گالیاں دینا یا صحابہ کرام مبنی الیم سے محبت کرنے والوں کے متعلق اپنی غلط زبان استعمال کرنا ایسے ہی ہے جیسا کہ یہ رسول اللہ صلی اللہ علیہ وسلم کو برا بھلا کہہ رہا ہے۔ اس سے ان لوگوں کو بھی سبق حاصل کرنا چاہیے جو دین اسلام پر عمل کرنے والوں کا مذاق اڑاتے ہیں۔ یہ ان کا مذاق نہیں بلکہ یہ نبی مکرم سے علم کا مذاق اڑا رہے ہیں، کیوں کہ یہ اسلام پر چلنے والوں کا مذاق اڑایا جاتا ہے کہ یہ لوگ اپنی زندگی سنت نبوی کے مطابق گزار رہے ہیں، کبھی شلوار ٹخنوں کے اوپر کا مذاق، کبھی داڑھی کا مذاق، جبکہ شلوار ٹخنوں کے اوپر رکھنا اور داڑھی رکھنا یہ رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے اور سنت پر عمل کرنے والا رسول اللہ صلی اللہ علیہ وسلم کا محبوب ہے۔","",{"k":"مجمع الزوائد (١٣٠/٩)، مجمع البحرين (٣٧١٦)، اسناده صحيح۔"}],[5833,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سورۃ اخلاص تہائی قرآن کے برابر ہے۔“ اس حدیث کو الزہری عن حمید بن عبد الرحمن عن ابی ہریرہ کی سند سے صرف ابراہیم بن اسماعیل نے اور ابراہیم سے صرف یونس بن بکیر نے روایت کیا۔ اس میں عبید بن یعیش کا تفرد ہے۔ الزہری کے بھائی کے بیٹے نے اسے زہری عن حمید عن امہ ( ان کی والدہ ام کلثوم ) کی سند سے روایت کیا۔","",{"k":"کر صحیح مسلم، سنن ترمذی (٢٨٩٩)، سنن ابن ماجه (٣٧٨٧)۔"}],[5834,"سیدنا جریر بن عبد اللہ رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: ” یمن والوں میں سے بہتر شخص تمہارے پاس آئے گا، اس کے چہرے پر بادشاہت کا نشان ہوگا۔ پس وہ میں ہی آیا تھا۔ اس حدیث کو قابوس سے صرف ابو کرینہ نے روایت کیا۔ اس میں سوید بن عمرو الکلمی کا تفرد ہے۔ خالد سیدنا جریر بن عبد اللہ بجلی یا اللہ فتح مکہ کے بعد ٩ ہجری میں مسلمان ہوئے۔ (البدايه عبد والنهایه) سیدنا عمر رضی اللہ عنہ فرمایا کرتے تھے: جریر ((يوسف هذه الامة ) اس امت کا یوسف ہے۔ الملک بن عمیر نے بیان کیا ہے: میں نے سیدنا جریر بی الیہ کو دیکھا، آپ کا چہرہ چاند کا ٹکڑا معلوم ہوتا تھا اور مذکورہ بالا روایت میں ہے، اس کے چہرے پر بادشاہت کا نشان ہے، اس سے مراد بھی خوبصورتی ہے۔ یہ سیدنا عثمان ضیا اللہ کی شہادت کے بعد سیدنا علی اور سیدنا معاویہ وہ پہنچا سے الگ ہو گئے اور جزیرہ میں مقیم رہے۔ حتی کہ ٥١ ہجری میں السراۃ کے مقام پر فوت ہو گئے۔ ٥٨٣٥","",{"k":"مجمع الزوائد (٩/٣٧٥)، مجمع البحرين (٣٩٠٤)، ادب المفرد (٢٥٠)، اسناده صحيح۔"}],[5835,"و سیدہ عائشہ علی النیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں تمہارے لیے اس طرح ہوں جس طرح ابو زرع ام زرع کے لیے تھا۔“ ناندن صحیح بخاری میں مفصل حدیث موجود ہے۔ سید عائشہ بنا لوہا فرماتی ہیں کہ گیارہ عورتوں کا ایک اجتماع ہوا جس میں انہوں نے آپس میں طے کیا کہ مجلس میں وہ اپنے خاوند کا صحیح صحیح حال بیان کریں، کوئی بات نہ چھپاویں ( دس کے بیان کے لیے دیکھئے صحیح بخاری: اور گیارہویں ان میں سے ام زرع بنت اکمل تھی) ام زرع کہنے لگی: میرا خاوند ابو زرع ہے اس کا کیا کہنا؟ اس نے میرے کانوں کو زیوروں سے بوجھل کر دیا ہے اور میرے دونوں باز و چربی سے پھلا دیئے ہیں، مجھے خوب کھلا کر موٹا کر دیا ہے، کہ میں بھی اپنے تئیں خوب موٹی سمجھنے لگی ہوں، شادی سے پہلے میں تھوڑی بھیڑ بکریوں میں تنگی سے گزر بسر کرتی تھی، ابو زرعہ نے مجھ کو گھوڑوں، اونٹوں، کھیت کھلیان سب کا مالک بنا دیا ہے، اتنی بہت جائداد ملنے پر بھی اس کا مزاج اتنا عمدہ ہے کہ بات کہوں تو برا نہیں مانتا، مجھ کو کبھی برا نہیں کہتا۔ سوئی پڑی رہوں تو صبح تک مجھے کوئی نہیں جگاتا، پانی پیوں تو خوب سیراب ہو کر پی لوں، رہی ابو زرعہ کی ماں (میری ساس) تو میں اس کی کیا خوبیاں بیان کروں، اس کا توشہ خانہ مال واسباب سے بھرا ہوا، اس کا گھر بہت ہی کشادہ، ابوزرعہ کا بیٹا بھی کیسا اچھا خوبصورت ( نازک بدن دبلا پتلا) ہری چھالی اور نگی تلوار کے برابر اس کے سونے کی جگہ، ایسا کم خوراک کہ بکری کے چار ماہ کے بچے کے دست Y م ٢ کا گوشت اس کا پیٹ بھر دے، ابو زرعہ کی بیٹی وہ بھی سبحان اللہ کیا کہنا! اپنے باپ کی پیاری، اپنی ماں کی پیاری، ( تابع فرماں اطاعت گزار ) کپڑا بھر پور پہنے والی (موٹی تازی) سوکن کی جلن۔ ابو زرعہ کی لونڈی اس کا بھی کیا پوچھتے ہو؟ کبھی کوئی بات ہماری مشہور نہیں کرتی ( گھر کا بھید ہمیشہ پوشیدہ رکھتی ہے) کھانے تک نہیں چراتی، گھر میں کوڑا کچرا نہیں چھوڑتی، مگر ایک دن ایسا ہوا کہ لوگ مکھن نکالنے کو متھ رہے تھے ( صبح ہی صبح ) ابو زرعہ باہر گیا اچانک اس نے ایک عورت دیکھی، جس کے دو بچے چیتوں کی طرح اس کی کمر کے تلے دو اناروں سے کھیل رہے تھے ( مراد اس کی دونوں چھاتیاں ہیں جو انار کی طرح تھیں) ابو زرعہ نے مجھ کو طلاق دے کر اس عورت سے نکاح کر لیا، اس کے بعد میں نے ایک اور شریف سردار سے نکاح کر لیا جو گھوڑے کا اچھا سوار، عمدہ نیزہ باز ہے اس نے بھی مجھے کو بہت سے جانور دے دیئے ہیں اور ہر قسم کے اسباب میں سے ایک جوڑا دیا ہوا ہے اور مجھ سے کہا کرتا ہے: کہ ام زرع خوب کھاپی، اپنے عزیز و اقرباء کو بھی خوب کھلا پلا، تیرے لیے عام اجازت ہے، مگر یہ سب کچھ بھی جو میں نے تجھ کو دیا ہوا ہے اگر اکٹھا کروں تو تیرے پہلے خاوند ابو زرعہ نے جو تجھ کو دیا تھا اس میں اس کا ایک چھوٹا برتن بھی نہ بھرے۔ سیدہ عائشہ بنی ہو یا فرماتی ہیں کہ یہ سارا قصہ سنانے کے بعد نبی معظم صلی اللہ علیہ وسلم نے مجھے سے فرمایا: عائشہ! میں بھی تیرے لیے ایسا خاوند ہوں جیسے ابو زرع ام زرع کے لیے تھا۔ ٥٨٣٦","",{"k":"صحیح بخاری (٥١٨٩)، صحیح مسلم (٢٤٤٨)۔"}],[5836,"سیدنا علی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم عید الفطر کے دن عید گاہ جانے سے پہلے ( طاق عدد میں کھجوریں) کھایا کرتے تھے۔“ یہ حدیث سیدنا علی بنی لینے سے صرف اس اسناد سے مروی ہے۔ اس میں سوار بن مصعب کا تفرد ہے۔ ٥٨٣٧","",{"k":"مجمع الزوائد (٢٠٢/٤)۔"}],[5837,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کنکری پھینکنے سے منع فرمایا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ آنکھ پھوڑ دیتی ہے اور دانت توڑ دیتی ہے۔“ اس حدیث کو محمد بن سیرین سے صرف اشعث بن سوار نے روایت کیا۔ اس میں علی بن مسہر کا تفرد ہے۔ ٥٨٣٨","",{"k":"صحیح بخاری (٦٢٢٠)، صحیح مسلم (١٩٥٤)۔"}],[5838,"سیدنا عبد اللہ ابن عمر ضیا المیہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دو اینٹوں کے درمیان قبلے کی طرف بول و براز کرتے دیکھا، جبکہ آپ گھر کی چھت پر تھے۔ ایوب بن عقبہ نے کہا: گویا کہ ان کی اچانک نظر پڑی۔“ خاندن. ایک دوسری حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: پاخانہ یا پیشاب کرتے وقت قبلہ کی جانب منہ کرو نہ ہی پیٹھ بلکہ مشرق یا مغرب کی جانب رخ کرلو۔ (صحیح بخاری، کتاب الصلاة، رقم: ٣٩٤) ان روایات کے اختلاف کے باعث اس مسئلے میں بھی اختلاف کیا گیا ہے۔ تاہم علماء کرام نے ان بظاہر متعارض روایات میں تطبیق یوں دی ہے کہ یہ ممانعت کھلی فضا میں ہے۔ عمارت یا تعمیر شدہ بیت الخلا میں نہیں، کیونکہ رسول اللہ صلی اللہ علیہ وسلم کو جن صحابہ نے قبلہ کی جانب ہو کر قضائے حاجت کرتے ہوئے دیکھا تھا انہوں نے فضا میں نہیں بلکہ گھر میں دیکھا تھا۔ سیدنا عبداللہ ابن عمر ضیا الہیہ کے عمل سے بھی اس کی تائید ہوتی ہے۔ مروان بن اصفر اللہ بیان کرتے ہیں: کہ میں نے سیدنا عبداللہ ابن عمر رضی اللہ عنہما کو دیکھا، انہوں نے قبلہ کی جانب اپنی سواری بٹھائی، پھر اس کی طرف پیشاب کرنے لگے تو میں نے کہا: عبد الرحمان! کیا اس سے منع نہیں کیا گیا؟ تو انہوں نے کہا، کیوں نہیں لیکن اس عمل سے صرف فضا میں منع کیا گیا ہے اور جب تمہارے اور قبلہ کے درمیان کوئی اوٹ حائل ہو تو اس میں کوئی حرج نہیں۔ (صحیح ابو داؤد، رقم: ٨) ٥٨٣٩","",{"k":"و، و، صحیح بخاری (١٤٥)، صحیح مسلم (٢٦٦)۔"}],[5839,"سیدنا عبداللہ ابن عباس نیلی اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو ہمارے خلاف ہتھیار اٹھائے وہ ہم میں سے نہیں۔“ اس حدیث کو بیچی بن ابی کثیر سے صرف ایوب بن عتبہ نے روایت کیا۔ ہتھیار اٹھانے سے مراد مسلمانوں کی جماعت کے خلاف خروج و بغاوت کرنا، یا بغیر کسی وجہ کے کسی مسلمان پر تلوار، بندوق، موزر اور کلاشنکوف وغیرہ اٹھانا اور اسے مار دینا ہے جیسے آج کل بدقسمتی سے یہ دہشت گردی عام ہے۔ ”ہم میں سے نہیں“ کا مطلب ہے مسلمانوں کے طریقے پر نہیں، اس کا یہ کردار مومنانہ نہیں، غیر مومنانہ ہے۔ اس لیے ہر مسلمان کو ہر قسم کی دھوکہ دہی سے اجتناب کرنا چاہیے۔","",{"k":"بن عتبة . مجمع الزوائد (٢٩٤٧)، صحیح بخاری، صحیح مسلم (٩٨)، ادب المفرد (١٢٨٠)۔"}],[5840,"سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا، نبی ملے لی ایم نے فرمایا: ”میرے بعد ابو بکر وعمر دونوں کی اقتدا کرنا، عمار کے طریقے پر چلنا اور ابن ام عبد (ابن مسعود نی نی ) کے عہد کو تھامنا۔“ یہ حدیث مسعر سے صرف اس اسناد سے مروی ہے۔ ٥٨٤١","",{"k":"مجمع الزوائد (٢٩٨/٩)، مجمع البحرين (٣٨٥١)، حاكم (٣/٧٥)۔"}],[5841,"سیدنا جریر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب غلام مفرور ہو جاتا ہے تو اس سے ذمہ وامان ختم ہو جاتی ہے۔ اس حدیث کو شیبانی سے صرف شریک نے روایت کیا۔ مذکورہ حدیث کا مطلب یہ ہے کہ اسلام کی پناہ جاتی رہی یا پہلے جو اس کی حمایت ہوتی","",{"k":"صحیح مسلم (٦٩)، سنن ابو داؤد (٤٣٦٠)۔","f":"تھی وہ نہ ہوگی، یہ تشدید اور تغلیظ پر محمول ہے۔ ٥٨٤٢"}],[5842,"سیدنا شراحیل بن مرہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلے علی کو سیدنا علی رضی اللہ عنہ سے فرماتے ہوئے سنا: علی! خوش ہو جا، تیرا جینا مرنا میرے ساتھ ہے۔“ اس حدیث کو ابو اسحاق سے صرف قیس نے روایت کیا اور شراحیل بن مرہ سے صرف اس اسناد سے مروی ہے۔ خاندن. ایک دوسری حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے سیدنا علی ضیا اللہ کے متعلق فرمایا: ((انت منى وانا منك)) تم مجھ سے ہو اور میں تم سے ہوں۔“ سیدنا مربی الیہ نے سیدنا علی رضی اللہ عنہ سے کہا: کہ رسول اللہ صلی اللہ علیہ وسلم اپنی وفات تک ان سے راضی تھے۔ (صحیح بخاری، کتاب فضائل اصحاب النبی صلی اللہ علیہ وسلم باب مناقب علی بن ابی طالب القريشي الخ) ٥٨٤٣","",{"k":"مجمع الزوائد (٩/١١٥)، مجمع البحرين (٣٧٢٨)، کنز العمال (٣٣٩٨٤)، اسناده حسن۔"}],[5843,"سیدنا عبداللہ ابن عمر نبی الیہ سے روایت ہے کہ جب وہ حجر اسود کے استلام کا ارادہ کرتے تو یوں کہتے تھے: اے اللہ! تجھ پر ایمان لاتے ہوئے، تیری کتاب کی تصدیق کرتے ہوئے اور تیرے نبی اسے علم کی سنت پر عمل کرتے ہوئے، پھر وہ اس کا استلام کرتے تھے۔“ اس حدیث کو نافع سے صرف محمد بن مہاجر نے روایت کیا۔ اس میں عون بن سلام کا تفرد ہے۔","",{"k":"معجم ٣٠٢/١١، كبير (١١/٣٠٢)، مجمع الزوائد (٣/٢٤٠)، مجمع البحرين (١٧٢٥)۔"}],[5844,"سیدنا عبداللہ ابن عباس فضل اللہ جا نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: ”حج عرفات کے میدان میں وقوف کا نام) ہے۔“ اس حدیث کو خصیف سے صرف عبد السلام بن حرب نے روایت کیا اور سیدنا عبد اللہ ابن عباس رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے۔ خاندان مذکورہ حدیث کا مطلب یہ ہے کہ وقوف عرفہ فرض ہے۔ اگر یہ رہ جائے تو حج ادا نہیں ہو گا اور نہ ہی فدیہ دینے سے اس کی تلافی ہوگی اور وقوف عرفہ کا وقت ٩ ذی الحجہ کے دن زوال سے لے کر اذی الحجہ کی طلوع فجر تک ہے۔ جیسا کہ سیدنا عبد الرحمان بن یعمر نا اہلیہ کہتے ہیں: کہ میں نبی مکرم ملنے نیم کے پاس تھا کہ کچھ لوگ آئے اور حج کے بارے میں پوچھا؟ تو آپ مالٹے سلیم نے فرمایا: حج عرفات میں ٹھہرنے کا نام ہے جو شخص مزدلفہ کی رات ( یعنی ٩ اور ١٠ ذی الحجہ کی درمیانی رات ) طلوع فجر سے پہلے عرفات میں پہنچ جائے اس کا حج ادا ہو گیا۔ (نسائی، کتاب الحج، باب فرض الوقوف بعرفة، اسنادہ صحیح) معلوم ہوا کہ جو شخص ١٠ ذوالحجہ کی طلوع فجر سے پہلے گھڑی بھر کے لیے بھی میدان عرفات میں پہنچ جائے، اس کا حج ادا ہو جاتا ہے۔","",{"k":"٥٨٤٤ مجمع الزوائد (٢٥٤/٣)، مجمع البحرين (١٧٥٧)۔"}],[5845,"سیدنا سعد رضی اللہ عنہ بیان کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سیدنا علی رضی اللہ عنہ سے فرماتے ہوئے سنا: ”تمہارا میرے ہاں وہی مقام ہے جو ہارون علیہ سلام کا موسی علی سلام کے ہاں مقام ہے، البتہ یہ کہ میرے بعد کوئی نبی نہیں۔“ اس حدیث کو زہری سے صرف ابن ابی ذئب نے اور ابن ابی ذئب سے صرف ابن ابی فدیک نے روایت کیا۔ اس میں احمد بن عیسی العلوی کا تفرد ہے۔","",{"k":"صحیح بخاری، غزوة تبوك (٤٤١٦)، صحيح مسلم، عنه (٢٤٠٤)۔"}],[5846,"سیدنا عبداللہ ابن عباس رضی جا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اے اللہ! ہمارے خلفا پر رحم فرما: ”ہم نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم کے خلفاء کون ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ جو میرے بعد آئیں گے، وہ میری احادیث اور میری سنت روایت کریں گے اور انہیں لوگوں کو سکھائیں گے۔“ اس حدیث کو زید بن اسلم سے صرف ہشام بن سعد نے اور ہشام سے صرف ابن ابی فدیک نے روایت کیا۔ اس میں احمد بن عیسی العلوی کا تفرد ہے۔ ٥٨٤٧","",{"k":"مجمع الزوائد (١/١٢٩)، مجمع البحرين (٢٠٤)، سلسلة ضعيفه (٨٥٤)، اسناده ضعیف۔"}],[5847,"سیدنا ابو بردہ بن ابی موسی نے بیان کیا، میں سیدنا معاویہ بن ابی سفیان رضی اللہ عنہ کے پاس گیا، ان کی پشت پر ایک پھوڑا تھا، وہ اس سے بہت سخت تکلیف محسوس کر رہے تھے۔ میں نے کہا: کیا یہ ساری تکلیف اسی کی وجہ سے ہے؟ انہوں نے فرمایا: میں یہ پسند نہیں کرتا کہ یہ تکلیف نہ ہو! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس مسلمان کو جسم میں کوئی تکلیف پہنچتی ہے تو وہ اس کی خطاؤں کا کفارہ بن جاتی ہے اور یہ بہت زیادہ تکلیف ہے۔“ اس حدیث کو طلحہ بن بیٹی سے صرف یونس بن بکیر نے روایت کیا اور معاویہ سے اسےصرف ابو بردہ نے روایت کیا۔ نان مذکورہ حدیث سے معلوم ہوا کہ مومن کو تکلیف پہنچنے کی وجہ سے اس کے گناہ معاف ہو جاتے ہیں اور اس کے لیے تکلیفوں میں اجر و ثواب ہے حتی کہ یہ تکلیفیں اس کو جنت میں لے جائیں گی۔","",{"k":"مجمع الزوائد (٢/٣٠١)، مجمع البحرين (١١٦١)۔"}],[5848,"سیدہ عائشہ ریلی نیہا نے بیان کیا، گویا کہ میں رسول اللہ علیم کی مانگ میں خوشبو کی چمک دیکھ رہی ہوں اور آپ ملنے کی تلبیہ پکار رہے ہیں۔ اس حدیث کو اعمش عن مسلم عن مسروق سے صرف زہیر نے روایت کیا، جبکہ ابراہیم کی روایت اسود کے حوالے سے مشہور ہے۔ قائد احرام کے دوران خوشبو استعمال کرنا جائز ہے، تاہم احترام کی تیاری کے وقت غسل کرتے اور لباس بدلتے ہوئے احرام سے پہلے خوشبو لگا لینا سنت ہے۔ اگر اس خوشبو کا رنگ اور اثر حالت احرام میں باقی رہے تو کوئی حرج نہیں ہے۔ ٥٨٤٩","",{"k":"صحيح مسلم (١١٩٠/٤١)، سنن ابن ماجه (٢٩٢٧، ١٢١٩)۔"}],[5849,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے حدیبیہ میں قربانی کے اونٹ میں اپنے اصحاب میں سے سات افراد کو حصہ دار بنایا۔“ ٥٨٥٠","",{"k":"مسلم (١٣١٨)، سنن ابو داود (٢٨٠٩)، سنن ترمذی (٩٠٤)۔"}],[5850,"سیدنا مخارق با اللہ نے بیان کیا، رسول اللہ ٹیم نے فرمایا: ”وہ امت کبھی پاک نہ ہوگی، جس میں کسی ضعیف کو پریشان کیے بغیر اس کا حق نہ دلایا جائے۔‘ اس حدیث کو سماک سے صرف شریک نے روایت کیا۔","",{"k":"مجمع الزوائد (٤/٢٠٠)، مجمع البحرين (٢٥٥٤)، سنن ابن ماجه (٢٤٣٦)، صحيح الجامع الصغير (٢٤٢١)۔","f":"انون مذکورہ حدیث سے معلوم ہوا حاکم وقت کو چاہیے کہ اگر کمزور لوگوں پر ظلم و زیادتی ہو تو وہ ظالموں سے ان کو بدلہ لے کر دے، مظلوم خاندان کی مدد کرے، لیکن افسوس صد افسوس، موجودہ زمانے میں مظلوم کی کوئی بھی سننے والا نہیں، ہر جگہ پر جابر و ظالم کا راج ہوتا ہے۔"}],[5851,"سیدنا عبد اللہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اپنی سواری پر وتر پڑھے۔ اس حدیث کو زہری سے صرف یونس اور یونس سے صرف عبد اللہ بن حارث نے روایت کیا۔ اس میں عبد الرحمن بن یونس کا تفرد ہے۔ ٥٨٥٢","",{"k":"صحیح بخاری (١٠٩٧)، صحیح مسلم (٢٩/٧٠٠)۔"}],[5852,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، انہوں (صحابہ کرام بھی اللی ) نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے اپنی امت میں جن افراد کو نہیں دیکھا، آپ صلی اللہ علیہ وسلم انہیں کس طرح پہچانیں گے؟ آپ سلم نے فرمایا: ”وضو کے آثار سے ان کے اعضاء چمکتے ہوں گے۔‘ اس حدیث کو ابو اسرائیل سے صرف حسن بن حسین نے روایت کیا۔ ٥٨٥٣","",{"k":"مجمع الزوائد (١/٢٢٨)، مجمع البحرين (٣٩٣)۔"}],[5853,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس آدمی کو لایا جائے گا جو دنیا میں لوگوں کی غیبت کیا کرتا تھا۔ اسے کہا جائے گا: اپنے مردہ بھائی کا گوشت کھا جس طرح تو نے اسے زندہ حالت میں کھایا تھا۔ فرمایا: ”وہ اسے کھائے گا، چیخ و پکار کرے گا اور ناگواری محسوس کرے گا۔“ اس حدیث کو موسیٰ بن لیسار سے صرف ابن اسحاق نے روایت کیا۔","",{"k":"مجمع الزوائد (٩٥/٨)، مجمع البحرين (٤٩٦٢)۔","f":"مذکورہ روایت میں محمد بن اسحاق مدلس ہے۔ تاہم ارشاد باری تعالیٰ ہے: يَأْيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَاتَّقُوا اللَّهَ إنَّ اللهَ تَوَّابٌ رَحِيمٌ ﴾ (الحجرات: ١٢) ”اے ایمان والو! بدگمانیوں سے بچو بے شک بدگمانیاں گناہ ہیں اور بھید نہ ٹولا کرو اور نہ تم میں سے کوئی کسی کی غیبت کرے، کیا تم میں سے کوئی بھی اپنے مردہ بھائی کا گوشت کھانا پسند کرتا ہے؟ تم کو: اس سے گھن آئے گی اور اللہ سے ڈرتے رہو، بے شک اللہ تو بہ قبول کرنے والا مہربان ہے۔“"}],[5854,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جہنمیوں کی دو قسمیں ایسی ہیں جنہیں میں نے تک ابھی دیکھا نہیں ایسے افراد کہ ان کے پاس گائے کی دموں کی طرح کوڑے ہوں گے وہ ان کے ساتھ لوگوں کو ماریں گے اور وہ عورتیں جو لباس پہن کر بھی عریاں ہوں گی، برائی کی طرف مائل ہونے والیاں اور مائل کرنے والیاں، ان کے سروں پر بختی اونٹوں کی کوہانوں کی طرح جوڑے ہوں گے، وہ جنت میں داخل ہوں گی، نہ اس کی خوشبو پائیں گی۔ اس حدیث کو زیاد بن خیثمہ سے صرف زہیر نے روایت کیا۔","",{"k":"مسلم (٢١٢٨)۔"}],[5855,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مرد کسی دوسرے مرد کے جسم کے ساتھ جسم لگائے نہ عورت کسی دوسری عورت کے جسم کے ساتھ جسم لگائے۔‘‘ اس حدیث کو محمد ابن: سیرین سے صرف ہشام نے اور ہشام سے صرف ابوبکر نے روایت کیا۔ اس میں احمد بن یونس کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠٢٨)، مجمع البحرين (٣١٧٤)۔"}],[5856,"سیدنا عبداللہ ابن عم رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص جمعہ کے لیے آئے تو وہ غسل کرے۔ اس حدیث کو فضیل بن عیاض، عن ابی لیلی اور عبید اللہ بن عمر سے مقرون سے صرف احمد بن یونس نے روایت کیا۔ ٥٨٥٧","",{"k":"صحیح بخاری (٨٩٤، ١٨)۔"}],[5857,"سیدنا عبد اللہ رضی اللہ عنہ نے بیان کیا، ایک یہودی عالم نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے کہا: محمد ملے یا کہا: ابو القاسم! اللہ عز وجل قیامت کے دن آسمانوں کو ایک انگلی پر تھام لے گا، پہاڑوں اور درختوں کو ایک انگلی پر تھام لے گا، پانی اور مٹی کو ایک انگلی پر اور باقی ساری مخلوق کو ایک انگلی پر، پھر وہ انہیں ہلائے گا اور کہے گا: میں بادشاہ ہوں، میں بادشاہ ہوں، رسول اللہ لے لیے اس یہودی عالم کی بات پر ہنس دیے اور اس کی تصدیق کے لیے یہ آیت: ”انہوں نے اللہ کی اس طرح قدر نہ کی جس طرح اس کی قدر کرنے کا حق تھا، قیامت کے دن ساری زمین اس کے قبضے میں ہوگی اور آسمان اس کے دائیں ہاتھ پر لیٹے ہوں گے، پاک ہے وہ اور بلند ہے اس سے جو وہ بیان کرتے ہیں تلاوت فرمائی۔“ اس حدیث کو فضیل بن عیاض سے صرف احمد بن یونس اور یحیی بن القطان نے روایت کیا۔","",{"k":"١٠١١ ويحيى بْنُ الْقَطَّان . صحیح بخاری، صحیح مسلم (٢٧٨٦، ٦٦٧، ١٨٧٤، ١٣٣١)۔"}],[5858,"سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب رات کو تہجد کے لیے اٹھتے تو آپ مالے علایم مسواک سے اپنا منہ صاف کیا کرتے تھے۔ اس حدیث کو فضیل بن عیاض سے حصین اور منصور سے اکٹھا صرف احمد بن یونس نے روایت کیا۔ خاندان مذکورہ حدیث سے معلوم ہوا کہ سو کر اٹھ کر مسواک کرنا مسنون ہے کیونکہ جب انسان نیند سے بیدار ہوتا ہے تو منہ کا ذائقہ بدلا ہوتا ہے۔ اس لیے رسول اللہ صلی اللہ علیہ وسلم رات کو بیدار ہونے کے بعد خوب مسواک فرماتے تھے۔ ٥٨٥٩","",{"k":"صحیح بخاری، صحیح مسلم (٤٧/٢٢٥)، سنن ابو داؤد (٥٥)۔"}],[5859,"- سیدنا نعیم بن دجاجہ نے بیان کیا، سیدنا علی فی اللہ نے سیدنا ابو مسعود بنی اللہ سے کہا: آپ کہتے ہیں: (موجودہ) لوگوں میں سے سو سال بعد کوئی زندہ نہ رہے گا؟ آپ نے فرمایا: ”موجودہ زندہ لوگوں میں سے سو سال بعد کوئی زندہ نہیں رہے گا اور اس امت کی خوش حالی اور آسودگی سو سال بعد ہے۔“ اس حدیث کو فضیل بن عیاض سے صرف احمد بن یونس نے روایت کیا۔","",{"k":"مجمع الزوائد (١/٢٠١)، مجمع البحرين (٣٢٠)، اسناده حسن۔","f":"شیخ البانی اللہ لکھتے ہیں، مذکورہ حدیث مبارکہ کا مطلب یہ ہے کہ جو اس وقت روئے زمین پر موجود تھے ان کی زندگی سو برس تک ختم ہو جائے گی۔ اس کا مطلب یہ نہیں کہ سوسال کے بعد قیامت آ جائے گی۔سیدنا عبد اللہ بن عمر رضی اللہ عنہما کہتے ہیں: نبی مکرم لئے علیم نے اپنی زندگی کے آخری ایام میں ہمیں نماز عشا پڑھائی، سلام پھیرنے کے بعد فرمایا: کیا خیال ہے تمہارا اس رات کے بارے میں جو آج زمین کی پشت پر موجود ہے؟ وہ سو برس تک باقی نہیں رہے گا۔ حافظ ابن حجر جماللہ نے فرمایا: کہ سیدنا جابر ضیا اللہ کی روایت میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے یہ بات اپنی وفات سے ایک ماہ قبل ارشاد فرمائی۔ (فتح الباری: ١/ ٢٨٢) ایسا ہی ہوا کہ نبی معظم نے ان کا آخری صحابی سیدنا ابوطفیل عامر بن واثله فضل الله سوسال کے بعد ١١٠ ہجری میں فوت ہوئے۔ ٥٨٦٠"}],[5860,"سیدنا عبد اللہ ابن عباس نیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” اولاد کی خوشبو جنت کی خوشبو میں سے ہے۔ اس حدیث کو عبید اللہ بن عبد اللہ سے صرف عبدالمجید نے اور عبدالمجید سے صرف مندل بن علی نے روایت کیا۔ ٥٨٦١","",{"k":"مجمع الزوائد (١٥٦/٨)، ضعيف الجامع الصغير (٣١٤٥)، مجمع البحرين (٢٨٧٤)، سلسة ضعيفه (٢٤٩٩)، اسناده ضعيف۔"}],[5861,"سیدنا سمرہ بن جندب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہ مسائل (مانگنا) تو ایک تکلیف ہے، جس کے ذریعے آدمی اپنے آپ کو تکلیف میں ڈالتا اور بے آبرو کرتا ہے، اب جو چاہے اپنے چہرے پر باقی رکھے اور جو چاہے ترک کر دے، اگر آدمی نے ضرور ہی سوال کرنا ہوتو وہ صاحب اختیار سے سوال کرے۔ اس حدیث کو فضیل بن عیاض سے صرف احمد بن یونس نے روایت کیا۔","",{"k":"سنن ابو داؤد (١٦٣٩)، سنن ترمذی (٦٨١)، قال الشيخ الالباني: صحيح۔","f":"اد مذکورہ حدیث سے معلوم ہوا کہ مانگنا ذلت و رسوائی ہے۔ مذکورہ حدیث میں سوال کرنے سے نفرت دلائی گئی ہے۔ مذکورہ حدیث میں ہے کہ وہ بادشاہ سے مانگے، اس کا مطلب ہے کہ اگر وہ مستحق ہے تو بیت المال کی طرف رجوع کرے، جو ایک اسلامی مملکت میں اس مقصد کے لیے ہوتا ہے کہ اس سے ضرورت مندوں کی آبرومندانہ کفالت کا اہتمام کیا جا سکے، اگر وہاں تک رسائی نہ ہو تو ناگزیر حالات میں دوسروں سے بھی سوال کرنا جائز ہے۔ ٥٨٦٢"}],[5862,"سیدنا ابو ذر رضی اللہ عنہ نے بیان کیا، میں مسجد میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا تو آ۔ ما علیم نے فرمایا: ” دیکھ تیری نظر میں کون شخص زیادہ بلند ہے؟ میں نے دیکھا کہ ایک آدمی ہے جس نے جوڑا پہن رکھا ہے اور اس کے ارد گرد لوگ ہیں، میں نے کہا: یہ آدمی، آپ صلی اللہ علیہ وسلم نے فرمایا: ''دیکھ، تیری نظر میں کون سا شخص ادنی ہے۔“ میں نے ایک آدمی دیکھا اس پر ایک چادر تھی، میں نے عرض کیا، یہ آدمی، آپ ملت علی ایم نے فرمایا: ”یہ (چادر والا شخص قیامت کے دن اللہ کے ہاں اس (جوڑے سوٹ والے ) جیسے زمین بھر لوگوں سے ہے۔“ یہ حدیث فضیل بن عیاض سے صرف احمد بن یونس نے روایت کیا۔ اندن صیح بخاری میں بھی اسی طرح کی ایک روایت ہے کہ ایک آدمی گزرا، رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس بیٹھے ہوئے آدمی سے فرمایا: تیری اس شخص کے بارے میں کیا رائے ہے؟ اس نے کہا: ( یہ ) معزز لوگوں میں سے ہے، ایک اور گزرا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے پھر پوچھا: اس کے بارے میں تیری کیا رائے ہے؟ اس نے کہا: اللہ کے رسول! اس شخص کا تعلق فقراء المسلمین سے ہے، فرمایا: یہ فقیر پہلے شخص جیسے دنیا بھر کے آدمیوں سے بہتر ہے۔ (صحیح بخاری شریف، حدیث نمبر: ٥٠٩١) مذکورہ بالا احادیث سے معلوم ہوا کہ اللہ ذوالجلال کے ہاں اہمیت و فضیلت ایمان اور تقویٰ کی ہے نہ کہ مال و دولت شان و شوکت، ذات و برادری اور نام و نسب کی۔ یہ بھی معلوم ہوا کہ تقویٰ والا آدمی دنیا بھر کے ان انسانوں سے بہتر ہے جو ایمان و تقویٰ سے محروم ہیں۔ اللہ ذوالجلال فرماتے ہیں: إنَّ اكْرَمَكُمْ عِنْدَ اللهِ أَتْقَاكُمْ ﴾ (الحجرات: ١٣) اللہ کے نزدیک تم میں سے سب سے زیادہ عزت والا وہ ہے جو تم میں سے سب سے زیادہ ڈرنے والا ہے۔“ ٥٨٦٣","",{"k":"مجمع الزوائد (١٠/٢٦٥)، مجمع البحرين (٠٤٩٥٠٤٩)، مسند احمد ه / ١٧٠، اسناده صحيح۔"}],[5863,"سيدنا عبداللہ ابن عباس فضا النجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کی روح قبض کی گئی جبکہ آپ صلی اللہ علیہ وسلم کی زرہ تھیں صاع ( تقریباً ستر کلو ) جو کے عوض میں ایک یہودی شخص کے ہاں گروی تھی، آپ نے انہیں اپنے گھر والوں کے کھانے کے لیے لیا تھا۔ اس حدیث کو فضیل سے احمد بن یونس نے روایت کیا۔ ناندن (١) مذکورہ حدیث سے معلوم ہوا کہ غیر مسلم سے ادھار وغیرہ کا معاملہ کرنا درست ہے، (٢) یہ بھی معلوم ہوا کہ نبی اکرم صلی اللہ علیہ وسلم مختار کل نہ تھے۔","",{"k":"سنن ترمذى (١٢١٤)، سنن ابن ماجه (٢٢٣٩)، قال الشيخ الالباني صحيح۔"}],[5864,"سیدنا عبد اللہ بن معقل رضی اللہ عنہ نے بیان کیا، میں نے اپنے والد کو عبد اللہ فی لینے سے کہتے ہوئے سنا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: ”ندامت تو بہ ہے؟“ انہوں نے فرمایا: ’ہاں۔‘ اس حدیث کو سیدنا ابوسعید خدری رضی اللہ عنہ سے صرف ابو بکر بن عیاش نے روایت کیا، اس میں احمد بن یونس کا تفرد ہے۔","",{"k":"سنن ابن ماجه كتاب الزهد (٤٢٥٢)، قال الشيخ الالباني: صحيح۔"}],[5865,"سیدنا ابو سعید خدری رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو سنانے کے لیے کوئی عمل کرتا ہے اللہ اسے سنا دے گا اور جو دکھانے کے لیے کوئی عمل کرتا ہے تو اللہ اسے دکھا دے گا ( اور وہ عمل کرنے والا اجر سے محروم رہے گا۔ اس حدیث کو فراس سے صرف شیبان نے روایت کیا۔ اس میں معاویہ بن ہشام کا تفرد ہے۔ ٥٨٦٦","",{"k":"سنن ترمذی (٢٣٨١)۔"}],[5866,"سیدنا یحی بن سعید ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ سے فرمایا: ” تمہارا میرے ہاں وہی مقام ہے جو ہارون علینا) کا موسی علی نام کے ہاں مقام و مرتبہ ہے، لیکن میرے بعد کوئی نبی نہیں۔“ اس حدیث کو روایت نہیں کیا","",{"k":"معجم كبير (١/١٤٦)، مجمع الزوائد (٩/١١٠)۔"}],[5867,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”تم میں سے جو شخص جمعہ پڑھنے آئے تو وہ غسل کرے۔“ اس حدیث کو زائدہ کے حوالے سے ابو اسحاق الشیبانی سے صرف الولید بن عقبہ نے روایت کیا۔ اس میں عبد العزیز کا تفرد ہے۔","",{"k":"کر تقدم تخريجه (١٨)۔"}],[5868,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں نے یعنی: نبی نے کیم کو سینگوں والے دو چتکبرے مینڈھے ذبح کرتے ہوئے دیکھا، آپ صلی اللہ علیہ وسلم اپنا پاؤں ان کے پہلوؤں پر رکھے ہوئے تھے اور ((بسم الله الله اکبر )) پڑھتے تھے۔ اس حدیث کو الحسن بن صالح سے صرف مصعب بن المقدام نے روایت کیا۔","",{"k":"صحیح بخاری، صحیح مسلم کتاب الاضاحی (١٩٦٦)۔","f":".. عید قربان کے موقع پر صاحب استطاعت کو کم از کم ایک بکری، مینڈھا گائے یا اونٹ کے ایک حصے کی قربانی کرنا ضروری ہے۔ مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ اگر اللہ ذوالجلال نے استطاعت دی ہے تو ایک سے زیادہ بھی قربانیاں کرنا جائز ہے، (٢) معلوم ہوا کہ قربانی کا جانور موٹا تازہ اور خوبصورت ہونا چاہیے۔ (٣) ذبح کرتے وقت جانور کے جسم پر پاؤں رکھنے کا مقصد یہ ہے کہ جانور قابو میں رہے اور بھاگنے کی کوشش نہ کرے۔ معلوم ہوا کہ قربانی کے جانور کو ذبح کرتے وقت بسم الله، اللہ اکبر پڑھنا چاہیے۔"}],[5869,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ اسے علم کو فرماتے ہوئے سنا: \"جو شخص جمعہ پڑھنے آئے تو وہ غسل کرے۔“ اس حدیث کو ابو اسحاق شیبانی سے صرف ولید نے روایت کیا۔ اس میں عبد العزیز کا تفرد ہے۔ اور معایہ بن عمرو وغیرہ نے اپنے والد کے حوالے سے اسے ابو اسحاق السبیعی سے روایت کیا ہے۔ ٥٨٧٠","",{"k":"معجم کبیر طبرانی (٨/١١)۔"}],[5870,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”میرے اہل بیت کی مثال نوح نائی نام کی کشتی کے مانند ہے، جو اس میں سوار ہو گیا وہ بچ گیا اور جو اس سے پیچھے رہا وہ غرق ہو گیا اور میرے اہل بیت کی تم میں مثال اس طرح ہے جس طرح بنی اسرائیل میں باب حطہ کی ہے، جو اس میں داخل ہو گیا وہ بخشا گیا۔ اس حدیث کو ابوسلمہ الصائغ سے صرف عبد الرحمن بن ابی حماد نے روایت کیا، اس میں عبد العزیز بن محمد بن ربیعہ کا تفرد ہے۔ ٥٨٧١","",{"k":"مجمع الزوائد (١٧١/٩)۔"}],[5871,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فتح مکہ کے دن فرمایا: ”یہ ہے جس کا میرے رب نے میرے ساتھ وعدہ فرمایا تھا۔ پھر آپ صلی اللہ علیہ وسلم نے سورۃ النصر تلاوت فرمائی اور فرمایا: ”جب لوگ جوق در جوق اللہ کے دین میں داخل ہوں اور اللہ کا دین تمام ادیان پر غالب آ جائے تو لوگ بہتر اور ہم بھی بہتر “ اس حدیث کو ابو خالد الدالانی سے صرف عبد السلام بن حرب نے روایت کیا۔ اس میں یحیی بن آدم کا تفرد ہے۔ ٥٨٧٢",""],[5872,"سیدنا ابو ہریرہ فی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے افراد کی عمریں ساٹھ اور ستر سال کے درمیان ہیں۔ “ اور نبی صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے کم لوگ ہی ستر سال کے ہوں گے۔ اس حدیث کو کامل بن العلاء سے صرف محمد بن ربیعہ الکلابی نے روایت کیا۔ ناند مذکورہ حدیث میں امت محمدیہ کی عمروں کا تذکرہ ہے کہ گذشتہ امتوں میں لوگوں کی عمریں بہت لمبی ہوتی تھیں لیکن اس امت کی عمریں بہت مختصر ہیں، اس لیے اس مختصر سی عمر میں زیادہ سے زیادہ نیکیاں کرنی چاہیں۔ بخاری شریف میں ہے، رسول اللہ سے تم نے فرمایا: اللہ تعالیٰ نے اس آدمی کے لیے کوئی عذر باقی نہیں چھوڑا جس کی موت کو اتنا مؤخر کر دیا کہ وہ ساٹھ سال کو پہنچ گیا۔ (صحیح بخاری، رقم: ٦٤١٩) معلوم ہوا کہ ساٹھ سال کے آدمی قریب پہنچ جائے تو زیادہ آخرت کی طرف توجہ کرنی چاہیے، لیکن ساٹھ سال سے کم عمر والے اپنے لیے کسی قسم کی گنجائش نہ سمجھیں۔ یہ بھی معلوم ہوا کہ کم ہی ایسے لوگ ہوں گے جن کی عمریں ستر سال سے زیادہ ہوں گی، اس صراحت میں بعض صحابہ کرام بھی نہیں کی عمریں بہت زیادہ تھیں، سیدہ اسماء بنت ابو بکر بنی اٹھا نے (١٠٠) سال، سیدنا انس رضی اللہ عنہ نے سال، سیدنا حسان رضی اللہ عنہ نے سال، سیدنا سلمان فارسی رضی اللہ عنہ نے سال عمر پائی۔ ٥٨٧٣","",{"k":"سنن ترمذی (٣٥٥٠)، قال الشيخ الالباني: حسن۔"}],[5873,"سیدنا عبد الله بن عتبہ ضیا المیہ نے بیان کیا، جب ابن مسعود رضی اللہ عنہ بن مسعود ) الله فوت ہوئے تو سیدنا عبد اللہ بن مسعود نیل الیہ ان پر روئے۔ انہوں نے ان سے کہا: آپ روتے ہیں؟ انہوں نے فرمایا: ہاں، وہ میرے نسبی بھائی، رسول اللہ صلی اللہ علیہ وسلم کے ساتھ میرے ساتھی اور سیدنا عمر بن خطاب نی اللہ کے علاوہ میرے سب سے زیادہ چہیتے تھے۔ اس حدیث کو عون بن عبد اللہ سے صرف ابو العمیں نے روایت کیا۔ ٥٨٥٧٤","",{"k":"مجمع الزوائد (٢٠٣)، مجمع البحرين (١٢٥٧)۔"}],[5874,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم سے بندروں اور خنزیروں کے بارے میں سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عزوجل جب کسی قوم پر ناراض ہوتا ہے تو وہ ان کی نسل کو باقی نہیں رکھتا۔“ اس حدیث کو ابو خالد الدالانی سے صرف عبد السلام بن حرب نے روایت کیا۔ ٥٨٧٥",""],[5875,"سیدنا ابوموسی ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تین قسم کے لوگوں کو دگنا اجر ملے گا: وہ غلام جو اللہ کے اس پر فرض کیے گئے حق کو ادا کرنے کے ساتھ ساتھ اپنے مالکوں کا حق ادا کرتا ہے، پس اسے قیامت کے دن اس کا دگنا اجر دیا جائے گا، ایک وہ آدمی جس کی خوبصورت لونڈی ہو، وہ اس کی بہترین تربیت کرے، پھر اسے آزاد کر دے اور پھر اللہ کی رضا کی خاطر اس سے شادی کر لے تو اس کو بھی دگنا اجر دیا جائے گا، ایک وہ آدمی جو کتاب اول پر ایمان لایا اور پھر دوسری کتاب آئی تو وہ اس پر بھی ایمان لایا تو اسے بھی دگنا اجر دیا جائے گا۔“","",{"k":"وَرَجُلٌ آمَنَ بِالْكِتَابِ الْأَوَّلِ، ثُمَّ جَاءَ الْكِتَابُ الْآخِرُ فَآمَنَ بِهِ، فَذَلِكَ يُؤْتَى أَجْرَهُ مَرَّتَيْنِ)) صحیح بخاری (٣٠١١)، صحیح مسلم (١٥٤)۔"}],[5876,"سیدنا جریر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب غلام دشمن کے ملک میں چلا جائے تو اس کا خون (قتل کرنا ) حلال ہو جائے گا۔“ اس حدیث کو ابو اسحاق السبیعی سے صرف عبد الرحمن بن حمید نے روایت کیا۔ اس میں اس کے بیٹے حمید بن عبد الرحمن کا تفرد ہے۔: ٥٨٧٧ مذکورہ حدیث میں بھاگ جانے والے غلام کے ساتھ شرعی سلوک کا بیان نہیں ہے۔","",{"k":"کر سنن ابو داود (٤٣٦٠)، سنن نسائی (٤٠٥٦)، مسند احمد: ٤ / ٣٦٥ قال شعیب الارناؤط : حديث صحيح۔"}],[5877,"سیدنا عبداللہ ابن عباس ریلی لا سے روایت ہے کہ ایک عورت نے نبی صلی اللہ علیہ وسلم اپنے والد کے بارے میں دریافت کیا جو کہ حج کیے بغیر فوت ہو گیا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے والد کی طرف سے حج کر۔“ اس حدیث کو ایوب سے صرف حماد بن زید نے روایت کیا، اس میں حمید بن عبد الرحمن الرؤاسی کا تفرد ہے۔ ٥٨٧٨","",{"k":"الرُّوَاسِيُّ . لم سنن نسائی (٢٦٣٤)، قال الشيخ الالباني: صحيح۔"}],[5878,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: کسی مومن کے دل میں بخل اور ایمان کبھی اکٹھے نہیں ہو سکتے۔“ اس حدیث کو محمد بن عمرو سے صرف یحی بن یمان نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ مومن کنجوس نہیں ہو سکتا۔ بخل یہ ہے کہ واجب اور فرض اخراجات ادا نہ کرے اور جو واجبات ادا کرتا جائے وہ بخیل نہیں ہے تو بخل کرنا مومن کی صفت نہیں، کیونکہ جس کے دل میں بخیلی نے گھر کر لیا اس کے دل میں ایمان کے رہنے کی گنجائش ہی نہیں رہتی۔ ٥٨٧٩","",{"k":"سنن نسائی، رقم: يرو ٣١١٠، اسناده صحیح، مجمع البحرين (١١٧)، ادب المفرد (٢٨١)۔"}],[5879,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس سے مشورہ کیا جاتا ہے وہ امین ہوتا ہے۔“ اس حدیث کو عبد الملک بن عمیر سے صرف قیس نے روایت کیا۔ اس میں ہارون میں ابی بردہ کا اپنے بھائی سے تفرد ہے۔","",{"k":"مجمع الزوائد (١٠٠/٨)، صحيح الجامع الصغير (٦٧٠٠)، سنن ابو داود (٥١٢٨)، مجمع البحرين (٣١٢٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جس سے مشورہ لیا جائے وہ ایسے ہے جیسے اس کے پاس امانت رکھی گئی ہے اور جس طرح امانت میں خیانت جائز نہیں اسی طرح کسی کو غلط مشورہ دینا بھی جائز نہیں، کیونکہ مشورہ لینے والے اس پر اعتماد کر کے اس کے سامنے اپنے حالات رکھتے ہیں تو مشورہ دینے والے کے لیے جائز نہیں کہ اس کے راز کی باتوں کو دوسرے تک پہنچائے کیونکہ راز فاش کرنا خیانت ہے اور خیانت منافق کی علامت ہے۔ ٥٨٨٠"}],[5880,"سیدنا زید بن ثابت رضی اللہ عنہ بیان کرتے ہیں، رسول اللہ صلی اللہ علیہ وسلم پر جب وحی نازل ہوتی تھی تو آپ صلی اللہ علیہ وسلم پر گراں ہوتی تھی اور آپ ملنے سے یمن کی پیشانی سے موتیوں کی طرح پسینہ گرتا تھا۔“ اس حدیث کو زہری سے صرف عثمان بن عبد الرحمن نے روایت کیا۔ اس میں یونس بن بکیر کا تفرد ہے۔ نان ایک دوسری حدیث میں ہے کہ سیدہ عائشہ نیا نیا کہتی ہیں: سیدنا حارث بن ہشام رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم سے سوال کیا کہ آپ صلی اللہ علیہ وسلم پر وحی آنے پر کیا کیفیت ہوتی ہے؟ آپ ملنے ہیم نے فرمایا: ” کبھی تو وہ گھنٹی کی گونج کی طرح آتی ہے اور یہ کیفیت مجھ پر بڑی گراں گزرتی ہے جب یہ کیفیت ختم ہوتی ہے تو میں وہ وحی یاد کر چکا ہوتا ہوں اور بسا اوقات ایسے بھی ہوتا ہے کہ میرے پاس فرشتہ انسانی شکل میں آتا ہے۔ پھر جو کچھ وہ کہتا ہے: میں یاد کر لیتا ہوں۔“ ٥٨٨١","",{"k":"معجم کبیر طبرانی (٢١/٥)، صحيح الجامع الصغير (٤٧٩٢)، سلسله صحیحه، رقم: ٢٠٨٨ . فائدة۔"}],[5881,"ابو وائل نے بیان کیا، سیدنا عبد اللہ ضیا اللہ نے بیان کیا، مجھے تمہارے بیٹھنے کا بتا دیا جاتا ہے، بس اس اندیشے کے پیش نظر کہ میں کہیں تمہیں اکتا نہ دوں تمہارے پاس نہیں آتا۔ بے شک رسول اللہ صلی اللہ علیہ وسلم ہمارے اکتائے جانے کو ناپسند کرتے ہوئے ہمیں وعظ و نصیحت کرنے میں ناغہ اور توقف کیا کرتے تھے۔ اس حدیث کو اعمش کے حوالے سے عمرو بن مرہ سے صرف علی بن مسہر نے روایت کیا۔ اس میں منجاب بن الحارث کا تفرد ہے۔: ٥٨٨٢","",{"k":"صحیح بخاری کتاب الدعوات، صحیح مسلم (٢٨٢١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ وعظ ونصیحت روزانہ نہیں بلکہ وقفے سے کرنی چاہیے۔"}],[5882,"سیدنا عبد اللہ فی اللہ نے فرمایا: رسول اللہ ملے عام یہ دعا کیا کرتے تھے: ”اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاک دامنی اور بے نیازی و تو نگری کا سوال کرتا ہوں۔“ اس حدیث کو ذکریا بن ابی زائدہ سے صرف محمد بن مسروق نے روایت کیا۔ ان مذکورہ دعا بڑی جامع ہے۔ ہدایت کا مطلب، خیر کی طرف راہنمائی ہے، جس کی ہر وقت","",{"k":"صحيح مسلم (٢٧٢١)، سنن ابن ماجه (٣٨٣٢)، سنن ترمذی (٣٤٨٩)۔","f":"انسان کو ضرورت رہتی ہے، پھر اس پر استقامت اختیار کرنا بھی ہدایت کے مفہوم میں شامل ہے۔ (٢) تقوی، اللہ کا ڈر جو نیکی کا سب سے اہم سبب اور گناہوں سے بچنے کا ایک بڑا ذریعہ ہے۔ (٣) عفاف کا مطلب یہ ہے کہ، تمام خواہشات شریعت کے تابع ہو جائیں اور گناہوں سے بچنے کو بھی کہتے ہیں۔ (٤) غنی سے مراد نفس کا غنی ہے اور لوگوں کے مال و دولت سے بے نیاز رہنا اور اس کی طمع نہ کرنا، بلکہ ساری امیدیں صرف ایک اللہ ہی سے وابستہ کرنا۔ ٥٨٨٣"}],[5883,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص دو حرم: مکہ یا مدینہ میں سے کسی ایک حرم میں فوت ہو جائے تو وہ امن اور ایمان کے ساتھ دوبارہ زندہ کر کے اٹھایا جائے گا۔“ اس حدیث کو ابوالزبیر سے صرف عبد اللہ بن المؤمل نے روایت کیا۔ اس میں زید بن الحباب کا تفرد ہے۔ ٥٨٨٤","",{"k":"مجمع الزوائد (٢/٣١٩)، مجمع البحرين (١٢١٧)، اسناده ضعيف۔"}],[5884,"سیدنا عبداللہ ابن عباس ولی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر مومن میں ایک گناہ رہتا ہے جسے وہ وقتاً فوقتاً کرتا رہتا ہے، مومن بہت بھول جانے والا ہے، جب اسے یاد کرایا جائے تو یاد کر لیتا ہے۔ اس حدیث کو ابو بشر سے صرف ابو معاذ اور وہ سلیمان بن ارقم ہیں نے روایت کیا ہے۔ فائد مذکورہ حدیث سے معلوم ہوا کہ مسلمان مومن سے بسا اوقات بتقاضہ بشریت لغزش ہو جاتی ہے کیونکہ خُلِقَ الْإِنسَان ضَعِيفًا لیکن اس کا امتیاز اس میں ہے کہ وہ غلطی کرنے کے بعد تو بہ کرے، جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا، آدم کی تمام اولاد بہت خطا کرنے والی ہے اور بہت خطا کرنے والوں میں سب سے بہتر بہت زیادہ تو بہ کرنے والے ہیں۔ (سنن ترمذی: ٢٤٩٩، سنن ابن ماجه: ٤٢٥١، اسناده حسن) اور جب مومن بھولتا ہے تو اس کے خیر خواہ اس کو وعظ ونصیحت کریں تو وہ فوراً ان کی نصیحت قبول کر لیتا ہے۔ ٥٨٨٥","",{"k":"مجمع الزوائد (١٠/٢٠٤)، صحيح الجامع الصغير (٥٧٣٥)، سلسله صحيحه (٢٢٧٦)، مجمع البحرين (٤٧٢٢)۔"}],[5885,"سیدنا عویم بن ساعدہ انصاری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے قبا والوں سے فرمایا: ”میں اللہ سے سنتا ہوں کہ اس نے پاکیزگی کے بارے میں تمہاری تعریف کی ہے تو وہ پاکیزگی کیا ہے؟ انہوں نے عرض کیا: اللہ کے رسول! اللہ کی قسم! ہم تو بس یہی جانتے ہیں کہ ہمارے پڑوسی یہود ہیں، ہم نے انہیں دیکھا کہ وہ بول و براز کے بعد اپنی پیٹھ دھوتے ہیں، تو جس طرح انہوں نے ( پیٹھ کو ) دھویا اسی طرح ہم نے دھویا۔“ یہ حدیث عویم بن ساعدہ رضی اللہ عنہ لینے سے صرف اس اسناد سے مروی ہے۔ اس میں ابواولیس کا تفرد ہے۔ اہل قبا کے متعلق اللہ ذوالجلال نے یہ آیت نازل فرمائی: فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَ اللَّهُ يُحِبُّ الْمُطَّهِّرِينَ ﴾ (التوبه: ١٠٨) کیونکہ یہ پانی کے ساتھ استنجا کرتے تھے۔ پیچھے حدیث گزر چکی ہے کہ رسول اللہ علیم نے ڈھیلوں کے: ٥٨٨٦ ساتھ استنجا کیا تھا، ڈھیلوں کے ساتھ استنجا کرنا جائز ہے تاہم افضل یہ ہے کہ پانی استعمال کیا جائے","",{"k":"مجمع الزوائد (١/٢١٤)، ارواء الغليل (١/٨٥)، مسند احمد (٤٢٢/٣)، مجمع البحرين (٣٥٧)، حدیث حسن لغيره۔"}],[5886,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، نبی لیے علم کی خدمت میں بھنا ہوا پرندہ پیش کیا گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! تیری مخلوق میں سے جو تجھے سب سے زیادہ محبوب ہے، اسے میرے پاس بھیج دے تا کہ وہ بھی میرے ساتھ اس پرندے میں سے کھائے۔ پس سیدنا علی رضی اللہ عنہ آئے، جب رسول اللہ تم نے انہیں دیکھا تو فرمایا: ”رب جی! وہ میرا دوست ہے۔“ اس حدیث کو الحسین بن الحکم سے صرف مفضل بن صالح نے روایت کیا۔ اس میں محمد بن طریف کا تفرد ہے۔","",{"k":"کر سنن ترمذی (٣٧٢١)، قال الشيخ الالبانی: ضعیف، انظر (١٧٤٤)۔"}],[5887,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” آدمی پر اس کے غلام اور اس کے گھوڑے میں صدقہ فطر کے علاوہ اور کوئی صدقہ نہیں۔“ اس حدیث کوموسی بن عقبہ سے صرف عبد السلام بن مصعب نے روایت کیا۔","",{"f":"مذکورہ حدیث سے معلوم ہوا کہ غلام اور گھوڑے پر زکوۃ نہیں۔ مذکورہ حدیث میں جو ہے اس میں غلام اور گھوڑے سے مراد وہ ہیں جو انسان نے اپنی خدمت اور سواری کے لیے مخصوص کیے ہوئے لیکن اگر تجارت کے لیے رکھا ہو تو پھر ان میں بھی تجارتی مال ہونے کی حیثیت سے زکاۃ لازم ہو گی، دوسری صحیح احادیث نه ده میں ہے کہ صرف غلام سے زکاۃ لی جائے گی۔ شیخ عبد اللہ ہمالہ نے بھی فرمایا، غلام سے صدقۃ الفطر لیا جائے گا، خواہ وہ خدمت کے لیے ہو یا تجارت کے لیے۔ ( توضیح الاحکام: ٣١٢/٣) جو مذکورہ بالا حدیث میں ہے کہ صدقہ فطر گھوڑے پر ہے یہ راوی کا اضافہ معلوم ہوتا ہے۔ ٥٨٨٨"}],[5888,"سیدہ عائشہ علی الہا نے بیان کیا، بسا اوقات رسول اللہ صلی اللہ علیہ وسلم مجھے بوسہ دیتے تھے، جبکہ آپ ملے عام روزے کی حالت میں ہوتے تھے۔ اس حدیث کو حبیب بن حسان سے صرف علی بن ہاشم نے روایت کیا۔","",{"k":"صحیح بخاری (١٩٢٨)، صحیح مسلم (١١٠٦)۔"}],[5889,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علی کی نماز مغرب کو نماز عشا کے لیے مؤخر کرتے تھے نہ کسی اور کے لیے مؤخر کرتے تھے۔ اس حدیث کو جعفر بن محمد سے صرف محمد بن میمون الزعفرانی نے روایت کیا۔ اند. ابو داؤد میں روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کھانے یا کسی اور وجہ سے نماز کو","",{"k":"سنن ابو داود (٣٧٥٨)، قال الشيخ الالباني: ضعيف۔","f":"مؤخر نہ کیا جائے۔ (سنن ابی داؤد، رقم: ٣٧٥٨)"}],[5890,"سیدنا علی رضی اللہ عنہ نے بیان کیا، ایک بچھو نے نبی الے علم کو ڈس لیا، جبکہ آپ صلی اللہ علیہ وسلم نما ز پڑھ رہے تھے، جب آپ ملے فارغ ہوئے تو آپ مے علیم نے فرمایا: اللہ بچھو پر لعنت فرمائے، وہ کسی نمازی کو چھوڑتا ہے نہ کسی اور کو۔ پھر آپ ملٹے علیم نے پانی اور نمک منگوایا اور آپ صلی اللہ علیہ وسلم اس پر ملنے لگے اور سورۃ الکافرون، سورۃ الفلق اور سورۃ الناس پڑھنے لگے۔ اس حدیث کو مطرف سے صرف ابن فضیل نے روایت کیا۔ اس میں اسماعیل بن موسی کا تفرد ہے۔ نان بعض روایات میں ہے کہ رسول اللہ ملنے کی تم نے فرمایا: ((ما تدع نبيا ولا غيره)) (صحيح الجامع الصغير، رقم: ٥٠٩٩) یہ کسی نبی کو بھی معاف نہیں کرتا۔ مذکورہ حدیث سے معلوم ہوا کہ یہ تینوں سورتیں بچھو کے کاٹنے کا بہترین علاج ہے۔ ابن ابی شیبہ کی روایت میں سورۃ الکافرون کے بجائے سورۃ الاخلاص اور معوذتین کا ذکر ہے ممکن ہے ایک بار سورہ اخلاص پڑھی ہو دوسری بار سورۃ الکافرون پڑھی ہو ) اور یہ بھی وضاحت ہے کہ آپ صلی اللہ علیہ وسلم اس وقت تک پڑھ کر دم کرتے رہے جب تک آرام نہیں آیا۔","",{"k":"معجم صغير :طبرانی (٢/٤٧١، ٨٣١)، مشكاة كتاب الطب (٥٤)، سلسلة صحيحة (٥٤٨)، مجمع الزوائدرقم: ١١١/٥ . فائدة۔"}],[5891,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مومن کا خواب نبوت کے ستر حصوں میں سے ایک حصہ ہے۔ اس حدیث کو ابن سیرین سے صرف عروہ بن عبد اللہ بن قشیر نے روایت کیا۔ اس میں محمد بن عبید اللہ العرزمی کا تفرد ہے۔","",{"k":"شود كتاب الرؤيا، رقم: ٢٢٦٥ . مجمع الزوائد (١٧٤/٧)، مجمع البحرين (٣٣٠٨)، صحیح مسلم۔","f":"امام نووی اللہ نے کہا: بعض روایتوں میں پینتالیس حصوں کا ذکر ہے، بعض میں چھیالیس کا، بعض میں چالیس کا، بعض میں انچاس کا، بعض میں پچاس کا، بعض میں ستر کا، بعض میں چھبیس کا، بعض میں چوالیس کا اور شاید یہ اختلاف خواب دیکھنے والے کی حالت پر ہے، اگر وہ مومن ہے تو اس کا خواب نبوت کے چھیالیس حصوں میں سے ایک حصہ ہے اور فاسق کا ستر حصوں میں سے ایک حصہ ہے اور بعضوں نے کہا: مشکل خواب ستر کا ایک حصہ ہے اور صاف چھیالیس کا۔ ٥٨٩٢"}],[5892,"سیدہ حفصہ رضی شینہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اللہ اور آخرت کے دن پر ایمان رکھنے والی عورت کے لیے حلال نہیں کہ وہ شوہر کے علاوہ کسی اور میت پر تین دن سے زائد سوگ کرے۔ اس حدیث کو عبد اللہ بن دینار سے صرف عبد السلام بن مصعب نے روایت کیا۔",""],[5893,"سیدنا ابو موسی رضی اللہ عنہ سے رایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” آدمی جس کے ساتھ محبت کرتا ہے (قیامت کے دن ) وہ اس کے ساتھ ہو گا۔“ یہ حدیث سیدنا ابو موسی بنی الیہ سے صرف اس اسناد سے صرف اعمش کی روایت سے مروی ہے۔ ٥٨٩٤","",{"k":"صحیح بخاری (٦١٧٠)، صحيح مسلم (١٦٣/٢٦٣٩)۔"}],[5894,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھے پچیس مرتبہ مغفرت کی دعا دی، میں ان سب کو اپنے ہاتھ پر شمار کرتا ہوں۔ انہوں نے کہا: آپ صلی اللہ علیہ وسلم فرماتے: کیا تم نے اپنے والد کا قرض ادا کر دیا ہے؟“ میں کہتا: جی ہاں، آپ صلی اللہ علیہ وسلم فرماتے: ”اللہ تمہاری مغفرت فرمائے۔“ اس حدیث کو سیدنا جابر رضی اللہ عنہ سے صرف شیبان نے روایت کیا۔ اس میں معاویہ بن ہشام کا تفرد ہے۔ ٥٨٩٥","",{"k":"کر طبرانی صغیر (٤٧٣/٢، ٨٣٣)، سنن ترمذی (٣٨٥٢)، صحیح ابن حبان (٧١٤٢)۔"}],[5895,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم بنو لحیان کی طرف گئے، پس آپ صلی اللہ علیہ وسلم نے کعبہ اپنی پچھلی جانب کیا۔ پھر فرمایا: ” جابر بن عبد اللہ! میں آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ صلی اللہ علیہ وسلم نے اپنے کسی کام کے لیے مجھے بھیجا، میں آپ صلی اللہ علیہ وسلم کے پاس آیا تو میں نے کہا: میں وہاں گیا تھا اور میں نے اس طرح اور اس طرح کیا، لیکن آپ صلی اللہ علیہ وسلم نے مجھے کوئی جواب نہ دیا، میں واپس آیا اور (اپنے دل میں ) کہا: ہوسکتا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بات سمجھائی نہ ہو، میں پھر آپ صلی اللہ علیہ وسلم کے پاس آیا اور میں نے عرض کیا: میں ان کے پاس گیا تھا، پس میں نے اس طرح اور اس طرح کیا۔ آپ مطلقے علیم نے فرمایا: میں نماز پڑھ رہا تھا۔“ اس حدیث کو ابراہیم بن مہاجر سے صرف اسرائیل نے روایت کیا۔ اس میں مصعب بن المقدام کا تفرد ہے۔ ناندو مسلم شریف میں ہے کہ سیدنا جابر علی اہلیہ فرماتے ہیں: میں واپس لوٹ کر آیا تو رسول اللہ صلی اللہ علیہ وسلم اپنے اونٹ پر نماز پڑھ رہے تھے، میں نے بات کی تو آپ صلی اللہ علیہ وسلم نے ہاتھ سے اس طرح اشارہ کیا۔ صحیح مسلم ہی کی روایت میں ہے کہ سیدنا جابر رضی اللہ عنہ فرماتے ہیں: میں نے سلام کیا تو آپ صلی اللہ علیہ وسلم نے جواب نہ دیا۔ ( صحیح مسلم، کتاب المساجد، باب تحريم الكلام في الصلاة الخ) امام نووی اللہ فرماتے ہیں: معلوم ہوا کہ نماز میں بات کرنا حرام ہے، خواہ ضرورت سے ہو یا بغیر ضرورت سے۔ (٢) معلوم ہوا کہ نماز میں زبان سے سلام کا جواب دینا حرام ہے، البتہ اشارے سے جواب دینا جائز ہے، جیسا کہ سیدنا صہیب رضی اللہ عنہ سے مروی ہے کہ میں رسول اللہ معلی علیم کے پاس سے گزرا جب کہ آپ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے، میں نے آپ تم کو سلام کہا تو آپ صلی اللہ علیہ وسلم نے اشارے سے جواب دیا۔ (سنن ابی داؤد، کتاب الصلاة، رقم: ٩٢٥)","",{"k":"و، و، صحیح بخاری (١٢١٧)، صحیح مسلم کتاب المساجد (٥٤٠)۔"}],[5896,"ا سیدنا عبد اللہ ابن عمر نبی الیہ نے بیان کیا، سیدنا عمر بن الخطاب نبی اللہ نے فرمایا: ” میں نے تین امور: حجاب، مقام ابراہیم اور بدر کے قیدیوں کے بارے میں، اپنے رب کی موافقت کی۔“ اس حدیث کو نافع سے صرف جویریہ نے روایت کیا۔ اس میں سعید بن عامر کا تفرد ہے۔ ٥٨٩٧","",{"k":"کر صحیح بخاری (٤٠٢)۔"}],[5897,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، نبی لیے علیم نے فرمایا: ”ایسی بیع جس میں اختیار ہو، اس کے علاوہ ہر خرید وفروخت کرنے والے کے درمیان کوئی بیچ نہیں حتی کہ وہ الگ الگ ہو جائیں۔“ اس حدیث کو شعبہ سے صرف سعید بن عامر نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ جب تک بائع اور مشتری ایک ہی مجلس میں ہوں، انہیں بیع فسخ کرنے کا اختیار ہے اور جب وہ جدا ہو جائیں تو پھر یہ اختیار ختم ہو جاتا ہے اور بیع پختہ ہو جاتی ہے۔ یہ بھی معلوم ہوا کہ اگر سودا اختیار والا ہو تو بائع اور مشتری کے جدا ہونے کے بعد بھی بیع فسح کرنے کا اختیار باقی رہتا ہے۔ اختیار والے سودے سے مراد یہ ہے کہ بیج کے وقت بائع نے مشتری کو اختیار دیا ہو یا مشتری نے اختیار کی شرط لگائی ہو تو پھر مقرر مدت پوری ہونے تک دونوں کو اختیار ہوتا ہے چاہے وہ بیع فسخ کر دیں یا برقرار رکھیں","",{"k":"صحیح بخاری (٢١١٣)، صحیح مسلم (١٥٣١)۔"}],[5898,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگانے والے ابو طیبہ کو بلا بھیجا تو اس نے آپ ملے علی یم کو رمضان میں عصر کے بعد پچھنے لگائے۔ اس حدیث کو اعمش سے صرف علیلہ بن بدر ( اور وہ الربیع بن بدر ہیں ) نے روایت کیا۔","",{"k":"٥٨٩٨ ١٠/ مجمع الزوائد (٣/١٧٣)، مجمع البحرين (١٥٣١)، اسناده ضعيف۔","f":"مذکورہ روایت ضعیف ہے اس میں علیلہ بن بدر متروک ہے، تاہم پیچھے صحیح احادیث گزر چکی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے روزے کی حالت میں سینگی لگوائی ہے۔"}],[5899,"سیدنا طارق بن شہاب نیل اللہ نے بیان کیا، ہم طلائی تلوار فروخت کیا کرتے تھے اور ہم اسے چاندی کے بدلے خریدتے تھے۔ اس حدیث کو ابو خالد الدالانی سے صرف عبدالسلام بن حرب نے روایت کیا اور طارق سے صرف اسی اسناد سے مروی ہے۔ ٥٩٠٠","",{"k":"کر مجمع الزوائد (١٢٣)۔"}],[5900,"سیدنا عبداللہ ابن عباس بنایا جا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم مکہ سے مدینہ کی طرف سفر کیا کرتے تھے، آپ صلی اللہ علیہ وسلم دو دو رکعتیں پڑھتے تھے اور آپ صلی اللہ علیہ وسلم صرف اللہ تبارک و تعالیٰ سے ڈرتے تھے۔ ( یعنی کسی دشمن کا خوف نہیں تھا)","",{"k":"کی سنن ترمذی كتاب الصلاة (٥٤٧)، قال الشيخ الالباني: صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں مغرب کے علاوہ باقی نمازیں دو دو رکعت نماز ادا کرتے تھے۔ ٥٩٠١"}],[5901,"سیدنا عبداللہ ابن عباس والی عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے پچھنے لگوائے اور اس کی اجرت بھی دی، اگر وہ کام خبیث ہوتا تو آپ صلی اللہ علیہ وسلم اس کی اجرت نہ دیتے۔ ان دونوں حدیثوں کو سعید بن عبد الرحمن سے صرف مسلم بن ابراہیم، ابونعیم اور عبد الرحمن بن مہدی نے روایت کیا۔ ٥٩٠٢","",{"k":"صحيح بخاري كتاب البيوع (٢١٠٣)، صحیح مسلم، تقدم تخريجه (٢٤٦٧)۔"}],[5902,"سیدنا عبد الله صل ال علینہ نے بیان کیا، میں نے رسول اللہ اسے علم کو فرماتے ہوئے سنا: مومن کی جان اس حال میں نکلتی ہے کہ اسے پسینہ آتا ہے اور میں گدھے کی موت کی طرح موت پسند نہیں کرتا۔ “ آپ صلی اللہ علیہ وسلم سے عرض کیا گیا: گدھے کی موت کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” اچانک موت۔ فرمایا: کافر کی روح اس کے جبڑوں سے نکلتی ہے۔ اس حدیث کو ابو معشر سے صرف حسام بن مصک نے روایت کیا۔ اس میں مسلم بن ابراہیم کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم دوسری صحیح حدیث سے ثابت ہے کہ اچانک موت مومن: ٥٩٠٣","",{"k":"مجمع الزوائد (٣٢٤/٢)، مجمع ال مجمع البحرين (١٢١٥)۔","f":"کے لیے رحمت اور غیر مومن کے لیے عذاب ہے۔ جیسا کہ سیدنا عبید اللہ بن خالد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اچانک موت ناراضی کی پکڑ ہے۔ (صحیح سنن ابی داؤد، رقم: ٢٦٦٧) مشكاة كتاب الجنائز، باب تمنى الموت میں ہے کافر کے لیے اچانک موت ) ناراضی کی پکڑ ہے اور مومن کے لیے ( باعث ) رحمت ہے۔"}],[5903,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو نوجوان کسی عمر رسیدہ شخص کی اس کی عمر کی وجہ سے عزت کرتا ہے تو اللہ اس کے لیے کسی کو مقرر کر دیتا ہے جو اس کی کبرسنی میں اس کی عزت کرتا ہے۔“ یہ حدیث سیدنا انس رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں یزید بن بیان کا تفرد ہے۔ ٥٩٠٤","",{"k":"سنن ترمذی (٢٠٢٢)، قال الشيخ الالباني: ضعيف . ہ۔"}],[5904,"سیدنا انس بن مالک نبی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارے نوجوانوں میں سے بہتر وہ ہے جو تمہارے عمر رسیدہ لوگوں سے مشابہت رکھتا ہے اور تمہارے عمر رسیدہ لوگوں میں سے بدتر وہ ہے جو تمہارے نو جوانوں سے مشابہت رکھتا ہے۔“ ٥٩٠٥","",{"k":"مجمع الزوائد (١٠/٢٧٣)، مجمع البحرين (٥٠٧٦)، مسند ابی یعلی (٧٤٨٣)، اس میں حسن بن ابی جعفر ضعیف ہے۔۔"}],[5905,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی نبی ملنے کے پاس آیا تو آپ میم نے فرمایا: تم ام ملدم میں کب مبتلا ہوئے؟ اس نے کہا: ام ملدم کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”حرارت (بخار ) جو جلد اور ہڈی کے درمیان ہوتی ہے، وہ خون چوستی ہے اور گوشت کھاتی ہے۔“ اس نے کہا: میں تو کبھی بیمار نہیں ہوا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی جہنمی کو دیکھنا چاہے تو وہ اسے دیکھ لے۔“ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اسے میرے پاس سے نکال دو۔ ان دونوں حدیثوں کو ثابت سے صرف الحسن بن ابی جعفر نے روایت کیا۔ اس میں مسلم بن ابراہیم کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٢٩٤)، مجمع البحرين (١١٦٩)، مسند احمد (٢/٣٣٢)، ابن حبان، رقم: ٢٩١٦ قال شعیب الارناؤط: اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ تکلیف پہنچنا مومن کی شان ہے کیونکہ اس میں اجر و ثواب ہے جو دخول جنت کا ذریعہ ہے۔ جسے کچھ بھی تکلیف نہ پہنچی ہو اس کے گناہ اس کے سر رہیں گے جن پر عذاب ہو گا۔ کفارے کے لیے جو تکلیفیں آتی ہیں وہ اس کو پیش نہ آئیں اور اس نے غفلت میں زندگی گزار دی تو یہ بظاہر دخول نار کا سبب بن گیا۔ ٥٩٠٦"}],[5906,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ ابو بکر پر رحم فرمائے! اس نے اپنی بیٹی سے میری شادی کرائی، مجھے دار ہجرت (مدینہ ) پہنچایا، اپنے مال میں سے بلال کو خریدا، اللہ تعالیٰ عمر پر رحم فرمائے، وہ حق بات کرتا ہے، خواہ وہ کڑوا ہو، حق نے اسے ترک کر دیا اور اس کا کوئی دوست نہیں، اللہ تعالیٰ عثمان پر رحم فرمائے! وہ تو ایسا شخص ہے کہ فرشتے اس سے حیا کرتے ہیں، اللہ تعالیٰ علی پر رحم فرمائے، اے اللہ! وہ جہاں جائے حق اس کے ساتھ ہو۔“ یہ حدیث سیدنا علی نبی الیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں ابو عتاب الدلال کا تفرد ہے۔ ٥٩٠٧","",{"k":"سنن ترمذی (٣٧١٤)، مسند ابی یعلی قال الشيخ الالباني: ضعيف جدا۔"}],[5907,"سیدنا ابو ہریرہ نبی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عورت کی کسی ایسے شخص سے شادی نہ کی جائے جس کے نکاح میں اس کی پھوپھی موجود ہو اور اسی طرح خالہ کی موجودگی میں بھانجی کی شادی نہ کی جائے۔“ اس حدیث کو قتادہ سے صرف ہمام اور سعید بن بشیر نے روایت کیا۔ اس میں ابو عاصم کا ہمام سے اور محمد بن بکار بن ہلال الدمشقی کا سعید بن بشیر سے تفرد ہے۔ ٥٩٠٨","",{"k":"صحیح بخاری (٥١٠٩)، صحیح مسلم (١٤٠٨)۔"}],[5908,"سيدنا عبد اللہ فی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: علم حاصل کرنا ہر مسلمان پر فرض ہے۔“ اس حدیث کو حماد سے صرف عثمان بن عبد الرحمن نے روایت کیا۔ اس میں الہذیل بن ابراہیم کا تفرد ہے۔","",{"k":"معجم کبیر طبرانی (٩/٤٢)، مجمع الزوائد (١/١٢٠)، مجمع البحرين (٠)۔"}],[5909,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آخری دور میں میری امت کے شریر لوگوں کے لیے قدر میں کلام کو مؤخر کیا جائے گا اور قرآن کے بارے میں جھگڑا، بحث و مباحثہ کرنا کفر ہے۔ اس حدیث کو زہری سے صرف عنبہ بن مہدی الحداد نے روایت کیا۔","",{"k":"مجمع الزوائد (٧/٢٠٥)، سلسله صحيحه (١١٢٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ تقدیر کے موضوع پر گفتگو کرنے والے اس امت کے بدترین لوگ ہیں اور نبی معظم سے ہم نے اس امت کے متاخرین کے بارے میں پیشین گوئی کی ہے اور موجودہ زمانہ امت محمدیہ کے متاخرین کا گزر رہا ہے۔ لہذا ہمیں اس کا مصداق بننے سے بچنا چاہیے کسی صورت میں بھی تقدیر کی بحث میں نہیں پڑنا چاہیے۔ ٥٩١٠"}],[5910,"سیدنا سعيد بن ابی سعید مقبری سے روایت ہے کہ انہوں نے سیدنا عبداللہ ابن عباس بیا اینجا کے پیچھے نماز جنازہ پڑھی تو انہوں نے سورۃ الفاتحہ بلند آواز سے پڑھی اور فرمایا: ”میں پسند کرتا ہوں کہ لوگ جان لیں کہ یہ سنت ہے۔ اس حدیث کو محمد بن عجلان سے صرف ہمام نے روایت کیا۔ اس میں الحوضی کا تفرد ہے۔","",{"k":"صحیح بخاری (١٣٣٥)، سنن ابو داود (٣١٩٨)، سنن ترمذی (١٠٢٧)۔","f":"ان مذکورہ حدیث سے معلوم ہوا کہ جنازہ کی نماز میں سورہ فاتحہ پڑھنا مسنون ہے، بلکہ اس کے بغیر نماز ہی نہیں ہوتی، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (( لا صلاة لمن لم يقرأ بفاتحة الكتاب)) (صحیح بخاری، رقم: ٧٥٦) کیونکہ نماز جنازہ بھی ایک نماز ہی ہے لہذا اس میں بھی دیگر نمازوں کی طرح سورہ فاتحہ کی قراءت ضروری ہے۔ (٢) یہ بھی معلوم ہوا کہ نماز جنازہ بلند آواز سے پڑھنا بھی مسنون ہے۔ (٣) سیدنا عبداللہ ابن عباس ولی اونجا کا یہ کہنا کہ یہ سنت ہے، یہ مرفوع حدیث کے معنی میں ہے۔ ٥٩١١"}],[5911,"سيدنا عاصم بن کلیب نے اپنے والد سے روایت کیا کہ نبی ملنے کی یکم جب سجدہ کیا کرتے تھے تو آپ ملنے دی ایم کے ہاتھ زمین پر لگنے سے پہلے آپ صلی اللہ علیہ وسلم کے گھٹنے لگا کرتے تھے اور جب آپ صلی اللہ علیہ وسلم ایک رکعت پڑھ کر دوسری رکعت کے لیے کھڑے ہوتے تھے تو آپ ملے نہ گھٹنوں پر کھڑے ہوتے تھے اور رانوں پر سہارا لیتے تھے۔ اس حدیث کو شقیق بن ابی عبد اللہ سے صرف ہمام نے روایت کیا۔ مذکورہ روایت ضعیف ہے، تاہم دوسری صحیح حدیث میں ہے، سیدنا ابو ہریرہ ڈالنے سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی سجدہ کرے تو اونٹ کی طرح نہ بیٹھے اور اپنے ہاتھ گھٹنوں سے پہلے (زمین پر) رکھے۔ (سنن ابی داؤد، رقم: ٨٤٠-٨٤١، سنن ترمذی، رقم: ٢٦٩، قال الشيخ الالبانی: صحیح معلوم ہوا کہ سجدہ جاتے وقت پہلے ہاتھ زمین پر رکھنے چاہئیں۔","",{"k":"سنن ابو داود (٨٣٨)، مجمع البحرين (٨٣٣)، قال الشيخ الالباني: ضعيف۔"}],[5912,"سیدنا ابو ہریرہ بیانیہ سے روایت ہے کہ رسول اللہ صل علی نے وضو کیا تو آپ صلی اللہ علیہ وسلم نے تین بار کلی کی، تین بار ناک میں پانی داخل کیا، تین بار چہرہ دھویا، تین بار ہاتھ دھوئے، تین بارسر کا مسح کیا اور تین بار پاؤں دھوئے۔ اس حدیث کو عطاء کے حوالے سے سیدنا ابو ہریرہ نیا لینے سے صرف عامر الاحول نے روایت کیا۔ اس میں ہمام کا تفرد ہے۔","",{"k":"٥٩١٣ مجمع الزوائد (١/٢٣٠)، مجمع البحرين (٤١٠)، اسناده صحيح۔"}],[5913,"سیدنا عبد اللہ بن حارث نے اپنے والد سے روایت کیا کہ نبی صلی اللہ علیہ وسلم نے نماز جنازہ کی دعا سکھائی: ”اے اللہ! ہمارے زندہ اور فوت شدگان کو بخش دے، ہمارے معاملات درست کر دے، ہمارے دلوں میں الفت ڈال دے، اے اللہ! یہ تیرا فلاں بندہ اس کے متعلق ہم تو خیر ہی جانتے ہیں، جبکہ اس کے متعلق تو خوب جانتا ہے، ہمیں اور اسے بخش دے۔ میں نے آپ صلی اللہ علیہ وسلم سے عرض کیا: جبکہ میں ان سب سے چھوٹا تھا۔ اگر ہم خیر نہ جانتے ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” تم نہ کہومگر وہی جو تم جانتے ہو۔“ اس حدیث کو علقمہ بن مرثد سے صرف لیث بن ابی سلیم نے روایت کیا۔ اس میں ہمام کا تفرد ہے۔حارث سے صرف اسی اسناد سے مروی ہے۔ ٩١٤","",{"k":"مجمع الزوائد (٣٦/٣)، مجمع البحرين (١٢٨٨)۔"}],[5914,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے ہیم نے فرمایا: مجلس کا کفارہ یہ دعا ہے: ”پاک ہے تو اے اللہ! اپنی حمد کے ساتھ، تیرے سوا کوئی معبود نہیں، میں تجھ سے مغفرت طلب کرتا ہوں اور تیرے حضور تو بہ کرتا ہوں۔ یہ حدیث سیدنا انس رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عثمان بن مطر کا تفرد ہے۔ ٥٩١٥","",{"k":"مجمع الزوائد (١٤٤/١٠)، تقدم تخريجه (١٢٢٧)۔"}],[5915,"سیدنا عبد الرحمن بن خباب رضی اللہ عنہ نے بیان کیا، میں نبی صلی اللہ علیہ وسلم کے پاس موجود تھا، آپ ملنے سلیم نے غزوہ تبوک کے لیے ترغیب دلائی تو سیدنا عثمان بن عفان رضی اللہ عنہ ہوئے، انہوں نے عرض کیا: اللہ کے رسول! سو اونٹ ان کے جھولوں اور پالانوں سمیت میرے ذمے، میں اللہ کی راہ میں پیش کرتا ہوں۔ پس میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، جبکہ آپ ملے ایام منبر پر فرما رہے تھے: ”اس کے بعد عثمان جو بھی عمل کرے اس پر کوئی مواخذہ نہیں۔“ یہ حدیث عبد الرحمن بن خباب سے صرف اسی اسناد سے مروی ہے۔ اس میں سکن بن المغیرہ کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم دوسری حدیث میں ہے کہ سیدنا عبد الرحمان بن سمرہ بنی اللہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے جب تنگی کی حالت میں لشکر تیار کرنا شروع کیا تو سیدنا عثمان بن عفان بنی الہیہ اس تیاری میں حصہ ڈالنے کے لیے رسول اللہ سے دین کی خدمت میں آئے۔ اپنے کپڑے میں انہوں نے ایک ہزار دینار ڈال رکھے تھے۔ آتے ہی انہوں نے یہ ساری رقم رسول اللہ صلی اللہ علیہ وسلم کی جھولی میں ڈال دی۔ اب تو رسول اللہ صلی اللہ علیہ وسلم ان دیناروں کو ہاتھ میں لے کر الٹ پلٹ کر رہے تھے اور فرما رہے تھے: عفان کے بیٹے کو کوئی پروا نہیں، چاہے آج کے بعد وہ کوئی اور عمل نہ کرے، رسول اللہ صلی اللہ علیہ وسلم نے یہ جملہ بار بار دہرایا۔ (مسند احمد: ٦٣/٥ - اسناده حسن لذاته ) ٥٩١٦","",{"k":"سنن ترمذی (٣٧٠٠)، قال الشيخ الالباني ضعيف۔"}],[5916,"سیدہ ام سلمہ بین النہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے عشا کی نماز میں قنوت سے منع فرمایا ہے۔ یہ حدیث سیدہ ام سلمہ بنلی ایشیا سے صرف اسی اسناد سے مروی ہے۔ اس میں محمد بن یعلی سے زنبور کا سے تفرد ہے۔","",{"k":"مجمع ضعيف . الزوائد (١٤١/٢)، مجمع البحرين (٨٦٢٢٦٢٢)، اسناده۔"}],[5917,"سیدنا جابر ضنا الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” گائے کی قربانی سات افراد کی طرف سے اور اونٹ کی قربانی سات افراد کی طرف سے ہے۔ اس حدیث کو قیس بن سعد سے صرف حماد بن سلمہ نے روایت کیا۔","",{"k":"کر صحیح مسلم (١٣١٨)۔"}],[5918,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا جبکہ آپ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے، میں نے آپ ملنے سلیم کو سلام کیا تو آپ صلی اللہ علیہ وسلم نے اشارے سے جواب دیا۔ اس حدیث کو سیدنا ابو ہریرہ میل الیہ کے حوالے سے سیدنا عبد اللہ ابن مسعود رضی اللہ عنہ سے صرف ابن سیرین نے اور ابن سیرین سے صرف ہشام نے اور ہشام سے صرف ابن رجاء نے روایت کیا۔ اس میں ابو یعلی التوزی کا تفرد ہے۔ خاندن مذکورہ حدیث سے معلوم ہوا کہ نمازی کو سلام کہنے میں کوئی حرج نہیں ہے۔ البتہ آواز آہستہ ہونی چاہیے اور معلوم ہوا کہ نماز میں جواب اشارے سے دے نہ کہ زبان سے۔ ٥٩١٩","",{"k":"مجمع الزوائد (٨١/٢)، اسناده صحيح۔"}],[5919,"سیدنا ابی بن کعب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج گرہن لگا اور رسول اللہ صلی اللہ علیہ وسلم نے انہیں نماز پڑھائی، آپ نے طوال سورتوں میں سے ایک سورت پڑھی، پھر آپ علیم نے پانچ رکوع کیے اور دو سجدے کیے، پھر آپ دوسری رکعت کے لیے کھڑے ہوئے تو آپ رضی اللہ عنہ نے طوال سورتوں میں سے ایک سورت پڑھی، پھر پانچ رکوع کیے اور دو سجدے کیے، پھر آپ بیٹھے جس طرح وہ قبلہ رخ تھے، آپ دعا کرتے رہے حتی کہ سورج گرہن ختم ہو گیا۔ اس حدیث کو رسول اللہ لی سے کہ نماز کسوف میں دس رکوع اور چار سجدے ہیں صرف سیدنا ابی بن کعب خیال الیہ نے روایت کیا اور سیدنا ابی بن کعب رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں ابو جعفر الرازی کا تفرد ہے۔","",{"k":"سنن ابی داود (١١٨٢)، قال الشيخ الالباني: ضعيف۔"}],[5920,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو میت کی چار پائی کو چاروں اطراف سے اٹھاتا ہے، اللہ تعالیٰ اس کے چالیس کبیرہ گناہ معاف کر دیتا ہے۔“ یہ حدیث سیدنا انس خلیل اللہ صلی اللہ علیہ وسلم سے صرف اسی اسناد سے مروی ہے۔ اس میں علی بن ابی سارہ کا تفرد ہے اور اسے نبی ملنے کام سے صرف سیدنا انس بن مالک رضی اللہ عنہ ہی نے روایت کیا ہے۔ ٥٩٢١","",{"k":"إِلَّا بِهَذَا الْإِسْنَادِ، تَفَرَّدَ بِهِ عَلِيُّ بْنُ أَبِي سَارَةَ، وَلَمْ يَرْوِهِ عَنِ إِلَّا أَنَّسُ بْنُ مَالِكِ . مجمع الزوائد (٢٩/٣)، سلسله ضعیفه (١٨٩١)، اسناده ضعیف۔"}],[5921,"سيدنا طلحہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سبزیوں پر کوئی زکوۃ نہیں۔“ اس حدیث کو موسی بن طلحہ، عن ابیہ سے موصولاً صرف عطاء بن سائب نے،عطاء سے صرف حارث بن بنیان نے روایت کیا ہے۔ اس میں ابو کامل الجحدری کا تفرد ہے۔ ٥٩٢٢","",{"k":"مجمع الزوائد (٣/٧٢)، مجمع البحرين (١٣٥٠)، اسناده ضعيف۔"}],[5922,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”بندہ خیر و بھلائی پر رہتا ہے، جب تک وہ عجلت نہیں کرتا۔ عرض کیا گیا: اللہ کے رسول! وہ کس طرح عجلت کرتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: وہ کہتا ہے میں نے اپنے رب سے دعا کی اور وہ قبول نہیں ہوئی۔“ ٥٩٢٣","",{"k":"مجمع الزوائد (١٠/١٥٠)، مجمع البحرين (٤٦٢١)، تقدم تخريجه (٢٤٩٧)۔"}],[5923,"سیدنا انس بنی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب بھی ہمیں خطبہ ارشاد فرماتے تو یہ فرماتے تھے: ”جس میں امانت نہیں اس میں ایمان نہیں اور جو عہد کا پابند نہیں اس میں دین نہیں۔“ ٩٢٤","",{"k":"مجمع الزوائد (٩٦/١)، مجمع البحرين (١١٦)، تقدم تخريجه (٢٦٠٦)۔"}],[5924,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو قریش کی اہانت کرتا ہے اللہ اس کی موت سے پہلے اس کی اہانت کر دیتا ہے۔“ ان احادیث کو قتادہ سے صرف ابو ہلال نے روایت کیا۔","",{"k":"مجمع الزوائد (١٠/٢٧، ٣٢٠٠)، مجمع البحرين (٣٩٣١)، اسناده ضعيف . ٥٩٢٥ ور له وه و و ل۔"}],[5925,"سیدنا عبد اللہ فی اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب گرج کی آواز سنتے تھے تو یہ دعا کرتے تھے: ”اے اللہ! ہمیں اپنے کسی قسم کے عذاب سے ہلاک نہ کرنا اور اس سے پہلے ہی ہمیں عافیت عطا فرمانا “ اس حدیث کو سالم سے صرف ابو مطر نے اور ابو مطر سے صرف الحجاج نے روایت کیا۔ اس میں عبد الواحد بن زیاد کا تفرد ہے۔","",{"k":"سنن ترمذی کتاب الدعوات (٣٤٥٠)، قال الشيخ الالباني: ضعيف . ضعيف الجامع (٤٤٢١)۔"}],[5926,"سیدہ عائشہ منی لا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو جادو کر دیا گیا تو آپ مطلع علیم نے اپنے رب سے دعا کی، پھر فرمایا: ”کیا تمہیں معلوم ہے کہ اللہ عزوجل نے میری دعا قبول فرمالی ہے؟ دوفرشتے میرے پاس آئے تو ان میں سے ایک سر کے پاس اور دوسرا میرے پاؤں کے پاس بیٹھ گیا اور ان میں سے ایک نے دوسرے سے کہا: اس آدمی کو کیا ہوا ہے؟ اس نے کہا: ان پر جادو کیا گیا ہے، اس نے کہا: کس نے ان پر جادو کیا ہے؟ اس نے کہا: لبید بن اعصم یہودی نے، اس نے کہا: کس چیز میں؟ اس نے کہا: بنور لیسان کے کنویں کے پتھر کے نیچے کھجور کے غلاف میں پڑے ہوئے کنگھی اور کنگھی کرتے وقت سر اور داڑھی سے گرنے والے بالوں پر کیا گیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: علی! وہاں جاؤ!“ اس کا پانی دیکھا تو وہ مہندی کے نچوڑ جیسا تھا، میں نے ارادہ کیا کہ میں اسے کھینچ نکالوں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے مجھے شفا عطا فرمادی ہے۔“ اس حدیث کو مرجی بن رجا سے صرف حفص بن عمر الحوضی نے روایت کیا۔ اند. مذکورہ حدیث پر بعض لوگ اعتراض کرتے ہیں کہ نبی معظم نے تم پر جادو ہوا تسلیم کر لینا کفار کے اس الزام کی تائید ہوتی ہے کہ نبی معظم صلی اللہ علیہ وسلم پر جادو کا اثر ہے، جس کا ذکر سورہ فرقان آیت نمبر ٨ میں، لیکن یہ اعتراض اس لیے غلط ہے کہ کفار قرآن مجید کو اور رسول اللہ صلی اللہ علیہ وسلم کی دعوت اور محنت کو جنون اور جادو کا اثر قرار دیتے تھے۔ مذکورہ حدیث کا کفار کے اس قول سے کوئی تعلق نہیں۔ نبی بھی انسان ہوتے ہیں اس لیے وہ جسمانی تشدد اور دینی پریشانی سے متاثر ہو سکتے ہیں۔ ایک حدیث میں ہے کہ ((أَشَدُّ النَّاسِ بَلاءَ الأَنْبِيَاءِ )) (صحیح بخاری، رقم: ٥٦٤٨) سخت ترین تکلیفیں انبیاء علیہم پر آتی ہیں۔ طائف کے میدان میں آپ ملنے کے نام پر پتھر برسائے گئے حتی کہ لہو لہان ہو کر بے ہوش ہو کر گر گئے، جنگ احد میں آپ ملے ان کا سر مبارک زخمی ہوا، دندان مبارک شہید کر دیئے گئے تو یہاں ایسی کوئی بات نہیں کہ انبیاء و رسل علی کو کوئی تکلیف یا جادو نہ ہو، لبید بن اعصم یہ ایک منافق تھا، جس کا یہودیوں سے تعلق تھا اور نبی معظم مام کی خدمت کرتا تھا، نبی معظم ملے عام بشر تھے، عالم الغیب نہیں، اس کا باطن کیا ہے؟ اور مافی الضمیر کیا ہے؟ اللہ تعالیٰ کے پیغمبر ملے ہی نہیں جانتے تھے، یہ عمل تقریباً چھ ماہ جاری رہا، کنویں کا رنگ مہندی رنگ کی طرح تھا، یہ غالبا عدم استعمال کی وجہ سے تھا۔ ٥٩٢٧","",{"k":"کر صحیح بخاری (٥٧٦٣)، صحيح مسلم (٢١٨٩)۔"}],[5927,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو ہمارے بڑے کی عزت نہیں کرتا اور ہمارے چھوٹے پر رحم نہیں کرتا وہ ہم میں سے نہیں۔“ اس حدیث کو ابوالز بیر سے صرف مبارک بن فضالہ نے روایت کیا۔ اس میں سہل بن تمام بن بزیع کا تفرد ہے۔ ٩٢٨","",{"k":"مجمع الزوائد (١٤/٨)، مجمع البحرين (٢٩٦٧)۔"}],[5928,"سیدنا حارث رضی اللہ عنہ سے روایت ہے کہ وہ حجتہ الوداع کے موقع پر رسول اللہ صلی اللہ علیہ وسلم سے ملے جبکہ آپ اپنی العضباء اونٹنی پر تھے۔ میں نے عرض کیا: اللہ کے رسول! میرے والدین آپ طلئے تعلیم پر قربان ہوں، میرے لیے مغفرت کی دعا فرمائیں! آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تمہیں معاف فرمائے۔“ پھر میں گھوم کر دوسری طرف اس امید سے آیا کہ آپ صلی اللہ علیہ وسلم میرے لیے خصوصی طور پر دعا فرمائیں۔ میں نے عرض کیا: اللہ کے رسول! میرے لیے مغفرت کی دعا فرما ئیں، آپ ملنے ہیم نے فرمایا: ”اللہ تمہیں معاف فرمائے۔“ ایک آدمی نے عرض کیا: اللہ کے رسول! فرائع اور عمائر؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو چاہے اونٹنی کے پہلوٹے بچے کو ذبح کرے، جو چاہے رجب کے مہینے میں بکری ذبح کرے اور جو چاہے رجب میں بکری ذبح نہ کرے اور بکری میں اس کی قربانی ہے۔“ پھر فرمایا: ”سنو! تمہارے خون اور تمہارے اموال تم پر اسی طرح حرام ہیں جس طرح تمہارے اس دن کی اور تمہارے اس مہینے کی حرمت ہے۔ یہ حدیث حارث بن عمرو سے صرف اس کے بیٹے کی روایت سے اس اسناد سے مروی ہے۔ اور عبد الوارث بن سعید نے اسے عقبہ بن عبد الملک اسہمی، عن کریم بن الحارث، عن ابیہ کی سند سے روایت کیا ہے۔","",{"k":"مجمع الزوائد (٢٦٢/٣)، سنن نسائی (٤٢٢٧)، مجمع البحرين (١٧٨٥، ٩٦٣)، اسناده حسن۔"}],[5929,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: علی! اپنی: خواتین سے کہو وہ زیورات سے خالی ہو کر نماز نہ پڑھیں، خواہ وہ گلے میں چمڑے وغیرہ کا تسمہ ہی ہار بنا کر پہن لیں۔“ یہ حدیث سیدنا علی ضیا لینے سے صرف اس اسناد سے مروی ہے۔ اس میں قیس بن الربیع کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥٥/٢)۔"}],[5930,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھے بیٹھے گئے حتی کہ خراٹے بھرنے لگے، پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے تو نماز پڑھائی اور (نیا) وضو نہ کیا۔ اس حدیث کو اشعث، عن ابی ہبیرہ سے، سعید بن مسیب سے صرف شریک نے روایت کیا۔ اور ان کے علاوہ اسے اشعث عن ابی ہبیر عن سعید بن جبیر کی سند سے روایت کیا۔ شاند. اگر چہ اس کی سند کمزور ہے، تاہم رسول اللہ صلے ان کی خصوصیت تھی کہ نیند میں بھی آپ ملنے کا وضو قائم رہتا تھا کیونکہ نبی معظم صلی اللہ علیہ وسلم کا دل بیدار رہتا تھا اگر آپ صلی اللہ علیہ وسلم کا وضو ٹوٹتا تو آپ طالب علم کو علم ہو جاتا۔ لوعلم ہو ٥٩٣١","",{"k":"سنن ابو داود (٢٠٢)، سنن ترمذى (٧٧)، قال الشيخ الالباني: ضعيف۔"}],[5931,"سیدنا عبداللہ ابن عباس ریلی عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کو فجر کی نماز میں ایک آیت میں تردد ہوا، پس جب آپ صلی اللہ علیہ وسلم نماز پڑھ چکے تو نمازیوں کی طرف متوجہ ہو کر فرمایا: کیا ابی بن کعب نے تمہارے ساتھ نماز پڑھی ہے؟ انہوں نے عرض کیا: نہیں، نمازیوں نے سمجھا کہ آپ صلی اللہ علیہ وسلم نے ان کا اس لیے نام لیا کہ وہ آپ صلی اللہ علیہ وسلم کو اس آیت کے متعلق بتائیں۔“ یہ حدیث سیدنا عبداللہ ابن عباس وہی پہنچا سے صرف اسی اسناد سے مروی ہے۔ اس میں قیس بن الربیع کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٧٢)، مجمع البحرين (٦٩٧)، اسناده ضعيف۔"}],[5932,"سیدہ رمیشہ ضمنی الینا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس دن وہ فوت ہوئے تھے تو ان کی خاطر رحمن کا عرش ہل گیا تھا۔“ اس سے مراد سیدنا سعد بن معاذ رضی اللہ عنہ یہ حدیث رمینہ رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں یوسف الماجشون کا تفرد ہے۔ مذکورہ حدیث سے سیدنا سعد بن معاذ رضی اللہ عنہ کی فضیلت کا اثبات ہوتا ہے، سیدنا سعد رضی اللہ عنہ اوس کے سردار تھے، آپ یا اللہ جنگ احد میں شہید ہوئے، عرش کا ہلنا شاید کہ ان کے آنے کی خوشی میں ہل گیا تھا اور کہتے ہیں کہ عرش ایک جسم ہے اس کا ہلنا جائز ہے۔","",{"k":"مجمع الزوائد (٣٠٨/٩)، سنن ترمذی (٣٨٤٨)، صحیح مسلم (٢٤٦٦)، صحیح بخاری، مجمع البحرين (٣٨٦٩)، اسناده صحيح۔"}],[5933,"سیدنا ابن عون رضی اللہ عنہ نے بیان کیا، میں نے نافع کے نام خط لکھا کہ میں ان سے قبال سے پہلے کی دعا کے متعلق سوال کروں، پس انہوں نے مجھے جواب لکھا: کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو مصطلق پر حملہ کیا، آپ نے ان کے جنگ جو افراد کو قتل کیا اور ان کے بچوں کو قیدی بنایا، سیدنا عبد اللہ بن عمر ضیا اللہ نے یہ حدیث مجھے بیان کیا، وہ اس لشکر میں شامل تھے۔ علی بن حکیم الباہلی بصری نے صرف اسی حدیث کو مسند روایت کیا۔ اس میں ابو الولید کا تفرد ہے۔","",{"k":"صحيح بخاری (٢٥٤١)، صحیح مسلم (١٧٣٠)۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے کہ دعوت اسلام دینے کے بغیر ہی غیر مسلموں پر حملہ کرنا جائز ہے۔ تا ہم دوسری روایات سے ثابت ہے کہ دعوت دینا چاہیے تو علماء اس میں تطبیق اس طرح دیتے ہیں کہ جن لوگوں کو اسلام اور مسلمانوں کی دعوت پہنچ چکی ہو بوقت قتال ان کو دعوت دینا کوئی ضروری نہیں ہے اور جنہیں نہ پہنچی ہو تو انہیں دی جانی چاہیے۔ ٥٩٣٤"}],[5934,"سیدنا عبد اللہ بن زید رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے تو ہم آپ صلی اللہ علیہ وسلم کے لیے پیتل کا برتن لائے، آپ صلی اللہ علیہ وسلم نے وضوء کیا: تین بار چہرہ دھویا، دو دو بار باز و دھوئے اور سر کا مسح کیا تو دونوں ہاتھ آگے لائے اور پھر انہیں واپس لے گئے۔ اس حدیث کو جو کہ عبد اللہ بن زید سے ہے صرف الماجشون نے یہ الفاظ ”ہم آپ کے لیے پیتل کا برتن لائے نقل کیے ہیں۔","",{"k":"صحیح بخاری (١٩٧)، صحیح مسلم (٢٣٥)۔","f":"م م مذکورہ حدیث سے یہ بھی معلوم ہوا کہ پیتل کے برتن میں وضو کرنا جائز ہے کیونکہ پیتل کی رنگت سونے کی طرح ہوتی ہے، لیکن خالص سونے، چاندی یا ان سے ملمع شدہ برتن استعمال کرنا جائز نہیں۔صرف ٹانکے کی حد تک جائز ہے۔"}],[5935,"سیدنا شقیق بن سلمہ نے بیان کیا، ہم سیدنا سلمان بنی الیہ کے پاس گئے تو انہوں نے گھر میں جو موجود تھا وہ منگوایا اور فرمایا: ”اگر رسول اللہ صلی اللہ علیہ وسلم نے مہمان کے لیے تکلف برتنے سے ہمیں منع نہ کیا ہوتا تو میں تمہارے لیے تکلف کرتا۔ اس حدیث کو عثمان بن شابور سے صرف قیس بن الربیع نے روایت کیا۔ خاندن کو مذکورہ حدیث سے معلوم ہوا کہ مہمان نوازی اور خاطر داری میں ضرورت سے زیادہ مشقت اٹھانا اور انواع و اقسام کے کھانے تیار کرنا تکلف ہے اور معلوم ہوا کہ ہر قسم کا تکلف ممنوع اور سخت نا پسندیدہ ہے۔ لیکن بدقسمتی سے مسلمان قوم نے اس تکلف یعنی دعوتوں میں اسراف و تبذیر کو اپنا شعار اور وطیرہ بنا لیا ہے۔ ٥٩٣٦","",{"k":"الجامع الصغير رقم: ٢٦٧١ . الزوائد، رقم: ١٨٢/٨ مجمع البحرين (٢٩٢١)، صحیح۔"}],[5936,"سیدنا انس بنی امیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ نی نیہا کے لیے ان کے عقب میں سے بالشت کا اندازہ لگایا اور فرمایا: ” یہ عورت کا دامن ہے۔“ اس حدیث کو حمدی سے صرف معتمر نے روایت کیا۔ اس میں ضرار بن صرد کا تفرد ہے۔ خاندان ایک دوسری حدیث میں ہے کہ سیدہ ام سلمہ بنی النہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا گیا، عورت اپنا دامن کتنا لٹکائے؟ آپ ملنے سلیم نے فرمایا: ایک بالشت، میں نے کہا، تب اس (کے قدموں یا پنڈلیوں) سے کپڑا ہٹ جائے گا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، ایک ہاتھ، اس سے زیادہ نہ لٹکائے۔(سنن ابی داؤد، رقم: ٤١١٨) حافظ ابن حجر رحمہ اللہ لکھتے ہیں: کہ مرد کی دو حالتیں ہیں، مستحب حالت یہ ہے کہ آدمی تہبند پنڈلی تک اونچا رکھے اور جائز حالت یہ ہے کہ ٹخنوں سے اوپر ) تک رکھے۔ اسی طرح عورتوں کی بھی دو حالتیں ہیں، مستحب حالت یہ ہے کہ مردوں کی جائز حالت سے ایک بالشت زیادہ ہو اور مستحب حالت ایک ہاتھ یعنی مردوں کی جائز حالت سے دو بالشت زیادہ۔ (فتح الباری: ٣٢٠/١٠)","",{"k":"مجمع الزوائد (١٣٠/٥)، سنن ترمذی (١٧٣٢)، سنن ابی داؤد (٤١١٩)، مجمع البحرين (٤٢٥٠)، اسناده ضعيف۔"}],[5937,"سیدنا ابو نضرہ نے بیان کیا، میں نے سیدنا عبداللہ ابن عباس ولی اینجا سے اللہ تعالیٰ کے فرمان: ”بلا عذر جہاد پر نہ جانے والے مومن برابر نہیں ہو سکتے“ کی تفسیر کے متعلق پوچھا تو سیدنا ابن عباس فضای اینجا نے فرمایا: ”وہ ایسے لوگ ہیں جنہیں تکالیف یا امراض نے روک رکھا ہے، پس یہ عذر والے ہیں اور جہاد پر نہ جانے والے مریض کے پاس صحت مند شخص کے جہاد پر نہ جانے والے کی نسبت زیادہ عذر ہے۔“‘اس حدیث کو ابو نضرہ سے صرف ابو عقیل الدورقی بشیر بن عقبہ نے روایت کیا۔ ٥٩٣٨","",{"k":"مجمع الزوائد، رقم: ١٢/٧ انظر (٢٥٢٩)۔"}],[5938,"سیدہ میل بنت مشرح نے بیان کیا، میں نے اپنے والد کو دیکھا، انہوں نے اپنے ناخن تراشے، پھر انہیں دفن کر دیا اور فرمایا: ”بیٹی! میں نے رسول اللہ صل علی کو دیکھا آپ مالے علیم نے اسی طرح کیا تھا۔ مشرح فی اللہ سے یہ حدیث صرف اسی اسناد سے مروی ہے۔ اس میں محمد بن سلیمان بن مسمول کا تفرد ہے۔","",{"k":"شعب الایمان (٥/٢٣٢، ٦٤٨٧)، مجمع الزوائد (١٧١/٥)۔"}],[5939,"سيدنا كعب بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے معاذ بن جبل بنا اللہ کو ان کے ذمے قرض کی وجہ سے، ان کے مال میں تصرف کرنے سے روک دیا۔ اس حدیث کو معمر سے موصولاً صرف ہشام بن یوسف نے روایت کیا۔ اس میں ابراہیم بن معاویہ کا تفرد ہے۔ ٥٩٤٠","",{"k":"كر مجمع الزوائد (١٤٦/٤)، مجمع البحرين (٢٠٩١)، اسناده ٥٩٣٩ ضعيف۔"}],[5940,"سیدہ عائشہ بنا یا بیان کرتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص صبح کی نماز پڑھ کر اپنی جائے نماز پر بیٹھا رہتا ہے حتی کہ سورج طلوع ہو جاتا ہے، پھر وہ چار رکعتیں پڑھتا ہے اللہ اس کے گناہ بخش دیتا ہے۔“","",{"k":"مجمع الزوائد (١٠٨/١٠)، مجمع البحرين (٤٦٦٠)۔"}],[5941,"سیدہ عائشہ علی ہو یا بیان کرتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومنوں کی عورتو! با ہم ہدیہ تحائف دیا کرو خواہ بکری کا گھر ہو، کیونکہ وہ مودت و محبت کو قائم رکھتا ہے اور کینہ و دشمنی دور کرتا ہے۔“ ان دونوں حدیثوں کو عمرہ بنت ارطاۃ وہ: الحد ویہ، بصر یہ ہیں، عمرہ بنت عبدالرحمن نہیں سے صرف الطبيب بن سلمان المودب نے روایت کیا، ان کی کنیت ابو حذیفہ ہے۔ ٥٩٤٢","",{"k":"مجمع الزوائد (١٤٩/٤)، مجمع البحرين (٢٠٥٣)۔"}],[5942,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، ہم کبیرہ گناہ کرنے والوں کے لیے استغفار نہیں کرتے تھے، حتی کہ ہم نے اپنے نبی کے علم کو فرماتے ہوئے سنا: ” میں نے اپنی امت کے کبیرہ گناہ کرنے والوں کے لیے اپنی شفاعت کو قیامت کے دن کے لیے محفوظ رکھا ہے۔“ تو ہم نے اپنے بہت سے خیالات ختم کر دیے اور ہم ان کے لیے پر امید ہو گئے۔ اس حدیث کو ایوب سختیانی سے صرف حرب بن سریج نے روایت کیا۔ اس میں شیبان کا تفرد ہے۔ تاہم دوسری صحیح احادیث سے ثابت ہے کہ نبی معظم ملنے کی اپنی امت کے کبیرہ گناہ کرنے والوں کے لیے سفارش کریں گے۔ ٥٩٤٣","",{"k":"مجمع الزوائد (٣٧٨/١٠)، مجمع البحرين (٤٨٠٩)۔"}],[5943,"سیدنا عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ آسانی سے خریدنے والے، آسانی سے ادا کرنے والے اور آسانی سے تقاضا کرنے والے پر رحم فرمائے۔ اس حدیث کو ہشام بن عروہ سے صرف ابوالربیع السلمان نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ خرید و فروخت میں نرم رویہ اختیار کرنا چاہیے۔ کیونکہ نرمی کرنے والے آدمی پر اللہ ذوالجلال رحم کرتا ہے، نرمی، عاجزی اور تواضع ایسے کیمیا نسخے ہیں کہ ان کے ذریعے دشمنوں کے دل بھی مسخر ہو جاتے ہیں، (١) خرید نے میں نرمی یہ ہے کہ قیمت میں نامناسب حد تک رعایت کا مطالبہ نہ کیا جائے۔ حتی الامکان نقد ادائیگی کی جائے، اگر دکان دار نامناسب رویہ اختیار کرے تو اس کے جواب میں تلخ کلامی نہ کی جائے۔ (٢) بیچنے والا آسانی کرے مطلب یہ ہے کہ قیمت میں مناسب رعایت دی جائے، ادھار لینے والے کو مہلت دی جائے، اگر خریدار نا مناسب حد تک رعایت طلب کرے تو جھگڑنے کی بجائے نرمی سے معذرت کر لی جائے، اگر خریدی ہوئی چیز گاہک واپس کریں تو واپس کر لے، یہ تقاضا کرنے میں نرمی ہے کسی کو قرض دیا تو واپس لینے میں نرمی سے تقاضا کرنا چاہیے، اگر وہ کوئی جائز عذر کرے تو عذر کو قبول کر کے مہلت دے دینی چاہیے۔ ٥٩٤٤","",{"k":"النبي سنن نسائی (٤٦٩٦)، سنن ابن ماجه (٢٢٠٢)، مسند احمد (١/٧٠)، بلفظ ادخل الله عزوجل، قال الشيخ الالباني: حسن۔"}],[5944,"سیدنا ہرمان بن زیاد البابلی ضیا اہلیہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو جوتے پہن کر نماز پڑھتے ہوئے دیکھا ہے۔“ یہ حدیث ہر ماس سے صرف اسی اسناد سے مروی ہے۔ اس میں عبد السلام بن ہاشم البز ار کا تفرد ہے۔","",{"k":"الزوائد (٢/٥٨)، مجمع، اسناده ضعيف۔","f":"مذکورہ روایت کی سند کمزور ہے۔ تاہم صحیح احادیث سے رسول اللہ صلی اللہ علیہ وسلم کا جوتیوں سمیت نماز پڑھنا ثابت ہے، جیسا کہ سیدنا انس بن مالک رضی اللہ عنہ سے پوچھا گیا: کیا نبی معظم ملنے سے تم اپنی جوتیاں پہن کر نماز پڑھتے تھے؟ تو انہوں نے فرمایا کہ ہاں۔ (صحیح بخاری، رقم: ٣٨٦)"}],[5945,"سیدہ عائشہ بنی السنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں فرمایا: ” نظر بد سے اللہ کی پناہ طلب کرو، کیونکہ وہ ( نظر کا لگ جانا ) حق ہے۔“ اس حدیث کو ابوسلمہ سے صرف ابو واقد الصالح بن محمد بن زایدہ نے روایت کیا۔ اس میں وہیب کا تفرد ہے۔","",{"k":"مستدرك حاكم (٤/٢١٥)، سلسلة صحيحة (٧٣٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نظر برحق ہے، عربی زبان میں نظر بد کو العین کہتے ہیں کہا جاتا ہے ((عان الرجل)) کہ اس نے فلاں شخص کو نظر لگا دی حتی کہ نظر بد کہ وجہ سے انسان موت کا شکار ہو جاتا ہے۔ جیسا کہ سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میری امت کے زیادہ تر لوگ قضا و قدر کے بعد نظر بد کے ذریعے موت کا شکار ہوں گے۔ (صحيح الجامع الصغير، رقم: ١٢٠٦، سلسله صحیحه، رقم: ٧٤٧) مذکورہ بالا حدیث میں ہے کہ نظر بد سے اللہ کی پناہ طلب کرو اس کے لیے بہترین عمل معوذتین ہیں۔ جیسا کہ سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں: نبی مکرم ملے ہم جن وانس کی برائی سے پناہ مانگا کرتے تھے، یہاں تک کہ معوذتین (سورہ فلق اور سورہ ناس) نازل ہو گئیں تو آپ صلی اللہ علیہ وسلم نے ٢ مو ان دونوں سورتوں کو اختیار کر لیا اور بقیہ تمام چیزوں کو چھوڑ دیا۔: (ترمذی، رقم: - صحيح الجامع الصغير، رقم: ٩٠٢)"}],[5946,"سیدنا سعد رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے پانچ درہم کی مالیت کی ڈھال کی چوری پر ہاتھ کاٹا۔“ اس حدیث کو ابو واقد سے صرف وہیب نے روایت کیا اور سعد رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ ٥٩٤٧","",{"k":"کر مجمع الزوائد: ٢٧٤/٦ اسناده ضعيف۔"}],[5947,"سیدنا عبداللہ ابن عمر بنی اہلیہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جو شخص حکمران کے پاس جائے تو وہ بھلی بات کرے ورنہ خاموش رہے۔ اس حدیث کو ابو واقد سے صرف وہیب نے روایت کیا۔","",{"k":"مجمع الزوائد (٢٣١/٥)، مجمع البحرين، رقم: ٢٥٨٤ سلسله ضعیفه (٤٥٨٧)، اسناده ضعيف۔"}],[5948,"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے کہا: السلام علیکم، آپ مالیے علیم نے اسے جواب دیا، پھر وہ بیٹھ گیا تو نبی نے ہیم نے فرمایا: ”دس۔“ پھر ایک اور آدمی آیا، اس نے کیا: السلام علیکم ورحمۃ اللہ، آپ صلی اللہ علیہ وسلم نے اسے جواب دیا، پھر وہ بیٹھ گیا تو نبی لئے علیم نے فرمایا: ” ہیں۔ پھر ایک اور آدمی آیا تو اس نے کہا: السلام علیکم ورحمۃ اللہ وبرکاتہ، آپ صلی اللہ علیہ وسلم نے اسے جواب دیا، پھر وہ بیٹھ گیا تو آپ ماے علی تم نے فرمایا: میں نیکیاں۔“ اس حدیث کو عوف سے صرف جعفر نے روایت کیا۔ اس میں محمد بن کثیر کا تفرد ہے اور سیدنا عمران بن حصین نبی الیہ سے صرف اسی اسناد سے مروی ہے۔ مذکوہ حدیث سے سلام کرنے کی فضیلت واضح ہوتی ہے، ہر کام پر دس نیکیاں ملتی ہیں یعنی جو صرف السلام علیکم کہے، اسے دس جو ساتھ ورحمتہ اللہ کا اضافہ کرے، اسے ہیں اور جو ساتھ وبرکاتہ کا کلمہ بھی ملائے تو اسے تمہیں نیکیاں ملتی ہیں۔ ٥٩٤٩","",{"k":"سنن ابو داود (٥١٩٥)، سنن ترمذی، رقم: ٢٦٨٩ قال الشيخ الالباني: صحيح۔"}],[5949,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، ہم نبی معظم مالے علم کے گرد بیٹھے ہوئے تھے کہ ایک آدمی آیا، اس نے کہا: السلام علیکم، نبی علینا نے فرمایا: ” دس نیکیاں۔‘“ پھر دوسرا شخص آیا تو اس نے کہا: السلام علیکم ورحمۃ اللہ تو نبی علیہ سلام نے فرمایا: ” ہیں۔ پھر ایک اور آدمی آیا تو اس نے کہا: ”السلام علیکم ورحمۃ اللہ وبرکاتہ۔ تو نبی ملنے یا تم نے فرمایا: میں نیکیاں۔“","",{"k":"فائده مجمع الزوائد (٣٤/٨)، مجمع البحرين (٣٠٢٦)۔"}],[5950,"سیدنا جابر بن عبد اللہ ضیا المیہ نے بیان کیا، نبی اے علی تم منبر بنائے جانے سے پہلے کھجور کے تنے کے پاس کھڑے ہوا کرتے تھے، جب منبر بنا لیا گیا تو وہ تنا رونے لگاحتیٰ کہ ہم نے اس کے رونے کی آواز سنی۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اس پر اپنا ہاتھ رکھا تو وہ خاموش ہو گیا۔ اس حدیث کو زہری سے صرف سلیمان بن کثیر نے روایت کیا۔ ٥٩٥١","",{"k":"ر مجمع البحرين (٩٨٥)۔"}],[5951,"سیدنا زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں: میری آنکھیں دکھنے لگیں تو نبی صلی اللہ علیہ وسلم نے میری عیادت کی اور آپ صلی اللہ علیہ وسلم نے فرمایا: \"زید! اگر تیری آنکھیں دکھیں تو تم کیا کرتے ہو؟“ انہوں نے کہا: میں صبر کرتا اور ثواب کی امید رکھتا ہوں، آپ ملنے سلیم نے فرمایا: \"زید! اگر تم اس آشوب چشم میں صبر کرو اور ثواب کی امید رکھو تو تمہیں ثواب میں جنت ملے گی۔ اس حدیث کو ابو اسحاق سے صرف اس کے بیٹے یونس نے روایت کیا۔ اس میں ابوقتیبہ کا تفرد ہے۔","",{"k":"سنن ابو داود (٣١٠٢)، قال الشيخ الالباني : حسن۔","f":"ماند. مذکورہ حدیث سے عیادت کی اہمیت کا اندازہ لگایا جا سکتا ہے کہ رسول اللہ علیم نے آنکھوں کے مریض کی بھی عیادت کی۔ (٢) معلوم ہوا کہ کوئی بھی تکلیف پہنچے تو انسان کو صبر کرنا چاہیے، کیونکہ تکلیف پر صبر کرنے کی وجہ سے اللہ ذوالجلال جنت عطا کریں گے۔ جیسا کہ ارشاد باری تعالیٰ ہے: وَجَزَاهُمْ بِمَا صَبَرُوا جَنَّةً وَحَرِيرًا﴾ (الدهر: ١٢) اور انہیں ان کے صبر کرنے کے عوض جنت اور ریشمی لباس کا بدلہ عطا فرمایا۔“"}],[5952,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں تھے کہ آپ صلی اللہ علیہ وسلم نے کسی کو اللہ اکبر، اللہ اکبر کہتے ہوئے سنا: ” تو آپ ملنے کریم نے فرمایا: ” فطرت پر ہے۔“ اس نے کہا: اشہد ان لا الہ الا اللہ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” جہنم سے آزاد ہو گیا۔“ صحابہ کرام بی ایم جلدی سے اس کی طرف گئے، دیکھا تو وہ بکریوں کا چرواہا تھا، نماز کا وقت ہوا تو اس نے اذان دی۔“ انده و صحیح مسلم میں مذکورہ بالا روایت سے پہلے یہ بھی ہے کہ سیدنا انس ولی اللہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح سویرے ہی دشمنوں پر حملہ کرتے تھے اور اذان کی آواز پر کان لگائے رکھتے تھے اور اگر مخالفوں کے شہر میں آپ صلی اللہ علیہ وسلم کو اذان کی آواز سنائی دیتی تو ان پر حملہ نہ کرتے تھے، امام مسلم نے باب باندھا ہے۔ باب الامساك عن الاغارة على قوم في دار الكفر اذا سمع فيهم الاذان . دارالکفر میں جب کسی قوم کو اذان دیتے سنا جائے تو ان پر غارت گری کرنے کی ممانعت۔ معلوم ہوا کہ اذان امن دینے کی علامت ہے۔ یہ بھی معلوم ہوا کہ خون کے معاملے میں بہت زیادہ احتیاط کرنی چاہیے، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم صرف اذان سننے پر ہی حملہ روک دیتے تھے۔ تکبیر کہنے پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: فطرت پر ہے، معلوم ہوا کہ منجم اوسط طبرانی - كم و دم مسلمان کے علاوہ کوئی بھی تکبیر نہیں کہتا، فطرت سے مراد اسلام ہے۔ ٥٩٥٣","",{"k":"صحیح مسلم (٣٨٢)۔"}],[5953,"سیدنا عبد اللہ ابن عم رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”وہ مومن جولوگوں کے ساتھ مل جل کر رہتا ہے اور ان کی ایذاؤں پر صبر کرتا ہے، اس مومن سے بہتر ہے جولوگوں کے ساتھ مل جل کر رہتا ہے نہ ان کی ایذاؤں پر صبر کرتا ہے۔ اس حدیث کو حصین سے صرف سفیان بن عیینہ نے روایت کیا۔ اس میں ابو یعلی التوزی کا تفرد ہے۔ ٥٩٥٤","",{"k":"کر سنن ترمذی (٢٥٠٧)، قال الشيخ الالباني: صحيح۔"}],[5954,"سیدنا ابوموسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم سب نگہبان ہو اور تم سب سے اس کی رعیت کے بارے میں باز پرس ہوگی۔ اس حدیث کو یزید سے صرف سفیان نے روایت کیا۔ اس میں الرمادی کا تفرد ہے۔ ٥٩٥٥","",{"k":"معجم کبیر (١١/٢٢٣)۔"}],[5955,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے دور میں اشیا کے نرخ بڑھ گئے تو انہوں نے عرض کیا: اللہ کے رسول! ہمارے لیے نرخ مقرر فرما دیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ نرخ مقرر کرنے والا ہے، میں امید کرتا ہوں کہ میں اللہ سے اس حال میں ملوں کہ تم میں سے کوئی دین و دنیا کے معاملے میں کسی حق کا مجھ سے مطالبہ نہ کرے۔ اس حدیث کو الحریری سے صرف عبد الاعلی نے روایت کیا اور سیدنا ابو سعید خدری رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔","",{"k":"سنن ابن ماجه كتاب التجارات (٢٢٠٠)، سنن ترمذی (١٣١٤)، قال الشيخ الالباني: صحيح۔"}],[5956,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رات کی تاریکی میں پیدل چل کر مساجد کی طرف آنے والوں کو قیامت کے دن کامل نور کی بشارت دے دو۔ “ اس حدیث کو ثابت سے صرف داود بن سلیمان نے روایت کیا۔ اس میں اس کے بیٹے سلیمان کا تفرد ہے۔","",{"k":"٥٩٥٦ الشيخ الالباني: صحيح . سنن ابن ماجه (٧٨١)، قال۔"}],[5957,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے اپنے رب سے درخواست کی کہ وہ آدم علینا کی اولاد میں سے جو بھولے نادان لوگ ہیں وہ میرے حوالے کر دے تو اس نے وہ میرے حوالے کر دیے۔“ اس حدیث کو زہری سے صرف عبد الرحمن بن اسحاق نے اور عبد الرحمن سے صرف فضیل بن سلیمان نے روایت کیا۔ اس میں عبد الرحمن بن المتوکل کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (٢١٩/٧)، صحيح الجامع (٣٥٩٢)، حسن۔"}],[5958,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حجاج نے انہیں بصرہ کا قاضی بنانا چاہا تو سیدنا انس رضی اللہ عنہ نے فرمایا: ”میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو قاضی بننے کا مطالبہ کرتا ہے اور اس پر مدد طلب کرتا ہے اسے اس کے نفس کے سپرد کر دیا جاتا ہے اور جو اس کا مطالبہ نہ کرے اور اس پر مدد طلب نہ کرے تو اللہ عزوجل ایک فرشتہ نازل فرماتا ہے وہ اس کی راہنمائی کرتا ہے۔ یہ حدیث سیدنا انس بنی ہونے سے صرف اسی اسناد سے مروی ہے۔ اس میں عبد الاعلی التعلمی کا تفرد ہے۔","",{"k":"سنن ابی داود (٣٥٧٨)، سنن ترمذی (١٣٢٣)، سنن ابن ماجه (٢٣٠٩)، قال الشيخ الالباني : ضعيف۔"}],[5959,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، تین آدمی نبی صلی اللہ علیہ وسلم کے پاس آئے تو پہلے نے کہا: السلام علیکم! تو نبی صلی اللہ علیہ وسلم نے اسے ان الفاظ کے ساتھ جواب دیا: ”سلام علیکم ورحمتہ اللہ “ دوسرا آیا تو اس نے کہا: السلام علیکم ورحمتہ اللہ تو نبی صلی اللہ علیہ وسلم نے اسے جواب دیا: ” سلام علیکم ورحمۃ اللہ وبرکاتہ “ تیسرا آیا تو اس نے کہا: السلام علیکم ورحمۃ اللہ و برکاتہ تو نبی صلی اللہ علیہ وسلم نے اسے جواب دیا: ”وعلیکم ابوالفتی ( تیسرے شخص کا والد ) نبی لئے علیم کے ساتھ بیٹھا ہوا تھا۔ اس نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فلاں اور فلاں کے سلام کا جواب دیتے ہوئے الفاظ کا اضافہ فرمایا، لیکن آپ سے تم نے میرے بیٹے کے سلام کے جواب میں کوئی اضافہ نہیں فرمایا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہم نے اس کے لیے مزید لفظ نہ پایا تو ہم نے اسے انہی الفاظ کے ساتھ جو اس نے کہے تھے جواب دے دیا۔ اس حدیث کو عکرمہ سے صرف نافع ابو ہرمز نے روایت کیا۔ اس میں عبد السلام بن مطہر کا تفرد ہے اور سیدنا عبداللہ ابن عباس نی این جا اسے صرف اس اسناد سے مروی ہے۔","",{"k":"كر مجمع الزوائد (٣٣/٨)، اسناده ضعيف۔"}],[5960,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سلیمان بن داود عالینا کے ہاں ایک بیٹا پیدا ہوا تو انہوں نے شیاطین سے کہا: ہم اسے موت سے کہاں چھپائیں؟ انہوں نے کہا: ہم اسے مشرق کی طرف لے جاتے ہیں، انہوں نے فرمایا: ”موت وہاں پہنچ جائے گی، انہوں نے کہا: مغرب کی طرف لے جاتے ہیں، انہوں نے فرمایا: ”موت وہاں بھی پہنچ جائے گی، انہوں نے کہا: سمندروں کی طرف لے جائیں، انہوں نے فرمایا: ”وہ وہاں بھی پہنچ جائے گی، انہوں نے کہا: ہم اسے آسمان اور زمین کے درمیان رکھ دیتے ہیں، ان کے پاس موت کا فرشتہ آیا تو اس نے کہا: ابن داود! مجھے ایک جان قبض کرنے کا حکم دیا گیا، میں نے اسے مشرق میں تلاش کیا، لیکن وہ مجھے نہ ملی، میں نے اسے مغرب میں تلاش کیا، لیکن وہ مجھے نہ ملی، میں نے اسے سمندروں میں تلاش کیا، میں نے اسے زمینوں کے درمیان حد فاصل میں تلاش کیا، لیکن میں نے اسے نہ پایا، اس اثناء میں کہ میں اوپر آسمانوں میں چڑھ رہا تھا کہ میں نے اسے پالیا تو میں نے اس کی روح قبض کر لی اور اس کا جسد آ گیا، حتیٰ کہ وہ ان کی کرسی پر آگرا، پس وہ اللہ عزوجل کا فرمان ہے: ”ہم نے سلیمان کا پینا کو آزمایا، ہم نے ایک جسدان کی کرسی پر ڈال دیا، پھر انہوں نے رجوع کیا۔‘‘ اس حدیث کو محمد بن عمرو سے صرف یحیی بن کثیر نے روایت کیا۔ اس میں ان کے بیٹے کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩٩/٧)، اسناده ضعیف۔"}],[5961,"سیدنا ابو بکر الصدیق رضی اللہ عنہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حرام سے نشوونما پانے والا جسم جنت میں نہیں جائے گا۔“ یہ حدیث سیدنا ابو بکر بنی لینے سے صرف اسی اسناد سے مروی ہے، اس میں عبد الواحد بن زید کا تفرد ہے۔ الله مذکورہ حدیث سے معلوم ہوا کہ انسان کو حرام کھانے سے اجتناب کرنا چاہیے، اسی طرح حرام پہنے سے بھی اجتناب کرنا چاہیے اور انسان کو پاکیزہ چیزیں کھانی چاہیے۔ جیسا کہ صحیح مسلم میں سیدنا ابو ہر یہ بیانیہ سے روایت ہے وہ بیان کرتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بلاشبہ اللہ پاک ہے وہ پاکیزگی کو قبول کرتا ہے اور اللہ ذوالجلال نے ایمان داروں کو ان باتوں کا حکم دیا ہے، جن کا اس نے پیغمبروں کو حکم دیا ہے، ارشاد باری تعالیٰ ہے: ياَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا (المؤمنون: ٥١) اے پیغمبرو! پاکیزہ چیزیں کھاؤ اور نیک عمل کرو۔“ نیز فرمایا: يَايُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَتِ مَا رَزَقْنكُمْ ﴾ (البقرة: ١٧٢) ”اے ایمان والو! جو پاکیزہ چیزیں رزق سے ہم نے تم کو عطا کی ہیں ان کو کھاؤ۔“ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس شخص کا ذکر کیا جو لمبا سفر طے کرتا ہے، اس کے بال پراگندہ ہیں، جسم خاک آلود ہے، وہ آسمان کی جانب اپنے ہاتھ اٹھاتا ہے اور یا رب یا رب پکارتا ہے، جب کہ اس کا کھانا حرام کا ہے. اس کا پینا حرام سے ہے، اس کا لباس حرام سے ہے، اس کی غذا حرام سے ہے۔ بھلا اس کی دعا کیسے قبول ہوگی؟ ٥٩٦٢","",{"k":"٥٩٦١ مجمع الزوائد (٢٩٦/١٠)، صحیح ترغیب و ترهیب (١٧٣٠)۔"}],[5962,"سیدنا ابو ہریرہ وانا الیہ بیان کرتے ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو شخص اپنا سر امام سے پہلے اٹھاتا ہے وہ اس سے ڈرتا نہیں کہ اللہ اس کے سر کو گدھے کے سر سے بدل ے۔ عبد اللہ بن یونس بن عبید نے حمار بن زید سے صرف اسی حدیث کو مسند روایت کیا ہے۔ ٥٩٦٣","",{"k":"صحیح بخاری (٦٩١)، صحيح مسلم (٤٢٧)۔"}],[5963,"سیدنا عمار بن یاسر رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے مجھے دیکھا جبکہ میں اپنے سامنے پڑے ہوئے چمڑے کے ڈول سے دو آدمیوں کو پانی پلا رہا تھا، پس میں نے بلغم نکالی تو میری بلغم میرے کپڑے پر لگ گئی، میں اپنے آگے پڑے ہوئے چمڑے کے ڈول سے اپنا کپڑا دھونے لگا تو نبی صلی اللہ علیہ وسلم نے فرمایا: عمار! تمہارا بلغم اور تمہاری آنکھوں کے آنسو ایسے ہیں جیسے تمہارے ڈول میں پانی ہے؟ تو بول و براز منی، خون اور قے وغیرہ لگ جانے سے اپنا کپڑا دھوؤ “ اس حدیث کو سعید بن المسیب سے صرف علی بن زید نے روایت کیا۔ اس میں ثابت بن حماد کا تفرد ہے۔ سیدنا عمار بن یاسر رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ ٥٩٦٤","",{"k":"مجمع الزوائد (١/٢٨٣)، مجمع البحرين (٥١٣)، اسناده ضعيف۔"}],[5964,"سیدنا عمران بن حصین نبی الیہ نے بیان کیا، ہم نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیا، آپ صلی اللہ علیہ وسلم نے رات کے آخری حصے میں آرام کے لیے قیام فرمایا، ( ہم سو گئے ) ہم بیدار ہوئے تو سورج طلوع ہو چکا تھا، آپ ملنے لگی تم نے فرمایا: ”کوچ کرو، کوچ کرو ہم نے کوچ کیا حتیٰ کہ جب سورج آسمان کے وسط میں تھا تو آپ مطلئے علیم نے سیدنا بلال بنی یہ کوحکم فرمایا اور ہم میں سے ہر آدمی نے دور کعتیں پڑھیں، پھر آپ مسلم نے ہمیں نماز پڑھائی تو ہم نے عرض کیا: اللہ کے رسول! کیا ہم کل اسے اس کے وقت پر دہرائیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا اللہ نے ہمیں سود سے منع فرمایا ہے، وہ اسے ہم سے قبول فرما لے گا؟“ اس حدیث کو سعید بن راشد سے صرف کثیر بن بیٹی نے روایت کیا۔ مذکورہ روایت کی سند کمزور ہے۔ تاہم اس کے شواہد صحیح مسلم میں موجود ہیں، (دیکھئے: مسلم، کتاب المساجد، باب قضاء الصلاة الخ: ٦٨٠) مذکورہ بالا حدیث سے معلوم ہوا کہ سوئے رہنے اور بھول جانے کا قصور معاف ہے۔ ایسی نمازوں کا وقت وہی ہے جب آدمی کو جاگ آ جائے یا اسے یاد آ جائے۔ یہ بھی معلوم ہوا کہ جب وقت نکل جائے تو شرعی عذر کے تحت تاخیر کر لینا بھی جائز ہے جیسا کہ نبی مکرم میم نے انگلی وادی میں جا کر نماز پڑھی۔ ٩٦٥","",{"k":"مجمع الزوائد (١/٣٢٢)، اسناده ضعيف۔"}],[5965,"سيدنا الجارود ابو المنذ رضی اللہ عنہ نے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے گم شدہ جانوروں کو پکڑ لینے کے متعلق سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان کا گم شدہ جانور پکڑ لینا جہنم میں SCCSC جلنا ہے۔ اس حدیث کو قتادہ سے صرف المثنی بن سعد نے اور المثنی سے صرف ابومعشر البراء نے روایت کیا۔ اس میں ابو کامل الجحد ی کا تفرد ہے۔","",{"k":"سنن ترمذى (١٨٨١)، قال الشيخ الالباني: صحيح لغيره (١٥٤٧)۔","f":"مذکورہ حدیث کا مطلب یہ ہے کہ اگر کسی کو کوئی جانور ملے تو اس کا مالک نہ بنے اگر اس کے مالک کو جانتا ہے تو مالک تک اس کو پہنچا دے اور اگر نہ جانتا ہو اور اس جانور کے تلف ہو جانے کا خطرہ ہو تو اس کو باندھ لے اور کھلی جگہ پر باندھے تا کہ اس کا مالک اگر اس کو تلاش کرتا ہوا آ جائے تو وہ اسے دیکھ لے یا اعلان کروا دے۔ لیکن اگر بڑا جانور ہے اور اس کے تلف ہونے کا خطرہ بھی نہ ہو تو اسے ہرگز نہ باندھے، ممکن ہے جانور خود ہی گھر کی راہ معلوم کرے، یا اس کا مالک اس کو تلاش کرتا ہوا پالے، لیکن اگر ایسا نہ کیا بلکہ اس کا ارادہ چھپانے کا ہے تو ایسا شخص جہنم کی آگ کی لپیٹ سے نہ بچ سکے گا۔"}],[5966,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے تو انتہائی فتیح صورت والا، بہت ہی برے کپڑوں والا، بہت بد بو والا انتہائی احمق شخص آیا، وہ لوگوں کی گردنیں پھلانگتا ہوا، رسول اللہ علیم کے سامنے آکر بیٹھ گیا تو اس نے کہا: آپ صلی اللہ علیہ وسلم کو کس نے پیدا کیا؟ آپ میم نے فرمایا: اللہ نے “ اس نے کہا: آسمان کس نے بنائے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ”اللہ نے “ اس نے کہا: زمین کو کس نے پیدا کیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ نے “ اس نے کہا: اللہ کو کس نے پیدا کیا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سبحان اللہ (اللہ پاک ہے دو مرتبہ فرمایا اور اپنی پیشانی پر ہاتھ رکھا، پس وہ آدمی کھڑا ہو اور چلا گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس آدمی کو میرے پاس لاؤ۔ پس ہم نے اسے تلاش کیا تو گویا وہ وہاں موجود نہ تھا، رسول اللہ میم نے فرمایا: ”یہ ابلیس ہے، وہ تمہارے دین کے بارے میں تمہیں شک میں مبتلا کرنے کے لیے آیا تھا۔“","",{"k":"مجمع الزوائد (١/٣٥)، مجمع البحرين (٧٣)، اسناده ضعیف۔"}],[5967,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، مکہ میں دو ا پانی تھے، ان دونوں کا ایک نوجوان بیٹا تھا، پس جب وہ صبح کرتا تو وہ انہیں منتقل کرتا اور انہیں مسجد میں لے آتا اور خود دن بھر ان کے لیے روزی کماتا، پس جب شام ہوتی تو وہ ان دونوں کو اٹھاتا، پس وہ انہیں واپس لے جاتا، رسول اللہ صلی اللہ علیہ وسلم نے اس نوجوان کو نہ دیکھا تو اس کے متعلق سوال کیا تو بتایا گیا کہ ان دونوں کا بیٹا فوت ہو گیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر کسی کو کسی دوسرے کے لیے چھوڑ دیا جاتا تو ان دونوں اپاہجوں کے بیٹے کو چھوڑ دیا جاتا۔“ ان دونوں حدیثوں کو عبد اللہ بن دینار سے صرف عبداللہ بن جعفر نے روایت کیا۔ ان دونوں میں ابو کامل الجحدری کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٣٢٣)، اسناده ضعيف۔"}],[5968,"سیدنا بلال رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: سورج اور چاند اللہ عزوجل کی نشانیوں میں سے دو نشانیاں ہیں۔ پس جب تم یہ ( گرہن ) دیکھو تو نماز کا سہارا لو۔‘ اس حدیث کو سیدنا بلال ریلی لینے سے صرف ابن ابی لیلی نے اور ابن ابی لیلیٰ سے صرف یزید نے روایت کیا۔ اس میں زیادہ بن عبد اللہ کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ سورج گرہن اور چاند گرہن کے وقت نماز پڑھنا مسنون ہے۔ تاہم کچھ فقہاء اس کو واجب اور کچھ سنت مؤکدہ کہتے ہیں۔ جمہور علماء کے نزدیک یہ سنت مؤکدہ ہے۔ (سبل السلام: ٦٩٠/٢) یہی موقف زیادہ راجح معلوم ہوتا ہے۔ (واللہ اعلم)","",{"k":"مجمع الزوائد (٢/٢٠٨)۔"}],[5969,"سيدنا ابو موسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر ایک آدمی کی گود (جھوٹی) میں درہم ہوں وہ انہیں تقسیم کرتا ہو، جبکہ دوسرا اللہ کا ذکر کرتا ہوتو اللہ کا ذکر کر نے والا افضل ہے۔“: ٥٩٧٠ یہ حدیث سیدنا ابو موسی نبی الیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عمر بن موسی کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (٧٧/١٠)، ضعيف الجامع الصغير (٤٨٠٤)، سلسله ضعیفه (٤٣٤٨)، اسناده ضعيف۔"}],[5970,"سیدنا عبد اللہ بن عمربی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص اپنے مال کی حفاظت کرتے ہوئے مارا جائے تو وہ شہید ہے۔“ اس حدیث کو ایوب اور خالد سے صرف وہیب نے روایت کیا۔ ٥٩٧١","",{"k":"سنن ابن ماجه (٢٥٨)، قال الشيخ الالباني: صحيح۔"}],[5971,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”امام تو اس لیے بنایا جاتا ہے کہ اس کی اقتدا کی جائے، جب وہ اللہ اکبر کہے تو تم اللہ اکبر کہو، تم اللہ اکبر نہ کہ حتی کہ وہ اللہ اکبر کہے، پس جب وہ رکوع کرے تم رکوع کرے اور تم رکوع نہ کر وحتی کہ وہ رکوع کرے اور جب وہ سمع اللہ لمن حمدہ کہے تو تم کہو: ربنا ولک الحمد۔ جب وہ سجدہ کرے تو تم سجدہ کرو اور تم سجدہ نہ کر وحتی کہ وہ سجدہ کرے، جب وہ اپنا سر اٹھائے تو تم سراٹھاؤ اور تم سر نہ اٹھاؤ حتی کہ وہ ( سجدے سے) سراٹھائے، اگر وہ بیٹھ کر نماز پڑھے تو تم سب بیٹھ کر نماز پڑھو۔“","",{"k":"صحیح بخاری (٧٢٢)، مسلم (٤١٤)۔"}],[5972,"سیدنا ابو ہریرہ بیانیہ سے روایت ہے کہ انہوں نے دن کے وقت کی کوئی نماز (ظہر الله یا عصر ) رسول اللہ علیم کے ساتھ پڑھی، آپ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں اور پھر سلام پھیر دیا، پس جلد باز حضرات مسجد سے نکل گئے، انہوں نے عرض کیا: اللہ کے رسول! کیا نماز کم کر دی گئی ہے؟ حاضرین میں سیدنا ابو بکر اور عمر بنی اچھا بھی موجود تھے، وہ آپ صلی اللہ علیہ وسلم سے بات کرنے سے گھبرائے تو وہاں سے ایک آدمی نے عرض کیا: اللہ کے رسول! کیا نماز کم کر دی گئی ہے، یا آپ بھول گئے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نماز کم کی گئی ہے نہ میں بھولا ہوں تو ایک آدمی نے عرض کیا: میرے والدین آپ مطلئے علیم پر قربان ہوں، آپ صلی اللہ علیہ وسلم بھول گئے ہیں، آپ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھائی ہیں، رسول اللہ علیم نے فرمایا: ”ذوالیدین جو کہہ رہا ہے کیا وہ درست ہے؟ انہوں نے عرض کیا: اللہ کے رسول! اس نے ٹھیک کہا ہے۔ پس آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور ان پہلی دو رکعتوں کے ساتھ دو رکعتیں پڑھیں، پھر سلام پھیر دیا، پھر نماز ہی کی طرح کے یا زیادہ طویل دو سجدے کیے۔“ اس حدیث کو طلحہ بن نضر الحمدانی سے صرف علی بن نصر اور یحیی بن ابی بکر الکرمانی نے روایت کیا۔ ٥٩٧٣","",{"k":"١٢٢٩ صحیح بخاری (١)، صحیح مسلم (٥٧٣)۔"}],[5973,"سیدنا سمرہ بنی اللہ نے بیان کیا، رسول اللہ سے ہم نے ہمیں منع فرمایا کہ عورت کی کسی ایسے شخص سے شادی کی جائے جس کے نکاح میں اس کی پھوپھی یا اس کی خالہ موجود ہو۔“‘ اس حدیث کو قتادہ سے: صرف ہمام نے اور ہمام سے صرف محمد بن بلال نے روایت کیا۔ اس میں محمد بن اسماعیل البخاری کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٦٦/٤)، مجمع البحرين (٢١٥٨)۔"}],[5974,"سیدہ عائشہ فی السنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اللہ نے جب آدم علینا کو زمین پر اتارا تو انہوں نے قبلہ رخ ہو کر دور کعتیں پڑھیں تو اللہ نے انہیں یہ دعا الہام کی: اے اللہ! تو میرے ظاہر و باطن کو جانتا ہے، میری معذرت قبول فرما تو میری حاجت جانتا ہے پس میری مانگ مجھے عطا فرما، جو میرے دل میں ہے تو اسے جانتا ہے، پس میری غلطی معاف فرما دے، اے اللہ! میں تجھ سے ایمان کا سوال کرتا ہوں جو میرے دل تک پہنچ جائے، یقین صادق عطا فرما حتی کہ میں جان لوں کہ مجھے وہی کچھ ملے گا جو تو نے میرے لیے لکھ دیا ہے اور جو تو نے میرے لیے تقسیم کر دیا ہے اس پر رضا مندی نصیب فرما، (اس دعا کے بعد ) اللہ نے ان کی طرف وحی کی: اے آدم! میں نے تیری توبہ قبول فرمائی، تیری غلطی معاف کر دی، جوشخص بھی اس دعا کے ساتھ مجھ سے دعا کرے گا میں اس کا گناہ بخش دوں گا، میں اس کے اہم کام سے اسے کفایت کر جاؤں گے، شیطان کو اس سے دور کر دوں گا اور ہر تاجر کے سامنے میں اس کے لیے تجارت کروں گا، دنیا اس کی طرف ذلیل ہو کر آئے گی، خواہ وہ اس کی طلب نہ بھی رکھتا ہو۔ اس حدیث کو ہشام بن عروہ سے صرف معاذ بن محمد نے روایت کیا، اس میں النضر بن طاہر کا تفرد ہے۔ ٥٩٧٥","",{"k":"مجمع الزوائد (١٠/١٨٣)، مجمع البحرين (٤٦٩٥)، اسناده ضعيف۔"}],[5975,"سیدنا شداد بن اوس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم اپنے قریب المرگ شخص کے پاس آؤ اور وہ فوت ہو جائے تو آنکھیں بند کر دو، کیونکہ نظر روح کے پیچھے جاتی ہے اور اچھی بات کرو، کیونکہ میت کے گھر والے جو بات کرتے ہیں فرشتے اس پر آمین کہتے ہیں۔“ یہ حدیث شداد بن اوس سے صرف اس اسناد سے مروی ہے۔ اس میں قرعہ بن سوید کا تفرد ہے۔","",{"k":"سنن ابن ماجه، رقم: ١٤٥٥ قال الشيخ الالباني: حسن . ٥٩٧٦۔"}],[5976,"سیدنا ابو امامہ الباہلی ویلا لینہ نے بیان کیا، رسول اللہ ملے سلیم نے فرمایا: ” ظالم قیامت کے دن آئے گا، حتی کہ جب وہ جہنم کے پل پر تاریکی اور دشواری میں ہوگا تو مظلوم اسے ملے گا، وہ اسے اور اس کے ساتھ جو ظلم کیا ہو گا اسے پہچان لے گا، پس مظلوم ظالموں سے بدلہ لیتے رہیں گے حتی کہ وہ ان کی ساری نیکیاں لے لیں گے، پس اگر ان کی نیکیاں نہ ہوئیں تو ان کے ظلم کے حساب سے ان (مظلوموں) کے گناہ لے کر ان ( ظالموں ) پر ڈال دیے جائیں گے، حتی کہ وہ جہنم کے انتہائی نچلے طبقے میں پہنچا دیے جائیں گے۔‘اس حدیث کو ایوب سے صرف حسین المعلم نے روایت کیا۔ اس میں ابن ابی عدی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٣٥٤)، مجمع البحرين (٤٨٠٠)، ضعیف ترغیب و ترهيب (٢١٠١)، سلسله ضعیفه (٥٣١٧)۔"}],[5977,"سیدنا ابو ذرضی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” نظر اللہ کے حکم سے بندے پر فریفتہ ہو جاتی ہے حتی کہ وہ مونڈتے ہوئے اوپر چڑھ جاتی ہے اور وہ ( آدمی اس حالت میں ) گر جاتا ہے۔“ یہ حدیث سیدنا ابو ذر رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں دیلم بن غزوان کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ نظر بد برحق ہے، کچھ لوگوں نے نظر بد کا انکار کیا ہے۔ لیکن ان کے رد کے لیے یہی کافی ہے کہ نبی معظم سے ہم نے اس کے وجود کی خبر دی ہے۔ یہ بھی معلوم ہوا کہ نظر: ٥٩٧٨ اللہ کے حکم سے لگتی ہے اللہ تعالیٰ کی مشیت اور ارادے کے بغیر کسی قسم کی تکلیف اور نقصان نہیں پہنچا سکتی۔","",{"k":"الزوائد: ١٠٦/٥ مج صحيح الجامع الصغير (١٦٨١)، سلسله صحیحه (٨٨٩)۔"}],[5978,"سیدنا ابو حرب یا سیدنا ابو الطفيل . نیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم سفر میں تھے، آپ صلی اللہ علیہ وسلم کے آگے آگے ایک آدمی تھا، وہ یہ دیکھتا تھا کہ کیا راستے میں کوئی ایسی چیز ہے جسے رسول اللہ صلی اللہ علیہ وسلم ناپسند کرتے ہوں تو وہ اس چیز کو راستے سے ہٹا دیتا تھا۔ پس اسے ایک بڑھیا ملی وہ ستر نہیں ڈھانپتی تھی۔ اس نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم تیرے نزدیک پہنچ چکے ہیں۔ پس اس نے اعراض کیا۔ انہوں نے اسے تین بار کہا: وہ ہر بار ان سے اعراض کرتی۔ اس نے کہا: اگر رسول اللہ صلی اللہ علیہ وسلم میرے قریب پہنچ چکے ہیں تو پھر تم مجھے کیا کہتے ہو؟ رسول اللہ صلی اللہ علیہ وسلم نے اس کی بات سن لی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کو چھوڑ دو، یہ تو سرکش ہے۔“ یہ حدیث سیدنا ابوطفیل رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں دیلم بن غزوان کا تفرد ہے۔ ٥٩٧٩","",{"k":"مجمع الزوائد (١/١١٠)، سنده ضعيف۔"}],[5979,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عزوجل قیامت کے دن فرمائے گا: میرے بندے نے تجھ سے کھانا طلب کیا تو نے اسے کھانا نہ کھلایا، اگر تو اسے کھانا کھلاتا تو میں تجھے کھلاتا، میرے بندے نے تجھ سے پانی طلب کیا، لیکن تو نے اسے پانی نہیں پلایا، اگر تو اسے پانی پلاتا تو میں تجھے پلاتا۔ اس حدیث کو سلام بن مسکین سے صرف طالوت بن عباد نے روایت کیا۔ مذکورہ حدیث سے ان لوگوں کی فضیلت واضح ہوتی ہے جو اللہ ذوالجلال کی ضرورت مند مخلوق کی خدمت کرتے ہیں اور خدمت کے عوض جو اللہ ذوالجلال ان کو جزا عطا فرمائے گا اس کا بھی اثبات ہوتا ہے۔ نیز اس میں اہل حاجات کے ساتھ حسن سلوک کرنے کی نہایت مؤثر اور بلیغ انداز میں تعلیم دی گئی ہے۔","",{"k":"مسلم (٢٥٦٩)۔"}],[5980,"سیدنا ابو قتادہ اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم میں سے کسی کو پسند ہے کہ اس کے کسی چہیتے کو آگ کا کنگن پہنایا جائے؟ انہوں نے عرض کیا: نہیں، آپ میم نے فرمایا: تم سونے کے زیور نہ پہنو، بلکہ چاندی کے ساتھ دل بہلاؤ۔ اس حدیث کو روایت نہیں کیا ذکورہ حدیث سے معلوم ہوا کہ سونے کے زیورات سے اجتناب کرنا چاہیے تا ہم چاندی کی اجازت ہے۔ امام ابو داؤد جماللہ اس روایت کو باب ما جاء في الذهب للنساء: کہ سونا عورتوں کے لیے ہے، کے تحت لائے ہیں، بعض علماء اس روایت سے استدلال کر کے کہتے ہیں کہ سونا عورتوں کے لیے بھی حرام ہے۔ لیکن پیچھے احادیث گزر چکی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عورتوں کو سونا پہننے کی اجازت دی ہے تو عورتوں کے لیے حرام کہنے والوں کے لیے یہ جواب ہے کہ منع والی روایات منسوخ ہیں۔","",{"k":"مجمع الزوائد (٥/١٤٧)، مسند احمد (٢/٣٧٨)۔"}],[5981,"سیدنا سعد رضی اللہ عنہ سے روایت ہے کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے قحط سالی کی شکایت کی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”گھٹنوں کے بل ہو کر یوں کہو: رب جی! رب جی! آپ صلی اللہ علیہ وسلم نے انگشت شہادت آسمان کی طرف بلند کی۔ پس انہوں نے اسی طرح کیا تو ان پر بارش ہوئی حتیٰ کہ انہوں نے چاہا کہ مطلع صاف ہو جائے (یعنی بارش تھم جائے۔ یہ حدیث سیدنا سعد ضیا الیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں محمد بن یحی الازدی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٢١٧)، سنده ضعیف۔"}],[5982,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ نبی سے ہم اکثر یہ دعا کیا کرتے تھے: تم ”اے اللہ! مجھے اپنے سے بہت زیادہ ڈرنے والا بنا دے حتی کہ یہ کیفیت ہو کہ میں تجھے ہمیشہ دیکھتا رہوں، حتی کہ میں تجھ سے ملاقات کروں، اپنے تقویٰ کے ذریعے مجھے سعادت مند بنا، اپنی معصیت کے ساتھ مجھے بد نصیب نہ بنا، اپنی قضا میں میرے لیے اختیار فرما، اپنی قدر میں میرے لیے برکت فرما، حتی کہ جس چیز کو مؤخر کرے میں اس میں جلدی کو پسند نہ کروں اور تو جسے جلدی کرے میں اس میں تاخیر پسند نہ کروں، میری غنا میرے دل میں پیدا فرما، میری سماعت و بصارت سے مجھے","",{"k":"مجمع الزوائد (١٠/١٧٨)، مجمع البحرين رقم: ٤٦٨٥ ضعيف الجامع الصغير (١١٦٥)، اسناده ضعيف . الله۔","f":"پہنچا۔ ان دونوں کو میری طرف سے وارث بنا، مجھ پر ظلم کرنے والے کے خلاف میری مدد فرما، اس میں مجھے میرا بدلہ دکھا اور اس کے ذریعے میری آنکھیں ٹھنڈی فرما۔ یہ حدیث عراک بن مالک سے صرف اسی اسناد سے مروی ہے۔ اس میں عمار بن طالوت کا تفرد ہے۔"}],[5983,"سیدنا جابر بن عبد اللہ صلی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے قبروں کو پختہ بنانے، ان پر عمارت بنانے اور ان پر ( مجاور بن کر بیٹھنے سے منع فرمایا ہے۔ اس حدیث کو اشعث سے صرف عدی بن الفضل نے روایت کیا۔ جامع ترمذی کی روایت میں یہ الفاظ ہیں، قبر پر لکھنے سے بھی منع فرمایا ہے،سنن نسائی میں یہ ہے کہ اس پر (قبر کی مٹی سے ) زائد مٹی ڈالنے سے بھی منع فرما دیا ہے۔ (ترمذی، رقم: ١٠٥٢) معلوم ہوا کہ قبر کو پختہ بنانا اور اسی طرح اس پر قبہ وغیرہ بنانا حرام ہے۔ قبر کے پاس یا قبرستان میں کسی ضرورت کے تحت بیٹھ جانے میں کوئی حرج نہیں، لیکن قبر کا مجاور بن کر بیٹھنا حرام ہے۔ اسی طرح قبر پر لکھنا بھی حرام ہے۔","",{"k":"صحیح مسلم (٩٧٠)، سنن ترمذی (١٠٥٢)۔"}],[5984,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے دور میں جب نماز کا وقت ہوتا تھا تو ایک آدمی دوڑ کر راستے کی طرف جاتا اور اعلان کرتا: نماز، نماز، پس یہ لوگوں پر گراں گزرا تو انہوں نے عرض کیا: اللہ کے رسول! اگر ہم ناقوس بنا لیں؟ آپ لے سلیم نے فرمایا: ”وہ عیسائیوں کے لیے ہے۔“ انہوں نے عرض کیا: اگر ہم بگل بنا لیں؟ آپ ملنے سلیم نے فرمایا: ”وہ یہود کے لیے ہے۔ پس سیدنا بلال ضیا یہ کو حکم دیا گیا کہ وہ اذان کے کلمات دو دو مرتبہ کہیں اور اقامت کے کلمات ایک ایک بار کہیں۔“ اس حدیث کو اہتمام کے ساتھ خالد الحذاء سے صرف روح بن عطا بن ابی میمونہ نے روایت کیا۔ اس میں محمد بن بیٹی القطعی کا تفرد ہے۔ نان اذان کی ابتدا ہجرت مدینہ کے بعد ہوئی۔ بعض روایات میں اگر چہ مکہ میں ہی ابتدائے اذان کا ذکر ہے۔ لیکن حافظ ابن حجر جاللہ فرماتے ہیں حق بات یہ ہے کہ ان روایات میں سے کچھ بھی ثابت نہیں۔ (فتح الباری: ٢٧٩/٢) اور سیدنا عبد اللہ بن زید رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے سامنے اپنا خواب بیان کیا، جس میں اذان کا ذکر تھا اور پھر سیدنا عم رضی اللہ عنہ نے بھی اسی طرح کا خواب دیکھنے کا ذکر کیا تو آپ صلی اللہ علیہ وسلم نے سیدنا بلال رضی اللہ عنہ کو اذان کہنے کا حکم دے دیا اور پھر آپ صلی اللہ علیہ وسلم کی وفات تک اذان کا سلسلہ جاری رہا۔ دیکھئے (فتح الباری: ٢/ - تحفة الاحوذي: ١/ ٥٨٩) مذکورہ بالا حدیث سے معلوم ہوا کہ یہود و نصاری کی مشابہت نہیں کرنی چاہیے بلکہ دین کے معاملات میں ان کی مخالفت کرنی چاہیے۔ یہ بھی معلوم ہوا کہ اذان کے کلمات دو دو مرتبہ اور اقامت کے کلمات ایک ایک مرتبہ کہنے چاہئیں۔ اس کی حکمت یہ بیان کی جاتی ہے کہ اذان چونکہ غیر حاضر لوگوں کو خبر دار کرنے کے لیے کہی جاتی ہے۔ اس لیے اس میں بلند آواز اور تکرار کی ضرورت ہوتی ہے۔ لیکن اس کے برخلاف اقامت حاضرین کو مطلع کرنے کے لیے کہی جاتی ہے، اس لیے اس میں تکرار کی ضرورت نہیں۔ (دوسری حدیث میں ہے کہ قد قامت الصلوة اقامت کے مکمل کلمات ایک ایک مرتبہ کہے۔ (دیکھئے:بخاری، رقم:۔ مسلم، رقم: ٣٧٨) قد قامت الصلوۃ۔ تحقیق نماز قائم ہوگئی، کے الفاظ دو مرتبہ اس لیے مسنون ہیں کیونکہ یہی تو اقامت کا مقصود ہیں۔ ٥٩٨٥","",{"k":"صحیح بخاری (٦٠٦)، صحيح مسلم (٣٧٨/٣)۔"}],[5985,"سیدنا معاویہ بن ابی سفیان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے چیتوں کی کھال پر (زین وغیرہ بنا کر ) سواری کرنے سے منع فرمایا ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ چیتوں اور اسی طرح تمام درندوں کی کھالیں رنگی ہوئی ہوں یا رنگی ہوئی نہ ہوں، ان کا استعمال کرنا جائز نہیں ہے۔ ٥٩٨٦","",{"k":"قال الشيخ الالباني: : صحيح . سنن ابو داود (٤١٢٩)، هم ٢٠٠٢۔"}],[5986,"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو جب نجاشی کی وفات کی خبر پہنچی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارا بھائی نجاشی فوت ہو گیا ہے، پس اس کی نماز جنازہ پڑھو۔“ پس آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور اس کی نماز جنازہ پڑھائی اور صحابہ کرام آپ ملنے کے پیچھے نماز پڑھی۔ ان دونوں حدیثوں کو خالد الحذاء سے صرف محبوب بن الحسن نے روایت کیا۔: ١٠/","",{"k":"مسلم (٩٥٣)۔"}],[5987,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یمن کے رہنے والے تمہارے پاس آئے ہیں، وہ نرم دل ہیں، ایمان یمن والے کا، دین کی سمجھ بوجھ یمن والوں میں ہے اور حکمت و دانائی بھی یمن کی ہے۔“ Sesi BIS","",{"k":"صحیح بخاری (٤٣٩٠)، مسلم (٥٢)۔"}],[5988,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”فخر و غرور گھوڑوں اور اونٹوں والوں میں ہوتا ہے، وقار وسکینت بکریوں والوں میں ہوتی ہے، متکبر ومغرور اونٹوں والے ہوتے ہیں۔ ان دونوں حدیثوں کو ابو مریم کے حوالے سے خالد الحذاء سے صرف یحیی بن المنذ رنے روایت کیا۔","",{"k":"صحیح بخاری (٣٣٠١)، مسلم (٥٢/٨٥)۔"}],[5989,"سیدنا ابو ہریرہ فی الینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں تمہیں کچھ برتنوں میں نبیذ بنانے سے منع کیا کرتا تھا، بے شک برتن کسی چیز کو حلال کرتے ہیں نہ اسے حرام کرتے ہیں، جن برتنوں میں تمہارا دل چاہے نبیذ بناؤ لیکن ہر نشہ آور چیز سے اجتناب کرو۔ اس حدیث کو خالد الحذاء سے صرف عمر بن حبیب نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوتا ہے کہ اب کسی بھی برتن میں نبیذ ہو اس کا پینا جائز ہے لیکن اگر نشہ آور مشروب ہو تو پھر کسی بھی برتن میں ہو جائز نہیں ہے۔","",{"k":"مجمع الزوائد (١٩/٤٤٣)۔"}],[5990,"سیدنا انس بن مالک نبی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص دنیا کی فکر میں لگا رہے اور اسی کا خواہش مند ہو وہی اس کا صح نظر ہو اور وہ اسی کی نیت و قصد کرتا ہوتو اللہ عز وجل فقر و محتاجگی اس کے پیش نظر کر دیتا ہے، اس کے امور کو منتشر کر دیتا ہے اور اس میں سے اسے اتنا ہی ملتا ہے جو اس کے مقدر میں لکھ دیا گیا ہے۔ اور جس کی فکر و کاوش اور جدوجہد آخرت کے لیے ہو، وہ اسی کی نیت کرتا ہو، اللہ تو نگری اس کے دل میں پیدا فرما دیتا ہے اور اس کے معاملات کو مجتمع کر دیتا ہے اور دنیا اس کے پاس ذلیل ہو کر چلی آتی ہے۔“ اس حدیث کو ہمام سے صرف داود بن الحبر نے روایت کیا۔ اس میں محمد بن یحی الازدی کا تفرد ہے۔ مذکورہ حدیث سے اخروی فکر اور دنیوی فکر رکھنے والے سے اللہ ذوالجلال کا جو معاملہ ہوتا ہے اس کا اثبات ہے، کیونکہ جو شخص دنیاوی دولت اور جاہ و حشمت کا طلب اور حریص ہوتا ہے وہ دنیا کے لیے بہت محنت کرتا ہے اسے جتنی بھی دولت ملے، مزید کی حرص کی وجہ سے وہ مطمئن نہیں ہوتا۔ آخرت کی طرف توجہ کرنے سے دنیا کی اہمیت کم ہو جاتی ہے، لہذا قناعت کی دولت حاصل ہو جاتی ہے اور بندہ مطمئن اور خوش کن زندگی گزارتا ہے اور اس کی زندگی میں نظم و ضبط پیدا ہو جاتا ہے جس سے کاروبار میں بہتر نتائج حاصل ہوتے ہیں اور رزق میں برکت ہوتی ہے اور اللہ ذوالجلال نے انسان کے لیے جو رزق رکھا ہے وہ حلال ذرائع اختیار کرنے سے بھی مل جاتا ہے۔ لہذا نا جائز طریقے اختیار کرنے سے بچنا چاہیے، کیونکہ اس میں پریشانیاں ہی پریشانیاں ہیں۔ ٩٩١","",{"k":"ووه و هو، لله ٥، کر مجمع الزوائد (٢٤٧/١٠)، صحیح ترغیب و ترهیب (١٧٠٧)، مجمع البحرين، رقم: ٤٩٢٨ . فائده۔"}],[5991,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے ایام مدینہ تشریف لائے، میں اس وقت آٹھ برس کا تھا، میری والدہ مجھے آپ کی خدمت میں لائیں تو انہوں نے عرض کیا: اللہ کے رسول! میرے علاوہ انصار کے خواتین وحضرات آپ صلی اللہ علیہ وسلم کو تحائف پیش کر چکے، آپ صلی اللہ علیہ وسلم کی خدمت میں تحفہ پیش کرنے کے لیے میرے پاس تو بس میرا یہ بیٹا ہی ہے، آپ ملنے مین میری طرف سے اسے قبول فرمائیں، جب تک آپ ملنے علی تیم چاہیں گے وہ آپ ملنے کی یمن کی خدمت کرے گا۔ انہوں نے کہا: میں نے رسول اللہ میم کی دس سال خدمت کی، آپ صلی اللہ علیہ وسلم نے مجھے مارا نہ مجھے برا بھلا کہا اور نہ ہی میرے چہرے پر شکن آنے دیے۔ (ہمیشہ خوش رکھا۔ ) آپ صلی اللہ علیہ وسلم نے مجھے پہلی پہلی یہ وصیت کی فرمایا: ”بیٹا! میرے راز افشاء نہ کرنا تم مومن بن جاؤ گے۔ پس میں نے آپ ملے لی ایم کا راز کبھی کسی کو نہیں بتایا، میری والدہ اور نبی صلی اللہ علیہ وسلم کی ازواج مطہرات بین این نے مجھ سے پوچھا لیکن میں نے آپ ملنے کے کام کے راز انہیں نہیں بتائے اور نہ ہی میں کبھی آپ ملنے کا راز کسی کو بتاؤں گا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”بیٹا! خوب اچھی طرح وضو کر تیری عمر دراز کر دی جائے گی اور تیری حفاظت کرنے والے دونوں تجھ سے محبت کریں گے۔‘ پھر فرمایا: ”بیٹا! اگر تو باوضو سونے کا اہتمام کر سکے تو کر، کیونکہ جسے وضو کی حالت میں موت آجائے اسے شہادت عطا کر دی جاتی ہے۔ پھر فرمایا: ”بیٹا! اگر تو مسلسل نماز پڑھتا رہے تو کر! کیونکہ جب تک تو نماز پڑھتا رہے گا، فرشتے تجھ پر رحمت نازل کرتے رہیں گے۔ پھر فرمایا: ”بیٹا! نماز میں ادھر ادھر دیکھنے سے اجتناب کر، کیونکہ نماز میں ادھر ادھر دیکھنا ہلاکت ہے، اگر ضرور ہی دیکھنا ہو تو صرف نوافل میں نہ کہ فرائض میں۔ پھر مجھے فرمایا: ”بیٹا! جب تو رکوع کرے تو اپنی ہتھیلیاں اپنے گھٹنوں پر رکھ، اپنی انگلیاں کشادہ رکھ، اپنے ہاتھ پہلوؤں سے دور رکھ، پس جب تو رکوع سے سر اٹھائے تو ہر عضو کو اپنی جگہ پر آنے دے، بے شک اللہ قیامت کے دن اس شخص کی طرف ( نظر رحمت سے ) نہیں دیکھے گا جو اپنی کمر سیدھی نہیں رکھتا۔ پھر مجھے فرمایا: ”بیٹا! جب تو سجدہ کرے تو اس طرح ٹھونگیں نہ مارنا جس طرح مرغ ٹھونگیں مارتا ہے اور اس طرح نہ بیٹھنا جس طرح کتا بیٹھتا ہے اور نہ ہی درندے کی طرح زمین پر اپنے بازو بچھانا، اپنے پاؤں کے ظاہری حصے کو زمین پر بچھانا اور اپنے سرین کو ایڑی پر رکھنا، بے شک یہ قیامت کے دن تمہارے حساب میں تم پر آسان ہوگا۔ پھر مجھے فرمایا: ” بیٹے اغسل جنابت خوب اچھی طرح کر ہتم غسل خانے سے نکلو گے تو تم پر کوئی گناہ ہو گا نہ کوئی خطا ہو گی۔ میں نے کہا: میرے والدین آپ ملے یہ تم پر قربان ہوں، خوب اچھی طرح غسل کرنے سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بالوں کی جڑیں تر ہو جائیں اور جسم صاف ہو جائے۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ” بیٹے! اگر تو اپنی نماز کا کچھ حصہ اپنے گھر میں پڑھ لے تو اس سے تمہارے گھر کی برکت میں اضافہ ہو جائے گا۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ” جب تو اپنے اہل خانہ کے پاس جائے تو سلام کر تم پر اور تمہارے گھر والوں پر برکت ہوگی۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ” بیٹے! جب تو اپنے گھر والوں سے آئے تو پھر اہل قبلہ میں سے جس شخص پر تیری نظر پڑے تو اسے سلام کر تو واپس آئے گا تو تیری نیکیاں بڑھ چکی ہوں گی۔ پھر فرمایا: ” بیٹے! اگر ہو سکے کہ تو اس حال میں صبح و شام کر کہ تیرے دل میں کسی کے لیے میل ( ناراضی ) نہ ہو تو ضرور کر۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ”بیٹے! یہ میری سنت ہے، پس جس نے میری سنت زندہ کی تو اس نے مجھ سے محبت کی اور جس نے مجھ سے محبت کی تو وہ جنت میں میرے ساتھ ہو گا۔ پھر آپ تم نے مجھے فرمایا: ” بیٹے! اگر تم نے میری وصیت یا درکھی تو پھر تجھے موت سے بڑھ کر کوئی اور چیز محبوب نہ ہو گی۔ اس حدیث کو اس اتمام کے ساتھ سعید بن مسیب سے صرف علی بن زید نے اور علی بن زید سے صرف عبد اللہ بن المثنی نے روایت کیا۔ اس میں مسلم بن حاتم کا الانصاری عن ابیہ سے تفرد ہے اور محمد بن الحسن بن ابی یزید کا عبادالمنقری سے تفرد ہے۔","",{"k":"معجم صغیر طبرانی (٢/٤٩٧، ٨٥٧)، مجمع البحرين (٨٤٥)، سنده ضعيف۔"}],[5992,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دو اوقات ایسے ہیں کہ ان میں طواف کرنے والوں کے گناہ بخش دیے جاتے ہیں، خواہ وہ گناہ جتنے بھی ہوں، صبح کی نماز کے بعد طواف جو طلوع آفتاب کے وقت مکمل ہو اور عصر کی نماز کے بعد طواف جو غروب آفتاب کے وقت ختم ہو۔“ انہوں نے عرض کیا: اللہ کے رسول! اگر اس سے پہلے اور اس کے بعد ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” وہ بھی اس کو مل جائے گا۔‘ اس حدیث کو سعید بن جبیر سے صرف زید العمی نے روایت کیا۔","",{"k":"مجمع الزوائد (٢٤٨/٣)، مجمع البحرين (١٧٣٢)، اسناده ضعيف۔"}],[5993,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اللہ کے ساتھ شریک ٹھہراتا ہے، جو کسی آدمی کو اس کی غلطی کے بغیر بادشاہ کے پاس لے جاتا ہے اور وہ اسے قتل کر دیتا ہے اور ایک وہ آدمی جو اپنے والدین کا نافرمان ہے، ایسے لوگوں کی جہنم کی آگ بجھے گی نہ ان کے کیڑے مریں گے اور نہ ہی ان کے عذاب میں کمی کی جائے گی۔ یہ حدیث سیدنا انس بنا لینے سے صرف اسی اسناد سے مروی ہے۔ اس میں عاصم بن منبع کا تفرد ہے۔ ٥٩٩٤","",{"k":"مجمع الزوائد (١/١٠٥)، مجمع البحرين (١٢٧)، اسناده ضعيف . ١٠٥/١۔"}],[5994,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، بنو کلب کا ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے آپ صلی اللہ علیہ وسلم سے نر کی مادہ سے جفتی کرانے کی اجرت کے بارے میں سوال کیا تو آپ مے تم نے اسے منع فرمایا، اس نے عرض کیا: اللہ کے رسول! ہم مفت جفتی کراتے ہیں تو ہماری تکریم ہوتی ہے، پس آپ صلی اللہ علیہ وسلم نے تکریم میں اس کے لیے رخصت دی۔“ كرامة، ایسے عطیے (یا ہدیے) کو کہتے ہیں جو بغیر شرط کے نر کی جفتی کے عوض (","",{"k":"سنن ترمذی (١٢٧٤)، قال الشيخ الالباني: صحيح۔","f":"حاصل کرنے والا مالک کے لیے ) پیش کرتا ہے۔ (روضة الندیه: ١٩٥/٢) ایک دوسری حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کی جفتی کے معاوضہ سے منع فرمایا ہے۔ (صحیح بخاری: ٢٢٨٤، ابو داود، رقم: ٣٤٢٩) مذکورہ حدیث سے معلوم ہوا کہ اجرت لینا درست نہیں ہے۔ علماء یہ کہتے ہیں کہ اگر با قاعدہ قیمت یا اجرت کا تعین کرنے کے بجائے اکرام کے تحت لین دین کا طریقہ رائج ہو جائے تو شرعاً اس پر اعتراض نہ ہوگا۔"}],[5995,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کسی بندے کو اہل یا مال یا اولاد کے حوالے سے کوئی نعمت عطا کرتا ہے اور وہ کہتا ہے: ماشاء اللہ، لاقوۃ الا رحمہ اللہ تو وہ اس میں موت سے پہلے کوئی آفت نہیں دیکھے گا۔ آپ اللہ تعالیٰ کے اس فرمان: ”جب تو اپنے باغ میں داخل ہوا تو تو نے یہ کہہ دیا ہوتا: ماشاء اللہ لاقوۃ الا رحمہ اللہ کی تفسیر بیان کرتے تھے۔ یہ حدیث سیدنا انس بنی اہلیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عمر بن یونس کا تفرد ہے۔","",{"k":"٥٩٩٥ مجمع الزوائد (١٠/١٤٠)، اسناده ضعيف۔"}],[5996,"سيدنا عمر بن خطاب رضی اللہ عنہ سے سانڈے، گوہ کی روایت کے بارے میں مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے اصحاب بھی ایم کی محفل میں تھے۔ کہ بنو سلیم کا ایک اعرابی آیا، اس نے ایک سانڈا شکار کیا تھا اور اسے اپنی آستین میں رکھا اور اسے اپنے قیام کی جگہ لے گیا۔ پس ایک جماعت دیکھی تو کہا: یہ جماعت کس پر اکٹھی ہے؟ انہوں نے کہا: اس شخص پر جو کہتا ہے کہ وہ نبی ہے، وہ لوگوں کو چیرتے ہوئے آگے پہنچا اور رسول اللہ علیم کی طرف متوجہ ہو کر کہنے گا: محمد ( صلی اللہ علیہ وسلم )! عور تیں تم سے بڑھ کر کسی جھوٹ بولنے والے اور سب سے زیادہ ناپسندیدہ شخص پر اکٹھی نہیں ہوئیں۔ اگر میری قوم کے لوگ مجھے جلد باز قرار نہ دیتے تو میں جلدی سے تمہیں قتل کر دیتا اور تمہارے قتل کرنے سے میں تمام لوگوں کو خوش کر دیتا۔سیدنا عم رضی اللہ عنہ نے عرض کیا، اللہ کے رسول! مجھے چھوڑ دیں میں اسے قتل کرتا ہوں۔ رسول اللہ سلیم نے فرمایا: ” کیا تمہیں معلوم ہے کہ بردبار شخص ہی نبی ہوسکتا ہے؟“ وہ پھر رسول اللہ تعلیم کو متوجہ ہو کر کہتا ہے: لات و عزیٰ کی قسم! میں تم پر ایمان نہیں لاؤں گا۔ رسول اللہ علیم نے فرمایا: ”اے اعرابی! تم نے جو کچھ کہا ہے، وہ سب ناحق ہے، لیکن ایسا کہنے پر کس چیز نے تمہیں آمادہ کیا ہے، جبکہ تم نے میری مجلس کی بھی عزت نہیں کی؟“ اس نے کہا: تم مجھ سے بات کرتے ہو۔ اس نے رسول اللہ صلی اللہ علیہ وسلم کا استخفاف کرتے ہوئے کہا: لات و عزیٰ کی قسم! میں تجھ پر ایمان نہیں لاؤں گا یا پھر یہ سانڈا تم پر ایمان لائے؟ پس اس نے اپنی آستین سے سانڈا نکالا اور اسے رسول اللہ صلی اللہ علیہ وسلم کے سامنے پھینک دیا اور کہا: اگر یہ سانڈا آپ پر ایمان لے آیا تو میں بھی آپ پر ایمان لے آؤں گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے سانڈے!‘ پس اس سانڈے نے واضح عربی زبان میں بات چیت کی، جسے وہ لوگ سمجھتے تھے۔ رب العالمین کے رسول! میں حاضر ہوں، رسول اللہ ملنے سلیم نے اسے کہا: ” تو کس کی عبادت کرتا ہے؟“ اس نے کہا: وہ جس کا عرش آسمان پر ہے، اس کی بادشاہت زمین پر ہے، سمندر میں اس کی راہ ہے، جنت میں اس کی رحمت ہے اور جہنم میں اس کا عذاب ہے، آپ نے فرمایا: ”اے سانڈے! میں کون ہوں؟ اس نے کہا: آپ رب العالمین کے رسول، خاتم النبیین ہیں، جس نے آپ صلی اللہ علیہ وسلم کی تصدیق کی وہ کامیاب ہو گیا اور جس نے آپ صلی اللہ علیہ وسلم کی تکذیب کی وہ ناکام و نامراد ہوا۔ اس اعرابی نے کہا: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ آپ اللہ کے سچے رسول ہیں، جب میں آپ صلی اللہ علیہ وسلم کے پاس آیا تھا تو روئے زمین پر میرے نزدیک آپ صلی اللہ علیہ وسلم سے زیادہ ناپسندیدہ شخص کوئی نہ تھا، اللہ کی قسم! اس وقت آپ صلی اللہ علیہ وسلم مجھے میری جان سے اور میرے والدین سے بھی زیادہ محبوب ہیں، میں دل و جان سے اور اپنے انگ انگ سے آپ صلی اللہ علیہ وسلم پر ظاہر و باطن اور اندرونی و بیرونی حوالے سے آپ ملے لی تم پر ایمان لا چکا ہوں، رسول اللہ علیم نے اسے فرمایا: ”ہر قسم کی تعریف اللہ کے لیے ہے جس نے اس دین کی طرف تیری راہنمائی فرمائی جو دین غالب آئے گا مغلوب نہیں ہو گا، اللہ اسے نماز کے بغیر قبول نہیں کرتا اور نماز کو قرآن کے بغیر قبول نہیں کرتا۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اسے سورۃ الفاتحہ اور سورۃ الاخلاص کی تعلیم دی تو اس نے عرض کیا: اللہ کے رسول! میں نے اس سے بہتر کلام نثر میں سنا ہے، نہ اشعار میں۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: 'یہ رب العالمین کا کلام ہے، کوئی شعر نہیں، جو تو ایک مرتبہ سورۃ الاخلاص پڑھے گا تو گویا تم نے تہائی قرآن پڑھا، جب تو نے دو مرتبہ سورۃ الاخلاص پڑھی تو گویا تو نے دو تہائی قرآن پڑھا اور جب تو نے تین بار سورۃ الاخلاص پڑھی تو گویا تو نے پورا قرآن پڑھا۔“ اس اعرابی نے کہا: ہمارا معبود بہترین معبود ہے، وہ تھوڑا سا عمل قبول فرمالیتا ہے اور بہت سا اجر عطا فرما دیتا ہے۔“ رسول اللہ لئے علیم نے فرمایا: اعرابی کو عطا کرو۔ پس انہوں نے اسے عطا کیا حتی کہ انہوں نے اسے ناقابل برداشت عطا کر دیا۔ پس سیدنا عبد الرحمن بن عوف رضا الیہ کھڑے ہوئے اور عرض کیا: اللہ کے رسول! میں اللہ کی رضا کے لیے اسے ایک اونٹنی دیتا ہوں جو بختی اونتوں سے کم اور اعرابی سے بڑی ہے اور وہ دس ماہ کی حاملہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ''تم نے جو دینا تھا اس کا وصف بیان کیا، اللہ تمہیں جو بدلہ عطا فرمائے گا میں اس کا تمہیں وصف بیان کرتا ہوں؟ انہوں نے عرض کیا: جی ہاں، آپ نے فرمایا: ”تمہارے لیے خول دار موتی کی اونٹنی ہے، اس کی ٹانگیں سبز زمرد کی ہیں، اس کی گردن پہلے زبرجد کی ہے، اس پر ایک ہو وج ہے اور ہووج پر سندس واستبرق کا ریشم ہے، وہ راستے (پل صراط پر بجلی چمکنے کی طرح گزر جائے گی۔ پس وہ اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو ہزار اونٹوں پر، ہزار اعرابی، ہزار نیزے اور ہزار تلوار میں لیے ہوئے اسے ملے تو اس نے انہیں کہا: کہاں کا ارادہ ہے؟ انہوں نے کہا: ہم اس شخص سے لڑنے کا ارادہ رکھتے ہیں جو جھوٹ بولتا ہے اور وہ کہتا ہے کہ وہ نبی ہے۔ اس اعرابی نے کہا: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ محمد ( ملے عام ) اللہ کے رسول ہیں۔ انہوں نے اسے کہا: تو بے دین ہو گیا ہے؟ اس نے کہا: میں بے دین نہیں ہوا اور اس نے انہیں واقعہ بیان کیا تو ان سب نے کہا: لَا إِلَهَ إِلَّا اللهُ مُحَمَّدٌ رَّسُولُ اللهِ، پس نبی صلی اللہ علیہ وسلم کو اس کی خبر پہنچی تو آپ نے بغیر چادر کے ان سے ملاقات کی، وہ اپنی سواریوں سے اترے اور کہنے لگے: AND AT ALL ANDAN اللهُ مُحَمَّدٌ رَّسُوْلُ اللهِ انہوں نے GALA GALANA عرض کیا: ہمیں ایسا امر بتا ئیں جسے رسول اللہ صلی اللہ علیہ وسلم پسند کرتے ہوں، آپ نے فرمایا: ”تم خالد بن ولید کے پرچم تلے چلے جاؤ۔ راوی نے بیان کیا، بنو سلیم کے علاوہ عرب کے کسی قبیلے سے اکٹھے ایک ہزار افراد مسلمان نہیں ہوئے۔ اس حدیث کو داود بن ابی ہند سے اس اتمام کے ساتھ صرف کہمس نے اور کہمس سے صرف معتمر نے روایت کیا۔ اس میں محمد بن عبد الاعلیٰ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨/٢٩٢)، مجمع البحرين (٣٥٤١)، اسناده ضعيف۔"}],[5997,"سیدنا ابن ابی اوفی ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قربانی کا دن حج اکبر کا دن ہے۔“ اس حدیث کو الشیبانی سے مرفوعاً صرف حفص بن عمر نے روایت کیا۔ اس میں محمد بن بکار کا تفرد ہے۔ ارشاد باری تعالی ہے: وَآذَانٌ مِنَ اللهِ وَرَسُولِةٍ إِلَى النَّاسِ يَوْمَ الْحَجَّ الْأَكْبَرِ ﴾ (التوبه:٣) اللہ اور اس کے رسول کی طرف سے لوگوں کو بڑے حج کے دن صاف اطلاع ہے۔“ معلوم ہوا کہ حج اکبر سے مراد حج ہے، اسے اس لیے حج اکبر کہتے ہیں، کیونکہ ١٠ ذوالحجہ کو حج کے سب سے زیادہ اہم مناسک ادا کئے جاتے ہیں۔ اور عوام عمرے کو حج اصغر کہا کرتے تھے تو اس لیے عمرے سے ممتاز کرنے کے لیے حج کو حج اکبر کہا گیا۔ مذکورہ بالا حدیث سے عوام الناس کی اس بات کی بھی تردید ہوتی ہے جو کہتے ہیں کہ جمعہ والے دن جو حج ہو وہ حج اکبر ہے۔ بلکہ ہر حج حج اکبر ہے، خواہ وہ کسی بھی روز ہو، جمعہ کے روز یوم عرفہ کا واقع ہونا ایک اتفاق امر ہے اور اللہ ذوالجلال کے ہاں قبولیت میں کوئی فرق نہیں۔","",{"k":"صحیح بخاری، مجمع الزوائد (٢٦٣/٣)، سنن ابو داود (٦٤٥)، مسلم (١٣٤٧)، مجمع البحرين (١٧٨٠)۔"}],[5998,"سیدنا بریدہ نیل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تین کام جفاء کے زمرے میں آتے ہیں: آدمی کا نماز سے فارغ ہونے سے پہلے اپنے چہرے سے مٹی صاف کرنا، نماز کے دوران چہرے کی جگہ سے پھونک مار کر مٹی اڑانا اور کھڑے ہو کر پیشاب کرنا۔“ یہ حدیث سیدنا بریدہ رضی لینے سے صرف اس اسناد سے مروی ہے۔ اس میں ابو عبیدہ الحداد کا تفرد ہے۔ ٥٩٩٩","",{"k":"مجمع الزوائد (٨٣/٢)، ضعيف الجامع الصغير (٢٥٣٥)۔"}],[5999,"سیدنا ابو مسعود البدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم میں سے کوئی رات میں تہائی قرآن پڑھنے سے عاجز ہے؟ انہوں نے عرض کیا: اللہ کے رسول! کیا وہ تہائی قرآن پڑھ سکتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم میں سے کوئی سورۃ الاخلاص پڑھنے سے عاجز ہے۔“ اس حدیث کو محمد بن جمادہ سے صرف الحسن بن ابی جعفر نے اور الحسن سے صرف ابو جابر نے روایت کیا۔ اس میں ابو حاتم السجستانی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ رات کو سورۂ اخلاص کی تلاوت کر کے سونا چاہیے۔ نیز سورۃ اخلاص کی تلاوت کی بھی فضیلت واضح ہے۔","",{"k":"طبرانی کبیر (٩/٥٧)۔"}],[6000,"سیدہ عائشہ بنی الجھا نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جو شخص دن میں مدینے کی سات عجوہ کھجوریں کھا لیتا ہے تو اس روز زہر اس کے لیے مضر نہیں ہوگی اور جو انہیں رات کے وقت کھا لیتا ہے تو زہر اس کے لیے مضر نہیں ہو گی۔ یہ حدیث سیدنا انس بنی اہلیہ کے حوالے سے سیدہ عائشہ بنی النیہا سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن یحیی القطعی کا تفرد ہے۔ اور سلیمان بن بلال وغیرہ نے اسے عبد اللہ بن عبد الرحمن بن معمر ابی طوالہ عن عامر بن سعد، عن ابیہ کی سند سے روایت کیا ہے۔ مذکورہ حدیث سے معلوم ہوا کہ صبح و شام عجوہ کھجور کھانے کی وجہ سے انسان اس دن زہر سے بچ جاتا ہے۔ صحیح بخاری و مسلم میں ہے کہ جس شخص نے صبح سات عجوہ کھجور میں کھا لیں اس دن اس پر زہر اور جادو کا اثر نہیں ہوسکتا۔ (صحیح بخاری، کتاب الطب، رقم: ٥٧٦٩، مسلم، رقم: ٢٠٤٧) ابن لولون طب نبوی کے موضوع پر اپنی کتاب میں لکھتے ہیں: عجوہ مدینہ کی کھجوروں میں سے ایک کھجور ہے جو صیحانی سے بڑی اور سیاہی مائل ہے۔ اس کھجور کو نبی مکرم ملتے ہم نے خود لگایا تھا اور شاید یہ اتنے سارے","",{"k":"مجمع الزوائد (٥/٨٢)، سلسله صحيحه (٢٠٠)، مجمع البحرين (٤١٧٩)۔","f":"آپ صلی اللہ علیہ وسلم کے لگانے کی برکت کی وجہ سے ہیں۔ (طب نبوی ابن لولون، ص: (١٩٠) امام خطابی اللہ نے فرمایا: عجوہ کی وجہ سے زہر اور جادو کا اثر نہ کرنا، یہ مدینہ کی کھجور کے لیے نبی میم کی دعاء برکت کی وجہ سے ہے، کھجور کی خاصیت نہیں ہے۔ (فتح الباری: ١٠/ ٢٥٠)"}],[6001,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”میرے نام پر نام رکھو اور میری کنیت پر کنیت نہ رکھو۔ اس حدیث کو سلمہ بن علقمہ سے صرف ابن ابی عدی نے روایت کیا۔ اس میں احمد بن عبد اللہ کر دی کا تفرد ہے۔ نبی مکرم نے یمن کی زندگی میں یہ ممانعت تھی، آپ صلی اللہ علیہ وسلم کے بعد علماء نے اجازت دے دی ہے۔ اب نبی مکرم ملے تعلیم کا نام اور کنیت دونوں رکھے جا سکتے ہیں۔ زندگی میں ممانعت کی وجہ یہ واقعہ تھا کہ ایک مرتبہ نبی مکرم لئے علیم بازار میں تھے کہ ایک شخص نے ابو القاسم کہہ کر آواز دی۔ آپ صلی اللہ علیہ وسلم نے پیچھے مڑ کر دیکھا تو آواز دینے والے نے کہا کہ میں نے آپ صلی اللہ علیہ وسلم کو آواز نہیں دی۔ میں نے فلاں شخص کو آواز دی ہے، اس واقعے کے بعد آپ صلی اللہ علیہ وسلم نے اپنی کنیت پر کنیت رکھنے سے روک دیا۔ (فتح الباری، حدیث: ٦١٨٨) ٦٠٠٢","",{"k":"صحیح بخاری (٣٥٣٩)، صحیح مسلم، رقم:٢١٣٤ . الله۔"}],[6002,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی ڈھیلوں سے استنجا کرے تو وہ طاق عدد میں ڈھیلے استعمال کرے، کیونکہ اللہ طاق ( یکتا ) ہے اور وہ طاق ہی کو پسند کرتا ہے۔“ اس حدیث کو ابو عامر الخزاز سے صرف روح نے روایت کیا۔ اس میں ابن بسطام کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ طاق عدد ڈھیلوں سے استنجا کرنا چاہیے، کم از کم تین ڈھیلے، اگر صفائی نہ ہو تو پھر پانچ، سات، وغیرہ۔ اللہ ذوالجلال وتر ہے اس کا مطلب یہ ہے کہ اللہ تعالیٰ اپنی ذات وصفات میں یکتا ہے اور وہی ایک ایسی ذات ہے جو عبادت کے لائق ہے۔","",{"k":"صحیح بخاری (١٦١)، صحيح مسلم (٢٢٧)، صحيح الجامع الصغير (١٨٣٠)۔"}],[6003,"و سیدہ عائشہ نونی انہما نے بیان کیا، سیدنا عثمان رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس آئے تو دونوں نے دیر تک سرگوشی کی، میں ان دونوں سے پرے تھی، پس اس بات نے مجھے چونکا دیا کہ سیدنا عثمان رضی اللہ عنہ کے بل بیٹھے ہیں اور کہہ رہے ہیں: اللہ کے رسول! ظلم و زیادتی کے طور پر؟ پس میں سمجھ گئی کہ آپ نے ان کے قتل کیے جانے کے متعلق انہیں بتایا ہے۔ اس حدیث کو ابوسعید المؤدب محمد بن مسلم بن ابی الوضاح نے روایت کیا۔ اس میں منصور بن ابی مزاحم کا تفرد ہے۔ ٦٠٠٤","",{"k":"مجمع الزوائد (٩/٩٠)، مجمع البحرين (٣٦٨٦)۔"}],[6004,"سیدہ عائشہ نبی یا لوہا نے بیان کیا، نبی صلی اللہ علیہ وسلم نے اختیار دیا تھا، لیکن وہ طلاق نہ تھی۔“ اس حدیث کو اشعث سے صرف خالد بن الحارث نے روایت کیا۔ اس میں ابن صدران کا تفرد ہے۔","",{"k":"صحیح بخاری، مسلم (١٤٧٧)۔"}],[6005,"سیدہ عائشہ بنی انا نے فرمایا: \"رسول اللہ صلی اللہ علیہ وسلم دیہاتی طرز زندگی بھی اختیار کیا کرتے تھے۔ اس حدیث کو ابو بردہ سے صرف برید نے اور برید سے صرف شریک نے اور شریک سے ابراہیم بن سعد نے اور ابراہیم بن سعد سے صرف محمد بن عباد نے روایت کیا۔ اس میں نصر بن علی کا تفرد ہے۔ ٦٠٠٦",""],[6006,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی لئے علیم نے فرمایا: «علیین کے مقام والوں میں سے ایک آدمی جنتیوں پر نظر ڈالے گا گویا کہ وہ چمکتا ہوا ستارہ ہے۔ بے شک سیدنا ابو بکر وسیدنا عمر بنا ہے ان میں سے ہیں بلکہ وہ دونوں ان میں سے سب سے زیادہ افضل ہیں۔“ یہ حدیث الشعمی سے صرف یونس بن ابی اسحاق نے روایت کیا۔اس میں ابوقتیبہ مسلم بن قتیبہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩/٥٧)، مجمع البحرين (٣٦٤٣)، سنده ضعيف۔"}],[6007,"سیدہ ام سلمہ رولی الیشیا نے بیان کیا، رسول اللہ سلیم نے فرمایا: ” میں اس عورت کو نا پسند کرتا ہوں جو اپنے گھر سے دامن گھسیٹتی ہوئی نکلتی ہے اور اپنے شوہر کا شکوہ کرتی ہے۔“ اس حدیث کو سیدہ ام سلمہ فی النھما سے صرف اسی اسناد سے مروی ہے۔ اس میں بیٹی بن یعلی الاسلمی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣١٦/٤)، ضعيف الجامع الصغير (٢٠٩٤)، مجمع البحرين (٢٣٢٣)، سلسله ضعيفه (٢٠٦٣)۔"}],[6008,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کے پاس دو کپڑے ہوں تو وہ انہیں پہن لے اور جس کے پاس ایک کپڑا ہو تو وہ اسے ازار بنالے اور وہ یہودیوں کی طرح کپڑا نہ اوڑھے ( وہ اس طرح کہ کوئی شخص اپنا کپڑا اپنے سر یا اپنے کندھے پر رکھ کر اس کے کنارے دونوں طرف چھوڑ دے اس سے ستر نگا ہو جاتا ہے )۔‘ اس حدیث کو علی بن ثابت سے صرف اس کے بھائی عزرہ نے اور ان سے صرف ابو بحر البکر اوی نے روایت کیا۔ اس میں محمد بن عبد اللہ بن بزیع کا تفرد ہے۔: وهو","",{"k":"کر ابن عدی (٢٠/٢١٦، ١١٤٢٤)۔"}],[6009,"سیدنا علی ولی ال یونین نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے مذی کے متعلق مسئلہ دریافت کیا تو آپ مطلئے علیم نے فرمایا: ”اس صورت میں وضو ہے۔ اور میں نے آپ صلی اللہ علیہ وسلم سے منی کے متعلق پوچھا تو آپ سے تم نے فرمایا: ”اس میں غسل ہے۔ اس حدیث کو زفر سے صرف ابوعلی الھی نے روایت کیا۔ اس میں ابوحفص کا تفرد ہے۔ خروج پر غسل فرض ہے۔: ٦٠١٠ مذکورہ حدیث سے معلوم ہوا کہ مذی کے خروج پر غسل نہیں، بلکہ وضو ہے اور منی کے","",{"k":"صحیح بخاری (١٣٢)، صحیح مسلم (٣٠٣)۔"}],[6010,"سیدنا عمرو بن تغلب رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” قیامت سے پہلے تم ایسے لوگوں سے قتال کرو گے جو بالوں کے بنے ہوئے جوتے پہنتے ہیں اور دوسرے وہ لوگ گویا کہ ان کے چہرے ڈھالوں کی طرح ہیں۔ اس حدیث کو ابو حمزہ العطار سے صرف محمد بن عباد نے روایت کیا۔ اس میں زفر بن علی کا تفرد ہے۔","",{"k":"صحیح مسلم (٢٩١٢)۔","f":"مذکورہ حدیث سے مراد ترک ہیں، کیونکہ ان کے چہرے پر گوشت، گول اور چوڑے ہوتے ہیں۔ اس میں جو قتال کا تذکرہ ہے یہ ان کے قبول اسلام سے پہلے کی بات ہے۔ یہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانے اور خلفائے اسلام کے زمانوں تک کافر رہے، یہاں تک کہ ہلاکو خاں ترک نے عربوں پر چڑھائی کر کے خلافت عباسیہ کا کام تمام کیا، ان کے بعد کچھ ترک مشرف باسلام ہوئے۔ ٦٠١١"}],[6011,"سیدنا حکیم بن حزام رضی اللہ عنہ نے بیان کیا، رسول اللہ علی علیم نے مجھے ایسی چیز کی بیع سے منع فرمایا جو میرے پاس موجود نہ ہو۔“: . دیکھئے حدیث وفوائد نمبر","",{"k":"قال الشيخ الالباني صحيح . سنن ابو داود، رقم: ٣٥٠٣۔۔"}],[6012,"سیدنا ابو بکرہ ضل النشینی نے بیان کیا کہ میں نے رسول اللہ سلم کو فرماتے ہوئے سنا: قریب ہے کہ لوگوں پر ایسا وقت بھی آئے گا کہ وہ اس وقت نیکی کا حکم کریں گے، نہ برائی سے منع کریں گے۔“ اس حدیث کو ابی کعب سے صرف بسطام بن حبیب نے روایت کیا۔ اس میں داود بن رشید کا تفرد ہے۔ سیدنا ابو بکرہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٢٨٣/٧)۔"}],[6013,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن میری شفاعت اس شخص کے لیے ہے جو گواہی دے کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ میں اللہ کا رسول ہوں۔ ان دونوں حدیثوں کو اُبی کعب سے صرف قرہ بن حبیب نے روایت کیا۔","",{"k":"٦٠١٣ ووه و لر بخاری (٧٥١٠)، صحیح مسلم (٩٣/٣٢٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم موحد لوگوں کے لیے سفارش کریں گے، اگر چہ وہ گناہ گار ہی کیوں نہ ہوں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں اپنی امت کے ان لوگوں کی سفارش کروں گا جو کبیرہ گناہوں کے مرتکب ہوئے ہوں گے۔ لیکن کس کا عقیدہ درست نہ ہوا مشرک ہوا، اس کے لیے نبی صلی اللہ علیہ وسلم سفارش نہیں کریں گے۔ جیسا کہ ارشاد باری تعالیٰ ہے: مَا كَانَ لِلنَّبِي وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِيْنَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَبُ الْجَحِيمِ ﴾ (التوبه: ١١٣) نبی ( اے ایم ) کو اور جو لوگ ایمان لائے ہیں، اس بات کی اجازت نہیں کہ مشرکوں کے لیے بخشش مانگیں، چاہے وہ ان کے قریبی رشتہ دار ہی کیوں نہ ہوں، جب کہ ان پر یہ بات کھل چکی ہے کہ وہ جہنم والے ہیں۔“ اسی طرح سیدنا نوح کا ئیسلام نے اپنے مشرک بیٹے کے لیے سفارش کی، لیکن ان کی سفارش کو قبول نہیں کیا گیا۔ ( سوره هود: آیت نمبر ٤٥ - ٤٧) ٦٠١٤"}],[6014,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” قرآن والو! وتر پڑھو۔ “ اس حدیث کو یحیی بن ابی کثیر سے صرف ابان نے روایت کیا۔ اس میں حبان بن ہلال کا تفرد ہے۔ نان و سنن ابی داود میں ہے: سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے اہل قرآن وتر پڑھا کرو کیونکہ اللہ وتر ہے اور وتر کو پسند فرماتا ہے، (ابو داؤد، رقم: ١٤١٦) اہل قرآن سے مراد","",{"k":"نصب راية (٢/٢٥٥)۔","f":"مومنین ہیں اور بطور خاص حفاظ ہیں۔ ٦٠١٥"}],[6015,"سیدنا سنان بن وبرہ یا اللہ نے بیان کیا، ہم غزوہ مریسیع غزوہ بنی المصطلق میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے، ان کا شعار ( علامت پہچان Code word) تھا: یا منصور! اُمت “ یہ حدیث سنان بن وبرہ سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن جہضم کا تفرد","",{"k":"لر مجمع الزوائد: ) د (١٤٥/٦)، مجمع البحرين (٢٧٨٠)، اسناده ضعیف۔"}],[6016,"سیدنا ابو موسی نیل الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ایک غزوہ میں تھے کہ تو مشرکوں میں سے ایک آدمی مسلمانوں کے ایک آدمی سے مقابلے کے لیے نکلا تو مشرک نے اسے شہید کر دیا۔ پھر مسلمانوں میں سے ایک اور آدمی مقابلے کے لیے نکلا تو اس نے اسے بھی شہید کر دیا۔ پھر وہ قریب ہوا اور نبی صلی اللہ علیہ وسلم کے پاس کھڑا ہو کر کہنے لگا: تم کس بات پر قتال کرتے ہو؟ آپ نے فرمایا: ”ہمارا دین: یہ کہ ہم لوگوں سے قتال کریں حتی کہ وہ گواہی دیں کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ محمد اس کے بندے اور اس کے رسول ہیں اور یہ کہ ہم اللہ کا پورا پورا حق ادا کریں۔“ اس نے کہا: اللہ کی قسم! یہ تو بڑا اچھا دین ہے میں اس پر ایمان لاتا ہوں، پھر وہ مسلمانوں کی طرف آ گیا اور مشرکوں پر حملہ کیا تو قتال کیا حتی کہ وہ شہید کر دیا گیا، اسے اٹھا لیا گیا اور اسے اس کے ان دونوں ساتھیوں کے ساتھ رکھ دیا گیا، جنہیں اس نے شہید کیا تھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” یہ جنتیوں میں سب سے زیادہ باہم محبت کریں گے۔ یہ حدیث سیدنا ابو موسی بنی اہلیہ سے صرف اسی اسناد سے مروی ہے۔ اس میں ابن المبارک کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥/٢٩٩)، مجمع البحرين (٢٦٥٢.٢٩٩/٥)۔"}],[6017,"سيدنا مغیره فضل اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میں جس مسئلے میں تمہیں چھوڑے رکھوں (نہ بتاؤں) تو تم مجھے چھوڑے رکھو، تم سے پہلے لوگ اپنے انبیاء علیہ ہم سے زیادہ سوال کرنے اور ان کے ساتھ اختلاف کرنے ہی کی وجہ سے ہلاک ہوئے۔ پس میں جس چیز کے متعلق تمہیں حکم دوں تو اس میں سے جتنا کرسکو کرو اور جس سے میں تمہیں منع کروں اس سے باز آجاؤ۔“ اس حدیث کو منصور سے صرف عمار بن رزیق نے روایت کیا۔ اس میں ابوالجواب کا تفرد ہے۔ قانون مذکورہ حدیث سے معلوم ہوا کہ کسی واقعی ضرورت اور وجہ کے بغیر سوال کرنا اور اللہ اور","",{"k":"مجمع الزوائد (١/١٦١)، صحیح مسلم (١٣٣٧)، مجمع البحرين (٢٦١)، صحیح بخاری (٤٢٨٨)۔","f":"اس کے رسول صلے علم کے احکام میں اختلاف و نزاع پیدا کرنا ہلاکت کا سبب ہے۔سلامتی کا راستہ صرف یہی ہے Jesse کہ اللہ اور اس کے رسول ملے تعلیم کی باتوں پر بلا چوں و چراں عمل کیا جائے۔ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں رسول اللہ ملنے سے زیادہ سوال کرنا اس لیے منع تھا کہ ایسا نہ ہو کہ کسی سوال کرنے سے مسلمانوں کے لیے وہ چیزیں حرام ہو جائیں جو سکوت کی وجہ سے جائز تھیں۔ وَلَا تَسْتَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَلَكُمْ تَسُؤْكُمْ ﴾ (المائده: ١٠١) .: ایسی چیزوں کے متعلق سوال نہ کرو کہ اگر تمہارے لیے ظاہر کر دی جائیں تو تمہیں بری لگیں۔“"}],[6018,"و سیدہ عائشہ ضمنی انا نے فرمایا: \"رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے ہوتے تھے جبکہ میں آپ میم کے آگے لیٹی ہوتی تھی۔ اس حدیث کو یزید بن رومان سے صرف ابراہیم بن اسماعیل بن ابی حبیبہ نے اور ابراہیم بن اسماعیل سے صرف ابو القاسم بن ابی طلحہ زناد نے روایت کیا۔ اس میں سعید بن بیچی الأموی کا تفرد ہے۔","",{"k":"صحیح بخاری، رقم: ٣٨٣ صحیح مسلم (٥١٢)۔"}],[6019,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں اس شخص کے متعلق نہ بتاؤں جو تم میں سے اللہ کو سب سے زیادہ چہیتا ہے؟“ ہم نے عرض کیا: اللہ کے رسول! ضرور بتائیں ہم نے گمان کیا کہ آپ صلی اللہ علیہ وسلم کسی آدمی کا نام بتائیں گے . آپ صلی اللہ علیہ وسلم نے فرمایا:! تم میں سے جو لوگوں کو سب سے زیادہ پسند ہے وہی تم میں سے اللہ کو سب سے زیادہ پسند ہے۔“ پھر رسول اللہ علے سلیم نے فرمایا: \"کیا میں تمہیں اس شخص کے متعلق نہ بتاؤں جو تم میں سے اللہ کو انتہائی ناپسند ہے؟“ ہم نے عرض کیا: اللہ کے رسول! ضرور بتائیں، ہم نے گمان کیا کہ آپ ملنے کی کسی آدمی کا نام لیں گے، آپ علیم نے فرمایا: تم میں سے جو لوگوں کو سب سے زیادہ ناپسند ہے وہی تم میں سے اللہ کو سب سے زیادہ ناپسند ہے۔“ یہ حدیث سیدنا ابوسعید خدری رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں ابن المبارک کا تفرد ہے اور اسے ابن المبارک سے صرف علی بن الحسن بن شقیق نے روایت کیا ہے۔ انہوں نے ہمیں یہ حدیث بیان کی: محمد بن الحسن بن شقیق نے بیان کیا: میں نے احمد بن حنبل کو یہ حدیث بیان کی تو انہوں نے اسے حسن قرار دیا۔ اندن۔ اس کے راوی عبد الرحمان بن جندہ کے متعلق علامہ ہیثمی اللہ نے فرمایا، لم اجدہ۔ (مجمع الزوائد: ١٠/ ٢٧٢ تاہم ایک دوسری حدیث میں ہے کہ رسول اللہ صل علی تم نے فرمایا: اللہ تعالیٰ جب کسی بندے سے محبت کرتا ہے تو جبریل عالی نام کو بلاتا اور اس سے فرماتا ہے: میں فلاں سے محبت کرتا ہوں تو بھی اس سے محبت کر۔ پس جبریل عالینام اس سے محبت کرنے لگ جاتے ہیں۔ پھر جبریل عالینام آسمان سے منادی کرتے اور کہتے ہیں: بے شک اللہ تعالیٰ فلاں سے محبت کرتا ہے تم بھی اس سے محبت کرو، پس آسمان والے بھی اس سے محبت کرنے لگ جاتے ہیں۔ پھر اس کے لیے زمین میں قبولیت رکھ دی جاتی ہے اور جب اللہ ذوالجلال کسی بندے سے دشمنی کرتا ہے تو جبریل علینا کو بلا کر فرماتا ہے: میں فلاں سے دشمنی کرتا ہوں تو بھی اس سے دشمنی کر۔ پس جبریل کا نام بھی اس سے دشمنی کرنے لگ جاتے ہیں۔ پھر وہ آسمان والوں میں منادی کرتے ہیں کہ اللہ ذوالجلال فلاں سے دشمنی کرتا ہے تم بھی اس سے دشمنی کرو، پھر اس کے لیے زمین میں بھی دشمنی رکھ دی SSS IS جاتی ہے۔ (مسلم، کتاب البر والصلة، رقم: ٢٦٣٧) معلوم ہوا کہ جو اللہ ذوالجلال کا محبوب ہے لوگ بھی اس سے محبت کرتے ہیں اور جس سے اللہ ذوالجلال دشمنی رکھتے ہیں، لوگوں کے نزدیک بھی اس کا مقام و مرتبہ نہیں ہوتا۔","",{"k":"مجمع الزوائد (١٠/٢٧٢)، مجمع البحرين (٤٩٧٩)۔"}],[6020,"سیدنا عبد اللہ ابن مسعود ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا، وہ مشک کی طرح تیز تیز حرکت کر رہا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دوڑنے کی بجائے اپنے جنازے میانہ روی کے ساتھ لے کر چلو، اگر خیر ہے تو تم اسے جلد وہاں پہنچا دو گے اور اگر شر ہے تو اللہ صرف جہنمیوں کو ہی دور کرتا ہے اور جنازے کے پیچھے پیچھے چلنا چاہیے اس کے آگے آگے نہیں چلنا چاہیے اور جو اس کے آگے آگے چلتا ہے وہ اس کے ساتھ نہیں۔“ اس حدیث کو ایوب سے صرف عبد المومن بن عباد نے روایت کیا۔ اس میں نصر بن علی کا تفرد ہے۔ ٦٠٢١","",{"k":"سنن ابو داود (٣١٨٤)، سنن يرو ترمذی (١٠١١)، قال الشيخ الالباني: ضعيف۔"}],[6021,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” قیامت کے Rickie روز مصوروں کو عذاب دیا جائے گا اور انہیں کہا جائے گا: تم نے جو تخلیق کیا تھا اسے زندہ کرو۔ “ اس حدیث کو علی بن ثابت سے صرف عمران القطان نے روایت کیا۔ اس میں محمد بن بلال کا تفرد ہے۔","",{"k":"صحیح بخاری (٥٩٥١)، صحیح مسلم (٢١٠٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ تصویر بنانا بہت بڑا گناہ ہے، جس پر عذاب ہوگا کیونکہ یہ صفت خالقیت میں اللہ ذوالجلال کی مشابہت اختیار کرتے ہیں۔ اسی طرح تصویر بنوانا بھی بہت بڑا گناہ ہے،لیکن جو تصویر حکومت کی طرف سے لازم قرار دی گئی ہو جیسے شناختی کارڈ، پاسپورٹ، ڈومی سائل، امتحان دینے کے لیے تصویر بنانا، اسی طرح زمین رجسٹری کروانے کے لیے تصویریں بنانا، ان میں چونکہ انسان مجبور ہے، اس میں اس کی اپنی مرضی کا دخل نہیں، اس لیے ان پر عذاب نہیں ہوگا۔"}],[6022,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر میں فجر کی نماز کے بعد سے طلوع آفتاب تک اللہ کا ذکر کرنے والوں کے ساتھ بیٹھ جاؤں تو یہ مجھے اسماعیل عالینام کی اولاد سے چار غلام آزاد کرنے سے زیادہ پسند ہے اور اگر میں نماز عصر کے بعد سے لے کر غروب آفتاب تک اللہ کا ذکر کرنے والوں کے ساتھ بیٹھ جاؤں تو یہ مجھے اسماعیل کا اسلام کی اولاد سے چار غلام آزاد کرنے سے زیادہ پسند ہے۔ اس حدیث کو محتسب سے صرف عرعرہ بن البرند نے روایت کیا۔ اس میں ریحان بن سعید کا تفرد ہے۔ ان مذکورہ حدیث سے صبح و شام اللہ ذوالجلال کا ذکر کرنے والوں کی فضیلت واضح ہے۔ ذکر الہی تو انسان کو ہر وقت ہی کرتے رہنا چاہیے۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم کے متعلق احادیث میں موجود ہے کہ نبی مکرم ملے تم ہر وقت اللہ ذوالجلال کا ذکر کرنا پسند کرتے تھے، لیکن صبح و شام اللہ ذوالجلال کا ذکر کرنے کی قرآن و سنت میں بہت زیادہ ترغیب ہے۔ ارشاد ربانی ہے: اور فرمایا: وَسَبِّحْ بِحَمْدِ رَبَّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ﴾ (ق: ٣٩) طلوع آفتاب اور غروب آفتاب سے قبل اپنے رب کی حمد کے ساتھ تسبیح بیان کیجئے۔‘“ يَأَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا هِ وَ سَبِّحُوهُ بُكْرَةً وَأَصِيلا (الاحزاب: ٤١ - ٤٢) مسلمانو! اللہ کا بہت زیادہ ذکر کیا کرو اور صبح و شام اس کی پاکیزگی بیان کیا کرو۔“ سیدنا اسماعیل علینا کی اولاد کیوں؟ بخاری و مسلم میں ہے سیدنا ابو ذر رضی اللہ عنہ فرماتے ہیں: میں نے نبی معظم صلی اللہ علیہ وسلم سے پوچھا کون سا عمل افضل ہے؟ فرمایا: اللہ پر ایمان اور اس کی راہ میں جہاد کرنا۔ میں نے پوچھا: گردنوں میں کون سی گردن ( آزاد کرنا ) افضل ہے؟ فرمایا: جو قیمت میں زیادہ اور اپنے مالکوں کے نزدیک زیادہ نفیس ہو۔ یہ بات ظاہر ہے کہ خاندانی شرافت کے لحاظ سے اولاد اسماعیل مالینام دوسروں سے برتر ہے، رسول اللہ صلی اللہ علیہ وسلم بھی انہی میں سے ہیں، اس لیے ان کا آزاد کرنا بھی زیادہ ثواب کا باعث ہے۔","",{"k":"سنن ابو داود (٣٦٦٧)، قال الشيخ الالباني: حسن۔"}],[6023,"سیدنا مالک بن ربیعہ رضی اللہ عنہ سے روایت ہے کہ بیعت رضوان کے موقع پر جب قربانی کو منی پہنچنے سے پہلے ہی روک لیا گیا تھا، وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ موجود تھے، اس روز ایک آدمی آپ صلی اللہ علیہ وسلم کے پاس آیا تو اس نے کہا: محمد ملے عین )! میں جو دیکھ رہا ہوں کہ آ ملے ہم ایسے لوگوں کو جن کے قبائل کا پتہ نہیں حرم میں داخل کرنا چاہتے ہیں جبکہ ہم اسے نا پسند کرتے ہیں، اس کام پر کون سی چیز آپ کو آمادہ کرتی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” یہ لوگ تم سے بہتر ہیں اور تمہارے آباؤ و اجداد سے بہتر ہیں۔ وہ اللہ اور یوم آخرت پر ایمان رکھتے ہیں۔ اس ذات کی قسم جس کے ہاتھ میں محمد ملنے کی یمن کی جان ہے! اللہ ان سے راضی ہو چکا ہے۔“ یہ حدیث مالک بن ربیعہ سے صرف اس اسناد سے مروی ہے۔: ٦٠٢٤","",{"k":"مجمع الزوائد (١٤٥/٦)، مجمع البحرين (٢٧٨٣)، اسناده ضعیف۔"}],[6024,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ نے ایام کو صلح حدیبیہ کے موقع پر دیکھا آپ صلی اللہ علیہ وسلم اونٹ کی قربانی میں اپنے اصحاب میں سے سات افراد شامل کرتے تھے۔“ اس حدیث کو الز ہری سے صرف معاویہ بن بیٹی نے روایت کیا۔ اس میں بیٹی بن سعید العطار کا تفرد ہے۔ ٦٠٢٥","",{"k":"کر مجمع الزوائد (٢٢٦/٣)، مجمع البحرين (١٧١٤)۔"}],[6025,"سیدنا ابو موسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں چار چیزیں بیان فرما ئیں تو فرمایا: ”اللہ عزوجل سوتا نہیں اور اس کے شان کے لائق ہی نہیں کہ وہ سو جائے، وہ میزان کو پست و بلند کرتا ہے، رات کے اعمال سے پہلے دن کے اعمال اس کی طرف بلند کیے جاتے ہیں اور دن کے اعمال سے پہلے رات کے اعمال (بلند کیے جاتے ہیں، اس کا حجاب نور ہے، اگر وہ حجاب اٹھا لے تو اس کے چہرے کے انوار ہر اس چیز کو جلا دیں جہاں تک پر اس کی نظر پہنچتی ہے، پھر آپ نے یہ آیت تلاوت فرمائی: ”آواز دی گئی کہ جو لوگ آگ کے اندر ہیں وہ بابرکت ہیں اور جو اس کے گرد ہیں وہ بھی بابرکت ہے۔‘ اس حدیث کو الحسن بن عمرو سے صرف عمر و بن عبد الغفار نے روایت کیا۔ ٦٠٢٦","",{"k":"مقدم صحیح مسلم۔"}],[6026,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے نه پاس آیا تو اس نے عرض کیا: اللہ کے رسول! کون سا شخص اللہ کو سب سے زیادہ محبوب ہے؟ اور کون ساعمل اللہ کو سب سے زیادہ پسند ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں کو سب سے زیادہ نفع پہنچانے والا شخص اللہ کو سب سے زیادہ محبوب ہے اور اللہ کو سب سے زیادہ پسندیدہ عمل وہ سرور ہے جو تو کسی مسلمان کو پہنچاتا ہے، یا تو اس کی کوئی تکلیف دور کر دیتا ہے، یا اس کا قرض ادا کر دیتا ہے، یا اس کی بھوک مٹا دیتا ہے اور کسی کام کے لیے کسی مسلمان بھائی کے ساتھ چل کر جانا اس مسجد یعنی مدینے کی مسجد میں ایک ماہ اعتکاف کرنے سے مجھے زیادہ پسند ہے۔ جو اپنے غصے پر قابو پاتا ہے اللہ اس کی پردہ پوشی فرماتا ہے اور جو شخص اپنے غیظ وغضب کو روکتا ہے۔ اگر وہ اسے نافذ کرنا چاہتا تو وہ نافذ کر سکتا تھا۔ اللہ عز وجل قیامت کے دن اس کے دل کو امن سے بھر دے گا اور جو شخص اپنے کسی بھائی کے ساتھ کسی کام کے لیے چلتا ہے حتی کہ وہ اس کا کام کرا دیتا ہے تو اللہ عز وجل اس روز اس کے پاؤں کو پل صراط پر ثابت قدم رکھے گا جس روز پاؤں ڈگمگائیں گے۔ اس حدیث کو عمرو بن دینار سے صرف سکین بن سراج نے روایت کیا۔ اس میں عبد الرحمن بن قیس کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨/١٩١)، مجمع البحرين (٢٩٤٤)، سلسله صحيحه (٩٠٦)، صحیح ترغیب و ترهيب (٢٦٣٣)۔","f":"قانون مذکورہ حدیث میں آپ ملنے لیے تم نے محبوب اعمال اور محبوب عاملین کا تذکرہ کرتے ہوئے آٹھ نیکیوں کا ذکر کیا ہے اور آٹھوں خصلتوں کا تعلق انسان کے حقوق سے ہے۔ یہ کسی شخص کی سعادت ہوگی کہ دوسروں کے دکھوں میں شریک ہو، دوسروں کا سہارا بنے اور اپنے ساتھ زیادتی کی صورت میں صبر کرے۔اس سے بڑا اجر کیا ہوسکتا ہے کہ آج غصہ پی جانے کے عوض میدان حشر میں دل کو سکون اور امید نصیب ہو اور آج کسی بھائی کی ضرورت پوری کرنے کی وجہ سے روز قیامت قدموں میں ثبات پیدا ہو جائے، جس دن ہر کسی کے پاؤں پھسل رہے ہوں گے۔ ٦٠٢٧"}],[6027,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ میم نے فرمایا: ” مریضوں کی عیادت کرو اور انہیں کہو کہ وہ تمہارے لیے دعا کریں، کیونکہ مریض کی دعا قبول ہوتی ہے اور اس کے گناہ معاف ہوتے ہیں۔ یہ حدیث سیدنا انس نیل ال لینے سے صرف اس اسناد سے مروی ہے۔ اس میں عبد الرحمن بن قیس کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٢٩٥)، مجمع البحرين (١١٦٧)، ضعیف ترغیب و ترهيب (٢٠٣٠)، سلسله ضعیفه (١٢٢٢)، قال الشيخ الالبانی موضوع۔"}],[6028,"سیدنا ابن مطیع نے اپنے والد سے روایت کیا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن فرمایا: ”آج کے بعد قیامت تک کسی قریشی کو باندھ کر قتل نہیں کیا جائے گا۔“ اس حدیث کو مجالد سے صرف عیسی بن یونس نے روایت کیا۔ اس میں سلیمان بن عمر بن خالد کا تفرد ہے۔ ماندن امام نووی اللہ فرماتے ہیں: اس کا مطلب یہ ہے کہ قریش مسلمان ہو جائیں گے اور ان میں سے کوئی اسلام سے نہ پھرے گا یعنی مرتد نہیں ہو گا۔ جس کی وجہ سے قتل کر دیے جائیں۔","",{"k":"صحيح مسلم (١٧٨٢)۔"}],[6029,"سیدنا مسروق نے بیان کیا، میں سیدہ عائشہ منی اشیا کے پاس گیا تو انہوں نے کھانا منگایا اور فرمایا: کھاؤ، میں کھانے سے کم ہی سیر ہوتا تھا اور میں چاہتا تھا کہ میں روؤں تو میں روتا تھا۔ میں نے عرض کیا: ام المومنین! یہ کیسا کھانا ہے؟ انہوں نے فرمایا: مجھے وہ حال یاد ہے جس پر رسول اللہ صلی اللہ علیہ وسلم اس دنیا سے گئے۔ رسول اللہ صلی اللہ علیہ وسلم ایک دن میں دو بار گندم کی روٹی سے شکم سیر نہیں ہوئے حتی کہ آپ ملے کہ تم اللہ سے جا ملے۔ عائشہ بونی نینجا نے فرمایا: انصار کی ایک خاتون میرے پاس آئی۔ اس نے رسول اللہ صلی اللہ علیہ وسلم کا بچھونا ایک عباء دیکھی تو اس نے کہا: آپ ملنے سلیم کا اس کے علاوہ کوئی بچھونا نہیں ہے؟ میں نے کہا: نہیں، اللہ کی قسم! اس کے علاوہ آپ صلی اللہ علیہ وسلم کا کوئی بچھونا نہیں۔ پس اس نے کپڑوں میں سے ایک کپڑے کا قصد کیا اور اس میں اون بھری، پھر اسے میرے پاس لائی اور کہا: رسول اللہ صلی اللہ علیہ وسلم کے لیے یہ بچھونا ہونا چاہیے۔ جب آپ صلی اللہ علیہ وسلم آئے تو فرمایا: عائشہ! یہ کیا ہے؟“ میں نے آپ صلی اللہ علیہ وسلم کو بتایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے واپس کر دو۔ “ سیدہ عائشہ منی اینجا نے فرمایا: ”رسول اللہ صلی اللہ علیہ وسلم میرے پاس سے تشریف لے گئے اور میں نے اسے واپس نہ کیا۔ مجھے اچھا لگا کہ وہ میرے گھر میں ہو۔ پس آپ صلی اللہ علیہ وسلم تشریف لائے تو فرمایا: \"عائشہ! کیا میں نے تمہیں کہا نہیں تھا کہ اسے وپس کر دو؟“ میں نے عرض کیا: اللہ کے رسول! میں نے اسے واپس نہیں کیا بلکہ میں نے چاہا کہ وہ میرے گھر میں ہو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! اسے واپس کر دو، کیونکہ اگر میں چاہوں تو اللہ میرے ساتھ سونا اور چاندی چلا دے۔ اس حدیث کو حماد بن زید سے صرف الصلت بن مسعود نے روایت کیا۔","",{"k":"يرو ٦٤٥٤ صحیح بخاری، رقم۔","f":".. مذکورہ حدیث سے نبی معظم ملے ان کے زہد، استغناء،قناعت اور بے مثال سادگی کا ثبوت ملتا ہے، رسول اللہ سے ہم دوسروں کی ضروریات پوری کرنا ضروری سمجھتے تھے اور خود کم سے کم پر اکتفا کرتے تھے۔ ایک مسلمان کے لیے بھی ایسا ہی ہونا چاہیے کہ وہ دوسروں کا خیال رکھے، صرف دنیا بنانے اور سنوار نے کے چکر میں اپنی آخرت برباد نہ کر بیٹھے بلکہ اس کو ہمہ وقت اس بات کی فکر رہنی چاہیے کہ کہیں اس کا نامہ اعمال دنیا میں مشغول ہونے کی وجہ سے سیاہ نہ ہو جائے بلکہ حساب کی سختی کا فکر ہونا چاہیے۔ جیسا کہ قرآن مجید میں عقل مندوں کی نشانیاں بیان کرتے ہوئے اللہ ذوالجلال نے ارشاد فرمایا: وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ﴾ (الرعد: ٢١) اور وہ اپنے رب سے ڈرتے ہیں اور حساب کی سختی کا اندیشہ رکھتے ہیں۔“ آل فرعون کے مومن نے اعلان کرتے ہوئے کہا تھا: يَا قَوْمِ إِنَّمَا هُذِهِ الْحَيَاةُ الدُّنْيَا مَتَاعٌ وَإِنَّ الْآخِرَةَ هِيَ دَارُ الْقَرَارِ ﴾ (المؤمن: ٣٩) اے میری قوم دنیا کی زندگی تو صرف سامان ہے حقیقت میں قرار کی جگہ آخرت میں ہے۔“ ٦٠٣٠"}],[6030,"سیدنا عبد اللہ بن مسعود ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”پانچ جانور موذی ہیں وہ حل وحرم میں مار ڈالے جائیں گے: چوہیا، بچھو، چیل، کاٹنے والا کتا اور کوا۔‘ اس حدیث کو عمر و بن دینار سے صرف محمد بن ثابت العبدی نے روایت کیا۔ اس میں الصلت کا تفرد ہے۔","",{"k":"صحیح بخاری (١٨٢٨)، صحیح مسلم (١١٩٩)۔"}],[6031,"سیدنا بشير بن الخصاصیہ رضی اللہ عنہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو میں آپ صلی اللہ علیہ وسلم سے بقیع میں ملا۔ میں نے آپ صلی اللہ علیہ وسلم کو یوں دعا کرتے ہوئے سنا؛ ”سلام ہو ان گھروں کے مومن مکینو! پس میرا تسمہ ٹوٹ گیا تو آپ سے تم نے فرمایا: ” اپنا قدم اٹھا۔“ میں نے عرض کیا: اللہ کے رسول! میرا مجرد زندگی گزارنے کا عرصلہ لمبا ہو گیا اور میں اپنی قوم کے گھر سے دور ہوں، آپ نے فرمایا: \"بشیر! کیا تم اس اللہ کا شکر ادا نہیں کرتے جس نے ربیعہ قبیلے سے تمہاری پیشانی پکڑ کر اسلام کی طرف راہنمائی فرمائی، وہ ایسے لوگ ہیں جو سمجھتے ہیں کہ اگر وہ نہ ہوں تو زمین اپنے اوپر موجود تمام چیزوں سمیت اوندھی ہو جائے؟“ اس حدیث کوالشیبانی سے صرف اس کے بیٹے اسحاق نے روایت کیا۔ اس میں عقبہ بن المغیرہ کا تفرد ہے۔ ٦٠٣٢","",{"k":"مجمع الزوائد (٦٠/٣)، مجمع البحرين (١٣٣٤)۔"}],[6032,"سیدنا عرفہ ضیا اللہ نے نبی صلی اللہ علیہ وسلم سے مرفوعاً روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: عنقریب فتنے ہوں گے اور شر ہو گا۔ پس تم جس شخص کو دیکھو کہ وہ محمد نے من کی امت منتشر کرنے کے لیے کوشاں رہتا ہے جبکہ وہ باہم متحد ہوں تو اس کو قتل کر دو خواہ وہ کوئی بھی ہو۔“ اس حدیث کو حماد بن زید کے حوالے سے المفضل بن فضالہ سے صرف محمد بن سلیمان نے روایت کیا۔","",{"k":"صحيح مسلم، سنن ابو داود (٤٧٦٢)۔"}],[6033,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قرآن سات قراء توں پر اتارا گیا، وہ سب اطمینان بخش اور کافی ہیں۔ اس حدیث کو میمون ابو حمزہ سے صرف ابوخیثمہ زہیر بن معاویہ نے روایت کیا۔ اس میں شجاع بن ولید کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٥٦/٧)، مجمع البحرين (٣٤٤٨)، سلسله صحيحه (٢٥٨١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قرآن مجید سات لغات پر نازل ہوا۔ شیخ البانی کہتے ہیں: اس حدیث اور اس کے شواہد سے معلوم ہوا کہ سبعة سے سات لغات مراد ہیں جن کی مدد سے ایک لفظ یا ایک کلمہ کو سات لغات میں بیان کیا جا سکتا ہے۔ ان لغات میں الفاظ مختلف ہوتے ہیں اور معانی متحد۔ امام طبری نے اپنی تفسیر کے مقدمہ میں اس کی کافی وشافی وضاحت کی ہے اور یہ ثابت کیا ہے کہ ( سیدنا عثمان نبی اللہ کے عہد میں ) پوری امت ایک لغت پر متحد ہو چکی ہے اور باقی چھ کو ترک کر دیا اور ایسا کرنے سے قرآن مجید کے کسی حصہ میں کوئی نسخ یا نقصان نہیں ہوا۔ آج قرآن مجید قراءت کے جس انداز پر مشتمل ہے، یہ وہی ہے جس پر سیدنا عثمان بنی اہلیہ نے لوگوں کو جمع کیا تھا۔ بہر حال انہوں نے بڑا عمدہ، پائیدار اور مفید کلام کیا ہے، اس کا مراجعہ کرنا چاہیے۔"}],[6034,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”میں حوض کوثر پر تمہارا پیش خیمہ ہوں گا اور اس کے کناروں کے درمیان اتنا فاصلہ ہے جتنا صنعا اور ایلہ کے درمیان فاصلہ ہے، وہاں آب خورے اس طرح ہیں جس طرح ستارے ہیں۔ اس حدیث کو زیاد بن خیثمہ سے صرف شجاع بن الولید نے روایت کیا۔ اس میں اس کے بیٹے کا تفرد ہے۔","",{"k":"کر صحیح مسلم، ٦٠٣٤ (٢٣٠٥)۔"}],[6035,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے پانچ چیزوں: کہتے کی قیمت، خنزیر کی قیمت، شراب کی قیمت، بدکار عورت کی اجرت اور نر کی مادہ پر جفتی کرانے کی اجرت سے منع فرمایا۔“ اس حدیث کو عبد اللہ بن عیسی سے صرف زیاد بن خیثمہ نے روایت کیا۔ اس میں شجاع بن الولید کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ مذکورہ بالا پانچ چیزوں کی قیمت لینا حرام ہے۔ یہ بھی:٦٠٣٦ معلوم ہوا کہ خنزیر اور شراب کی قیمت بھی حرام ہے کیونکہ وہ اشیا جن کا استعمال جائز نہیں، ان کی تجارت بھی جائز نہیں ہے، کیونکہ خنزیر زندہ ہو یا مردہ اس کے تمام اجزا انجس اور حرام ہیں، اسی طرح شراب بھی حرام ہے تو اس کا ادویات میں استعمال کرنا یا تجارت کرنا حرام ہے۔","",{"k":"مجمع الزوائد (٩١/٤)۔"}],[6036,"سیدنا ارقم بنی لینہ نے بیان کیا، رسول اللہ نے ہم نے غزوہ بدر کے موقع پر فرمایا: مال غنیمت میں سے جو کچھ تمہارے پاس ہے اسے لوٹا دو پس سیدنا ابو اسید الساعدی رضی اللہ عنہ نے بنو العائذ بن المرزبان کی تلوار بلند کی تو سیدنا ارقم نبی الیہ نے اسے پہچان لیا اور عرض کیا: اللہ کے رسول! یہ مجھے ہبہ کر دیں تو آپ صلی اللہ علیہ وسلم نے وہ انہیں دے دی۔“ یہ حدیث ارقم بن ابی ارقم سے صرف اسی اسناد سے مروی ہے۔ اس میں ابو مصعب کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩٢/٦)، مجمع البحرين (٢٧٦١)، حاكم (٥٧٦/٣)، اسناده صحيح۔"}],[6037,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”نبی داود علی اسلام نے کہا: میرے معبود! تیرے بندوں کا تم پر کیا حق ہے جب وہ تیرے گھر میں تیری زیارت کریں؟ اس نے فرمایا: ”ہر زائر کا جس کی وہ زیارت کرتا ہے اس پر حق ہے۔ داود! ان کا مجھ پر یہ حق ہے کہ میں انہیں دنیا میں معاف کردوں اور جب ان سے میری ملاقات ہو تو میں انہیں بخش دوں۔ اس حدیث کو الوفین بن عطا سے صرف الخلیل بن مرہ نے روایت کیا۔ اس میں محمد بن حمزہ الرقی کا تفرد ہے اور سیدنا ابو ذر یا لینے سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٣/٢٠٨)، مجمع البحرين، رقم: ١٦٤٤ ضعیف ترغیب و ترهيب (٧٠٠)، سلسله ضعیفه (٥٠٩٤)، اسناده ضعيف۔"}],[6038,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی الٹے سم کے کسی صحابی کو کسی موذی چیز نے ڈس لیاء اللہ نے جو چاہا اسے اس سے تکلیف پہنچی، نبی ملنے سلیم کو اس کی خبر پہنچی تو آپ ملنے صلی اللہ علیہ وسلم نے فرمایا: جس وقت اس نے شام کی تھی اگر اس نے یہ دعا: ” میں اللہ کے کامل کلمات کے ذریعے ہر اس چیز کے شر سے جو اس نے پیدا فرمائی پناہ چاہتا ہوں۔ تین بار پڑھ لی ہوتی تو وہ اسے نقصان نہ پہنچاتی۔“ اس حدیث کو حماد بن زید سے اچھی طرح سیدنا ابو ہریرہ رضایا لینے سے صرف محمد بن سلیمان نے روایت کیا۔ اور دوسرے لوگوں نے اسے حماد بن سہیل، عن ابیہ عن رجل عن اصحاب النبی صلی اللہ علیہ وسلم ن کی سند سے روایت کیا ہے۔","",{"k":"صحيح مسلم (٢٧٠٩)، سنن ابو داود (٣٨٩٩)۔","f":"اندن مذکورہ حدیث سے معلوم ہوا کہ مذکورہ بالا الفاظ پڑھنے کی وجہ سے اللہ ذوالجلال بچھو کے ڈنگ سے یا پھر کوئی بھی زہریلی چیز ہو گی اس کے ڈنگ کے ضرر سے بچالے گا۔ مذکورہ بالا دعا ترمذی شریف میں بھی ہے۔ (دیکھئے حدیث نمبر ٣٦٠٤) امام ترمذی ہی اللہ نے اس حدیث کے بعد اس کے ایک راوی سہیل بن ابی صالح سے روایت کیا ہے کہ ہمارے گھر والوں نے یہ دعا سیکھ لی تھی، پھر ہر رات یہ دعا پڑھتے تھے، ایک دفعہ ایک باندی کو کسی زہریلی چیز نے ڈس لیا لیکن اسے کوئی درد و تکلیف نہیں ہوئی۔"}],[6039,"سیدہ عائشہ نیلی نیہا نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”جس میت کی سو مسلمان نماز جنازہ پڑھیں اور وہ سب اس کے لیے شفاعت کریں تو اس کے متعلق ان کی شفاعت قبول کی جاتی ہے۔ اس حدیث کو سلام بن ابی مطیع سے صرف ابن المبارک نے روایت کیا۔ . ایک دوسری حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو کوئی مسلمان فوت ہو جائے اور پھر اس پر چالیس آدمی کھڑے ہو کر نماز جنازہ پڑھیں جو اللہ کے ساتھ کسی کو شریک نہ ٹھہراتے ہوں تو اس میت کے بارے میں ان کی سفارش قبول کر لی جاتی ہے۔ (مسلم، رقم: ٩٤٨، ابو داؤد، رقم: ٣١٧٠) مذکورہ بالا روایات سے یہ ثابت ہوتا ہے کہ جنازے میں زیادہ سے زیادہ لوگوں کو شرکت کرنا چاہیے لیکن ہوں وہ اہل ایمان و توحید اور جو مختلف روایات میں تعداد بیان ہوئی ہے، جس سے مقصود کثرت ہے اور کثرت بھی کثرت محض نہیں، اہل ایمان و تقویٰ اور اہل توحید کی کثرت ہے۔","",{"k":"صحيح مسلم (٩٤٧)، سنن ترمذی (١٠٢٩)۔"}],[6040,"سیدہ ضباعہ بنت زبیر بن عبد المطلب من النوجا سے روایت ہے کہ انہوں نے اپنے گھر میں ایک بکری ذبح کی تو رسول اللہ سے ہم نے انہیں پیغام بھیجا، اپنی بکری کا گوشت ہمیں بھی کھلاؤ۔“ انہوں نے قاصد سے کہا: اس میں سے تو صرف گردن بچی ہے اور مجھے حیا آتی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں گردن بھیجوں۔ پس وہ قاصد واپس آیا اور رسول اللہ علیم کو بتایا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”واپس جا، اور کہہ: وہی (گردن) میری طرف بھیج دو، کیونکہ وہ بکری کی گردن ہے، بکری کا خیر کے بہت قریب والا حصہ ہے اور گندگی سے بہت دور والا حصہ ہے۔ یہ حدیث ضباعہ بنت الزبیر علی الشیا سے صرف اس اسناد سے مروی ہے۔اس میں اسامہ بن زید کا تفرد ہے۔","",{"k":"مسند احمد (٦/٣٦٠، ٢٧٠٧٦)، قال شعیب الارناؤط: اسناده ضعيف۔"}],[6041,"سیدنا عبداللہ ابن عم رضی اللہ عنہ سے اللہ عز و جل کے فرمان: «فصل کی کٹائی کے دن اس کا حق دو“ کی تفسیر میں مروی ہے، انہوں نے کہا: صدقہ کے سوا جو چیز انہیں پیش آتی اسے دے دیتے تھے۔“ اس حدیث کو اشعث بن سوار سے صرف عبد الرحیم بن سلیمان نے روایت کیا۔ ٦٠٤٢","",{"k":"ضعیف ہے۔ مجمع الزوائد (٢٢/٧)، مجمع البحرين (٣٣١٨)، اس میں اشعث بن سوار۔"}],[6042,"سیدنا جابر بن عبد اللہ ہی اللہ سے روایت ہے کہ دو بھائیوں کی زمین تھی، ان میں سے ایک نے اپنا حصہ اپنی والدہ کو عمر بھر کے لیے دے دیا، پس وہ فوت ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے زمین دونوں میں تقسیم کر دی۔“ اس حدیث کو زفر سے صرف الانصاری نے روایت کیا اور زفر نے حدیث کی اسناد سے دو راوی ساقط کیے ہیں، کیونکہ ثوری اور قیس بن الربیع نے اسے حبیب بن ابی ثابت، عن حمید الاعرج عن طارق ( مکہ کے قاضی ) عن جابر کی سند سے روایت کیا ہے۔",""],[6043,"سیدنا ابو ہریرہ اور سیدنا عبداللہ ابن عمر ضای اینجا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”نماز (ظہر ) کو ٹھنڈے وقت میں پڑھو، کیونکہ گرمی کی شدت جہنم کے جوش کی وجہ سے ہے۔“ اس حدیث کو صالح بن کیسان، عن نافع سے صرف سلیمان بن بلال نے روایت کیا۔ اس میں ایوب بن سلیمان من ابی بکر بن ابی اولیس کا تفرد ہے۔ ٦٠٤٤","",{"k":"بخاری (٥٣٣، ٠٥٣٤)۔"}],[6044,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، نبی طلق علیکم سفر سے لوٹے، پس جب آپ صلی اللہ علیہ وسلم مدینے کے قریب پہنچے تو آپ صلی اللہ علیہ وسلم نے یہ دعا پڑھی: \"لوٹنے والے، تو بہ کرنے والے عبادت کرنے والے، اپنے رب کی حمد بیان کرنے والے ہیں، اے اللہ! میں سفر کی مشقت سے، اہل و مال میں تکلیف دہ واپسی اور برے منظر سے تیری پناہ چاہتا ہوں۔“ اس حدیث کو سعید بن المسیب سے صرف عاصم بن عمر بن قتادہ نے اور عاصم سے صرف محمد بن اسحاق نے روایت کیا۔ اس میں بیٹی بن محمد الشعری کا تفرد ہے۔ نان مذکورہ روایت ضعیف ہے، تاہم لفظ (( أنبون تائبون عابدون، لربنا حامدون)) صحیح مسلم میں ہیں۔ (دیکھئے: مسلم، رقم: ١٣٤٥) معلوم ہوا کہ کسی بھی سفر سے جب انسان واپس آئے اور اپنا شہر اسے نظر آنے لگے تو مذکورہ کلمات پڑھنا شروع کر دے اور اپنے شہر میں داخل ہونے تک پڑھتا رہے۔","",{"k":"مجمع زوائد (١٠/١٣٠)، مجمع البحرين (٤٥٨٥)۔"}],[6045,"سیدنا انس بن مالک نبی الیہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اے اللہ! انصار، ازواج انصار اور ان کی اولاد کو بخش دے۔“ اس حدیث کو عبد اللہ بن المنیب سے صرف محمد بن خالد بن عثمہ نے روایت کیا ہے۔ ٦٠٤٦","",{"k":"مجمع الزوائد (١٠/٤٠)، مجمع البحرين (٣٩٥٣.١٠٤٠)۔"}],[6046,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، انہوں نے تقدیر کے بارے میں نبی صلی اللہ علیہ وسلم کے سامنے بحث ومباحثہ کیا، آپ صلی اللہ علیہ وسلم نے اسے نہایت نا پسند فرمایا، حتی کہ ایسے محسوس ہونے لگا کہ آپ صلی اللہ علیہ وسلم کے چہرے پر انار کے دانے نچوڑے گئے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم کس چیز کے بارے میں بحث ومباحثہ کرتے ہو؟“ انہوں نے عرض کیا، اللہ کے رسول! ہم نے تقدیر کے بارے میں بحث و مباحثہ کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہر چیز قضاء و قدر کے ساتھ ہے، خواہ یہ ہو۔ آپ صلی اللہ علیہ وسلم نے اپنی انگشت شہادت دوسرے بازو کی رگ پر لگائی۔ مجز اوہ ابو اسید ثقفی نے ثابت البنانی سے صرف یہی حدیث روایت کی۔ اس میں اس کے بیٹے کا تفرد ہے۔ .. علامہ بیشمی جملہ فرماتے ہیں: تقدیر پر ایمان لانا فرض ہے، اس میں اختلاف نہیں کرنا چاہیے، کیونکہ اختلاف کی وجہ سے لوگ تباہ ہو جاتے ہیں۔ جیسا کہ سیدنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے فرمایا: ایک روز رسول اللہ صلی اللہ علیہ وسلم با ہر صحابہ کے پاس تشریف لائے تو وہ تقدیر کے بارے میں بحث کر رہے تھے، آپ مالٹے علیم کا چہرہ غصے سے اس قدر سرخ ہو گیا، گویا اس پر انار کے دانے نچوڑ دیے گئے تھے۔: ٦٠٤٧ یکھئے: سنن ابن ماجه، رقم: ٨٥، اسناده صحیح)","",{"k":"مجمع الزوائد: د (٧/٢٠٨)، مجمع البحرين (٣٢٢٦)۔"}],[6047,"سیدنا ابو ذر ضیا اہلیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اپنے مال سے، اللہ کی راہ میں جوڑا جوڑا خرچ کیا تو جنت کے دربان اس کی طرف لپکیں گے۔“ میں نے کہا: یعنی: دواونٹ، دو گھوڑے، دو بکریاں، دو درہم، دوموزے اور دو جوتے۔“ اس حدیث کو حماد بن سلمہ کے حوالے سے حمید سے صرف ابو ہشام المخزومی نے روایت کیا۔ اس میں احمد بن ثابت الجحدری کا تفرد ہے۔ مذکورہ حدیث سے جوڑا جوڑا صدقہ کرنے والوں کی فضیلت واضح ہے۔ جوڑے جوڑے کی وضاحت نبی معظم صلی اللہ علیہ وسلم نے خود ہی فرمادی ہے جیسا کہ مذکورہ بالا حدیث سے ثابت ہے۔","",{"k":"مجمع الزوائد (٢٤٢/٩)، مجمع البحرين (٢٨٣٤)، اسناده ضعيف۔"}],[6048,"سیدنا ابو الطفل رضی اللہ عنہ بیان کرتے ہیں: نبی ملنے ان مبعوث کیے گئے، جبکہ میں نو عمر لڑکا تھا، میں ہموار زمین سے پہاڑی زمین کی طرف گوشت منتقل کرتا تھا۔“ اس حدیث کو خالد بن ابی عثمان سے صرف یعقوب حضرمی نے روایت کیا۔","",{"k":"مجمع الزوائد (٤/٣١٥)، مجمع البحرين (٢٣٣٤)۔","f":"اس روایت کے راوی محمد بن یونس عصفری کے متعلق علامہ ہیثمی رحمہ اللہ فرماتے ہیں: \"لم اجدہ“ ( میں نے اس کے حالات نہیں پاۓ )(مجمع الزوائد: ١/ ١٩٩)"}],[6049,"سیدنا عقبہ بن عامر الجبنی فی اللہ بیان کرتے ہیں کہ رسول اللہ ملتے ہیم نے فرمایا: دستم سورۃ الفلق سے زیادہ بلیغ اور اللہ کو زیادہ محبوب اور کوئی سورت نہیں پڑھو گے، اگر تم استطاعت رکھو کہ تم اسے نماز میں پڑھنا نہ چھوڑو تو پڑھا کرو۔ اس حدیث کو عبد العزیز بن مروان سے صرف کثیر بن مرہ نے اور کثیر سے صرف صالح بن ابی غریب نے روایت کیا۔ اس میں عبد الحمید بن جعفر کا تفرد ہے۔ انده مذکورہ حدیث سے معلوم ہوا کہ سورۃ الفلق اللہ ذوالجلال کو بہت زیادہ پسند ہے، کوشش کرنی چاہیے کہ ہر نماز میں اس سورت کی تلاوت کی جائے۔ ایک دوسری حدیث میں ہے، سیدنا عقبہ بن عامر ضیا اللہ کا بیان ہے کہ رسول اللہ ملے لی ایم نے فرمایا: کیا میں تجھے دو ایسی سورتیں نہ سکھاؤں جو ان سب سورتوں سے بہتر ہیں، جنہیں لوگ پڑھتے ہیں؟ پھر آپ لئے علیم نے مجھے (قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ اور قُلْ اَعُوْذُ برب الناس پڑھائی۔ اتنے میں نماز کھڑی ہو گئی۔ آپ سے آگے بڑھے اور نماز پڑھائی جس میں آپ نے یہی دونوں سورتیں پڑھیں۔ پھر آپ ملنے کی تم میرے پاس سے گزرے تو فرمایا: عقبہ! ان سورتوں کی اہمیت سمجھ پائے ہو (یا نہیں؟“ پھر آپ سے سلیم نے فرمایا: ” جب بھی سونے لگو تو یہ دونوں سورتیں پڑھو اور جب جا گوتب بھی یہ دونوں سورتیں پڑھو۔ (نسائی، کتاب الاستعاذه، باب ما جاء في سورة المعوذتين، اسناده حسن سورہ فلق اور سورہ ناس کی احادیث سے بہت زیادہ فضیلت ثابت ہے۔ ٦٠٥٠","",{"k":"مجمع الزوائد (٤/٢٣٦)، ضعيف الجامع الصغير (٥٣١٩)، سلسله ضعیفه (٢٠٥٣)، مجمع البحرين (٢٠٤٦)، اسناده ضعيف۔"}],[6050,"سیدنا عبداللہ ابن عمر فی الشیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم نماز پڑھ رہے ہو اور کوئی آدمی تمہارے آگے سے گزرنا چاہے تو اسے واپس کرو، اگر وہ دوبارہ ایسا کرے تو اسے واپس کرو، پھر اگر گزرنا چاہے تو اسے واپس کرو، اگر وہ چوتھی بار گزرنا چاہے تو اس سے لڑو، وہ تو شیطان ہے۔‘اس حدیث کو قتادہ سے صرف سعید بن ابی عروبہ نے روایت کیا۔ اس میں النضر بن کثیر کا تفرد ہے۔","",{"f":"نان بخاری شریف میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی سترہ سامنے رکھ کے نماز پڑھنے لگے اور کوئی آدمی اس کے سامنے (یعنی سترے اور نمازی کے درمیان ) سے گزرنے: ٦٠٥١ لگے تو نمازی کو چاہیے کہ اسے روکنے کی کوشش کرے۔ (بخاری، رقم: ٥٠٩) معلوم ہوا کہ جب نمازی نے سترہ رکھا ہو اور کوئی اس کے اور سترے کے درمیانی فاصلے سے گزرنا چاہے تو تین مرتبہ اس کو اشارے سے روکے، واپس لوٹائے اگر چوتھی مرتبہ کوشش کرے تو اس سے لڑائی بھی کی جاسکتی ہے۔ جمہور علما نے اس عمل کو مستحب جبکہ اہل ظاہر نے اسے واجب قرار دیا ہے۔ مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ اتنے عمل سے نماز باطل نہیں ہوتی۔ (شرح مسلم: ٢/ ٤٦٤، فتح الباری: ٢/ ١٦٧)"}],[6051,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، نبی صلے علی کیم جب بستر پر آئے تو یہ دعا پڑھا کرتے تھے: ”اے اللہ! میں نے اپنی جان تیرے سپرد کر دی، اپنا معاملہ تجھے سونپ دیا، اپنی پشت تیری طرف جھکائی، رغبت و شوق اور تیرے ڈر سے، تیرے سوا کوئی پناہ گاہ ہے نہ کوئی مقام نجات تو نے کتاب میں جو اتارا اور رسول کو جو کچھ دے کر بھیجا میں اس پر ایمان لایا۔ اس حدیث کو ثابت البنانی سے صرف حماد بن سلمہ نے روایت کیا۔ اس میں مؤمل بن اسماعیل کا تفرد ہے۔",""],[6052,"سیدنا صفوان فضل اللہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ میم نے فرمایا: ” جو ظہر سے پہلے چار کعتیں پڑھتا ہے، اس کے لیے غلام آزاد کرنے کے مثل ثواب ہے۔ یا فرمایا: ” اسماعیل ملنے نیم کی اولاد سے چار غلام آزاد کرنے کے مثل ثواب ملتا ہے۔“ اس حدیث کو صفوان الزہری سے صرف اس اسناد سے مروی ہے۔ اس میں زید بن اخزم کا تفرد ہے۔ قائد علامہ سیمی اللہ فرماتے ہیں: فيه جماعة لم اجد من ترجمهم - دیکھئے مجمع الزوائد: ٢٢٠/٢۔ تاہم ظہر کی نماز سے قبل چار رکعت پڑھنے کی فضیلت احادیث سے ثابت ہے۔ سیدہ ام حبیبہ نیا ٹیچا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو شخص ظہر کے فرضوں) سے پہلے چار رکعتوں کی اور ظہر کے بعد چار رکعتوں کی حفاظت کرے گا، (یعنی انہیں ہمیشہ پڑھے گا ) تو اللہ ذوالجلال اس پر جہنم کی آگ کو حرام فرما دے گا۔ (سنن ابی داؤد، رقم: ١٢٦٩، ترمذی، رقم: ٤٢٧) ایک دوسری حدیث میں ہے کہ رسول اللہ ملتے لیکن سورج ڈھلنے کے بعد ظہر سے پہلے چار رکعتیں پڑھا کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: یہ ایسی گھڑی ہے جس میں آسمان کے دروازے کھولے جاتے ہیں، پس میں پسند کرتا ہوں کہ میرے نیک اعمال اس گھڑی میں اوپر چڑھیں۔ (ترمذی، ابواب الصلوة، رقم: ٤٧٨)",""],[6053,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے ایک صحابی کے پاس گئے جبکہ وہ مریض تھا تو آپ نے دعا پڑھی، لوگوں کے رب! بیماری کو دور کر دے، شفا عطا فرما تو ہی شفا عطا فرمانے والا ہے، تیرے سوا کوئی شفا عطا کرنے والا نہیں، ایسی شفا عطا فرما جو کوئی بیماری نہ چھوڑے۔“ اس حدیث کو حماد بن ابی سلیمان سے صرف حماد بن سلمہ نے اور حماد سے صرف ہلال بن عبد الملک نے روایت کیا۔ اس میں ابو حفص کا تفرد ہے۔ مانده مذکورہ حدیث سے رسول اللہ صلی اللہ علیہ وسلم کا دم کرنا ثابت ہوا۔ اس لیے دم کرنے کے جواز ٢٩ م ٢٥ میں کوئی شک نہیں ہے۔ تا ہم کوشش یہ ہونی چاہیے کہ مریض پر وہی کچھ دم کیا جائے جو رسول اللہ علیم سے ثابت ہو اور دم کے ساتھ یہ عقیدہ ہو کہ ظاہری اسباب بذات خود مؤثر نہیں۔ یہ اللہ ذوالجلال کی مشیت ہی سے مؤثر ہو سکتے ہیں۔ ٦٠٥٤",""],[6054,"سیدنا ولید بن سورین نے بیان کیا، میں نے مکہ میں ایک شیخ کے پہلو میں صبح کی نماز پڑھی، جب وہ نماز سے فارغ ہوئے تو انہوں نے کہا: میں نے رسول اللہ ملنے نسیم کے بعد کسی ایسے شخص کے پیچھے نماز نہیں پڑھی، جس کی نماز رسول اللہ صلی اللہ علیہ وسلم کی نماز سے اس نوجوان سے زیادہ مشابہ ہو ان دنوں امام عمر بن عبد العزیز تھے۔ میں نے کہا: اللہ آپ پر رحم فرمائے! آپ کون ہیں؟ انہوں نے فرمایا: نس بن مالک۔“ اس حدیث کو الولید بن سورین سے صرف اس کے بیٹے بیٹی بن الولید نے اور بیٹی سے صرف عبد الملک الذماری نے روایت کیا۔","",{"f":"نا سنن ابی داؤد میں ہے، راوی کہتے ہیں: کہ ہم نے اندازہ لگایا کہ وہ اپنے رکوع اور سجدے میں دس دس تسبیحات کہتے تھے۔ (ابو داؤد، رقم: ٨٨٨، اسنادہ حسن) امام شوکانی جراللہ نے فرمایا: ہے کہ زیادہ سے زیادہ تسبیحات کی تعداد رکوع و سجود میں کسی صحیح حدیث سے ثابت نہیں ہے۔ نماز کی طوالت کے اعتبار سے زیادہ سے زیادہ بغیر عدد معین کے تسبیحات کہی جاسکتی ہیں۔ ٦٠٥٥"}],[6055,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، جس روز انہوں نے رسول اللہ صلی اللہ علیہ وسلم کا چہرہ زخمی کیا، ہم آپ (عالینڈ) کے لیے اونٹ کے چمڑوں میں پانی لاتے تھے۔“ اس حدیث کو ابو الحواری سے صرف المنہال بن بحر نے روایت کیا۔اس میں ابوحفص کا تفرد ہے۔ ٦٠٥٦",""],[6056,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”سوتے وقت اثمد (سرمہ لگایا کرو، وہ بال ( پلکیں) اگا تا اور نظر کو جلا بخشتا ہے۔ اس حدیث کو ہشام بن حسان سے صرف زیاد بن الربیع نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ سوتے وقت سرمہ لگانا سنت ہے۔ ٦٠٥٧",""],[6057,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”تم (نبیذ بنانے کے لیے منفی اور کھجور کو ملاؤ نہ خشک کھجور اور تازہ کھجور کو ملاؤ",""],[6058,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں خطبہ دیا تو فرمایا: ”عمری جائز ہے۔“ ان دونوں حدیثوں کو بسطام بن مسلم سے صرف ابو داود نے روایت کیا۔",""],[6059,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (نبیذ بنانے کے لیے ) منقی اور کھجور (ملانے) سے اور خشک کھجور اور تازہ کھجور (ملانے) سے منع فرمایا ہے۔‘ اس حدیث کو منصور بن دینار سے صرف ابو عاصم نے روایت کیا۔ ٦٠٦٠",""],[6060,"سیدنا عمرو بن شعیب نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا، انہوں نے کہا، رسول اللہ سے تم نے فرمایا: \"جو شخص بیٹھا بیٹھا سو جائے تو اس پر (نیا) وضو کرنا لازم نہیں، پس جب وہ اپنا پہلوں گا لے تو پھر اس پر وضو کرنا لازم ہے۔“ اس حدیث کولیٹ سے صرف الحسن بن ابی جعفر نے روایت کیا۔ اس میں عبد القاہر ابن شعیب کا تفرد ہے۔","",{"f":"مذکورہ روایت ضعیف ہے۔ نیند کے ناقض وضو ہونے کے متعلق اہل علم کے آٹھ مختلف اقوال ہیں۔ جس میں امام ابن حزم مرالله ( محلی بالاثار: ٢١٢/١)، علامہ ناصر الدین البانی رحمہ اللہ (تمام المنه ص: ١٠١)، الشیخ عبدالعزیز بن باز راه (فتاوی اسلامیه: ٢٠٨/١ ) کا موقف ہے کہ مطلقا نیند ناقض وضو ہے خواہ نیند بیٹھ کر آئے یا لیٹ کر یا کھڑے ہو کر، بشرطیکہ وہ گہری ہو اور اس سے شعور زائل ہو جائے۔ یہی موقف زیادہ راجح لگتا ہے۔ جن روایات سے معلوم ہوتا ہے کہ صرف لیٹ کر سونے والے کی نیند ہی ناقض ہے۔ وہ ضعیف ہیں۔ (تمام المنه ص: ١٠٢)"}],[6061,"سیدنا قعقاع بن ابی حد رد الا سلمی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: معد بن عدنان کی سی وضع اختیار کرو (وہ جفاکش، سادہ آدمی تھے، سخت جان رہو اور ننگے پاؤں چلو۔“ یہ: حدیث قعقاع بن ابی حدود سے صرف اس اسناد سے مروی ہے۔ اس میں صفوان بن عیسی کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ اس میں عبداللہ بن سعید المقبر کی المدنی متروک ہے۔",""],[6062,"سیدنا عبید اللہ بن ابی بکر بن انس نے بیان کیا، میں نے سیدنا انس بن مالک رضی اللہ عنہ سے تین چیزوں، سورج، چاند اور ستاروں کے متعلق سوال کیا، وہ کس چیز سے بنائے گئے؟ انہوں نے کہا: رسول اللہ ملے لی ایم نے مجھے بیان کیا، وہ عرش کے نور سے پیدا کیے گئے ہیں۔ یہ حدیث سیدنا انس رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں یزید بن عمرو بن البراء کا تفرد ہے۔:٦٠٦٣ .. حافظ ہیثمی جاللہ فرماتے ہیں: اس کے راوی محمد بن یونس عصفری: لم اجده",""],[6063,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو لوگوں کے معاملے کا ذمہ دار بنے اور اس کی نیت حق پر مبنی ہو، اس کے ساتھ دو فرشتے مامور کر دیے جاتے ہیں، جو اس کی راہنمائی کرتے ہیں اور جو شخص لوگوں کے کسی معاملے کا ذمہ دار بنے اور اس کی نیت حق پر نہ ہو تو اللہ اسے اس کی ذات کے حوالے کر دیتا ہے۔ یہ حدیث سیدنا ابو ہریرہ نبی الیہ سے صرف اس اسناد سے مروی ہے۔ اس میں یزید بن عمرو بن البراء کا تفرد ہے۔:٦٠٦٤ مذکورہ روایت ضعیف ہے۔ اس میں ابراہیم بن خظیم بن عراک ضعیف ہے۔",""],[6064,"سیدنا جابر فی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: غم تو قرض کا غم ہے اور تکلیف تو آنکھ کی تکلیف ہے\":٦٠٦٥ مذکورہ روایت موضوع ہے۔",""],[6065,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میری امت کے دو گروہ ہیں ان کا اسلام میں کوئی حصہ نہیں، مرجئہ اور قدریہ“:٦٠٦٦","",{"f":"مذکورہ روایت ضعیف ہے۔"}],[6066,"سیدنا جابر ضیا اللہ نے بیان کیا، نبی تعلیم نے فرمایا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! کعبہ کی ایک زبان اور دو ہونٹ ہیں۔ اس نے اللہ سے شکایت کی تو عرض کیا: رب جی! مجھے ملنے والے اور میری زیارت کے لیے آنے والے کم ہیں، پس اللہ عزوجل نے اس کی طرف وحی کی: میں خشوع و خضوع اور سجدے کرنے والی مخلوق انسان پیدا کرنے والا ہوں، وہ تیرے اس طرح مشتاق ہوں گے، جس طرح کبوتری اپنے انڈوں کی مشتاق ہوتی ہے۔“ اس حدیث کو ابن ابی ذئب سے صرف سہل بن قرین نے روایت کیا۔","",{"f":"مذکورہ روایت ضعیف ہے۔ ٦٠٦٧"}],[6067,"سیدنا عروہ بن زبیر نے بیان کیا، میں نے سیدہ عائشہ منی نیہا سے کہا: خالہ جان! میں آپ کے معاملے میں غور و فکر کرتا ہوں، میں کچھ چیزوں پر تعجب کرتا ہوں اور کچھ پر تعجب نہیں کرتا، میں نے:٦٠٦٨ آپ کو سب سے زیادہ فقیہ پایا ہے، میں نے کہا: انہیں کون سی چیز مانع ہو سکتی ہے؟ رسول اللہ ملنے ان کی زوجہ محتر مہ اور ابو بکر الصدیق رضی اللہ عنہ کی لخت جگر۔ میں نے آپ کو عرب کے انساب اور اس کے ایام کی بہت عالمہ پایا تو میں نے کہا: انہیں کون سی چیز مانع ہو سکتی ہے؟ ان کے والد قریش کے علامہ ہیں، لیکن تعجب یہ ہوتا ہے کہ میں نے آپ کو طب کی عالمہ پایا ہے تو یہ علم کہاں سے آیا؟ انہوں نے فرمایا: ”عر یہ! رسول اللہ صلی اللہ علیہ وسلم کے امراض زیادہ ہو گئے تھے تو ہم علاج کرتی تھیں۔ اس حدیث کو محمد بن عبد الرحمن ملیکی سے صرف خلاد بن یز ید الباہلی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٤٢/٩)، مجمع البحرين (٣٨٣٤)، اسناده ضعيف۔"}],[6068,"سیدہ عائشہ علی انہما سے روایت ہے کہ رسول اللہ ملنے سلیم نے انہیں ایک حدیث سنائی جبکہ آپ صلی اللہ علیہ وسلم ان کے ساتھ ایک لحاف میں تھے۔ انہوں نے عرض کیا: اللہ کے رسول! میرے والدین آپ صلی اللہ علیہ وسلم پر قربان ہوں، اگر آپ ملے یکم مجھے یہ حدیث نہ بیان کرتے تو میں خیال کرتی کہ وہ کوئی افسانہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! حدیث خرافہ (افسانہ) کیا ہے؟ انہوں نے عرض کیا: ایسی چیز جو نہ ہو تو کہا جاتا ہے حدیث خرافہ ( بے سروپا بات، افسانہ)، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سب سے سچی بات حدیث خرافہ ہے، بنو عذرہ کا ایک آدمی، جنوں نے اسے قیدی بنا لیا، وہ ان کے ساتھ رہتا تھا۔ پس جب وہ کوئی بات چوری چھے سن لیتے تو وہ اسے بتا دیتے تھے تو وہ اسے لوگوں کو بتا دیتا تھا۔ پس وہ اسے ویسے ہی پاتے تھے جیسے اس نے کہا ہوتا تھا۔ اس حدیث کو انس سے ثابت نے، ثابت سے صرف علی بن ابی سارہ نے اور علی سے صرف سعید بن عبد اللہ نے روایت کیا۔ اس میں یزید بن عمر والغنوی کا تفرد ہے۔ ٦٠٦٩","",{"k":"مجمع الزوائد (٣١٥/٤)، مجمع البحرين (٢٣٣٤)، اسناده ضعيف۔"}],[6069,"سیدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں سے کوئی لونڈی خریدے تو وہ سب سے پہلے اسے میٹھی چیز کھلائے، کیونکہ وہ اس کے لیے بہت اچھی ہے۔“ یہ حدیث سیدنا معاذ بن جبل رضی اللہ عنہ سے صرف اس اسناد سے روایت کی جاتی ہے۔ اس میں عثمان بن عبد الرحمن طرائھی -٠ کا تفرد ہے۔ ٦٠٧٠","",{"k":"مجمع الزوائد (٤/٢٣٦)، ضعيف الجامع الصغير (٥٣١٩)، سلسلة ضعيفة (٢٠٥٣)، مجمع البحرين (٣٠١٠)، اسناده ضعيف۔"}],[6070,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ پر ایمان لانے کے بعد عقل کی چوٹی لوگوں سے محبت کرنا ہے۔“ ٦٠٧١","",{"k":"مجمع الزوائد (٨/٣٨)، مجمع البحرين (٣٠١٠)، سلسله ضعیفه (٣٦٣١)، اسناده ضعيف۔"}],[6071,"و سیدہ عائشہ منی اشیا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں جو اختیار دیا، تھا کیا وہ طلاق تھی؟؟‘ اس حدیث کو بیان سے صرف زائدہ نے اور زائدہ سے صرف عبد اللہ بن رجا، خلف بن تمیم اور بیٹی بن یعلی بن الحارث نے روایت کیا۔ ٦٠٧٢","",{"k":"صحیح بخاری (٥٢٦٣)، صحیح مسلم (١٧٧٧)۔"}],[6072,"سیدنا عبد اللہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے تشہد کے بارے میں روایت کیا: ”تمام قولی، بدنی اور مالی عبادات اللہ کے لیے ہیں۔ سلام ہو آپ پر اے نبی! اور اللہ کی رحمت اور اس کی برکات ہوں، ہم پر اور اللہ کے صالح بندوں پر سلامتی ہو، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ محمد اس کے بندے اور اس کے رسول ہیں۔ “ اس حدیث کو ابن عون سے صرف عثمان بن الہیثم نے روایت کیا۔","",{"k":"صحیح بخاری (٨٣١)، صحيح = = مسلم (٤٠٢)۔"}],[6073,"سیدنا زید بن ثابت ولا لله بیان کرتے ہیں: یہ آیت: ” جو شخص کسی مومن کو عمداً قتل کر دے تو اس کی جزا جہنم ہے وہ اس میں ہمیشہ رہے گا، سورۃ الفرقان کی اس آیت: ” جولوگ اللہ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے اور وہ اس جان کو جسے اللہ نے حرام قرار دیا ہے، ناحق قتل نہیں کرتے۔“ سے چھ ماہ بعد نازل ہوئی۔ اس حدیث کو حماد بن زید سے صرف مسلم بن ابراہیم نے روایت کیا۔ فائد سوره نساء آیت نمبر ٩٣ اور سورہ فرقان کی آیت نمبر ٦٨ کا ترجمہ اوپر گزر چکا ہے اور سورہ فرقان آیت نمبر ٧٠ کا ترجمہ ہے، مگر جو تو بہ کرے، ایمان لائے اور عمل صالح اختیار کرے تو ایسے لوگوں کے گناہوں کو اللہ ذوالجلال نیکیوں سے بدل دیتا ہے۔ معلوم ہوا کہ دنیا میں خالص تو بہ سے ہر گناہ معاف ہوسکتا ہے، چاہے وہ کتنا ہی بڑا ہو اور سورہ نساء کی آیت میں جو مومن کے قتل کی سزا جہنم بتلائی گئی ہے تو وہ اس صورت پر محمول ہو گی جب قاتل نے تو بہ نہ کی ہو اور بغیر تو بہ کیے ہی فوت ہو گیا ورنہ حدیث میں آتا ہے کہ سو آدمی کے قاتل نے بھی خالص توبہ کی تو اللہ ذوالجلال نے اسے معاف فرما دیا۔ (صحیح مسلم، كتاب التوبه، رقم: ٢٧٦٦)","",{"k":"سنن ابو داود (٤٢٧٢)، سلسله صحیحه (٢٧٩٩)۔"}],[6074,"سيدنا قره ضیا اللہ نے بیان کیا، رسول اللہ ملنے کی ایم نے فرمایا: ”جو شخص ان دو درختوں (لہسن اور پیاز ) میں سے کھائے تو وہ ہماری مسجد کے قریب نہ آئے، اگر تم نے ضرور ہی ان کو کھانا ہو تو پکا کر ان کی بوختم کر لو۔“ اس حدیث کو معاویہ بن قرہ رضی اللہ عنہ سے صرف خالد بن میسرہ نے روایت کیا۔ مانده مذکورہ حدیث سے معلوم ہوا کہ لہسن اور پیاز حرام نہیں ہیں۔ اگر حرام ہوتا تو رسول اللہ صلی اللہ علیہ وسلم پکا کر ان کے کھانے کے اجازت نہ دیتے۔","",{"k":"سنن ابو داود (٣٨٢٧)، قال الشيخ ٦٠٧٤ الالباني: صحيح۔"}],[6075,"سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کو بندے کی وہ حالت سب سے زیادہ پسند ہے جب وہ اسے اپنے چہرے کو مٹی پر رکھے ہوئے سجدہ کرتے ہوئے دیکھتا ہے۔“ مذکورہ روایت ضعیف ہے، تاہم سجدہ کی حالت اللہ ذوالجلال کو بڑی پیاری لگتی ہے اور اس حال میں اللہ ذوالجلال کا قرب حاصل ہوتا ہے۔ جیسا کہ ارشاد ربانی ہے: وَاسْجُدْ وَاقْتَرِبْ ﴾ (العلق: ١٩) اور اپنے رب کے سامنے سجدہ کیجئے اور اس کا قرب حاصل کیجئے۔“ الله سیدنا ابو ہریرہ رضی نینہ سے مروی ہے کہ رسول اللہ ملنے سلیم نے فرمایا: یقیناً بندہ حالت سجدہ میں اپنے رب سے بہت قریب ہوتا ہے پس ( سجدے میں ) زیادہ سے زیادہ دعا کرو۔ (مسلم، کتاب الصلة، رقم: ٤٨٢) ایک دوسری حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب آدم علی نام کا بیٹا سجدے کی آیت تلاوت کرتا ہے اور سجدہ کرتا ہے تو شیطان اس سے دور ہو کر رونا شروع کر دیتا ہے اور وہ کہتا ہے: افسوس ہے! آدم علیہ سلام کے بیٹے کو سجدہ کرنے کا حکم دیا گیا، اس نے سجدہ کیا، اس کے لیے جنت ہے، مجھے سجدہ کرنے کا حکم دیا گیا، میں نے انکار کیا، میرے لیے دوزخ ہے۔ (مسلم، کتاب الایمان، رقم: ٢٤٤) ٦٠٧٦","",{"k":"مجمع البحرين (٥٤٤)، مجمع الزوائد (٣٠١/١)۔"}],[6076,"سيدنا عبد اللہ فی الین نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے، آپ کے ساتھ انصار کی کچھ خواتین تھیں، آپ نے انہیں وعظ و نصیحت کی اور فرمایا: ”جس عورت کے تین بچے فوت ہو جائیں وہ جنت میں داخل ہو گی۔ ایک عورت کھڑی ہوئی، وہ ان میں سے بڑی تھی، اس نے عرض کیا: اللہ کے رسول! جس کے دو بچے فوت ہوں، آپ نے فرمایا: ”جس کے دو فوت ہوں وہ بھی۔“ ان دونوں حدیثوں کو عاصم سے صرف الہیثم بن جہم نے روایت کیا۔ ان دونوں میں عثمان بن الہیثم کا تفرد ہے۔ ادب المفرد میں ہے کہ وہ عورت سیدہ ام سلیم بینی نوپا تھی جنہوں نے پوچھا کہ دو بچے فوت ہو جائیں تو کیا حکم ہے۔ (ادب المفرد، رقم: ١٤٩) معلوم ہوا کہ جس کسی مسلمان کے دو یا تین نابالغ بچے فوت ہو جائیں اور وہ ان پر صبر کرتا ہے اور اللہ کی رضا پر راضی رہتا ہے تو اس کی وجہ سے اللہ ذوالجلال اس کو جنت میں داخل فرمائیں گے۔ سیدنا ابو ہریرہ ہی یہ فرماتے ہیں: کہ ایک عورت نبی معظم صلی اللہ علیہ وسلم کے پاس ایک بچے کو لے کر آئی اور عرض کیا، اس بچے کے لیے دعا فرمائیں، میں تین بچوں کو دفن کر چکی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تو نے جہنم کے آگے مضبوط دیوار بنالی ہے۔ (ادب المفرد: ١٤٤۔ شیخ البانی رحمہ اللہ نے اس کو صحیح کہا ہے۔): الله،","",{"k":"مسند احمد (٥٤٦/١، ٣٩٩)، ادب المفرد للبخارى (١٤٩)، الشيخ الالباني: صحيح، قال۔"}],[6077,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے کنکری کو بیچ کی دو انگلیوں میں رکھ کر پھینکنے سے منع فرمایا اور فرمایا: ”اس سے شکار کیا جا سکتا ہے، نہ دشمن کو زخمی کر کے مارا جا سکتا ہے،:٦٠٧٨ لیکن وہ دانت توڑسکتی ہے اور آنکھ پھوڑ سکتی ہے۔ اس حدیث کو خزاعی بن زیاد سے صرف بہیثم بن جہم نے روایت کیا۔","",{"k":"صحیح بخاری (٦٢٢٠)، مسلم (١٩٥٤/٥٥)۔"}],[6078,"سیدنا ابو برزہ اسلمی نبی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر ہو سکے تو تم (نماز میں ) امام کے پیچھے کھڑے ہوا کرو ورنہ پھر اس کی دائیں طرف۔“ اس حدیث کو سیدنا ابو برزہ ضیا لینے سے صرف اس اسناد سے روایت کیا جاتا ہے۔ اس میں یہ عمران بن خالد الخزاعی کا تفرد ہے۔ ٦٠٧٩","",{"k":"مجمع الزوائد: (٢/٢٢)، اسناده ضعيف۔"}],[6079,"سیدنا عبادہ بن صامت رضی لالی نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہمارا رب تبارک و تعالیٰ ہر رات آخری تہائی حصے میں آسمان دنیا پر نازل ہوتا ہے اور کہتا ہے: جو بندہ میرے بندوں میں سے مجھ سے دعا کرے گا، میں اس کی دعا قبول کروں گا، اپنی جان پر ظلم کرنے والا مجھ سے دعا کرے گا تو میں اسے بخش دوں گا، جس پر رزق تنگ کر دیا گیا ہے وہ مجھ سے دعا کرے میں اس کا رزق فراخ کر دوں، مظلوم مجھے سے دعا کرے میں اس کی مدد کروں، کوئی مدد طلب کرے میں اس کی معاونت کروں۔ فرمایا: ” صبح ہونے تک یہ سلسلہ جاری رہتا ہے، پھر ہمارا رب عزوجل اپنی کرسی پر تشریف لے جاتا ہے۔“ یہ حدیث سیدنا عبادہ بن صامت رضی اللہ عنہ سے صرف اسی اسناد سے مروی ہے۔ اس میں عبد الرحمن بن مبارک کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/١٥٤)، اسناده ضعیف، اس میں محمد بن عثمان بن ابی سوید ضعیف ہے۔۔","f":"مذکورہ روایت ضعیف ہے، تاہم دوسری صحیح احادیث سے ثابت ہے کہ اللہ ذوالجلال آسمان دنیا پر آتے ہیں، جیسا کہ سیدنا ابو ہریرہ بنی الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہمارا رب تبارک و تعالیٰ ہر رات آسمان دنیا کی طرف نزول فرماتا ہے، اس وقت رات کا آخری تہائی حصہ باقی رہ جاتا ہے اور فرماتا ہے: کون ہے جو مجھ سے دعا کرتا ہے کہ میں اس کی دعا قبول کروں، کون ہے جو مجھ سے مانگتا ہے کہ میں اسے دوں، کون ہے جو مجھ سے بخشش طلب کرتا ہے کہ میں اسے بخش دوں؟ (بخاری، کتاب الدعوات، رقم: ٦٣٢١) مذکورہ روایت سے اللہ ذوالجلال کے نزول کا اثبات ہے یعنی خود اللہ ذوالجلال اپنی ذات کے ساتھ نزول فرماتا ہے لیکن بعض لوگ تاویل کرتے ہیں کہ اس سے مراد اللہ کی رحمت یا فرشتوں کا اترنا ہے، بی حض تاویل فاسد ہے۔ ٦٠٨٠"}],[6080,"سیده ام درداء علی اینجا بیان کرتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدنا سلمان رضی اللہ عنہ اور سیدنا ابو درداء رضی اللہ عنہ کے درمیان بھائی چارہ قائم کرایا۔ اس حدیث کو ابو غالب سے قریش بن حیان نے روایت کیا۔ اس میں عبد الرحمن بن المبارک کا تفرد ہے۔","",{"k":"صحیح بخاری (١٩٦٨)، سنن ترمذی (٢٤١٣)۔","f":"نبی معظم صلی اللہ علیہ وسلم نے مدینہ میں ہجرت کے پانچ ماہ بعد مہاجرین اور انصار صحابہ میں مواخات کرائی۔ ابتدا میں مؤاخات ترکہ میں میراث تک پہنچ گئی تھی یعنی منہ بولے بھائیوں کو مرنے والے بھائی کے ترکہ میں حصہ دیا جانے لگا مگر واقعہ بدر کے بعد آیت کریمہ ﴿ وَأُولُوا الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ نازل ہوئی جس سے ترکہ میں حصہ صرف حقیقی وارثوں کے لیے مخصوص ہو گیا، کیونکہ سیدنا سلمان فارسی ولی ہے جن کی کنیت ابو عبد اللہ تھی، ان کو نبی معظم صلی اللہ علیہ وسلم نے آزاد کروایا، یہ فارس کے شہر ہرمز رام کے رہنے والے مجوسی النسل تھے اور دین حق کی طلب میں انہوں نے ترک وطن کیا اور پہلے عیسائی ہوئے پھر ایک دفعہ ایک قافلے کے ساتھ سفر پہ تھے کہ اس کو ڈاکوؤں نے لوٹا اور سیدنا سلمان فارسی یا اللہ کو قیدی بنانے کے بعد فروخت کر دیا، بکتے بکاتے مدینہ منورہ کے یہودیوں کے ہاتھ لگے اور مدینہ پہنچ گئے۔ مدینہ منورہ میں پہنچے تو پہلی ہی صحبت میں دولت ایمان سے مالا مال ہو گئے تو ان کو نبی معظم صلی اللہ علیہ وسلم نے آزاد کروایا اور سیدنا ابو درداءرضی اللہ کے ساتھ مواخات کروا دی۔"}],[6081,"سیدنا عبداللہ ابن عباس بیا اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے پچھنے لگوائے اور پچھنے لگانے والے کو اس کی اجرت ادا کی۔“ اس حدیث کو ابو یزید بن المدینی سے صرف ابو عزہ الدباغ نے روایت کیا۔",""],[6082,"سیدنا عبداللہ ابن عم رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے اصحاب میں سے ایک آدمی سے سوال کیا تو فرمایا: ” تم نے آج کسی مریض کی عیادت کی؟“ اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ” تم نے کوئی صدقہ کیا ہے؟ اس نے عرض کیا: نہیں، آپ ملنے لیے تم نے فرمایا: ” تم نے کوئی نماز جنازہ پڑھی ہے؟“ اس نے عرض کیا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے اپنی کسی اہلیہ سے تعلق زن و شوہر قائم کیا ہے؟“ اس نے عرض کیا: نہیں، آپ ملنے سلیم نے فرمایا: ”ان میں سے کسی سے تعلق زن وشو ہر قائم کر، کیونکہ وہ تیری طرف سے ان پر صدقہ ہے۔“ یہ جمعہ کا دن تھا۔ اس حدیث کو صحر بن جویریہ سے صرف النضر بن عاصم بن ہلال نے روایت کیا: اس میں الجراح بن مجالد کا تفرد ہے۔ اسے نافع سے صرف صحر بن جویریہ نے روایت کیا اور عبداللہ ابن عمر رضی اللہ عنہا سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد ٢٩٢/٤۔","f":"اس روایت کے راوی نضر بن عاصم بن ہلال بارقی کے متعلق علامہ بیشمی اللہ فرماتے ہیں: لم اعرفه . (مجمع الزوائد: ٤/ ٢٩٢)"}],[6083,"سیدنا عبد اللہ ابن عباس نیلی انا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں اللہ پر گواہ ہوں کہ کوئی عاقل لغزش نہیں کرتا مگر وہ اسے بلندی عطا کرتا ہے، حتی کہ اس کا انجام جنت بنا دیتا ہے۔ اس حدیث کو ابراہیم بن میسرہ سے صرف محمد بن مسلم نے اور محمد بن مسلم سے صرف محمد بن عمر الرقی نے روایت کیا۔ اس میں یعقوب بن اسحاق القلوسی کا تفرد ہے۔: ٦٠٨٤","",{"k":"مجمع الزوائد (٢٨٥/٦)، سلسله ضعیفه، رقم: ٢٣٤٥ ضعيف الجامع الصغير (١٣٠٥)، اسناده ضعيف۔"}],[6084,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مومن سے بڑھ کر کوئی چیز اللہ کو عزیز نہیں، مومن اللہ کو ہر چیز سے زیادہ عزیز ہے۔“ اس حدیث کو یونس بن عبید اللہ سے صرف عبید اللہ بن تمام نے روایت کیا۔ اس میں عبد الغفار بن عبد اللہ الکریزی کا تفرد ہے۔ ٦٠٨٥","",{"k":"مجمع الزوائد (١/٨١)، اسناده ضعيف۔"}],[6085,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو یمن میں ہمارا امیر مقرر فر مایا اور سیدنا خالد بن ولید رضی لن لینے کو پہاڑ پر مقرر کیا اور فرمایا: ”اگر تم اکٹھے ہو جاؤ تو پھر علی سب کے امیر ہوں گے۔ پس ان کا مقابلہ ہوا اور انہیں اس قدر مال غنیمت ملا کہ اس سے پہلے اتنا مال غنیمت نہیں ملا تھا۔ سیدناعلی ضیا الیہ نے شمس سے ایک لونڈی لے لی تو سیدنا خالد بن ولیدر علی انہ نے سیدنا بریدہ ضیا کو بلایا تو کہا: اسے غنیمت جانو، انہوں نے جو کیا ہے اس کے متعلق نبی نے تم کو بتاؤ، پس میں مدینہ پہنچا اور مسجد میں داخل ہوا، جبکہ رسول اللہ صلی اللہ علیہ وسلم اپنے گھر میں تھے اور آپ صلی اللہ علیہ وسلم کے اصحاب میں سے کچھ لوگ آپ صلی اللہ علیہ وسلم کے دروازے پر تھے۔ انہوں نے کہا: بریدہ! کیا خبر ہے؟ میں نے کہا: خیر ہے، اللہ نے مسلمانوں کو فتح عطا فرمائی ہے۔ انہوں نے کہا: آپ پہلے کیوں آئے ہیں؟ انہوں نے کہا: ایک لونڈی ہے جسے سیدنا علی ضیا اللہ نے شمس میں سے لے لیا ہے۔ میں آیا ہوں تاکہ نبی نے یم کو اس کے متعلق بتاؤں۔ انہوں نے کہا: آپ کو بتاؤ، یہ واقعہ انہیں رسول اللہ ملے ان کی نظر سے گرا دے گا، جبکہ رسول اللہ ملنے لیے تم یہ باتیں سن رہے تھے، آپ صلی اللہ علیہ وسلم غصے کی حالت میں باہر تشریف لائے اور فرمایا: ”لوگوں کو کیا ہو گیا ہے کہ وہ علی کی تنقیص کرتے ہیں، جوعلی رضی اللہ عنہ کی تنقیص کرتا ہے وہ میری تنقیص کرتا ہے، جس نے علی کو چھوڑا اس نے مجھے چھوڑ دیا، علی مجھ سے ہیں اور میں علی سے ہوں، وہ میری طینت (مٹی) سے ہیں اور میں ابراہیم علینام کی طینت سے ہوں، جبکہ میں ابراہیم کالینام سے افضل ہوں، وہ ایک دوسرے کی اولاد ہیں اور اللہ سننے والا جاننے والا ہے۔ اور فرمایا: ” بریدہ! کیا تمہیں معلوم نہیں کہ علی نے جو لونڈی لی ہے اس کے لیے تو اس سے زیادہ لونڈیاں ہیں اور وہ میرے بعد تمہارے ولی سر پرست ہیں۔“ میں نے عرض کیا: اللہ کے رسول! صحابیت کے ذریعے مگر یہ کہ آپ اپنا ہاتھ بڑھا ئیں حتیٰ کہ میں نئے سرے سے اسلام پر بیعت کروں۔ انہوں نے کہا: میں آپ سے الگ نہیں ہو احتیٰ کہ میں نے اسلام پر آپ کی بیعت کی۔“ یہ حدیث ابو اسحاق سے صرف اس اسناد سے مروی ہے۔ اس میں حسین الاشقر کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٢٨/٩)، سلسله ضعیفه (٤٩٥٦)۔"}],[6086,"سیدہ ام سلمہ علی النیہا نے بیان کیا، رسول الله علیم نے فرمایا: ”احسان کرنا برائی میں گرنے سے بچاتا ہے اور مخفی صدقہ رب کے غصے کو ختم کر دیتا ہے، صلہ رحمی عمر دراز کرتی ہے، ہر نیکی صدقہ ہے، دنیا میں نیکی کرنے والے آخرت میں نیکی کرنے والے ہیں، دنیا میں اہل منکر آخرت میں اہل منکر ہیں، اہل معروف سب سے پہلے جنت میں داخل ہوں گے۔“ یہ حدیث سیدہ ام سلمہ بنلی انتہا سے صرف اس اسناد سے مروی ہے۔ اس میں عبید اللہ بن الولید الوصافی کا تفرد ہے۔ انون مذکورہ حدیث سے معلوم ہوا کہ احسان کرنا برائی میں گرنے سے بچاتا ہے۔ (٢) معلوم ہوا کہ مخفی صدقہ غضب الہی کو مٹاتا ہے۔ مخفی صدقہ کرنے والے خوش نصیب لوگوں کو اللہ عزوجل اپنے عرش کا سایہ عطا کرے گا۔ (٣) یہ بھی معلوم ہوا کہ صلہ رحمی سے عمر دراز ہوتی ہے۔ (٤) اہل معروف، معروف اچھے اعمال اور اچھے اخلاق کے لیے استعمال کیا جاتا ہے اور منکر برے اعمال اور برے اخلاق کے لیے استعمال ہوتا ہے۔اہل معروف آخرت میں بھی اہل معروف ہوں گے، مطلب یہ ہے کہ وہ آخرت میں اچھے لوگوں میں شمار ہوں گے اور اپنے اعمال کا اچھا بدلہ پائیں گے اور اس کے اچھے اعمال ہی اس کے سامنے آئیں گے، جو ان کی نجات اور فلاح کا ذریعہ ہوں گے، اس کے برعکس منکر اس کام کو کہتے ہیں جو شریعت میں کسی درجہ میں بھی برا ہو۔ جو لوگ دنیا میں برے اخلاق میں لگے رہتے ہیں، آخرت میں ان کے اعمال ان کے سامنے آئیں گے اور ان کا بدلہ پائیں گے۔","",{"k":"مجمع الزوائد (٣/١١٥)، مجمع البحرين (١٤٣٦)، صحیح ترغیب (٨٩٠)، اسناده حسن لغيره . فائده۔"}],[6087,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، میں اور نبی صلی اللہ علیہ وسلم ایک برتن میں غسل کیا کرتے تھے۔ اس حدیث کولیث سے صرف محمد بن کثیر نے روایت کیا۔","",{"k":"صحیح بخاری (٢٥٠)، صحیح مسلم (٣٢١)۔"}],[6088,"سیدہ عائشہ منی اش جا نے بیان کیا، نبی ملنے ایک یتیم جنبی ہو جاتے تھے پھر سو جاتے تھے، پھر جاگ جاتے اور پھر سو جاتے تھے اور آپ صلی اللہ علیہ وسلم پانی کو ہاتھ بھی نہیں لگاتے تھے۔“ اس حدیث کو کریب سے صرف محمد بن عبد الرحمن نے اور محمد سے صرف شریک نے روایت کیا۔ اس میں شاذان کا تفرد ہے۔ مانده پیچھے بھی احادیث گزر چکی ہیں کہ رسول اللہ علی علیکم وضو کر کے سویا کرتے تھے۔ جن احادیث میں وضو کر کے سونے کا تذکرہ ہے، علماء نے اس کو استحباب پر محمول کیا ہے۔ اسی طرح بغیر پانی چھوئے بھی سونا جائز ہے۔ لیکن افضل یہ ہے کہ کم از کم سونے سے پہلے وضو کر لیا جائے، رسول اللہ سے تم نے کبھی تو وضو کیا، تا کہ فضیلت ثابت ہو جائے اور کبھی وضو نہ کیا تا کہ رخصت رہے اور لوگوں کو عمل میں آسانی ہو۔ ٦٠٨٩","",{"k":"سنن ابن ماجه، قال الشيخ الالباني: صحيح۔"}],[6089,"سیدنا قرضہ بن کعب اور زید بن صوحان سے روایت ہے کہ وہ کوفہ کی طرف روانہ ہوئے۔ سیدنا عمر بن خطاب نیل اس لیے ان سے آگے نکل گئے، وہ اپنے جوتے بائیں ہاتھ میں پکڑے ہوئے تھے، وہ تقریباً تین میل ان سے آگے نکل گئے،حتی کہ وہ بنو عبد الاشہل پہنچ گئے، انہوں نے فرمایا: “ تم ایسے شہر میں جا رہے ہو کہ ان کی بھنبھناہٹ شہد کی مکھیوں کی بھنبھناہٹ کی طرح ہے، رسول اللہ صلی اللہ علیہ وسلم سے کم روایت کرنا، میں اس میں تمہارا شریک ہوں۔“ اس حدیث کو مطرف سے صرف عمرو بن ابی قیس نے روایت کیا۔ اس میں محمد بن سابق کا تفرد ہے۔ اس حدیث میں شعمی عن قرطہ اور زید بن صوحان سے صرف مطرف نے نقل کیا ہے۔ مذکورہ روایت سے منکرین حدیث حدیث کی اہمیت کے گھٹانے پر استدلال کرتے ہیں۔ جبکہ مقصود احادیث کے بیان کرنے میں احتیاط کو ملحوظ رکھنے کی طرف توجہ مبذول کرانا تھا۔ گویا اس سے اصل مقصد احادیث کو تحقیق کے ساتھ بیان کرنے کی اہمیت کو بیان کرنا تھا کہ نبی معظم صلی اللہ علیہ وسلم ن کی طرف غلط نسبت نہ ہو۔ ٦٠٩٠","",{"k":"سنن ابن ماجه۔"}],[6090,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اللہ اور اس کے فرشتے پہلی صف ( والوں ) پر رحمتیں بھیجتے ہیں۔“ اس حدیث کو سفیان سے صرف معلی بن عبد الرحمن نے روایت کیا۔","",{"k":"سنن ابو داود (٦٦٤)، قال الشيخ الالباني: صحيح۔"}],[6091,"سیده ام درداء بنی اشیا نے بیان کیا، فضالہ بن عبید کہا کرتے تھے: ”اے اللہ! میں تجھ سے قضا کے بعد رضا، موت کے بعد زندگی کی ٹھنڈک، تیرے چہرے کی طرف دیکھنے کی لذت اور تیری ملاقات کے شوق کا کسی نقصان اور گمراہ کن فتنے کے بغیر سوال کرتا ہوں۔ اور انہوں نے کہا کہ یہ وہ دعائیں ہیں جو رسول اللہ صلی اللہ علیہ وسلم پڑھا کرتے تھے۔“ یہ حدیث فضالہ بن عبید سے صرف اس اسناد سے مروی ہے۔ اس میں عثمان بن سعید احمصی کا تفرد ہے۔","",{"k":"البحرين، رقم: ٤٦٨١ . مجمع الزوائد (١٧٧/١٠)، صحيح الجامع الصغير (١٣٠١)، مجمع۔"}],[6092,"سیدنا انس بن مالک فی اللہ سے روایت ہے کہ عبد القیس کا وفد نبی صلی اللہ علیہ وسلم کے پاس آیا، پس اس اثنا میں کہ وہ آپ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ آپ صلی اللہ علیہ وسلم ان کی طرف متوجہ ہوئے تو آپ منے سی ایم نے انہیں کہا: ” ایک پھل تم اسے اس نام سے پکارتے ہو، ایک پھل ہے تم اسے اس نام سے پکارتے ہو۔ حتی کہ آپ صلی اللہ علیہ وسلم نے ان کے تمام پھلوں کے رنگ بتا دیے، لوگوں میں سے ایک آدمی نے آپ لم سے کہا: اللہ کے رسول! میرے والدین آپ ملنے کی تم پر قربان ہوں! اللہ کی قسم! اگر میں ہجر بستی کے وسط میں بھی پیدا ہوتا تو میں آپ صلی اللہ علیہ وسلم سے زیادہ نہ جانتا، میں گواہی دیتا ہوں کہ آپ صلی اللہ علیہ وسلم اللہ کے رسول ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس وقت سے تم میرے پاس بیٹھے ہو اسی وقت سے تمہاری سرزمین میرے سامنے بلند کر دی گئی۔ پس میں نے اس کے قریب و بعید کی ہر چیز کو دیکھا تمہارا بہترین پھل برنی کھجور ہے، وہ بیماری کو دور کرتی ہے جبکہ اس میں کوئی بیماری نہیں۔“ اس حدیث کو حمید الطویل سے صرف عثمان بن عبد اللہ العتیمی نے روایت کیا۔ اس میں عبید اللہ بن واقد کا تفرد ہے۔ ٦٠٩٣","",{"k":"میں عبید بن واقد قیسی ضعیف ہے۔ مجمع الزوائد (٤٠/٥)، مجمع البحرين (٤٠٧٢)، حاكم (٢٢٦/٤)، اس۔"}],[6093,"سیدنا عبداللہ ابن عباس نبی انتہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کلمات ہر بیماری کے لیے دوا ہیں: ” میں اللہ کے کامل کلمات اور اس کے تمام ناموں کے ذریعے موت اور زہریلی چیزوں کے شر سے، نظر بد کے شر سے، حاسد کے شر سے جب حسد کرے، شیطان اور اس کی اولاد کے شر سے پناہ چاہتا ہوں،تنیس فرشتے اپنے رب کے پاس آ کر کہتے ہیں: ہماری سرزمین میں بیماری ہے، بیماری ہے، وہ فرماتا ہے: اپنی زمین کی کچھ مٹی لو، پھر اپنے بیمار پر پھیرو، محمد ملنے کی یمن کا دم، جس نے اس پر کوئی بخششیں ( نذرانہ ) لی یا اسے کسی سے چھپایا تو وہ کبھی فلاح نہیں پائے گا۔“ یہ حدیث سیدنا ابن عباس بنایا جا سے صرف اس اسناد سے مروی ہے۔ اس میں معتمر بن سلیمان کا تفرد ہے۔ ٦٠٩٤",""],[6094,"سیدنا عقبہ بن صہبان نے بیان کیا، میں نے سیدہ عائشہ صلی علیہا سے کہا: مجھے اللہ تعالیٰ کے فرمان: ” پھر ہم نے اس کتاب کا ان لوگوں کو وارث بنایا، جنہیں ہم نے اپنے بندوں میں سے چن لیا، پس ان میں سے کچھ اپنی جان پر ظلم کرنے والے ہیں، کچھ اعتدال پسند اور کچھ اللہ کے حکم سے نیکیوں میں آگے","",{"k":"مجمع الزوائد (٩٦/٧)، سنن ترمذی، صحيح ترمذی (٢٥٧٧)، مجمع البحرين (٣٣٧٥)۔","f":"بڑھنے والے ہیں۔“ کے متعلق بتائیں، انہوں نے فرمایا: ”ر ہے سبقت کرنے والے وہ تو رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں گزر گئے اور آپ نے ان کے لیے جنت کی گواہی دی، رہے اعتدال پسند اس سے وہ مراد ہیں جنہوں نے ان کے آثار کی اتباع کی اور ان جیسے عمل کیے حتی کہ ان سے جاملے اور رہے اپنی جان کے لیے ظلم کرنے والے پس وہ میری مثل، تمہاری مثل اور جنہوں نے ہماری اتباع کی، انہوں نے ( مزید ) فرمایا: اور وہ سب جنتی ہیں۔“ اس حدیث کو عقبہ بن صبہان سے صرف ابو شعیب الصلت بن دینار نے روایت کیا۔ اس میں معتمر کا تفرد ہے۔ نا مذکورہ روایت میں تین طرح کے آدمی بیان کیے گئے ہیں۔\n(١) سابق بالخیرات وہ ہیں جو واجبات کے علاوہ مستحبات بھی بجالائیں اور محرمات اور مکروہات سے بھی بچیں\n(٢) اعتدال پسند وہ ہے جو واجبات کو ادا کریں اور محرمات سے بچیں لیکن بعض مستحبات کو چھوڑ دیں اور بعض مکروہات کا ارتکاب بھی کر لیں۔\n(٣) جان پر ظلم کرنے والے، جو بعض واجب بھی چھوڑ دیں اور بعض حرام چیزوں کا ارتکاب بھی کر لیں۔ حقیقت میں یہ تینوں مومن ہیں۔ سیدہ عائشہ نبی اش با سابق الخیرات میں سے ہے بلکہ ان میں سے بھی جو بہترین درجے والے ہیں ان میں ان کا بھی شمار ہوتا ہے لیکن انہوں نے اپنے لیے تواضع اختیار کی۔ ٦٠٩٥"}],[6095,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، ام سلیم بنی النا رسول اللہ صلی اللہ علیہ وسلم کی فوج میں زخمیوں کا علاج کرتی تھیں، انہوں نے عرض کیا: اللہ کے رسول! کاش! آپ صلی اللہ علیہ وسلم میرے بیٹے کے لیے دعا و م کریں، رسول اللہ علیم نے فرمایا: ”انیس؟\" انہوں نے عرض کیا: جی ہاں، پس آپ ملاے علی تم نے مجھے آگے بٹھا لیا اور میرے سر پر ہاتھ پھیرا اور فرمایا: ”انیس! مسلمان میرے بعد کئی شہر بسائیں گے، وہ جو شہر بسائیں گے ان میں سے ایک کو بصرہ کہا جائے گا، اگر تم وہاں جاؤ تو وہاں کی ریل پیل، وہاں کے بازاروں وہاں کے بادشاہ کے دروازے سے بچنا، اس سرزمین پر دھنسنا، مسخ ہو جانا اور پتھروں کا برسنا ہو گا، اس زمانے کی نشانی یہ ہے کہ عدل ختم ہو جائے گا، ظلم عام ہو جائے گا، زنا بہت ہو گا اور اسی دور میں جھوٹی گواہی عام ہو جائے گی۔“ یہ حدیث زیادہ الا برص سے صرف اسی اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد: ١١/٨ مجمع البحرين (٤٤٨٤)، سنده ضعيف۔"}],[6096,"سیدنا عبد اللہ ضل الیہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم، سیدنا ابو بکر و عمر اور عثمان علی ایم کو دیکھا وہ جنازے کے آگے آگے چلتے تھے۔ اس حدیث کو منصور بن المعتمر اور بکر بن وائل سے: صرف ہمام نے اور ہمام سے صرف ابو عبد الرحمن المقری اور عمرو بن عاصم الکلائی نے روایت کیا۔","",{"k":"سنن ابو داود (٣١٧٩)، سنن ترمذی (١٠٠٧)، قال الشيخ الالباني: صحيح۔"}],[6097,"سیدنا نافع ضیا اللہ نے بیان کیا، سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے کہا گیا: جب آپ مکہ کی طرف جاتے ہیں تو آپ سواری پر نماز پڑھتے ہیں جب آپ مدینہ کی طرف لوٹتے ہیں تو پھر آپ یہ کیوں نہیں کرتے ہیں؟ انہوں نے کہا: اگر میں نے رسول اللہ تم کو اس طرح کرتے ہوئے نہ دیکھا ہوتا تو میں یہ نہ کرتا۔‘ اس حدیث کو خصیف سے صرف عتاب بن بشیر نے روایت کیا۔ اس میں المقرئ کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ نفلی نماز سواری پر پڑھنا جائز ہے۔:٦٠٩٨","",{"k":"کر صحیح بخاری (١٠٩٥)۔"}],[6098,"سیدہ عائشہ بنی النیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدہ خدیجہ بنی ہویا کو جنت کے انگور کھلائے۔ اس حدیث کو الہی سے صرف وائل بن داود نے روایت کیا۔ اس میں مروان بن معاویہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩/٢٢٥)، سنده ضعيف۔"}],[6099,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ان کی خالہ سیدہ میمونہ بنی النیہا سے نکاح کیا جبکہ آپ ملنے کی ایم احرام کی حالت میں تھے۔“ اس حدیث کو جن محدثین نے ابن جریج سے روایت کیا ہے ان میں سے سعید بن سالم القداح کے علاوہ کسی ایک نے بھی عطا اور ابن عباس نی جا کے درمیان ابو شعثا کو داخل نہیں کیا۔ ٦١٠٠","",{"k":"صحیح بخاری (١٨٣٧)، صحیح مسلم (١٤١٠)۔"}],[6100,"سیده ربیع بنت معوذ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا اور سر پر ایک بار مسح کیا۔ اس حدیث کو الحسن بن عیاش سے صرف عبد الرحمن بن یونس نے روایت کیا۔ اس میں العباس کا انده مذکورہ حدیث سے معلوم ہوا کہ سر کا مسح صرف ایک مرتبہ ہی فرض ہے۔ اہل علم کی اکثریت اسی کی قائل ہے۔ بعض اہل علم تین مرتبہ سر کے مسح کے قائل ہیں۔","",{"k":"سنن ابو داود (٣٤)، قال الشيخ الالباني: حسن۔"}],[6101,"سيدنا ابو جحیفہ صلی اللہ نے بیان کیا، ہم نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حجہ الوداع کا حج کیا تو ہم واپس آنے تک دو دو رکعتیں پڑھتے رہے۔ اس حدیث کو کثیر بن قاروندا سے صرف فضیل بن سلیمان نے روایت کیا اور فضیل سے صرف عبد الرحمن بن عبد العزیز نے۔ اس میں العباس کا تفرد ہے۔ ناندو مذکورہ حدیث سے معلوم ہوا کہ آپ صلی اللہ علیہ وسلم نے دوران سفر مدینہ منورہ واپسی تک نماز قصر","",{"k":"معجم کبیر طبرانی (٤٨٦/١٥)۔","f":"کر کے ہی ادا فرمائی۔ ٦١٠٢"}],[6102,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو وَالذَّكَرِ وَالْأَنْقَی پڑھتے ہوئے سنا۔“ اس حدیث کو ہارون النحوی سے صرف یونس بن محمد نے روایت کیا۔ اس میں العباس کا تفرد ہے۔","",{"k":"صحیح بخاری (٤٩٤٤)، صحيح مسلم (٨٢٤)۔","f":": صحیح بخاری میں ہے، سیدنا ابو درداء رضی اللہ عنہ فرماتے ہیں: کہ یہ لوگ (یعنی شام والے) چاہتے ہیں کہ میں وما خلق الذكر والانثی پڑھوں، اللہ کی قسم! میں ان کی پیروی نہیں کروں گا۔ (صحيح بخاری، کتاب التفسير: ٤٩٤٤) کیونکہ سیدنا ابو درداء رضی اللہ عنہ نے نبی معظم تعلیم سے والذكر والانثی سنا تھا اس لیے انہوں نے ﴿ والذکر والانثی پڑھا اور ان کو دوسری قراءت کی خبر نہیں ہوئی۔ یعنی وما خلق الذکر والانثی کی جو اخیر قرات اور متواتر تھی اور مصحف عثمانی میں درج ہے۔"}],[6103,"سیدنا عمرو بن شعیب نے اپنے والد سے انہوں نے اپنے دادا سے روایت کیا، انہوں نے کہا: نبی ملنے سلیم نے فرمایا: ”ہر نشہ آور چیز حرام ہے۔ ابو القاسم الطبرانی نے بیان کیا، ابو یونس کا نام القوی ان کی عبادت پر قوت کی وجہ سے رکھا گیا، وہ قیام کرتے حتی کہ بٹھائے جاتے، وہ روتے حتی کہ اندھے ہو گئے اور وہ روزہ رکھتے حتیٰ کہ لکڑی کی طرح ہو گئے۔ اس حدیث کو ابو یونس سے صرف سعید بن سالم القداح نے روایت کیا۔ اس میں علی بن حرب کا تفرد ہے۔ . دیکھئے حدیث وفوائد نمبر ٦٢٦-١٦٣٤۔ ابو یونس قوی، ان کا نام حسن بن زید بجلی، علامہ ابن عدی نے اپنی ضعفاء ابن عدی میں لکھا ہے کہ کثرت سے یہ بیت اللہ کا طواف کرتے اس لیے ان کو قوی کہا جاتا ہے۔ دیکھئے (ابن عدی ضعفاء: ٤٢٦/٦، تهذيب الكمال: ٣٤٤/٦) یہ کوفہ کے رہنے والے تھے اور ثقہ راوی ہیں۔ (تهذيب الكمال: ٣٤٣/٦)","",{"k":"کی سنن ابو داود (٣٦٨٥)، طبرانی صغير (٩٨٣)، قال الشيخ الالباني: صحيح۔"}],[6104,"سیدنا ابو جبیره نبی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بچہ سات سال سردار ہے، سات سال غلام ہے اور سات سال وزیر ہے۔ پس اگر تم اکیس سال کے لیے اس کی مدد پر راضی ہو تو ٹھیک ورنہ اس کے پہلو پر مار تم نے اللہ عزوجل کے حضور اپنا عذر پیش کر دیا۔ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اسی اسناد سے مروی ہے۔ اس میں علی بن حرب کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨/١٥٩)، مجمع البحرين (٢٨٧٦)، كشف الشفاء (٢٩١٢)، اسناده ضعيف۔"}],[6105,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: یعقوب عالی سلام کا ایک بھائی تھا، ایک دن اس نے انہیں کہا: یعقوب کلینم! آپ عالینام کی بینائی جانے اور آپ علینا کی کمر جھک جانے کا کیا سبب ہے؟ انہوں نے فرمایا: ”میری بینائی جانے کا سبب یوسف علینا) پر رونا ہے اور میری کمر جھک جانے کا سبب بنیا مین کا غم ہے۔ پس جبریل علینا ان کے پاس آئے تو انہوں نے کہا: یعقوب کالینام! اللہ عزوجل ٢٩ قم ٢ ٢٠٠٢ آپ علینا کو سلام کہتا ہے اور آپ کا لینا سے فرماتا ہے: کیا آپ علینا کو میرے علاوہ کسی سے شکوہ کرتے ہوئے حیا نہیں آتی؟ یعقوب علینا نے کہا: میں اپنے شدید غم و رنج کی شکایت اللہ ہی سے کرتا ہوں۔ جبریل اینڈا نے فرمایا: ” یعقوب عالسلام! آپ عالی سلام جو شکایت کرتے ہیں اللہ اسے خوب جانتا ہے۔ پھر یعقوب علی اسلام نے کہا: رب جی! کیا تو عمر رسیدہ شخص پر رحم نہیں فرماتا تو نے میری بینائی لے لی اور میری کمر جھکا دی، پس تو میرے یوسف جو پھول ہیں انہیں مجھے لوٹا دے، میں موت سے پہلے اس کی خوشبو سونگھ لوں، پھر میرے رب میرے ساتھ جو تو چاہے کر لینا۔ پس جبریل علی سلام ان کے پاس آئے تو کہا: یعقوب السلام! اللہ آپ علی نام کو سلام کہتا ہے اور وہ کہتا ہے: خوش ہو جا، تیرا دل فرحت محسوس کرے، مجھے اپنی عزت کی قسم! اگر وہ دونوں فوت بھی ہو گئے ہوں گے تو میں تمہاری خاطر انہیں دوبارہ زندہ کروں گا۔ پس آپ گالینام مساکین کے لیے کھانا بنائیں، کیونکہ میں اپنے بندوں میں سے مسکینوں کو زیادہ پسند کرتا ہوں اور تم جانتے ہو کہ میں نے تمہاری بینائی سلب کی، نہ تمہاری کمر جھکائی اور یوسف علینا کے بھائیوں نے ان کے ساتھ کیا کیا؟ تم نے ایک بکری ذبح کی، ایک روزہ دار مسکین تمہارے پاس آیا، لیکن تم نے اس میں سے اس کو کچھ بھی نہ کھلایا، اس کے بعد یعقوب علی نام کا معمول تھا کہ جب ان کے پاس صبح کا کھانا آتا تو وہ منادی سے کہتے: تو وہ اعلان کرتا، سن لو! مساکین میں سے جو صبح کا کھانا کھانا چاہتا ہے وہ یعقوب علینا کے پاس کھانا کھائے اور اگر وہ روزہ سے ہوتے تو منادی سے فرماتے: وہ اعلان کرتا: سن لو! مساکین میں سے جو روزہ دار ہے وہ یعقوب کالینا کے پاس افطار کرے۔“ یہ حدیث نبی صلی اللہ علیہ وسلم سے صرف اسی اسناد سے مروی ہے۔ اس میں وہب بن بقیہ کا تفرد ہے۔ ٦١٠٦","",{"k":"ضعيف . مجمع الزوائد (٤٠/٧)، ضعیف ترغیب و ترهیب (١٨٥٩)، اسناده۔"}],[6106,"سیدنا انس بن مالک فی اللہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جس نے مجھے دیکھا اس کے لیے خوش خبری ہے، جس نے اسے دیکھا جس نے مجھے دیکھا اس کے لیے خوش خبری ہے اور جس نے اسے دیکھا جس نے مجھے دیکھنے والے کو دیکھا اس کے لیے خوش خبری ہے۔ تین بار","",{"k":"مجمع الزوائد (١٠/٢٠)، مجمع البحرين (٣٩٧٣)۔","f":"مذکورہ حدیث سے صحابہ نی نیم، تابعین اور تبع تابعین کی فضیلت واضح ہوتی ہے۔ نبی معظم تم نے اس زمانے کے لوگوں کو بہترین قرار دیا ہے جیسا کہ سیدنا ابو ہریرہ ہی یہ بیان کرتے ہیں کہ نبی معظم بنی اللہ نے فرمایا: میری امت کے بہترین افراد وہ ہیں جن میں مجھے بھیجا گیا، پھر وہ جو ان کے بعد آئیں گے ( یعنی تابعین ) پھر وہ جو ان کے بعد آئیں گے ( یعنی تبع تابعین ) اللہ ذوالجلال بہتر جانتا ہے کہ آپ صلی اللہ علیہ وسلم نے تیسری بار کا ذکر کیا تھا یا نہیں، پھر ایسے لوگ پیدا ہوں گے جو موٹاپے کو پسند کریں گے وہ شہادت دیں گے حالانکہ ان سے شہادت دینے کا مطالبہ نہیں کیا جائے گا۔"}],[6107,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما بیان کرتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے ابن صیاد سے فرمایا: میں نے تیرے لیے کوئی چیز چھپائی ہے۔ اس نے کہا: وہ دھواں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ” دور ہو جا۔“ اس حدیث کو ابو رجاء سے صرف سلیم بن زریر نے روایت کیا۔","",{"k":"صحیح بخاری، اخسا (١٧٢)۔","f":"ابن صیاد یہودی النسل تھا، بچپن میں وہ کا ہنوں سے ملتا جلتا تھا، اس کی باتیں کبھی سچی اور کبھی جھوٹ ہوا کرتی تھیں۔ اس کے بارے میں خیال کیا جاتا تھا کہ وہ دجال ہے، جب وہ بالغ ہوا تو مسلمان ہو گیا، اس نے حج کیا اور مسلمانوں کے ساتھ شامل ہو کر جہا د کیا، بعد ازاں اس کی کچھ باتوں اور واقعات سے شبہ گزرنے لگا کہ وہ دجال ہے، کہا جاتا ہے کہ جنگ حرہ کے موقع پر وہ گم ہو گیا اس کے بعد اس کا علم نہ ہو سکا۔ واقعہ حرہ، ٦٣ ہجری ذوالحجہ کو یزید بن معاویہ نے مدینہ منورہ پر چڑھائی کی تھی اور اس پر مسلط ہوا تھا اسی واقعہ کو تاریخ نے یوم الحرہ کے نام سے یاد رکھا ہے، اب سوال یہ پیدا ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ میں نے تیرے لیے کوئی چیز چھپائی ہے تو وہ کہنے لگا (دخ) حالانکہ اس طرح تھا تو علماء اس کا یہ جواب دیتے ہیں کہ نبی مکرم اے ہم نے ممکن ہے کہ صحابہ کرام بی سیم کی مجلس میں فرمایا ہو کہ میں نے ابن صیاد سے یہ سوال کرنا ہے اور شیطان نے جا کر بتا دیا ہو کہ آپ صلی اللہ علیہ وسلم نے تجھ سے یہ سوال کرنا ہے۔"}],[6108,"سیدنا سلمہ بن اکوع ری اہلیہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ کے دن (جمعہ کی) نماز پڑھا کرتے تھے، جبکہ دیواروں کا سایہ نہیں ہوتا تھا کہ ہم اس سے سایہ حاصل کر لیں۔“ یہ حدیث سیدنا سلمہ بن اکوع رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں یعلی بن حارث کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ لے لیام نماز جمعہ جلدی ادا فرما لیا کرتے تھے۔ جمعہ کا آخری وقت تو وہی ہے جو ظہر کا آخری وقت ہے البتہ اس کے ابتدائی وقت میں اہل علم کے درمیان اختلاف ہے۔ امام مالک، امام شافعی اور امام ابوحنیفہ دینہ کا کہنا ہے کہ نماز جمعہ کا اول وقت ظہر کا اول وقت ہی ہے، یعنی بعد از زوال آفتاب۔ جبکہ امام احمد جماللہ نے یہ موقف اپنایا ہے کہ نماز جمعہ زوال آفتاب سے پہلے بھی ادا کی جا سکتی ہے۔ (تحفة الاحوذی: ٣/ ٣٦، نیل الاوطار: ٥٤٩/٢، شرح مسلم: ٤١٣/٣، بداية المجتهد: ١/ ١١٤) انہوں نے مذکورہ بالا حدیث اور ان احادیث سے استدلال کیا ہے، سیدنا انس نبی الیہ سے مروی ہے کہ رسول اللہ اللہ علیہ تم اس وقت نماز جمعہ پڑھاتے۔ جب سورج ڈھلتا تھا۔ (بخاری، رقم: ٩٠٤، ابو داؤد، رقم: ١٠٨٤، مسند احمد: ٣/ ١٢٨) سیدنا جابر نبی الیہ سے مروی ہے کہ نبی معظم ملنے کی اہم نماز جمعہ پڑھاتے، پھر ہم اپنے اونٹوں کے پاس جاتے اور انہیں لے کر چلتے جبکہ سورج اس وقت ڈھل رہا ہوتا تھا، مراد ایسے اونٹ ہیں کہ جن پر سیراب کرنے کے لیے پانی لایا جاتا ہے۔(مسلم، کتاب الجمعة، رقم: ٨٥٨) شیخ عبد السلام جو اللہ نے مذکورہ حدیث کی وجہ سے کہا ہے کہ رسول اللہ ملنے کی بعض اوقات زوال سے پہلے بھی نماز جمعہ ادا کر لیا کرتے تھے۔ لہذا یہ بھی جائز ہے البتہ افضل یہی ہے کہ زوال کے بعد ہی نماز جمعہ ادا کی جائے کیونکہ زیادہ تر آپ صلی اللہ علیہ وسلم کا یہی عمل تھا اور اس لیے بھی کہ اس وقت پر سب مسلمانوں کا اجماع ہے۔ (توضیح الاحکام: ٢/ ٥٦٨) یہی راجح معلوم ہوتا ہے۔ (واللہ اعلم)","",{"k":"صحیح بخاری (٤١٦٨)، صحيح مسلم، رقم: حين تزول الشمس (٣٢/٨٦٠)۔"}],[6109,"سیدنا عبداللہ ابن عباس نوای اینجا نے فرمایا: ”تمہارے نبی ملتے ہیم کو پچاس نمازوں کا حکم دیا گیا تھا، انہوں نے اپنے رب سے درخواست کی کہ وہ انہیں پانچ کر دے۔“ اس حدیث کو عبد اللہ بن عصم سے صرف شریک نے روایت کیا۔","",{"k":"مسند احمد (١/٣١٥)، قال شعیب الارناؤط : صحيح لغيره۔","f":"اندن صحیح بخاری میں ہے کہ سیدنا انس بن مالک روی لینہ نے سیدنا ابو ذر رضی اللہ عنہ سے نقل کیا ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” پس اللہ تعالیٰ نے میری امت پر پچاس نماز میں فرض کیں، میں یہ حکم لے کر واپس لوٹا، جب سیدنا موسیٰ علینام تک پہنچا تو انہوں نے پوچھا کہ آپ صلی اللہ علیہ وسلم کی امت پر اللہ ذوالجلال نے کیا فرض کیا ہے؟ میں نے کہا: پچاس نمازیں فرض کی ہیں۔ انہوں نے فرمایا: آپ ملے لیے واپس اپنے رب کی بارگاہ میں جائیں، کیونکہ آپ مے علم کی امت اتنی نمازوں کو ادا کرنے کی طاقت نہیں رکھتی۔ میں واپس بارگاہ رب العزت میں گیا تو اللہ ذوالجلال نے اس میں سے ایک حصہ کم کر دیا۔ پھر موسیٰ علینا کے پاس آیا اور کہا: ایک حصہ کم کر دیا گیا ہے۔ انہوں نے کہا: دوبارہ جائیں کیونکہ آپ ملنے کی یمن کی امت میں اس کی بھی طاقت نہیں، پھر میں بارگاہ رب العزت میں حاضر ہوا۔ پھر ایک حصہ کم ہوا۔ جب موسی علینا کے پاس پہنچا تو انہوں نے فرمایا: اپنے رب کی بارگاہ میں پھر جائیں، کیونکہ آپ صلی اللہ علیہ وسلم کی امت اس کو بھی برداشت نہیں کر سکے گی، پھر میں بار بار آنا جانا رہا، پس اللہ ذوالجلال نے فرمایا کہ یہ نمازیں ( عمل میں ) پانچ ہیں اور ( ثواب میں ) پچاس (کے برابر) ہیں، میری بات بدلی نہیں جاتی۔“ (صحیح بخاری، کتاب الصلوة، رقم: ٣٤٩)"}],[6110,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم تشریف فرما تھے اور دو بکریاں چر رہی تھیں، پس ان میں سے ایک نے دوسری کو سینگ مار دیا تو اس نے اسے گرا دیا۔ رسول اللہ لئے علیکم یہ منظر دیکھ کر مسکرا دیے۔ آپ ملنے مدینہ سے عرض کیا گیا، آپ ملنے ہی کیوں مسکرائے ہیں؟ آپ ملنے کی ہم نے فرمایا: ” مجھے اس پر تعجب ہوا ہے، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! قیامت کے دن اسے بدلہ دلایا جائے گا۔ ہنریل بن شرحبیل نے سیدنا ابو ذر رضی اللہ عنہ سے صرف یہی ایک حدیث روایت کی ہے۔ ہنریل سے اسے صرف عبد الرحمن بن شروان ابو قیس نے روایت کیا، ابو قیس سے صرف لیث بن ابوسلیم نے، لیٹ سے صرف حماد بن سلمہ اور صدقہ بن موسی الرقیقی نے روایت کیا۔","",{"k":"مجمع الزوائد (١٠/٣٥٥)، مسند احمد (١٧٢/٥)، مجمع البحرين (٤٧٩٦)، قال شعیب الارناؤط: حدیث حسن . والله۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قیامت کے دن حیوانات کو بھی قصاص دلوایا جائے گا۔ مذکورہ حدیث سے ان لوگوں کا بھی رد ہوتا ہے جو کہتے ہیں کہ جانوروں کو حشر میں جمع نہیں کیا جائے گا۔ ایک دوسری حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مخلوقات کو ایک دوسرے سے قصاص دلایا جائے گا کہ بے سینگ جانور کو سینگ والے جانور سے اور چیونٹی تک کو قصاص دلوایا جائے گا۔ (مسند احمد: ٣٦٣/٢) امام نووی اللہ فرماتے ہیں: کہ اس حدیث میں یہ صراحت کر دی گئی ہے کہ روز قیامت جانوروں کا بھی حشر ہوگا اور قرآن مجید کی اس آیت سے بھی ثابت ہوتا ہے: ﴿وَاذَا الْوُحُوشُ حُشِرَتْ ﴾ (التكوير"}],[6111,"زہری نے بیان کیا، جو شخص جمعہ کی شب غسل کرتا ہے اور دو رکعتیں پڑھتا ہے جن میں ہزار بار سورۃ الاخلاص پڑھتا ہے، پھر وہ وضو کی حالت میں سو جاتا ہے تو اسے خواب میں نبی صلی اللہ علیہ وسلم کی زیارت ہوتی ہے۔ محمد بن عکاشہ نے بیان کیا: میں نے دو سال سے زائد عرصہ اس پر متواتر عمل کیا، میں ہر جمعہ کی شب غسل کرتا، دو رکعتیں پڑھتا اور ان میں ہزار بار سورہ اخلاص پڑھتا اور یہ سب اس طمع سے کرتا کہ میں خواب میں نبی میم کی زیارت کروں۔ پس میں نے جمعہ کی رات دورکعتیں پڑھیں، ان میں ہزار بار سورہ اخلاص پڑھی، پس جب میں بستر پر سوگیا تو مجھے احتلام ہو گیا، میں کھڑا ہوا، نسل کیا اور دورکعتیں پڑھیں، ان میں ہزار بار سورۂ اخلاص پڑھی، جب میں ان دو رکعتوں سے فارغ ہوا تو سحری کا وقت تھا۔ میں نے دیوار کے ساتھ ٹیک لگائی اور میرا چہرہ قبلے کی طرف تھا تو نبی صلے علی تیم مذکورہ صفات کے مطابق میرے پاس تشریف لائے، آپ صلی اللہ علیہ وسلم پر دو یمنی چادریں تھیں ایک کا ازار تھا اور دوسری آپ صلی اللہ علیہ وسلم کے اوپر تھی، پس آپ صلی اللہ علیہ وسلم آئے بائیں پاؤں پر سیدھے کھڑے ہو گئے اور دائیں کو کھڑا کر لیا، محمد بن عکاشہ نے کہا: میں نے ارادہ کیا کہ میں کہوں: (( حياك الله) تو آپ میم نے مجھ سے پہلے ہی کہ دیا: (( حياك الله )) میں آپ صلی اللہ علیہ وسلم کے وہ دانت دیکھنا چاہتا تھا جو ( غزوہ احد میں ) ٹوٹ گئے تھے، پس رسول اللہ ملے عام مسکرائے تو میں نے آپ صلی اللہ علیہ وسلم کے سامنے والے چار دانت دیکھ لیے جو کہ ٹوٹے ہوئے تھے، میں نے عرض کیا: اللہ کے رسول! فقہاء نے مجھے التباس کا شکار کر دیا ہے، میرے پاس سنت سے دواصل ہیں، میں وہ آپ ملے لیے تم پر پیش کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں۔‘ میں نے عرض کیا: اللہ کی قضاء پر رضاء اللہ کے حکم پر سر تسلیم خم کر دینا، اس کے حکم پر صبر کرنا، اللہ نے جس چیز کا حکم فرمایا ہے اسے لے لینا، جس سے منع فرمایا ہے، اس سے رک جانا، اخلاص کے ساتھ اللہ کی خاطر عمل کرنا، تقدیر کے اللہ:٢٠ کی طرف سے اچھا، برا ہونے پر ایمان رکھنا، دین کے بارے میں بحث و مناظرہ ترک کرنا، موزوں پر مسح کرنا، ہر خلیفہ کی معیت میں جہاد کرنا، ہر نیک و فاجر کے ساتھ جمعہ پڑھنا، اہل قبلہ میں سے فوت ہو جانے والے کی نماز جنازہ پڑھنا، ایمان قول و عمل کا نام ہے، وہ زیادہ اور کم ہوتا ہے، قرآن اللہ کا کلام ہے وہ مخلوق نہیں، بادشاہ کے پر چم تلے رہنا، خواہ وہ عدل کرتا ہو یا ظلم، حکمران اگر ظلم بھی کریں ان کے خلاف بغاوت نہ کرنا، اہل قبلہ میں سے کسی کو جنتی قرار دینا نہ جہنمی، اہل توحید میں سے کسی کی تکفیر نہ کرنا خواہ وہ کبیرہ گناہ کرتے ہوں، رسول اللہ علیم کے اصحاب بینی نسیم کی تقصیروں پر خاموش رہنا، رسول اللہ صلی اللہ علیہ وسلم کے بعد سب سے افضل سیدنا ابو بکر نیا لیے ہیں او رپھر سیدنا عمر ضیا انہیں محمد بن عکاشہ نے بیان کیا: عثمان و علی نلی اینجا کا ذکر کرتے وقت میں نے توقف کیا۔ میں نبی صلی اللہ علیہ وسلم سے ڈر گیا کہ میں سیدنا عثمان رضی اللہ عنہ کو سیدنا علی ضیا اللہ پر فضیلت دوں۔ میں نے دل میں کہا: علی علی الیہ آپ صلی اللہ علیہ وسلم کے چچا زاد ہیں اور عثمان رضی اللہ عنہ ہے آپ صلی اللہ علیہ وسلم کے داماد ہیں۔ رسول اللہ ملے عام مسکرا دیے گویا کہ آپ صلی اللہ علیہ وسلم جان چکے تھے، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”عثمان، پھر علی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” یہ سنت ہے اس سے تمسک اختیار کرو۔ آپ صلی اللہ علیہ وسلم نے اپنی انگلیاں ملائیں، ترانوے کی گرہ لگائی اور اپنے انگو ٹھے کو انگلیوں کے اوپر ملایا۔ محمد بن عکاشہ نے بیان کیا: میں نے تین راتیں یہ اصول آپ صلی اللہ علیہ وسلم پر پیش کیے، میں ہر رات علی و عثمان ڈا پہنچا پر وقوف کرتا تھا اور میرے اس وقوف کرنے ( ٹھہرنے) پر آپ صلی اللہ علیہ وسلم مسکراتے تھے، گویا کہ آپ ملنے ندیدیم جان جاتے تھے، پھر آپ مطلئے علی یکم فرماتے: ” عثمان، پھر علی، پس اس کو تھام لو۔“ محمد بن عکاشہ نے بیان کیا، میں یہ اصل آپ صلے علی یم پر پیش کرتا تھا اور آپ مطلئے علیم کے رونے کی وجہ سے آپ ملنے کی آنکھیں اشک بار ہو جاتی تھیں، اگر میں کہتا: رسول اللہ صلی اللہ علیہ وسلم کے اصحاب علی ایم کی تقصیروں پر خاموش رہنا تو آپ صلی اللہ علیہ وسلم خوب روتے حتی کہ آپ ملے عام کی آواز بلند ہو جاتی تھی۔ محمد بن عکاشہ نے بیان کیا: میں نے اس خواب کے بعد اپنے منہ اور دل میں حلاوت پائی، میں نے آٹھ دن تک کھانا بند کر دیا، حتی کہ میں فرض نماز پڑھنے سے عاجز ہو گیا۔ پس جب میں نے کھانا کھا لیا تو میرے منہ سے وہ حلاوت جاتی رہی۔“","",{"k":"کر تاریخ دمشق (٣٠١/٩)۔"}],[6112,"سیدنا انس بن مالک نیلی اہلیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال کی وجہ سے چور کا ہاتھ کا ٹا، اس کی قیمت تین درہم تھی۔ یہ حدیث اسماعیل بن محمد بن سعد سے صرف عبد اللہ بن جعفر المخزومی نے روایت کیا۔ اس میں نعمان بن شبل کا تفرد ہے۔","",{"k":"سنن نسائی (٤٩١٠)، قال الشيخ الالباني: صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ تین درہم یا تین درہم کی قیمت کے برابر کوئی چیز چوری کی تو ہاتھ کاٹا جائے گا۔ پیچھے حدیث گزر چکی ہے کہ چور کا ہاتھ نہیں کاٹا جائے گا، مگر ربع دینار، ان دونوں میں تین درہم اور چوتھائی درہم کی قیمت مراد تھی۔ ٦١٣"}],[6113,"سیدنا عبد اللہ ابن عباس ولی اشیا سے اللہ عزوجل کے فرمان: ”ان کے متعلق صرف قلیل ہی جانتے ہیں۔“ کی تفسیر میں مروی ہے۔ سیدنا عبداللہ ابن عباس پایا جا نے فرمایا: میں ان قلیل میں سے ہوں مکسملیت ملی۔ یہ وہ ہے جسے کرنسی دے کر کھانا لانے کے لیے شہر بھیجا تھا مرولس، یونس، ذرتونس، کفاشطیطوس، منطنو اسیسوس یہ چرواہا ہے اور کتے کا نام قطمیر ہے، وہ کردی سے چھوٹا اور قبطی سے بڑا ہے، میں گمان نہیں کرتا کہ وہ قبطی سے بڑا ہو۔ ابو بل نے بیان کیا، میرے والد نے کہا: مجھے خبر پہنچی کہ جس نے یہ نام کسی چیز میں لکھے اور انہیں آگ میں پھینکا تو آگ بجھ گئی۔“ اس حدیث کو ابو روق سے صرف اس کے بیٹے کی۔ روایت کیا۔","",{"k":"١٠١٩٩٠ کر مجمع الزوائد (٥٣/٣)، مجمع البحرين (٣٣٥٩)، اسناده ضعيف۔"}],[6114,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ مسلہ سلم نے فرمایا: \"جو شخص ہر جمعے اپنے والدین یا ان میں سے کسی ایک کی قبر کی زیارت کرتا ہے تو اسے بخش دیا جاتا ہے اور وہ اچھا سلوک کرنے والا لکھ دیا جاتا ہے۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ اس میں بیٹی بن العلاء کا تفرد ہے۔ ٦١١٥","",{"k":"صلى الله عليه وسلم مجمع الزوائد (٥٩/٣)، مجمع البحرين (١٣٢٩)، سلسله ضعیفه، رقم: ٤٩ قال الشيخ الالباني: موضوع۔"}],[6115,"سیدنا عبداللہ ابن عباس ریلی لا سے روایت ہے کہ ایک آدمی نے عرض کیا: اللہ کے رسول! کیا دعا کے کچھ ایسے کلمات بھی ہیں جو ضرور قبول ہوتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں، تم کہو: میں تیرے اعلی، انتہائی عزیز، شان و اکرام والے نام کے ساتھ تجھ سے سوال کرتا ہوں۔“ یہ حدیث سیدنا ابن عباس قیلی اینجا سے صرف اس اسناد سے مروی ہے، اس میں یعقوب بن جعفر کا تفرد ہے۔ م و م ٦١١٦","",{"k":"مجمع الزوائد (١٥٦/١٠)، مجمع البحرين (٤٦٣٦)، اسناده ضعيف۔"}],[6116,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، عثمان رضی اللہ عنہما نے مجھے بتایا کہ رسول اللہ علیم نے جس وقت اپنی دوسری بیٹی کی مجھ سے شادی کی تو آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: ”اگر میری دس بیٹیاں بھی ہوتیں تو میں یکے بعد دیگرے تمہاری ان کے ساتھ شادی کر دیتا، کیونکہ میں تم سے راضی ہوں۔“ یہ حدیث سیدنا عبداللہ ابن عباس نیا اینجا کے حوالے سے عثمان رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے۔ اس میں یعقوب بن جعفر کا تفرد ہے۔ ٦١١٧","",{"k":"الزوائد (٨٣/٩)، مجمع، اسناده ضعيف . البحرين (٣٦٧٧)، مجمع۔"}],[6117,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اچھے چہرے والوں سے خیر و بھلائی طلب کرو۔“ اس حدیث کو محمد بن المنکدر سے صرف عمر بن صہبان نے روایت کیا۔ اس میں سلیمان بن کر ان کا تفرد ہے۔ سیدنا جابر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔","",{"k":"کر جمع الزوائد (١٩٤/٨)، مسند ابی یعلی (٤٧٥٩)، سلسله ضعیفه (٢٨٥٥)، اسناده ضعيف۔"}],[6118,"سیدنا بریدہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا کہ انہوں نے ایک آدمی کو بیماری میں مبتلا دیکھا تو آپ ملنے کی ایم نے فرمایا: ”ہو سکتا ہے کہ تم نے اس (اللہ تعالیٰ ) سے سوال کیا ہو کہ وہ تمہیں دنیا میں آزمائش سے دو چار کر دے، اس نے عرض کیا، جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے اللہ سے عافیت کا سوال کیوں نہ کیا اور تم کہتے: اے اللہ! ہمیں دنیا میں بھلائی عطا فرما اور آخرت میں بھلائی عطا فرما اور ہمیں جہنم کے عذاب سے بچا۔ اس حدیث کو الحارث بن حصیرہ سے صرف اسرائیل نے روایت کیا اور بریدہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ ناده صحیح مسلم میں ہے سیدنا ان نبی اللہ سے روایت ہے: رسول اللہ صلی اللہ علیہ وسلم نے ایک مسلمان کی عیادت کی جو بیماری سے چوزے کی طرح ہو گیا، ( یعنی بہت ضعیف اور ناتواں ہو گیا تھا ) آپ صلی اللہ علیہ وسلم نے اس سے فرمایا تو کچھ دعا کیا کرتا تھا یا اللہ ذوالجلال سے کچھ سوال کیا کرتا تھا؟ وہ بولا: ہاں میں یہ کہا کرتا تھا: یا اللہ! جو کچھ تو مجھ کو آخرت میں عذاب کرنے والا ہے وہ دنیا ہی میں کر دے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سبحان اللہ! تجھے اتنی طاقت کہاں ہے کہ اللہ ذوالجلال کا عذاب اٹھا سکو تو نے یہ کیوں نہیں کہا؟ اور مجھ کو بچالے جہنم کے عذاب سے، پھر آپ صلی اللہ علیہ وسلم نے اس کے لیے اللہ عزوجل سے دعا کی، اللہ تعالیٰ نے اس کو اچھا کر دیا۔","",{"k":"مجمع الزوائد (٢/٢٩٠)، مسلم (٢٦٨٨)۔","f":"(مسلم، رقم: ٢٦٨٨) مذکورہ حدیث سے معلوم ہوا کہ ایسی دعا نہیں کرنی چاہیے کہ دنیا میں عذاب دے دے اور آخرت کو بچا لینا، انسان تو بہت زیادہ کمزور ہے ذراسی بھی بیماری، تکلیف برداشت نہیں کرسکتا، بلکہ اللہ ذوالجلال سے دنیا و آخرت کے عذابوں اور دنیا و آخرت کی مصیبتوں سے بچنے کے لیے ہر وقت ((رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ)) یا اللہ! مجھ کو دنیا میں بھی بھلائی دے اور آخرت میں بھی بھلائی دے۔“ پڑھتے رہنا چاہیے۔ ١١٩"}],[6119,"سیدہ اسماء بنت عمیس ولی اینجا سے روایت ہے کہ نبی تعلیم نے بنو عبد المطلب کو اکٹھا کیا تو آپ صلی اللہ علیہ وسلم نے انہیں فرمایا: ”اگر تم میں سے کسی کو رنج و غم یا کوئی تکلیف یا بیماری یا کوئی سختی پہنچے تو وہ تین بار یہ دعا پڑھے: اللہ میرا رب ہے، میں اس کے ساتھ کسی کو شریک نہیں ٹھہرا تا۔“ راوی نے بیان کیا: عمر بن عبد العزیز اللہ کا موت کے وقت یہ آخری کلام تھا۔ اس حدیث کو سفیان بن عیینہ سے صرف الرمادی نے روایت کیا۔","",{"k":"کی سنن ابو داود كتاب الصلاة (١٥٢٥)، سنن ابن ماجه (٣٨٨٢)، سلسله ضعیفه (٢٨٥٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مذکورہ بالا الفاظ پڑھنے کی وجہ سے تکلیفیں، بیماریاں، پریشانیاں ختم ہو جاتی ہیں۔ اس دعا میں یہ راز ہے کہ بندہ جس قدر اپنے خالق و مالک سے ربط و تعلق میں مضبوط ہوگا، اسی قدر دنیا وی پریشانیوں سے محفوظ رہے گا اور اس کے دل کو تسکین ہوگی۔ جیسا کہ ارشاد باری تعالیٰ ہے: الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللهِ الَّا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ (الرعد: ٢٨) ”جو لوگ ایمان لائے ان کے دل اللہ کے ذکر سے اطمینان حاصل کرتے ہیں۔ یاد رکھو! اللہ کے ذکر سے ہی دلوں کو تسلی حاصل ہوتی ہے۔“ لیکن جو اللہ ذوالجلال کی نافرمانی کر کے اپنے آپ کو راحت میں سمجھتے ہیں فریب خوردہ ہیں، حقیقت یہ ہے کہ اللہ ذوالجلال نے انہیں مہلت دی ہوئی ہے اور آخرت میں سکون نہیں بلکہ پریشانیاں ہی پریشانیاں ہیں۔"}],[6120,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دنیا سے بے رغبتی دل و جسم کو راحت پہنچاتی ہے۔ اس حدیث کو علی بن زید سے صرف اشعث بن براز نے روایت کیا۔اس میں بیچی بن بسطام کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٨٦/١٠)، ضعیف ترغیب (١٨٦٧)، اسناده ضعیف۔"}],[6121,"سیدنا عبد اللہ فی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم اپنی دائیں طرف سلام پھیرتے تھے حتی کہ آپ ملے عالم کی دائیں رخسار کی سفیدی نظر آ جاتی تھی اور آپ ملے علام فرماتے تھے: \"السلام علیکم ورحمۃ اللہ “ اور اسی طرح بائیں طرف کرتے تھے۔ اس حدیث کو حماد، عن ابراہیم، عن علقمہ کی سند سے صرف ہشام بن عبد الرحمن اور محمد بن ابان نے روایت کیا۔","",{"k":"سنن ابو داود (٩٩٦)۔"}],[6122,"سیدنا عبد اللہ ابن عمر نبی الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عورت پر صرف اس کے چہرے میں حج کا احرام ہے۔“ اس حدیث کو عبید اللہ بن عمر سے صرف ایوب ابوالجمل نے روایت کیا۔ اس میں عبد اللہ بن رجاء کا تفرد ہے۔","",{"k":"٦١٢٢ مجمع الزوائد (٣/٢٢٢)، مجمع البحرين (١٦٩٩)، اسناده ضعیف۔"}],[6123,"سیدنا سعد رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” میں نے مومن کے لیے تعجب کیا، اگر اسے بھلائی نصیب ہوتی ہے تو وہ اللہ کی حمد بیان کرتا ہے اور شکر ادا کرتا ہے اور اگر اسے کوئی مصیبت پہنچتی ہے تو وہ اپنے رب کی حمد بیان کرتا ہے اور صبر کرتا ہے اور مومن کو ہر صورت میں اجر ملتا ہے، حتی کہ اس لقمے میں بھی جو وہ اپنے منہ میں ڈالتا ہے۔“ اس حدیث کو جریر بن ایوب سے صرف ابن رجاء نے روایت کیا۔ کر مجمع الزوائد: ١٠ / ٩٥، صحيح الجامع الصغير، رقم: . مذکورہ حدیث سے معلوم ہوا کہ خوشی پر اللہ ذوالجلال کا شکر کرنا اور مصیبت پر صبر کرنا، یہ مومنوں کی صفات ہیں۔ حدیث کے آخر میں ہے کہ مومن کو اجر ملتا ہے حتی کہ اس لقمہ کا بھی جو وہ اپنے منہ میں ڈالتا ہے۔ شعب الایمان بیہقی میں ہے کہ ((حَتَّى فِی النُّقْمَةِ يَرْفَعُهَا إِلَى فَي امْرَأَتِهِ)) یہاں تک کہ اس لقمے میں بھی جو وہ اپنی بیوی کے منہ میں ڈالتا ہے تو معلوم ہوا کہ مومن جو کچھ بھی کام کرتا، خواہ اپنی ذات کے لیے، اس میں اس کو اجر ملتا ہے، بیوی بچوں کے کپڑے اور خوراک کا بھی اس کو اجر ملتا ہے کیونکہ اس کی نیت یہ ہوتی ہے کہ اللہ ذوالجلال نے ان کا خرچ میرے ذمے فرض کیا ہے، میں اس کی ادائیگی کر رہا ہوں تو اس نیت کی بنا پر اس کو اجر ملتا ہے اور جو کچھ اپنی ذات پر بھی مومن خرچ کرتا ہے، اس کا بھی اس کو اجر ملتا ہے۔",""],[6124,"سیدنا براء بن عازب رضی اللہ عنہما بیان کرتے ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اس راستے سے یمن والوں میں سے سب سے بہتر شخص تمہارے پاس آئے گا، اس کے چہرے پر بادشاہت کا نشان ہوگا۔“ راوی نے بیان کیا: لوگوں میں سے ہر آدمی تمنا کرتا تھا کہ وہ اس میں سے ہو کہ اچانک ایک سوار ان کے پاس نمودار ہوا اور رسول اللہ صلی اللہ علیہ وسلم تک پہنچ گیا، وہ اپنی سواری سے اترا، نبی صلی اللہ علیہ وسلم کے پاس آیا، آپ ملنے کی کمی کا ہاتھ تھاما، آپ صلی اللہ علیہ وسلم کو سلام کیا، آپ صلی اللہ علیہ وسلم کی بیعت کی اور ایک طرف ہو گیا، آپ لم نے فرمایا: ” تم کون ہو؟“ اس نے عرض کیا: میں جریر بن عبد اللہ انجلی ہوں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اسے اپنے پہلو میں بٹھایا اور اپنا دست مبارک اس کے سر، اس کے چہرے، اس کے سینے اور اس کے پیٹ پر پھیرا، حتیٰ کہ جریر اس حیا سے کہ آپ صلی اللہ علیہ وسلم کہیں اپنا ہاتھ ان کے ازار کے نیچے نہ داخل کر دیں جھک گئے۔ آپ صلی اللہ علیہ وسلم ان کے لیے اور ان کی اولاد کے لیے برکت کی دعا کرتے رہے اور پھر آپ صلی اللہ علیہ وسلم نے ان کے سر اور پشت پر ہاتھ پھیرا اور ان کے لیے دعا کی۔“ اس حدیث کو عامر بن سعد البجلی سے صرف جریر بن ایوب نے روایت کیا۔","",{"k":"لر مجمع الزوائد (٩/٣٧٥)، اسناده ضعيف۔"}],[6125,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے تو فرمایا: ”میں اپنی امت کے شریر لوگوں کے لیے بہترین شخص ہوں۔“ ہم نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم اس کے بہتر لوگوں کے لیے کس طرح ہیں؟ آپ ملے لیے ہم نے فرمایا: ”رہے میری امت کے بہتر لوگ تو وہ اپنے اعمال کی وجہ سے جنت میں جائیں گے، رہے ان کے برے لوگ تو وہ میری شفاعت کے ذریعے جنت میں جائیں گے۔“ یہ حدیث سیدنا ابو امامہ بیانیہ سے صرف اس اسناد سے مروی ہے۔ اس میں بیٹی بن بسطام کا تفرد ہے۔ ٦١٢٦","",{"k":"مجمع الزوائد (٣٨٠/١٠)، اس میں محمد بن زکریا غلابی متہم بالوضع ۔۔"}],[6126,"سیدنا عکراش بن ذویب فضل اللہ نے بیان کیا، مجھے بنو مرہ بن عبید نے اپنے اموال کے صدقات کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا، میں آپ صلی اللہ علیہ وسلم کے پاس مدینہ پہنچا تو میں نے آپ صلی اللہ علیہ وسلم کو مہاجرین اور انصار کے درمیان پایا۔ پس میں اونٹ کے ساتھ آپ صلی اللہ علیہ وسلم کے پاس پہنچا، گویا کہ وہ امطا (سرخ رنگ کی بوٹی) کی شاخوں کی طرح ہیں۔ آپ لئے علیم نے فرمایا: ”آدمی کون ہے؟“ میں نے عرض کیا: عکراش بن ذؤيب، آپ صلی اللہ علیہ وسلم نے فرمایا: ” نسب کو مزید بیان کر“ میں نے کہا: ابن حرقوس بن جعدہ بن عمرو بن النزال بن مرہ بن عبید، یہ بنومرہ بن عبید کے صدقات ہیں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے تبسم فرمایا، پھر فرمایا: ”یہ میری قوم کے اونٹ ہیں، یہ میری قوم کے صدقات ہیں۔ “ پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کے متعلق حکم فرمایا کہ نشان والے آلے کے ساتھ صدقہ کے اونٹ والا نشان لگایا جائے۔ پس وہ ان کے ساتھ ملا دیے گئے۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے ہاتھ سے پکڑا اور مجھے سیدہ ام سلمہ بنی انا کے گھر لے گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” کچھ کھانا ہے؟ ہمارے پاس ثرید اور گوشت کے ٹکڑے لائے گئے۔ پس ہم اس میں سے کھانے لگے، میں اس کے کناروں میں بے ترتیب اپنا ہاتھ مارنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے بائیں ہاتھ سے میرا دایاں ہاتھ پکڑ لیا اور فرمایا: ” عکراش! ایک جگہ سے کھا، کیونکہ وہ ایک ہی قسم کا کھانا ہے۔ پھر ہمارے پاس ایک طشت لایا گیا، اس میں مختلف رنگوں کی تازہ کھجوریں تھیں۔ پس میں اپنے سامنے سے کھانے لگا، جبکہ رسول اللہ ملے ان کا ہاتھ طبق، طشت میں گھومنے لگا۔ پھر آپ مالٹے علیم نے فرمایا: \"کراش! جہاں سے چاہو کھاؤ، کیونکہ یہ ایک قسم کا کھانا نہیں۔“ پھر ہمارے پاس پانی لایا گیا تو رسول اللہ ملنے سلیم نے ہاتھ دھوئے اور اپنے گیلے ہاتھوں سے چہرے، بازؤں اور سر کا مسح کیا، پھر فرمایا: ” عکراش! آگ پر پکی ہوئی چیز کھا کر اس طرح وضو کرنا چاہیے۔“ یہ حدیث عکراش بن ذویب سے صرف اس اسناد سے مروی ہے، اس میں العلاء بن الفضل بن ابی سویہ کا تفرد ہے۔","",{"k":"سنن ترمذی (١٨٤٨)، قال الشيخ الالباني : ضعيف۔"}],[6127,"سیدنا عبد الملک بن ابی سو یہ المنقری نے بیان کیا، میں سیدنا قیس بن عاصم نبیل اللہ کے پاس موجود تھا، جبکہ وہ وصیت کر رہے تھے، انہوں نے اپنے بیٹوں کو اکٹھا کیا، وہ بتیس بیٹے تھے، انہوں نے کہا: بیٹھو! جب میں فوت ہو جاؤں تو اپنے سب سے بڑے بھائی کو سردار بنا لینا اور اپنے آباء کی جانشینی کرنا، اپنے سب سے چھوٹے کو سردار نہ بنانا، یہ تمہیں تمہارے برابر کے لوگوں کے ہاں بے وقعت بنا دے گا، نوحہ کرنے والی میرے اوپر کھڑی نہ کرنا، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو نوحہ خوانی سے منع کرتے ہوئے دیکھا ہے، اصلاح مال کا خیال رکھنا، کیونکہ وہ سخی کا شرف ہے اور اس کے ذریعے بخیل شخص سے بے نیاز ہوا جاتا ہے اور تم اونٹوں کی گردنیں (اونٹ) صرف مستحق افراد کو دو اور انہیں حق داروں سے نہ روکو، اپنے آپ کو ہر بری رگ سے بچاؤ، اگر کسی دن تمہیں خوشی حاصل ہوتی ہے تو تمہیں پریشان کرنے والی چیزیں زیادہ ہیں، اپنے دشمنوں کے بیٹوں سے بچنا، کیونکہ وہ اپنے آباء کے طریقے پر تمہارے دشمن ہیں اور جب میں فوت ہو جاؤں تو مجھے کسی ایسی جگہ دفن کرنا جس کے متعلق بکر بن وائل قبیلے والوں کو پتہ نہ چل سکے، کیونکہ دور جاہلیت میں میرے اور ان کے درمیان گڑ بڑ رہتی تھی، مجھے اندیشہ ہے کہ وہ مجھے قبر سے نکال نہ لیں تو تم کہیں ان پر ان کی دنیا خراب نہ کر دو اور وہ تم پر تمہاری آخرت نہ خراب کر دیں، پھر انہوں نے اپنا ترکش منگایا اور اپنے بڑے بیٹے سیدنا علی سے کہا: میرے ترکش سے ایک تیر نکالو، اس نے اسے نکالا تو انہوں نے کہا: اسے توڑو، پس اس نے اسے توڑا، پھر انہوں نے کہا: دو تیر نکالو، اس نے دو تیر نکالے، انہوں نے کہا: ان دونوں کو توڑو، اس نے وہ دونوں توڑ دیے،انہوں نے کہا: تین تیر نکالو، اس نے وہ نکالے تو انہوں نے کہا: تانت کے ساتھ انہیں باندھ دو، پس اس نے باندھ دیے، پھر انہوں نے کہا: انہیں توڑ دو لیکن وہ انہیں توڑ نہ سکا، انہوں نے کہا: بیٹو! اتحاد کی صورت میں تم بھی اسی طرح ہو اور اگر الگ الگ رہے تو پھر تم بھی ان الگ الگ تیروں کی طرح ہو گے، پھر انہوں نے اشعار کہتے ہوئے فرمایا: اصل شان وشوکت وہ ہے جس کی بنیاد سچا والد رکھے اور اس کے بعد اس کی اولا دا سے زندہ کرے۔ کافی ہے شان و شجاعت اور بردباری، جب پاک دامنی اور سخاوت بھی اسے مزین کرے، میرے بیٹو! جب تمہیں افراد مصائب میں متحد ہوں تو وہ ان تمیں آدمیوں کی طرح ہیں۔ جنہیں زادراہ کے لیے مضبوط گرہ لگائی گئی ہو تو وہ نہیں ٹوٹتے اور اگر وہ الگ الگ ہوں تو وہ ٹوٹ جائیں گے۔ بڑی عمر اور اخلاق و مروت والے مقدم ہیں، اگر ان جیسے سردار موجود نہ ہوتے اور ان پر چھوٹوں کی حفاظت ضروری ہے حتی کہ وہ محنت و مشقت کرنے والا چھوٹا بالغ ہو جائے۔“ اس حدیث کو اس اتمام اور شعر کے ساتھ صرف اس اسناد سے روایت کیا جاتا ہے، اس میں العلاء بن الفضل بن ابی سو یہ المنقر ی کا تفرد ہے۔","",{"k":"مجمع الزوائد : د (٤/٢٢٢)، حاكم (٣/٧٠٨)، اسناده ضعيف۔"}],[6128,"سیدنا عبد اللہ بنی امیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” اونٹ اور گائے کی قربانی سات سات افراد کی طرف سے ہوتی ہے۔“ اس حدیث کو مغیرہ سے صرف حفص بن جمیع نے روایت کیا۔ اس میں عمر بن بیٹی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٢٩/٣)۔"}],[6129,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص نیند یا بھول جانے کی وجہ سے نماز نہ پڑھ سکے تو وہ یاد آ جانے پر نماز پڑھے، پھر آپ صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی: ” میری یاد کے لیے نماز قائم کر۔“ اس حدیث کو زہری سے صرف محمد بن اسحاق نے اور محمد بن اسحاق سے صرف زیاد بن عبد اللہ نے روایت کیا۔ اس میں عمر بن بیٹی الا بلی کا تفرد ہے۔","",{"k":"صحیح بخاری، فليصل اذا ذكر . الخ (٥٩٧)، صحیح مسلم (٦٨٤)۔","f":"پیچھے بھی احادیث گزر چکی ہیں کہ نبی معظم صلی اللہ علیہ وسلم سفر میں اپنے صحابہ کرام بھی اسلام کے ساتھ تھے وہ سو گئے، فجر کے لیے نہ اٹھ سکے حتی کہ سورج طلوع ہو گیا تو اس وقت نماز ادا کی، معلوم ہوا کہ بھول جانے یا سو جانے یا کسی اور وجہ سے نماز معاف نہیں اور نہ ہی اس کا کوئی مالی یا بدنی کفارہ ہے بلکہ نماز ہی پڑھنا ہوگی۔"}],[6130,"سیدنا جابر ریلا لینہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے ایک آدمی کو شہرمہ کی طرف سے حج کا تلبیہ پکارتے ہوئے سنا: تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تم نے اپنی طرف سے حج کیا ہے؟“ اس نے عرض کیا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”پہلے اپنی طرف سے حج کر اور پھر شہرمہ کی طرف سے حج کر۔“ اس حدیث کو ابوالز بیر سے صرف تمامہ بن عبیدہ نے روایت کیا۔","",{"k":"مجمع الزوائد (٢٨٦/٣)، مجمع البحرين (١٦٨٢)۔"}],[6131,"سیدنا یوسف بن عبد اللہ بن سلام رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:: تم میں سے کسی کا اپنے مسلمان بھائی کی ناحق بے عزتی کرنا سب سے بڑا سود ہے۔“ اس حدیث کو بحر بن مرار سے صرف سعید الحریری نے اور الجریری سے صرف جعفر بن سلیمان نے روایت کیا۔ اس میں عمر بن بیٹی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨/٩٢)، مجمع البحرين (٤٩٥٨)، اسناده ضعيف۔"}],[6132,"سیدنا حذیفہ بن اسید ابن سریحہ الغفاری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب بیت اللہ کو دیکھتے تو یہ دعا پڑھتے تھے: اے اللہ! اپنے اس گھر کو تشریف و تعظیم اور تکریم و بر او تنظیم میں بڑھا دے، اس کا حج یا عمرہ کرنے والے کی نسبت اس کی عزت و تعظیم کرنے والے کو تعظیم و تشریف و تکریم اور عزت میں بڑھا دے۔“ اس حدیث کو زید بن اسلم سے صرف عاصم بن سلیمان نے روایت کیا۔ اس میں عمر بن بیٹی کا تفرد ہے۔ ابوسر یحہ سے صرف اس اسناد سے مروی ہے۔ ٦١٣٣","",{"k":"مجمع الزوائد (٣/٢٣٨)، مجمع البحرين، رقم: (١٧٢٠)، سلسله ضعیفه (٤٢١٥)، ضعيف الجامع الصغير (٤٤٥٦)۔"}],[6133,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” جب قیامت کا دن ہوگا تو اعمال کو مہر بند صحیفوں میں لایا جائے گا تو رب تبارک و تعالیٰ فرمائے گا: اسے قبول کرو، اسے چھوڑ دو تو فرشتے کہیں گے: تیری عزت کی قسم! ہم نے تو صرف وہی کچھ لکھا جو اس نے عمل کیا: وہ فرمائے گا: تم نے ٹھیک کہا، اس کے اعمال میری رضا کے لیے نہ تھے، میں تو آج صرف وہی عمل قبول کروں گا، جو میری رضا کے . تھے۔ “ اس حدیث کو ابو عمران الجونی سے صرف حارث بن غسان نے روایت کیا۔ ٦١٣٤","",{"k":"مجمع الزوائد (١٠/٣٥٠)، سلسله ضعیفه (٢٦٧٢)، مجمع البحرين (٤٧٩٠)۔"}],[6134,"سیدنا عبداللہ ابن عباس بنایا جا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”ہر بچہ فطرت، دین پر پیدا ہوتا ہے۔“ اس حدیث کو ابن جریج سے صرف حارث بن غسان نے روایت کیا۔ ٦١٣٥","",{"k":"مجمع الزوائد (٢١٨/٧)۔"}],[6135,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” ( قیامت کے دن) بندے کے ترازو میں سب سے پہلے اس کا اپنے اہل پر خرچ کرنا رکھا جائے گا۔“ اس حدیث کو محمد بن عبد المنکد ر سے صرف عبدالحمید بن الحسن نے روایت کیا۔","",{"k":"مجمع الزوائد (٤/٣٢٥)، مجمع البحرين (٢٤٠٥)، ضعيف الجامع الصغير (٢١٤١)، سلسله ضعیفه (٥١٧٩)۔"}],[6136,"سیدنا عبداللہ ابن عباس نیا اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے افراد جب بحری سفر کریں اور وہ یہ دعا پڑھیں تو یہ غرق ہونے سے ان کے لیے امان و تحفظ ہے، اللہ بادشاہ کے نام کے ساتھ اور انہوں نے اللہ کی ویسی قدر نہ کی جس طرح اس کی قدر کرنے کا حق ہے، قیامت کے دن ساری زمینیں اس کی مٹھی میں ہوں گے اور آسمان اس کے دائیں ہاتھ پر لیٹے ہوں گے اور وہ جو شریک ٹھہرا رہے ہیں وہ اس سے پاک و برتر ہے، اس کا چلنا اور ٹھہرنا اللہ کے نام کے ساتھ ہے، بے شک میرا رب بخشنے والا مہربان ہے۔ اس حدیث کو ضحاک بن مزاحم سے صرف نہشل بن سعید نے روایت کیا۔","",{"k":"مجمع الزوائد (١٠/١٣٢)، مجمع البحرين (٤٥٨٦)، ضعيف الجامع الصغير (١٢٤٨)، سلسله ضعيفه (٢٩٣٣)، قال الشيخ الالباني: موضوع۔"}],[6137,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی ملنے کی ایم نے فرمایا: ”اللہ کے موجبات میں سے تین ہیں، جب وہ اللہ کے حقوق میں سے کوئی حق دیکھے تو وہ اسے ان ایام تک مؤخر نہ کرے جن کو وہ پا نہ سکے، یہ کہ وہ ظاہری طور پر بھی نیک عمل اسی مقدار و اعتدال کے ساتھ کرے جس طرح کہ وہ مخفی طور پر کرتا ہے اور اس کے ساتھ ساتھ وہ جو عمل کرتا ہے قابل امید عمل کی صلاح بھی جمع کرتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”پس اللہ کا ولی اس طرح ہوتا ہے۔ آپ نے اپنے ہاتھ سے تمیں کی گرہ لگائی۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ اس میں حکیم بن حزام کا تفرد ہے۔ ٦١٣٨","",{"k":"مجمع الزوائد (٢٦٩/١٠)، اسناده ضعيف۔"}],[6138,"سیدنا عمران بن حصین رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے جب بھی ہمیں خطبہ ارشاد فرمایا: تو آپ صلی اللہ علیہ وسلم نے ہمیں صدقہ کرنے کا حکم فرمایا اور مثلہ کرنے سے منع فرمایا۔ اس حدیث کو عبد الکریم سے صرف یحی بن کثیر نے روایت کیا۔ ..مذکورہ حدیث سے معلوم ہوا کہ قتل کرنے کے بعد مقتول کے اعضا کاٹنے یا اس کی شکل بگاڑ نا ناجائز ہے، اسی طرح قتل سے پہلے بھی یہ عمل ناجائز ہے۔ مگر قصاص کی کوئی صورت ہو جیسے کہ پیچھے احادیث گزر چکی ہیں کہ قبیلہ عسکل وعرینہ کے لوگوں کا بطور قصاص مثلہ کیا تھا۔","",{"k":"صحیح بخاری (٤١٩٢)، سنن ابو داود (٢٦٦٧)۔"}],[6139,"سیدنا عبداللہ ابن عم رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”پچھنے لگانے والے اور جسے پچھنے لگائے جائیں دونوں کا روزہ ٹوٹ جاتا ہے۔ اس حدیث کو ایوب سے صرف الحسن بن ابی جعفر نے روایت کیا اور الحسن سے صرف موسی بن اسماعیل نے۔ اس میں محمد بن اللیث کا تفرد ہے۔ ٦١٤٠","",{"k":"مجمع الزوائد (١٥٩/٤)۔"}],[6140,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بچہ اپنے شفعہ پر ہے حتی کہ وہ پالے۔ پس جب وہ پالے تو پھر اگر وہ چاہے تو لے لے اور اگر چاہے تو ترک کر دے۔“ اس حدیث کو صدقہ بن ابی عمران سے صرف عبد اللہ بن بزیع نے روایت کیا۔ اس میں عبد اللہ بن رشید کا تفرد ہے۔ ١٤١","",{"k":"مجمع الزوائد (١٥٩/٤)، ضعيف الجامع الصغير (٣٥٤٠)، اسناده ضعيف۔"}],[6141,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر دینے سے منع فرمایا، مگر سونے یا چاندی کے بدلے۔ یہ حدیث عمر بن ذر سے صرف اس اسناد سے مروی ہے۔ اس میں عبد اللہ بن رشید کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ زمین کو سونے، چاندی کے عوض ٹھیکے پر دینا جائز ہے۔ لیکن یہ بھی معلوم ہوا کہ اس کے علاوہ جائز نہیں ہے۔ ممانعت اس بات سے ہے کہ زمین کو ٹھیکے پر دیتے وقت کسی خاص حصے کی پیداوار کو اپنے لیے مخصوص کر لینا جیسا کہ عہد رسالت میں لوگ کیا کرتے تھے۔ اس کا نقصان یہ ہوتا تھا کہ کبھی ایک حصے میں پیداوار زیادہ ہو جاتی اور دوسرے حصے میں نہ ہوتی تو مالک کو","",{"k":"صحیح مسلم کتاب البیوع، رقم: ١٥٣٦/٨٧ بلفظ نهى عن كراء الارض، دار قطنی (٣٦/٣)۔","f":"ہو جاتا اور ٹھیکے پر لینے والے کا نقصان، اسی طرح بعض واقعات اس کے برعکس مالک کو نقصان ہو جاتا اور لینے والے کو فائدہ، جس سے نزاع و انتشار پیدا ہو جاتا تو آپ صلی اللہ علیہ وسلم نے اس سے منع فرما دیا۔ اس لیے یہ صورت منع ہے وگر نہ اگر کوئی چیز مقرر ہو مثلاً معین پیدا وار سونا چاندی یا مروجہ نقدی وغیرہ تو پھر کوئی حرج نہیں۔ممانعت صرف نامعلوم پیدوار اور قطعہ ارضی کی تخصیص میں ہے۔ ٦١٤٢"}],[6142,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عنقریب آخری دور میں نو عمر کم عقل لوگ ہوں گے، وہ سب سے بہترین شخص کا قول بیان کریں گے، وہ دین سے اس طرح نکل جائیں گے جس طرح تیر شکار سے پار ہو جاتا ہے، وہ سب مخلوقات سے بدتر ہیں، اس شخص کے لیے خوشخبری ہے۔ جس نے انہیں قتل کیا، یا انہوں نے اسے قتل کیا۔ اس حدیث کو مسلم سے صرف مجاعہ بن الزبیر نے روایت کیا۔ اس میں عبد اللہ بن رشید کا تفرد ہے۔","",{"k":"صحیح بخاری (٥٠٥٧)، سنن ابو داود (٤٧٦٧)۔","f":"مذکورہ حدیث میں جن کا تذکرہ ہے۔ ان سے مقصود خوارج، معتزلہ اور ان جیسے نظریات رکھنے والے لوگ ہیں، یہ خارجی، سیدنا علی نا اہلیہ کے زمانہ میں نکلے اور قرآن کی آیات پڑھتے تھے لیکن معنی غلط کرتے تھے، انہوں نے سیدنا علی ضیا الیہ سے کہا: قرآن پر چلو، اللہ تعالیٰ فرماتا ہے: وَإِنِ الْحُكْمُ إِلَّا لِلَّهِ﴾ (الانعام: ٥٧) تم نے آدمیوں کو کیسے حکم مقرر کیا ہے اور اس بنا پر سیدنا معاویہ نا اہلی اور سیدنا علی بیانیہ پر کفر کا فتویٰ لگاتے، سیدنا علی ضیا اللہ نے فرمایا: ((کلمہ حق ارید بھا الباطل بات تو برحق ہے مگر جو مطلب انہوں نے سمجھا ہے وہ غلط ہے۔ جتنے گمراہ فرقے ہیں وہ سب اپنی دانست میں قرآن سے دلیل لاتے ہیں، مگر ان کی گمراہی اس سے کھل جاتی ہے کہ قرآن کی تفسیر اس طرح نہیں کرتے جو نبی معظم صلی اللہ علیہ وسلم اور صحابہ کرام بیٹی ایم سے ماثور ہے۔ جن پر قرآن اترا تھا اور جو اہل زبان تھے، یہ کل کے لونڈے قرآن سمجھ گئے اور صحابہ علی السلام، تابعین مہم اور خود نبی معظم ملے جن پر قرآن اترا تھا، انہوں نے نہیں سمجھا، یہ بھی کوئی بات ہے، آج کل کے اہل بدعت کا بھی یہی حال ہے، جو آیات قرآنی سے اپنے عقائد باطلہ کے اثبات کے لیے دلائل پیش کر کے آیات قرآنی کے معنی و مطالب کو مسخ کر کے رکھ دیتے ہیں۔"}],[6143,"سیدنا زبیر بن العوام رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”ایمان نے کسی کو غفلت میں ( یا کسی معاہد کو قتل کرنے سے منع کیا ہے۔ اس حدیث میں یونس کے حوالے سے حسن اور زبیر کے درمیان اشعث بن ثرملہ کو صرف عبد الا علی نے داخل کیا۔ اس میں نصر بن علی کا تفرد ہے۔","",{"k":"مجمع الزوائد: د (١/٩٦)، مسند احمد (١/١٦٧)، مجمع البحرين (١١٥)، اسناده حسن۔","f":"قانون مذکورہ حدیث سے معلوم ہوا کہ مسلمان کسی کو دھو کے اور غفلت سے قتل نہ کرے، اسی طرح ایسا شخص بھی جس سے کوئی عہد و پیمان ہوا، اس کو بھی قتل کرنا ناجائز ہے، مگر جن دشمنوں کے ساتھ اعلان جنگ ہو اور دونوں فریق جنگ کی کیفیت میں ہوں اس میں یہ عمل جائز ہے۔"}],[6144,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مشرق کی جانب سے کچھ لوگ آئیں گے، وہ قرآن پڑھیں گے لیکن وہ ان کے حلق سے نیچے نہیں اترے گا، وہ اسے خراب کھجور بکھیر نے کی طرح جلدی جلدی پڑھیں گے، وہ دین سے نکل جائیں گے، پھر وہ اس میں واپس نہیں آئیں گے حتی کہ تیرا اپنے سوفار میں واپس آ جائے، ان (خارجیوں) میں سرمنڈانا بہت ہوگا۔“ اس حدیث کو ابوحرہ سے صرف مسلم بن سلیمان نے روایت کیا۔","",{"k":"صحیح بخاری (٧٥٦٢)، صحیح مسلم (١٠٦٤/١٤٨)، صحيح الجامع الصغير (٨٠٦٣)۔"}],[6145,"سیدہ عائشہ بنی النہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے بہتر وہ ہے جو تم میں سے اپنے اہل خانہ کے لیے بہتر ہے۔“ اس حدیث کو روح سے صرف یزید نے روایت کیا۔ اس میں از ہر بن جمیل کا تفرد ہے۔","",{"k":"کی سنن ترمذی (٣٨٩٥)، قال، الشيخ الالباني: صحيح۔"}],[6146,"سیدہ عائشہ بیلی عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے بیٹے ابراہیم عل اللہ کی قبر پر پانی چھڑ کا “ اس حدیث کو ہشام بن عروہ سے صرف الدر اور دی نے روایت کیا۔ اس میں احمد بن عبدہ کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ قبر پر پانی چھڑکنا جائز ہے تاکہ مٹی بیٹھ جائے۔ ایک دوسری حدیث میں ہے کہ سیدنا جابر نبی اللہ فرماتے ہیں: نبی مکرم سے علی کی قبر پر پانی چھڑکا گیا اور پانی چھڑ کنے والے سیدنا بلال بن رباح رضی اللہ عنہ جنہوں نے ایک مشکیزے کے ساتھ سر کی طرف سے پانی چھڑکنا شروع کیا اور پاؤں تک چھڑکا۔ (مشکاة المصابيح للالبانی، رقم: ١٨١٠)","",{"k":"مجمع الزوائد (٣/٤٥)، سلسله صحيحه (٣٠٤٥)۔"}],[6147,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، جب سیدنا علی بن ابی طالب فضل الله یمن آئے تو نبی سے تم نے انہیں فرمایا: تم نے کس نیت سے احرام باندھا تھا؟“ انہوں نے کہا: جس نیت سے نبی صلی اللہ علیہ وسلم نے احرام باندھا ہے۔ نبی تعلیم نے فرمایا: \"اگر میرے ساتھ قربانی کا جانور نہ ہوتا تو میں احرام کھول دیتا۔ “ اس حدیث کو شعبہ سے صرف سمید ع بن واہب نے روایت کیا۔ اس میں ابو برید کا تفرد ہے۔ ان في معظم اے علی تم نے حج قران کا احرام باندھا تھا تو سیدنا علی ضیا اللہ کو علم نہ تھا تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے احرام والی نیت کی۔ حج قران کا مطلب یہ ہے کہ احرام باندھتے ہوئے انسان عمرے اور حج","",{"k":"صحیح بخاری، صحیح مسلم (١٢٥٠)۔","f":"دونوں کی نیت کرے، مکہ پہنچ کر پہلے عمرہ کر لے مگر اس سے حلال نہ ہو بلکہ اسی احرام میں رہتے ہوئے حج کے اعمال مکمل کرے اور آخر میں حلال ہو تو اسے حج قران کہتے ہیں۔"}],[6148,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری میرے رب پر کرامت و اعزاز ہے کہ میں پیدا ہوا تو میرے پہلے ہی سے ختنے ہو چکے تھے، میرے ستر کو کسی نے نہیں دیکھا۔‘ اس حدیث کو یونس سے صرف ہشیم نے روایت کیا۔ اس میں سفیان بن محمد الفزاری کا تفرد ہے۔ ٦١٤٩","",{"k":"ضعيف . مجمع الزوائد (٢٢٤/٨)، ضعيف الجامع الصغير (٥٣١٠)، اسناده۔"}],[6149,"سیدنا محمد بن سیرین نے بیان کیا، سیدنا انس رضی اللہ عنہ کا معمول تھا کہ جب وہ رسول الله علیم سے حدیث بیان کرتے اور فارغ ہوتے تو فرماتے تھے، یا جس طرح رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔“ اس حدیث کو عوف سے صرف ابن ابی عدی نے روایت کیا۔ نان مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرنے میں احتیاط کرنا","",{"k":"سنن ابن ماجه المقدمة (٢٤)، سنن دارمی (٢٧٧)، مسند احمد (٣/٢٠٥)، قال الشيخ الالباني: صحيح۔","f":"چاہیے اور احتیاط میں سے یہ بھی ہے کہ جب حدیث کے الفاظ پوری طرح یاد نہ ہوں تو پھر حدیث بیان کر کے کہے ((او كما قال رسول اللہ صلی اللہ علیہ وسلم یہ الفاظ یا جو الفاظ آپ صلی اللہ علیہ وسلم نے فرمائے۔“ ٦١٥٠"}],[6150,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ للہ علیم نے فرمایا: ”میں جنت میں داخل ہوا تو میں نے اپنے آگے کسی کے چلنے کی آواز سنی تو میں نے کہا: جبریل! یہ آواز کیسی ہے؟ انہوں نے کہا: بلال آپ صلی اللہ علیہ وسلم کے آگے آگے چل رہے ہیں۔“ اس حدیث کو ابو العالیہ سے صرف ابو جناب کلبی نے روایت کیا۔ مذکورہ حدیث سے سیدنا بلال بنی اللہ کی فضیلت و عظمت واضح ہوتی ہے، سیدنا بلال بن ابی","",{"k":"کر مجمع الزوائد (٣٠٢/٩)، صحيح الجامع الصغير (٣٣٦٩)۔","f":"ربات نبی صلی اللہ علیہ وسلم اور آپ کو بلال بن حمامہ بھی کہا جاتا ہے، حمامہ آپ کی ماں تھیں، آپ نے بہت پہلے اسلام قبول کیا اور آپ کے اسلام لانے پر اہل مکہ نے آپ کو بہت ہی ستایا تھا، امیہ بن خلف جس کے آپ غلام تھے، وہ اپنے ہاتھ سے ان کو انتہائی اذیت دیتا تھا، سیدنا بلال فضیل ان کو سیدنا ابو بکر رضی اللہ عنہ نے خرید کر آزاد کر دیا۔ اللہ ذوالجلال کی قدرت کہ جنگ بدر میں امیہ بن خلف سیدنا بلال رضی اللہ عنہ کی تلوار سے واصل جہنم ہوا، آپ رضی اللہ عنہ ہجری میں دمشق میں فوت ہوئے، آپ نبی الیہ کو باب الضغر میں دفن کیا گیا اور آپ نبی اللہ کی عمر ساٹھ یا پینسٹھ سال تھی۔ مذکورہ بالا روایت میں جو ہے کہ آپ نبی اللہ زمین پر چلتے تو قدموں کی آواز جنت میں سنائی دی، رسول اللہ صلی اللہ علیہ وسلم واپس تشریف لائے تو فرمایا کہ (( قد افلح بلال بلال کامیاب ہو گیا۔ میں نے ان کو ایسے ایسے دیکھا ہے۔ (مسند احمد: ٣٥٤/٥) یہ مرتبہ و مقام کیسے ملا؟ سیدنا بلال رضی اللہ عنہ نے عرض کیا: یا رسول اللہ! میں جب اذان دیتا ہوں تو دو رکعت پڑھتا ہوں اور ہمیشہ وضو میں رہتا ہوں، جب بھی میرا وضو ٹوٹتا ہے تو میں وضو کرتا ہوں، پھر دو رکعت نماز اتنی با قاعدگی سے پڑھتا ہوں کہ گویا کہ مجھ پر میرے اللہ کا حق ہے تو نبی مکرم ملنے ندیم نے فرمایا: انہی دو عملوں کی وجہ سے اللہ ذوالجلال نے تجھے یہ مقام دیا کہ میں جب جنت میں داخل ہوا، تیرے چلنے کی آواز اپنے آگے یا ایک طرف سنی۔ (ترمذی، کتاب المناقب، رقم: ٣٩٥٤، اسنادہ صحیح)"}],[6151,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ سلم نے فرمایا: ”سوتے وقت احمد (سرمہ لگایا کرو، کیونکہ وہ نظر تیز کرتا ہے اور بال ( پلکیں) اگا تا ہے۔‘‘ اس حدیث کو سلیمان بن خالد الواسطی سے صرف محمد بن ماہان نے روایت کیا۔ اس میں ان سے ان کے بیٹے کا تفرد ہے۔","",{"k":"سنن ابن ماجه (٣٤٩٦)، قال الشيخ الالباني: صحيح۔"}],[6152,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے کسی کی ستر پوشی کی گویا کہ اس نے زندہ درگور کی ہوئی لڑکی کو اس کی قبر سے زندہ کیا۔“ اس حدیث کو بلال بن سعد سے صرف الوفین نے روایت کیا اور الومنین سے صرف طلحہ بن زید نے۔ اس میں محمد بن ماہان کا تفرد ہے۔ ٦١٥٣","",{"k":"مجمع الزوائد (٢٤٧/٦)، ادب المفرد (٧٥٨)، ضعيف الجامع الصغير (٥٥٩٠)، اسناده ضعيف۔"}],[6153,"سیدنا عبادہ بن صامت رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: عنقریب فتنے ہوں گے، اس دور میں مومن ہاتھ کے ساتھ انہیں بدل سکے گا، نہ زبان کے ساتھ۔“ سیدنا علی بن ابی طالب رضی اللہ عنہ نے عرض کیا، اللہ کے رسول! کیا یہ ان کے ایمان میں کمی کرے گا؟ فرمایا دو نہیں، مگر جس طرح قطرہ مشکیزے سے کمی کرتا ہے۔ انہوں نے عرض کیا: یہ کس لیے ہے؟ آپ نے فرمایا: ”وہ اسے اپنے دلوں سے ناپسند کرتے ہوں گے۔ اس حدیث کو الوفین بن عطا سے صرف طلحہ بن زید نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔","",{"k":"مجمع الزوائد (٧/٢٧٥)، اسناده ضعيف۔"}],[6154,"سیدنا عبد اللہ بن عمرو بن العاص نبی اللہ نے بیان کیا، نبی تعلیم نے فرمایا: ” جو شخص اپنے گھر آئے اور اس پر ناحق چڑھائی کر دی جائے، وہ قتال کرے اور قتل کر دیا جائے تو وہ شہید ہے۔ جس سے صدقہ طلب کیا جائے وہ عطا کر دے اور اس پر ظلم کیا جائے، پس وہ قتال کرے اور قتل کر دیا جائے تو وہ شہید ہے۔ اس حدیث کو طلحہ بن مصرف سے صرف سلیمان بن خالد نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ کوئی شخص اپنے گھر کی حفاظت یا اپنے اوپر ظلم کو ختم کرتے ہوئے لڑتا ہوا مارا جاتا ہے تو وہ شہید ہے۔ اگر یہ اپنے گھر کی یا اپنی حفاظت کرتے ہوئے حملہ آور انسان کو قتل کر دیتا ہے یا زخمی کر دیتا ہے تو وہ انسان مجرم نہیں ہے۔ فتح الباری میں سیدنا ابو ہریرہ یا اللہ سے مروی حدیث ہے کہ آپ ملنے سے دریافت کیا گیا کہ اگر ایک شخص مجھ سے میرا مال چھینا چاہتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: تو مدافعت کر۔ اگر مدافعت کرتے ہوئے (حملہ آور شخص ) قتل ہو جاتا ہے تو وہ دوزخی ہے اور اگر تو مارا جائے تو تو شہید ہے۔ (فتح الباری: ٤٩/٦) مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ شہید کی مختلف اقسام ہیں۔","",{"k":"٦١٥٤ صحیح بخاری (٢٤٨٠)، مسلم (١٤١)، للفظ من قتل دون ماله فهو شهید۔"}],[6155,"سیدنا زبیر بن العوام رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ طہارت (وضو) کے بغیر نماز قبول کرتا ہے نہ خیانت کا صدقہ “ اس حدیث کو ابن سعید سے صرف ابو قتادہ الحرانی نے روایت کیا اور زبیر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ نماز کے لیے وضو کرنا واجب ہے۔ کیونکہ بغیر وضو کے نماز ہی نہیں ہوتی۔ ایک دوسری حدیث میں ہے کہ رسول اللہ علیم نے فرمایا: اللہ تعالیٰ کسی بے وضو انسان کی نماز قبول نہیں کرتا حتی کہ وہ وضو کرے۔ (صحیح بخاری، رقم: ١٣٥، ابو داؤد، رقم: ٦٠) لیکن اگر پانی مہیا نہ ہو یا مہیا ہو لیکن کسی مجبوری کی بنا پر استعمال نہ کیا جا سکتا ہو تو تیم کرنا فرض ہے۔ (٢) اسی طرح خیانت، چوری، سود، رشوت وغیرہ کے مال سے دیا جانے والا صدقہ قبول نہیں ہوتا۔ ٦١٥٦","",{"k":"مجمع الزوائد (١/٢٢٧)، مسلم، سنن ابو داود (٥٩)۔"}],[6156,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ جس کی بینائی لے جائے اور وہ صبر کرے اور ثواب کی امید رکھے تو اللہ پر حق واجب ہے کہ اس کی آنکھیں جہنم کی آگ نہ دیکھیں۔ “ اس حدیث کو مسعر سے صرف جعفر بن عون نے روایت کیا۔ اس میں وہب ابن حفص کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم آنکھوں کی بینائی ختم ہونے پر صبر کرنے والے کے لیے بہت بڑا اجر ہے۔","",{"k":"ضعيف . مجمع الزوائد (٢/٣٠٩)، ضعیف ترغیب و ترهیب (٢٠١١)، اسناده۔"}],[6157,"سیدنا عبداللہ ابن عباس بنایا جا نے بیان کیا، رسول اللہ من انم نے فرمایا: ”جو شخص جمعہ کے دن سورۃ آل عمران پڑھتا ہے، اللہ اور اس کے فرشتے اس پر رحمتیں نازل کرتے ہیں حتی کہ سورج غروب ہو جاتا ہے۔ اس حدیث کو یزید بن جابر سے صرف یزید بن سنان نے روایت کیا اور یزید بن سنان سے صرف طلحہ بن زید نے۔ اس میں محمد بن ماہان کا تفرد ہے۔ ٦١٥٨","",{"k":"مجمع الزوائد (١٦٨/٢)، مجمع البحرين (٩٥٣)، ضعیف ترغیب و ترهيب (٤٥١)، قال الشيخ الالباني: موضوع۔"}],[6158,"سیدنا یزید بن جاریہ الانصاری نے بیان کیا، ہم سیدنا معاویہ فی الیہ کی چار پائی کے گرد بیٹھے ہوئے تھے تو انہوں نے کہا: تم اس سے کیا بات کر رہے تھے؟ انہوں نے کہا: ہم انصار کے متعلق بات کر رہے تھے، انہوں نے کہا: کیا میں تمہیں ایک حدیث نہ سناؤں، جسے میں نے رسول اللہ للہ علیم سے سنا ہے؟ انہوں نے کہا: ضرور سنا ئیں، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو انصار سے محبت کرتا ہے اللہ اس سے محبت کرتا ہے اور جو انصار سے بغض رکھتا ہے اللہ اس سے بغض رکھتا ہے۔“ اس حدیث کو ابان المعلم سے صرف خلف بن خلیفہ نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔","",{"f":"مسند احمد: ٤ / ٩٦، قال شعیب الارناؤط: اسناده صحيح . اندن مذکورہ حدیث سے انصار صحابہ کرام کی فضیلت واضح ہوتی ہے۔ لفظ انصار ناصر کی جمع ہے، جس کے معنی مددگار کے ہیں۔ حافظ ابن حجر جماللہ فرماتے ہیں: انصار اسلامی نام ہے، رسول اللہ صلی اللہ علیہ وسلم نے اوس، خز رج اور ان کے حلیف قبائل کا یہ نام رکھا جیسا کہ حدیث ان نبی الیہ میں مذکور ہے۔ ( صحیح بخاری میں ہے کہ سیدنا انس ضیا اللہ سے پوچھا گیا، بتلائیے انصار اپنا نام آپ لوگوں نے خود رکھ لیا تھا یا آپ لوگوں کا یہ نام اللہ ذوالجلال نے رکھا؟ انہوں نے فرمایا نہیں بلکہ ہمارا یہ نام اللہ ذوالجلال نے رکھا ہے۔ ( صحیح بخاری، کتاب المناقب انصار، رقم: ٣٧٧٢) اوس قبیلہ اپنے دادا اوس بن حارثہ کی طرف منسوب ہے اور خزرج، خزرج بن حارثہ کی طرف جو دونوں بھائی، ایک عورت قیلہ نامی کے بیٹے ہیں۔ ان کے باپ کا نام حارثہ بن عمرو بن عامر ہے، جس پر قبیلہ ازد کی جملہ شاخوں کے نسب نامے جا کر مل جاتے ہیں۔ مذکورہ بالا حدیث سے معلوم ہوا کہ انصار سے محبت کرنا ایمان کا حصہ ہے جو نہیں کرتے ان کو اپنے ایمان کی فکر کرنا چاہیے وہ مومن نہیں بلکہ منافق ہیں۔"}],[6159,"سیدنا واثلہ بن اسقع رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”سب سے بڑا افترا ( جھوٹ گھڑنا) یہ ہے کہ جو اپنے آپ کو اپنے باپ کے علاوہ کسی اور کی طرف منسوب کرے، یا رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ باندھے یا جھوٹا خواب بیان کرے۔“ اس حدیث کو زہری سے صرف یونس نے اور یونس سے صرف طلحہ بن ربیعہ نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔ شانده لفظ افرای اسم تفضیل کا صیغہ ہے۔ یعنی بہت ہی بڑا جھوٹ۔ مذکورہ حدیث سے معلوم ہوا کہ اپنا نسب بدلنا بہت بڑا جھوٹ ہے۔ ایسے لوگوں کو غور کرنا چاہیے جو دھوکا دینے کے لیے اپنے باپ بدل لیتے ہیں یا عورتیں کسی کو اپنا شوہر باور کراتی ہیں اور کچھ لوگ اپنی قومیت بدل لیتے ہیں۔ (٢) یہ بھی معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ باندھنا کبیرہ گناہ ہے۔ (٣) مذکورہ حدیث سے یہ بھی معلوم ہوا کہ جھوٹا خواب بنانا بہت ہی بڑا گناہ ہے لیکن یہ بیماری ہمارے معاشرے میں عام ہے، جو لوگ شہرت و ناموری کے بھوکے ہوتے یا اپنی پاکبازی کا پرو پیگنڈا کرنا چاہتے ہوں، وہ اپنی طرف سے جھوٹے خواب بنا کر لوگوں کو بتاتے ہیں۔ ایک دوسری حدیث میں ہے کہ سیدنا عبداللہ ابن عباس ناہنجا سے روایت ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: جس شخص نے ایسا خواب بیان کیا، جو اس نے نہیں دیکھا تو اسے (قیامت والے دن ) مجبور کیا جائے گا کہ وہ جو کے دو دانوں کے در میان گرہ لگائے اور وہ یہ ہرگز نہیں کر سکے گا۔ (بخاری، کتاب التعبير، رقم: ٧٠٤٢)","",{"k":"صحیح بخاری (٣٥٠٩، ٧٠٤٣)، مسند احمد (٥٩٩٨)۔"}],[6160,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کی زمین ہوتو وہ اسے کاشت کرے یا پھر اپنے (مسلمان) بھائی کو عطیہ کے طور پر دے دے۔“ اس حدیث کو یونس سے صرف حماد بن سلمہ نے روایت کیا۔","",{"k":"صحیح بخاری (٢٣٤٠)، صحیح مسلم (١٥٣٦/٩٢)۔","f":". ایک دوسری حدیث میں ہے، نبی معظم صلی اللہ علیہ وسلم ایک مرتبہ ایسے کھیت کی طرف تشریف لے گئے، جس کی کھیتی لہلہا رہی تھی۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا کہ یہ کس کا ہے؟ صحابہ کرام نے بتلایا کہ فلاں نے اسے کرایہ پر لیا ہے اس پر آپ صلی اللہ علیہ وسلم نے فرمایا کہ اگر وہ ہدیتاً دے دیتا تو اس سے بہتر تھا کہ اس پر ایک مقررہ اجرت وصول کرتا۔ (بخاری، کتاب الهبة، رقم: ٢٦٣٤) مطلب ان احادیث کا یہ ہے کہ اگر کسی کے پاس فالتو زمین بریکار پڑی ہوئی ہے تو بہتر ہے کہ وہ اپنے کسی بھائی کو بطور عطیہ دے دے کہ وہ اس زمین سے فائدہ حاصل کر سکے، ویسے قانونی حیثیت میں بہر حال وہ اس کا مالک ہے اور ٹھیکے پر دے سکتا ہے۔ ١٦١"}],[6161,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جنت میں ایک دروازہ ہے جسے الریان کہتے ہیں: قیامت کے دن اس میں سے صرف روزہ دار ہی داخل ہوں گے۔ اس حدیث کو حمد بن عمرو سے صرف عمر بن حبیب نے روایت کیا۔ اس میں الحسن بن جبلہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠١٨٠)، مجمع البحرين (١٤٦٩)، صحیح بخاری (١١٥٢)۔","f":"مذکورہ حدیث سے روزے داروں کی فضیلت واضح ہے۔ روزے داروں سے مراد وہ اہل ایمان ہیں جو رمضان کے فرض روزوں کے علاوہ دیگر ایام میں کثرت سے نفلی روزے رکھتے ہیں ورنہ رمضان کے روزے تو ہر مسلمان کے لیے ضروری ہیں۔ جس طرح باب الریان ہے، اسی طرح جنت کے دوسرے دروازے باب الصلاۃ، باب الجہاد بھی ہیں۔"}],[6162,"سیدنا انس بن مالک نبی اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب کسی گھرانے میں افطاری کرتے تو آپ مطل علم یہ دعا کرتے تھے۔ روزہ داروں نے تمہارے ہاں افطار کیا، نیک لوگوں نے تمہارا کھانا کھایا، فرشتے (رحمت کے ساتھ ) تم پر نازل ہوئے۔ “ ( تمہارے ہاں روزہ دار افطار کرتے رہیں، نیک لوگ تمہارا کھانا کھاتے رہیں اور ( رحمت کے ) فرشتے تم پر نازل ہوتے رہیں۔‘) اس حدیث کو یحیی بن سعید سے صرف مہران بن اسحاق نے روایت کیا۔اس میں الحسن بن جبلہ کا تفرد ہے۔","",{"k":"مسند احمد (٣/١١٨)، قال شعیب الارناؤط : حديث صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جب کسی کے گھر روزہ افطار کریں تو گھر والوں کو مذکورہ بالا الفاظ کے ساتھ دعا دیں، یا افطاری کے علاوہ بھی کسی کے گھر سے کھانا کھائیں تو مذکورہ الفاظ پڑھے جا سکتے ہیں۔ اسی طرح یہ دعا بھی ثابت ہے کہ مہمان میز بان کو دے: ((اللَّهُمَّ بَارِكْ لَهُمْ فِى مَا رَزَقْتَهُم وَاغْفِرْلَهُمَ وَارْحَمْهُم)) (مسلم، کتاب الاشربة، رقم: ٢٠٤٢) مذکورہ بالا روایت میں میزبان کے لیے اس بات کی دعا ہے کہ تمہیں یہ توفیق ملتی رہے کہ تمہارے پاس روزے دار نیک لوگ آئیں اور تمہارے خوان نعمت سے لطف اندوز ہوں اور تم زیادہ سے زیادہ فرشتوں کی دعائے رحمت و مغفرت کے مستحق بنو۔ اس میں حسب توفیق و استطاعت مہمان نوازی کی ترغیب بھی ہے۔"}],[6163,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دو نعمتیں ایسی ہین جن کی اکثر لوگ قدر نہیں کرتے، صحت اور فراغت۔“ اس حدیث کو الحسن سے صرف حمید بن الحکم نے روایت کیا۔ اس میں عمرو بن عاصم کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٢٩٠، ٦٣١)، صحیح بخاری (٦٤١٢)، سنن ترمذی (٢٣٠٤)۔","f":"غین کے معنی ہیں گھاٹا، یعنی اپنی چیز کو کم قیمت پر فروخت کر دینا، یا کسی چیز کو اس کی اصل قیمت سے دگنی تگنی قیمت پر خریدنا۔ دونوں صورتوں میں انسان کا گھاتا ہے اور معلوم ہونے پر اسے حسرت و ندامت ہوتی ہے۔ اسی گھاٹے اور حسرت کو غبن کہتے ہیں۔ انسانوں کی اکثریت صحت اور فراغت والی نعمت کی قدر نہیں کرتے، وہ اپنے اوقات بھی بے فائدہ اور فضول کاموں میں صرف کرتی ہے اور جسمانی قوت و توانائی بھی اللہ کی نافرمانی میں خرچ کرتی ہے، اس کا سخت خمیازہ اس کو قیامت والے دن بھگتنا پڑے گا، جب ہر چیز کا حساب ہو گا اور اس کی زندگی کے متعلق سوال کیا جائے گا، اسی لیے ایک آدمی کو نبی معظم ملنے سلیم نے نصیحت کرتے ہوئے فرمایا: ((اغْتَنِمْ خَمْسًا قَبْلَ خَمْسِ الخ)) پانچ چیزوں کو پانچ چیزوں سے پہلے غنیمت جانو، جوانی کو بڑھاپے سے پہلے، صحت کو بیماری سے پہلے، تو نگری کو فقر سے پہلے، فراغت کو مصروفیت سے پہلے اور زندگی کو موت سے پہلے۔ (مستدرك حاكم: ٢٤١/٤) مولانا الطاف حسین حالی اپنی مسدس میں اس حدیث کو یوں بیان کرتے ہیں:: غنیمت ہے صحت علالت سے پہلے فراغت مشاغل کی کثرت پہلے جوانی بڑھاپے کی زحمت سے پہلے اقامت، مسافر کی رحلت سے پہلے فقیری پہلے غنیمت ہے دولت جو کرنا ہے کر لو کہ تھوڑی ہے مہلت (مسدس حالی ص: ٢٠)"}],[6164,"سیدنا ابو جحیفہ ضیا المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو نماز پڑھتے ہوئے دیکھا اس نے اپنا کپڑا گلے میں اس طرح لٹکا رکھا تھا کہ اس کے دونوں سرے سامنے لٹک رہے تھے۔ پس رسول اللہ صلی اللہ علیہ وسلم اس کے قریب گئے اور اس کے کپڑے کو موڑ دیا۔“: ٦١٦٥ مذکورہ روایت ضعیف ہے۔ اس میں حفص بن ابی داؤد غاضری، متروک ہے۔","",{"k":"مجمع الزوائد (٢/٥٠)، سنن ابو داود (٦٣٨)، اسناده ضعيف . ٥٠۔"}],[6165,"سیدنا سہل بن سعد الساعدی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو مسلمان جہاد حج یا عمرہ کے لیے اللہ کی راہ میں نکلتا ہے تو شام ہونے تک اس کے گناہ معاف کر دیے جاتے ہیں۔“ ان دونوں حدیثوں کو الہیثم بن حبیب سے صرف حفص بن ابی داود نے روایت کیا۔ ان دونوں حدیثوں میں احمد بن الفرج کا تفرد ہے۔ ٦١٦٦","",{"k":"مجمع الزوائد (٣/١٠٩)، ضعیف ترغیب و ترهيب (٧٠١)، سلسله ضعیفه (٥٠٩٥)، اسناده ضعيف۔"}],[6166,"سیدنا ابو ہریرہ ضمنی الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”دین میں فقاہت ( سمجھ بوجھ اللہ کی بہترین عبادت ہے۔ فقیہ شیطان پر ہزار عابد سے زیادہ سخت ہے۔ ہر چیز کا ایک ستون ہے اور: اس دین کا ستون فقہ ہے۔ اس حدیث کو صفوان بن سلیم سے صرف یزید بن عیاض نے روایت کیا۔","",{"k":"مجمع الزوائد (١/١٢٤)، سنن ترمذی (٢٦٨١)، سنن ابن ماجه (٢٢٢)، سلسله ضعيفه (٤٤٦١)، قال الشيخ الالباني .موضوع۔"}],[6167,"سیدنا عبداللہ ابن عمر نبی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اللہ کی رضا کے لیے مسجد بناتا ہے خواہ وہ کبوتری کے انڈہ دینے کی جگہ کے برابر ہو (یعنی خواہ بہت ہی چھوٹی ہو ) اللہ اس کے لیے جنت میں گھر بنا دیتا ہے۔“ اس حدیث کو نافع سے صرف ابن ابی لیلی نے اور ابن ابی لیلی سے صرف الحکم بن ظہیر نے روایت کیا۔","",{"k":"مجمع الزوائد (٢/٧)۔"}],[6168,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” ایک آدمی جنت میں داخل ہو گا، وہاں ہر گھر اور ہر بالا خانے والے کہیں گے خوش آمدید، خوش آمدید، خوش آمدید، ہماری طرف تشریف لاؤ۔ سیدنا ابو بکر رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! آپ آج اس آدمی کے متعلق جانتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں، ابو بکر وہ آپ ہیں۔ اس حدیث کو قیس بن سعد سے صرف رباح بن ابی معروف نے اور رباح سے صرف ابن ابی فریک نے روایت کیا۔ اس میں احمد بن محمد بن ابی بکر السلمی کا تفرد ہے۔","",{"k":"معجم کبیر طبرانی (٣٠٨/٩)، ابن حبان (٦٨٦٧)۔"}],[6169,"سیدنا عبداللہ ابن عباس رضی جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ولی (سرپرست) کے بغیر نکاح نہیں ہوتا۔ اس حدیث کو عطا کے حوالے سے سیدنا عبداللہ ابن عباس ریلی لینا سے صرف نہاس بن ق ہم نے روایت کیا ہے۔ ٦١٧٠","",{"k":"٦١٦٩ معجم كبير (٣٤١/٧)۔"}],[6170,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رمضان میں اللہ کا ذکر کرنے والے کے گناہ بخش دیے جاتے ہیں اور اس میں اللہ سے مانگنے والا نامراد نہیں رہتا۔“ اس نه ده حدیث کو علی بن زید سے صرف ہلال بن عبد الرحمن نے روایت کیا، اس میں عبد الرحمن بن قیس کا تفرد ہے۔ سیدنا عمر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (١٤٤/٣)، ضعيف الجامع الصغير (٣٠٣٨)، سلسله ضعیفه (٣٦٢١)، قال الشيخ الالباني موضوع۔"}],[6171,"سیدنا ان نبی اللہ سے روایت ہے کہ نبی ٹیم نے فرمایا: \"جو شخص اللہ کا ذکر کرتا ہے اور اللہ کے ڈر سے اس کی آنکھیں اشک بار ہو جاتی ہیں حتی کہ اس کے آنسو زمین پر گر جاتے ہیں تو اللہ قیامت کے دن اسے عذاب نہیں دے گا۔“ اس حدیث کو ابو جعفر الرازی سے صرف محمد بن سلیمان بن ابی داود نے روایت کیا۔ حرام ہو جاتی ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم جو اللہ کے خوف کی وجہ سے روتا ہے اس پر جہنم کی آگ ٦١٧٢","",{"k":"ضعیف ترغیب ترهیب (٢/١٨١، ١٩٣١)۔"}],[6172,"سیدہ عائشہ بنی ہوجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص تہجد پڑھتا ہو لیکن کسی رات وہ سویا ر ہے تو اللہ اس کے لے اس رات کا ثواب لکھ دیتا ہے اور اس کا سونا اللہ کی طرف سے اس کے لیے صدقہ ہو جائے گا۔“ اس حدیث کو محمد بن المنکد ر، عن سعید بن جبیر، عن الاسود بن یزید، عن عائشہ کی سند سے صرف ابو جعفر الرازی نے روایت کیا۔ مالک نے اسے محمد بن المنکد ر عن سعید بن جبیر، عن عائشہ کی سند سے روایت کیا۔","",{"k":"سنن ابو داود (١٣١٤)، سنن نسائی، قال الشيخ الالباني: صحيح۔","f":"مذکورہ حدیث سے اللہ ذوالجلال کا اپنے بندوں کے ساتھ فضل و کرم کرنا ثابت ہوتا ہے کہ ایک آدمی اگر نماز تہجد پڑھتا ہے کبھی نہ اٹھ سکا تو اللہ ذوالجلال اس کو ثواب نماز تہجد کا ہی عطا فرمائے گا۔ یعنی نماز کا بھی ثواب مل گیا اور ساتھ ہی نیند اضافی طور پر مل گئی۔ تاہم مستحب یہ ہے کہ وہ رات کو نہیں اٹھ سکا تو سورج نکلنے کے بعد بارہ رکعتیں پڑھ لے جیسا کہ سیدہ عائشہ خلیل عنہا سے روایت ہے کہ جب نبی معظم صلی اللہ علیہ وسلم سے تکلیف یا کسی اور وجہ سے رات کی نماز چھوٹ جاتی تو آپ دن کو بارہ رکعتیں ادا فرماتے۔ (صحیح مسلم، کتاب صلاة المسافرين، رقم: (٧٤٦ ٦١٧٣"}],[6173,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”فرشتوں نے کہا: ہمارے پروردگار! تو نے انسانوں کو عطا کیا، پس وہ کھاتے پیتے،ہسواری کرتے اور لباس پہنتے ہیں، جبکہ ہم: تیری حمد کے ساتھ تسبیح بیان کرتے ہیں، ہم کھاتے پیتے ہیں، نہ کھیل کو د کرتے ہیں، پس تو نے جس طرح ان کے لیے دنیا مقرر کر دی ہے تو ہمارے لیے آخرت مقرر فرما دے۔ اس نے فرمایا: میں نے جسے اپنے ہاتھ سے بنایا ہے میں اس کی اولاد کو اس کے مانند نہیں کروں گا جسے میں نے کہا: ہو جا تو وہ ہو گیا۔“ اس حدیث کو صفوان بن سلیم سے صرف طلحہ بن زید اور ابو غسان محمد بن مطرف نے روایت کیا۔ اس میں طلحہ بن زید سے محمد بن ماہان کا تفرد ہے اور ابوغسان سے حجاج الاعرج کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨٢/١)، شرح عقيده طحاوية للالبانی (٣٤٢/١)، اسناده ضعيف۔"}],[6174,"سیدنا معاویہ بن الحکم اسلمی فی اللہ سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو انہوں نے عرض کیا: اللہ کے رسول! میں آپ ملنے سے ایک امر کے متعلق سوال کرنا چاہتا ہوں، میں اس کے متعلق آپ ملنے ایام کے بعد کسی سے سوال نہیں کروں گا، ہمارا باپ کون ہے؟ فرمایا: ” آدم علی نام “ اس نے کہا: ہماری والدہ؟ فرمایا: ” حواء۔ عرض کیا: جنوں کا باپ کون ہے؟ فرمایا: ” ابلیس “ عرض کیا: ان کی ماں کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کی بیوی۔“ اس حدیث کو الزہری سے صرف یونس بن یزید نے اور یونس سے صرف طلحہ بن زید نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔","",{"k":"كم مجمع الزوائد (١/١٩٣)، اسناده ضعیف۔"}],[6175,"سیدنا سبرہ الیمنی فی اللہ نے فرمایا: نبی سے ہم نے عورتوں کے (ساتھ نکاح) متعہ سے منع فرمایا ہے۔ اس حدیث کو ابو فروہ سے صرف سلمہ بن صالح نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔","",{"k":"ده دات صحيح مسلم (٤٠٦/٢٥)، سنن ابو داود (٢٠٧٢)، سنن نسائی (٣٣٦٦.٦١٧٦)۔"}],[6176,"سیدنا عبد اللہ ابن عباس خلیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ی منی کی راتوں میں ہر رات بیت اللہ تشریف لاتے تھے، پھر آپ ملے لیکن طواف کرتے اور طواف کی دورکعتیں پڑھتے اور صبح ہونے سے پہلے پہلے منی تشریف لے جاتے تھے۔“ طاوس سے صرف عمر بن ریاح نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ منی والی راتوں کو بیت اللہ کی زیارت کرنا جائز ہے، تاہم صبح ہونے سے پہلے واپس منی میں لوٹ آنا چاہیے۔","",{"k":"صحیح بخاری، سلسله صحيحه (٨٠٤)۔"}],[6177,"سیدہ ام سلمہ رونی اشیا نے بیان کیا، میں نے عرض کیا: اللہ کے رسول! کیا ہم (خواتین) پر جہاد فرض ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں، تمہارا جہاد یہ گھر ہے۔ یعنی: مکہ (مراد حج کرنا ہے)۔‘ اس حدیث کو علقمہ بن مرشد سے صرف ابو شیبہ نے روایت کیا، اس میں ابوسمرہ کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ عورتوں پر جہاد واجب نہیں ہے، لیکن عورت جہاد میں: ٦١٧٨","",{"k":"و۔","f":"زخمیوں کی مرہم پٹی کرنے اور انہیں ایک جگہ سے دوسری جگہ منتقل کرنے کے لیے شرکت کر سکتی ہیں۔"}],[6178,"سیدنا عبداللہ ابن عباس نیای اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” انصار کی جماعت! تمہارا سردار کون ہے؟ انہوں نے عرض کیا: جد بن قیس اور ہم اسے بخیل جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ تمہارا سردار نہیں، تمہارا سردار تو عمرو بن الجموح ہے۔“ وہ سخی تھے۔","",{"k":"تقدم تخريجة (٣٦٥٠)۔"}],[6179,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، ہم نے قربانی کا جانور خریدا، بھیڑیے نے اس پر حملہ کر دیا اور اس کی ایک طرف کاٹ دی، میں نبی صلی اللہ علیہ وسلم کے پاس آیا تو میں نے اس کے متعلق آپ طل علم سے سوال کیا تو آپ مطلقے علیم نے فرمایا: تم پر اور قربانی لازم نہیں، پس تم اسے ہی قربان کرو۔ ان دونوں حدیثوں کو الحکم سے صرف ابو شیبہ نے روایت کیا۔ ان دونوں میں ابوسمرہ کا تفرد ہے۔","",{"k":"مسند احمد (٣٢٣٢٧٨)، اسناده ضعيف۔"}],[6180,"سیدنا عبداللہ ابن عباس نا اہوجا نے بیان کیا، داود نبی علی نام کی دعا ہوتی تھی: ”اے اللہ! ایسے مال سے تیری پناہ چاہتا ہوں جو مجھ پر فتنہ ہو، ایسی اولاد سے جو مجھ پر وبال ہو، ایسی اہلیہ سے جو بڑھاپے سے پہلے بڑھاپے کو پہنچا دے، میں برے ہمسائے سے تیری پناہ چاہتا ہوں، اس کی آنکھیں میری نگرانی کرتی ہوں اور اس کے کان مجھے سنتے ہوں، اگر وہ (میری) کوئی اچھائی دیکھے تو اسے دفن کر دے اور اگر کوئی برا عمل دیکھے تو اس کو مشہور کر دے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دار اقامت میں برا ہمسایہ بہت بڑی مصیبت ہے۔ یہ حدیث سیدنا عبد اللہ ابن عباس نیلی اینجا اسے صرف اس اسناد سے مروی ہے۔ اس میں ابو علی الرجی حسین بن عبد اللہ بن عبید اللہ بن العباس بن عبد المطلب کا تفرد ہے۔ ٦١٨١","",{"k":"مجمع الزوائد (١٠/١٨٣)، اسناده ضعیف۔"}],[6181,"سیدہ عائشہ بین النہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے شادی کی جبکہ آپ صلی اللہ علیہ وسلم حالت احرام میں تھے۔ اس حدیث کو عثمان بن الاسود سے صرف ابو عاصم نے روایت کیا۔","",{"k":"مجمع الزوائد (٤٩١٠/٤، ٧٤٠٥)، اسناده ضعيف۔"}],[6182,"سیدنا عبد اللہ بن عمر فی الیہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے صحن میں بیٹھے ہوئے تھے کہ ایک خاتون گزری۔ کسی نے کہا: یہ محمد اے سی کی بیٹی ہیں۔ ابوسفیان نے کہا: بنو ہاشم میں محمد ( م ) کی مثال بد بو کے وسط میں خوشبو کی مانند ہے، پس وہ خاتون رسول اللہ صلی اللہ علیہ وسلم کے پاس گئیں اور انہوں نے آپ صلی اللہ علیہ وسلم کو بتایا، پس آپ ملے لی تم باہر تشریف لائے تو ناراضی آپ صلی اللہ علیہ وسلم کے چہرے سے عیاں تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں کو کیا ہو گیا ہے کہ وہ میرے اہل کے متعلق مجھے ایذا پہنچاتے ہیں۔“ پھر فرمایا: اللہ نے سات آسمان تخلیق فرمائے، پس اس نے سب سے اوپر والا منتخب فرمایا اور وہاں اقامت اختیار کی اور اپنی مخلوق میں سے جسے چاہا باقی سارے آسمانوں میں قیام کرایا اور اس نے ساتوں زمینیں تخلیق کیں، پس اوپر والی کو منتخب کیا اور اپنی مخلوق میں سے جسے چاہا وہاں قیام کرایا، پھر اس نے مخلوق تخلیق کی، اور مخلوق میں سے بنو آدم کو پسند کیا، بنو آدم میں سے عرب کو اختیار کیا، عربوں میں سے مضر کو، مصر میں سے قریش کو، قریش میں سے بنو ہاشم کو اور بنو ہاشم میں سے مجھے پسند کیا، میں پسندیدہ لوگوں میں سے پسندیدہ لوگوں کی طرف مبعوث کیا گیا ہوں، پس جو عرب سے محبت کرتا ہے تو وہ میری محبت کی وجہ سے ان سے محبت کرتا ہے اور جو عرب سے بغض رکھتا ہے تو وہ: ٦١٨٣ میرے بغض کی وجہ سے ان سے بغض رکھتا ہے۔“ اس حدیث کو عمرو بن دینار سے صرف محمد بن ذکوان نے اور محمد بن ذکوان سے صرف حماد بن واقد نے روایت کیا۔ یہ سیدنا عبداللہ ابن عمر سے صرف اسی اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٢١٥/٨)، اسناده ضعيف۔"}],[6183,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم سفید گول ٹوپی پہنا کرتے تھے۔“ یہ حدیث سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے، اس میں عبد اللہ بن خراش کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/١٢٩)، اس میں عبد اللہ بن خراش منکر الحدیث ہے ۔۔"}],[6184,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علی علیم نے فرمایا؛ «علم سیکھو اور علم کی خاطر سکینت و وقار سیکھو اور جس سے علم حاصل کر رہے ہو اس کے ساتھ تواضع سے پیش آؤ۔“ ٦١٨٥","",{"k":"مجمع الزوائد (١/١٢٩)، سلسله ضعیفه (٥١٦٠)، ضعیف ترغیب و ترهيب (٨١)۔"}],[6185,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے دوست سے اعتدال کے ساتھ دوستی رکھ ہوسکتا ہے کسی روز وہ تمہارا دشمن ہو جائے اور اپنے دشمن سے اعتدال کے ساتھ دشمنی رکھ، ہو سکتا ہے کسی روز وہ تمہارا دوست ہو جائے۔“ ان دونوں حدیثوں کو ابوالزناد سے صرف عباد بن کثیر نے روایت کیا، ان دونوں میں محمد بن ماہان کا تفرد ہے۔ ٦١٨٦","",{"k":"سنن ترمذی (١٩٩٧)، قال الشيخ الالباني: صحيح۔"}],[6186,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ نے بیان کیا، غزوہ حدیبیہ کے موقع پر ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے، اس رات بہت طوفانی بارش ہوئی، جب رسول اللہ صلی اللہ علیہ وسلم نے صبح کی تو آپ میم نے فرمایا: تم جانتے ہو تمہارے رب نے کیا کہا ہے؟ انہوں نے عرض کیا: اللہ اور اس کے رسول بہتر جانتے ہیں .. آپ ل علم نے تین بار اس طرح فرمایا: ”اور انہوں نے بھی یہی عرض کیا. آپ صلی اللہ علیہ وسلم نے فرمایا: ” تمہارے رب نے فرمایا ہے: جو کہتا ہے، ہم پر فلاں اور فلاں ستارے کی وجہ سے بارش ہوئی ہے تو اس نے میرے ساتھ کفر کیا اور اس ستارے پر ایمان رکھا اور جو کہتا ہے: اللہ نے ہم پر بارش برسائی ہے تو وہ مجھ پر ایمان لایا اور اس ستارے کا انکار کیا۔ اس حدیث کو صالح بن کیسان سے صرف مسلم بن خالد نے روایت کیا۔","",{"k":"مجمع الزوائد (١١٤/٨)، سنن نسائی (٥٢٥)، سنن دارمی (٢٧٦٢)۔","f":"روه و نان نوء، ناءَ يَنُوءُ کا مصدر ہے۔ نَاءَ النَّجْمُ اس وقت بولتے ہیں جب ستارہ جھڑ جائے یا غروب ہو جائے اور بعض کہتے ہیں: اس وقت بولتے ہیں جب ستارہ طلوع ہوتا ہے۔ تمام حوادث و واقعات کا فاعل اور مؤثر حقیقی اللہ تعالیٰ ہے، اس لیے اس کی طرف ان کی نسبت ہونی چاہیے۔ اس عقیدے کے ساتھ اگر کسی موقع پر حوادث کی نسبت اسباب کی طرف بھی کر دی جائے تو وہ جائز ہے، لیکن اسباب کو ہی فاعل اور موثر مان لینا جیسا کہ اکثر مشرکین کا عقیدہ ہوتا ہے۔ کفر و شرک ہے۔ اہل جاہلیت، جب بارش کسی ستارے کے طلوع یا غروب کے وقت ہوتی تو وہ بارش اس ستارے کی طرف منسوب کر دیتے اور اسی ستارے کو وہ فاعل اور مؤثر و متصرف تسلیم کرتے۔ اس حدیث میں ایسے عقیدے کو اللہ کے ساتھ کفر و شرک قرار دیا گیا ہے۔ اللہ ذوالجلال نے ان کے رد میں فرمایا: وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِبُونَ﴾ (الواقعه: ٨٢) ”اور تم اپنے حصے میں یہی لیتے ہو کہ جھٹلاتے پھر و یعنی تم اپنے شکر کا اظہار اس صورت میں کرتے ہو کہ تم تکذیب کرتے ہو۔“ اس آیت کریمہ کی یہ تفسیر رسول اللہ صلی اللہ علیہ وسلم سے منقول ہے، چنانچہ سیدنا علی ضیا الینہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: وتجعلون رِزْقَكُمْ يقول شُكْرُكُم إِنَّكُمَ تُكَذِبُونَ يَقُولُونَ مُطِرُنَا بِنَوءٍ كَذَا و كذا وَبِنَجْمِ كذا وكذا)) (ترمذی، رقم: ٣٢٩٥، مسند احمد: ١٠٨/١) شعیب ارناؤط نے اسے حسن لغیرہ کہا ہے۔ ابن حجر (فتح الباری: ٢/ ٥٢٢) نے اسے صحیح کہا ہے، یعنی اس آیت میں رزق بمعنی شکر ہے، چنانچہ معنی یوں ہوگا کہ تم اللہ کی نعمتوں کے مقابلہ میں اظہار شکر کا یہ طریقہ اپناتے ہو کہ تم اس نعمت کا من جانب اللہ ہونے کا انکار کرتے ہو (اور کہتے ہو) کہ ہمیں فلاں ستارے سے بارش دی گئی ہے۔"}],[6187,"سیدنا عبداللہ ابن عباس والی نینجا نے بیان کیا، ہم سیدنا ابو بکر صدیق رضی اللہ عنہ کے ساتھ بیٹھے تھے تو ایک جنازہ گزرا، وہ کھڑے ہو گئے، تو ہم بھی کھڑے ہو گئے، پھر ہم نے نماز پڑھی تو انہوں نے جوتے اتار دیے، ہم نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے خلیفہ! آپ نے جوتے اتار دیے، جس وقت لوگ جوتے پہنتے ہیں۔ انہوں نے کہا: میں نے رسول اللہ علے نیلم کو فرماتے ہوئے سنا: \"جو شخص اللہ کی اطاعت میں ننگے پاؤں چلتا ہے اللہ عز وجل قیامت کے دن اس سے ان امور کے متعلق سوال نہیں کرے گا جو اس نے اس پر فرض کیے تھے۔“ یہ حدیث ابو بکر سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن عبد اللہ بن معاویہ الخذا الواسطی کا تفرد ہے۔ ٦١٨٨","",{"k":"مجمع الزوائد (١/١٣٣)، اسناده ضعيف۔"}],[6188,"سيدنا اشعث بن قیس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے مسلمانوں پر رحم نہ کیا اللہ اس پر رحم نہیں فرمائے گا۔ اس حدیث کو علقمہ بن مرشد سے صرف ہشام بن عبد الرحمن نے روایت کیا۔ اشعث بن قیس سے صرف اس اسناد سے مروی ہے۔","",{"k":"مَرْثَدٍ مجمع الزوائد (١٨٧/٨، ٣٧٢١)، مسند احمد (٤/٣٥٨)، بلفظ من لم يرحم الناس، قال شعيب الأرناؤط: حديث صحيح۔"}],[6189,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب حزن“ سے اللہ کی پناہ طلب کرو۔ “ انہوں نے عرض کیا: اللہ کے رسول! ”جب حزن“ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” جہنم میں ایک وادی ہے، جہنم اس وادی کے شر سے روزانہ چار سو مرتبہ اللہ کی پناہ طلب کرتی ہے، اس میں ”غرارون“ ڈالے جائیں گے۔ عرض کیا گیا: اللہ کے رسول! غرارون کیا ہیں؟ فرمایا: ”دنیا میں اعمال کا دکھلاوا کرنے والے۔‘ اس حدیث کو سلیمان التیمی سے صرف محمد بن الفضل نے روایت کیا۔اس میں محمد ابن ماہان کا تفرد ہے۔","",{"k":"سنن ترمذی (٢٣٧٣)، مجمع الزوائد (٣٨٨/١٠)، قال الشيخ الالباني: ضعيف۔"}],[6190,"سیدنا عبداللہ ابن عباس ولی الہنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”برا کھانا ولیمے کا کھانا ہے، جہاں شکم سیروں کو مدعو کیا جاتا ہے اور بھوکوں کو اس سے روک دیا جاتا ہے۔ اس حدیث کو قتادہ سے صرف عمران القطان نے اور عمران سے صرف سعید بن سوید نے روایت کیا۔ اس میں عبد القدوس بن محمد کا تفرد ہے۔ ٦١٩١","",{"k":"مجمع الزوائد (٥٣/٤)، اسناده ضعیف، اس میں محمد بن حنیفہ الواسطی ضعیف ہے۔۔"}],[6191,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص نماز جنازہ پڑھتا ہے اس کے لیے ایک قیراط اجر ہے اور جو شخص نماز جنازہ پڑھتا ہے اور اس کے ساتھ چلتا ہے حتی کہ اسے دفن کر دیا جائے اس کے لیے دو قیراط اجر ہے اور قیراط احد ( پہاڑ) کے مثل ہے۔“ اس حدیث کو کامل ابو العلاء سے محمد بن اسماعیل الکوفی نے روایت کیا۔ اس میں معمر بن سہل کا تفرد ہے۔ ٦١٩٢","",{"k":"صحیح بخاری (١٣٢٥)، صحیح مسلم (٥٤٥)۔"}],[6192,"سیدنا رافعہ ابو موسی الصفار نے بیان کیا، میں نے سیدنا عبداللہ ابن عباس فضای اینجا سے پوچھا کون سا صدقہ افضل ہے؟ انہوں نے کہا: میں نے رسول اللہ ملنے کی یمن سے سوال کیا، میں نے عرض کیا: کون سا صدقہ افضل ہے؟ آپ ملنے کی تم نے فرمایا: ”پانی۔ میں نے عرض کیا: اللہ کے نبی! کون سا صدقہ افضل ہے؟ آپ لم نے فرمایا: ”پانی۔ کیا تم دیکھتے نہیں کہ جہنمی جب جنتیوں سے فریاد کریں گے تو وہ اس طرح آواز دیں گے: ”ہمیں کچھ پانی یا اللہ نے تمہیں جو کچھ دے رکھا ہے اس میں سے کچھ عنایت کرو۔“ اس حدیث کو سیدنا: مقدم عبداللہ ابن عباس علی تنہا سے صرف اس اسناد سے روایت کیا جاتا ہے۔ اس میں محمد بن موسی الحرشی کا تفرد ہے۔","",{"k":"کر تقدم تخريجه (١٠١١)۔"}],[6193,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلے علی کی صفا اور مروہ کے درمیان سعی کرتے تھے تو بطن مسیل (پانی بہنے کی جگہ یعنی: نالے کے وسط میں ) تیز تیز چلتے تھے۔“ اس حدیث کو عبید اللہ بن عمر سے صرف ایوب بن واقد نے روایت کیا۔","",{"k":"صحیح بخاری (١٦١٧)، مسلم (١٢٦١)۔","f":"نشیبی جگہ پر پہنچ کر مردوں کے لیے دوڑنا مسنون ہے، عورتوں یا بیماری یا بڑھاپے کی وجہ سے سبز ستونوں کے درمیان تیز تیز نہ چلنے میں کوئی حرج نہیں ہے۔ ٦١٩٤"}],[6194,"سیدہ عائشہ بنی اشیا نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے برتن رکھا کرتی تھیں، آپ ملے عام اپنے ہاتھ پر پانی انڈیلتے تو اسے دھوتے تھے، حتی کہ اسے صاف کر لیتے، پھر دائیں ہاتھ سے بائیں پر پانی ڈالتے اور شرم گاہ دھوتے تھے، پھر تین بار سر پر پانی ڈالتے اور پھر غسل کرتے تھے۔“ اس حدیث کو منصور سے صرف زیاد بن عبد اللہ البکائی نے روایت کیا۔: ائد مذکورہ حدیث سے معلوم ہوا کہ غسل جنابت سے پہلے ہاتھ دھونے چاہیے پھر شرم گاہ۔","",{"k":"صحیح بخاری (٢٤٨)، مسلم (٣١٦)۔"}],[6195,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب کسی عورت کو پیغام نکاح کا ارادہ فرماتے تو آپ ملت علی ام ام سلیم نا ہی کو بھیجتے وہ اسے دیکھتی تھی، وہ اس کے سر کو سونگھتیں اور اس کی ٹانگوں کو دیکھتی تھیں۔ یہ حدیث سیدنا انس رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن موسی الحرشی کا مذکورہ بالا روایت سے یہ معلوم ہوا کہ اگر انسان خود نہ دیکھے تو اپنی کسی عزیزہ کو یا اور کسی عورت کو بھیج کر اس کے ذریعہ سے عورت کے رنگ روپ اور عادات و خصائل کے متعلق صحیح معلومات حاصل کر سکتا ہے، آپ نہ بھی دیکھیں تو کوئی حرج نہیں ہے۔ تاہم اگر خود دیکھ لیں تو یہ بھی جائز ہے۔","",{"k":"کر ع الزوائد (٢٧٦/٤)، مسند احمد (٣/٢٣١)، قال شعیب الارناؤط حدیث حسن . مجمع۔"}],[6196,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے ہیم نے فرمایا: ”جب تم میں سے کوئی روزے کی حالت میں بھول کر کھا پی لے تو وہ اپنا روزہ مکمل کرے، اسے تو اللہ نے کھلایا پلایا ہے۔ اس حدیث کو اشعث سے صرف صلہ بن سلیمان نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ روزے کی حالت میں بھول کر کھا پی لینے سے روزہ نہیں ٹوٹتا اور نہ ہی ایسے شخص پر کوئی قضا یا کفارہ لازم آتا ہے۔ جمہور علماء اسی کے قائل ہیں۔ (نیل الاوطار: ٣/ ١٧٨، سبل السلام: ٤/ ١٣٧) اس سے اسلام کی ایک شفقت وسہولت کا بھی اثبات ہوتا ہے۔","",{"k":"صحیح بخاری (١٩٣٣)، صحیح مسلم (١١٥٥)۔"}],[6197,"سیدہ ام سلمہ بنی النہا سے روایت ہے کہ سیدنا حسن رضی اللہ عنہ حسین ضیا اللہ نے نبی صلی اللہ علیہ وسلم کے پیٹ پر پیشاب کر دیا، وہ گئے تا کہ ان کو پکڑیں تو نبی مالے سلیم نے فرمایا: ”میرے بیٹے کو تکلیف نہ پہنچاؤ (اسے پیشاب کرنے دو) یا فرمایا: ” اسے عجلت میں مبتلا نہ کرو۔ پس انہوں نے انہیں چھوڑ دیا، حتی کہ وہ پیشاب کر چکے تو آپ ملنے کی ایم نے پانی منگایا اور اس پر انڈیل دیا۔ اس حدیث کو یونس سے صرف ہشیم نے روایت کیا۔ اس میں محمد بن ماہان کا تفرد ہے۔ ١٩٨","",{"k":"مجمع الزوائد (١/٢٨٥)، اسناده ضعيف۔"}],[6198,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم اپنی مدینہ تشریف آوری کے شروع ہی میں ایک دلہن کے پاس سے گزرے جبکہ اس کے ساتھ کچھ خواتین تھیں، جبکہ ان میں سے ایک کہہ رہی تھی۔ اس نے اسے مینڈھے ہدیہ کیے ہیں، وہ باڑے میں کھنکارتے ہیں اور تیرا شوہر مجلس میں وہ کل کے حالات جانتا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اس طرح نہ کہو، بلکہ تم یوں کہو: ”ہم تمہارے پاس آئے، ہم تمہارے پاس آئے . انہوں نے ہمیں سلام کیا اور انہوں نے تمہیں سلام کیا۔ اس حدیث کولیث بن سعد سے صرف مجاشع بن عمرو نے روایت۔ سیدنا انس بنی اہلیہ سے صرف اس اسناد سے مروی ہے اور ابن ابی اولیس نے اپنے والد کے حوالے سے بیٹی بن سعید، عن عمرہ، عن عائشہ کی سند سے اسے روایت کیا۔ ٦١٩٩",""],[6199,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جس کی تین بیٹیاں ہوں اس نے ان کے ساتھ اچھا سلوک کیا، انہیں ٹھکانا دیا اور ان کی شادی کر دی، اس کے لیے جنت واجب ہو گئی۔“ ہم نے عرض کیا اور دو ( بیٹیاں ) ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اور دو پر بھی۔“ ہم نے عرض کیا، ایک ہو، آپ صلی اللہ علیہ وسلم نے فرمایا: ” ایک بھی۔ اس حدیث کو ایوب سے صرف عبید بن عمرو نے روایت کیا۔ اس میں الحسن بن جبلہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥٨/٨)۔"}],[6200,"سیدنا ابو ہریرہ وی ایہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو مسلمان شخص دن اور رات میں بارہ رکعتیں پڑھتا ہے اللہ اس کے لیے جنت میں گھر بنا دیتا ہے۔‘ اس حدیث کو سلیمان التیمی سے صرف معتمر بن نافع نے روایت کیا۔ اس میں محمد بن موسی الحرشی کا تفرد ہے۔",""],[6201,"سیدنا علی رضی اللہ عنہ نے بیان کیا، دو کلمے ہیں، میں نے انہیں رسول اللہ ملنے نام سے یاد کیا ہے، میں چاہتا ہوں کہ تم بھی انہیں یاد کر لو، اللہ دنیا میں کسی گناہ کی سزا دے دے تو وہ زیادہ عادل ہے کہ وہ اپنی سزا دو بار دے اور اللہ دنیا میں جس گناہ سے در گزر فرمائے تو وہ اللہ اس بات سے زیادہ سخی ہے کہ وہ جس چیز سے درگزر فرما دے اور وہ اسے پھر دہرائے، تمہارے اور جنوں کے درمیان پردہ: بسم اللہ ہے۔“ اس حدیث کو ابو اسحاق السبیعی سے صرف الحکم النصری اور یونس بن ابی اسحاق نے روایت کیا اور الحکم النصری سے صرف خلا دالصفار نے روایت کیا، اس میں الحکم بن بشیر بن سلیمان کا تفرد ہے اور یونس بن ابی اسحاق سے الحجاج الاعور کا تفرد ہے۔ مذکورہ روایت کا پہلا حصہ ضعیف ہے۔ دیکھئے (سنن ابن ماجه، رقم: ٢٦٠٤) تحقیق شیخ الالبانی اللہ کی تاہم آخری حصہ اس کے شواہد موجود ہیں، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((ستر ما بين الجن وعورات بنى ادم اذا دخل الخلاء ان يقول بسم الله)) (ارواء الغليل: ١/ ٨٧ - سنن ابن ماجه: ٢٩٧، اسناده صحیح) بنی آدم (انسانوں) کے پردے کے اعضاء اور جنوں کی نظروں کے درمیان یہ چیز پردہ بن جاتی ہے کہ جب کوئی بیت الخلا میں داخل ہو تو بسم اللہ کہے۔","",{"k":"مستدرك حاكم (٤/٣٨٨)، مسند احمد (٠/٩٩، ٦٥١)، مجمع الزوائد: ١.٨/٧۔"}],[6202,"سیدہ ام سلمہ رضی نیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے (شوال میں ) شادی کی اور شوال میں مجھ سے تعلق زن و شو قائم کیا۔ اس حدیث کو سیدہ ام سلمہ بنی النھا سے صرف اس اسناد سے روایت کیا جاتا ہے۔ خاندان مذکورہ روایت ضعیف ہے۔ تاہم سیدہ عائشہ نیلی نیہا کا نکاح شوال کے مہینے میں ہوا تھا جیسا کہ صحیح مسلم میں ہے کہ سیدہ عائشہ منی با بیان کرتی ہیں کہ رسول اللہ ملے نسیم نے میرے ساتھ شوال میں نکاح کیا اور میری رخصتی بھی شوال میں ہوئی تو رسول اللہ صلی اللہ علیہ وسلم ن کی بیویوں میں سے کون سے بیوی تھی جو مجھ سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے ہاں خوش نصیب ہو؟ (مسلم، کتاب النکاح، رقم: ١٤٢٣) مذکورہ حدیث سے معلوم ہوا که ماه شوال میں شادی کرنا جائز ہے، زمانہ جاہلیت میں شوال کے مہینہ میں نکاح کرنے کو بے برکت سمجھا جاتا تھا، (جیسا کہ آج بھی جہلاء کا یہ عقیدہ ہے کہ محرم اور صفر کے مہینوں میں شادی کروانا نحوست ہے۔) سیدہ عائشہ نیلی نیا اس کا رد کر رہی ہیں اور اس کو غلط قرار دے رہی ہیں۔ سیدہ عائشہ بنا لوہا کا مقصود یہ ہے کہ اگر شوال میں نکاح کرنا منحوس ہوتا تو مجھے نبی صلی اللہ علیہ وسلم کے ہاں اتنی قدر و منزلت حاصل نہ ہوتی۔ ٦٢٠٣","",{"k":"سنن ابن ماجه (١٩٩١)، قال الشيخ الالباني: ضعيف۔"}],[6203,"سیدنا عمر فاروق رضی اللہ عنہ نے فرمایا: ”میں نے تین امور میں اپنے رب سے موافقت کی اور اس نے تین امور میں مجھ سے موافقت کی ہے میں نے عرض کیا: اللہ کے رسول! یہ ہمارے باپ سیدنا ابراہیم کالیندا کا مقام ہے، اگر ہم اسے جائے نماز بنا لیں تو اللہ عزوجل نے یہ آیت: ”مقام ابراہیم کو جائے نماز بناؤ “ نازل فرمائی۔ اس حدیث کو قرہ بن خالد سے صرف حفص بن عمر النجار الرازی نے روایت کیا۔ اس میں العلاء بن سالم کا تفرد ہے۔ ٦٢٠٤","",{"k":"حَفْصُ ه و ور، صحیح بخاری (٤٠٢، ٥٨٩٦)، مسلم (٢٣٩٩)۔"}],[6204,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سوال کیا، مجھے اللہ عزوجل کے اس فرمان: ((كما انزلنا على المقتسمين)) کے متعلق بتائیں، ((المقتسمین)) کون ہیں؟ آپ لئے علیم نے فرمایا: ” یہود و نصاری۔ اور اللہ تعالیٰ کا فرمان ہے: ((والذين جعلوا القرآن عضین)) ((عضین)) سے کیا مراد ہے؟ فرمایا: ”وہ (اس قرآن کے ) بعض حصے پر ایمان لائے اور بعض کا انکار کیا۔ اس حدیث کو حبیب بن حسان سے صرف حمید بن حماد بن خوار نے روایت کیا اور ابوظبیان سے اسے صرف حبیب بن حسان نے مرفوع روایت کیا اور اعمش نے اسے ابو ظبیان، عن ابن عباس سے موقوف روایت کیا۔","",{"k":"مجمع الزوائد (٤٦/٧)، صحیح بخاری (٤٧٠٦)، موقوف عن ابن عباس۔","f":": كَمَا أَنْزَلْنَا عَلَى الْمُقْتَسِيْنَ الَّذِينَ جَعَلُوا الْقُرْآنَ عِضِيْنَ (الحجر: ٩٠-٩١) ”جیسا کہ ہم نے ان تقسیم کرنے والوں پر اتارا، جنہوں نے اس کتاب کے ٹکڑے ٹکڑے کر دیئے۔“ مذکورہ بالا روایت سے معلوم ہوا کہ مقتسمین سے مراد یہو دو عیسائی ہیں۔ عضین سے مراد ہے کہ یہود و نصاریٰ نے قرآن مجید کا وہ حصہ جو تورات و انجیل سے موافق تھا، اسے مانا اور جو خلاف تھا، اسے نہ مانا۔ کیونکہ بعض چیزیں پہلی شریعت میں جائز تھیں اس میں ناجائز ہو گئیں اور پھر یہود ونصاری نے تورات، انجیل میں تحریف بھی کی۔ بعض کہتے ہیں: اس سے مراد قریش کی قوم ہے۔ جنہوں نے اللہ کی کتاب کو تقسیم کر دیا، اس کے بعض حصے کو شعر، بعض کو سحر ( جادو ) بعض کو کہانت اور بعض کو اساطیر الاولین ” پہلوں کی کہانیاں“ قرار دیا۔ عضین کا ایک معنی یہ بھی کیا گیا ہے کہ قرآن مجید کی بعض باتوں پر ایمان رکھنا اور بعض کے ساتھ کفر کرنا۔"}],[6205,"سیدنا عبداللہ ابن عم رضی اللہ عنہ نے بیان کیا، نبی لئے علیم سے سوال کیا گیا، سب سے بہترین آواز میں قرآن پڑھنے والا کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ شخص کہ جب وہ قرآن پڑھے اور تو دیکھے کہ وہ اللہ سے ڈرتا ہے۔ اس حدیث کو مسعر سے صرف حمید بن حماد نے روایت کیا، اس میں محمد بن معمر کا تفرد ہے۔ ٦٢٠٦","",{"k":"معمر مجمع الزوائد: ٧/ صحيح۔"}],[6206,"سیدنا ابو اولیس کا بیان ہے کہ میں مدینہ میں تاجر تھا۔ میں نے کہا: میں جاؤں گا، پس جب میں مدینہ پہنچا تو مجھے سیدنا ابو ہریرہ رضی نہ ملے تو انہوں نے مجھ سے سیدنا سمرہ بن جندب بنی اہلیہ کے متعلق دریافت کیا اور جب میں بصرہ پہنچا تو انہوں نے مجھ سے سیدنا ابو ہریرہ رضی اللہ عنہ کے بارے میں پوچھا۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، ہم ایک گھر میں سات افراد تھے۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے جو سب سے آخر میں فوت ہو گا، وہ آگ میں جائے گا۔‘ پس (ان سات میں سے ) میں اور سمرہ ہی باقی بچے ہیں۔“ اس حدیث کو یونس بن عبید سے صرف ابو مروان یحییٰ بن ابی زکریا الغسانی نے روایت کیا۔ اس میں محمد بن حرب کا تفرد ہے۔: ٦٢٠٧","",{"k":"مجمع الزوائد (٢٩٠/٨)، اسناده ضعیف۔"}],[6207,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، کوفہ والوں نے سیدنا سعد رضی اللہ عنہ کے بارے میں سیدنا عمر رضی اللہ عنہ کے پاس شکایات کیں۔ انہوں نے کہا: وہ اچھی طرح نماز نہیں پڑھاتے، انہوں نے فرمایا: ”ابو اسحاق ( سیدنا سعد رضی اللہ عنہ کو میرے پاس بلاؤ، جب وہ آئے تو سیدنا عم رضی اللہ عنہ نے فرمایا: یہ لوگ (کوفی) کہتے ہیں کہ آپ اچھی طرح نماز نہیں پڑھاتے؟ انہوں نے کہا: میں تو انہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز کے مطابق ہی نماز پڑھاتا ہوں، میں اس میں کوئی کمی کرنے والا نہیں ہوں، میں پہلی دو رکعتیں لمبی پڑھاتا ہوں اور آخری دور کعتیں مختصر پڑھاتا ہوں۔ انہوں نے فرمایا: ”ابو اسحاق! آپ کے متعلق میرا یہی گمان تھا۔“ ماندن بخاری شریف میں یہ روایت تفصیل کے ساتھ موجود ہے۔ سیدنا سعد بنی اہلیہ کے ساتھ رضی (سیدنا عم رضی اللہ عنہ نے ایک یا کئی آدمیوں کو کوفہ بھیجا تھا۔ قاصد نے ہر ہر مسجد میں جا کر ان کے متعلق پوچھا تو سب نے آپ کی تعریف کی، لیکن جب مسجد بنی عبس میں گئے تو ایک شخص جس کا نام اسامہ بن قتادہ اور کنیت ابوسعدہ تھی کھڑا ہوا اس نے کہا: جب آپ نے اللہ ذوالجلال کا واسطہ دے کر پوچھا ہے تو ( سنئے کہ ) سعد نہ فوج کے ساتھ خود جہاد کرتے تھے، نہ مال غنیمت کی تقسیم صحیح کرتے تھے اور نہ فیصلے میں عدل وانصاف کرتے تھے۔ سیدنا سعد رضی اللہ عنہ نے ( یہ سن کر ) فرمایا: اللہ ذوالجلال کی قسم! میں (تمہاری اس بات پر ) تین دعائیں کرتا ہوں: اے اللہ! اگر تیرا یہ بندہ جھوٹا ہے اور صرف ریا و نمود کے لیے کھڑا ہوا ہے تو اس کی عمر دراز کر اور اسے خوب محتاج بنا اور اسے فتنوں میں مبتلا کر۔ اس کے بعد ( وہ شخص اس درجہ بدحال ہوا کہ ) جب اس سے پوچھا جاتا تو کہتا کہ ایک بوڑھا اور پریشان ہوں، مجھے سیدنا سعد رضی اللہ عنہ کی بددعا لگ گئی۔ عبد الملک نے بیان کیا کہ میں نے اسے دیکھا، اس کی بھویں بڑھاپے کی وجہ سے آنکھوں پر آگئی تھیں، لیکن اب بھی راستوں میں وہ لڑکیوں کو چھیڑتا ہے۔ (بخاری، کتاب الاذان، رقم ٧٥٥، مسلم، رقم: ٤٥٣) سیدنا سعد بن ابی وقاص رضی اللہ عنہ مبشرہ میں سے ہیں۔ یہ مستجاب الدعوات تھے۔ نبی معظم صلی اللہ علیہ وسلم نے ان کے لیے دعا فرمائی تھی، عہد فاروق میں یہ کوفہ کے گورنر تھے۔ مگر کوفہ والوں کی بے وفائی مشہور ہے۔ انہوں نے سیدنا سعد بنی الینے کے خلاف جھوٹی شکایتیں کیں، آخر کار سیدنا عمر رضی اللہ عنہ نے وہاں کے حالات کا اندازہ فرما کر سیدنا عمار رضی اللہ عنہ کو نماز پڑھانے کے لیے اور سیدنا عبداللہ ابن مسعود بنی اہلیہ کو بیت المال کی حفاظت کے لیے مقرر فرمایا۔ معلوم ہوا کہ عمال حکومت کو مصلحت کے طور پر بدل دینا بھی جائز ہے، جیسے سیدنا سعد رضی اللہ عنہ کو معزول کر دیا گیا، حالانکہ ان کے خلاف شکایات جھوٹ پر مبنی تھیں۔ پھر سیدنا عمر رضی اللہ عنہ نے مصلحت اسی میں سمجھی کہ ان کی جگہ نیا حاکم مقرر کر دیا جائے۔ یہ بھی معلوم ہوا کہ کسی کی بابت تحقیق و تفتیش کرنا ہو تو اہل خیر واہل اصلاح سے پوچھا جائے جیسے کوفے کی مساجد میں جا کر نمازیوں سے تحقیق کی گئی۔ مذکورہ روایت سے سیدنا سعد رضی اللہ عنہ کی کرامت کا بھی اثبات ہے کہ سیدنا سعد رضی اللہ عنہ کی بددعائیں قبول ہوئیں۔ ٦٢٠٨","",{"k":"صحیح بخاری (٧٥٥)، مسلم۔"}],[6208,"سیدنا عطیہ القرظی رضی اللہ عنہ نے بیان کیا، میں بھی ان میں شامل تھا جن کے بارے میں سیدنا سعد بن معاذضی اللہ نے فیصلہ کیا تھا۔ انہوں نے کہا: پس انہوں نے میرے زیر ناف بال دیکھے تو انہوں نے دیکھا کہ وہ اگے نہیں تھے۔ پس انہوں نے مجھے چھوڑ دیا، (اور قتل نہ کیا۔‘ اس حدیث کو داود الطائی صرف اسماعیل بن علیہ نے روایت کیا۔ بنو قریظہ یہودی قبیلہ مدینہ کے اطراف میں آباد تھا اور میثاق مدینہ کی رو سے یثرب کے دفاع کا ذمے دار اور پابند تھا مگر جنگ خندق کے موقع پر انہوں نے اس معاہدے کی خلاف ورزی کرتے ہوئے قریش مکہ کا ساتھ دیا تو اللہ ذوالجلال نے مسلمانوں کو فتح عطا کی اور قریش مکہ کو ذلیل کیا۔ بعد ازاں مسلمانوں نے بنو قریظہ کا محاصرہ کیا تو یہ لوگ سیدنا سعد بن معاذ رضی اللہ عنہ کے فیصلے پر راضی ہو گئے، کیونکہ سیدنا سعد رضی اللہ عنہ کے اوس قبیلے کے سردار تھے، بنو قریظہ کے یہودی اوس کے حلیف تھے۔ یہودیوں کا خیال یہ تھا کہ وہ فیصلہ کرتے ہوئے ہمارا خیال کریں گے۔ صحیح بخاری میں ہے کہ سیدنا سعد بنی اللہ نے فیصلہ دیا کہ ان کے جو لوگ لڑنے کے قابل ہیں، انہیں قتل کر دیا جائے اور ان کے بچوں اور عورتوں کو قیدی بنا لیا جائے۔ اس فیصلے پر رسول اللہ علیم نے فرمایا: ((قضت بحكم الله)) (بخاری، کتاب المغازی، رقم: ٤١٢١) تم نے اللہ کے فیصلے کے مطابق فیصلہ کیا۔ مذکورہ بالا روایت میں جو ہے کہ عطیہ قرضی ضیا اللہ فرماتے ہیں: میں قیدیوں میں سے تھا تو زیر ناف بال دیکھئے گئے، معلوم ہوا کہ زیر ناف بال اگ آنا بلوغت کی علامت ہے۔ یہ بھی معلوم ہوا کہ شرعی ضرورت کے لیے کسی کے زیر ناف بال دیکھ لینا جائز ہے۔ بلا ضرورت شرعی نا جائز ہے۔ ٦٢٠٩","",{"k":"سنن ابن ماجه (٢٥٤١)، سنن ترمذی (١٥٨٤)، قال الشيخ الالباني: صحيح، سنن ابو داود (٤٤٠٤)۔"}],[6209,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کھانے کو ٹھنڈا کر کے کھاؤ، کیونکہ گرم کھانے میں برکت نہیں ہوتی۔“ اس حدیث کو ابن ابی ذئب سے صرف عبد اللہ بن یزید نے روایت کیا۔ اس میں ہشام کا تفرد ہے۔ ٦٢١٠","",{"k":"مجمع الزوائد: د (٥/٢٠)، سلسله ضعیفه (١٥٨٧)، اسناده ضعيف۔"}],[6210,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، ہم رسول اللہ صل علی کی خدمت میں آپ صلی اللہ علیہ وسلم کے گھر حاضر ہوئے تو آپ صلی اللہ علیہ وسلم نے ایک آدمی کو پراگندہ حالت میں دیکھا تو فرمایا: ” کیا یہ نہیں پاتا جو اس کا لباس دھوتا اور اس کے بکھرے بالوں کو سنوارتا “ اس حدیث کو محمد بن المنکد رسے صرف حسان بن عطیہ نے روایت کیا۔ اس میں الاوزاعی کا تفرد ہے۔ مذکورہ روایت سے معلوم ہوا کہ میلے کچیلے کپڑے پہنا اور بالوں کو نہ سنوارنا، سادگی نہیں ہے بلکہ جہالت اور غفلت کی علامت ہے۔ دین اسلام تو واحد ایک ایسا دین ہے جس میں صفائی کی بہت زیادہ اہمیت ہے۔ جیسا کہ رسول اللہ سے تم نے فرمایا: ((الطهور شطر الایمان)) (مسلم: ٨٣٢) ”پاکیزگی آدھا ایمان ہے۔“ ایک اور حدیث میں ہے کہ رسول اللہ نے ہم نے فرمایا: ((ان الله جَمِيلٌ يُحِبُّ الْجَمَالَ)) (مسند احمد: ٤ / ١٣٣، ١٣٤) بلاشبہ اللہ تعالیٰ حسین و جمیل ہے اور جمال یعنی حسن و خوبصورتی کو پسند فرماتا ہے۔“ معلوم ہوا کہ مسلمان وہ ہے جو اپنے جسم اور اپنے لباس کی صفائی ستھرائی کا خیال رکھتا ہے۔ ٦٢١١","",{"k":"سنن ابو داود (٤٠٦٢)، قال الشيخ الالبانى صحيح۔"}],[6211,"سیدنا ابو جحیفہ رضی اللہ عنہ نے بیان کیا، میں اپنے چچا کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس تھا جبکہ آپ صلی اللہ علیہ وسلم خطبہ ارشاد فرما رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کا معاملہ درست رہے گا حتی کہ بارہ خلیفے گزر جائیں گے۔ آپ صلی اللہ علیہ وسلم نے آواز پست کی تو میں نے اپنے چا سے کہا وہ مجھ سے آگے تھے چا جان! آپ نے کیا فرمایا ہے؟ انہوں نے کہا آپ صلی اللہ علیہ وسلم نے فرمایا ہے: وہ سب۔ قریش سے ہوں گے۔“ اس حدیث کو عون بن ابی جحیفہ سے صرف یونس بن ابی یعفور نے روایت کیا، ابو جیفہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ ٦٢١٢","",{"k":"مجمع الزوائد (٥/١٩٠)، اسناده صحيح۔"}],[6212,"سیدنا عمرو بن شعیب نے اپنے والد سے، انہوں نے اپنے دادا سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ” جب تک حدود کا معاملہ تمہارے درمیان رہے تو (حدود سے ) درگزر کرو۔ پس جو مجھ تک پہنچ جائے تو پھر واجب ہوگئی۔ اس حدیث کو ابن جریج سے صرف اسماعیل بن عیاش نے روایت کیا ہے۔","",{"k":"سنن ابو داود، ما لم تبلغ السلطان (٤٣٧٦)، سنن نسائی، قال الشيخ الالباني: صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حدود کا مقدمہ اگر قاضی یا حاکم تک نہ پہنچا ہو تو معاف کیا جا سکتا ہے۔ خود یا اس کو دیکھنے والے گواہوں پر واجب نہیں کہ یہ معاملہ قاضی تک پہنچائیں۔ اگر معاملہ قابل ستر اور قابل معافی ہو تو اس سے درگزر کرنا اور اس پر پردہ پوشی کرنا بہتر ہے۔ جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کسی مسلمان پر پردہ ڈالا، اللہ تعالیٰ روز قیامت اس پر پردہ ڈال دے گا۔ (بخاری، رقم: ٢٤٤٢۔ مسلم، رقم: ٢٥٨٠) لیکن جب معاملہ حاکم کے پاس پہنچ جائے تو مدعی معاف بھی کر دے تو حد ساقط نہیں ہوگی۔ رسول اللہ علیہ نے ایک چور کا ہاتھ کاٹنے کا حکم دیا تو جس کی چوری ہوئی تھی اس نے کہا: میں نے یہ چیز اسے ہبہ کر دی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اسے میرے پاس لانے سے پہلے ایسا کیوں نہ کیا۔ (ابو داؤد، رقم: ٤٣٩٤، ابن ماجه، رقم: ٢٥٩٥، ارواء الغليل، رقم: ٢٣١٧) شیخ الالبانی نے اسے صحیح کہا ہے امام ابو حنیفہ اللہ کا موقف یہ ہے کہ حاکم کے پاس معاملہ پہنچنے کے بعد بھی معاف کر دینے کی وجہ سے حد ساقط ہو جائے گی۔ (المبسوط: ١٨٦/٩) امام شوکانی براللہ فرماتے ہیں: کہ مذکورہ: بالا حدیث اس (ابو حنیفہ جماللہ کے موقف ) کاردکرتی ہے۔ (نیل الاوطار: ٥٨٢/٤)"}],[6213,"سیدنا ابوخلدہ نے بیان کیا، میں نے میمون الکردی سے سنا ہے ہم مالک بن دینار کے پاس تھے کہ مالک بن دینار نے ان سے کہا: الشیخ کو کیا ہے کہ وہ اپنے والد سے حدیث بیان نہیں کرتا؟ کیونکہ آپ کے والد کی تو نبی صلی اللہ علیہ وسلم سے ملاقات ثابت ہے اور انہوں نے آپ سے سماعت کی ہے۔ انہوں نے کہا: میرے والد نبی صلی اللہ علیہ وسلم سے اس اندیشے کے پیش نظر ہمیں حدیث بیان نہیں کرتے تھے کہ کہیں کمی بیشی نہ ہو جائے۔ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو شخص مجھ پر عمداً جھوٹ بولتا ہے وہ اپنا ٹھکانا جہنم میں بنالے۔ لیکن میں تمہیں آپ سے ایک حدیث بیان کرتا ہوں جسے میں نے ان سے ایک، دو اور تین بار نہیں بلکہ اس سے بھی زیادہ مرتبہ بیان کرتے ہوئے سنا ہے۔ میں نے رسول اللہ علیم کو فرماتے ہوئے سنا: جو آدمی کسی عورت سے شادی کرتا ہے، وہ جس دن اس سے شادی کرتا ہے اس دن سے یہ نیت کر لیتا ہے کہ وہ اس کا حق مہر اسے ادا نہیں کرے گا تو وہ اللہ عزوجل سے قیامت کے دن اس حال میں ملاقات کرے گا کہ وہ زانی ہو گا اور جو شخص قرض لیتا ہے اور وہ اسے ادا نہیں کرنا چاہتا اور وہ اسے ادا کیے بغیر ہی فوت ہو جاتا ہے تو وہ اللہ تبارک و تعالیٰ سے اس حال میں ملاقات کرے گا کہ وہ چور ہو گا۔ اس حدیث کو ابوخلدہ سے صرف ابوسعید موسی بن ہاشم نے روایت کیا، ابو میمون الکردی سے صرف اس اسناد سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ عورت کو حق مہر ادا کرنا واجب ہے۔ ارشاد باری تعالیٰ بھی ہے: فَمَا اسْتَمْتَعْتُم بِهِ مِنْهُنَّ فَأْتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً ﴾ (النساء: ٢٤) جن عورتوں سے تم ( شرعی نکاح کے بعد )","",{"k":"مجمع الزوائد (١/١٥١)، صحیح ترغیب و ترهیب (١٨٠٧)۔","f":"اٹھاؤ، انہیں ان کا مقررہ مہر ادا کرو۔“ تو مذکورہ بالا حدیث سے معلوم ہوتا ہے کہ جو حق مہر ادا نہ کرنے کی نیت کرتا ہے تو ایسے آدمی پر دنیا میں زانی کی حد نہیں لگے گی لیکن اسے قیامت کے دن سزا ملے گی۔ (٢) اسی طرح معلوم ہوا کہ جو قرض لے، واپسی کی نیت نہ ہو تو وہ چور ہے، لیکن قانونی طور پر چوری کی حد نہیں لگے گی لیکن قیامت کے دن سزا ضرور ملے گی، کیونکہ مذکورہ بالا دونوں چیزوں کا تعلق نیت کے ساتھ ہے اور اللہ تعالیٰ دلوں کے حالات کو جانتا ہے، اس لیے مسلمان کو چاہیے کہ وہ کسی کو دھوکہ نہ دے، ممکن ہے انسان کو دھوکہ دے لے لیکن اللہ ذوالجلال کو نہیں دے سکتا۔ ٦٢١٤"}],[6214,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے سلیم نے فرمایا: ”اس اثنا میں کہ میں بیٹھا ہوا تھا کہ سیدنا جبریل علی نام آئے تو انہوں نے میرے کندھوں کے درمیان گھونسا مارا۔ میں ایک درخت کی طرف گیا، اس میں پرندے کے دو گھونسلے تھے، پس ان میں سے ایک میں وہ بیٹھ گئے اور میں دوسرے میں بیٹھ گیا، پس وہ اٹھنا اور بلند ہونا شروع ہوا حتی کہ جب دونوں کناروں پر پہنچ گیا اور میں اتنا قریب تھا کہ اگر میں آسمان کو ہاتھ لگانا چاہتا تو لگا لیتا۔ پس میں نے جبریل عالی سلام کو دیکھا گویا کہ وہ ٹاٹ ہوں، زمین کے ساتھ لگے ہوئے۔ پس میں نے اللہ کے متعلق علم کے بارے میں انہیں مجھ پر جو فضیلت حاصل ہے وہ میں نے پہچان لی، میرے لیے آسمان کا ایک دروازہ کھولا گیا تو میں نے نور اعظم دیکھا، میرے سامنے موتیوں اور یاقوت کا ریشمی پردہ حائل کر دیا گیا۔ پس اللہ نے جو چاہا میری طرف وحی فرمائی۔ اس حدیث کو ابو عمران الجونی سے صرف حارث نے روایت کیا۔","",{"k":"١٠٠: سلسله ضعيفه (٥٤٤٤)، شعب الايمان (١٥٥)۔"}],[6215,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”دو کام ایسے ہیں کہ جو مسلمان شخص رات اور دن میں ان کی پابندی کرتا ہے اللہ اسے جنت میں داخل فرمائے گا، وہ بہت آسان ہیں لیکن ان کی پابندی کرنے والے قلیل ہیں۔“ انہوں نے عرض کیا: اللہ کے رسول! وہ دو کام کیا ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” بندے کا ہر نماز کے بعد دس بارسبحان اللہ کہنا، دس بار الحمد منجم اوسط طبرانی ٢ للہ کہنا اور دس بار لا الہ الا اللہ پڑھنا، وہ پانچوں نمازوں میں ایک سو پچاس ہیں جبکہ اللہ کے ہاں ایک ہزار پانچ سو ہیں۔ وہ تینتیس بارسبحان اللہ کہے، تینتیس بار الحمد للہ کہے اور چونتیس بار اللہ اکبر کہے، پس یہ سو ہوا، وہ اللہ کے ہاں ہزار نیکی ہے، پس یہ اڑھائی ہزار نیکیاں ہوئیں۔ انہوں نے عرض کیا: اللہ کے رسول! ہمیں کیا ہے کہ ہم اس کی پابندی نہ کریں؟ آپ نے فرمایا: ”جب تم میں سے کوئی نماز پڑھ لیتا ہے تو شیطان اس کے پاس آتا ہے اور اسے اس کے کام کاج یاد کراتا ہے تو وہ انہیں پڑھنے سے پہلے ہی کھڑا ہو جاتا ہے، پس جب وہ اپنے بستر پر آتا ہے تو وہ اسے اس عمل سے غافل کر دیتا ہے حتی کہ وہ سو جاتا ہے۔ اس حدیث کو زیاد بن سعد سے صرف زمعہ نے روایت کیا۔ اس میں ابوقرہ کا تفرد ہے۔ نا سنن ابی داؤد میں ہے کہ عشرا ويكبر ويهلل عشرا تمیں کی جگہ پر دس بار بھی کہنا درست ہے۔ اسی طرح پیچھے حدیث گزر چکی ہے۔ تینتیں، تینتیں بار سبحان الله، الحمد لله اور چونتیس مرتبہ اللہ اکبر کہنا بھی درست ہے۔ زیادہ سے زیادہ نیکیاں کرنے کی کوشش کرنی چاہیے۔ لیکن اگر زیادہ نہیں تو اس کا مطلب یہ نہیں کہ تھوڑی نیکی بھی نہ کی جائے، بلکہ جتنی اللہ ذوالجلال نے توفیق دی ہے کریں لیکن ہمیشہ اس نیکی کو کرنے کی کوشش کرنی چاہیے۔ فرمایا کہ یہ ایک سو پچاس (١٥٠) کلمات ہیں، مطلب یہ ہے کہ یہ تمیں کلمات پانچوں فرض نمازوں کے بعد کہے جائیں گے تو ایک سو پچاس کا مجموعہ ہوگا اور ایک نیکی کا ثواب دس گنا ملے گا۔ جیسا کہ ارشاد باری تعالیٰ ہے:- مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا﴾ (الانعام: ١٦٠) جو شخص نیکی کا کام کرے گا، اس کو دس گنا ( ثواب ) ملے گا۔“ (٢) سنن ابی داؤد کی روایت میں ہے: ((اذا أوى الى فَرْشِه)) ” جب اپنے بستر پر جائے تو “ سبحان الله ٣٣ مرتبه، الحمد لله ٣٣ مرتبه الله اکبر ٣٤ مرتبہ کہے۔ صحیح بخاری ومسلم میں ہے کہ یہ عمل نبی معظم ماے علی تم نے اپنی بیٹی سیدۃ النساء الجنہ فاطمہ الزہرہ نیا نیا کو بتایا۔ (دیکھئے: صحیح بخاری، رقم: ٥٢٦٢، مسلم، رقم: ٢٧٢٧)، اہل علم فرماتے ہیں: اس وظیفے کو پڑھنے سے جسمانی قوت ملتی ہے، صحت اور ہمت ملتی ہے۔ علامہ ابن قیم اللہ فرماتے ہیں کہ ذکر اس کے عامل (ذاکر ) کو وہ قوت بخشتا ہے کہ وہ ذکر کی وجہ سے ایسے کام کر جاتا ہے جو کہ ذکر کے بغیر نہیں کر سکتا۔","",{"k":"سنن ابو داود (٥٠٦٥)، سنن ترمذی (٣٤١٠)۔"}],[6216,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم کے دور میں اس (سورت ) کو المانعہ کا نام دیتے تھے، وہ اللہ عزوجل کی کتاب میں ایک سورت ہے، پس جو ہر رات اسے پڑھتا ہے تو وہ بہت بہتر رہتا ہے، یعنی: سورۃ الملک اس حدیث کو سہیل بن ابی صالح سے صرف ابن ابی حازم نے روایت کیا۔ ممکن ہے کہ اس کو سورہ مانعہ اس لیے کہتے ہوں کہ سورہ ملک کی رات کو روزانہ تلاوت کرنے والا، عذاب قبر سے محفوظ رہے گا، جیسا کہ سیدنا عبد اللہ بن مسعود بنی اہلیہ کہتے ہیں: ((سورة تبرك هي المانعة من عذاب القبر )) (سلسله صحیحه، رقم: ١١٤٠) سورہ ملک عذاب قبر سے رکاوٹ ہے۔“ ٢١٧","",{"k":"مجمع الزوائد ١٢٧/٧، مجمع البحرين (٣٤٠٦)، صحیح ترغیب و ترهيب (٢/٩١)، اسناده حسن . فائده۔"}],[6217,"سیدنا عبداللہ ابن عباس یا اینجا نے بیان کیا، بنو فزارہ میں سے کسی آدمی نے اس آدمی کے بارے میں جس کی سیدنا موسی علینا نے اتباع کی، مجھ سے بحث کی۔ اس کا بیان ہے کہ میں نے کہا: وہ خضر عالی نام ہیں۔ الفزاری نے کہا: وہ کوئی اور آدمی ہیں۔ پس اُبی بن کعب رضا اللہ ہمارے پیارے سے گزرے۔ سیدنا عبداللہ ابن عباس نئی اینجا نے فرمایا: ”میں نے انہیں بلایا تو میں نے ان سے سوال کیا، کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو اس شخص کا تذکرہ کرتے ہوئے سنا ہے جس کے پیچھے موسی علینام گئے تھے؟ انہوں نے کہا: ہاں میں نے رسول اللہ علم کو فرماتے ہوئے سنا کہ موسی علی نام بنی اسرائیل کی جماعت میں تشریف فرما تھے تو کسی آدمی نے ان سے کہا: اللہ کے بارے میں آپ کا گینڈا سے زیادہ کوئی علم رکھتا ہے؟ انہوں نے فرمایا: ” میں کسی کو نہیں جانتا؟ فرمایا: اللہ نے ان پر عتاب فرمایا، جب انہوں نے اس معاملے کو اللہ تعالیٰ کے سپرد نہیں کیا، پس اللہ تعالیٰ نے وحی فرمائی: نہیں، بلکہ میرا بندہ خضر ہے۔ پس انہوں نے ان تک پہنچنے کا راستہ معلوم کیا؟ تو اللہ تعالیٰ نے مچھلی کو ان کے لیے نشانی بنا دیا کہ جب وہ اسے نہ پائیں (تو وہ اسی جگہ ہیں) اللہ تعالیٰ نے جو قصہ بیان فرمایا یہ ان کی شان سے ہے۔“ اس حدیث کو جعفر بن محمد سے صرف مسلم بن خالد اور عبد اللہ بن میمون القداح نے روایت کیا۔ اندن مذکورہ حدیث سے معلوم ہوا کہ جب کسی سے پوچھا جائے کہ بڑا عالم کون ہے تو اس کو یہ نہیں کہنا چاہیے کہ میں بڑا ہوں، بلکہ بہتر ہے کہ اللہ کے حوالے کر دے یعنی یہ کہہ دے کہ اللہ ذوالجلال سب سے زیادہ علم رکھتا ہے، یا یہ کہہ دے کہ اللہ ہی جانتا ہے کہ کون سب سے بڑا عالم ہے، حضرت خضر، نبی ہوں یا ولی مگر سیدنا موسی مینا سے افضل نہیں ہو سکتے،مگر سیدنا موسی علی نام کا یہ کہنا کہ میں سب سے زیادہ علم والا ہوں، اللہ تعالیٰ کو نا گوار ہوا اور ان کا مقابلہ ایسے بندے سے کرایا جو ان سے درجہ میں کم تھے۔","",{"k":"صحیح بخاری کتاب العلم باب ما ذكر في ذهاب موسى . الخ (٧٤)، صحيح مسلم (٢٣٨٠)۔"}],[6218,"فی سے علم کی زوجہ محترمہ سیدہ ام سلمہ نیلی اینجا نے رسول اللہ علیم سے روایت کیا کہ آپ صلی اللہ علیہ وسلم ان کلمات سے دعا کیا کرتے تھے: ”اے اللہ! تو اول ہے تجھ سے پہلے کوئی چیز نہیں تو آخر ہے تیرے بعد کوئی چیز نہیں ہوگی، میں ہر جان کے شر سے تیری پناہ چاہتا ہوں جس کی پیشانی تیرے ہاتھ میں ہے، میں گناہ، کسل مندی، عذاب قبر، تو نگری کے فتنے اور فقر کے فتنے سے تیری پناہ چاہتا ہوں اور میں گناہ وقرض سے تیری پناہ چاہتا ہوں۔ اے اللہ! میرے دل کو گناہوں سے پاک کر دے، جس طرح تو نے سفید کپڑے کو میل سے پاک صاف کر دیا۔ اے اللہ! میرے اور میرے گناہوں کے درمیان دوری پیدا کر دے، جس طرح تو نے مشرق و مغرب کے درمیان دوری پیدا کر دی۔ یہ وہ ہے جس کا محمد صلی اللہ علیہ وسلم نے اپنے رب سے سوال کیا: ”اے اللہ! میں تجھ سے بہتر مسئلہ، بہتر دعا، بہتر کامیابی، بہتر عمل، بہتر ثواب، اور بہتر جینے اور بہتر مرنے کی درخواست کرتا ہوں، مجھے دین پر ثابت رکھ، میرے ترازو کو وزنی بنا، میرے درجات بلند فرما، میری نماز قبول فرما، میری خطائیں معاف فرما، میں تجھ سے جنت کے بلند درجات کا سوال کرتا ہوں، آمین۔ اے اللہ! میں تجھ سے جنت کا Bes سوال کرتا ہوں، آمین۔ اے اللہ! جو فعل و عمل کیا گیا اس کی بھلائی، باطن و ظاہر کی بھلائی اور جنت کے بلند درجات کا میں تجھ سے سوال کرتا ہوں، آمین۔ اے اللہ! میں تجھ سے سوال کرتا ہوں کہ تو میرا ذکر بلند کر دے، میرا بوجھ اتار دے، میرا معاملہ درست کر دے، میرے دل کو پاک کر دے اور میری شرم گاہ کی حفاظت فرما، میرے دل کومنور فرما، میرے گناہ معاف فرما، میں تجھ سے جنت کے بلند درجات کا سوال کرتا ہوں، آمین۔ اے اللہ! مجھے جہنم کی آگ سے بچا۔ “ محمد بن زنبور کی روایت کے الفاظ ہیں۔","",{"k":"مجمع الزوائد (١٠/١٧٧)، مجمع البحرين رقم ٤٦٧٦ عاصم بن ابی عبید سے امام بخاری رحمہ اللہ اور ابن ابی حاتم رحمہ اللہ نے سکوت فرمایا ہے۔۔"}],[6219,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”خیر وبھلائی کے معلم کے لیے ہر چیز مغفرت طلب کرتی ہے حتی کہ سمندروں کی مچھلیاں بھی۔“ اس حدیث کو اعمش سے صرف ابو اسحاق الفزاری نے روایت کیا۔ مذکورہ حدیث سے دین کے معلم کی فضیلت کا اثبات ہوتا ہے جو قرآن وحدیث کا علم سکھاتا ہے کہ زمین و آسمان کی ہر چیز اس خوش نصیب کے لیے دعا کرتی ہے، فرشتے، چیونٹیاں، مچھلیاں اور دیگر مخلوقات۔ سیدنا ابو امامہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے دو آدمیوں کا ذکر کیا گیا: ان میں سے ایک عالم اور دوسرا عابد تھا۔ آپ سے یہ نے ارشاد فرمایا: عالم کو عابد پر ایسی فضیلت حاصل ہے جیسی مجھے تم میں سے کسی عام آدمی پر حاصل ہے۔ پھر ارشاد فرمایا: بے شک اللہ ذوالجلال لوگوں کو بھلائی کی تعلیم دینے والوں پر اپنی رحمت نازل فرماتا ہے اور فرشتے ان کے لیے رحمت کی دعا کرتے ہیں، نیز زمین و آسمان کی ساری مخلوق حتی کہ اپنی بلوں میں چیونٹیاں اور ( پانی میں ) مچھلیاں تک ان کے لیے رحمت کی دعا کرتی ہیں۔ (ترمذی: ابواب العلم، باب فی فضل الفقه على العبادة، اسناده صحیح) اور یہ مقام اللہ ذوالجلال دین کے علم کو سیکھنے والے کو بھی عطا کرتے ہیں۔","",{"k":"صحیح ترغیب و ترهيب (٨٢)، مجمع الزوائد (١/١٢٤)، مجمع البحرين (٢٠٣)، سلسله صحيحه (٣٠٢٤)۔"}],[6220,"سیدنا ابو ذر رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو موزوں اور عمامے پر مسح کرتے ہوئے دیکھا۔“ اس حدیث کو ہشام بن حسان سے صرف مخلد بن الحسین نے روایت کیا۔ اس میں المسیب بن واضح کا تفرد ہے۔: ٦٢٢١ موزوں اور عمامے پر مسح کرنا جائز ہے۔","",{"k":"نصب رايه (١/١٨٤)۔"}],[6221,"سیدنا ابو سہلہ السائب بن خلاد سے روایت ہے کہ ایک آدمی نے کچھ لوگوں کی امامت کی تو اس نے قبلے کی جانب تھوک دیا، جبکہ رسول اللہ صلی اللہ علیہ وسلم دیکھ رہے تھے، وہ جس وقت فارغ ہوا تو رسول اللہ تم نے فرمایا: یہ شخص تمہیں نماز نہ پڑھائے۔ پس اس نے اس کے بعد انہیں نماز پڑھانے کا ارادہ کیا تو انہوں نے اسے روک دیا اور اسے رسول اللہ صلی اللہ علیہ وسلم کے فرمان کے متعلق بتایا، اس نے رسول اللہ صلی اللہ علیہ وسلم سے اس کا تذکرہ کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”انہوں نے جو کیا اچھا کیا۔ میرا خیال ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ” تو نے اللہ کو اذیت پہنچائی۔ یا اس طرح کی بات فرمائی۔ یہ حدیث نبی صلی اللہ علیہ وسلم سے صرف اس اسناد سے مجم اوسط طبرانیم و مروی ہے۔ اس میں عمرو بن الحارث کا تفرد ہے۔ مذکورہ حدیث سے (١) معلوم ہوا کہ نماز کے دوران قبلہ کی طرف تھوکنا ادب کے منافی ہے ایک دوسری حدیث میں ہے کہ طارق بن عبد اللہ فرماتے ہیں کہ نبی معظم ماے علی تم نے فرمایا ” جب تو نماز پڑھ رہا ہو تو اپنے سامنے تھوکنا نہ دائیں طرف تھوکنا، البتہ بائیں طرف یا قدم کے نیچے تھوک سکتے ہو۔ (ابوداؤد، رقم: ٤٧٨) (٢) یہ بھی معلوم ہوا کہ شریعت کے بیان کردہ آداب و حدود کی خلاف ورزی اللہ اور اس کے رسول ے یمن کو ایذا دینا ہے۔ (٣) معلوم ہوا کہ امام خلاف شرعیت کام کرے تو اس کو امامت سے ہٹا دینا چاہیے۔ ٦٢٢٢","",{"k":"سنن ابو داود كتاب الصلاة (٤٨١)، قال الشيخ الالباني: حسن۔"}],[6222,"سیدنا ابو ہریرہ ضیا علینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے حکم دیا گیا ہے کہ میں لوگوں سے قتال کروں حتی کہ وہ لا الہ الا اللہ کا اقرار کر لیں، پس جب وہ لا الہ الا اللہ کا اقرار کر لیں تو انہوں نے حق اسلام کے علاوہ اپنے اموال اور اپنی جانیں مجھ سے محفوظ کر لیں جبکہ ان کا حساب اللہ کے ذمے ہے۔“ ٦٢٢٣","",{"k":"صحیح بخاری (١٣٩٩)، صحيح مسلم، رقم: ٢٠. ووه۔"}],[6223,"سیدنا ابو ہریرہ ولی الیہ نے بیان کیا، رسول اللہ صلے علی کیم نے فرمایا: ”ہم نے سانپوں سے جب سے دشمنی کی ہے، تب سے ہم نے ان سے صلح نہیں کی، پس جو شخص ان میں سے کسی کو دیکھے تو اسے مار ڈالے، کیونکہ ان میں سے جو مسلمان ہے وہ تمہارے سامنے نہیں آئے گا اور جس نے ان میں سے کسی کو ڈر کی وجہ RSS مو سے چھوڑ دیا تو وہ مجھ سے نہیں۔“ اند مذکورہ حدیث سے معلوم ہوا کہ سانپ سے ڈرنا نہیں چاہیے بلکہ اس کو مار دینا چاہیے۔ اسی طرح اس کے بدلے سے بھی نہیں ڈرنا چاہیے۔","",{"k":"مجمع الزوائد (٤/٤٧)، سنن ابو داود (٥٢٤٨)۔"}],[6224,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تم میرے نام اور میری کنیت کو اکٹھا نہ کرو، میں ابو القاسم ہوں، اللہ مجھے عطا کرتا ہے اور میں تقسیم کرنے والا ہوں","",{"k":"صحیح بخاری (٣٥٣٩، ١٠٤٩، ٢٥٤، ٦٠٠١٦٢٢٥)۔"}],[6225,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے ہیم نے فرمایا: ” جو شخص دس افراد کا بھی امیر ہو گا اسے قیامت کے دن اس حال میں لایا جائے گا کہ اس کی گردن میں طوق ہو گا، حتی کہ عدل اسے آزادی دلائے گا، یا ظلم اسے ہلاک کر دے گا۔“: الله","",{"k":"مجمع الزوائد (٥/٢٠٥)۔"}],[6226,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے بالشت برابر زمین نا حق حاصل کی اسے قیامت کے دن سات زمینوں کا طوق پہنایا جائے گا۔“","",{"k":"مجمع الزوائد (٤/١٧٥)۔"}],[6227,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: \"اگر کوئی شخص تمہارے گھر میں جھانکتا ہے اور تم کنکری سے اس کی آنکھیں پھوڑ دیتے ہو تو تم پر کوئی گناہ نہیں۔‘ ان احادیث کو عبد اللہ بن محمد بن عجلان سے صرف ابراہیم بن المنذ رالحزامی نے روایت کیا۔ .. مذکورہ حدیث سے معلوم ہوا کہ کسی کے گھر میں بغیر اجازت کے جھانکنا حرام اور انتہائی بداخلاقی ہے۔ صاحب گھر کو حق حاصل ہے کہ اگر کوئی بغیر اجازت اندر دیکھے تو وہ اس کی آنکھ پھوڑ دے۔ ذراغور کیجئے! اگر ظالم کسی کی ایک آنکھ نکال دے تو اس سے قصاص لیا جائے گا اور قصاص میں اس کی آنکھ نکال دی جائے گی یا اس سے پچاس اونٹ دیت وصول کی جائے گی، لیکن اگر یہی آنکھ دیانت وامانت کا مظاہرہ نہیں کرتی،کسی کے گھر میں داخل ہو جاتی ہے تو اس کی قدر و منزلت ختم ہو جاتی ہے، اسلام معاشرے کو امن وسکون اور امانت و دیانت کا گہوارہ بناتا ہے۔گھر تو بنایا ہی اس لیے جاتا ہے کہ اہل خانہ کی جان و مال اور عزت اس میں محفوظ رہے، اگر کوئی باہر سے گھر کے اندر کا نظارہ کرتا ہے اور پردہ نشین عورتوں کے لیے پریشانی کا موجب بنتا ہے تو اسلام اس آنکھ کی ضمانت نہیں دیتا۔ شریعت نے یہ ادب سکھایا ہے کہ جب انسان دروازے پر دستک دے تو اس کا ادب یہ ہے کہ ایک جانب کھڑا ہو۔ ٦٢٢٨","",{"k":"کی صحیح بخاری کتاب الديات (٦٨٨٨)، مسلم (٢١٥٨/٤٤)، ادب (١٠٦٨)، سنن ابو داود (٥١٧٢)۔"}],[6228,"سیدہ عائشہ بی جا نے فرمایا: رسول اللہ نے یمن کی چار پائی سخت قسم کی چھال سے بنی ہوئی تھی، آپ صلی اللہ علیہ وسلم پر کالی کملی تھی، پس ہم نے آپ صلی اللہ علیہ وسلم کو اس سخت قسم کی چھال سے بنی ہوئی چار پائی، چٹائی پر بٹھا دیا، سیدنا ابو بکر وعمر یہی تھا آپ صلی اللہ علیہ وسلم کے پاس آئے، جبکہ نبی صلی اللہ علیہ وسلم اس پر بیٹھے ہوئے تھے، ان دونوں نے دیکھا تو انہوں نے اس چار پائی کے آثار رسول اللہ صلی اللہ علیہ وسلم کے پہلو پر دیکھے تو سیدنا ابو بکر و عمر نا پہنچا رو پڑے۔ رسول اللہ میم نے ان دونوں سے فرمایا: ”تم کیوں روتے ہو؟ انہوں نے عرض کیا: ہم اس لیے روتے ہیں کہ یہ جو چار پائی ہے اس کی سختی اور کھردرے پن نے آپ صلی اللہ علیہ وسلم کے پہلو پر نشان ڈال دیے ہیں، بلکہ کسری و قیصر ریشمی بچھونوں پر ہیں۔ رسول اللہ سلم نے فرمایا: کسری و قیصر کا انجام جہنم ہے، جبکہ میری اس چارپائی کا انجام جنت ہے۔ اس حدیث کو لیث سے صرف عبد العزیز بن بیٹی نے روایت کیا۔ ٦٢٩","",{"k":"ضعيف . مجمع الزوائد (١٠/٣٢٧)، ضعیف ترغیب و ترهیب (١٩١٣)، اسناده۔"}],[6229,"سیدہ عقیلہ بنت عبید بن الحارث بنایا نہ جا نے بیان کیا، میں اور میری والدہ قریرہ بنت الحارث العتوار یہ مہاجر خواتین کے ساتھ آئیں تو ہم نے رسول اللہ ملے ان کی بیعت کی، جبکہ آپ صلی اللہ علیہ وسلم ابطح میں ایک خیمہ لگائے ہوئے تھے۔ آپ صلی اللہ علیہ وسلم نے ہم سے عہد لیا کہ ہم اللہ کے ساتھ کسی کو شریک نہیں ٹھہرائیں گی پوری آیت پس جب ہم نے اقرار کر لیا اور ہم نے ہاتھ بڑھائے تا کہ ہم آپ ملنے کی بیعت یں تو نبی لئے علیم نے فرمایا: میں عورتوں کے ہاتھوں کو ہاتھ نہیں لگاتا۔ پس آپ صلی اللہ علیہ وسلم نے ہمارے لیے مغفرت کی دعا کی اور یہ ہماری بیعت تھی۔“ یہ حدیث عقیلہ بنت عبید سے صرف اس اسناد سے مروی ہے۔ اس میں بکار ا بن عبد اللہ الر بزی کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ اس میں موسی بن عبيدة ابذی، ضعیف ہے۔ تاہم نبی مکرم اے علی تم اپنے صحابہ کرام اور صحابیات بھی انہم سے بیعت لیا کرتے تھے۔","",{"k":"کر الزوائد (٣٩/٦)، مجمع، اسناده ضعيف۔"}],[6230,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی لئے علیم سے عرفہ کے دن اس عبداللہ صلے یعنی: رجب کے مہینے میں اللہ کے نام پر جانور ذبح کرنے کے متعلق سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ حق ہے۔“ اس حدیث کو زید بن اسلم سے صرف سفیان نے اور سفیان سے صرف محمد بن ابی عمر العدنی نے روایت کیا۔ اندن زمانہ جاہلیت میں، لوگ ذوالقعدہ، ذوالحجہ، محرم اور رجب، ان چار مہینوں کی حرمت کا خیال رکھتے تھے اور آپس کی جنگ اور لڑائی کو ان میں روک دیا کرتے تھے۔ عربی زبان میں لفظ رجب کا معنی تعظیم ہے اور اس مہینے کو اسی لیے رجب کہا گیا ہے کہ عرب لوگ اس کی تعظیم کرتے تھے اور اس میں بتوں کے نام پر جانور ذبح کرتے تھے اور اس رسم کو عتیرہ کا نام دیتے تھے، جب اسلام آیا تو اس نے بھی ان حرمت والے مہینوں ٢٩ قم ٢ کے احترام و تقدس کو برقرار رکھا اور ان سے لڑائی کو کبیرہ گناہ قرار دیا، لیکن جو لوگ غیر اللہ کے نام پر رجب کے مہینے میں ذبح کرتے، شریعت نے اس رسم کو ختم کر دیا۔ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((لا فَرْعَ وَلَا عَتيره )) (بخاری، رقم: مسلم، رقم: ١٩٧٦) اسلام میں فرع ہے نہ عتیرہ ہے۔ لیکن مذکورہ بالا روایت میں رخصت ہے۔ (١) تو یہ ہے کہ ابتدائے اسلام میں فرع اور عتیرہ پر عمل ہوتا تھا کہ کفار غیر اللہ کے نام پر ذبح کرتے تھے اور مسلمان اللہ کے نام پر مگر بعد میں جب قربانی کا حکم ہوا تو انہیں منسوخ کر دیا گیا۔ (٢) جو جواز کی حدیثیں ہیں وہ اس بات کا تقاضا کرتی ہیں کہ یہ جانور بتوں کے نام پر ذبح نہ کئے جائیں، البتہ اللہ کی رضا کے لیے ان کا ذبح کرنا مستحب ہے اور نبی کی احادیث سے معلوم ہوا کہ ذبح کرنا واجب نہیں ہے۔ (٣) صدقہ خیرات، اللہ ذوالجلال کے نام پر ذبح کرنا ہر وقت ہر مہینے میں جائز ہے، لیکن ذی الحجہ کے علاوہ کسی اور مہینے کی قید لگا کر قربانی کرنا تو اس کام کی اسلام میں کوئی اجازت نہیں ہے۔ قربانی کے علاوہ مخصوص کر کے کسی مہینے میں جانور ذبح کرنا جائز نہیں","",{"k":"مجمع الزوائد (٢٩/٤)، اسناده صحيح . فائدة۔"}],[6231,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے کسی غلام کو اس کے آقا، مالک کے خلاف بھڑ کا یا۔“ یحیی بن سعید سے صرف محمد بن دینار نے روایت کیا۔ اس میں محمد ابن معاویہ کا تفرد ہے۔","",{"k":"سنن ابو داود كتاب الطلاق (٢١٧٥)۔"}],[6232,"سیدنا عمار بن یاسر رضی اللہ عنہ بیان کرتے ہیں: سیدنا علی بن ابو طالب یا اللہ نفل نماز میں رکوع کی حالت میں تھے کہ کسی سوالی نے ان سے سوال کر دیا تو انہوں نے اپنی انگوٹھی اتار کر سوال کرنے والے کو دے دی۔ پس وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس کے متعلق آپ صلی اللہ علیہ وسلم کو بتایا تو نبی ملنے کی تم پر یہ آیت نازل ہوئی: ”اللہ، اس کے رسول اور وہ مومن تمہارے ولی ہیں جو نماز پڑھتے ہیں، زکوۃ دیتے ہیں جبکہ وہ حالت رکوع میں ہوتے ہیں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اس کی قراءت کی، پھر فرمایا: ”جس کا میں مولا ہوں تو علی اس کے مولا ہیں۔ اے اللہ! جو اس سے دوستی و محبت رکھتا ہے تو اس سے دوستی رکھ اور جو اس سے دشمنی رکھتا ہے تو اس سے دشمنی رکھ۔“ یہ حدیث سیدنا عمار بن یاسر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں خالد بن یزید کا تفرد ہے۔","",{"k":"مجمع الزوائد، میزان الاعتدال (١٢/٦٤٦)، اسناده ضعيف۔"}],[6233,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تقدیر کے بارے میں اس امت کے شریر لوگوں کے لیے کلام کو مؤخر کر دیا گیا۔ اس حدیث کو ہشام بن حسان کے حوالے سے محمد بن سیرین سے صرف عمر بن ابی خلیفہ نے روایت کیا۔ اس میں محمد بن بکار العیشی کا تفرد ہے۔ RSS","",{"k":"مستدرك حاكم (٢/٤٧٣)، ظلال الجنة (٣٥٠)، سلسله صحيحه (١١٢)، اسناده حسن۔"}],[6234,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب شام کا کھانا آجائے اور نماز کے لیے اقامت ہو جائے تو پہلے کھانا کھاؤ۔ اس حدیث کو معمر سے صرف ابن المبارک نے روایت کیا۔ ٦٢٣٥","",{"k":"صحیح بخاری (٤٦٣)، مسلم (٥٧)۔"}],[6235,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی علم کو فرماتے ہوئے سنا: ”پھوپھی کا کسی ایسے شخص سے نکاح نہ کیا جائے جس کے نکاح میں اس کی بھتیجی موجود ہو اور خالہ کا کسی ایسے شخص سے نکاح نہ کیا جائے جس کے نکاح میں اس کی بھانجی موجود ہو۔“ اس حدیث کو اسحاق بن جعفر بن محمد سے صرف ابراہیم بن المنذر نے روایت کیا۔","",{"k":"صحیح مسلم (٣٥/١٠٨)، سنن ابو داود (٢٠٦٥)، سنن ترمذی (١١٢٦)۔"}],[6236,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے فرمایا: ”رسول اللہ صلی اللہ علیہ وسلم دوران سفر اپنی سواری پر (نفل) نماز پڑھا کرتے تھے۔ اس حدیث کو ایوب سے صرف الحارث بن عمیر نے روایت کیا۔ اس میں ابراہیم الشامی کا تفرد ہے۔ ٦٢٣٧","",{"k":"صحیح بخاری، رقم: مسلم (٣٣)۔"}],[6237,"سیدنا حارثہ بن وہب الخزاعی رضی اللہ عنہ نے بیان کیا: ہم نے نبی الے علم کے ساتھ منی میں ظہر کی نماز دو رکعتیں پڑھی، حالانکہ لوگ بہت زیادہ تھے اور انتہائی امن کی حالت میں تھے۔“ اس حدیث کو مسعر سے صرف وکیع نے روایت کیا۔ اس میں یعقوب بن حمید کا تفرد ہے۔ ٦٢٣٨","",{"k":"سنن نسائی (١٤٤٦)، قال الشيخ الالباني: صحيح۔"}],[6238,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کو قربانی کا جانور ہانکتے ہوئے دیکھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس پر سوار ہو جائے اس حدیث کو سفیان بن عیینہ سے صرف محمد بن ابی عمر نے روایت کیا۔ اسے مسعر کے حوالے سے مختار بن فلفل سے صرف سفیان نے روایت کیا جبکہ دیگر محدثین نے اسے مسعر کے حوالے سے بکیر بن الاخنس سے روایت کیا ہے۔","",{"k":"صحیح بخاری (١٦٩٠)، صيح مسلم (١٣٢٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قربانی کے جانور پر سواری کرنا جائز ہے۔ اس حدیث سے یہ ثابت ہوتا ہے کہ قربانی کے جانور سے فائدہ اٹھایا جا سکتا ہے۔ مثلاً دودھ دھونا، اون اتارنا وغیرہ ( اللہ اعلم)"}],[6239,"سیدنا بہر بن حکیم نے اپنے والد سے، انہوں نے اس کے دادا سے روایت کیا کہ نبی عالم نے فرمایا: ”تم (قیامت کے دن ) پیش کیے جاؤ گے، تمہارے منہ بند ہوں گے، پس تم میں سے کسی کا ہاتھ اور اس کی ران سب سے پہلے کلام کریں گے۔ اس حدیث کو ہشام بن حسان سے صرف حاتم نے روایت کیا۔ اس میں یعقوب بن حمید کا تفرد ہے۔","",{"k":"معجم طبرانی کبیر (٦/٢٢٠)، مسند احمد (٣/٥)، قال شعیب الارناؤط اسناده حسن۔","f":"ارشاد باری تعالی ہے: شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُمْ بِمَا كَانُوا يَعْمَلُونَ، وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنَا قَالُوْا اَنطَقَنَا اللَّهُ الَّذِي أَنطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَالَيْهِ تُرْجَعُونَ (حم السجده: ٢٠ - ٢١) ان پر ان کے کان اور ان کی آنکھیں اور ان کی کھالیں ان کے اعمال کی گواہی دیں گے، یہ اپنی کھالوں سے کہیں گے کہ تم نے ہمارے خلاف شہادت کیوں دی، وہ جواب دیں گی کہ ہمیں اس اللہ نے قوت گویائی عطا فرمائی جس نے ہر چیز کو بولنے کی طاقت بخشی ہے اسی نے تمہیں اول مرتبہ پیدا کیا اور اسی کی طرف تم سب لوٹائے جاؤ گے۔“ اور فرمایا: وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ اَرْجُلُهُمْ بِمَا كَانُوا يَكْسِبُونَ» (يس: ٦٥) ہم سے ان کے ہاتھ باتیں کریں گے اور ان کے پاؤں گواہیاں دیں گے، ان کاموں کی جو وہ کرتے تھے۔“ معلوم ہوا کہ انسان کے اعضا کو اللہ ذوالجلال قوت گویائی عطا فرما دے گا اور یہ اعضا اس کے خلاف گواہ بن جائیں گے۔"}],[6240,"سیدہ عائشه خیلی تنہا سے روایت ہے کہ نبی صلے علی کیم جب حالت جنابت میں سونے کا ارادہ فرماتے تو آپ صلی اللہ علیہ وسلم نماز کے وضو کی طرح وضو کرتے تھے اور جب آپ صلی اللہ علیہ وسلم کھانا کھانے کا ارادہ فرماتے تو وضو کرتے تھے۔ اس حدیث کو معمر کے حوالے سے قتادہ سے صرف ابن المبارک نے روایت کیا۔ عبد الرزاق نے اسے معمر کے حوالے سے زہری نے روایت کیا۔","",{"k":"صحیح بخاری، يتوضا ثم ينام (٢٨٨)، مسلم (٣٠٥)۔"}],[6241,"سیدنا عبد اللہ بن ہشام رضی اللہ عنہ نے بیان کیا، جب سال یا مہینہ شروع ہوتا تو نبی ملنے ان کے اصحاب بھی ایم اسی دعا کی تعلیم دیا کرتے تھے: اے اللہ! اسے ہم پر امن و ایمان، سلامتی و اسلام، ( اللہ ) رحمن کی رضا مندی اور شیطان سے دوری بنا۔ یہ حدیث عبد اللہ بن ہشام سے صرف اس اسناد سے مروی ہے۔ اس میں رشدین بن ابی سعد کا تفرد ہے۔ ٦٢٤٢","",{"k":"مجمع الزوائد (١٣٩/١٠)، مجمع البحرين (٤٥٩٦)، اسناده ضعيف۔"}],[6242,"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں، رسول اللہ علیم نے فرمایا: ”اسلام غالب آ جائے گا حتی کہ تاجر سمندری سفر کریں گے حتیٰ کہ گھڑ سوار اللہ کی راہ میں مصروف ہوں گے، پھر کچھ لوگ ظاہر ہوں گے وہ قرآن پڑھیں گے، وہ کہیں گے: ہم سے زیادہ پڑھنے والا کون ہے؟ ہم سے زیادہ سمجھ بوجھ رکھنے والا کون ہے؟ ہم سے زیادہ عالم کون ہے؟ پھر آپ نے اپنے اصحاب سے فرمایا: ” کیا ایسے لوگوں میں کوئی خیر و بھلائی ہے؟ انہوں نے عرض کیا: اللہ اور اس کے رسول بہتر جانتے ہیں۔ آپ طلئے علیم نے فرمایا: ”وہ تم ہی سے اس امت کے افراد ہوں گے، وہ جہنم کا ایندھن ہیں۔ اس حدیث کو عبد اللہ بن زید بن اسلم سے صرف خالد بن یزید العمری نے روایت کیا۔:٦٢٤٣","",{"k":"مجمع الزوائد (١/١٨٦)، مسند ابی یعلی (٦٦٩٨)، مجمع البحرين (٣٣١)، اسناده ضعیف۔"}],[6243,"سیدنا محمد بن مسلمہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علی یتیم نے فرمایا: ”تمہارے رب کی طرف سے زندگی میں کچھ فیض آتے رہتے ہیں، پس تم ان کو لو، ہوسکتا ہے کہ تم میں سے کوئی اس فیض کو حاصل کر لے تو پھر اس کے بعد کبھی وہ بدنصیب نہ ہو گا۔“ یہ حدیث محمد بن مسلمہ سے صرف اس اسناد سے مروی ہے، اس میں احمد بن عبدہ کا تفرد ہے۔ ٦٢٤٤","",{"k":"مجمع الزوائد (٢٣١/١٠)۔"}],[6244,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ نے مریم نے سیدنا فضل بن عباس بیانیہ کو حکم فرمایا کہ وہ آپ صلی اللہ علیہ وسلم کے لیے پانی کا انتظام کریں۔ پس رسول اللہ صلی اللہ علیہ وسلم قضائے حاجت کے لیے تشریف لے گئے، جب آپ کو بول و براز کی حاجت ہوتی تھی تو آپ اتنی دور تشریف لے جاتے تھے کہ نظروں سے اوجھل ہو جاتے تھے۔ جب رسول اللہ سے یکم قضائے حاجت سے فارغ ہوئے تو آپ واپس تشریف لاتے ہوئے ایک عورت کے پاس سے گزرے جو اپنی میت کی قبر کے پاس تھی، وہ چیخ و پکار کر رہی تھی۔ رسول اللہ صلی اللہ علیہ وسلم اس کے پاس کھڑے ہو گئے، جبکہ وہ آپ ملے سلیم کو پہچانتی نہیں تھی، آپ سے ہم نے اسے فرمایا: ”اللہ سے ڈر اور صبر کر۔ اس نے کہا: اللہ کے بندے جا اپنا کام کر، آپ صلی اللہ علیہ وسلم نے اسے تین بار فرمایا پھر آپ ملے ایام تشریف لے گئے، پس آپ صلی اللہ علیہ وسلم آئے اور سیدنا فضل ولی اللہ سے پانی کا برتن لیا، سیدنا فضل نبی اللہ کھڑے ہوئے اور اس عورت کے پاس آئے۔ انہوں نے اسے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تمہیں کیا کہا؟ پس وہ کھڑی ہو گئی اور کہا: ہائے افسوس! یہ اللہ کے رسول ہیں جبکہ میں نے آپ صلی اللہ علیہ وسلم کو پہچانا نہیں! پس وہ تیز تیز چلی حتی کہ باب مسجد پر آپ ملے سے جاملی اور عرض کیا، اللہ کے رسول! اللہ کی قسم! میں نے آپ کو پہچانا نہیں، رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ”صبر پہلے صدمے پر ہے. آپ صلی اللہ علیہ وسلم نے اسے تین بار فرمایا۔ اس ملے حدیث کو اس اتمام کے ساتھ عطاء بن ابی میمونہ سے صرف یوسف بن عطیہ نے روایت کیا۔ اس میں سعید بن منصور کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/٥)، مجمع البحرين . مقدم۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جب مصیبت پہنچے یا غم تو انسان اپنے آپ کو اس وقت سے ہی غلط حرکات واقوال سے بچائے تو یہ ہی اصل صبر ہے۔ ایسے صبر کے متعلق نبی معظم علیم نے فرمایا: اللہ ذوالجلال فرماتا ہے، اے آدم کے بیٹے! اگر ابتدائے صدمہ کے وقت تو صبر کرے اور حصول ثواب کی نیت کرے تو میں تیرے لیے جنت سے کم ثواب پسند نہیں کروں گا۔ (ابن ماجه، رقم: ١٥٩٧، اسناده حسن) (٢) مذکوره بالا روایت سے نبی معظم ملے عام کا اخلاق بھی ثابت ہوتا ہے کہ اس عورت نے آپ صلی اللہ علیہ وسلم کی شان کے شایان انداز اختیار نہیں کیا، لیکن آپ صلی اللہ علیہ وسلم نے برہمی کا اظہار نہیں فرمایا، نہ اسے سخت ست کہا، بلکہ دوبارہ وہ سامنے آئی تو پھر بھی آپ صلی اللہ علیہ وسلم نے نصیحت ہی فرمائی۔ اس میں داعیان حق کے لیے بہت بڑا سبق ہے، اگر دین کے راستے میں لوگ ان کی شان و مقام کو نہ بھی پہنچانے تو ان کو اپنا مقام و مرتبہ دیکھنا چاہیے۔"}],[6245,"سیدنا ابو رافع بنی اللہ نے بیان کیا، رسول اللہ لیے علم جب اپنے مرض وفات میں تھے تو سیدہ فاطمہ بنت رسول اللہ علم حسن و حسین واہ ہونا کو لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور عرض کیا: یہ دونوں آپ صلی اللہ علیہ وسلم کے بیٹے ہیں، ان دونوں کو کسی چیز کا وارث بنا ئیں تو آپ صلی اللہ علیہ وسلم نے انہیں فرمایا: ”رہا حسن تو اس کے لیے میرا ثبات اور میری سیادت ہے اور رہا حسین تو اس کے لیے میری پختگی اور سخاوت ہے۔“ یہ ٩ / حدیث ابو رافع سے صرف اس اسناد سے مروی ہے۔ اس میں خالد بن یزید العمری کا تفرد ہے۔ ٦٢٤٦","",{"k":"كر مجمع الزوائد (١٨٥٩)، مجمع البحرين (٣٧٨٧)، اسناده ضعیف۔"}],[6246,"نافع سے روایت ہے کہ ایک آدمی نے سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے دریافت کیا تو کہا: میرے ماموں نے اپنی اہلیہ کو طلاق دے دی ہے، اس وجہ سے وہ ٹمگین ہے اور اس پر بہت گراں ہے، میں نے ارادہ کیا کہ میں اس سے شادی کر لوں، اس نے اس کا مجھے حکم دیا ہے نہ اسے اس کا پتہ ہے؟ سیدنا عبداللہ ابن عم رضی اللہ عنہ نے فرمایا: نہیں، مگر یہ کہ تم ندامت کا نکاح کرو، اگر اس نے تم سے موافقت کی تم نے اسے روک لیا اور اگر تم نے پسند نہ کیا تو اسے علیحدہ کر دیا مگر یہ کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے دور میں اسے بدکاری شمار کیا کرتے تھے۔ اس حدیث کو عمر بن نافع سے صرف ابو غسان نے روایت کیا۔","",{"k":"مجمع الزوائد (٢٦٧/٤)، صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حلالہ کرنا بدکاری ہے، بلکہ ایسے لوگوں کے متعلق حدیث میں آتا ہے کہ سیدنا عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا میں تمہیں ادھار کے سانڈ کی خبر نہ دوں؟ صحا بہ معنی اسلیم نے عرض کیا: کیوں نہیں، اللہ کے رسول! تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ حلالہ کرنے والا: ٦٢٤٧ ہے۔ (صحیح ابن ماجه، رقم: ١٥٧٢)"}],[6247,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک بچہ دیکھا انگلی کے ساتھ اس کے حلق کو دبایا گیا تھا، آپ مٹ سلیم نے فرمایا: ”تم اپنے بچوں کے حلق کو انگلی سے کیوں دباتے ہو، تم قسط استعمال کرو، پانی میں گھول کر ناک میں ڈالی جائے۔“ اس حدیث کو موسی بن علقمہ سے صرف عبد العزیز الدراوردی نے روایت کیا اور جابر کے حوالے سے سیدنا عائشہ بنی اشیا سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٥/٨٩)، صحیح بخاری، طب، السعوط بالقسط (٥٣٦٨)، مسند ابی یعلی (٤٣٨٣)، مسند احمد (٣٨٧/٣، ١٤٣٩٨)، رجاله رجال الصحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حلق کا کو اگر جانے کا بہترین علاج عود ہندی دینا ہے اور بچے کے حلق کو دبانا یا ملنا نہیں چاہیے۔ اس سے یہ بھی معلوم ہوا کہ نبی معظم من علم نے بچوں پر رحم کرنے کا حکم دیا ہے اور بچوں کے لیے آپ صلی اللہ علیہ وسلم کا رحمت کرنا ثابت ہے۔"}],[6248,"سیدنا ابو ہریرہ رضی لینہ نے بیان کیا، ایک دن رسول اللہ صلی اللہ علیہ وسلم کے پاس بخار کو برا بھلا کہا گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اسے برا بھلا نہ کہو، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! وہ مومن کے گناہ اس طرح ختم کر دیتا ہے جس طرح بھٹی لوہے کا میل کچیل دور کر دیتی ہے۔“ اس حدیث کو علقمہ بن مرشد سے صرف موسی بن عبیدہ نے روایت کیا۔ اس میں عبد العزیز بن محمد کا تفرد ہے، اور حفص بن عبید اللہ بن انس نے سیدنا ابو ہریرہ بنی الیہ سے صرف یہی حدیث روایت کی ہے۔ انون مذکورہ حدیث سے معلوم ہوا کہ بخار محض اللہ ذوالجلال کی طرف سے ہوتا، لہذا شکوہ شکایت کیے بغیر اللہ تعالیٰ کے اس فیصلے پر راضی ہونا چاہیے، بلکہ بیماری اور مصیبت پر صبر کرنا چاہیے، کیونکہ صبر کرنے سے گناہ معاف ہو جاتے ہیں۔","",{"k":"١١٠١٩ الالباني: صحيح . سنن ابن ماجه کتاب ال (٣٤٦٩)، قال الشيخ۔"}],[6249,"سیدنا عبد اللہ بن زبیر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایک بار دودھ چوسنے سے حرمت رضاعت ثابت ہوتی ہے نہ دو بار چوسنے سے۔“‘ اس حدیث کو عبید اللہ بن عمر سے صرف عبد اللہ بن رجاء نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ ایک یا دو مرتبہ پستان چوسنے سے حرمت رضاعت ثابت نہیں ہوتی۔ اس مسئلے میں اختلاف ہے کہ بچے کو کتنی مرتبہ دودھ پلانے سے حرمت ثابت ہوتی ہے۔ راجح موقف یہ ہے کہ پانچ مرتبہ دودھ پلانے سے حرمت رضاعت ثابت ہوتی ہے۔","",{"k":"٦٢٤٩ ١١٠. مسلم (١٤٥٠)، سنن ابو داود (٢٠٦٣)، سنن ترمذی، رقم۔"}],[6250,"سیدنا عقبہ بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور منبر پر لوگوں کو خطبہ دیا تو ارشاد فرمایا: ”میں اس منبر پر کھڑا ہوا، میں شب قدر جانتا ہوں، پس تم اسے آخری عشرے کی طاق راتوں میں تلاش کرو۔“ یہ حدیث عقبہ بن مالک سے صرف اس اسناد سے مروی ہے۔ اس میں عبد العزیز بن بیٹی کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ تاہم اس روایت کا آخری حصہ دوسری صحیح روایات سے ثابت ہے کہ آخری عشرے کی طاق راتوں میں لیلۃ القدر ہے۔","",{"k":"مجمع الزوائد (٤/١٧٧)، اسناده ضعيف۔"}],[6251,"سیدہ عائشہ منی اتنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے وعدہ فرمایا کہ وہ بیت اللہ میں نماز پڑھیں گی اور آپ صلی اللہ علیہ وسلم نے انہیں حکم فرمایا کہ وہ حطیم میں نماز پڑھیں، انہوں نے عرض کیا، آپ نے مجھ سے وعدہ فرمایا تھا کہ میں بیت اللہ میں نماز پڑھوں گی، اس پر آپ نے فرمایا: ”وہ ( حطیم ) بھی تو بیت اللہ کا حصہ ہے، اگر تمہاری قوم نئی نئی مسلمان نہ ہوئی ہوتی تو میں اس ( حطیم ) کو بھی بیت اللہ میں شامل کر دیتا۔ اس حدیث کو قتادہ سے صرف عمرو بن الحارث نے روایت کیا۔ ٦٢٥٢","",{"k":"تقدم تخريجه (٥١٨٠)۔"}],[6252,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: ”عنقریب تم چھلنی میں چھانے جاؤ گے حتی کہ تم کمینے لوگوں میں رہ جاؤ گے، ان کے عہد اور امانتیں خراب ہو جائیں گی، پس ہم میں سے کسی نے عرض کیا: اللہ کے رسول! ہماری کیا کیفیت ہوگی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: تم جو جانتے ہو گے اس پر عمل کرو گے، جسے نہیں پہچانتے ہو گے اسے چھوڑ دو گے اور تم کہو گے: احد احد، ہم پر ظلم کرنے والے کے خلاف ہماری مدد فرما اور ہم پر سرکشی کرنے والے کے مقابلے میں ہمیں کافی ہو جا۔“ یہ حدیث شریح القاضی سے صرف اس اسناد سے مروی ہے۔ اس میں یعقوب ابن حمید کا تفرد ہے۔","",{"k":"مجمع الزوائد (٧/٢٨٣)، مجمع البحرين (٤٤١٠)، کنز العمال (٣١٤٦٨)، اسناده ضعيف۔"}],[6253,"سعید بن مسیب نے بیان کیا، میں نے سیدنا عثمان بن عفان فضل اللہ کو دیکھا انہوں نے وضو کیا تو اپنی داڑھی کا خلال کیا، پھر فرمایا: ”میں نے نبی ملنے کی تم کو وضو کرتے ہوئے دیکھا آپ مطلعے علیم نے اپنی داڑھی کا خلال کیا۔ اس حدیث کو عطاء الخراسانی سے صرف شعیب بن رزیق نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ وضو کرتے ہوئے داڑھی کا خلال کرنا چاہیے۔: ٦٢٥٤","",{"k":"سنن ترمذی (٣١)، قال الشيخ الألباني: صحيح۔"}],[6254,"سیدنا علی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایمان دل سے معرفت، زبان سے اقرار اور اعضاء کے ساتھ عمل کا نام ہے۔“ یہ حدیث سیدنا لی فی الینے سے صرف اس اسناد سے مروی ہے۔ اس میں عبد السلام بن صالح الہروی کا تفرد ہے۔ ٦٢٥٥","",{"k":"سنن ابن ماجه (٦٥)، قال الشيخ الالبانی موضوع سلسله ضعیفه (٢٢٧١)، ضعيف الجامع (٢٣٠٩)۔"}],[6255,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں، رسول اللہ اسے علم کا تلبیہ یہ تھا: ((لبيك اله الحق)) معبود حقیقی میں حاضر ہوں۔“ اس حدیث کو سعید بن مسلم بن با نک سے صرف خالد بن یزید العمری نے روایت کیا۔","",{"k":"سنن نسائی (٢٧٥٢)، سنن ابن ماجه (٢٩٢٠)، قال الشيخ الالباني: صحيح۔"}],[6256,"سیدنا معاویہ بن ابی سفیان رضی اللہ عنہ نے بیان کیا، میں نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ ام حبیبہ منیشا کے پاس گیا تو میں نے نبی صلی اللہ علیہ وسلم کو ایک کپڑے میں نماز پڑھتے ہوئے دیکھا، آپ ملے میم نے اسے اپنی گدی سے باندھا ہوا تھا۔ میں نے ام حبیبہ مولانا سے کہا: نبی صلی اللہ علیہ وسلم ایک کپڑے میں نماز پڑھتے ہیں؟ انہوں نے فرمایا: ہاں، یہ وہی تھے جو اس حالت میں نماز پڑھ لیا کرتے تھے۔“ اس حدیث کو سعید بن مسلم بن بانک سے صرف خالد بن یزید العمری نے روایت کیا۔:٦٢٥٧ مذکورہ حدیث سے معلوم ہوا کہ ایک کپڑے میں نماز ہو جاتی ہے۔",""],[6257,"سیدنا عبد الرحمن بن ابی عمر نے بیان کیا، سیدنا عثمان بن عفان رضی اللہ عنہ نے مجھے بتایا، ہم کہا کرتے تھے کہ عشا کی نماز باجماعت پڑھنا نصف شب کے قیام سے بہتر ہے، جبکہ صبح کی نماز باجماعت پڑھنا، شب بھر کے قیام سے بہتر ہے۔ اس حدیث کو عبد الرحمن بن عمرو بن ابی عمرہ سے صرف عبد اللہ بن خالد ابو عطاف نے اور عبد اللہ سے صرف اس کے بھائی عطاف نے روایت کیا۔ اس میں سعید بن منصور کا تفرد ہے۔ اندن مذکورہ حدیث سے صبح، عشا کی جماعت کی فضیلت واضح ہے اور معلوم ہوا کہ ان دونوں نمازوں کو جماعت سے پڑھ لینا شب بھر کے قیام، اللہ کی عبادت کرنے سے افضل ہے۔ لیکن جو شخص یہ نمازیں باجماعت پڑھ لے اور رات کو قیام بھی کرے تو اس کا مقام بہت ہی اونچا ہو گا، لیکن یہ سعادت مومن کو ہی نصیب ہوتی ہے، منافق پر تو یہ دونوں نمازیں بھاری ہیں۔ جیسا کہ سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ رسول اللہ سلم نے فرمایا: منافقین پر دو نماز میں سب سے زیادہ بوجھل ہیں، نماز عشا اور نماز فجر اور اگر نہیں علم ہو جائے کہ ان میں حاضر ہونے کا کتنا اجر ہے تو وہ ضرور ان میں حاضر ہوں، خواہ کتنی ہی تکلیف کیوں نہ اٹھانی پڑے۔: (بخاری، کتاب الاذان، رقم: ٦٥٧)","",{"k":"سنن ابو داود (٥٥٥)، قال الشيخ الالباني: صحيح، سنن ترمذی (٢٢١)۔"}],[6258,"سیدنا عبداللہ ابن عمر نبی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مغرب کی نماز مزدلفہ میں پڑھی، پس جب اونٹ بٹھا دیا، فرمایا: ”نماز اقامت کے ساتھ ہے (اقامت کہہ کر عشاء پڑھو )۔‘اس حدیث کو عبید اللہ بن عمر سے صرف الدراوردی نے روایت کیا۔ اندن مطلب یہ ہے کہ نماز کے لیے اقامت ضروری ہے اور ہر نماز کے لیے الگ الگ تکبیر کہنا چاہیے۔ (بخاری، کتاب الحج، رقم: ١٦٧٣) لیکن ایک تکبیر کے ساتھ دو نمازیں پڑھنا درست نہیں ہے۔ C&S SEK","",{"k":"سنن ابن ماجه (٣٠٢١)، قال الشيخ الالباني: صحيح سنن ابو داود (١٩٢٧)۔"}],[6259,"سیدنا عبداللہ ابن عباس ریلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آخری دور میں کچھ ایسے لوگ آئیں گے، ان کے چہرے تو آدمیوں والے ہوں گے، جبکہ ان کے دل شیطان کے دل ہوں گے، خون خوار بھیڑیوں کی طرح، ان کے دل رحمت سے خالی ہوں گے، خون بہانے والے، وہ کسی فتیح کام سے نہیں روکیں گے، اگر تم نے ان کی متابعت کی تو وہ تجھے بڑھا چڑھا کر پیش کریں گے، اگر تو ان کے پاس نہیں ہوگا تو وہ تیری برائی بیان کریں گے، اگر تجھ سے بات کریں گے تو تجھے جھٹلائیں گے، اگر تم ان کے پاس امانت رکھو گے تو وہ تجھ سے خیانت کریں گے، ان کے بچے شرارتی، ان کے نوجوان شاطر اور ان کے عمر رسیدہ نیکی کا حکم کریں گے نہ برائی سے منع کریں گے، ان کے ذریعے عزت دار ہونا ذلت ہے، ان سے کسی چیز کو طلب کرنا فقر ہے، ان میں حلیم شخص گمراہ ہے، نیکی کا حکم کرنے والا ان میں متہم ہے، مومن ان میں ضعیف تصور کیا جاتا ہے، فاسق ان میں عزت دار ہے، سنت ان میں بدعت اور بدعت ان میں سنت ہے، پس ان حالات میں اللہ ان کے برے لوگوں کو ان پر مسلط کر دے گا اور ان کے اچھے لوگ دعائیں کریں گے تو ان کی دعائیں قبول نہیں ہوں Y من .. گی۔ اس حدیث کو خصیف سے صرف محمد بن سلمہ نے روایت کیا، اس میں محمد بن معاویہ کا تفرد ہے۔ رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٧/٢٨٦)، مجمع البحرين (٤٣٩٦)، اسناده ضعيف۔"}],[6260,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم گھر میں تھے تو ایک آدمی نے آپ کے گھر میں جھانکا تو آپ تیر کے ساتھ اس کی طرف لپکے اور اسے اس کی طرف بڑھایا تو وہ آدمی پیچھے ہٹ گیا۔ اس حدیث کو حمید سے صرف طفیل بصری الشیخ نے روایت کیا۔ اس میں معتمر کا تفرد ہے۔","",{"k":"صحیح بخاری (٦٨٨٩)، مسلم (٢١٥٧، ٦٢٢٧)۔"}],[6261,"سیدنا عبداللہ ابن عمر نبی الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی سے فرمایا: معصیت کے علاوہ ہر امر میں خواہ تمہیں پسند ہو یا ناپسند ہو سمع و اطاعت کرنا ہے، پس اللہ کی معصیت میں کسی کی کوئی اطاعت نہیں۔“ اس حدیث کو عبد اللہ بن سعید بن ابی ہند سے صرف المغیرہ بن عبد الرحمن نے روایت کیا۔ اس میں یعقوب بن حمید کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ جائز کاموں میں حکمرانوں کی اطاعت کرنا ضروری ہے۔ Big ناجائز کاموں میں ان کی اطاعت کرنا حرام ہے۔ ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ امَنُوا أَطِيعُوا اللَّهَ وَاَطِيْعُوا الرَّسُولَ وَ أُولِي الْأَمْرِ مِنْكُمْ (النساء: ٥٩) ”اے ایمان والو! اطاعت کرو اللہ کی اور اطاعت کرو رسول کی اور ان کی جو تمہارے حکمران ہیں۔“ اس آیت سے معلوم ہوا کہ اللہ اور رسول دونوں کے ساتھ لفظ اطاعت کے ذکر سے اس بات کی طرف اشارہ کرنا مقصود ہے کہ ان دونوں کی اطاعت مستقل بالذات ہے۔ جس کا مطلب یہ ہے کہ کتاب اللہ اور سنت رسول اللہ پر عمل کرنا واجب ہے، جبکہ مسلمان حکمرانوں کی اطاعت مستقل نہیں بلکہ اللہ و رسول ملنے نیم کے تابع ہے مذکورہ بالا حدیث میں مسلمانوں کے لیے مسلم حکمرانوں کی اطاعت کی حدود واضح کر دی گئی ہیں کہ مسلم حکمرانوں کی عزت اسی میں ہے کہ وہ اللہ اور اس کے رسول ملے تعلیم کے حکموں سے انحراف نہ کریں۔ اللہ کی نافرمانی میں مخلوق میں سے کسی کی بھی اطاعت جائز نہیں۔ ٦٢٦٢","",{"k":"صحیح بخاری (٢٩٥٥)، سنن ابو داود (٢٦٢٦)، سنن ترمذی (١٧٠٧)۔"}],[6262,"سیدنا ابو اروی الدوسی رضی اللہ عنہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا کہ سیدنا ابو بکر وعمر ناہنجا تشریف لائے تو آپ ملنے سلیم نے فرمایا: ”ہر قسم کی تعریف اللہ کے لیے ہے جس نے ان دونوں کے ذریعے میری مدد فرمائی۔ اس حدیث کو النضر بن عربی سے صرف بشر بن عمیس نے روایت کیا اور ابو اروی سے صرف اس اسناد سے روایت کیا جاتا ہے۔","",{"k":"مجمع الزوائد (٩/٥١)، مجمع البحرين (٣٦٣٣)، اسناده ضعيف۔"}],[6263,"سیدنا عبداللہ ابن عباس نا اہوجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اگر رکن (حجر اسود ) پر جاہلیت کی پلیدی اور ظلم و گناہ کے ہاتھ نہ لگتے تو مریض اس کے ذریعے شفا طلب کرتے۔“ یہ حدیث وہب بن منبہ کے حوالے سے طاوس سے صرف اس اسناد سے مروی ہے۔ اس میں الحلوانی کا تفرد ہے۔","",{"k":"مجمع الزوائد: د (٢٣)، اسناده ضعيف۔"}],[6264,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، ”اسلام کی بنیاد اس پر رکھی گئی ہے کہ اللہ کے سوا کوئی معبود نہیں، یہ کہ محمد (سے) اللہ کے رسول ہیں، نماز قائم کرنا، زکوۃ دینا، بیت اللہ کا حج کرنا اور رمضان کے روزے رکھنا۔ ان سے کہا گیا: رمضان کے روزے اور بیت اللہ کا حج، انہوں نے کہا: نہیں، مگر آپ نے اسی طرح فرمایا۔ اس حدیث کو سفیان کے حوالے سے عہدہ سے صرف ابراہیم بن محمد الشافعی نے روایت کیا اور ابراہیم بن بشار الرمادی وغیرہ نے اسے سفیان، عن سعیر بن النمس اور مسعر بن کدام کی سند سے روایت کیا۔ ناند مذکورہ حدیث میں اسلام کو ایک عظیم عمارت کے ساتھ تشبیہ دی گئی ہے جس کی پانچ بنیادیں ہیں، جس طرح بنیادوں کے بغیر کوئی عمارت قائم نہیں رہ سکتی، اسی طرح ان ارکان خمسہ کے بغیر اسلام کا","",{"k":"صحیح بخاری (٨)، مسلم (٢١/١٦)۔","f":"وجود برقرار نہیں رہ سکتا۔ اس لیے جو شخص بھی ان میں سے کسی ایک فرض کا انکار کرے گا تو وہ کافر اور جو یوں ہی مستی اور غفلت کی وجہ سے ان میں سے کسی ایک فرض کا تارک ہوگا وہ فاجر و فاسق ہوگا۔"}],[6265,"سیدنا عبد اللہ نبی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں کسی کو خلیل ( جگری دوست ) بنانے والا ہوتا تو میں ابو بکر کو خلیل بناتا اس حدیث کو سفیان سے صرف ابراہیم بن محمد الشافعی نے روایت کیا۔","",{"k":"کے صحیح مسلم، سنن ترمذی (٣٦٥٥)، سنن ابن ماجه (٩٣)۔"}],[6266,"میں نے بیان کیا، سیدنا عمر نبی الیہ نے سیدہ اسماء بنی ہو یا اسے کہا: ہم نے تم سے پہلے ہجرت کی، انہوں نے کہا: اللہ کی قسم! تم نے ہم سے پہلے ہجرت کی، ہم ننگے بدن ننگے پاؤں کے پاس تھے اور تم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے، وہ تمہارے جاہل و عالم کو تعلیم دیتے تھے اور تم کو اعلی اخلاق کا حکم دیتے تھے اور انہوں (اسماء بنی الیھا) نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤں گی اور آپ کو بتاؤں گی، انہوں نے فرمایا: لوگوں کی ایک ہجرت ہے، جبکہ تمہاری دو ہجرتیں ہیں۔“ اس حدیث کو سفیان سے صرف محمد بن ابی عمر نے روایت کیا۔ مذکورہ حدیث سے حبشہ سے ہجرت کرنے والوں کی فضیلت واضح ہے۔ دو ہجرتیں اس لیے فرمایا: ایک تو مکہ مکرمہ سے حبشہ، پھر حبشہ سے مدینہ منورہ کی طرف ہجرت کی۔",""],[6267,"سیدنا عبداللہ ابن عمر ضیا المیہ نے بیان کیا، بسا اوقات شمار کرنے والا، ایک ہی مجلس میں رسول اللہ صلی اللہ علیہ وسلم کا یہ دعا پڑھنا سو بار شمار کرتا: ” مجھے بخش دے، میری توبہ قبول فرما، بے شک تو توبہ قبول فرمانے والا بخشنے والا ہے۔“ یا مذکورہ حدیث کا مطلب یہ ہے کہ نبی معظم سے علی کی مجلس میں تشریف رکھتے ہوئے بھی بار بار اللہ تعالیٰ کی طرف متوجہ ہو کر ان کلمات کے ساتھ استغفار و توبہ کرتے رہتے۔ جس کو ہم اپنے طور پر شمار کرتے تو معلوم ہوتا کہ آپ نے ایک مجلس میں سو مرتبہ اللہ ذوالجلال سے ان الفاظ کے ساتھ استغفار فرمایا، مذکورہ حدیث سے دعا کا ایک ادب بھی معلوم ہوتا ہے وہ یہ ہے کہ اللہ کے صفاتی نام استعمال کیے جائیں، جیسے تو بہ واستغفار میں اس کی صفت تو ابیت اور صفت غفوری و رحیمی کا اور دنیا کے معاملات میں اس کے جواد، کریم وغیرہ ہونے کا ذکر کیا جائے۔","",{"k":"سنن ابو داود (١٥١٦)، سنن ترمذی (٣٤٣٤)، سنن ابن ماجه (٣٨١٤)، قال الشيخ الالباني: صحيح۔"}],[6268,"سیدنا محمد بن سیرین نے بیان کیا، میں نے سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے قربانی کے متعلق سوال کیا، کیا وہ واجب ہے؟ انہوں نے فرمایا: ”رسول اللہ سے ہم نے قربانی کی اور آپ کے بعد:٦٢٦٩ مسلمانوں نے قربانی کی۔ اس حدیث کو ابن عون سے صرف اسماعیل بن عیاش نے روایت کیا۔","",{"k":"٦٢٦٨ سنن ترمذی (١٥٠٦)، قال الشيخ الالباني: ضعيف۔"}],[6269,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم سے گدھوں کے بارے میں سوال کیا گیا؟ تو آپ نے فرمایا: ”ان کے بارے میں بس یہی نادر جامع آیت ہی نازل ہوئی ہے: پس جو ذرہ برابر خیر و بھلائی کرے گا وہ اسے دیکھ لے گا اور جو ذرہ برابر برائی کرے گا وہ اسے بھی دیکھ لے گا۔‘ اس حدیث کو سفیان سے صرف سعید بن منصور نے روایت کیا۔","",{"k":"صحیح بخاری (٤٩٦٣)، مسلم (٩٨٧)۔","f":": صحیح بخاری میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گھوڑوں کے متعلق فرمایا: ((الخَيْلُ لِثَلاثَةِ لِرَجُلٍ أَجْرٌ وَلِرَجُلٍ سِتْر وَعَلَى رَجُلٍ وِزْرٌ ) گھوڑے تین طرح کے ہیں، ایک گھوڑا آدمی کے لیے اجر ہے، ایک گھوڑا پردہ ہے اور ایک گھوڑا بوجھ ہے۔“ اس پر نبی مکرم ملتے علیم سے گدھوں کے متعلق سوال کیا گیا تو آپ علیہ سلام نے مذکورہ بالا الفاظ ارشاد فرمائے۔"}],[6270,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”گھوڑے اور غلام پر زکوۃ نہیں البتہ غلام پر صدقہ فطر ( فطرانہ) ہے۔“ اس حدیث کو عبید اللہ بن عمر سے صرف ابن ابی زائدہ نے روایت کیا۔ اس میں یزید کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ غلام اور گھوڑے میں زکاۃ نہیں، لیکن غلام سے مراد ایسا غلام ہے جو انسان نے اپنی خدمت کے لیے رکھا ہو اور گھوڑے سے مراد ایسا گھوڑا ہے جو اپنی سواری کے لیے مخصوص ہو۔ پھر ان میں زکاۃ نہیں ہو گی لیکن اگر انہیں تجارت کے لیے رکھا ہو تو پھر ان میں بھی تجارتی مال ہونے کی حیثیت سے زکاۃ لازم ہوگی۔ جمہور علماء کا یہی موقف ہے۔ یہ بھی معلوم ہوا کہ غلام کی طرف سے صدقہ فطر کی ادا ئیگی واجب ہے۔ شیخ عبد اللہ بسام رحمہ اللہ نے کہا ہے کہ غلام پر زکوۃ الفطر واجب ہے۔ خواہ وہ خدمت کے لیے ہو یا تجارت کے لیے۔ (توضیح الاحکام، شرح بلوغ المرام: ٣/ ٣١٢)","",{"k":"صحيح بخارى (١٤٦٤)، مسلم، رقم: ٩٨٢ . الله۔"}],[6271,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” جہنمیوں میں سے سب سے ہلکا عذاب اس کو ہو گا، جس کی آگ کی جوتیاں ہوں گی، ان سے اس کا دماغ کھولے گا۔“ اس حدیث کو عبد اللہ بن عیاش سے صرف مفضل بن فضالہ نے روایت کیا۔ ننده مسند احمد: ٢٩٥/١ میں ہے کہ جس کو ہلکا ترین عذاب ہوگا، وہ ابو طالب ہے۔ مذکورہ بالا روایت سے یہ بھی معلوم ہوا کہ جہنم کے عذاب کے مختلف درجات ہوں گے اور یہ بات دوسری احادیث سے بھی ثابت ہے جیسا کہ سیدنا سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی مکرم سے تعلیم کو یہ فرماتے ہوئے سنا: آگ بعض جہنمیوں کو ٹخنوں تک جلائے گی، بعض کو گھٹنوں تک جلائے گی، بعض کو کمر تک اور بعض کو گردن تک جلا دے گی۔ (مسند احمد: ٥/ ١٠ - ١٨) ٢ ٦٢٧٢","",{"k":"مجمع الزوائد (١٠/٣٩٥)، صحیح ترغیب و ترهيب (٤٦٨٧)۔"}],[6272,"سیدنا عقبہ بن عامر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے مریضوں کو کھانے پینے پر مجبور نہ کرو، کیونکہ اللہ انہیں کھلاتا پلاتا ہے۔ اس حدیث کو موسی بن علی سے صرف بکر بن یونس نے روایت کیا۔ عقبہ بن عامر سے صرف اس اسناد سے مروی ہے۔","",{"k":"سنن ترمذی (٢٠٤٠)، سنن ابن ماجه (٣٤٤٤)، قال الشيخ الالباني: صحيح۔","f":"مذکورہ روایت میں بکر بن یونس بن بکیر راوی ضعیف اور منکر الحدیث ہے۔ (میزان الاعتدال: ١/ ٣٤٨) تاہم شیخ البانی اللہ نے اس روایت کو صحیح کہا ہے۔(دیکھئے:سلسلة صحيحه: ٧٢٧) مذکورہ حدیث سے معلوم ہوا کہ مریض کو کھانا کھانے پر مجبور نہیں کرنا چاہیے، کیونکہ اگر مریض کی طبیعت کھانا کھانے پر آمادہ نہ ہو اور زبردستی کی جائے تو فائدے کی بجائے نقصان ہو گا، مناسب ترغیب کے ذریعے سے ہلکی پھلکی زود ہضم غذا دی جا سکتی ہے، تا کہ قوت قائم رہے۔ اللہ ذوالجلال مریض کو کھلاتا پلاتا ہے، اس کا مطلب یہ ہے کہ انہیں تندرست آدمی کی طرح کھانے پینے کی ضرورت نہیں ہوتی کہ ایک مریض دس دن کھانا نہیں کھاتا، لیکن جو نہی وہ شفایاب ہوتا ہے تو ایک دو دنوں کے اندر اندر اس کی صحت بحال ہو جاتی اور اس پر دس دنوں کے فاقے کے آثار نظر نہیں آتے، اس کے برعکس اگر کوئی صحت مند آدمی تین چار دن کھانا پینا بند کر دے تو اس کی قوتیں جواب دے جاتی ہیں، وہ چلنے پھرنے سے قاصر ہو جاتا اور اس کے پیٹ کا نظام تباہ ہو جاتا ہے۔ پتا چلا کہ مریض کے ساتھ اللہ ذوالجلال کا کوئی خاص تعلق ہوتا ہے۔ ٦٢٧٣"}],[6273,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” آدمی حلم کی وجہ سے قیام کرنے والے روزہ دار کے درجے کو پالیتا ہے، آدمی جبار لکھا جاتا ہے جبکہ وہ صرف اپنے گھرانے کا مالک ہوتا ہے۔“ رضی ہے۔ سیدنا علی ولی اللہ سے یہ حدیث صرف اس اسناد سے مروی ہے۔ اس میں اسماعیل بن عیاش کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٤/٨)، سلسله ضعيفه (٣٠٠٢)، ضعيف الجامع الصغير (١٤٥٣)، اسناده ضعيف۔"}],[6274,"اسود نے بیان کیا، میں نے سیدہ عائشہ صلی اشیا سے اس آدمی کے متعلق سوال کیا جو احرام باندھنا چاہتا ہے کیا وہ خوشبو لگا سکتا ہے؟ انہوں نے فرمایا: ”جس قدر ہو سکے بہترین خوشبو لگائے، گویا کہ میں رسول اللہ علم کی مانگ میں خوشبو کی چمک دیکھ رہی ہوں، جبکہ آپ ملے یکم محرم تھے۔“ انس بن ابی القاسم نے عبد الرحمن بن اسود سے صرف یہی حدیث روایت کی ہے اور ابو القاسم کا نام، مالک، کوفی ہے۔ احرام کی تیاری کے وقت لباس بدلتے ہوئے احرام سے پہلے پہلے خوشبو لگا لینا مسنون ہے۔ اگر اس خوشبو کا رنگ اور اثر حالت احرام میں باقی رہے تو کوئی حرج نہیں۔ لیکن حالت احرام میں خوشبو لگانا جائز نہیں، حتی کہ حالت احرام میں غسل کے لیے ایسا صابن بھی استعمال نہیں کرنا چاہیے، جس میں عطریات شامل ہوں۔","",{"k":"صحیح بخاری، رقم: صحیح مسلم (١١٩٠)۔"}],[6275,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو اللہ کی راہ میں ایک دن روزہ رکھتا ہے، اللہ اسے ستر سال کی مسافت کے برابر جہنم کی آگ سے دور کر دیتا ہے۔“ اس حدیث کو زید بن اسلم سے صرف اس کے بیٹے عبد الرحمن اور ہشام بن سعد نے روایت کیا۔ اس میں ہشام بن سعد سے لیث بن سعد کا تفرد ہے۔","",{"k":"الله، سنن ترمذی (١٦٣٢)، قال الشيخ الالباني: صحيح۔"}],[6276,"سیدہ عائشہ منی اش جیا نے بیان کیا، سال میں ایک دن تھا اس میں نبی صلی اللہ علیہ وسلم کی ازواج مطہرات بیان تین دن سے رات تک آپ صلی اللہ علیہ وسلم کے پاس اکٹھی رہتیں، سیدہ عائشہ بنایا نجھا نے فرمایا: اسی روز آپ میم نے فرمایا: ”تم میں سے جس کا ہاتھ زیادہ دراز ہے وہ سب سے پہلے مجھ سے ملے گی۔“ سیدہ عائشہ نیلی نیہا نے فرمایا: ”ہم آپس میں ہاتھ ناپنے لگیں کہ ہم میں سے کس کے ہاتھ زیادہ لمبے ہیں، سیدہ سو وہ ہنی الجھا کے ہاتھ زیادہ لمبے تھے، پس جب زینب بنا یا یوں فوت ہوئیں تو ہم نے جان لیا کہ ان میں سے خیر وصدقہ میں زیادہ لمبے ہاتھ والی تھیں۔ انہوں نے بیان کیا، سیدہ زینب نی اینجا سوت کا تی تھیں، وہ اسے نبی صلی اللہ علیہ وسلم کے لشکروں کو دیتی تھیں وہ اس کے ذریعے سلائی کرتے تھے اور اس سے اپنی غزوات میں مدد حاصل کرتے تھے، اسی روز آپ نے فرمایا تھا: ”تم میں سے ایک کی کیا حالت ہو گی جب اس پر جواب کے کتے بھونکیں گے۔ اس حدیث کو مجالد سے صرف ابن ابی زایدہ نے روایت کیا۔ مذکورہ حدیث سے صدقہ کرنے والوں کی فضیلت ثابت ہوئی اور نبی معظم ما علیم نے جو اپنی زندگی میں پیشین گوئی کی، وہ سچ ثابت ہوئی اور سیدہ زینب نوا النخجہا نبی معظم صلی اللہ علیہ وسلم کے بعد ازواج مطہرات بین الدین میں سے سب سے پہلے ٢٠ ہجری ترین سال کی عمر میں سیدنا عمر بن الہیہ کی خلافت میں فوت ہوئیں۔ مرعاۃ المصابیح میں ہے کہ سیدہ زینب بنی ہویا چمڑا میں اور اسے فروخت کرتیں اور صدقہ و خیرات کرتی تھیں۔:٦٢٧٧ و- دوه و (مرعاة المصابيح: ٤، ٥، صفحه نمبر ١٤٧)","",{"k":"مجمع الزوائد (٨/٢٨٩)، بخاری (١٤٢٠)، مسلم (٢٤٥٢)۔"}],[6277,"سیدنا ابو ہریرہ رضی عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے شتر مرغوں کے انڈوں کے بارے میں، جنہیں احرام والا کھا لیتا ہے، فیصلہ فرمایا کہ وہ اس کے بقدر قیمت ادا کرے۔“ یہ حدیث سیدنا ابو ہریرہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں مروان بن معاویہ کا تفرد ہے۔ ابوالمبزم کا نام: یزید بن سفیان ہے۔","",{"k":"سنن ابن ماجه (٣٠٨٦)، قال الشيخ الالبانی: ضعیف، ضعيف الجامع الصغير (٤٠٠٩)۔"}],[6278,"سيدنا سعد بن ابی وقاص رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”دنیا میں دو چہروں والا شخص، قیامت کے دن آئے گا اور اس کے آگ کے دو چہرے ہوں گے۔“ یہ حدیث سیدنا سعد رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں خالد بن یزید العمری کا تفرد ہے۔ . دو چہرے کا یہ مطلب نہیں کہ پیدائشی طور پر اس کے دو منہ تھے، بلکہ چونکہ ہر فریق سے اس طرح بات کرتا تھا، جیسے خاص اسی کا ہم درد ہے، گویا کہ فریق اول سے جو بات کی وہ اس منہ سے کی اور دوسرے فریق کے ساتھ دوسرا منہ لے کر بات کی اور بات میں دوغلہ پن اختیار کیا، ایسے شخص کے ایک ہی چہرے کو دو چہرے قرار دیا گیا، کیونکہ غیرت مند آدمی اپنی زبان سے جب ایک بات کہہ دیتا ہے تو اس کے خلاف دوسری بات اسی زبان سے کہتے ہوئے شرم محسوس کرتا ہے۔ بے ضمیر اور بے غیرت آدمی ایک چہرے کو دو چہروں کی جگہ استعمال کرتا ہے جو کہ زبان کی الٹا لیٹی کی وجہ سے ایک چہرے کے دو چہرے قرار دیئے گئے اور ایک زبان سے دو چہروں کا کردار ادا کیا، اس لیے قیامت کے دن اس حرکت بد کی سزا یہ مقرر کی گئی کہ ایسے دوغلے شخص کے منہ میں آگ کی دو زبانیں پیدا کر دی جائیں گی، جن کے ذریعہ جلتا بھتا رہے گا اور اس کا یہ خاص عذاب دیکھ کر لوگ سمجھ لیں گے کہ یہ شخص دو منہ والا اور دوغلہ تھا۔ (اعاذنا الله من ذلك) ٦٢٧٩",""],[6279,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دوخون خوار بھیڑیے بکریوں کے ریوڑ میں اتنا بگاڑ پیدا نہیں کرتے جتنا طلب مال اور طلب عہدہ مسلمان شخص کے دین میں باعث فساد ہے۔“ یہ حدیث سیدنا ابوسعید خدری رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں خالد بن یزید کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٢٥٠)۔"}],[6280,"سیدہ ام فضل بنت حارثہ نیا اینجا سے روایت ہے کہ جب وہ کسی کو سورۃ المرسلات پڑھتے ہوئے سنتیں تو فرماتیں: آپ صلی اللہ علیہ وسلم نے مغرب کی نماز میں سورۃ المرسلات تلاوت فرمائی۔ پھر آپ ملنے کی یکم نے ہمیں عشا نہیں پڑھائی حتی کہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کی روح قبض کر لی۔“ اس حدیث کو زہری کے حوالے سے ابو رشد ین وہ کریب ہیں سے صرف اسامہ ابن زید نے روایت کیا اور باقی لوگوں نے اسے زہری، عن عبید اللہ، عن ابن عباس، عن ام الفضل کی سند سے روایت کیا۔","",{"k":"صحیح بخاری (٤٤٢٩)، صحیح مسلم (٤٦٢)۔","f":"اند جیسا کہ پیچھے بھی گذر چکا ہے کہ مغرب میں قصار مفصل ( یعنی سورۃ البینہ سے لے کر سورۃ الناس تک ) پڑھنا مسنون ہے۔ تاہم احادیث سے ثابت ہے کہ کبھی کبھی اس کے برخلاف مغرب میں رسول اللہ ملے عالم طوال مفصل پڑھ لیا کرتے تھے۔ جیسا کہ پیچھے گزر چکا ہے کہ مغرب میں سورہ طور پڑھی اور مذکورہ بالا حدیث سے سورہ المرسلات کا پڑھنا ثابت ہوتا ہے۔"}],[6281,"سیدنا عبد الرحمن بن سمرہ رضی اللہ عنہ نے بیان کیا، جس وقت غزوہ تبوک کی تیاری کی گئی، اس وقت سیدنا عثمان بن عفان رضی اللہ عنہ ایک ہزار دینار لائے اور نبی صلی اللہ علیہ وسلم کی گود میں ڈھیر کر دیے۔ سیدنا عبد الرحمن ضیا اللہ کہتے ہیں: ” میں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم اپنے دست مبارک سے انہیں الٹ پلیٹ رہے تھے اور فرما رہے تھے: ” ابن عفان فی اللہ ہے آج کے بعد جو بھی عمل کرے اس کے لیے مضر نہیں۔“ یہ حدیث عبد الرحمن بن سمرہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے، اس میں عبد اللہ بن شوذب کا تفرد ہے اور ابن شوذب سے صرف ضمرہ نے روایت کیا۔ نان سیدنا عثمان ولی الیہ کی عظمت شان کے متعلق پیچھے بھی گزر چکا ہے۔ ((لا يضر ابن عفان)) مطلب یہ ہے کہ سیدنا عثمان بنی اہلیہ نے ایسا نیکی کا کام کیا ہے کہ وہ کام اللہ ذوالجلال کی عدالت میں قبول ہوا ہے کہ اگر کبھی کوئی غلطی ہو بھی گئی تو اللہ ذوالجلال کے ہاں محاسبہ نہیں ہو گا، اس گناہ سے ضرر بھی نہیں ہو گا۔ مذکورہ حدیث سے ان ملعون لوگوں کو سبق حاصل کرنا چاہیے جو سیدنا عثمان رضی اللہ عنہ کے متعلق اپنی غلیظ زبان استعمال کرتے ہیں، اگر انسان ہونے کی وجہ سے کوئی گناہ ہوا بھی ہو تو اللہ ذوالجلال نے معاف کر دیا تو پھر لعن کرنا، ایسا ہے کہ جیسے کوئی شخص بیمار ہو کر اچھا ہو گیا پھر کوئی احمق اس کو بیمار کہے۔","",{"k":"سنن ترمذی (٣٧٠١)، قال الشيخ الالباني: حسن . ور۔"}],[6282,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ پسند فرماتا ہے کہ اس کی رخصتوں پر عمل کیا جائے جس طرح وہ پسند کرتا ہے کہ اس کے عزائم پر عمل کیا جائے۔ میں نے کہا: اس کے عزائم کیا ہیں؟ فرمایا: اس کے فرائض۔ اس حدیث کو ہشام بن عروہ سے صرف عمر بن عبید نے روایت کیا۔ اس میں حفص ابن عبد اللہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٦٣/٣)، اسناده ضعيف۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اللہ ذوالجلال کو وہ بندہ محبوب لگتا ہے جو اللہ ذوالجلال کی دی ہوئی رخصتوں پر عمل کرے، اسی طرح جس طرح واجبات پر عمل کرنے والا اللہ ذوالجلال کو پیارا لگتا ہے۔ یہی وجہ ہے کہ اللہ تعالیٰ جہاں کہیں کوئی کام بندوں پر مشکل ہوتا ہو وہیں اس میں کوئی سہولت کا پہلو رکھ دیتے ہیں اور کسی کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے۔ ارشاد باری تعالیٰ ہے کہ:: ﴾ (البقره: ١٨٥) اللہ تعالیٰ تمہارے ساتھ آسانی چاہتا ہے اور تمہیں تنگی میں نہیں ڈالنا چاہتا۔“"}],[6283,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بندہ اپنے حسن خلق کی وجہ سے قیام کرنے والے روزہ دار کے درجے کو پہنچ جاتا ہے۔ میرا خیال ہے کہ آپ نے فرمایا: اللہ کی راہ میں جہاد کرنے والے کے درجہ تک بھی۔“ اس حدیث کو سہیل سے صرف عمر بن عبید نے روایت کیا۔ اس میں حفص بن عبد اللہ کا تفرد ہے۔ ٦٢٨٤","",{"k":"ترغیب و ترهيب (٤٠٤/٣)۔"}],[6284,"سيده عزہ بنت فایل مولی عنہا نے بیان کیا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئیں تو آپ میم نے ان سے اس پر بیعت لی کہ تم زنا کرو گی نہ چوری کرو گی اور تم ظاہری طور پر یا خفیہ طور پر اولا دکو زندہ درگور نہیں کرو گی، میں نے کہا: ظاہری طور پر اولاد کو زندہ درگور کرنا تو میں جانتی ہوں، رہا مخفی طور پر اولاد کو زندہ درگور کرنا تو میں نے (اس کے متعلق) رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تو آپ نے مجھے بتایا، میرے دل میں خیال پیدا ہوا کہ وہ بچے کو خراب کرنا ہے اللہ کی قسم! میں کبھی اپنے کسی بچے کو خراب نہیں کروں گی۔ یہ حدیث عزہ بنت فایل سے صرف اس اسناد سے مروی ہے۔ اس میں موسی بن یعقوب کا تفرد ہے۔ اسے موسی سے صرف عباس بن ابی شملہ اور ابن ابی فدیک نے روایت کیا۔ مذکورہ روایت کمزور ہے۔ تاہم ارشاد باری تعالیٰ ہے: يَأَيُّهَا النَّبِيُّ إِذَا جَانَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكُنَ بِاللَّهِ شَيْئًا وَلَا يَسْرِقُنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَادَهُنَّ وَلَا يَأْتِيْنَ بِبُهْتَانٍ يَفْتَرِيْنَهُ بَيْنَ أَيْدِيْهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِيْنَكَ فِي مَعْرُوفٍ فَبَايِعُهُنَّ وَاسْتَغْفِرُ لَهُنَّ اللَّهَ إِنَّ اللهَ غَفُورٌ رَحِيم (الممتحنه: ١٢) اے پیغمبر ( م )! جب مسلمان عورتیں آپ نے میم ) سے ان باتوں پر بیعت کرنے آئیں کہ وہ اللہ کے ساتھ کسی کو شریک نہ کریں گی، چوری نہ کریں گی، زنا کاری نہ کریں گی، اپنی اولاد کو نہ مار ڈالیں گی اور کوئی ایسا بہتان نہ باندھیں گی جو خود اپنے ہاتھوں اور پیروں کے سامنے گھڑ لیں اور کسی نیک کام میں تیری بے حکمی نہ کریں گی تو آپ لئے یہ ) ان سے بیعت کر لیا کریں اور ان کے لیے اللہ سے مغفرت طلب کریں، بے شک اللہ ذوالجلال بخشنے اور معاف کرنے والا ہے۔“ صحیح بخاری میں ہے کہ فتح مکہ والے دن آپ صلی اللہ علیہ وسلم نے قریش کی عورتوں سے بیعت لی، بیعت لیتے وقت آپ صلی اللہ علیہ وسلم صرف زبان سے عہد لیتے، کسی عورت کے ہاتھ کو آپ صلی اللہ علیہ وسلم نہیں چھوتے تھے، سیدہ عائشہ من الشیبا فرماتی ہیں: اللہ کی قسم! بیعت میں نبی مکرم ملے لی ایم کے ہاتھ نے کبھی کسی عورت کے ہاتھ کو نہیں چھوا، بیعت کرتے وقت آپ صلی اللہ علیہ وسلم صرف یہ فرماتے کہ میں نے ان باتوں پر تجھ سے بیعت لے لی۔ (صحیح بخاری، کتاب التفسير، باب تفسير سوره (البینہ فتح مکہ کے موقع پر بھی بیعت لی، اسی طرح جو بھی ہجرت کر کے عورتیں آتیں، ان سے بھی ان الفاظ کے ساتھ بیعت لیتے۔","",{"k":"مجمع الزوائد (٣٩/٦)، مجمع البحرين (٢٢)۔"}],[6285,"سیدہ عائشہ منی اشیا نے رسول اللہ صلی اللہ علیہ وسلم سے، انہوں نے سیدنا جبریل علیہ اسلام سے روایت کیا، انہوں نے کہا: میں نے زمین کے مشارق و مغارب چھان مارے، میں نے محمد صلی اللہ علیہ وسلم سے بہتر کوئی شخص دیکھا نہ بنو ہاشم کے گھر سے بہتر کوئی گھر دیکھا۔“ یہ حدیث زہری سے صرف اس اسناد سے مروی ہے،اس میں موسی بن عبیدہ کا تفرد ہے۔ اور سیدہ عائشہ ریلی نینجا اسے صرف اس اسناد سے مروی ہے۔","",{"k":"تَفَرَّدَ بِهِ مُوسَى بْنُ عُبَيْدَةَ . وَلَا يُرْوَى عَنْ عَائِشَةَ إِلَّا بِهَذَا الْإِسْنَادِ . کر مجمع الزوائد (٢١٧/٨)، مجمع البحرين (٣٥١١)، سلسله ضعیفه (٤٠٤٦)، ضعيف الجامع الصغير (٤٦٤)۔"}],[6286,"سیدنا حذیفہ بن یمان ولی اللہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کے ہاں ایک رات بسر کی، میں نے آپ صلی اللہ علیہ وسلم کے پاس ایک شخص دیکھا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”حذیفہ! کیا تم نے اسے دیکھا ہے؟“ میں نے عرض کیا: اللہ کے رسول! جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ فرشتہ ہے، میں جب سے نبی بنا ہوں میرے پاس نہیں آیا، اس رات میرے پاس آیا، اور اس نے مجھے خوش خبری سنائی کہ حسن و حسین (نا) جنتی نوجوانوں کے سردار ہیں۔ “ اس حدیث کو قیس سے صرف سالم بن ابی الجعد نے اور سالم سے صرف ابوعمر والا شیعی نے روایت کیا۔ اس میں عطاء بن مسلم کا تفرد ہے۔ مذکورہ روایت ضعیف ہے، تاہم صحیح احادیث سے ثابت ہے کہ سیدنا حسنین کریمی نیا اینجا:٦٢٨٧ جنتی نوجوانوں کے سردار ہیں۔","",{"k":"مجمع الزوائد (٩/١٨٢)، مجمع البحرين (٣٧٨٢)، اسناده ضعيف۔"}],[6287,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ سیدنا حسان بن ثابت رضی اللہ عنہ کے پاس سے گزرے، جبکہ وہ مسجد میں شعر پڑھ رہے تھے، سیدناعمر رضی اللہ عنہ نے ان سے کہا: یہاں (شعر ن الله پڑھتے ہو )؟ سیدنا حسان رضی اللہ عنہ نے ان سے کہا: جی ہاں، میں نے یہاں (مسجد نبوی میں ) اس شخصیت کی موجودگی میں شعر پڑھے جو آپ سے بہتر ہیں، پھر سیدنا حسان یا اللہ سیدنا ابو ہریرہ میل الیہ کی طرف متوجہ ہوئے اور فرمایا: ”ابو ہریرہ! میں آپ کو اللہ کی قسم دیتا ہوں، کیا آپ نے رسول اللہ میم کو فرماتے ہوئے سنا: ”میری طرف سے جواب دو، اے اللہ! اس کی جبریل علی نام کے ذریعے مدد فرما؟ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: اللہ کی قسم! ہاں، پس سیدنا عم رضی اللہ عنہ ہو گئے اور تشریف لے گئے۔ اس حدیث کو ہشام سے صرف مخلد بن الحسین نے روایت کیا۔ فاندن . سیدنا حسان بن ثابت رضی اللہ عنہ کے قبیلہ خزرج میں سے تھے، شاعر رسول ملے علیم کے لقب سے مشہور تھے۔ ابو عید ہ کا قول ہے کہ عرب متفق ہیں کہ شہری شعراء میں سیدنا حسان بن ثابت فضل الہیہ سب سے بڑے شاعر تھے۔ ٥٤ ہجری میں سیدنا امیر معاویہ رضی اللہ عنہ کے دورہ خلافت میں وفات پائی، بعض کے نزدیک ٥٥ ہجری میں فوت ہوئے، وفات کے وقت ان کی عمر ایک سو بیس سال تھی۔ مذکورہ بالا حدیث سے معلوم ہوتا ہے کہ مسجد میں اشعار پڑھنا جائز ہے، مگر ایسے اشعار نہ ہوں جو توحید کے منافی ہوں اور ان سے شرک کی بو آتی ہو، جو برے اشعار ہوں یا نمازیوں کے لیے دخل اندازی کا سبب ہوں کہ نماز میں توجہ منتشر کر دیں، برے اشعار مسجد تو در کنار باہر بھی کسی جگہ پر نہیں پڑھنے چاہئیں۔ نیز واضح رہے کہ سیدنا حسان فضل اللی مسجد میں ایسے اشعار پڑھتے تھے، جن میں کفار کی ہجو ہوتی تھی۔ نبی معظم نے یہ سن کر فرماتے، اللہ تعالیٰ روح القدس سے تیری مددفرمائے، جیسا کہ پیچھے احادیث گزر چکی ہیں۔ تاہم ایک روایت میں ہے کہ رسول اللہ تعلیم نے مسجد میں شعر و شاعری کرنے سے منع فرمایا ہے۔ (ترمذی، رقم: ٣٢٢، ابن ماجه، رقم: ٧٤٩، ابن خزیمه، رقم: ١٣٠٦، اسناده حسن) اہل علم نے ان متعارض روایات کو یوں جمع کیا ہے کہ ممانعت اہل جاہلیت کے اشعار، باطل و گمراہ فرقوں کے اشعار اور ان اشعار کی ہے جو بے مقصد ہوں اور جو اشعار ایسے نہ ہوں ان کی اجازت ہے۔","",{"k":"صحیح بخاری (٣٢١٢)، مسلم۔"}],[6288,"سیدنا معاویہ بن قره نبی اللہ نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک ایک بار وضو کیا اور فرمایا: ” ” یہ اس شخص کا وضو ہے جس کے بغیر اللہ اس کی نماز قبول نہیں کرتا۔ “ پھر آپ نے دو دو بار وضو کیا اور فرمایا: ”جس نے اس طرح وضو کیا اللہ اس کے لیے اس کے اجر کو دو گنا بڑھا دیتا ہے۔ پھر آپ نے تین تین بار وضو کیا اور فرمایا: ”یہ اچھی طرح وضو کرنا ہے اور یہ میرا وضو ہے اور اللہ کے خلیل ابراہیم عالی نام کا وضو ہے، جس نے اس طرح وضو کیا، پھر فارغ ہونے کے بعد یہ دعا پڑھی: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں وہ یکتا ہے اس کا کوئی شریک نہیں اور یہ کہ محمد ( ملنے ان ) اس کے بندے اور اس کے رسول ہیں، اللہ اس کے لیے جنت کے آٹھوں دروازے کھول دیتا ہے، وہ جس میں سے چاہے داخل ہو جائے۔ اس حدیث کو مرحوم بن عبد العزیز نے عبد الرحیم بن زید، عن ابیہ، عن معاویہ بن قرہ، عن ابیہ عن جدہ کی سند سے روایت کیا ہے اور انجین وغیرہ نے عبد الرحیم بن زید، عن ابیہ، عن معاویہ بن قره، عن ابن عمر کی سند سے روایت کیا ہے۔ عبد اللہ بن عرادہ الشیبانی نے زید اعمی عن معاویہ ابن قرہ بن عبید بن عمیر عن ابی بن کعب کی سند سے روایت کیا۔ سے ثابت ہے۔:٦٢٨٩ مذکورہ بالا روایت ضعیف ہے۔ تاہم ایک مرتبہ، دو مرتبہ، تین مرتبہ وضو کر ناصحیح حدیث","",{"k":"مجمع الزوائد (١/٢٣٩)، سنن ابن ماجه (٤١٩)، سلسله ضعیفه، رقم: ٤٧٣٥ ضعيفه (٤٧٣٥)۔"}],[6289,"نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ زینب بنی لویا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «نفیس چیز کو قبول کرو، سب سے زیادہ نفیس چیز خوشبو ہے، اس کا اٹھانا خفیف تر ہے اور خوشبو کے لحاظ سے بہت اچھی ہے۔“ یہ حدیث سیدہ زینب بنی الجھا سے صرف اس اسناد سے مروی ہے۔ اس میں بشر بن عمیس کا تفرد ہے۔ ٦٢٩٠","",{"k":"مجمع الزوائد (٥/١٥٨)، سلسله ضعیفه (٢٨٦٢)، ضعيف الجامع الصغير (١٠٥٩)۔"}],[6290,"سيدنا جریر رضی اللہ عنہ نے بیان کیا، جب نبی صلے علی تیم مبعوث کیے گئے تو میں آپ مطلئے علیم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: جریر! تم کس طرح ہمارے پاس آئے ہو؟“ میں نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم کے ہاتھ پر اسلام قبول کرنے کے لیے، آپ صلی اللہ علیہ وسلم نے اپنی چادر میری طرف نه ده پھینکی، پھر اپنے اصحاب کی طرف متوجہ ہوئے اور فرمایا: ” جب کسی قوم کا معزز شخص تمہارے پاس آئے تو اس کی عزت کرو۔“ اس حدیث کو اسماعیل بن ابی خالد سے صرف حصین بن عمر الا تمس نے روایت کیا ہے۔","",{"k":"مجمع الزوائد (٨/١٥)، اسناده ضعیف۔"}],[6291,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو استغفار کو لازم کر لیتا ہے اللہ اسے ہر غم سے نجات دے دیتا ہے، ہر تنگی دور کر دیتا ہے اور اسے ایسی جگہ سے رزق فراہم کرتا ہے جہاں سے اس کا وہم وگمان میں بھی نہیں ہوتا۔ یہ حدیث سیدنا عبداللہ ابن عباس نیلی اینجا سے صرف اسی اسناد سے مروی ہے۔ اس میں الولید بن مسلم کا تفرد ہے۔ خاندن مذکورہ روایت ضعیف ہے۔ تاہم استغفار کی اہمیت وفضیلت قرآن و حدیث سے ثابت ہے، استغفار کی برکات کی وجہ سے رزق کی تنگیوں کو یا اور کوئی پریشانی ہو تو اللہ ذوالجلال ختم کر دیتے ہیں، جیسا کہ ارشاد باری تعالیٰ ہے: اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا يُرْسِلِ السَّمَاءَ عَلَيْكُمْ مِدْرَارًا وَيُمْدِدْكُمْ بِأَمْوَالٍ وَبَنِينَ وَيَجْعَلْ لَّكُمْ جَنَّتٍ وَيَجْعَلْ لَّكُمْ أَنْهَرًا» (نوح: ١٠ تا ١٢) اللہ سے بخشش مانگو، بے شک وہ بہت ہی بخشنے والا ہے، وہ تم پر آسمان کو خوب برستا ہوا چھوڑ دے گا اور تمہیں خوب پے در پے مال و اولاد میں ترقی دے گا اور تمہیں باغات دے گا اور تمہارے لیے نہریں نکال دے گا۔“","",{"k":"ابو داود (١٥١٨)، سنن ابن ماجه (٣٨١٩)، قال الشيخ الالباني: ضعيف۔"}],[6292,"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب قضائے حاجت کا ارادہ فرماتے تو بہت دور جاتے تھے۔ اس حدیث کو ہشام بن عروہ سے صرف ابو بجر نے روایت کیا۔ اس میں موسی بن محمد ابن حبان کا تفرد ہے۔ جس علاقے میں قضائے حاجت کے لیے یا جس گھر میں اہتمام نہ ہو تو وہاں کے لوگوں کو چاہیے کہ وہ قضائے حاجت کے لیے آبادی سے دور چلے جائیں تاکہ کسی شخص کی نظر نہ پڑے، لیکن جہاں بیت الخلاء بنے ہوتے ہیں، وہاں دور جانے کی ضرورت نہیں۔ نبی مکرم لے لی ایم کا معمول مبارک انسانی اور اسلامی فطرت کا آئینہ دار ہے جس میں شرم و حیا کو ملحوظ رکھنے کے علاوہ ماحول کی صفائی ستھرائی کے اہتمام کا بھی درس ملتا ہے، مزید یہ کہ آبادی کے ماحول کو کسی طرح بھی آلودہ نہیں ہونا چاہیے۔","",{"k":"صحیح بخاری، رقم: ٣٦٣۔ صحیح مسلم (٧٧/٢٧٤)۔"}],[6293,"سیدنا عبد اللہ ابن عمر بن الہیہ سے روایت ہے کہ نبی ملنے کی تم نے فرمایا: ” سفر میں روزہ رکھنا کوئی نیکی نہیں۔ اس حدیث کو عبید اللہ بن عمر سے صرف محمد بن حرب نے روایت کیا۔","",{"k":"سنن ابن ماجه (١٦٦٥)، قال الشيخ الالباني: صحيح۔"}],[6294,"سیدنا ابو مسعود الانصاری رضی اللہ عنہ نے بیان کیا، سیدنا مصعب بن عمیر رضی اللہ عنہ نے سب سے پہلے مدینہ ہجرت کی، انہوں نے ہی سب سے پہلے وہاں جمعہ پڑھایا، رسول اللہ صلی اللہ علیہ وسلم کی مدینہ تشریف، آوری سے پہلے انہوں نے انہیں جمعہ پڑھایا اور نمازیں پڑھائیں۔“ اس حدیث کو زہری سے صرف صالح بن الاخضر نے اور صالح سے صرف عبد الغفار بن عبید اللہ نے روایت کیا۔ اس میں عباس العنبر ی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/١٧٦)، مجمع البحرين (٩٧٦)، ارواء الغليل ٦٨/٣، اسناده ضعيف . ٦٢٩٥۔"}],[6295,"سیدہ عائشہ بین النہا سے روایت ہے کہ نبی ملنے کی ایم نے فرمایا: ” تم پاک دامنی اختیار کرو، تمہاری خواتین پاک دامنی اختیار کریں گی، اپنے آباء سے اچھا سلوک کرو، تمہاری اولاد تم سے اچھا سلوک کرے گی، جو اپنی کسی غلطی پر اپنے مسلمان بھائی سے معذرت کرے اور وہ اس کی معذرت قبول نہ کرے تو وہ حوض کوثر پر نہیں آئے گا۔ اس حدیث کو عامر بن عبد اللہ بن الزبیر سے صرف عبد المالک بن یحیی بن الزبیر نے روایت کیا۔ اس میں خالد بن یزید العمری کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٣٩/٨)، مجمع البحرين (٢٨٢٧)، ضعيف الجامع الصغير (٣٧١٤)، اسناده ضعيف۔"}],[6296,"سیدنا ابو ہریرہ میل الیہ بیان کرتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے ایک دن اپنے اصحاب سے فرمایا: جبکہ میں موجود تھا۔ اگر تم میں سے کسی کا یہ ستون ہو تو اسے ناپسند ہوگا کہ اسے کاٹ، توڑ دیا جائے تو پھر تم میں سے کوئی کس طرح ارادہ کرتا ہے کہ وہ اپنی نماز کاٹ ڈالے جو کہ اللہ کے لیے ہے، پس تم اپنی نماز مکمل کرو، بے شک اللہ مکمل چیز ہی قبول فرماتا ہے۔ اس حدیث کو بلال بن یحیی بن طلحہ سے صرف عبد الملک بن یحیی بن الزبیر نے روایت کیا۔ اس میں خالد بن یزید العمری کا تفرد ہے۔","",{"k":"كر مجمع الزوائد: ١٢١/٢ مجمع البحرين (٨٥٧)، ضعیف ترغیب و، ترهیب (٢٧٧)، سلسله ضعیفه (٥٢٨٢)۔"}],[6297,"سیدنا عبد اللہ ابن عباس علی الجھا نے بیان کیا، رسول اللہ سے تم نے فرمایا: جبریل علینا) میرے پاس آئے تو انہوں نے کہا: عمر کو سلام کہنا اور اس سے کہنا کہ اس کی رضا حکم ہے اور اس کا ضب غلبہ ہے۔ اس حدیث کو زید العمی سے صرف جریر بن حازم نے روایت کیا۔اس میں خالد بن یزید العمری کا تفرد ہے۔","",{"k":"٦٢٩٧ مجمع الزوائد (٦٩/٩)، مجمع البحرين (٣٦٦٩)، ضعيف الجامع الصغير (٦٩)، سلسله ضعيفه (١٦٨٧)۔"}],[6298,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم کے زمانے میں اپنی اہلیہ سے اس کی دبر ( پیٹھ ) میں جماع کیا، لوگوں نے اس پر اعتراض کیا تو اللہ تعالیٰ نے یہ آیت: ”تمہاری بیویاں تمہاری کھیتی ہیں۔ نازل فرمائی۔ اس حدیث کو ابن ابی ذئب سے صرف ابو صفوان نے روایت کیا۔ لوگوں کا یہ خیال تھا خصوصاً یہودیوں کا کہ اگر عورت کو پیٹ کے بل لٹا کر مباشرت کی جائے تو بچہ بھینگا پیدا ہوتا ہے، اس کی تردید میں مذکورہ بالا آیت نازل ہوئی کہ مباشرت آگے سے کر دیا پیچھے سے یا کروٹ پر جس طرح چاہو جائز ہے، لیکن یہ ضروری ہے کہ ہر صورت میں عورت کی فرج ہی استعمال ہو۔","",{"k":"مجمع الزوائد (٦/٣١٩)، مجمع البحرين (٣٢٩٨)، اسناده حسن۔"}],[6299,"سیدنا ابو ہریرہ منی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم صفہ والوں کے پاس تشریف لائے، ان کی آوازیں بلند تھیں، وہ بہت زیادہ ہنسے، اس سے آپ ملے ناراض ہوئے، پس آپ ل علم نے فرمایا: ”تم بننے کے لیے پیدا نہیں کیے گئے۔ آپ صلی اللہ علیہ وسلم نے ان پر اعتراض کیا تو اللہ عزوجل کی طرف سے سیدنا جبریل عالی نام آپ صلی اللہ علیہ وسلم کے پاس آئے تو انہوں نے کہا: اللہ تعالیٰ آپ نے تم کو حکم فرماتا ہے Seeker کہ آپ صلی اللہ علیہ وسلم آسانی پیدا کریں مشکل نہ بنائیں، خوشخبری سنائیں نفرت نہ دلائیں، پس رسول اللہ ملے عام ان کے پاس تشریف لائے، انہیں خوشخبری سنائی، ان پر خوش ہوئے اور ان سے خندہ پیشانی سے پیش آئے","",{"k":"مجمع الزوائد (٣٠٦/١٠)، اسناده ضعيف۔"}],[6300,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، جب جنتی جنت میں اور جہنمی جہنم میں داخل ہو جائیں گے تو اعلان کرنے والا اعلان کرے گا: جنتیو! ہمیشہ رہنا ہے اس میں موت نہیں اور جہنمیو! ہمیشہ رہنا ہے اس میں کوئی موت نہیں۔ ان دونوں حدیثوں کولیٹ سے صرف عبد العزیز بن بیٹی نے روایت کیا۔ ٦٣٠١","",{"k":"بن يحيى . صحیح بخاری (٦٥٤٥)، سنن ترمذی (٢٥٥٧)۔"}],[6301,"سیدنا عبداللہ ابن عباس بنی انشا سے روایت ہے کہ رسول اللہ سلیم نے فرمایا: دوگر گٹ، چھپکلی مار ڈالو، خواہ وہ کعبہ کے اندر ہو۔“","",{"k":"مجمع الزوائد: د (٤/٤٧)، مجمع البحرين (١٨٧٣)، سلسله ضعیفه (٢٥٢٢)، اسناده ضعيف۔","f":"مذکورہ روایت ضعیف ہے۔ تاہم صحیح روایات سے چھپکلی کو مارنے کا حکم ثابت ہے، بلکہ الله اس کو مارنے کا ثواب بھی ہے، جیسا کہ سیدنا ابو ہریرہ نیا لینے سے مروی ہے نبی معظم ما علیم نے فرمایا: جس نے چھپکلی (یا گرگٹ ) کو پہلی ہی چوٹ میں مار دیا، اس کے لیے ستر نیکیاں ہیں۔ (مسلم، رقم: ٢٢٤٠) بعض روایات میں پہلی چوٹ کے ساتھ مار دینے سے سو نیکیاں ملتی ہیں۔ (مسلم، کتاب السلام، رقم: ٢٢٤٠)"}],[6302,"سیدنا عبداللہ ابن عباس والہا نے بیان کیا، رسول اللہ ملت علی نے فرمایا: ”جو شخص طلوع فجر سے پہلے عرفات پہنچ جائے وہ حج پالیتا ہے۔ ان دونوں حدیثوں کو عطاء سے صرف عمر بن قیس نے روایت کیا۔ مذکورہ روایت ضعیف ہے تاہم یہ حقیقت ہے کہ حج وقوف عرفہ کا نام ہے اور وقوف عرفہ کا وقت نو ذی الحجہ کے دن زوال سے لے کر دس ذی الحجہ کی طلوع فجر تک ہے جو شخص دس ذی الحجہ کی طلوع فجر سے پہلے پہلے گھڑی بھر کے لیے بھی میدان عرفات میں پہنچ جائے اس کا حج ادا ہو جاتا ہے۔ لیکن اگر کسی شخص نے لا علمی سے یا غلطی سے وادی عرفات کی بجائے وادی نمرہ میں وقوف کیا تو اس کا حج ادا نہیں ہو گا، کیونکہ وادی عرفات اور وادی نمرہ دونوں ایک دوسرے سے متصل ہیں، یہ بھی یادر ہے کہ مسجد نمرہ کا ایک حصہ وادی عرفات میں ہے اور دوسرا وادی نمرہ میں مسجد کے اندر بورڈ لگا کر اس کی نشاندہی کی گئی ہے لہذا مسجد نمرہ میں قیام سے قبل حدود عرفات کی تحقیق کر لینی چاہیے تا کہ حج باطل نہ ہو۔: ور للوه","",{"k":"مجمع الزوائد (٢٥٤/٣)، اسناده ضعيف۔"}],[6303,"علقمہ المزنی نے اپنے والد سے روایت کیا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ جس شخص کے گناہوں پر دنیا میں پردہ ڈال دیتا ہے تو وہ آخرت میں بھی اس کے گناہوں پر پردہ ڈالے گا۔“ اس حدیث کو مالک بن دینار سے صرف عباد نے روایت کیا۔ اس میں الفریابی کا تفرد ہے۔","",{"k":"مجمع الزوائد: ١٩٢/١٠ . د (١٠/١٩٢)، مجمع البحرين (١٧٥٨)۔"}],[6304,"سیدہ عائشہ علی النیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے اس آیت: ” وہ اس کی اتباع کرتے ہیں جو اس میں سے متشابہ ( آیات) ہیں۔ سے معنی اخذ کیا، پھر رسول اللہ علیم نے فرمایا: ”اللہ نے تمہیں آگاہ فرمایا ہے، جب تم انہیں دیکھو تو انہیں پہچان لو۔ اس حدیث کو عبد الرحمن بن القاسم سے صرف حماد بن سلمہ نے روایت کیا۔ اس میں الولید کا تفرد ہے اور ان کے علاوہ دیگر نے اسے حماد بن سلمہ عن ابن ابی ملیکہ عن القاسم، عن عائشہ کی سند سے روایت کیا ہے۔","",{"k":"صحیح بخاری (٤٥٤٧)، صحیح مسلم (٢٦٦٥)۔"}],[6305,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی کا اسلام نے فرمایا: ”اللہ نے اپنے حرم کو حرام قرار دیا، پس وہ قیامت کے دن تک حرام ہے، اس کا کوئی درخت کاٹا جائے گا، نہ اس کی گھاس کاٹی جائے گی اور نہ ہی اس کی گری پڑی چیز کو اٹھایا جائے گا سوائے اس کا اعلان کرنے کے اور اس کا شکار بھی حلال نہ سمجھا جائے گا۔‘ اس حدیث کو نافع سے صرف عیسی الحناط نے روایت کیا۔:٦٣٠٦","",{"k":"مجمع الزوائد (٢٨٣/٣)، مجمع البحرين (١٧٩٢)، اسناده ضعيف۔"}],[6306,"سیدنا عمرو بن عبسہ رضی یا لیلی نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو کئی بار فرماتے ہوئے سنا: ”جب مومن بندہ وضوء کرتا ہے، وہ کلی کرتا ہے اور ناک میں پانی داخل کرتا ہے تو اس کی آنکھوں کے کناروں سے گناہ جھڑ جاتے ہیں، جب وہ ہاتھ دھوتا ہے تو اس کے ہاتھوں کے ناخنوں سے گناہ جھڑ جاتے ہیں، جب پاؤں دھوتا ہے تو اس کے پاؤں کے ناخنوں سے گناہ جھڑ جاتے ہیں، پس جب وہ وضو کر لیتا ہے تو یہ اس کے وضو سے اس کا حصہ ہے، پس اگر وہ اللہ عزوجل سے لو لگا کر پوری توجہ کے ساتھ دورکعتیں پڑھتا ہے تو وہ گناہوں سے اس طرح پاک ہو جاتا ہے، جس طرح وہ اپنی پیدائش کے دن گناہوں سے پاک تھا۔ اس حدیث کو ایوب بن موسی سے صرف الضحاک بن عثمان نے روایت کیا۔ اس میں عبد العزیز بن ابی حازم کا تفرد ہے۔ بعض روایات میں ہے کہ جس نے اچھی طرح وضو کیا، اچھی طرح کا مطلب یہ ہے کہ سنت کے مطابق وضو کیا۔ معلوم ہوا کہ وضوسنت کے مطابق کرنا چاہیے اور پھر نماز پڑھے تو دل و توجہ کو نماز میں لگا کر دو رکعت پڑھے۔ ایسا نہیں ہونا چاہیے کہ زبان سے نماز کے الفاظ جاری ہیں، دل سے اپنی دکانداری کا حساب ہو رہا ہے، یا دل اور کسی طرف مشغول ہے، بعض لوگوں کی صورت حال یہ ہے کہ جلدی جلدی اپنی زبان سے نماز کے الفاظ نکالتے ہیں، جس کی سمجھ انسان کو اپنے آپ کو بھی نہیں ہوتی کہ میں کیا پڑھ رہا ہوں۔ نمازی حضرات سے گذارش ہے کہ نماز پڑھیں تو الفاظ پر توجہ ہونی چاہیے اور نماز کا ترجمہ بھی آنا چاہیے اور مومن کی نماز کی کیفیت ((ان تعبد الله كانك تراه)) والی ہونی چاہیے اور دنیا و مافیھا سے غافل ہو جانا چاہیے۔ جیسا کہ خاشعین کی یہ کیفیت ہوتی ہے۔ دو عالم سے کرتی ہے بیگانہ دل کو عجب چیز ہے لذت آشنائی احادیث میں نبی مکرم نے علیم اور صحابہ کرام بھی نیم کی نماز کی کیفیت ملتی ہے کہ دوران نماز کیا ان کی کیفیت ہوا کرتی تھی، یہ تو زمانہ نبوی کی بات ہے۔ آج بھی خاشعین کی ہزاروں مثالیں ملتی ہیں، جیسا کہ حضرت مولنا عبد اللہ غزنوی اللہ جو شیخ الکل حضرت میاں نذیر حسین محدث دہلوی جماللہ کے شاگرد تھے۔ میاں صاحب فرمایا کرتے تھے کہ مولنا عبد اللہ غزنوی حدیث ہم سے پڑھ گیا اور نماز پڑھنی ہمیں سکھا گیا۔ مولنا عبد اللہ اللہ کا نماز میں محویت اور توجہ الی اللہ کا یہ عالم تھا کہ اپنی جان کی خبر نہ رہتی، ایک مرتبہ عصر کی نماز پڑھ رہے تھے کہ یکا یک سخت بارش ہو گئی، ایسی سخت بارش کے مقتدی سب نماز چھوڑ کر بھاگ گئے، صرف دو چار رہ گئے، نماز سے فارغ ہو کر جب دعا کے لیے ہاتھ اٹھائے تو ہاتھ کیچڑ سے بھرے ہوئے تھے، فرمانے لگے، باراں شد، واللہ عبد الله را بے خبر شد، بارش ہوئی اللہ کی قسم! عبد اللہ کو خبر نہیں ہوئی۔ “ ( داؤد غزنوی،ص:١٤)","",{"k":"صحیح مسلم (٨٣٢)، سنن نسائی (١٤٧)۔"}],[6307,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے جس وقت سیدنا علی رضی اللہ عنہ کو یمن کا امیر مقرر کیا تو اس وقت میں ان (علی ولی اللہ ) کے ساتھ تھا۔ پس ان کے ساتھ مجھے بھی کچھ اوقیہ چاندی ملی، جب وہ رسول اللہ علیم کے پاس آئے تو انہوں نے کہا: میں نے سیدہ فاطمہ بنی الوی کو دیکھا کہ انہوں نے گھر کو خوب صافت ستھرا، معطر کر رکھا تھا۔ پس میں نے اسے خطاوار قرار دیا تو انہوں نے (سیدہ فاطمہ بنی ) نے فرمایا: ” آپ کو کیا ہوا؟ رسول اللہ تعلیم نے اپنے اصحاب کو حکم فرمایا تو انہوں نے اپنے احرام کھول دیے۔ انہوں نے بیان کیا: میں نے انہیں کہا: میں نے وہی احرام باندھا جس نیت سے نبی صلی اللہ علیہ وسلم نے احرام باندھا ہے۔ آپ نے فرمایا: ”میں چونکہ قربانی کا جانور ساتھ لایا ہوں اور میں نے حج قران کا احرام باندھا ہے اور آپ نے اپنے اصحاب سے فرمایا: ”جس بات کا مجھے بعد میں پتہ چلا اگر اس کا پہلے پتہ چل جاتا تو میں بھی اسی طرح کرتا جس طرح تم نے کیا ہے، لیکن میں قربانی کا جانور ساتھ لے آیا اور میں نے حج قران کا احرام باندھا۔ آپ نے فرمایا: ”سڑسٹھ یا چھیاسٹھ قربانی کے اونٹ ذبح کرو اور تینتیس یا چونتیس جانور اپنے لیے رکھ لو اور ہر اونٹ سے کچھ حصہ رکھ لو۔ اس حدیث کو ابو اسحاق سے صرف یونس نے روایت کیا۔ اس میں حجاج بن محمد کا تفرد. پیچھے بھی حدیث گزر چکی ہے کہ سیدناعلی بنی اہلیہ نے اسی نیت سے احرام باندھا، جس نیت سے رسول اللہ صلی اللہ علیہ وسلم نے احرام باندھا، تاہم مذکورہ روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سڑسٹھ یا چھیاسٹھ اونٹ نحر کیسے۔ باقی سیدناعلی ضیا اللہ نے نحر کیے۔ تاہم صحیح یہ ہے کہ تریسٹھ قربانیاں نبی معظم تعلیم نے اپنے ہاتھ سے کیں اور بقیہ سیدناعلی یا اللہ کو حکم فرمایا تھا اور انہوں نے کیں۔ (صحیح مسلم، رقم: ١٢١٨) یہ بھی معلوم ہوا کہ قربانی کے جانور پہلے دن ہی ذبح کر دینے چاہئیں البتہ تیرہ ذوالحجہ تک شریعت نے رخصت دی ہے لیکن افضل پہلا دن ہے۔ اسی طرح یہ بھی معلوم ہوا کہ ہر جانور میں سے کچھ نہ کچھ کھانا چاہیے اور ہر جانور میں سے صدقہ بھی کرنا چاہیے، جو لوگ بکرے کا گوشت سارے کا سارا اپنے لیے اور گائے غربا میں تقسیم کر دیتے ہیں، یہ طریقہ درست نہیں۔ ٦٣٠٨","",{"k":"مجمع الزوائد (٢٣٧/٣)، مجمع البحرين (١٧٥١)، سنن ابو داود كتاب المناسك (١٧٩٧)، قال الشيخ الالباني: صحيح۔"}],[6308,"سیدہ عائشہ ولی اینجا نے بیان کیا، جب یہ آیت: ”ان میں سے جس کو چاہیں آپ اپنے سے دور رکھیں اور جس کو چاہیں اپنے پاس رکھیں۔ نازل ہوئی تو اس کے بعد جب ہم میں سے جس اہلیہ کی باری ہوتی تھی ( اور آپ کسی دوسری اہلیہ کے پاس جانا چاہئے ) تو آپ ہم سے اجازت طلب کیا کرتے تھے۔ معاذہ نے کہا: میں نے کہا: تو آپ کیا کہا کرتی تھیں؟ انہوں نے فرمایا: ” میں کہا کرتی تھی: اگر تو یہ میرا حق ہے تو پھر میں اپنی ذات پر کسی دوسری کو ترجیح نہیں دوں گی۔ اس حدیث کو عاصم الاحول سے صرف عباد بن عباد نے روایت کیا۔","",{"k":"صحیح بخاری کتاب التفسیر (٤٧٨٩)، صحیح مسلم (١٤٧٦)۔","f":"اندن مذکورہ بالا آیت میں نبی مکرم مالٹے علیم کے لیے ایک خصوصیت کا بیان ہے وہ یہ کہ بیویوں کے درمیان باریاں مقرر کرنے میں آپ صلی اللہ علیہ وسلم کو اختیار دے دیا گیا تھا، آپ صلی اللہ علیہ وسلم جس کی باری چاہیں موقوف کر دیں، یعنی اسے نکاح میں رکھتے ہوئے اس سے مباشرت نہ کریں اور جس سے چاہیں یہ تعلق قائم رکھیں، لیکن یہ اختیار ملنے کے باوجود رسول اللہ صلی اللہ علیہ وسلم نے اس کو استعمال نہیں کیا۔ البتہ سیدہ سودہ نیا ٹوپا کے (کہ انہوں نے اپنی باری خود ہی سیدہ عائشہ بنایا ہوا کے لیے ہبہ کر دی تھی ) آپ صلی اللہ علیہ وسلم نے تمام ازواج مطہرات کی باریاں برابر مقرر کر رکھی تھیں، اسی لیے آپ ملے عام نے مرض الموت میں ازواج مطہرات سے اجازت لے کر بیماری کے ایام سیدہ عائشہ ریلی لوہا کے پاس گزارے۔ سیدہ عائشہ بنی ہوجا کا اپنے آپ کو ترجیح دینا کسی نفسیانی حظ کی بنا پر نہ تھا بلکہ اس شرف خدمت کی بنا پر تھا جو ان کے قرب سے حاصل ہوتا تھا۔"}],[6309,"سیدنا عبداللہ بن زبیر بنی اہلیہ سے روایت ہے، انہوں نے کہا: میں نے پسند کیا کہ رسول اللہ علیم اذان دینے کی اجازت) ہمیں دے دیں۔ میں نے کہا: کس لیے؟ انہوں نے فرمایا: ”اس لیے کہ وہ قیامت کے دن جنتیوں میں سے سب سے زیادہ لمبی گردنوں والے ہوں گے۔‘ اس حدیث کو ہشام سے صرف عبد اللہ بن محمد بن بیٹی نے روایت کیا۔ اس میں ابراہیم بن المنذر کا تفرد ہے اور ابن الزبیر سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٣٢٦/١)، اسناده ضعیف، عبد اللہ بن محمد بن یحی بن عروہ متروک۔۔","f":"مذکورہ روایت ضعیف ہے۔ تاہم یہ صحیح ہے کہ اذان دینے والوں کی گردن لمبی ہوگی۔ جیسا کہ صحیح مسلم میں ہے، سیدنا معاویہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ سے یمن کو فرماتے ہوئے سنا کہ اذان دینے والے قیامت کے دن دیگر تمام لوگوں سے لمبی گردن والے ہوں گے۔ (مسلم، کتاب الصلاۃ، نم: ٣٨٧) مذکورہ حدیث سے مؤذن کی فضیلت واضح ہے۔ کیونکہ یہ میدان حشر میں ممتاز ہوں گے، ان کی گردنیں سب سے لمبی ہوں گی۔"}],[6310,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد تمہارے کچھ ایسے حکمران ہوں گے، پس نیک اپنی نیکی کے ساتھ تم پر حکمرانی کرے گا اور فاجر اپنے فجور کے ساتھ تم پر حکمرانی کرے گا۔ پس تم ان کی بات سنو اور حق سے موافقت رکھنے والی ہر چیز میں ان کی اطاعت کرو، ان کے پیچھے نماز پڑھو، اگر وہ اچھا کریں گے، تو وہ تمہارے اور ان کے لیے بہتر ہے اور اگر وہ برا کریں گے تو تمہیں اجر ملے گا اور انہیں گناہ ملے گا۔ اس حدیث کو ہشام بن عروہ سے صرف عبد اللہ بن محمد بن عروہ نے روایت کیا۔ اس میں ابراہیم بن المنذر کا تفرد ہے اور ہشام بن عروہ نے ابو صالح سے صرف اسی حدیث کو مسند روایت کیا ہے۔","",{"k":"مجمع الزوائد (٢١٨/٥)، كنز العمال (١٤٨٤٦)، اسناده ضعيف۔"}],[6311,"سیدنا ابو ہریرہ نبی الیہ سے روایت ہے کہ نبی تعلیم نے فرمایا: ”حجاج اور عمرہ کرنے والے اللہ کا وفد ہیں، اگر وہ اس سے دعا کریں تو وہ ان کی دعا قبول فرمائے اور اگر وہ اس سے مغفرت طلب کریں تو وہ انہیں بخش دے۔“ اس حدیث کو یعقوب بن عباد سے صرف صالح بن عبداللہ نے روایت کیا۔ اس میں ابراہیم بن المنذ رکا تفرد ہے۔","",{"k":"سنن ابن ماجه (٢٨٩٢)، قال الشيخ الالباني ضعيف۔"}],[6312,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا: مشکیزے کے منہ سے ( براہ راست منہ لگا کر ) پینے سے منع کیا گیا ہے۔ اس حدیث کو ایوب سے صرف الحارث بن عمیر نے روایت کیا۔ اس میں ابراہیم بن محمد الشافعی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ مشکیزے کے منہ سے پانی پینا صحیح نہیں ہے۔ نبی معظم صلی اللہ علیہ وسلم نے اس کے متعلق فرمایا کہ اس سے وہ بد بودار ہو جاتا ہے ( یعنی مشکیزہ)(سلسله الصحيحة، رقم: ٤٠٠) سنن ابن ماجہ میں ہے کہ رسول اللہ علیم کی ممانعت کے بعد ایک آدمی رات کو اٹھا اور اس نے (پانی پینے کے لیے مشکیزے کا منہ الٹایا تو اس میں سے سانپ نکل آیا۔ (سنن ابن ماجه، رقم: ٣٤١٩) ایک دوسری روایت میں ہے سیدہ کبشہ انصاریہ بنی النوجا سے روایت ہے کہ رسول اللہ صلے علی تیم ان کے ہاں تشریف لے گئے۔ ان کے پاس ایک مشک لٹکی ہوئی تھی۔ چنانچہ آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر اس سے پانی پی لیا۔ (سنن ابن ماجه رقم: ٣٤٢٣، ترمذی، رقم: ١٨٩٢) مذکورہ روایت سے تو معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم نے خود پیا۔ علامہ عبد الرحمان مبارکپوری جماللہ نے اس کا جواب اس طرح دیا ہے کہ ممکن ہے کہ نہی والی احادیث کا تعلق بڑے مشکیزے اور جواز والی حدیث کا تعلق چھوٹے مشکیزے سے ہو۔ (٢) نہی والی احادیث کا تعلق عام حالات سے ہو اور جواز والی حدیث کا تعلق ضرورت اور مجبوری سے ہو۔ (٣) نہی والی احادیث کا تعلق عادت بنا لینے سے ہو اور جواز والی حدیث کا تعلق بعض اوقات کے ساتھ۔ (٤)۔ اجازت والی حدیث نہیں والی احادیث کی ناسخ ہو (تحفة الاحوذی: ١١٤/٣) عصر حاضر میں مشکیزوں کا وجود تقریباً ختم ہو چکا ہے، سوال یہ ہے کہ گھر میں رکھی گئی یا بنائی گئی ٹینکیوں کا بھی یہی حکم ہے کہ ان سے نکلنے والی ٹونٹی سے براہ راست پانی نہ پیا جائے۔ معلوم تو یہی ہوتا ہے کہ مشکیزے اور ٹینکی دونوں کا ایک ہی حکم ہے۔ اسی طرح نلکا کے ساتھ منہ لگا کر پینا اس سے بھی اجتناب کرنا چاہیے۔ میرے ایک عزیز کا واقعہ ہے کہ نلکے کے ساتھ منہ لگا کر پانی پی رہا تھا، منہ الگ کیا تو نلکے سے سانپ نکل آیا۔ ٦٣١٣","",{"k":"صحيح بخاري (٥٦٢٨)، سنن ابو داود (٣٧١٩)۔"}],[6313,"سیدہ ام ہانی بنت ابی طالب نی نیہا نے بیان کیا، میں نے عرض کیا: اللہ کے رسول! میں عمر رسیدہ ہوگئی ہوں، میری ہڈیاں کمزور ہو گئی ہیں، پس آپ صلی اللہ علیہ وسلم مجھے کسی ایسے عمل کے متعلق بتائیں جو مجھے جنت میں داخل کر دے، آپ مطلئے علیم نے فرمایا: ” واہ خوب، واہ خوب، تم نے سوال کیا ہے، سو بارسبحان اللہ کہو وہ تمہارے لیے سو غلام آزاد کرنے سے بہتر ہے، سو بار الحمد للہ کہو، وہ تمہارے لیے اللہ کی راہ میں زین و لگام والے سو گھوڑے دینے سے بہتر ہے اور سو بار اللہ اکبر کہو، وہ تمہارے لیے بیٹے ڈالے ہوئے سو اونٹ بیت اللہ کی طرف روانہ کرنے سے بہتر ہے، تم سو بار لا الہ الا اللہ پڑھو وہ تمہارے لیے آسمان وزمین کی تمام چیزوں سے بہتر ہے، اس روز جیسا تمہارا عمل اوپر جائے گا، اس سے بہتر کسی اور کا عمل اوپر نہیں جائے گا، سوائے اس کے جس نے ویسے ہی کلمات کہے جیسے تم نے کہے یا اس سے زیادہ بار کہے۔ اس حدیث کو ابن شوذب سے صرف ضمرہ بن ربیعہ نے روایت کیا۔ دور و مذکورہ حدیث سے اللہ ذوالجلال کے ذکر کی فضیلت ثابت ہوتی ہے اور سوسو دفعہ سُبْحَانَ اللهِ، اَلْحَمْدُ لِلَّهِ، اللهُ أَكْبَرُ، لا اله الا اللہ کہنے کا عظیم ثواب بھی ثابت ہوتا ہے۔ یہ بھی معلوم ہوا کہ ضعیف آدمی کو زیادہ سے زیادہ اللہ ذوالجلال کے ذکر میں مشغول ہونا چاہے اور یہ بھی معلوم ہوا کہ جو شخص بڑے بڑے اعمال انجام نہ دے سکتا ہو، اس کے لیے اللہ کا ذکر ان اعمال سے بہتر ہے۔","",{"k":"مجمع الزوائد (١٠/٩٢)، سلسله صحیحه (١٣١٢)، صحیح ترغیب و ترهيب (١٥٥٣)، قال الشيخ الالباني: حسن۔"}],[6314,"سیدنا عبداللہ ابن عباس نیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ بیت اللہ والوں پر روزانہ ایک سو میں رحمتیں نازل فرماتا ہے، ان میں سے ساٹھ طواف کرنے والوں کے لیے، چالیس نماز پڑھنے والوں کے لیے اور ہمیں دیکھنے والوں کے لیے ہیں۔ اس حدیث کو اوزاعی سے صرف عبد الرحمن بن السفر نے روایت کیا۔ ٦٣١٥","",{"k":"مجمع الزوائد (٣/٢٩٢)، مجمع البحرين (١٧٩٦)، سلسله ضعيفه : (١٨٧)، ضعیف ترغیب و ترهیب (٧٢٢)، اسناده ضعيف۔"}],[6315,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ملے عام مسجد تعمیر کر رہے تھے اور عمار بن یاسر بی این دو پتھر اٹھاتے تھے۔ آپ ملنے سلیم نے فرمایا: ”سمیہ کے بیٹے! بہت خوب، باغی گروہ تجھے قتل کرے گا۔“ اس حدیث کو حماد بن سلمہ سے بنو ہاشم کے آزاد کردہ غلام ابوسعید نے روایت کیا۔ اس میں احمد بن عمر الرازی کا تفرد ہے۔ سیدنا عمار بن یاسر فضل اللہ بڑے جلیل القدر صحابی اور نبی معظم صلی اللہ علیہ وسلم کے سچے جان نثار تھے۔ ان کی ماں سیدہ سمیہ بنی اٹھوا بھی بڑے عزم وایقان والی خاتون گذری ہیں جن کو شہید کر دیا گیا تھا۔ نبی معظم صلی اللہ علیہ وسلم نے جو پیش گوئی فرمائی وہ ثابت ہوئی۔ سیدنا عمر رضی اللہ عنہ کو صفین میں ٩١ سال کی عمر میں شہید کر دیا گیا۔ بعض نے آپ رضی اللہ عنہ کی عمر ٩٣ اور ٩٤ سال بھی بیان کی ہے، آپ میل کو ابو العادیہ نے نیزہ مارا تو آپ نیا لینے گر پڑے، پھر ایک شخص نے آپ نوال اللہ پر جھک کر آپ رضی اللہ عنہ کا سر کاٹ لیا، پھر وہ دونوں سیدنا معاویہ ضیا الیہ کے پاس جھگڑا لے کر گئے کہ ان دونوں میں سے کس نے آپ نیل اللہ کو قتل کیا ہے تو سیدنا عمرو بن: عاص رضی اللہ عنہ نے ان دونوں سے کہا کیا تم دونوں کو معلوم ہے؟ اللہ کی قسم! تم دونوں تو دوزخ کے بارے میں جھگڑا کر رہے ہو۔ (دیکھئے: البدايه والنهايه جلد نمبر ٧، حالات سیدنا عمار ٣٧ هجری)","",{"k":"کر مجمع الزوائد (٢٤٢/٧)، مجمع البحرين (٤٣٣٠)، صحيح الجامع الصغير (٤١٠١)، اسناده حسن۔"}],[6316,"سیدہ عائشہ منی نیپا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حسین نبی الیہ کو اپنی ران پر بٹھایا، تو سیدنا جبریل علیہ سلام آپ صلی اللہ علیہ وسلم کے پاس آئے، انہوں نے کہا: یہ آپ کا بیٹا ہے؟ آپ ملنے لیے تم نے فرمایا: ”ہاں۔ انہوں نے کہا: آپ کے بعد آپ کی امت اسے قتل کر دے گی، پس رسول اللہ صلی اللہ علیہ وسلم کی آنکھیں اشک بار ہو گئیں، انہوں نے کہا: اگر آپ چاہیں تو میں اس جگہ کی مٹی آپ کو دکھا دوں، جہاں اسے شہید کیا جائے گا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں۔ پس سیدنا جبریل عالی نام الطف (کربلا) کی مٹی آپ صلی اللہ علیہ وسلم کے پاس لائے۔“ اس حدیث کو ایوب سے صرف حمادالدیناری نے روایت کیا۔ نان مذکورہ حدیث سے معلوم ہوا کہ شہادت سیدنا حسی نیل الیہ کی خبر آپ صلی اللہ علیہ وسلم کو فرشتے نے آکر دی اور نبی معظم ملنے کی یہ سنتے ہی بے اختیار رو پڑے اور شدت غم کا اظہار فرمایا۔ معلوم ہوا کہ سیدنا حسین ولی اللہ کی شہادت برحق ہے، مگر افسوس صد افسوس کہ کچھ لوگ سیدنا حسین نبی الیہ کو باغی، سلطنت کا حریص اور خطا کار ثابت کرتے ہیں اور اس المناک واقعہ پر افسردگی کی بجائے، اس کے چہرے پر، ان کی قلم سے گستاخی و بے ادبی کے جذبات اور جراثیم ظاہر ہوتے ہیں۔ سیدنا حسین رضی اللہ عنہما جب ٦١ ہجری میں شہید کر دیے گئے تو سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے فرمایا: میں نے ایک دو پہر کے وقت رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جس طرح سونے والا (خواب) دیکھتا ہے، پراگندہ اور خاک آلود پاؤں تھے، آپ کے ہاتھ میں ایک چھوٹی سی بوتل تھی، جس میں خون تھا۔ میں نے کہا: میرے ماں باپ آپ پر قربان! یہ کیا ہے؟ فرمایا: یہ سیدنا حسین رضی اللہ عنہما اور اس کے ساتھیوں کا خون ہے، جس کو میں آج اکٹھا کرتا رہا ہوں۔ سیدنا عبد اللہ ابن عباس نئی پوچھا کہتے ہیں، میں نے اس دن کو یا د رکھا تو میں نے پایا کہ ان کو اسی دن قتل کیا گیا۔ (مسند احمد: ٢٤٢/١، اسنادہ حسن)","",{"k":"مجمع الزوائد (٩/١٨٧)، اسناده حسن۔"}],[6317,"سیدنا جبیر بن مطعم رضی اللہ عنہ نے بیان کیا، میرا گدھا گم ہو گیا، میں اسے تلاش کرنے کے لیے عرفات کی طرف آیا، پس میں نے رسول اللہ صلی اللہ علیہ وسلم کو عرفات میں دیکھا، ان کے ساتھ سیدنا ابو بکر رضی اللہ عنہ تھے، آپ صلی اللہ علیہ وسلم قریش کے مواقف پر وقوف کرتے تھے۔ اس حدیث کو عثمان بن الاسود سے صرف عبد اللہ بن القاسم نے روایت کیا۔ اس میں زہدم کا تفرد ہے۔","",{"k":"صحیح بخاری (١٦٦٤)، مسلم (١٢٢٠)۔","f":"مانہ جاہلیت میں تمام لوگ عرفات میں وقوف کرتے تھے لیکن قریش عرفات میں وقوف نہیں کرتے تھے بلکہ وہ مزدلفہ سے ہی لوٹ آتے تھے۔ سیدنا جبیر بن مطعم نبی اللہ کے کہنے کا مطلب یہ تھا کہ نبی معظم مم اور سیدنا ابو بکر یا اللہ قریش میں سے تھے اور انہوں نے عرفات میں وقوف کیا۔ دیکھئے: ( بخاری، رقم: ١٦٦٤، مسلم، رقم: ١٢٢٠) ارشاد باری تعالیٰ ہے: افِيْضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللهَ ﴾ (البقرة: ١٩٩) ٨٠٦٥٠ تم اس جگہ سے لوٹو جس جگہ سے سب لوگ لوٹتے ہیں اور اللہ تعالیٰ سے بخشش طلب کرتے رہو۔“ ٦٣١٨"}],[6318,"سیدنا ولید بن عبادہ بن صامت سے روایت ہے کہ جب ان کے والد سیدنا عبادہ بن صامت رضی اللہ عنہ کی وفات کا وقت قریب آیا تو ان کے بیٹے عبد اللہ نے انہیں کہا: ابا جی! مجھے وصیت فرمائیں۔ انہوں نے کہا: مجھے میرے بیٹے کی خاطر بٹھاؤ۔ پس انہوں نے انہیں بٹھایا تو انہوں نے کہا: بیٹا: اللہ سے ڈر اور تم اللہ کا تقویٰ اختیار نہیں کر سکو گے، حتی کہ تم اللہ پر ایمان لاؤ اور تم جان لو کہ تم کو جو تکلیف پہنچی ہے وہ تم سے چوک نہیں سکتی تھی اور جو تم سے چوک گئی وہ تمہیں پہنچ نہیں سکتی تھی۔ میں نے رسول اللہ میم کو فرماتے ہوئے سنا: تقدیر اس پر ہے، جو اس کے غیر پر فوت ہوا، اللہ اسے جہنم میں داخل کرے گا۔“ اس حدیث کو سلیمان بن حبیب المحاربی سے صرف عثمان بن ابی العاتکہ نے روایت کیا۔ اس میں الولید کا تفرد ہے۔ ٦٣١٩","",{"k":"مجمع الزوائد (١١٨/٧)۔"}],[6319,"سیدنا عبداللہ ابن عم رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کی نعمتوں کے بارے میں غور وفکر کرو اور اللہ کی ذات کے بارے میں غور وفکر نہ کرو۔ اس حدیث کو سالم سے صرف الوازع نے روایت کیا۔ اس میں علی بن ثابت کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ اللہ ذوالجلال کی ذات میں نہیں بلکہ اس کے انعامات میں غور وفکر کرنا چاہیے۔ کیونکہ جو اللہ ذوالجلال کی تخلیق زمین و آسمان اور کائنات کے دیگر اسرار و رموز پر غور کرتے ہیں، انہیں کائنات کے خالق اور اس کے اصل فرمانروا کی معرفت حاصل ہو جاتی ہے اور وہ سمجھ جاتے ہیں کہ اتنی طویل و عریض کائنات کے اس ترتیب شدہ نظام کے پیچھے ایک ذات ہے جو اس کو چلا رہی ہے اور وہ اللہ تعالیٰ کی ذات ہے۔ ارشاد باری تعالیٰ ہے۔ إِنَّ فِي خَلْقِ السَّمَوتِ وَالْأَرْضِ وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ لَايَتِ لِأُولِي الْأَلْبَابِ فِي (آل عمران: ١١٩) آسمانوں اور زمین کی پیدائش میں اور رات اور دن کے ہیر پھیر میں یقینا عقل مندوں کے۔ نشانیاں ہیں۔“ ٦٣٢٠","",{"k":"مجمع الزوائد (١/٨١)، مجمع البحرين (٧١)، صحيح الجامع الصغير (٢٩٧٥)، سلسله صحیحه (١٧٨٨)۔"}],[6320,"سیدنا عبد اللہ بن الحارث بن جزء الزبیدی رضی اللہ عنہ نے بیان کیا، ہم ایک دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں تھے، آپ نے ہمارے لیے کھانا تیار کیا، پس ہم نے کھایا، پھر نماز کے لیے اقامت کہی گئی، پس ہم نے نماز پڑھی اور ہم نے (نیا) وضو نہ کیا۔ اس حدیث کو عقبہ بن مسلم سے صرف حیوہ بن شریح نے روایت کیا۔","",{"k":"سنن ابو داود، مما مست النار (١٩٣)، مسند احمد (٤/١٩٠)، ابن ماجه (٣٣١١)، قال شعیب الارناؤط: صحيح۔","f":"قانون مذکورہ حدیث سے معلوم ہوا کہ آگ پر پکی ہوئی چیز کھانے سے وضو نہیں ٹوٹتا، جس روایت میں ہے کہ ٹوٹ جاتا ہے وہ حکم منسوخ ہے۔"}],[6321,"سیدہ عائشہ بنی النیہا نے بیان کیا، مجھے اور نبی ملے عام کی زوجہ محترمہ سیدہ حفصہ علی النیها کو کھانے کا ہدیہ پیش کیا گیا۔ ہم دونوں روزہ دار تھیں ہم میں سے ایک نے اپنی ساتھ والی سے کہا: کیا تم روزہ افطار کرنا چاہتی ہو؟ اس نے کہا: ہاں، پس ہم نے روزہ توڑ ڈالا۔ پھر رسول اللہ لئے علیم ہمارے ہاں تشریف لائے تو ہم نے عرض کیا: اللہ کے رسول! ہمیں ہدیہ پیش کیا گیا، ہمیں اس کی بہت خواہش ہوئی تو ہم نے روزہ توڑ دیا۔ پس نبی صلی اللہ علیہ وسلم نے فرمایا: تم پر کوئی مواخذہ نہیں، اس کی جگہ ایک دن کا روزہ رکھ لو۔“ عروہ کے آزاد کردہ غلام زمیل سے اس حدیث کو صرف ابن الہاد نے روایت کیا ہے۔ اس میں حیوہ کا تفرد ہے۔ ٦٣٢٢","",{"k":"سنن ابو داود (٢٤٥٧)، سنن ترمذی (٧٣٥)، قال الشيخ الالباني: ضعيف۔"}],[6322,"سیدنا علی رضی اللہ عنہ نے بیان کیا، جب ابو طالب فوت ہوئے تو میں رسول اللہ لئے علیم کے پاس آیا، اور کہا: آپ کے بوڑھے چچا فوت ہو گئے ہیں آپ ملت علی ایم نے فرمایا: ”جاؤ اسے دفن کرو اور کوئی بات نہ کرناحتی کہ تم میرے پاس آجاؤ۔ پس میں نے انہیں دفن کیا، پھر آپ صلی اللہ علیہ وسلم کے پاس آیا تو آپ کیا نے فرمایا: ”جا غسل کر اور کوئی بات نہ کرنا حتی کہ تم میرے پاس آجاؤ، پس میں نے غسل کیا، پھر آپ ملنے کی ایم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے میرے لیے دعائیں کیں، ان کے بدلے میں سرخ اونٹ لینا مجھے پسند نہیں۔“ اس حدیث کو السد ی سے صرف یحیی بن یزید نے روایت کیا۔ جناب ابو طالب کی وفات اسلام پر نہیں ہوئی بلکہ کفر پر ہوئی تھی۔ اس لیے نبی معظم من علم نے نماز جنازہ کے بغیر دفن کرنے کا حکم دیا تھا۔ ارشاد باری تعالیٰ ہے: ما كَانَ لِلنَّبِي وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَ لَوْ كَانُوا أُولِي قُرْنِي (التوبه: ١١٣) د نبی تعلیم اور دوسرے مسلمانوں کے لیے یہ جائز نہیں کہ مشرکین کے لیے مغفرت کی دعا کریں، اگر چہ وہ قریبی رشتہ دار ہی ہوں۔“ امام نووی اللہ نے فرمایا: کافر کی نماز جنازہ اور اس کے لیے بخشش کی دعا کرنا نص قرآن اور اجماع امت کی وجہ سے حرام ہے۔ (المجموع: ١٤٤/٥) شیخ البانی اللہ بھی اسی کے قائل ہیں۔ (احکام الجنائز: ص ١٢٠) مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ بعد از دفن غسل کرنا مسنون ہے۔ ٦٣٢٣","",{"k":"سنن ابو داود (٣٢١٤)، سنن نسائی، قال الشيخ الالباني: صحيح۔"}],[6323,"سیدنا عمرو بن شعیب نے اپنے والد سے، انہوں نے اس کے دادا سے روایت کیا، انہوں نے کہا: رسول اللہ علیم نے فرمایا: ” دو مختلف دینوں کے پیروکار ایک دوسرے کی کسی چیز میں وارث نہیں بنیں گے۔ اس حدیث کو یعقوب بن عطا سے صرف سفیان نے روایت کیا۔ اس میں سعید بن منصور کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ اختلاف دین وراثت کے مواقع میں سے ہے۔ اس بات میں اختلاف کیا گیا ہے کہ دو مختلف دین والوں سے مراد صرف مسلمان اور کافر ہیں، یا کفار کے مختلف ادیان بھی اس میں شامل ہیں۔ امام اوزاعی جداللہ حدیث کی عمومیت کی بنا پر تمام ملتوں کو اسی میں شامل کرتے ہیں اور فرماتے ہیں: کہ یہودی، عیسائی کا اور عیسائی یہودی کا بھی وارث نہیں بن سکتا۔ جمہور اہل علم کے نزدیک اس سے مراد کفر","",{"k":"سنن ابو داود، المسلم الكافر (٢٩١١)، قال الشيخ الالباني: حسن صحيح۔","f":"اور اسلام ہے۔ کافر ایک دوسرے کے وارث ہو سکتے ہیں۔ شیخ عبد اللہ بسام اللہ اور امام صنعانی رحمہ اللہ نے امام اوزاعی ہراللہ وغیرہ کے موقف کو ترجیح دی ہے۔ (سبل السلام، رقم: ٣/ ٢٤٧، توضیح الاحكام: ١٦٢/٥) ٦٣٢٤"}],[6324,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ سے تم نے فرمایا: ”سات قسم کے لوگوں کو اللہ اپنے سائے تلے جگہ نصیب فرمائے گا، جس روز صرف اسی کا سایہ ہوگا، عادل حکمران، نوجوان جو اللہ کی عبادت کے لیے پروان چڑھا، دو آدمی جو اللہ کی رضا کی خاطر محبت کرتے ہیں، اسی پر ملتے اور جدا ہوتے ہیں، ایک آدمی جس کا دل مسجد کے ساتھ معلق رہتا ہے جو اگر وہاں سے نکلتا ہے حتی کہ وہاں واپس آ جاتا ہے، ایک آدمی جسے کوئی حسب و منصب والی عورت برائی کی دعوت دے تو وہ کہے: میں اللہ سے ڈرتا ہوں، ایک وہ جس نے صدقہ کیا اور اسے اپنی بائیں جانب سے بھی چھپایا، حتی کہ اس کا بایاں (ہاتھ ) نہیں جانتا جو اس کا دایاں (ہاتھ ) خرچ کرتا ہے، ایک وہ آدمی جس نے اللہ کو یاد کیا تو اس کی آنکھیں اشک بار ہو گئیں۔“ خاندان (١) مذکورہ حدیث سے اللہ ذوالجلال کے عرش کا اثبات ہوتا ہے۔ (٢) قیامت کے دن کائنات بھر کے لوگ میدان محشر میں جمع ہوں گے اور جسموں پر کپڑا نہیں ہوگا اور سایہ بھی نہیں ہو گا، سورج لوگوں کے بالکل قریب ہوگا اور پوری قوت سے چمک رہا ہوں گا۔ اتنی شدت کی آگ سورج برسائے گا کہ کبھی بھی اس طرح کی گرمی نہیں ہو گی۔ بعض لوگ گرمی کی وجہ سے پسینوں میں ڈوبے ہوئے ہوں گے۔ ایسے پریشان کن ماحول میں لوگ سایہ کی تلاش میں ارد گرد دیکھیں گے، لیکن کہیں سایہ نظر نہ آئے گا، لیکن صرف اللہ ذوالجلال کے عرش کے نیچے بڑا خوبصورت اور ٹھنڈا سایہ ہو گا، وہ بھی چند خوبی کے حامل درج ذیل خوش نصیب لوگوں کو نصیب ہوگا۔ (١) عدل کرنے والا امام: حافظ ابن حجر عسقلانی اللہ امام کے متعلق وضاحت فرماتے ہیں: ((والمراد به صاحب الولاية العظمى و يتعلق به کل من ولی شيئا من امور المسلمين فعدل فيه )) (فتح الباری: ٢/ ١٨٤، مكتبه (قدیمی) امام سے مراد وہ آدمی ہے جسے ولایت عظمی حاصل ہو اور اس کے ساتھ ہر وہ شخص بھی شامل ہے جسے مسلمانوں کے آپس کے معاملات میں سے کسی معاملہ میں حق ولایت حاصل ہو اور وہ اس میں عدل سے کام لے۔“ معلوم ہوا کہ انصاف کرنے والا شخص خواہ وہ کسی ملک کا حکمران ہو یا صوبے کا وزیر، گورنر، کسی شہر کا ناظم، اپنے حلقے کا ایم این اے، کوئی معمولی افسر، گاؤں کا چوہدری، کسی کالج یا مدرسے کا سربراہ، اگر اس نے اپنے ماتحت لوگوں کے ساتھ انصاف کیا تو اللہ ذوالجلال اسے اپنے عرش کا سایہ عطا کرے گا۔ (٢) وہ خوش نصیب جو اپنی جوانی کو اللہ تعالیٰ کی عبادت میں کھپا دینے والا، اس کو بھی اللہ ذوالجلال اپنے عرش کا سایہ عطا کرے گا۔ چوں کہ جوانی میں خواہشات زیادہ ہوتی ہیں اس لیے اگر آدمی برائی کرنا چاہے تو ہاتھ پاؤں اسے قوت فراہم کرتے ہیں نیز جوانی میں جذبات بھی زیادہ غالب ہوتے ہیں عربی کا ایک مقولہ ہے ((الشباب شعبة من الجنون)) جوانی دیوانگی کی ایک قسم ہے۔ اور جوانی میں عبادت کرنا پیغمبرانہ کام ہے۔ جیسا کہ شیخ سعدی اللہ نے اس کا بڑا اچھا نقشہ کھینچا ہے۔ جوانی تو به کردن شیوه پیغمبری ست وقت پیری گرگ ظالم می شود پر ہیز گار جوانی میں تو بہ پیغمبرانہ شیوہ ہے۔ بڑھاپے کے وقت ظالم بھیڑیا بھی پر ہیز گار بن جاتا ہے“ (٣) تیسرا ان خوش نصیب لوگوں کا گروہ ہے جو اللہ ذوالجلال کی خاطر آپس میں محبت کرنے والے، اس کی وجہ سے جمع ہوتے ہیں اور اس کی رضا کے لیے جدا ہوتے، یعنی دنیاوی محبت نہیں کہ انہیں ایک دوسرے سے کوئی مفاد ہو، یا کوئی دنیاوی غرض ہو، یا کوئی ذاتی مقصد ہو بلکہ ایسی پر خلوص محبت ہے، جس کی بنیاد حاصل رضائے الہی اور اطاعت رسول ملنے دیتی ہے۔ خدانخواستہ کبھی اس محبت کو خیر باد کہہ کر جدائی کی نوبت آئے تو اس کی بنیاد بھی رضائے الہی ہو، یہ کام بڑا مشکل ہے، لیکن اللہ ذوالجلال نے اس کا اجر بہت عظیم رکھا ہے۔ اجر کیا ہے؟ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ ذوالجلال قیامت کے دن فرمائیں گے: میری الله SKI عظمت و جلالت کے لیے باہم محبت کرنے والے کہاں ہیں؟ (اليوم اظلهم في ظلي يوم لا ظل الاظلي)) (مسلم، كتاب البر والصلة، رقم: ٢٥٦٦) ”آج میں ان کو اپنے سائے میں جگہ دوں گا جس دن میرے سائے کے علاوہ کوئی سایہ نہیں۔“ (٤) وہ خوش نصیب بھی عرش الہی کے نیچے ہو گا جو مسجد سے محبت کرتا ہے۔ ((رجل قلبه معلق في المساجد)) یعنی ایسی کیفیت دل کی ہوتی ہے کہ نماز پڑھی، گھر واپس آ گیا، کاروبار میں مصروف ہے یا دوستوں کی محفل میں ہے، جہاں بھی ہے، اسے دوسری نماز کا دھیان ہے، انتظار کر رہا ہے جیسے ہی اذان ہوئی مسجد کی جانب چل دیا، وہ مسجد سے باہر بے قرار رہتا ہے، اس کا وجود اگر چہ مسجد سے باہر ہے لیکن دل مسجد میں اٹکا ہوا ہے۔ امام مالک ہراللہ اس کی وضاحت اس طرح کرتے ہیں۔ (( رجل قلبه معلق بالمساجد اذا خرج منه حتى يعود اليه)) اس سے مراد وہ شخص ہے کہ جب وہ مسجد سے باہر آتا ہے تو جب تک دوبارہ مسجد میں نہ لوٹ آئے اس کا دل مسجد کی طرف لگا رہتا ہے۔ (موطا امام مالك، كتاب الجامع، باب ما جاء متى بين في الله) (٥) وہ خوش نصیب بھی عرش الہی کے سائے تلے ہو گا جو برائی کی دعوت پر منہ موڑ لیتا ہے۔ حدیث کے الفاظ ہیں: ((رجل دعته امراة ذات حسب و منصب الى نفسها حدیث میں جو الفاظ ہیں امراۃ ذات حسب و منصب، اس کا مطلب ہے کہ برائی کی دعوت دینے والی عورت حسب و نسب والی ہو، یعنی وہ عورت بازاری نہ ہو، کیونکہ بازاری عورتوں سے تو ہر کوئی دامن بچا کر گزرتا ہے کہ کہیں اس کی برائی کے چھینٹے مجھے رسوا نہ کر دیں، مگر جب عورت بھی بازاری نہ ہو، خاندانی اور حسن و جمال والی ہے، ایسے میں بڑے بڑے پارسا بھی بہک جاتے ہیں، اس وقت اللہ تعالی گناہ سے بچنے کی توفیق دے دے تو یہ کمال ہے، ایسے باکمال کام کا اجر بھی عظیم ہے۔ (٢) وہ خوش نصیب جو بروز محشر قیامت کی سختیوں سے محفوظ اللہ تعالیٰ کے عرش کے سایہ میں ہوگا، وہ ہے جو صدقہ تو کرتا ہے لیکن انتہائی راز داری کے ساتھ، ریا کاری اس کے ذہن میں نہیں ہوتی، چپکے سے کسی ضرورت مند کی مدد کرتا ہے، مقصد یہ ہے کہ اللہ ذوالجلال راضی ہو جائے۔ (٧) تنہائیوں میں خوف الہی سے آنسو بہانے والا خوش نصیب بھی عرش الہی کے نیچے ہو گا۔ کیونکہ تنہائی میں انسان کی صحیح حقیقت کھلتی ہے کہ وہ کیا ہے؟ دوسروں کے سامنے تو وہ ڈھونگ رچا کر اپنے آپ کو جو چاہے ظاہر کر سکتا ہے، لیکن خلوت میں اس کی اصلی شخصیت اس کے سامنے آجاتی ہے، وہاں اسے دیکھنے والا تو صرف اللہ تعالیٰ: ٦٣٢٥ ہی ہوتا ہے، ایسے میں جو اس کے خوف سے اشک بہاتا ہے، اس پر رحمت باری تعالیٰ مہربان ہو جاتی ہے۔","",{"k":"صحیح بخاری (٦٦٠)، مسلم (١٠٣١)۔"}],[6325,"سیدنا ابو ہریرہ رضی علینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی جوتے پہنے تو وہ ( پہلے ) دایاں پہنے اور جب اتارے تو پہلے بایاں اتارے، یا پھر وہ دونوں جوتے اتارے یا دونوں پہنے۔ ان دونوں حدیثوں کو سعید بن ابی الابیض سے صرف القعنبی نے روایت کیا۔ ماندن مذکورہ حدیث میں جوتا پہننے کے آداب بتائے جا رہے ہیں۔ پہننے میں دایاں اور اتارنے میں پہلے بایاں۔ یہ بھی معلوم ہوا کہ ایک جوتا پہن کر چلنا نہیں چاہیے، کیونکہ جوتے کا مقصود پاؤں کو تکلیف دہ چیزوں مثلاً کانٹے وغیرہ سے بچانا ہوتا ہے، جب صرف ایک پاؤں میں جوتا ہو تو دوسرے پاؤں کو بچانے کے لیے خاصی جدو جہد کرنا پڑتی ہے جس سے اس کی معمول کی چال برقرار نہیں رہتی، نہ ہی جسم کا توازن درست رہتا ہے اور پاؤں میں موچ آنے کا خطرہ ہوتا ہے، اس کی کوشش میں آدمی گر بھی سکتا ہے۔ بظاہر یہ حکمتیں معلوم ہوتی ہیں، مگر ہر حکم کی اصل علت اللہ ذوالجلال ہی جانتا ہے۔","",{"k":"صحیح بخاری (٥٨٥٦)، صحیح مسلم (٣٠٩٧)۔"}],[6326,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”کتوں کو مار ڈالو۔ آپ نے یہ بلند آواز سے فرمایا۔“ صحیح مسلم میں سیدنا جابر بن عبد اللہ ہی اللہ سے روایت ہے کہ رسول اللہ میم نے کتوں کے مارنے کا حکم دیا، یہاں تک کہ عورت جنگل سے اپنا کتا لے کر آتی تو ہم اس کو مار ڈالتے۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے ہمیں اس سے منع کر دیا۔ نیز فرمایا: صرف کالے کتوں کو مارو۔ (مسلم، کتاب المساقاة، رقم: ١٥٧٢) معلوم ہوا کہ کتوں کو مارنے کا حکم منسوخ ہو چکا ہے اور اس روایت میں بھی کالا کتا مراد ہے اور اسی طرح جس کی آنکھوں پر دو نقطے ہوں، یہ دونوں خطرناک ہیں، لہذا ان کو قتل کرنا چاہیے اور اسی طرح اگر کسی آبادی میں عام کتنے بڑھ جائیں اور لوگوں کے لیے اذیت کا باعث ہوں تو ان کو قتل کرنا اور کم کرنا بھی جائز ہے، لیکن بالکل فنا کر دینا جائز نہیں۔ ٦٣٢٧","",{"k":"صحیح بخاری (٣٣٢٣)۔"}],[6327,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ ملنے کی کھجور کی بیع سے منع کیا کرتے تھے، حتی کہ اس کی پختگی ظاہر ہو جائے اور آپ بیع مزابنہ سے منع کرتے تھے۔“ ان دونوں حدیثوں کو زہری سے صرف یونس نے اور یونس سے صرف شبیب بن سعید نے روایت کیا۔ ان دونوں میں احمد بن شبیب کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ جب تک کھجور کی پختگی ظاہر نہ ہو جائے اس کی بیع جائز نہیں، کیونکہ کچی کھجور کا صحیح اندازہ نہیں ہو سکتا کہ وہ پک کر کتنی رہ جائے گی، اس میں دھوکہ ہے، لہذا اس لیے منع ہے۔ (٢) اس طرح بیع مزابنہ بھی ناجائز ہے۔ مزابنہ کا مطلب یہ ہے کہ درختوں پر لگے ہوئے پھل کو اسی جنس کے اتارے ہوئے خشک پھل کے عوض فروخت کرنا، مثلاً کھجوروں کے بدلے کھجور کے درخت پر لگی تازہ اور تر کھجوروں کی بیچ اور انگور کے بدلے خشک (یعنی کشمش) کی بیع وغیرہ۔ اس میں حرمت کا سبب یہ ہے کہ ترکھیتی یا تر میوے کی صحیح مقدار کا علم نہیں ہوتا کہ وہ خشک ہو کر کنارہ جائے گا، اسی طرح کسی کا بھی نقصان ہوسکتا ہے۔ RSS ٦:٣٢٨","",{"k":"صحیح بخاری (٢١٨٥)، صحیح مسلم (١٥٤٢)۔"}],[6328,"سیدنا سمرہ بن جندب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”موت سے فرار ہونے والے کی مثال اس لومڑ کی مانند ہے جسے زمین قرض کی وجہ سے تلاش کرتی ہے پس وہ دوڑتا ہے، حتی کہ جب وہ تھک گیا اور سانس پھول گئی تو وہ اپنے بل میں داخل ہو گیا تو زمین نے اسے کہا: لومر! میرا قرض، پس وہ باہر نکلا اور بہت تیز دوڑا، پس وہ اسی طرح رہتا ہے حتی کہ اس کی گردن کٹ جاتی ہے تو وہ مر جاتا ہے۔ اس حدیث کو یونس سے صرف معاذ بن محمد الہد لی سیدنا ابو بکر الہدلی کے بھائی نے روایت کیا اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٢/٣٢٠)، ضعفاء العقيلي (٢٠٠/٤)۔"}],[6329,"سیدہ عائشہ ولی اللہا نے بیان کیا، رسول اللہ صل علی کو نماز کی اطلاع دی گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائے۔“ پھر آپ صلی اللہ علیہ وسلم بے ہوش ہو گئے، جب وہ کیفیت جاتی رہی تو آپ ملے سلیم نے فرمایا: تم نے ابو بکر سے کہہ دیا کہ وہ لوگوں کو نماز پڑھائے؟“ ہم نے عرض کیا: ابو بکر نرم دل ہیں، اگر وہ لوگوں کو نماز پڑھائیں گے تو وہ انہیں سنا نہ پائیں گے۔ آپ سیدنا عمر سے فرما دیں کہ وہ لوگوں کو نماز پڑھائیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائے، تم یوسف علی نام کے ساتھ والی عورتوں کی طرح ہو، بہت سے کہنے والے کہیں گے اور بہت سے تمنا کرنے والے تمنا کریں گے، جبکہ اللہ اور مومن ( ابوبکر نبی اللہ کے سوا کسی اور کی جانشینی سے ) انکار کرتے ہیں۔ “ اس حدیث کو القاسم بن محمد سے صرف سلیمان بن عبد الرحمن نے روایت کیا۔ اس میں فلیح بن سلیمان کا تفرد ہے۔","",{"k":"صحیح بخاری (٦٧٩)، مسلم (٤١٨/٩٤)۔"}],[6330,"سیدنا زیاد بن جبیر نے بیان کیا کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے ایک آدمی کو دیکھا وہ اپنے اونٹ کو بٹھا کر ذبح کر رہا تھا تو انہوں نے کہا: اسے کھڑا کر، کیونکہ یہ ابو القاسم نے علیم کی سنت ہے۔ اس حدیث کو ایوب سے صرف عبد الوارث نے روایت کیا۔ اس میں حفص بن عمر الجدی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ اونٹ کو نحر کرنا چاہیے۔ نحر کرنے کا طریقہ اس طرح ہے کہ اونٹ کا اگلا بایاں گھٹنا باندھ کر اسے تین ٹانگوں پر کھڑا کر دینا چاہیے اور کوئی تیز دھار چیز مثلاً چھری، چاقو، نیزہ یا برچھی وغیرہ اس کی گردن میں مارنی چاہیے، آہستہ آہستہ خون بہہ جائے گا اور اونٹ ایک طرف گر جائے گا، پھر اس کی کھال وغیرہ اتار کر گوشت بنا لینا چاہیے۔ ٦٣٣١","",{"k":"ه و ور، هوس صحیح بخاری (١٧١٣)، مسلم (١٣٢٠)۔"}],[6331,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اس . یعنی: ماہ رمضان سے پہلے روزہ رکھنا شروع نہ کرو۔ اس ماہ کا چاند دیکھ کر روزہ رکھنا شروع کرو اور ماہ شوال کا چاند دیکھ کر روزہ رکھنا بند کر دو، پس اگر مطلع ابر آلود ہو تو پھر تمیں کی گنتی پوری کرو۔“ یہ حدیث سیدنا عم رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں عبد الرحمن بن مغراء کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٤٦/٣)، مجمع البحرين (١٤٩٢)۔"}],[6332,"سیدنا براء بن عازب رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو ظہر سے پہلے چار کعتیں پڑھتا ہے، گویا کہ اس نے رات کے وقت انہیں تجد میں پڑھا اور جس نے انہیں عشا کے بعد پڑھا وہ ان کے مانند شب قدر سے ہو جائیں گی۔ جب مسلمان دوسرے مسلمان سے ملتا ہے اور وہ اس کا ہاتھ پکڑ لیتا ہے ( مصافحہ کرتا ہے)، جبکہ وہ دونوں بچے اور مخلص ہوں تو وہ الگ نہیں ہوتے حتی کہ ان دونوں کو بخش دیا جاتا ہے۔“ اس حدیث کو الربیع بن لوط سے صرف عمار بن ابو ہاشم نے روایت کیا، اس میں نابض بن سالم کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/٢٢١)، مجمع البحرين (١٠٣٧)، ضعیف ترغیب و ترهيب (٣٢٢)، سلسله ضعیفه (٥٠٥٣)۔"}],[6333,"سیدنا مقداد بن اسود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آدمی کا دس عورتوں سے زنا کرنا، اپنے پڑوسی کی بیوی سے زنا کرنے سے کم گناہ کا باعث ہے۔ اگر وہ دس گھروں کی چوری کرتا ہے تو یہ اس کے لیے اپنے پڑوسی کے گھر سے چوری کرنے سے کم گناہ کا باعث ہے۔“ یہ حدیث سیدنا مقداد بنی الیہ سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن فضیل کا تفرد ہے۔ الله مذکورہ حدیث میں ہمسائے کے ساتھ برائی کرنے پر گناہ کی زیادتی کا تذکرہ ہے۔ اسی طرح ادب المفرد میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا آدمی دس عورتوں سے زنا کرے تو اس کا گناہ اس سے کم ہے کہ اپنے پڑوسی کی بیوی سے زنا کرے۔ (ادب المفرد، رقم: ١٠٣) کیونکہ ہمسایہ کا حق تو یہ ہے کہ اس کے ساتھ احسان کیا جائے، اس کی جان، مال اور آبرو کی حفاظت کی جائے،لیکن اس کے برعکس جب ہمسایہ ہی اپنے ہمسائے کی عزت، مال بر باد کرے تو اس میں کئی جرائم ملنے کی وجہ سے بہت بڑا گناہ بن جاتا ہے اور پھر جتنا گناہ بڑا ہو گا، اس کی سزا بھی آخرت میں اتنی بڑی ہوگی اور دنیا میں سزا، اس کے علاوہ ملے گی۔ دنیا میں اللہ پاک نے جو سزائیں مقرر کی ہیں کہ زانی کو درے لگائے جائیں گے، سنگسار کیا جائے گا اور چور کا ہاتھ کاٹا جائے گا۔ یہ سزا دنیا میں ملے گی اور آخرت میں دس گنا سے بھی زیادہ سزا ملے گی، کیونکہ ہمسائے کے ساتھ برائی کرنے کا گناہ دس گنا سے بھی زیادہ ہے۔","",{"k":"مجمع الزوائد (١٦٨/٨)، مجمع البحرين (٢٨٩٧)، مسند احمد (٨/٦)، ادب المفرد (١٠٣)، قال الشيخ الالباني: صحيح۔"}],[6334,"سیدنا موسیٰ بن سلمہ رضی اللہ عنہ نے بیان کیا، میں نے سیدنا عبداللہ ابن عباس خلیلی اینجا سے کہا: ہم آپ کے ساتھ ہوتے ہیں، پس ہم سفر پر نکلتے ہیں اور واپس آتے ہیں تو ہم دور کعتیں پڑھتے ہیں؟ انہوں نے فرمایا: یہ ابو القاسم نے علیم کی سنت ہے خواہ تمہیں نا گوار ہو۔ اس حدیث کو ایوب سے صرف الحارث بن عمیر نے اور محمد بن عبد الرحمن الطفاوی نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ سفر سے واپسی پر دو رکعت نماز پڑھنا مسنون ہے۔ کیونکہ یہ دو رکعت نفل بطور شکرانہ ہے کہ خیر و عافیت کے ساتھ انسان اپنے گھر واپس آ گیا ہے۔ بہتر یہ ہے کہ یہ دو رکعتیں مسجد میں جا کر ادا کی جائیں۔ جیسا کہ سیدنا کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ج سفر سے واپس آتے تو پہلے مسجد میں تشریف لاتے اور اس میں دو رکعت نماز ادا فرماتے۔: (بخاری، کتاب الجهاد، رقم: ٣٠٨٨، مسلم، رقم: ٢٧٦٩)",""],[6335,"سیدنا عبد اللہ بن عباس بنایا جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بنو عبد مناف! اگر دنیا کے معاملے کے تم سرپرست بنا دیے جاؤ تو تم کسی کو بیت اللہ کا طواف کرنے سے منع کرنا نہ نماز پڑھنے سے خواہ کوئی بھی وقت ہو۔ “ اس حدیث کو علی بن عبد اللہ بن عباس سے صرف ابوالزبیر نے روایت کیا۔ اس میں ثمامہ بن عبیدہ کا تفرد ہے۔ ٦٣٦","",{"k":"معجم کبیر طبرانی (١٤٢/٢، ١٦٠٠، ٥٥٦٦)، دار قطنی (٤٢٥/١، ٤٢٦، ١٠)، م (١٠)، مسند حمیدی (٥٦١)۔"}],[6336,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، ایک اعرابی نے عرض کیا: اللہ کے رسول! جب ہم ریگستان میں ہوتے ہیں تو ہم میں حیض و جنابت اور نفاس والی ہوتی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم مٹی سے تیم کرلو۔‘ اس حدیث کو زہری سے صرف المثنی بن الصباح نے اور المثنی سے صرف حفص نے روایت کیا۔ اس میں ابراہیم الشافعی کا تفرد ہے۔ الثوری اور عبد الرزاق وغیرہ نے اسے المثنی، عن عمرو بن شعیب، عن سعید بن المسیب کی سند سے روایت کیا۔","",{"k":"مجمع الزوائد (١/٢٦١)، مجمع البحرين (٤٧٧)، اسناده ضعيف۔","f":"مذکورہ روایت ضعیف ہے۔ تاہم شریعت نے یہ رخصت دی ہوئی ہے کہ اگر پانی میسر نہ ہو تو تیم کرلو۔ ارشاد باری تعالیٰ ہے:: (المائده: ٦ ) تمہیں پانی نہ ملے تو تم پاک مٹی سے تیم کر"}],[6337,"سیدنا عبداللہ ابن عباس زنای اشنا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر میں چھ ماہ قیام کیا، آپ صلی اللہ علیہ وسلم وہاں ظہر، عصر اور مغرب وعشاء کو جمع کر کے پڑھتے تھے۔“ اس حدیث کو جابر بن زید سے صرف ابوحیہ نے روایت کیا اس میں قزعہ بن سوید کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢/١٦٠)، مجمع البحرين (٩٣٧)، اسناده ضعیف۔"}],[6338,"سیدنا شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” وہ شخص جھوٹا نہیں جو ( صلح کرانے کے لیے) خیر و بھلائی کی بات کرتا ہے یا خیر کی بات آگے پہنچاتا ہے۔“ اس حدیث کو زہری، عن محمود، عن شداد بن اوس کی سند سے صرف یحی بن جرجہ نے روایت کیا ہے۔ اس میں فزعہ بن سوید کا:٦٣٣٩ تفرد ہے، جبکہ دیگر محدثین نے اسے زہری، عن حمید بن عبد الرحمن، عن، امہ عن ام کلثوم کی سند سے روایت کیا۔","",{"k":"مجمع الزوائد (٨٠/٨)۔"}],[6339,"سیدنا سعد رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے بہتر وہ ہے جو قرآن سیکھتا اور قرآن سکھاتا ہے۔ اس حدیث کو سعد سے صرف اس اسناد سے روایت کیا گیا ہے۔ اس میں الحارث بن نبہان کا تفرد ہے۔","",{"k":"سنن ابن ماجه (٢١١)، صحیح بخاری کتاب فضائل القرآن باب خيركم من تعلم القرآن ابو داؤد (١٤٥٢)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قرآن مجید کا علم سیکھنے والا دوسرے تمام علوم سیکھنے والوں سے افضل ہے۔ اسی طرح قرآن مجید کا علم سکھانے والا شخص دیگر تمام علوم سکھانے والوں سے اعلی اور افضل ہے۔ قرآن مجید سیکھنے اور سکھانے سے مراد اس کے تمام علوم ہیں، مثلاً قراءت، تجوید، ترجمہ، تفسیر اور تحفیظ وغیرہ اور قاعدے سے لے کر قرآن مجید تک ان شاء اللہ یہ مقام حاصل ہوگا۔"}],[6340,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، سیدنا جبریل عال السلام نبی صلی اللہ علیہ وسلم کے پاس آئے تو انہوں نے کہا: آپ کا رب آپ کو سلام کہتا ہے اور اس نے اس گچھے خوشے کے ساتھ مجھے آپ کی طرف بھیجا ہے تا کہ آپ اسے کھائیں، پس رسول اللہ صلی اللہ علیہ وسلم نے اسے لے لیا۔",""],[6341,"سیدنا عبداللہ ابن عباس رزولی اینجا نے بیان کیا، سیدنا جبریل عالی نام نبی صلی اللہ علیہ وسلم کے پاس آئے، تو انہوں نے کہا: آپ کا رب آپ کو سلام کہتا ہے اور اس نے اس خوشے کے ساتھ مجھے آپ کی طرف بھیجا ہے تا کہ آپ اسے کھا ئیں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اسے پکڑ لیا۔ ان دونوں حدیثوں کو زہری سے صرف عقیل نے اور عقیل سے صرف حفص بن عمر نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے اور زہری کی سیدنا انس نیل لیے سے روایت ہے۔ اس میں ابراہیم بن المنذرکا ابن وہب سے تفرد ہے۔ ٦٣٤٢","",{"k":"مجمع البحرين (٤٠٧٩)، سنده ضعيف۔"}],[6342,"سیدنا عبد الرحمن بن عوف رضی اللہ عنہ نے بیان کیا، رسول اللہ تعلیم نے فرمایا: ”اللہ تعالیٰ اور اس کے فرشتے پہلی صف ( والوں) پر رحمتیں بھیجتے ہیں۔ اس حدیث کو ابراہیم بن عبد الرحمن سے صرف محمد بن عمر و نے روایت کیا۔ اس میں ابو ضمرہ انس بن عیاض کا تفرد ہے۔","",{"k":"سنن ابن ماجه (٩٩٩)، قال الشيخ الالباني: حسن صحيح۔"}],[6343,"سيدنا سلمہ بن اکوع ری اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اسلم قبیلے کے کچھ لوگوں کے پاس سے گزرے، جبکہ وہ تیر اندازی کا مقابلہ کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” بنو اسماعیل! تیر اندازی کرو، تمہارا باپ تیرانداز تھا۔ اس حدیث کو ایاس بن سلمہ سے صرف عبد الرحمن بن حرملہ نے روایت کیا۔ اس میں سلیمان بن بلال کا تفرد ہے۔ نان عربوں کی دو قسمیں ہیں۔ ایک عرب مستعربہ، جنہیں عدنانیہ بھی کہا جاتا ہے اور دوسرے عرب عار بہ، جنہیں قحطانیہ بھی کہا جاتا ہے۔ عربوں کی پہلی قسم کو بنو اسماعیل بھی کہا جاتا ہے۔معلوم ہوا کہ عربوں کے جد امجد سیدنا اسماعیل علینام بڑے زبر دست سپاہی تھے اور نیزہ بازی ہی ان کا مشغلہ تھا۔ یہ بھی معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم نے اپنے پیروکاروں کو ہمیشہ سپاہی بنانے کی کوشش فرمائی اور مجاہدانہ زندگی گزارنے کے لیے شب و روز تلقین فرماتے رہے۔ آج بھی نبی مکرم مالی ایم کے ماننے والوں کو چاہیے کہ وہ بندوق، توپ، جنگی جہاز، ٹینک اور جتنے بھی آلات حرب وجود میں آچکے ہیں، ان سب میں مہارت حاصل کریں۔","",{"k":"صحیح بخاری (٢٨٩٩)۔"}],[6344,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ نے بیان کیا، مفصل سورتیں مکہ میں نازل ہوئیں۔ پس ہم کئی سال انہیں پڑھتے رہے۔ ہم نے حج کرنے کی حیثیت سے وہاں قیام کیا اور ہم انہیں پڑھتے رہے۔ ان کے علاوہ کوئی اور سورت نازل نہیں ہوئی۔ اس حدیث کو ابو اسحاق کے حوالے سے عبد اللہ بن حبیب ابی عبد الرحمن سے صرف حدیج بن معاویہ نے روایت کیا۔","",{"k":"حبيب مجمع الزوائد (٧/١٥٧)، مجمع البحرين (٣٤٥١)، سندہ ضعیف، اس میں حدیج بن معاویہ راوی مجہول ہے ۔۔"}],[6345,"سيدنا كعب بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ مانے تعلیم کھڑے ہوئے اور آپ صلی اللہ علیہ وسلم نے رمضان میں منبر پر لوگوں کو خطاب فرمایا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”میں اس منبر پر کھڑا ہوں اور میں شب قدر کو جانتا ہوں، پس تم اسے آخری عشرے کی طاق رات میں تلاش کرو۔“ یہ حدیث سیدنا کعب بن مالک رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں سلیمان بن بلال کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٧٠٧/٣)۔"}],[6346,"سیدنا عبد اللہ بن سبرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اللہ تمہیں تین چیزوں: کہا گیا اور اس نے کہا: کثرت سوال اور مال کے ضائع کرنے سے منع فرماتا ہے۔“ یہ حدیث سیدنا عبد اللہ بن سبرہ بنی اللہ سے صرف اس اسناد سے مروی ہے۔ اس میں معتمر کا تفرد ہے۔ ٦٣٤٧","",{"k":"مجمع الزوائد (١/١٥٧)۔"}],[6347,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دینار کے بدلے دینار اور درہم کے بدلے درہم، ان دونوں کے درمیان کوئی فضیلت نہیں۔ پس جسے سونے کی ضرورت ہو تو وہ اس کا چاندی کے ساتھ تبادلہ کرے اور جسے چاندی کی ضرورت ہو تو وہ اسے سونے کی ساتھ بدل لے، نقد بنقد “ یہ حدیث سیدناعلی بیانیہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابراہیم الشافعی کا تفرد ہے۔ ٦٣٤٨","",{"k":"کی سنن ابن ماجه (٢٢٦٢)، قال الشيخ الالباني: صحيح۔"}],[6348,"سیدنا عبد الرحمن بن کیسان نے اپنے والد سے روایت کیا، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو عشا کی نماز میں دیکھا کہ آپ صلی اللہ علیہ وسلم ایک کپڑے میں لپٹ کر نماز پڑھ رہے تھے۔‘اس حدیث کو معروف سے صرف محمد بن حنظلہ مخزومی نے روایت کیا۔","",{"k":"٠١٠٦ قال الشيخ الالباني: حسن . سنن ابن ماجه (١٠٥١)۔"}],[6349,"سیدہ اسماء بنت ابی بکر نی اینجا نے بیان کیا، میں گواہی دیتی ہوں کہ میں نے رسول اللہ طالت علی ایم کو فرماتے ہوئے سنا: \" ثقیف سے ایک کذاب (جھوٹا شخص ) اور ایک ہلا کو ظاہر ہو گا۔“ اس حدیث کو ہشام بن عروہ سے صرف عبد اللہ بن محمد بن یحیی بن عروہ نے روایت کیا۔ اس میں ابراہیم بن المنذ رکا تفرد ہے۔","",{"k":"صحیح مسلم، ومبيرها (٢٥٤٥)۔"}],[6350,"سیدہ عائشہ نون النہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اساف اور نائلہ (بت) ایک آدمی تھا اور ایک عورت تھی۔ پس اللہ تعالیٰ نے ان دونوں کو پتھروں کی صورت میں مسخ کر دیا، وہ دونوں مکہ میں تھے۔“ اس حدیث کو عمرہ سے صرف سعید بن مسلم نے روایت کیا۔ اس میں خالد بن یزید العمری کا تفرد ہے۔ البدايه والنهايه: ٢ / ١٨٥ میں ہے کہ اساف نامی مرد اور نائلہ نامی عورت کے آپس میں غلط تعلق قائم ہوئے۔ ان دونوں نے بیت اللہ شریف میں داخل ہو کر بدکاری کی تو اللہ ذوالجلال کا ان پر غضب نازل ہوا کہ اللہ تعالیٰ نے ان دونوں کو پتھر بنا دیا۔ ٦٣٥١","",{"k":"مجمع البحرين (٤٧١٤)، اسناده ضعيف۔"}],[6351,"محمد بن عمرو بن حزم بیان کرتے ہیں کہ میں نے سیدنا ابو ہریرہ رضیانی کو بیان کرتے ہوئے سنا: ” میں ان کے اس مرض میں عیادت کرنے آیا تھا جس میں انہوں نے وفات پائی تھی۔ جب میں فوت ہو جاؤں تو مجھے قمیض نہ پہنانا، میں نے رسول اللہ لئے علیم کو دیکھا، انہیں قمیض پہنائی گئی نہ عمامہ باندھا گیا۔‘اس حدیث کو محمد بن عمر و بن حزم سے صرف ابو الغصن نے روایت کیا۔ اس میں خالد بن یزید کا تفرد ہے۔","",{"k":"٦٣٥٢ مجمع الزوائد (٢٤/٣)، مجمع البحرين (١٢٧٢)، اسناده ضعيف۔"}],[6352,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو عورت اپنے سر پرست کی اجازت کے بغیر نکاح کرتی ہے تو اس کا نکاح باطل ہے۔ پس اگر اس نے اس کے ساتھ تعلق زن و شو قائم کیا ہو تو اس کے لیے حق مہر ہے جس کے ذریعے اس کی شرم گاہ اس کے لیے حلال ہوئی۔ پس اگر وہ جھگڑا کریں تو جس کا کوئی سر پرست نہ ہو تو بادشاہ اس کا سر پرست ہے۔ اس حدیث کو ابوالغصن سے صرف خالد بن یزید نے روایت کیا۔","",{"k":"سنن ابو داود (٢٠٨٣)، سنن ترمذی (١١٠٢)، قال الشيخ الالباني: صحيح۔"}],[6353,"سیدنا خزیمہ بن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالی تمہیں عورتوں کی پیٹھ میں جماع کرنے سے منع فرماتا ہے۔ اس حدیث کو عمرو بن احیہ سے صرف عبد اللہ بن علی بن السائب نے روایت کیا۔ اس میں ابراہیم الشافعی کا تفرد ہے۔","",{"k":"سنن ابن ماجه (١٩٢٤)، قال الشيخ الالباني: صحيح۔","f":"مذکورہ روایت سے معلوم ہوا کہ اپنی بیوی کے ساتھ دبر میں مباشرت حرام ہے اور ایسے شخص کو نبی مکرم ملے ایم نے ملعون کہا ہے۔"}],[6354,"سیدہ عائشہ مولانا نے فرمایا: سیدنا ابو بکر رضی اللہ عنہ نے بکری کا پایہ ہمیں ہدیہ کیا۔ پس میں اور رسول اللہ علیم رات کی تاریکی میں بیٹھ کر اسے کاٹ کر کھاتے تھے۔ مسروق کا بیان ہے کہ میں نے کہا: آپ نے دیا کیوں نہ جلا لیا؟ انہوں نے فرمایا: اگر ہمارے پاس چراغ ہوتا تو ہم اس کے ذریعے سالن نہ بنا لیتے۔“","",{"k":"مجمع البحرين (٥١٣٤)، مسند اسحاق بن راهويه (١٧٣٣)، کنز العمال (١٨٦١١)، سنده ضعيف۔"}],[6355,"سیدہ عائشہ بنی الجھا نے فرمایا: ” جب سے ہم مدینہ آئے ہیں آل محمد صلی اللہ علیہ وسلم نے تین دن متواتر پیٹ بھر کر گندم کی روٹی نہیں کھائی۔ اس حدیث کو منصور سے صرف صالح بن موسی نے روایت کیا۔ مذکورہ حدیث میں نبی معظم نے سم کے زہد استغنا و قناعت اور بے مثال سادگی کا بیان","",{"k":"صحیح بخاری (٥٤٢٤)، مسلم (٢٩٧٠)۔","f":"ہے۔ حتی کہ آخر میں جب آپ صلی اللہ علیہ وسلم نے ازواج مطہرات والوں کے لیے ایک سال کا نان ونفقہ ذخیرہ کر کے رکھنا شروع کر دیا تھا، آپ صلی اللہ علیہ وسلم کا یہی حال رہا اور آپ صلی اللہ علیہ وسلم اسے ضرورت مندوں پر خرچ کر دیتے تھے، اس لیے ازواج مطہرات کیوں کا یہ کہنا مبنی بر حقیقت ہے کہ آل محمد الے سے تم نے تین دن مسلسل پیٹ بھر کر کھانا نہیں کھایا۔ دوسری احادیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے متواتر کبھی دو دن پیٹ بھر کر نہیں کھایا۔"}],[6356,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا: میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا۔ پس آپ سے کم قضائے حاجت کی خاطر پیچھے رہ گئے۔ پس آپ صلی اللہ علیہ وسلم مجھ سے آملے تو فرمایا: ” کیا کچھ پانی ہے؟“ آپ صلی اللہ علیہ وسلم نے وضو کیا، موزوں پر مسح کیا اور پھر لشکر سے جاملے اور ان کی امامت کرائی۔‘“ اس حدیث کو عطاء الخراسانی سے صرف عمر بن المثنی نے روایت کیا۔ اس میں عمر بن عبید الطنافسی کا تفرد ہے۔",""],[6357,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ قیامت کے دن اس شخص کی طرف ( نظر رحمت سے ) نہیں دیکھے گا جو عورت سے اس کی پیٹھ میں جماع کرتا ہے۔“ اس حدیث کو ابن الہاد سے صرف لیث اور لیث سے صرف عمر و بن خالد نے روایت کیا۔ مذکورہ حدیث سے دبر میں جماع کرنے کی قباحت ثابت ہوتی ہے۔ ٦٣٥٨","",{"k":"سنن ابن ماجه كتاب النكاح باب النهي عن اتيان النساء (١٩٢٣)، قال الشيخ الالباني: صحيح۔"}],[6358,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم مشرکوں کو راستے میں ملو تو انہیں سلام کرنے میں پہل نہ کرو اور انہیں اس ( راستے) کے انتہائی تنگ حصے کی طرف (چلنے پر ) مجبور کر دو۔“ اس حدیث کو اعمش سے صرف حماد بن عمرو نے روایت کیا۔ اس میں عمرو بن خالد الحرانی کا تفرد ہے۔ مذکورہ حدیث میں کفار سے سلام کا طریقہ بتایا جا رہا ہے۔ کفار کو پہلے سلام کہنے میں ان","",{"k":"صحيح مسلم (٢١٦٧)، سنن ترمذی (١٦٠٢)، ادب (١١٠٣)، سنن ابو داود (٥٢٠٥)۔","f":"کی تعظیم و تکریم پائی جاتی ہے حالانکہ عزت کے حق دار صرف اہل ایمان ہیں۔ وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ وَلَ: كُنَّ الْمُنَافِقِينَ لَا يَعْلَمُونَ) (المنافقون: ٨) عزت صرف اللہ کے لیے اور اس کے رسول (الینا) کے لیے اور ایمان والوں کے لیے ہے، مگر منافق لوگ جانتے نہیں، (کفار کے لیے تو ذلت ہے)۔“ جیسا کہ ارشاد باری تعالی ہے: حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَّدٍ وَ هُمْ صُغِرُونَ﴾ (التوبه: ٢٩) یہاں تک کہ وہ ذلیل ہو کر اپنے ہاتھ سے جزیہ دیں۔“ اسی ذلت کا احساس دلانے کے لیے اور اسے مستقل قائم رکھنے کے لیے مسلمانوں کو حکم دیا کہ اگر راستے میں تمہاری ملاقات ان سے ہو تو ان کے لیے کھلا راستہ مت چھوڑو بلکہ انہیں مجبور کرو کہ تنگ تر راستے سے گزریں، سلام کی ایک حکمت رسول اللہ صلی اللہ علیہ وسلم نے یہ بیان فرمائی ہے کہ سلام سے آپس میں محبت پیدا ہوتی ہے۔ لیکن کفار کے ساتھ دوستی نہیں لگانی چاہیے، جیسا کہ ارشاد باری تعالیٰ ہے:: لا (ممتحنه: ١) ”میرے اور اپنے دشمن کو دوست مت بناؤ ““ لیکن کسی مجلس میں مسلمان اور کافر موجود ہوں تو ان کو سلام کر لینا جائز ہے۔ (دیکھئے: صحیح بخاری، رقم: ٦٢٥٤)"}],[6359,"سیدنا عمرو بن شعیب نے اپنے والد سے، انہوں نے اس کے دادا سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: جس کے ہاتھ میں نکاح کی گرہ ہے وہ شوہر ہے۔“ اس حدیث کو اس اسناد سے صرف ابن لہیعہ نے روایت کیا اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ مذکورہ روایت ضعیف ہے۔ اس میں ابن لہیعہ ضعیف ہے۔ تاہم اکثر مفسرین نے قرآن مجید کے ان الفاظ ((بیده عقدة النکاح) جس کے ہاتھ میں نکاح کی گرہ ہے۔“ اس سے مراد خاوند ہی لیا ہے کیونکہ نکاح کی گرہ، اس کا کھولنا اور باقی رکھنا خاوند کے ہاتھ میں ہوتا ہے۔:٦٣٦٠","",{"k":"مجمع الزوائد (٣٢٣/٦)، مجمع البحرين (٣٢٩٩)۔"}],[6360,"فی تعلیم کی زوجہ محترمہ سیدہ صفیہ بنایا جا نے فرمایا: ”ایک دن رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے تو فرمایا: ”حی کی بیٹی! کیا تمہارے پاس کھانے کے لیے کوئی چیز ہے؟ کیونکہ مجھے بھوک لگی ہے؟ میں نے عرض کیا: اللہ کے رسول! اللہ کی قسم! نہیں، صرف ایک مد ( تقریباً چھ سو گرام) آتا ہے، آپ ملیم نے فرمایا: ”اسے گرم کرو۔“ انہوں نے فرمایا: پس میں نے اسے ہنڈیا میں ڈالا اور اسے پکایا، میں نے عرض کیا، اللہ کے رسول! وہ پک گیا ہے، آپ ملنے صلی اللہ علیہ وسلم نے فرمایا: ”کیا تم جانتی ہو کہ ابو بکر کی بیٹی (عائشہ منی اشیا) کے گھی والے کنستر، مشکیزے میں کچھ ہے؟ میں نے عرض کیا: اللہ کے رسول! میں نہیں جانتی، انہوں نے کہا: آپ لئے علیم بنفس نفیس تشریف لے گئے، حتی کہ ان کے گھر پہنچے تو فرمایا: ”ابو بکر کی بیٹی! کیا تمہارے گھی والے مشکیزے میں کچھ ہے؟ انہوں نے عرض کیا: اس میں بس تھوڑا سا ہے، پس آپ مطلئے علیکم بذات خود اسے لائے اور اس کے کناروں کو ہنڈیا میں نچوڑا، حتی کہ میں نے دیکھا جو آپ صلی اللہ علیہ وسلم کے ہاتھ کی جگہ سے نکل رہا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”بسم اللہ “ پھر آپ صلی اللہ علیہ وسلم نے برکت کی دعا فرمائی اور فرمایا: ” اپنی بہنوں کو بھی بلا لو، کیونکہ میں جانتا ہوں کہ جس طرح مجھے بھوک لگی ہے، اسی طرح وہ بھی بھوکی ہیں۔ پس میں نے انہیں بلایا، ہم نے کھایا، حتی کہ ہم شکم سیر ہو گئے۔ پھر سیدنا ابو بکر نیا نہیں آئے، انہوں نے اجازت طلب کی اور اندر آگئے۔ پھر سیدنا عمر نل ا ل لینے آئے، پھر ایک اور آدمی آیا، انہوں نے بیان کیا: پس انہوں نے کھا یا حتی کہ وہ بھی سیر ہو گئے، اور ان سے بیچ رہا۔“ یہ حدیث سیدہ صفیہ رضی شہا سے صرف اس اسناد سے مروی ہے۔ اس میں عمرو بن خالد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٨/٨)، سنده ضعيف۔"}],[6361,"سیدنا انس بن مالک نبی الیہ سے روایت ہے، نبی صلی اللہ علیہ وسلم بچے کے ساتھ سب سے زیادہ مزاح کرنے والے تھے۔ اس حدیث کو اسحاق بن عبد اللہ بن ابی طلحہ سے صرف عمارہ بن غزیہ نے روایت کیا۔ اس میں ابن لہیعہ کا تفرد ہے۔ انس رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ مزاح، خوش طبعی، دل لگی وغیرہ وہ اوصاف ہیں جو انسانی فطرت میں داخل ہیں اور آج کل تو لوازمات تہذیب میں گنے جاتے ہیں۔ وہ انسان جو خوش مزاج نہ ہو، ہنسی مذاق نہ کر سکتا ہو، اسے بادہ کشان مغرب کے نزدیک اس دور مدنیت میں زندہ رہنے کا کوئی حق نہیں، کیونکہ وہ ﴿عبوسا قمطریرا خشک مزاج ہے، مردہ دل ہے، بدو ہے اور تہذیب جدید سے نا آشنا ہے، زندگی زندہ دلی کا نام ہے مردہ دل کیا خاک جیا کرتے ہیں۔ اسلام سے پہلے محسن کائنات مے علم کی نبوت کے دور میں آج کل کے یہ مدعیان تہذیب تو رہبانیت کی انتہائی منزلیں طے کر رہے تھے اور مزاح و تقسیم سے انہیں کوئی واسطہ نہ تھا، مگر جب اسلام آیا اور نبی مکرم نے نیم کے ذریعے سے آیا تو یہ کیوں کرممکن تھا کہ وہ نبی سے کم معاشرت کے اس اہم شعبہ پر اپنا اسوہ حسنہ نہ چھوڑتے، لیکن شریعت نے وہ مزاح یا دل لگی کرنے کا حکم دیا ہے، جو سچ پر مبنی ہو اور اس میں جھوٹ کا شائبہ نہ ہو اور اس میں کسی کی دل آزاری یا تو ہین بھی مقصود نہ ہو تو وہ جائز ہے۔ مذکورہ بالا حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم بچوں کے ساتھ زیادہ مزاح کیا کرتے تھے، اس کی مثال احادیث کی کتب سے ملتی ہیں، جیسا کہ سیدنا انس بنی لینے کے ایک چھوٹے بھائی تھے۔ جن کا نام سیدنا عمیر رضی اللہ عنہ انہوں نے ایک سرخ رنگ کی چڑیا پال رکھی تھی، جو اتفاقا مر گئی، سیدنا عمیر رضی اللہ عنہ کو اس کا بہت صدمہ ہوا اور رونے لگے، نبی مکرم صل علیم ادھر سے گزرے، بچے کو روتے ہوئے دیکھا تو اس کا دل بہلانے کے لیے فرمایا: ((يا أبا عمير ما فعل النغير )) (بخاری، رقم: ٦١٢٩) اے عمیر! تمہاری غیر نامی چڑیا کا کیا حال ہے؟ یہ ایک ایسا دلکش اور مناسب حال جملہ تھا جس سے بچہ ہنس پڑا۔ اسی طرح رسول اللہ سے تم اپنی عزیز عورتوں کے ساتھ بھی مزاح کر لیا کرتے تھے۔اسی طرح احادیث سے ثابت ہے کہ رسول اللہ ملے عام اپنے صحابہ کرام ٹی ایم سے خوش طبعی کرتے تھے۔ ٣٦٢","",{"k":"طبرانی صغیر (٨٧٠)۔"}],[6362,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ سامان تجارت کو منڈی پہنچنے سے پہلے ملا جائے اور اگر کوئی ملنے والا اسے ملتا ہے اور کوئی چیز خرید لیتا ہے تو مارکیٹ پہنچنے پر سامان تجارت کے مالک کو اس میں اختیار حاصل ہے ( کہ وہ اس بیع کو قائم رکھے یا ختم کر دے)۔‘ اس حدیث کو ایوب سے صرف عبید اللہ بن عمرو نے روایت کیا۔ ٦٣٦٣","",{"k":"صحيح مسلم (١٥١٩)، سنن ابو داود (٢٦٧)، سنن ترمذی (١٢٢١)۔"}],[6363,"سیدنا عبد اللہ فی اللہ نے بیان کیا، میں نے نبی لئے علیم اور سیدنا ابو بکر و عمر نا یا کو جنازے کے آگے چلتے ہوئے دیکھا۔ اس حدیث کو یونس سے متصل صرف ابن لہیعہ نے روایت کیا۔ ٦٣٦٤","",{"k":"سنن ابو داود (٣١٧٩)، سنن ترمذی (١٠٠٧)، قال الشيخ الالباني: صحيح۔"}],[6364,"سیدہ عائشہ منی نیہا نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ طلاے علی تم نے فرمایا: ”جو نذر مانے کہ وہ اللہ کی اطاعت کرے گا تو وہ اس کی اطاعت کرے، اور جو نذر مانے کہ وہ اس کی نافرمانی کرے گا تو وہ اس کی نافرمانی نہ کرے۔“ اس حدیث کو عبدالرحمن بن قاسم سے صرف محمد بن عبید اللہ الفزاری نے روایت کیا۔ اس میں محمد بن سلمہ کا تفرد ہے۔","",{"k":"صحیح بخاری (٦٦٩٦)، سنن ابو داود (٣٢٨٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اللہ ذوالجلال کی معصیت والی نذر پوری کرنا جائز نہیں اور اگر کوئی ایسی نذر مانے تو پوری نہ کرے، بلکہ وہ کفارہ قسم ادا کرے۔ امام شوکانی رحمہ اللہ اسی بات کے قائل ہیں۔ (الدرر البهية كتاب النذر) ٦٣٦٥"}],[6365,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ اسے علم سے اس روزہ دار کے بارے میں دریافت کیا گیا جو بھول کر کھا پی لیتا ہے تو آپ ملنے سلیم نے اسے قضا کا حکم نہ فرمایا اور فرمایا: ” یہ وہ کھانا ہے جو اللہ نے اسے کھلایا ہے۔“ یہ حدیث سیدنا ابوسعید خدری ضیا الہیہ سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن عبید اللہ کا تفرد ہے۔ ٦٣٦٦","",{"k":"کر مجمع الزوائد (٣٥٧/٣)، مجمع البحرين (١٥٢٣)۔"}],[6366,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: سر پرست اور دو معتبر گواہوں کے بغیر کوئی نکاح نہیں۔“ اندن مذکورہ روایت ضعیف ہے، تاہم نکاح کے لیے دو گواہوں کی موجودگی شرط ہے۔ کیونکہ ان کے بغیر نکاح نہیں ہوتا۔ امام شافعی براللہ کا یہ موقف ہے کہ مردوں کی گواہی کے بغیر نکاح نہیں ہوتا۔ امام ابو حنیفہ اور امام احمد عبداللہ نے فرمایا ہے کہ نکاح میں ایک مرد اور دو عورتوں کی گواہی بھی کافی ہے اور احناف کے نزدیک عادل ہونا شرط نہیں ہے۔ امام مالک ہمالہ نے یہ موقف اپنایا ہے کہ گواہوں کے بغیر بھی نکاح درست ہے، بشرطیکہ اعلان نکاح کر دیا جائے۔ (تحفة الاحوذي: ٢٤٤/٤، المبسوط: ٣١/٥) راجح موقف امام شافعی اللہ کا ہے۔ امام شافعی اللہ نے بھی اسی کو ترجیح دی ہے۔ دیکھئے: ( نيل الأوطار: ٢٠٣/٤، تحفة الاحوذی: ٢٤٤/٤) اور گواہ بھی دین دار ہونے چاہئیں، جیسا کہ سیدنا عبد اللہ بن عباس و پہنچا نے فرمایا ہے کہ دو عادل گواہوں کے بغیر نکاح نہیں ہوتا۔ (صحیح موقوف، ارواء الغليل: ١٨٤٤) ٦٣٦٧","",{"k":"مجمع الزوائد (٤/٢٨٦)، مجمع البحرين (٢٢٦٦)، سلیمان بن ارقم متروک، اسناده ضعيف۔"}],[6367,"سیدہ عائشہ صلی للہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں آپ لئے عالی ایم کی مسواک اور آپ مالٹے کو ایم کی کنگھی الگ نہیں ہوتی تھی اور جب آپ ملنے کی تم اپنی داڑھی میں کنگھی کرتے تھے تو آپ صلی اللہ علیہ وسلم آئینہ دیکھتے تھے۔ ان دونوں حدیثوں کو زہری سے صرف سلیمان بن ارقم نے روایت کیا۔ ان میں محمد بن سلمہ کا تفرد ہے۔","",{"k":"الموضوعات: ١/ ١٢٣١. مجمع الزوائد (٥/١٧١)، مجمع البحرين (٤٣١٤)، تذكرة۔"}],[6368,"سیدنا معاویہ نیل الیہ کے آزاد کردہ غلام ابو حریز نے بیان کیا سیدنا معاویہ رضی لینہ نے لوگوں کو خطبہ ارشاد فرمایا تو انہوں نے اپنے خطبے میں ذکر کیا کہ رسول اللہ تعلیم نے کچھ چیزوں سے منع فرمایا ہے، میں وہ تمہیں پہنچاتا ہوں اور تم کو ان سے منع کرتا ہوں، نوحہ کرنا، شعر گوئی، تصاویر، درندوں کے چمڑے،سونا اور چاندی۔“ اس حدیث کو سیدنا معاویہ رضی اللہ عنہ کے آزاد کردہ غلام ابو حریز سے صرف عبد اللہ بن دینار الہرانی نے اور عبد اللہ بن دینار سے صرف اسماعیل بن عیاش نے روایت کیا۔","",{"k":"سنن ابن ماجه (١٥٨٠)، سلسله ضعیفه (٤٧٢٥)، مسند احمد (١٠١/٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مذکورہ بالا چیزیں حرام ہیں،\n(١) نوحہ کرنا، نوحہ سے مراد ہے مرنے والے کی خوبیاں ذکر کر کے اور اپنے غم کے اظہار کے لیے مختلف فقرے بول بول کر بلند آواز سے رونا، یہ مرد اور عورتوں دونوں کے لیے حرام ہے۔\n(٢) شعر گوئی، سے مراد جاہلیت کے شعر یا ایسے شعر جو توحید کے منافی اور شرکیہ امور پر مشتمل ہوں یا جن میں فحاشی و بے حیائی کا عنصر موجود ہو۔ اچھے اشعار پڑھنا جائز ہے۔سیدنا حسان رضی اللہ عنہ تھے،\n(٣) معلوم ہوا کہ تصاویر بنانا یا بنوانا حرام ہے۔\n(٤) درندوں کی کھالیں رنگی ہوں یا نہ رنگی ہوں تمام کا حکم یہ ہے کہ استعمال نہ کی جائیں۔ (٥۔٦) سونا اور ریشم عورتوں کے لیے جائز ہے تاہم مردوں کے لیے حرام ہے۔"}],[6369,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم سے روایت کیا، اللہ تعالیٰ کی مخلوق میں سے اس کے چند خاص بندے ہیں، وہ انہیں عافیت میں زندہ رکھتا ہے اور جب وہ ان کو فوت کر کے اپنی جنت کی طرف لے آتا ہے۔ یہ وہ لوگ ہیں کہ ان پر فتنے تاریک رات کے ٹکڑوں کی طرح آتے ہیں، جبکہ وہ ان میں عافیت سے ہوتے ہیں۔“ اس حدیث کو نافع سے صرف مسلم بن عبد اللہ المعصی نے روایت کیا۔ اس میں اسماعیل بن عیاش کا تفرد ہے۔ ٦٣٧٠","",{"k":"الصغير، رقم: ١٩٤٨ . مجمع الزوائد (١٠/٢٦٥)، مجمع البحرين (٥٠٥٠)، ضعيف الجامع۔"}],[6370,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک برچھے کی طرف نماز پڑھی۔“ اس حدیث کو محمد ابن عجلان سے صرف ابن لہیعہ نے روایت کیا۔ مانده مذکورہ حدیث سے معلوم ہوا کہ سترہ کسی بھی چیز کا بنایا جا سکتا ہے، خواہ وہ لکڑی کا ہو یا تیر، لاٹھی، کوئی بھی چیز ہو بشرطیکہ اس کی لمبائی کجاوے کی پچھلی لکڑی کے برابر ہونی چاہیے۔ معلوم ہوا کہ سترہ کسی باریک چیز کو بھی بنایا جا سکتا ہے۔ اسی طرح کسی جانور کو بھی سترہ بنانا جائز ہے۔ دیکھئے: (صحیح ابو داؤد، رقم: ٦٤١)","",{"k":"مسند احمد (٤/٣٠٨)، مجمع البحرين (٧٤٥)، قال شعیب الارناؤط: اسناده صحيح۔"}],[6371,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے ورایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے نشہ کی حالت میں ایک مرتبہ نماز چھوڑ دی تو گویا کہ اس کے پاس دنیا اور اس کی تمام چیزیں تھیں، وہ سلب کر لی گئیں اور جس نے چار مرتبہ نشہ کیا، (اور نماز نہ پڑھی) تو اللہ پر حق ہے کہ وہ اسے طیۃ الخبال‘ میں سے پلائے۔“ عرض کیا گیا: اللہ کے رسول! ”طیۃ الخبال کیا چیز ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جہنمیوں کی پیپ۔“ مذکورہ حدیث میں نماز ترک کرنے والوں کی سزا کا تذکرہ ہے، لیکن یہ بیماری آج کل عام ہے، نوجوان طبقہ جو دن بدن غافل ہوتا چلا جارہا ہے، اگر یہ لوگ عقل کے ناخن لیں تو اس حدیث میں بیان کی گئی وعید کافی ہے۔ رسول اللہ صل علی تم نے فرمایا: شراب سے بچتے رہو، ((فانها مفتاح كل شر )) (حاكم: ١٤٥/٤، سلسله صحیحه:٢٧٩٨) ”یہ تو ہر برائی کا سر چشمہ ہے۔ (٢) تو بہ کرنے سے کبیرہ گناہ بھی معاف ہو جاتا ہے، لیکن بار بار تو بہ توڑنے سے مجرم کے دل میں تو بہ کی اہمیت ختم ہو جاتی ہے جس کی وجہ سے ایسی کیفیت پیدا ہو جاتی ہے کہ تو بہ کرتے وقت دل میں ندامت پیدا نہیں ہوتی، چنانچہ وہ تو بہ قبول نہیں ہوتی۔","",{"k":"حاكم: ٤ / ١٤٦ . الزوائد ٥/. ٧٠، مسند احمد (٢/١٧٨)، سلسله صحیحه، رقم۔"}],[6372,"سیدنا عمرو بن شعیب نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا، انہوں نے کہا: ہلال اپنے شہر کا دسواں حصہ لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے سوال کیا، کہ آپ صلی اللہ علیہ وسلم ایک وادی اس کے لیے مخصوص کر دیں، اسے سلبہ کہا جاتا ہے۔ پس رسول اللہ صلی اللہ علیہ وسلم نے وہ وادی اس کے لیے مخصوص فرما دی۔ ان دونوں حدیثوں کو عمرو بن الحارث سے صرف موسی بن امین نے روایت کیا۔ قانون مذکورہ حدیث سے معلوم ہوا کہ شہر میں زکاۃ ہے، جیسا کہ مذکورہ بالا حدیث سے ثابت","",{"k":"اعين . کی سنن ابو داود (١٦٠٠)، قال الشيخ الالباني: حسن۔","f":"ہوا کہ رسول اللہ علی علیہم نے زکاۃ وصول کی اور وادی سلبہ اس کے نام لکھ دی۔سنن ابی داؤد میں یہ بھی ہے کہ جب سیدنا عمر رضی اللہ عنہ بنے تو حضرت سفیان بن وہب نبی اللہ نے تحریراً سیدنا عمر رضی اللہ عنہ سے اس کے بارے میں پوچھا تو سیدنا عمر رضی اللہ عنہ نے لکھا: اگر یہ اپنے شہر کا وہی عشر دیتا رہے جو رسول اللہ نے ہم کو دیا کرتا تھا تو وادی سلبہ اسی کے نام رہنے دو، ورنہ یہ شہد کی مکھیاں ہیں جو چاہیے (ان کا شہد ) کھا لے۔ (سنن ابی داؤد، رقم: ١٦٠٠)"}],[6373,"سیدہ عائشہ والا نہا سے روایت ہے کہ انہوں نے خواب دیکھا کہ تین چاندان کے حجرے میں گرے ہیں۔ پس انہوں نے اس کا سیدنا ابو بکر ضیا لینے سے تذکرہ کیا۔ پس جب رسول اللہ صلی اللہ علیہ وسلم نے وفات پائی اور آپ صلی اللہ علیہ وسلم کو ان کے گھر میں دفن کیا گیا تو سیدنا ابو بکر رضی اللہ عنہ نے فرمایا: یہ تمہارے (ان تین) چاندوں میں سے سب سے بہتر ہے۔“ مجمع الزوائد کی دوسری حدیث میں اس کی وضاحت موجود ہے، اس سے مراد رسول اللہ صلی اللہ علیہ وسلم سیدنا ابو بکر اور سیدنا عمر نہی پہنچا ہیں جو سیدہ عائشہ بنی ان چاہا کے حجرے میں دفن ہوئے۔ ٦٣٧٤","",{"k":"٦٣٧٣ مجمع الزوائد (١٨٥٧)، مجمع البحرين (٣٢١٣)۔"}],[6374,"سیدنا جابر رضی اللہ عنہ ہم نے بیان کیا، میرے کانوں نے رسول اللہ صلم کو فرماتے ہوئے سنا: ” کچھ لوگ جہنم سے نکلیں گے۔“ پیچھے بھی احادیث گزر چکی ہیں کہ جو مسلمان ہو گئے، اگر گناہوں کی وجہ سے جہنم میں چلے جائیں گے تو سزا بھگت کر جنت میں چلے جائیں گے۔ مذکورہ بالا حدیث سے یہ معلوم ہوا کہ مومن کے لیے دوزخ میں دائمی عذاب نہیں۔ ٦٣٧٥","",{"k":"صحیح بخاری (٦٥٥٨)، مسلم۔"}],[6375,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ظہر کی نماز مدینہ میں چار رکعتیں پڑھی۔ پھر آپ صلی اللہ علیہ وسلم کسی سفر پر روانہ ہوئے تو آپ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز درخت کے پاس دورکعتیں پڑھائی۔“ قائده درخت سے مراد ذوالحلیفہ کا مقام ہے۔ یہاں پر درخت تھا، جیسا کہ بخاری ومسلم میں ہے کہ مدینہ میں ظہر کی نماز چار رکعت پڑھی اور ذوالحلیفہ میں عصر کی دو رکعت۔ (باری، رقم: ١٠٨٩، مسلم، رقم: ٦٩٠) یہ بھی معلوم ہوا کہ سفر شروع ہو جانے کے بعد شہر سے نکل کر نماز قصر شروع ہو جاتی ہے۔ ذوالحلیفہ جس کا موجودہ نام آبار علی ہے یہ مدینہ سے چھ میل دور ہے۔","",{"k":"صحیح بخاری (١٥٤٦)، مسلم۔"}],[6376,"عمرہ نے بیان کیا کہ وہ سیدہ عائشہ نیا انھی جا کے پاس تھیں، ان سے کہا گیا کہ سیدنا ابو سعید خدری بنا الله رسول الله علی علیم سے روایت کرتے ہیں، آپ نے فرمایا: کسی عورت کے لیے حلال نہیں کہ وہ محرم کے بغیر تین دن کا سفر کرے۔ عمرہ نے بیان کیا سیدہ عائشہ منی اینجا نے ہماری طرف دیکھا اور فرمایا: تم سب کے لیے محرم نہیں۔“","",{"k":"صحیح بخاری (١٨٦٤)۔","f":"مان مذکورہ روایت میں تین دنوں کا تذکرہ ہے، بعض روایات میں ایک دن اور رات، بعض میں دو دن کا تذکرہ ہے۔ یہ نبی معظم ملنے سلیم نے مختلف سائلین کو بتایا، لیکن ان سب کا مفہوم یہ ہے کہ کسی مسلمان عورت کو اپنے محرم کی معیت کے بغیر سفر نہیں کرنا چاہیے۔ حالات کیسے بھی ہوں، مسلمان پر لازم ہے کہ وہ اپنے آپ کو شریعت کا پابند بنائے،حیل و حجت نہ کرے۔ ٦٣٧٧"}],[6377,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ علل علم منبر پر کھڑے ہوئے تو آپ ملنے سے تم نے فرمایا: ” تم میں سے جو شخص جمعہ کے لیے آئے تو وہ غسل کرے۔“","",{"k":"صحیح بخاری (٨٩٤)، مسلم (٨٤٦)۔"}],[6378,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلیے علیم نے غزوہ تبوک میں ظہر و عصر اور مغرب و عشا کو ملا کر پڑھا، حتی کہ ہم واپس آگئے۔ ان احادیث کو عمرو بن الحارث سے صرف بکیر بن مضر نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ دوران سفر ظہر و عصر اور مغرب وعشا کی نمازیں جمع کرنا درست ہے۔ ایک کو دوسری کے وقت میں ادا کیا جائے، اسے جمع تقدیم و تاخیر کہتے ہیں، امام احمد، مالک، شافعی بیشتم دوران سفر، اس جمع کے جواز کے قائل ہیں۔ جبکہ احناف صرف جمع صوری کے ہی قائل ہیں، (جمع صوری یہ ہے کہ ایک نماز کو اس کے آخری وقت میں اور دوسری کو اس کے اول وقت میں پڑھنا، دونوں نمازیں جمع بھی ہوں جائیں گی اور ادا بھی اپنے اپنے وقت میں ہی ہوں گی ) (بداية المجتهد: ١/ ١٢٥، فتح القدير: ٢/ ٤٨ ) پہلا موقف ہی راجح ہے۔","",{"k":"و، مضر . صحيح مسلم، ١٢٠ (٧٠٦)، سنن ابو داود كتاب الصلاة باب الجمع بين الصلاتين (١٢٠٦)، سنن نسائی۔"}],[6379,"سیدہ فاطمہ بنت قیس بنایا جا نے بیان کیا، رسول اللہ نے سلم نے دجال کا ذکر کیا تو فرمایا: ”وہ اس طرف سے تمہارے پاس آئے گا اور آپ نے مشرق کی جانب اشارہ فرمایا۔“ مذکورہ حدیث سے معلوم ہوا کہ دجال مشرق سے آئے گا۔ صحیح مسلم میں ہے کہ سیدہ فاطمہ بنت قیس بنا لی کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: آگاہ رہو، دجال شام یا یمن کے سمندر میں موجود ہے (پھر فرمایا) نہیں بلکہ وہ مشرق کی طرف ہے، وہ مشرق کی طرف ہے، وہ مشرق کی طرف ہے۔ پھر آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ مبارک سے مشرق کی طرف اشارہ کیا۔ (مسلم، کتاب الملاحم، باب قصة الجساسة) رسول اللہ صلی اللہ علیہ وسلم نے پہلے شام یا یمن کے سمندر کا ذکر فرمایا، پھر فوراً ہی اس کی تردید فرما کر تاکید کے ساتھ مشرق کے کسی سمندر کا ذکر فرمایا۔ شارحین حدیث نے اس کی وضاحت میں یہ لکھا ہے کہ آپ صلی اللہ علیہ وسلم کا پہلی بات کی تردید فرما کر دوسری بات کی تین مرتبہ تاکید فرمانا وحی کی بنا پر تھا۔","",{"k":"کر مجمع الزوائد (٣٣٩/٧)۔"}],[6380,"سیدنا اسامہ بن شریک نیل اللہ نے بیان کیا، ہم نبی صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے، گویا کہ ہمارے سروں پر رغم (پرندہ) ہو، ہم میں سے کسی نے کلام نہ کیا کہ اتنے میں کچھ لوگ آپ مٹ عام کے پاس آئے تو انہوں نے عرض کیا: اللہ کے رسول! اس بارے میں ہمیں فتویٰ دیں، اس بارے میں ہمیں فتویٰ دیں، آپ ملنے صلی اللہ علیہ وسلم نے فرمایا: ”لوگو! اللہ نے حرج ختم کر دیا، مگر جس نے اپنے بھائی کی عزت خراب کی (اس کی غیبت کی )۔ پس اس نے حرج ( گناہ کا کام کیا اور وہ ہلاک ہوا۔ انہوں نے عرض کیا، اللہ کے رسول! کیا ہم علاج معالجہ کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں۔ اللہ نے ایک مرض کے علاوہ جو بھی بیماری نازل کی تو اس کی دوا بھی نازل فرمائی۔ انہوں نے عرض کیا: اللہ کے رسول صلی اللہ علیہ وسلم! وہ کون سا مرض ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بڑھاپا۔“ انہوں نے عرض کیا: اللہ کو کون سا بندہ زیادہ محبوب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جس کے اخلاق سب سے اچھے ہیں۔“ اس حدیث کو عثمان بن حکیم سے صرف عیسی بن یونس نے روایت کیا۔ مذکورہ حدیث سے (١) صحابہ کرام کا رسول اللہ صلی اللہ علیہ وسلم کا ادب و احترام کرنا ثابت ہوتا ہے۔ اس سے یہ ثابت ہوتا ہے کہ طالب علم کو چاہیے کہ وہ اپنے اساتذہ کے سامنے با ادب ہو کر بیٹھا کرے۔ (٢) مذکورہ حدیث سے رسول اللہ صلی اللہ علیہ وسلم کے حسن اخلاق کا بھی اثبات ہوتا ہے کہ آپ اسلام میں نئے داخل ہونے والوں کے نامناسب رویے کو خندہ پیشانی سے برداشت کرتے تھے۔ (٣) معلوم ہوا کہ کسی کی غیبت کرنا، یہ انسان کو ہلاکت کی طرف لے جاتا ہے۔ (٣) معلوم ہوا کہ بیماری کا علاج کرانا بھی جائز اسباب میں سے ہے جنہیں اختیار کرنے میں کوئی حرج نہیں۔ معلوم ہوا کہ ہر بیماری کا علاج ہے، آگے رہا کہ اس بیماری کی سمجھ آئے یا نہ آئے، اس انسان کی محنت سمجھ اور توجہ پر مبنی ہے۔ (٤) مذکورہ حدیث سے معلوم ہوا کہ اللہ کے ہاں محبوب ترین وہ ہے جو اخلاق کے لحاظ سے اچھا ہے، کیونکہ خوش اخلاقی ایک ایسی خوبی ہے جس سے دنیا میں بھی","",{"k":"سنن ابو داود (٣٨٥٥)، سنن ترمذی، والحث عليه (٢٠٣٨)، قال الشيخ الالباني: صحيح۔","f":"حاصل ہوتا ہے اور آخرت میں بھی۔ ٦٣٨١"}],[6381,"سیدنا عروہ البارقی بی الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” گھوڑوں کی پیشانیوں میں قیامت کے دن تک خیر و بھلائی وابستہ کر دی گئی ہے۔ اس حدیث کو جابر سے صرف زہیر نے روایت کیا۔","",{"k":"صحیح بخاری (٢٨٥٢)، مسلم (١٨٧٣)۔"}],[6382,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ للہ علیم نے فرمایا: ”یہ امت سیدھی رہے گی اور اس کا امر دشمنوں پر غالب رہے گا یہاں تک کہ ان میں بارہ خلفا گزر جائیں گے اور وہ سب قریش سے ہوں گے۔ پس جب آپ صلی اللہ علیہ وسلم اپنے گھر تشریف لے گئے تو قریش آپ صلی اللہ علیہ وسلم کے پاس آئے اور انہوں نے عرض کیا: پھر کیا ہوگا؟ فرمایا: ”پھر قتل و غارت ہو گی۔“ اس حدیث کو اسود بن سعید سے صرف زیاد بن خیثمہ نے اور زیاد سے صرف زہیر بن معاویہ نے روایت کیا۔ ٦٣٨٣","",{"k":"سنن ابو داود (٤٢٨٠، ٤٢٨٠)، قال الشيخ الالباني۔"}],[6383,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو مسجد سے الفت رکھتا ہے اللہ اس سے الفت رکھتا ہے۔“ اس حدیث کو دراج سے صرف ابن لہیعہ نے روایت کیا۔ اس میں عمر و بن خالد کا تفرد ہے۔ ٣٨٤","",{"k":"مجمع الزوائد ٢٣/٢، ضعيف الجامع الصغير (٥٤٨٢)، ضعیف ترغیب و ترهيب (٢٠٥)، مجمع البحرين (٦٨٣)، اسناده ضعيف۔"}],[6384,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں سیدنا ابوطلحہ رضی اللہ عنہ کے پیچھے سواری پر سوار تھا، میرا گھٹنا نبی صلی اللہ علیہ وسلم کے گھٹنے کو چھور رہا تھا، وہ حج وعمرہ کا تلبیہ پکارتے رہے۔‘ اس حدیث کو ایوب، عن حمید بن ہلال سے صرف عبید اللہ بن عمرو نے روایت کیا۔ اور حماد بن زید وغیرہ نے اسے صرف ابو قلابہ سے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ ایک سواری پر دو آدمی بیٹھ سکتے ہیں، بشرطیکہ سواری کمزور نہ ہو۔ (٢) حج اور عمرہ دونوں کا تلبیہ پکارا۔ یہ اس وقت ہوتا ہے کہ جب حج قران کیا جائے، کیونکہ رسول اللہ علیم نے حج قران کیا تھا، اس لیے حج اور عمرہ دونوں کا احرام باندھا، حج کی تین اقسام ہیں۔ (١) حج تمتع، (٢) حج قران (٣) حج افراد۔","",{"k":"صحیح بخاری (٢٩٨٦)، مسلم (١٢٥١)۔"}],[6385,"سیدنا اسامہ بن زید ضیا الیہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سونے کے بدلے سونے کے بارے میں دریافت کیا . وہ اور سیدنا زید بن ارقم بنا اللہ تجارت کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نقد بنقد ہو تو اس میں کوئی مضائقہ نہیں",""],[6386,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ، مخابرہ اور مزابنہ (بیع کی اقسام) سے منع فرمایا اور یہ کہ کھجور فروخت نہ کی جائے حتی کہ وہ سرخ ہو جائے یا زرد ہو جائے، یا وہ کھانے کے قابل ہو جائے۔“ ان دونوں حدیثوں کو زید بن ابی انیسہ سے صرف عبید اللہ بن عمرو نے روایت کیا۔ هیچ محاقلہ یہ ہے کہ، بالیوں میں کھڑی کھیتی کو غلے کے عوض فروخت کر دینا جیسے گندم کے کھیت کے بدلے گندم فروخت کرنا وغیرہ بیع محاقلہ کہلاتی ہے۔ بیچ مذابنہ، درختوں پر لگے ہوئے پھل کو اسی جنس کے اتارے ہوئے خشک پھل کے عوض فروخت کرنا مثلاً کھجوروں کے بدلے کھجور کے درخت پر لگی تازہ اور تر کھجوروں کی بیع اور انگور کے بدلے خشک انگور کی بیع وغیرہ بیع مزابنہ کہلاتی ہے۔ مذکورہ بالا دونوں بیوع کی حرمت کا سبب یہ ہے کہ ان میں ترکھیتی یا تر میوے کی صحیح مقدار کا علم نہیں ہوتا، کہ وہ خشک ہو کر کتنا رہ جائے گا، اس طرح کسی کا بھی نقصان ہو سکتا ہے۔ بیع مخابرہ، یہ بیع مطلق طور پر حرام نہیں، بلکہ اس کی صرف ایک خاص صورت ہی حرام ہے اور وہ یہ ہے کہ مالک مکمل پیداوار کا تیسرا یا چوتھا حصہ مقرر کرنے کی بجائے مزارع کے لیے زمین کے ایک خاص حصے کی پیداوار بطور معاوضہ مقرر کر لے، اس کا نقصان یہ ہوگا کہ بعض اوقات مزارع کی زمین میں پیداوار زیادہ ہو جائے گی اور بعض اوقات مالک کی زمین میں اس طرح دونوں میں جھگڑے کی نوبت آ جائے گی، اسی لیے اس بیع سے منع کر دیا یا گیا ہے، مذکورہ بالا حدیث کے آخر میں ہے کہ کھجور کی بیع نہ کی جائے، حتی کہ وہ سرخ ہو جائے یا زرد ہو جائے یا وہ کھانے کے قابل ہو جائے، کیونکہ اس سے پہلے فروخت کی جائے تو اس میں دھوکہ ہے اور دھوکے کی بیع سے نبی مکرم میم نے منع فرمایا ہے۔ دیکھئے: (مسلم، کتاب البیوع، رقم: ١٥١٣، ابو داؤد، رقم: ٣٣٧٦)","",{"k":"صحیح بخاری (٢١٩٦)۔"}],[6387,"سیدہ ام سلمہ رونی و یا بیان کرتی ہیں، سیدنا ابو بکر ہی اللہ تجارت کی غرض سے بصری کی طرف گئے۔ رسول اللہ صلی اللہ علیہ وسلم سے الفت اور آپ صلی اللہ علیہ وسلم کی صحبت نے سیدنا ابو بکر رضی اللہ عنہ کو اپنا نصیب حاصل کرنے سے روکا نہ رسول اللہ ملے نے سیدنا ابو بکر ضیا اللہ کو ان سے محبت و رفاقت ہونے کے باوجود روانگی سے منع کیا، حالانکہ آپ صلی اللہ علیہ وسلم کو سیدنا ابو بکر بنی اللہ سے محبت تھی، لیکن رسول اللہ ملنے کی اہم تجارت کو مستحب سمجھتے تھے اور وہ آپ صلی اللہ علیہ وسلم کو بھلی لگتی تھی، اس لیے آپ صلی اللہ علیہ وسلم نے انہیں منع نہیں فرمایا۔“ اس حدیث کو زہری سے صرف اسحاق بن راشد نے روایت کیا۔ اس میں موسی بن اعین کا تفرد ہے۔","",{"k":"٥-٥، کر مجمع الزوائد (٤/٦٢)، سلسله صحیحه (٢٩٢٩)، مجمع البحرين (١٩٢٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام تجارت کے پیشہ سے محبت کرتے تھے۔ اور اس کے لیے کوشش بھی کرتے اور اس کی خاطر دور دراز علاقوں کا سفر بھی کرتے تھے۔ لیکن ان کا یہ شوق اور حرص ان کی محبت مصطفی ملنے دی ایم کو متاثر نہ کر سکی، وہی بندگان رب میدان جہاد میں نظر آتے تھے، حج وعمرہ کے سفروں میں آپ صلی اللہ علیہ وسلم کے ہم سفر ہوتے اور آپ صلی اللہ علیہ وسلم کی آنکھ کے اشارے پر مال و جان لٹا دیتے۔ Buck"}],[6388,"سیدنا جابر میل الیہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے ایک اعرابی سے میرا خیال ہے کہ انہوں نے کہا: بنو عامر بن صعصعہ سے ( بطور چارہ) ایک گھڑی پتے خریدے، پس جب اس کے لیے بیچ واجب کر دی تو نبی میم نے فرمایا: ” (بیع کو باقی رکھنے یا منسوخ کرنے کا ) انتخاب کر لے۔‘‘ اعرابی نے کہا: اگر میں آج کے دن کی طرح کوئی دن دیکھوں، اللہ تمہاری عمر دراز کرے، آپ کس قبیلے سے ہیں؟ آپ نے فرمایا: ” قریش سے۔“ اس حدیث کو ابن جریج سے صرف یحیی بن ایوب نے روایت کیا اور یحیی بن ایوب سے صرف لیث بن سعد اور موسی بن امین نے روایت کیا۔","",{"k":"سنن ابن ماجه، قال الشيخ الالباني: حسن۔"}],[6389,"سیدہ عائشہ لیا جا نے بیان کیا، میں سیدہ ام مسطح نا ہلا کے پاس گئی۔ پس میں قضائے حاجت کے لیے کھجور کے درختوں کے جھنڈ کی طرف گئی۔ ام مسطح بنا لیا کے پاؤں میں ہڈی یا کانٹا لگا تو SCIS انہوں نے کہا: مسطح برباد ہو، میں نے کہا: تم نے برے الفاظ کہے ہیں، تم رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے ایک آدمی کو برا بھلا کہتی ہو۔ انہوں نے کہا: میں گواہی دیتی ہوں کہ آپ بھولی بھالی بے خبر مومنہ ہیں۔ کیا آپ کو معلوم ہے کہ آپ کے خلاف کیا کچھ مشہور کر دیا گیا ہے؟ میں نے کہا: نہیں، اللہ کی قسم! انہوں نے کہا: آپ کی رسول اللہ صلی اللہ علیہ وسلم کے ہاں باری کب ہے؟ میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم اپنی ازواج کے بارے میں اپنی پسند کے مطابق کرتے ہیں، آپ جسے پسند کرتے ہیں اس سے آغاز کرتے ہیں اور ان میں سے جسے پسند کرتے ہیں، مؤخر کر دیتے ہیں، انہوں نے کہا: آپ کے خلاف یہ یہ مشہور کر دیا گیا ہے۔ پس میں بے ہوش ہو کر گر پڑی، پس میری والدہ سیدہ ام رومان نی نی یا کوخبر پہنچی، جب انہیں خبر پہنچی کہ سیدہ عائشہ ریلی نیہا کو اس معاملے کا پتہ چل گیا ہے وہ میرے پاس آئیں، انہوں نے مجھے اٹھایا اور میں ان کے گھر چلی گئی۔ رسول اللہ سے تم کو خبر پہنچی کہ عائشہ کو اس معاملے کا پتہ چل گیا ہے تو آپ ان کی طرف آئے اور ان کے پاس آکر بیٹھ گئے اور فرمایا: \"عائشہ! اللہ نے تو بہ کو کشادہ کیا ہے۔ پس مجھے جو تکلیف تھی اس میں اضافہ ہو گیا، میں اسی کیفیت میں تھی کہ ابو بکر تشریف لائے اور میرے پاس آئے تو انہوں نے کہا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم اس کے متعلق کیا انتظار کرتے ہیں جس نے آپ صلی اللہ علیہ وسلم سے خیانت کی اور مجھے رسوا کر دیا، عائشہ نبی اشیا نے فرمایا: ”میری تکلیف میں مزید اضافہ ہو گیا، انہوں نے فرمایا: پس انہوں نے علی رضی اللہ عنہ کو بلا بھیجا تو فرمایا: ” علی! عائشہ کے بارے میں تمہاری کیا رائے ہے؟ انہوں نے کہا: اللہ اور اس کے رسول ملے تعلیم بہتر جانتے ہیں، آپ نے فرمایا: ” تم مجھے ضرور بتاؤ کہ عائشہ کے بارے میں تمہاری کیا رائے ہے؟ انہوں نے کہا: اللہ نے عورتوں کی کمی نہیں چھوڑی، لیکن ان کی خادمہ سیدہ بریرہ نیا نیا کو بلائیں اور اس سے پوچھیں، ہو سکتا ہے کہ اسے ان کے کسی معاملے کا پتہ ہو۔ پس آپ صلی اللہ علیہ وسلم نے سیدہ بریرہ بنی اشیا کو بھلا بھیجا، وہ آئیں تو آپ صلی اللہ علیہ وسلم نے ان سے کہا: ”کیا تم گواہی دیتی ہو کہ میں اللہ کا رسول ہوں؟ انہوں نے عرض کیا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں تم سے کسی چیز کے بارے میں سوال کروں تو مجھ سے چھپانا نہیں۔ انہوں نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم جس چیز کے متعلق مجھ سے سوال کریں گے تو میں آپ صلی اللہ علیہ وسلم کو بتا دوں گی، ان شاء اللہ میں آپ صلی اللہ علیہ وسلم سے کوئی چیز مخفی نہیں رکھوں گی، آپ علم نے فرمایا: تم عائشہ کے پاس رہی ہو کیا تم نے اس میں کوئی ایسی چیز دیکھی ہے جسے تم نا پسند کرتی ہو؟“ انہوں نے عرض کیا: نہیں، اس ذات کی قسم جس نے آپ صلی اللہ علیہ وسلم کو نبوت کے ساتھ مبعوث فرمایا! میں جب سے ان کے پاس ہوں میں نے بس ان میں ایک عادت دیکھی ہے، فرمایا: ”وہ کیا ہے؟“ انہوں نے عرض کیا: میں نے اپنے لیے آٹا گوندھا تو میں نے عائشہ سے کہا: اس آٹے کی حفاظت کرنا، حتی کہ میں آگ کا شعلہ لے لوں، پس میں روٹیاں پکاؤں گی، پس وہ کھڑی ہو کر نماز پڑھنے لگیں، اور آٹے سے غافل ہو گئیں، اتنے میں بکری آئی اور آٹا کھا گئی، آپ میم نے اسامہ ولی اللہ کو پیغام بھیجا اور فرمایا: ”اسامہ! عائشہ کے بارے میں تمہاری کیا رائے ہے؟ انہوں نے عرض کیا، اللہ اور اس کے رسول ملے علیم بہتر جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم اس کے متعلق جو جانتے ہو، وہ مجھے ضرور بتاؤ۔“ انہوں نے عرض کیا: میں تو یہی سمجھتا ہوں کہ آپ ان کے متعلق خاموشی اختیار فرمائیں حتی کہ ان کے متعلق اللہ آپ کو کوئی حکم فرما دے۔ سیدہ عائشہ منی نیہا نے فرمایا: ” تھوڑی سی دیر ہوئی تھی کہ وحی نازل ہوئی، پس جب وحی نازل ہوئی ہم رسول اللہ صلی اللہ علیہ وسلم کے چہرے میں خوشی دیکھنے لگے اور اللہ عز وجل کی طرف سے ان کا عذر آ گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! خوش ہو جا، عائشہ! پھر خوش ہو جا، اللہ نے تمہارا عذر بھیج دیا، میں نے کہا: آپ اور آپ کے ساتھی کے شکریے کے بغیر راوی نے بیان کیا: اس وقت انہوں نے کلام فرمایا اور جب آپ ملے لی ہم ان کے ہاں تشریف لایا کرتے تھے تو فرماتے تھے: ”تم کیسی ہو؟‘اس حدیث کو مقسم سے صرف خصیف نے روایت کیا۔ اس میں عتاب بن بشیر کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩/٢٣٠)، صحیح بخاری (٤٧٥٠)، مجمع البحرين (٣٨٣٢)۔","f":"نبی معظم ملے ان کی عادت مبارکہ تھی کہ جب آپ لے لیاتی سفر پر جاتے تو اپنی بیویوں کے نام قرعہ ڈالتے، جس خاتون کے نام قرعہ نکلتا، اسے آپ صلی اللہ علیہ وسلم ساتھ لے جاتے، چنانچہ غزوہ بنی مصطلق میں قرعہ ڈالا گیا تو قرعہ سیدہ عائشہ منی انا کے نام نکلا، سیدہ عائشہ منی نہیں فرماتی ہیں کہ یہ واقعہ حجاب کا حکم نازل ہونے کے بعد کا ہے۔ میں ایک ہووج میں سوار رہتی اور جب اترتی تو ہو وج سمیت اتار لی جاتی، ہم اس طرح سفر کرتے رہے جب آپ صلی اللہ علیہ وسلم اس غزوہ سے فارغ ہوئے اور سفر سے لوٹے تو ہم لوگ مدینہ کے نزدیک آن پہنچے، پڑاؤ کے دوران میں اٹھی اور پیدل چل کر لشکر سے پار نکل گئی، جب حاجت سے فارغ ہوئی اور لشکر کی طرف آنے لگی تو مجھے معلوم ہوا کہ ظفار کے نگینوں کا ہار میرے گلے سے ٹوٹ کر گر چکا ہے، میں ڈھونڈ نے لگی اور اسے ڈھونڈتے ڈھونڈتے دیر ہوگئی۔ اتنے میں وہ لوگ جو میرا ہو وج اٹھا کر اونٹ پر لادا کرتے تھے، انہوں نے ہووج اٹھایا اور میرے اونٹ پر لاد دیا، رات کا وقت تھا، لشکر کوچ کر گیا، وہ سمجھ رہے تھے کہ میں ہووج میں موجود ہوں کیونکہ اس زمانہ میں عورتیں ہلکی پھلکی ہوتی تھیں، کم خوراک کھایا کرتیں، گوشت سے بوجھل اور بھاری نہ ہوتی تھیں، لہذا ان لوگوں نے ہووج اٹھایا اور ہووج اونٹ پر لاد کر چل دیئے لشکر کے روانہ ہونے کے بعد میرا ہارمل گیا، میں جب واپس آئی تو دیکھا کہ وہاں کوئی پکارنے والا ہے نہ کوئی جواب دینے والا میں وہاں جا کر بیٹھ گئی، جہاں پہلے بیٹھی ہوئی تھی، مجھے یقین تھا کہ جب وہ لوگ مجھے نہ پائیں گے تو اسی جگہ تلاش کرنے آئیں گے، میں وہاں بیٹھی رہی، نیند نے غلبہ کیا، اور میں سو گئی لشکر کے پیچھے پیچھے گرے پڑے سامان کی خبر رکھنے کے لیے صفوان بن معطل سلم نبی اللہ مقرر تھے، وہ پچھلی رات چلے اور صبح میرے ٹھکانے کے قریب پہنچے تو انہوں نے دور سے کسی انسان کو سوتے ہوئے دیکھا، پھر میرے قریب آئے تو مجھے پہچان لیا، کیونکہ حجاب کا حکم نازل ہونے سے پہلے انہوں نے مجھے دیکھا تھا، جب انہوں نے مجھے پہچانا تو ((انا للہ وانا اليه راجعون)) پڑھا، جس پر میں بیدار ہوگئی اور اپنی چادر سے اپنا چہرہ ڈھانپ لیا۔ اللہ کی قسم! انہوں نے مجھ سے کوئی بات کی اور نہ میں نے ((انا لله وانا اليه راجعون) کے سوا کوئی بات سنی، انہوں نے اب اپنی سواری بٹھائی اور اس کا پاؤں اپنے ہاتھ سے دبائے رکھا، میں اس پر سوار ہو گئی، وہ پیدل چلتے رہے اور اونٹنی کو چلاتے رہے تا آنکہ ہم لشکر سے اس وقت جا ملے جب اہل لشکر عین دو پہر کی گرمی کی شدت کی وجہ سے پڑاؤ کیسے ہوئے تھے، جن لوگوں کی قسمت میں بربادی لکھی تھی وہ تباہ ہوئے، اس تہمت کو سب سے زیادہ پھیلانے والا عبد اللہ بن ابی بن سلول تھا، خیر ہم لوگ مدینہ پہنچے، وہاں پہنچ کر میں بیمار ہو گئی اور مہینہ بھر بیمار رہی، لوگ تہمت لگانے والوں کی باتوں کا چرچا کرتے رہے اور مجھے خبر تک نہ ہوئی۔ البتہ ایک بات سے مجھے وہم سا ہوا کہ آپ ملنے کی یمن کی وہ مہربانی جو بیماری کی حالت میں مجھ پر ہوا کرتی تھی، وہ اس بیماری میں نہیں تھی، آپ تشریف لاتے، السلام علیکم کہتے، پھر یہ پوچھ کر کہ اب طبیعت کیسی ہے؟ چل دیتے، اس بات سے مجھے کچھ شک تو پڑتا مگر کسی بات کی خبر نہ تھی، بیماری سے کچھ افاقہ ہوا میں ابھی کمزور ہی تھی کہ مناصح کی طرف گئی، مسطح کی ماں ( سلمی ) میرے ساتھ تھی"}],[6390,"سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز پڑھانے کے لیے کھڑے تھے کہ اچانک تشریف لے گئے، پھر آپ آئے تو آپ کے سر سے پانی کی قطرے گر رہے تھے، آپ نے فرمایا: میں تمہیں نماز پڑھانے کھڑا تھا کہ مجھے یاد آ گیا کہ میں جنسی تھا اور میں نے غسل نہیں کیا تھا، پس میں گیا اور غسل کیا، پس تم میں سے کسی کو یہی مسئلہ در پیش ہو جو مجھے درپیش ہوا ہے یا وہ اپنے پیٹ میں گڑ بڑ محسوس کرے تو وہ جائے اور غسل کرے، پھر آئے اور اپنی نماز کی طرف متوجہ ہو۔ “ یہ حدیث سید علی علی علیہ سے صرف اس اسناد سے مروی ہے، اس میں ابن لہیعہ کا تفرد ہے۔ ٦٣٩١","",{"k":"مسند احمد: ٩٩/١ . ضعيف . مجمع الزوائد (٢/٦٨)، قال شعیب الارناؤط: اسناده۔"}],[6391,"سیدنا علی ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں اپنی امت پر کسی شخص کو ان کے مشورے کے بغیر امیر مقرر کرتا تو میں ابن ام عبد کو ان کا امیر مقرر کرتا۔“ اس حدیث کو ابو اسحاق سے صرف منصور نے روایت کیا۔ اس میں زہیر کا تفرد ہے۔","",{"k":"کی سنن ترمذی، قال الشيخ الالباني: ضعيف۔"}],[6392,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو عصر کے بعد دو رکعتوں سے منع کرتے ہوئے سنا، جس نے ان کا حکم دینے والے کو سنا ہے، اسے پیش کرو۔“","",{"k":"صحیح بخاری کتاب مواقيت الصلاة (٥٨٦)، مسلم (٨٢٧١)۔"}],[6393,"سیده ام عطیہ نبی اشیا نے بیان کیا، ہم نے رسول اللہ صلی اللہ علیہ وسلم کی بیعت کی، آپ صلی اللہ علیہ وسلم نے جن معروف کاموں کا ہمیں حکم فرمایا، وہ یہ تھا کہ ہم نوحہ نہیں کریں گی، ایک عورت نے عرض کیا: اللہ کے رسول! آل فلاں کی خواتین نے (نوحہ کرنے میں ) میری مدد کی تھی، پس میں آپ ملنے کی بیعت نہیں کروں گی حتیٰ کہ میں ان کی مدد کرلوں، انہوں نے بیان کیا، میں نے ان کی مدد کی، پھر آپ صلی اللہ علیہ وسلم کی بیعت کی، اس عورت اور ام سلیم کے علاوہ کسی عورت نے وفا نہ کی۔“","",{"k":"صحيح بخاری کتاب التفسير (٤٨٩٢)، مسلم (٩٣٧)۔","f":"اندن پیچھے بھی احادیث گزر چکی ہیں کہ نبی معظم نے بیعت لیا کرتے تھے اور مذکورہ بالا روایت سے بھی معلوم ہوتا ہے، ان تمام احادیث سے یہی بات ثابت ہوتی ہے کہ ان چیزوں کی بیعت لی، جن کا عام ارتکاب عورتوں سے ہوتا تھا، تا کہ وہ ارکان دین کی پابندی کے ساتھ ان چیزوں سے بھی اجتناب کریں۔ اس سے یہ بات معلوم ہوئی کہ علماء دعاۃ اور واعظین حضرات اپنا زور خطابت ارکان دین کے بیان کرنے میں ہی صرف نہ کریں، جو پہلے ہی واضح ہیں، بلکہ ان خرابیوں اور رسموں کی بھی پرزور انداز میں تردید کیا کریں، جو معاشرے میں عام ہیں، کیونکہ اکثر نماز روزے کے پابند حضرات بھی ان سے اجتناب نہیں کرتے۔ ٦٣٩٤"}],[6394,"سیدہ ام عطیہ روی اشیا نے بیان کیا، ہمیں، پردہ نشینوں اور کنواری لڑکیوں کو عیدین کے لیے عید گاہ جانے کا حکم دیا جاتا تھا۔ انہوں نے کہا: حیض والی خواتین بھی جاتی تھیں، وہ لوگوں کے پیچھے ہوتی تھیں اور لوگوں کے ساتھ تکبیر میں کہتی تھیں۔“ ٦٣٩٥","",{"k":"صحيح مسلم (١٩./١١)۔"}],[6395,"سیدنا عمرو بن سلمہ رضی اللہ عنہ نے بیان کیا، کسی قبیلے کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو انہوں نے آپ ملنے کی تم کو فرماتے ہوئے سنا: ”تم میں سے جو قرآن کا زیادہ قاری ہو وہ تمہاری امامت کرائے۔ پس انہوں نے مجھے اپنا امام بنایا جبکہ میں لڑکا تھا، میں ایک پیوندگی چادر میں ان کی امامت کراتا تھا اور وہ چھوٹی تھی، پس جب میں سجدہ کرتا تھا تو میرے سرین ظاہر ہو جاتے تھے۔ انہوں نے میرے والد سے کہا: کیا تم اس کے سرین ہم سے نہیں چھپاتے؟ میں قرآن سیکھنے میں ان سب سے زیادہ رغبت رکھتا تھا۔ زہیر نے کہا: وہ نماز اور جنازوں میں اپنی قوم کی امامت کراتے رہے۔ ان احادیث کو عاصم الاحول سے صرف زہیر بن معاویہ نے روایت کیا۔ ناندن مذکورہ حدیث سے معلوم ہوا کہ کم سن بچے کی امامت درست ہے۔ (سنن ابی داؤد میں ہے سیدنا عمر و بن سلمہ فی اللہ بیان کرتے ہیں کہ میری عمر اس وقت سات یا آٹھ سال تھی ) امام شافعی رحمہ اللہ اسی کے قائل ہیں، جبکہ امام مالک اللہ نے اسے مکروہ کہا ہے اور امام احمد اور امام ابو حنیفہ عبداللہ نے کہا ہے کہ بچے کی امامت نوافل میں کفایت کرتی ہے، فرائض میں نہیں۔ (فتح الباری: ٢/ ٤١٥، نیل الاوطار: ٢/ ٤٢٥، کتاب الام: ١/ ٢٩٥، المغنی: ٧٠/٣، البدایه /٥٦) راجح موقف امام شافعی ہمالہ کا ہے۔ یہ بھی معلوم ہوا کہ امام اگر نفل پڑھ رہا ہو تو اس کے پیچھے فرض کی نیت کی جاسکتی ہے کیونکہ بچے کی نماز اس کے حق میں نفل ہوتی ہے۔","",{"k":"صحیح بخاری (٤٢٠٢)، ابو داود (٥٨٦)۔"}],[6396,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علی یم نے فرمایا: ”جو لا الہ الا اللہ کا اقرار کرتا ہے وہ اس کی زندگی میں ایک دن اسے","",{"k":"مجمع الزوائد (١/١٧)، صحیح ترغیب و ترهيب (١٥٢٥)۔","f":"پہنچائے گا، اس سے پہلے جو اسے پہنچ چکا سوپہنچ چکا۔‘اس حدیث کو حصین سے صرف حدیج بن معاویہ نے روایت کیا۔ مانده مذکورہ حدیث سے کلمہ توحید کی فضیلت ثابت ہوتی ہے اور کلمہ توحید کہنے والوں کے لیے فوائد بھی ثابت ہوتے ہیں اور کلمہ توحید کہنے والوں کے لیے دوزخ کا عذاب ہمیشہ نہیں ہے وہ جو گناہ گار ہے، اس کو گناہوں کی سزا دے کر جنت دے دی جائے گی۔"}],[6397,"سیدنا عبداللہ ابن عباس والہا نے بیان کیا، مفصل سورتوں میں سجدے نہیں، پس میں (ابو العریان ) ابو عبیدہ بن عبد اللہ بن مسعود کے پاس آیا۔ تو سیدنا ابن عباس ریلی اینجا نے جو کہا تھا اس کا ان سے ذکر کیا تو انہوں نے کہا: سیدنا عبد اللہ بن مسعود ضیا اللہ نے فرمایا: سورۃ النجم میں رسول اللہ علیم مسلمانوں اور مشرکوں نے سجدہ کیا، پس ہم سجدہ کرتے رہیں گے۔“ اندن صحیح بخاری میں ہے کہ سب نے سجدہ کیا، لیکن ایک آدمی نے کنکریوں کی یا مٹی کی ایک مٹھی لی اور اپنے چہرے کی طرف اٹھائی اور کہا: مجھے یہی کافی ہے۔ سیدنا عبد اللہ بن مسعود بنی اہلیہ بیان کرتے ہیں: میں نے بعد میں اسے دیکھا کہ حالت کفر میں قتل کر دیا گیا۔ (بخاری، رقم: ١٠٧٠) مذکورہ بالا حدیث سے معلوم ہوا کہ سجدہ تلاوت کرنا مسنون ہے اور سورہ نجم کے سجدے کی مشروعیت بھی ثابت ہوتی ہے،۔ یہ بھی معلوم ہوا کہ پڑھنے اور سننے والے تمام کو سجدہ کرنا چاہیے۔ مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ قرآن مجید کی یہ تاثیر ہے کہ مشرکین مکہ بھی عالم بے خودی میں سجدہ میں گر گئے۔ جس نے سجدہ نہ کیا، یہ متکبر امیہ بن خلف تھا، جو کفار مکہ کے سرداروں میں سے تھا۔","",{"k":"صحیح بخاری (١٠٧٠)، مسلم۔"}],[6398,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، ہم ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، رات کے آخری حصے میں ہم نے پڑاؤ ڈالا، ہم آپ ملنے دین کے ساتھ تقریباً ایک ہزار کی تعداد میں تھے، آپ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں، پھر ہماری طرف متوجہ ہوئے، آپ صلی اللہ علیہ وسلم ن کی آنکھیں اشک بار تھیں۔ سیدنا عمر بن خطاب فضل اللہ آپ صلی اللہ علیہ وسلم کے سامنے کھڑے ہوئے اور آپ پر اپنے والدین قربان ہونے کا کہتے ہوئے،عرض کرنے لگے: اللہ کے رسول! آپ صلی اللہ علیہ وسلم کو کیا ہوا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے اپنی والدہ کے استغفار کے لیے اپنے رب سے اجازت طلب کی تو اس نے مجھے اجازت نہ دی۔ پس جہنم سے ان کے لیے ترس کھاتے ہوئے میری آنکھیں اشک بار ہو گئیں اور میں تین چیزوں سے تمہیں منع کیا کرتا تھا، قبروں کی زیارت سے، پس ان کی زیارت کرو، ان کی زیارت تمہیں خیر میں بڑھائے گی۔ میں نے تین دن کے بعد قربانیوں کا گوشت کھانے سے تمہیں منع کیا تھا، پس کھاؤ اور جتنا چاہو رکھ لو۔ میں نے مشروبات سے تمہیں منع کیا تھا، پس پیو اور نشہ آور نہ پیو۔“ اس حدیث کو زبید الیا می سے صرف زہیر بن معاویہ نے روایت کیا۔","",{"k":"صحيح مسلم (٩٧٧)، سنن ابو داود (٣٦٩٨)، مسند احمد (٥/٣٥٥، ٢٣٨، ٢٧٠٩)۔","f":"کسی کے لیے سفارش کرنا اللہ ذوالجلال سے وہی قبول ہو سکتی ہے، جس کی اللہ ذوالجلال اجازت دے اور اللہ ذوالجلال نے استغفار کرنے سے روک دیا تو نبی معظم صلی اللہ علیہ وسلم رک گئے۔ مذکورہ بالا روایت سے یہ بھی معلوم ہوا کہ قبروں کی زیارت کرنا جائز ہے۔ نبیذ بنانا جائز ہے، کسی بھی برتن میں بنا لیا جائے"}],[6399,"سیدنا عبداللہ ابن عباس نوای نینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” روزہ دار شخص جب ایسے لوگوں میں بیٹھتا ہے جو کہ کھانا کھا رہے ہوں تو فرشتے اس پر رحمتیں نازل کرتے ہیں حتی کہ روزہ دار افطار کر لیتا ہے۔“","",{"k":"مجمع الزوائد (٣/٢٠)، مجمع البحرين (١٦١٠)، اسناده ضعيف۔"}],[6400,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ ملے عام نماز کے بعد دعا کیا کرتے تھے: ”اے اللہ! میں ان چار چیزوں سے تیری پناہ چاہتا ہوں۔“","",{"k":"سندہ ضعیف، اس کی سند میں ابان بن عیاش ضعیف راوی ہے ۔۔"}],[6401,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کے ہاں ہر دن رات جہنم سے آزادی پانے والے ہیں اور ہر مسلمان کے لیے ہر دن رات ایک دعا قبول ہوتی ہے۔“ صحیح ترغیب و ترہیب میں ہے کہ اللہ ذوالجلال کے لیے ہر دن رات جہنم سے آزادی پانے والے ہیں، یعنی رمضان المبارک میں۔ معلوم ہوا کہ جہنم سے آزادی کا یہ شرف خلوص کے ساتھ، سنت کے مطابق روزہ رکھ کر اور گناہوں سے تو بہ کر کے حاصل ہوسکتا ہے۔","",{"k":"مجمع الزوائد (١٤٩/١٠)، صحیح ترغیب و ترهيب (١٠٠٢)، قال الشيخ الالباني: صحيح لغيره، مجمع البحرين (٤٦٢٦)۔"}],[6402,"سیدنا معاویہ رضی اللہ عنہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو میں نے کہا: میں نے ان کے عدد کے برابر قسم اٹھائی ہے اور اپنے دونوں ہاتھوں کی انگلیوں کی طرف اشارہ کیا اور وہ دس ہیں، یہ کہ میں آپ ملنے کی اتباع کروں گا نہ آپ کی شریعت کی اتباع کروں گا۔ میں آپ صلی اللہ علیہ وسلم کو اللہ کی قسم دے کر سوال کرتا ہوں! تمہارا دین کیا ہے جس کے ساتھ اللہ نے آپ صلی اللہ علیہ وسلم کو مبعوث فرمایا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ نے مجھے اسلام کے ساتھ مبعوث فرمایا ہے۔“ اس نے کہا: اسلام کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کہ تم کہو: میں نے اپنے نفس کو اللہ کے لیے مطیع کر دیا، اپنے چہرے کو اس کے لیے خالص کر دیا، نماز قائم کر، زکوۃ ادا کر، (ہم دونوں بھائی مددگار ہیں اور یہ کہ اسلام کے بعد شرک کرنے والے کی اللہ تو بہ قبول نہیں کرتا۔ “ میں نے عرض کیا: ہماری بیویوں کے ہم پر کیا حقوق ہیں؟ آپ ملنے سلیم نے فرمایا: ”جب تم کھاؤ تو انہیں کھلا ؤ، جب پہنو تو انہیں پہناؤ، چہرے پر مارونہ، چہرے کو برا بھلا کہو اور اسے صرف گھر ہی میں الگ رکھو۔ پھر فرمایا: ” تم یہاں اکٹھے کیے جاؤ گے۔ آپ صلی اللہ علیہ وسلم نے شام کی طرف اشارہ کیا: ”پیدل چلتے ہوئے اور سواری پر تم قیامت کے دن اللہ کے پاس آؤ گے، تمہارے مونہوں پر غلاف ہو گا، تم میں سے کسی کی ران سب سے پہلے کلام کرے گی تم ستر امتوں کو پورا کرو گے تم سب سے آخر میں ہو اور اللہ کو سب سے زیادہ عزیز ہو، جو مولی کسی مولی کے پاس آئے اور اس کے پاس جو فضل ہے اس کے متعلق اس سے سوال کرے اور وہ اسے نہ دے تو وہ قیامت کے دن اس کے پاس آئے گا کہ وہ از رہا ہو گا اور اس پر زبان نکالے گا۔ تم سے پہلے لوگوں میں سے ایک آدمی تھا جسے اللہ نے بہت سا مال اور اولاد دے رکھی تھی، حتی کہ جب کچھ وقت گزر گیا اور کچھ باقی رہ گیا۔ پس جب اس کی موت کا وقت آیا تو اس نے اپنے گھر والوں سے کہا: میں تمہارے حق میں کیسا تھا؟ انہوں نے کہا: بہترین شخص تھا، اس نے کہا: میں نے تمہیں جو کچھ دیا وہ میں تم سے لے لوں گا، یا پھر میں تمہیں جو کہوں: اسے بجالاؤ، انہوں نے کہا: تم ہمیں جو حکم دو گے ہم اسے بجالائیں گے، اس نے کہا: جب میں فوت ہو جاؤں تو مجھے آگ میں ڈال دینا۔ جب میں کوئلہ ہو جاؤں تو مجھے پیس دینا، پھر ہوا کے دن مجھے اڑا دینا۔ پس اللہ نے (اسے) بلایا تو وہ جس طرح تھا اسی طرح آ گیا، فرمایا: تم نے جو کیا اس پر کس چیز نے تجھے آمادہ کیا؟ اس نے عرض کیا: رب جی! تیرے ڈر نے۔‘ ان احادیث کو محمد بن حمادہ سے صرف زہیر نے روایت کیا۔ Backac B ماندن مذکورہ حدیث سے معلوم ہوا کہ خاوند پر بیوی کے بھی حقوق ہیں، کیونکہ اسلام نے معاشرے کو صحیح بنیادوں پر قائم کرنے کے لیے ہر فرد کے حقوق و فرائض کا تعین کر دیا ہے، جس طرح مردوں کے حقوق ہیں، اسی طرح عورتوں کے بھی حقوق ہیں، جیسا کہ ارشاد باری تعالیٰ ہے: لَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ﴾ (البقره: ٢٢٨) اور دستور کے مطابق عورتوں کے لیے مردوں پر ویسے ہی حقوق ہیں، جیسے مردوں کے لیے عورتوں پر حقوق ہیں۔:٦٤٠٣ گھر میں امن وسکون قائم رکھنے کے لیے ضروری ہے کہ دونوں ایک دوسرے کے حقوق کا خیال رکھیں","",{"k":"مجمع الزوائد (١٠/١٩٥)، مجمع البحرين (٥٠٩٦.١٩٥)۔"}],[6403,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ لوگوں سے علم کو چھین کر اچانک ختم نہیں کرے گا بلکہ وہ علماء کو فوت کر کے اسے ختم کرے گا۔ جب علماء چلے جائیں گے تو لوگ جاہلوں کو اپنا سردار بنالیں گے، ان سے مسائل پوچھے جائیں گے تو وہ علم کے بغیر فتویٰ دیں گے، ( پہلے ) وہ گمراہ ہوں گے اور (پھر دوسروں کو ) سیدھی راہ سے گمراہ کریں گے۔“ اس حدیث کو زہری کے حوالے سے ابوسلمہ سے صرف العلاء بن سلیمان نے روایت کیا اور دیگر لوگوں نے اسے زہری، عن عروہ بن عائشہ عن ابی ہریرہ کی سند سے روایت کیا۔ ٦٤٠٤","",{"k":"مجمع الزوائد (١/٢٠١)، مجمع البحرين (٣٣٣)۔"}],[6404,"سیدنا علی ضیا اللہ سے روایت ہے کہ نبی تعلیم نے فرمایا: ” میں نے گھوڑے اور غلام کے صدقے کے بارے میں تم سے درگزر فرمایا۔ اس حدیث کو موسی بن عقبہ سے صرف ابن لہیعہ نے روایت کیا۔اس میں عمر بن خالد الحرانی کا تفرد ہے۔ ٦٤٠٥","",{"k":"سنن ابو داود (١٥٧٤)، قال الشيخ الالباني: صحيح۔"}],[6405,"ابراہیم بن الاشقر سے روایت ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ علیم کا ذکر کیا، پھر انہیں کہا: اللہ کا ہاتھ جماعت پر ہے اور اکیلا شخص شیطان کے ساتھ ہے، حق جنت میں اصل ہے اور باطل جہنم میں اصل ہے۔ سن لو! میرے اصحاب تم میں سب سے بہتر ہیں، پس ان کی عزت کرو، پھر وہ لوگ جو ان کے بعد آئیں گے، پھر وہ جو ان کے بعد آئیں گے، پھر جھوٹ اور قتل و غارت عام ہو جائے گی۔“ یہ حدیث مالک الاشتر سے صرف اس اسناد سے مروی ہے۔ اس میں عمرو بن خالد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٥/٢٢٥)، مجمع البحرين (٢٥٤٤، ١٦٥٩، ٢٩٢٩.٢٢٥)۔","f":"علامہ پیٹی اللہ فرماتے ہیں: فيه جماعة لم اعرفهم، تا ہم دوسری صحیح احادیث سے ثابت ہے: ((ید الله على الجماعة))"}],[6406,"سیدنا حذیفہ بن یمان رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے کچھ لوگوں کے کوڑے کرکٹ کے ڈھیر پر پیشاب کیا، پھر آپ صلی اللہ علیہ وسلم نے وضو کیا اور موزوں پر مسح کیا۔“ اس حدیث کو محمد بن عجلان سے صرف یحیی بن راشد نے روایت کیا۔ اس میں محمد بن الحارث کا تفرد ہے۔","",{"k":"صحیح بخاری (٢٢٤)، صحیح مسلم (٢٧٣)۔"}],[6407,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”میں نے جبریل علینا سے سوال کیا، کیا تم اپنے رب کو دیکھتے ہو؟“ انہوں نے کہا: میرے اور اس کے درمیان نور کے ستر پردے ہیں، اگر میں اس کے سب سے کم تر کو دیکھ لوں تو میں جل جاؤں۔‘ اس حدیث کو اعمش سے صرف ابو مسلم نے روایت کیا۔","",{"k":"مجمع الزوائد (٧٩/١)، ضعيف الجامع الصغير (٣٢١٩)، مجمع البحرين (٦٢)، اسناده ضعيف۔"}],[6408,"سیدہ عائشہ منی نیہا نے فرمایا: ایک مسکین عورت اپنے دو بیٹے اٹھائے ہوئے میرے پاس آئی، میں نے اسے تین کھجوریں دیں تو اس نے اپنے دونوں بیٹوں میں سے ہر ایک کو ان میں سے ایک ایک کھجور دے دی تو انہوں نے اسے کھا لیا، پس اس کے بیٹوں نے اس سے مزید مطالبہ کیا تو اس نے اس کھجور کے دوٹکڑے کیے، جسے وہ کھانا چاہتی تھی اور وہ ان دونوں کو دے دی۔ سیدہعائشہ بیا نیہا نے فرمایا: اس کا یہ معاملہ مجھے بہت اچھا لگا، اس نے جو کیا تھا میں نے اس کا رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا تو آپ مطلقے علیم نے فرمایا: ”اللہ نے اس کے لیے جنت واجب کر دی اور اسے جہنم سے آزاد کر دیا۔ اس حدیث کو عراک بن مالک سے صرف زیاد بن ابی زیاد نے روایت کیا۔ اس میں بکر بن مضر کا تفرد ہے۔ ٦٤٠٩","",{"k":"صحیح مسلم (٢٦٣٠)۔"}],[6409,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کو چالیس سال کی عمر میں نبوت عطا کی گئی، آپ صلی اللہ علیہ وسلم نے دس سال مکہ میں قیام کیا، پھر اللہ نے ساٹھ سال کی عمر میں آپ صلی اللہ علیہ وسلم کی روح قبض کر لی اور آپ صلی اللہ علیہ وسلم کے سر اور داڑھی میں ہیں بال بھی سفید نہ تھے۔“ اس حدیث کو عمارہ بن غزیہ سے صرف بکر بن مضر نے روایت کیا۔","",{"k":"صحیح بخاری کتاب المناقب (٣٥٤٨)، مسلم (٢٣٤٧)۔","f":"بخاری شریف کی دوسری روایت میں ہے کہ نبی مکرم نے یم کی عمر مبارک تریسٹھ سال تھی۔ دیکھئے: (بخاری، کتاب المغازی: ٤٤٦٦) راجح بات یہ ہے کہ نبوت کے بعد نبی معظم صلی اللہ علیہ وسلم نے تیرہ برس مکہ مکرمہ میں رہے اور دس برس مدینہ منورہ میں گزارے۔ جب آپ صلی اللہ علیہ وسلم اس دنیا سے رخصت ہوئے تو اس وقت آپ مے کم کی عمر مبارک تریسٹھ سال تھی۔ اس تضاد کی وجہ یہ ہے کہ جس راوی نے مکے کی زندگی کو دس سال بتایا ہے اور آپ ملنے کی کل عمر ساٹھ سال بتائی ہے تو اس نے کسر کو کوئی اہمیت نہیں دی۔ جیسا کہ اس وقت رواج تھا کہ لوگ کسر کو کوئی اہمیت نہیں دیا کرتے تھے۔"}],[6410,"سیدنا جابر فی الیہ سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے عرض کیا، اللہ کے رسول! میری اہلیہ کسی ہاتھ لگانے والے کے ہاتھ کو نہیں روکتی، آپ ملٹے سلیم نے فرمایا: ”اسے طلاق دے دو۔“ اس نے عرض کیا: میں اس سے محبت کرتا ہوں، وہ خوبصورت عورت ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس سے متمتع ہو۔“ اس حدیث کو عبدالکریم سے صرف عبید اللہ بن عمر والرقی نے روایت کیا۔ ٦٤١١","",{"k":"مجمع الزوائد ٣٣٥٤، مجمع البحرين (٢٣٣٢/)۔"}],[6411,"سيدنا ابی بن کعب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سورۃ الفاتحہ پڑھی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ” تمہارا رب فرماتا ہے: اے انسان! میں نے تم پر سات آیات نازل فرمائیں، تین میرے لیے، تین تیرے لیے اور ایک میرے اور تیرے لیے ہے، پس وہ جو میرے لیے ہیں، وہ ہیں: ﴿ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ ﴾ اور وہ جو میرے اور تیرے درمیان ہے: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ عبادت تیری طرف سے اور تیری مدد کرنا میرے ذمے ہے اور وہ آیات جو تیرے لیے ہیں، تو وہ یہ ہیں: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ یہ تیرے لیے ہے، صِرَاطَ الَّذِينَ نُعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ ﴾ جن پر غضب ہوا: وہ یہود ہیں، ﴿ وَلَا الضَّالِّينَ ﴾ نصاری ہیں۔“ ٦٤١٢","",{"k":"مجمع الزوائد (٢/١١٢)، مجمع البحرين (٨٠٨)، سلسله ضعيفه (٥٤٤٢)۔"}],[6412,"سیدنا ابی نبی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ایک دن ہمیں نماز پڑھائی تو آپ صلی اللہ علیہ وسلم نے قرآن کی ایک سورت چھوڑ دی۔ جب آپ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو سیدنا ابی بنی اہلیہ نے عرض کیا: اللہ کے رسول! کیا فلاں اور فلاں آیت منسوخ کر دی گئی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں۔ انہوں نے عرض کیا: آپ صلی اللہ علیہ وسلم نے انہیں پڑھا نہیں۔ آپ ملنے کی تم نے فرمایا: تم نے مجھے لقمہ کیوں نہ دے دیا۔“ ان دونوں حدیثوں کو زہری سے صرف سلیمان بن ارقم نے روایت کیا۔ ٦٤١٣","",{"k":"کر مجمع الزوائد (٦٩/٢)، اسناده ضعیف، مجمع البحرين (٧٢٩)۔"}],[6413,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، ایک آدمی آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے دن لوگوں کو خطبہ ارشاد فرما رہے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ”کھڑا ہو اور اختصار کے ساتھ دورکعتیں پڑھ۔ اس حدیث کو غالب بن عبید اللہ سے صرف محمد بن سلمہ نے روایت کیا۔","",{"k":"/ ٠ / صحیح بخاری (٩٣٠)، صحیح مسلم۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے کہ دوران خطبہ مسجد میں آنے والے کو دو رکعت نماز پڑھ کر بیٹھنا چاہیے۔ امام احمد اور امام شافعی عبدالے اس کے قائل ہیں، جبکہ امام مالک اور امام ابو حنیفہ جمال کا موقف اس کے برخلاف ہے۔ (کتاب الام: ١/ ٣٣٨، المغنی: ٣/، المجموع: ٤ / ٤٢٨) مگر مذکورہ بالا روایت ان کے موقف کا رد کرتی ہے لہذا پہلا موقف راجح ہے۔ مزید دیکھئے: (فتح الباری: ٣/ ٧٣، شرح مسلم للنووي: ٤٣٠/٣، تحفة الاحوذى: ٥١/٣، سبل السلام: (٢ / ٦٤٢) شیخ ابن باز جاللہ نے بھی اسی کے مطابق فتوی دیا ہے۔ (فتاوی اسلامیه: ١/ ٤٠٢) ٦٤١٤"}],[6414,"سیدنا ابو طلحہ رضی اللہ عنہ نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم کا چہرہ مبارک خوشی سے دمک رہا تھا۔ میں نے عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم جس حال پر ہیں میں نے اس حال پر آپ کے علم کو نہیں دیکھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے کون سی چیز مانع ہو سکتی ہے؟ ابھی ابھی جبریل علینا میرے پاس آئے تو انہوں نے مجھے کہا: اپنی امت کو خوشخبری سنا دیں کہ جس نے آپ ملنے کی یکم پر ایک مرتبہ صلاۃ پڑھی، اللہ اس کے بدلے میں اس کے لیے دس نیکیاں لکھ دیتا ہے اور اس وجہ سے اس کے دس گناہ معاف کر دیتا ہے۔“ اس حدیث کو الزہری سے صرف زید بن رفیع اور عبد العزیز بن ابی سلمہ الماجشون نے روایت کیا۔ اس میں زید بن رفیع سے حماد بن عمرو کا اور الماجشون سے الولید بن سلمہ الطبر انی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ ایک مرتبہ درود پاک پڑھنے سے دس نیکیاں ملتی ہیں اور دس گناہ معاف ہو جاتے ہیں۔ درود شریف پڑھنے کی اہمیت و فضیلت کا اندازہ اس سے بھی لگایا جا سکتا ہے کہ درود پڑھنے کا حکم خود اللہ ذوالجلال نے دیا ہے۔ ارشاد باری تعالی ہے: إن اللهَ وَمَلَئِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَأَيُّهَا الَّذِينَ آمَنُوا صَلُّوْاعَلَيْهِ وَسَلِّمُوا تسليما﴾ (الاحزاب: ٥٦) یقینا اللہ ذوالجلال اور اس کے فرشتے نبی پر صلاۃ بھیجتے ہیں، اے وہ لوگو جو ایمان لائے ہو تم بھی آپ پر صلاۃ بھیجو اور سلام بھیجو، سلام بھیجنا۔“","",{"k":"سنن نسائی، مجمع الزوائد (١٠/١٦١)، مسند احمد ٢٩/٤۔"}],[6415,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ اسے علم کو فرماتے ہوئے سنا: جس شخص کا اونٹ ہو سنن ابی داؤد میں ہے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ اونٹوں کا کیا حق ہے؟ انہوں نے کہا: تو بہترین اونٹ ( اللہ کی راہ میں ) دے دے، زیادہ دودھ دینے والی اونٹنی عطیہ کر دے، کوئی سواری عاریتاً دے دے اور جفتی کے لیے نر دے دے اور لوگوں کو دودھ پلا دے۔: (سنن ابی داؤد، رقم: ١٦٦٠) -٥-٥-","",{"k":"سنن ابو داود (١٦٦٠)۔"}],[6416,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” کھجور کو فروخت نہ کر وحتی کہ اس کی پختگی ظاہر ہو جائے اور سونے کو فروخت نہ کرو مگر برابر برابر۔“ اس حدیث کو جابر سے صرف یحیی بن ابی انیسہ نے روایت کیا۔ اس میں موسی بن اعین کا تفرد ہے۔","",{"k":"مجمع الزوائد (٤/١٠٢)، مجمع البحرين (٢٠١٩)، اسناده ضعيف۔"}],[6417,"سیدنا جندب بن سفیان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: فرض نماز کے بعد افضل نماز، نماز تہجد ہے اور ماہ رمضان کے بعد افضل روزہ اللہ کے مہینے کا روزہ ہے جسے تم محرم کہتے ہو۔“ مذکورہ روایت سے نماز تہجد کی فضیلت ثابت ہوتی ہے۔ ایک دوسری روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بندہ رات کے آخری حصے میں اللہ تعالیٰ کے سب سے زیادہ قریب ہوتا ہے اس لیے تم اس وقت اللہ کا ذکر کرنے والوں میں سے ہو سکتے ہو تو ہو جاؤ۔ (ابو داود، رقم: ١٢٧٧، حاکم: ٣٠٩/١) اور نبی مکرم ملے تم نے اپنی امت کے لوگوں کو قیام اللیل کی ترغیب دی۔ فرمایا: قیام اللیل کو لازم پکڑو، بلاشبہ یہ تم سے پہلے نیک لوگوں کی روش، پروردگار کی قربت کا ذریعہ اور برائیاں مٹانے کا سبب ہے۔ (ترمذی، رقم: ٣٥٤٩، هداية الرواة: ٢/ ٤٦) ٩ ٤٦/٢) (٢) یہ بھی معلوم ہوا کہ رمضان شریف کے بعد افضل روزہ محرم کا ہے۔ جو اللہ کی طرف مہینے کی نسبت کی گئی ہے، اس سے بھی اس کے روزہ کی فضیلت کا انداہ لگایا جا سکتا ہے اور جیسے بیت اللہ، ناقة الله وغیرہ اسی طرح ہی شهر الله ہے۔ ٦٤١٨","",{"k":"مجمع الزوائد (٣/١٩١)، مسلم (١١٦٣)، سنن ابو داود (٢٤٢٩)۔"}],[6418,"سیدنا انس نبی اللہ نے بیان کیا، ہم رسول اللہ مالی ایم کے ساتھ حج کرنے کے لیے روانہ ہوتے تھے، ہم اگلے دن روحا کے مقام پر نہیں پہنچتے تھے حتی کہ ہمارے گلے بیٹھ جاتے تھے یعنی بلند آواز سے تلبیہ پکارنے کی وجہ سے۔“ اس حدیث کو ابو الزناد سے صرف عمر بن صبہان نے اور عمر سے صرف عیسی بن یونس نے روایت کیا۔ اس میں موسی بن اعین کا تفرد ہے۔","",{"k":"کر مجمع الزوائد (٢٢٤/٣)، مجمع البحرين (١٧٠٤)۔","f":"مذکورہ روایت ضعیف ہے تاہم دوسری صحیح احادیث سے ثابت ہے کہ مردوں کو تلبیہ بلند واز سے پکارنا چاہیے۔ جیسا کہ سیدنا خلاد بن سائب نبی اللہ اپنے باپ (حضرت سائب خضی اللہ ) سے روایت کرتے ہیں کہ نبی مکرم ملنے ہیم نے فرمایا: میرے پاس جبریل عالی نام آئے اور مجھے (اللہ کی طرف سے ) حکم دیا کہ میں اپنے اصحاب کو حکم دوں کہ وہ تلبیہ بلند آواز سے کہیں۔ (ابن ماجه، کتاب المناسك، باب رفع الصوت والتلبيه) بلند آواز سے تلبیہ کہنا اجر وثواب میں اضافہ کا باعث ہے۔"}],[6419,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مشکیزے کا منہ موڑ کر ان میں سے منہ لگا کر پانی پینے سے منع فرمایا۔ اس حدیث کو اوزاعی، عن الزہری، عن عطاء بن یزید کی سند سے صرف موسی بن امین نے روایت کیا۔ اور دیگر نے زہری عن عبید اللہ بن عبد اللہ بن عتبہ کی سند سے روایت کیا اور اسی طرح اصحاب زہری نے اسے روایت کیا۔","",{"k":"صحیح بخاری (٥٦٢٥)، صحیح مسلم (٢٠٢٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مشک سے منہ لگا کر پانی پینا درست نہیں ہے۔ اسی طرح نکے کی نالی یا ٹوٹی وغیرہ سے بھی منہ لگا کر نہ پیا جائے، ہو سکتا ہے کہ کوئی نقصان دہ چیز ہو جو پیٹ کے اندر چلی جائے۔ جیسا کہ فتح الباری میں ہے: ((شرب رجل من سقاه فانساب في بطنه جنان فنهى رسول الله ل ( ) ( فتح الباری شرح حديث: ٥٦٢٥، ٥٦٢٦) ایک شخص نے مشک سے منہ لگا کر پانی پیا اس کے پیٹ میں مشک سے ایک چھوٹا سانپ داخل ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس طرح پانی پینے سے منع فرمایا۔ ٦٤٢٠"}],[6420,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ اے علی تم نے فرمایا: ”حالت احرام والی عورت نقاب کرے، نہ دستانے پہنے اور نہ ہی برقع، پس اگر وہ احرام باندھنا چاہے جبکہ وہ حائضہ ہو تو وہ احرام باندھ لے، بیت اللہ کے طواف اور صفا و مروہ کے درمیان سعی کے علاوہ دیگر مواقف پر وقوف کرے۔‘اس حدیث کو عمر بن صبہان سے صرف عیسی بن یونس نے روایت کیا۔ اس میں موسی بن اعین کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/٢١٩)، مجمع البحرین (١٦٩٨)، اسناده ضعيف۔","f":"مذکورہ روایت ضعیف ہے، تاہم ترمذی شریف میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: احرام والی عورت نقاب اور دستانے استعمال نہ کرے۔ (ترمذی، کتاب الحج، باب ما جاء فيما لا يجوز للمحرم اور موطا امام مالک میں روایت ہے، فاطمہ بنت منذر بیان کرتی ہیں: کہ ہم حالت احرام میں اپنے چہرے ڈھانپا کرتی تھیں اور اسماء بنت ابی بکر صدیق یا اللہ بھی ہمارے ساتھ ہوتی تھیں۔ (موطا مالك: ١/ ٣٢٨) اور مستدرک حاکم میں بھی انہیں سے روایت ہے کہ ہم مردوں سے اپنے چہروں کا پردہ کرتی تھیں۔ (مستدرك حاکم: ١/ ٤٥٤) علاوہ ازیں سیدہ عائشہ بین النہا سے مروی ہے کہ محرم عورت نہ نقاب ڈالے اور نہ گھونگھٹ نکالے، البتہ سر کی طرف سے چہرے پر کپڑا لٹکائے، (سنن کبری بیهقی: ٢٧/٥) ان تمام موقوف روایات سے معلوم ہوا کہ آپ صلی اللہ علیہ وسلم نے خاص قسم کے نقاب سے منع کیا ہے نہ کہ بالکل ہی پردہ کرنے سے منع کیا ہے۔ اس لیے ہر خاتون کو چاہیے کہ وہ اس معاملے میں اپنے رب سے ڈرے اور فیشن ایبل اور ایسے نقابوں سے بچے جو بے حجابی کو فروغ دیتے ہوں۔"}],[6421,"سیدنا عبد اللہ ابن عباس ولی الجھا نے بیان کیا، اللہ عزوجل نے جو بھی نبی (عال السلام ) مبعوث فرمایا تو وہ جوان ہی تھے اور جس بھی عالم کو علم دیا گیا وہ جوان ہی تھا۔“ اس حدیث کو قابوس سے صرف جریر نے روایت کیا۔","",{"k":"مجمع الزوائد (١/٢٥)، تذكرة الموضوعات (١/١٣٦)، مجمع البحرين (٢١٨)، اسناده ضعيف۔"}],[6422,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، سیدنا جبریل علیہ سلام نبی صلی اللہ علیہ وسلم پر نازل ہوئے تو فرمایا: گواہ کے ساتھ حکم کے ذریعے فیصلہ فرمائیں، اور فرمایا: ”بدھ کا دن نحس مستمر کا دن ہے۔“ اس حدیث میں جعفر بن محمد سے ”نزل جبریل کے الفاظ صرف ابراہیم بن ابی حیہ نے روایت کیا اور یوم الاربعاء، یوم حس مستمر کے الفاظ سے جعفر سے صرف ابراہیم بن ابی حیہ روایت کرتے ہیں۔ مذکورہ روایت ضعیف ہے۔ تاہم روایت کا پہلا حصہ صحیح ہے۔:٦٤٢٣","",{"k":"وَلَا يَرْوِى: ((يَوْمُ الْأَرْبِعَاءِ يَوْمُ نَحْسٍ مُسْتَمِرٌ)) عَنْ جَعْفَرٍ إِلَّا إِبْرَاهِيمُ بْنُ أَبِي حَيَّةَ . مجمع الزوائد (٤/٢٠٢)، مجمع البحرين (٢١٦٨)، اسناده ضعيف۔"}],[6423,"سیدنا ابو قتادہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علے عین فرمایا کرتے تھے، لوگوں کو پلانے والا سب سے آخر میں پیسے۔ اس حدیث کو ایوب سے صرف حماد بن زید نے روایت کیا۔ اس میں قتیبہ بن سعید کا تفرد ہے۔ ٦٤٢٤","",{"k":"صحيح مسلم (٦٨١)، سنن ابن ماجه (٣٤٣٤)، سنن ترمذی، قم (١٨٩٤)۔"}],[6424,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی ملت علی ایم نے مسجد ذوالحلیفہ سے تلبیہ پکارا۔ اس حدیث کو محمد بن عجلان سے صرف مؤمل بن عبدالرحمن نے روایت کیا۔ اس میں عبدالغنی بن عبد العزیز کا تفرد ہے۔","",{"k":"صحیح بخاری، قائمة (١٧١٥)۔","f":"قانون مذکورہ حدیث سے معلوم ہوا کہ مسجد ذوالحلیفہ سے ہی رسول اللہ میم نے تلبیہ کا آغاز کیا۔ ٦٤٢٥"}],[6425,"سیدنا ابو ہریرہ فی اللہ نے بیان کیا، نبی سے تم نے فرمایا: ”چوپایہ زخمی کر دے تو اس پر کوئی دیت و تاوان نہیں، کنویں میں کوئی گر کر مر جائے تو اس پر کوئی تاوان نہیں۔ کان میں کوئی دب کر مر جائے۔ اس پر کوئی تاوان نہیں اور دینے میں خمس ہے۔ اس حدیث کو ابن عون سے صرف مؤمل بن عبد الرحمن نے روایت کیا۔ اس میں عبد الغنی بن عبد العزیز کا تفرد ہے۔ ٦٤٢٦","",{"k":"صحیح بخاری (٦٩١٣)، صحيح مسلم (١٧١٠)۔"}],[6426,"نافع نے بیان کیا، ایک آدمی سیدنا عبداللہ ابن عم رضی اللہ عنہ کے پاس آیا، اسے ابن جریج کہا جاتا تھا: اس نے کہا: ابو عبد الرحمن! میں نے آپ کو دیکھا ہے کہ آپ کچھ ایسے کام کرتے ہیں کہ میں نے کسی اور کو وہ کام کرتے نہیں دیکھا۔ انہوں نے کہا: ابن جریج! دوبارہ کہو، تم مجھ سے عجیب وغریب باتیں ہی کرتے ہو۔ انہوں نے کہا: میں نے آپ کو دیکھا ہے کہ آپ کی سواری جب آپ کو بالکل سیدھا لے کر کھڑی ہو جاتی ہے تو تب آپ تلبیہ پکارتے ہیں۔ میں نے آپ کو مونچھیں کترتے ہوئے دیکھا ہے، میں نے آپ کو دیکھا ہے کہ آپ زرد رنگ کا خضاب پسند کرتے ہیں، میں نے آپ کو بالوں کے بنے ہوئے جوتے پہنتے ہوئے دیکھا ہے۔ انہوں نے فرمایا: رہا میرا تلبیہ پکارنا جس وقت میری سواری مجھے لے کر کھڑی ہو جاتی ہے تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم تلبیہ نہیں پکارتے تھے حتی کہ آپ تعلیم کی سواری آپ صلی اللہ علیہ وسلم کو لے کر کھڑی ہو جاتی تھی، رہا میرا مونچھیں کترانا تو میں نے رسول اللہ نے ان کو مونچھیں کتراتے ہوئے دیکھا ہے۔ رہا زرد خضاب کرنا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ صلی اللہ علیہ وسلم زرد، پیلا خضاب پسند کرتے تھے اور رہا میرا بالوں والے جوتے پہنا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ صلی اللہ علیہ وسلم انہیں پسند کرتے تھے اور آپ ملے انہی میں وضو فرماتے تھے۔“ اس حدیث کو نافع سے صرف ابو امیہ نے روایت کیا۔ اس میں مؤمل بن عبد الرحمن کا تفرد ہے اور لوگوں کے ہاں: سعید المقبری کی عبید بن جریج کے حوالے سے مشہور ہے۔ صحیح بخاری، کتاب الوضوء، باب غسل الرجلين في النعلين الخ، رقم: ١٦٦، مسلم، كتاب الحج، باب بيان ان الافضل ان يحرم الخ:","",{"f":"مذکورہ حدیث سے معلوم ہوا کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما کا ہر کام سنت کے مطابق تھا اور ہر مسلمان کو ایسا ہی کرنا چاہیے کہ اس کا ہر کام سنت نبوی کے مطابق ہو۔\n(١) جب سواری سیدھی کھڑی ہو جائے تو تلبیہ کہنا ایسا نبی اکرم صلی اللہ علیہ وسلم نے ذوالحلیفہ میں کیا، دیکھئے (بخاری، کتاب الحج، رقم: ١٥٤٦)\n(٢) معلوم ہوا کہ مونچھوں کے بال کتروانا سنت ہے، بخاری شریف میں ہے کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما مونچھ کترتے تھے کہ کھال کی سپیدی دکھلائی دیتی۔ (بخاری، کتاب اللباس، باب قص الشارب)\n(٣) معلوم ہوا کہ زرد رنگ سے بال رنگنا مستحب ہے۔\n(٤) سبتی جوتے نبی مکرم ملاے علی تم پہنتے تھے۔ ٦٤٢٧"}],[6427,"ام ضراب نے بیان کیا، میرے والد فوت ہوئے، انہوں نے مجھے اور میرے بھائی کو چھوڑا اور انہوں نے ہمارے لیے کوئی مال نہ چھوڑا، بس میرے چچا مدینہ سے آئے، وہ ہمیں سیدہ عائشہ من الشیا کے پاس لے گئے۔ پس انہوں نے مجھے اپنی گود میں بٹھا لیا کیونکہ میں بچی تھی اور لڑکے کو نہ بٹھایا، میرے چچانے اپنے کام، ضرورت کی ان سے شکایت کی تو انہوں نے ہمارے لیے بہت زیادہ دودھ دینے والی دو اونٹنیوں کا حکم دیا، پھر انہوں نے فرمایا: ”میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”قیامت قائم نہ ہوگی حتی کہ اولا د غصہ کا باعث بن جائے گی، بارش گرمی کا باعث ہوگی، بخیل بدذات لوگ عام ہو جائیں گے، جبکہ سخی معزز شخص کم ہو جائیں گے، چھوٹا بڑے کے خلاف اور بد ذات معزز شخص کے خلاف جسارت کرے گا۔“ حدیث سیدہ عائشہ بولی لوبیا سے صرف اس اسناد سے مروی ہے۔ اس میں مؤمل بن عبد الرحمن کا تفرد ہے۔","",{"k":"مجمع الزوائد: ٣٢٥/٧ مجمع البحرين (٤٤٨٠)، اسناده ضعيف۔"}],[6428,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” آدمی اپنی عمر کا ایک حصہ جنتیوں والے عمل کرتا رہتا ہے، پس جب اس کی موت سے پہلے کا وقت ہوتا ہے تو وہ بدل جاتا ہے اور جہنمیوں والے عمل کرتا ہے، پس وہ فوت ہو جاتا ہے اور جہنم میں داخل ہو جاتا ہے اور آدمی اپنی عمر کا ایک حصہ BY جہنمیوں والے عمل کرتا رہتا ہے پس جب وہ اپنی موت سے پہلے ہوتا ہے تو بدل جاتا ہے اور جنتیوں والے عمل کرتا ہے تو وہ جنت میں داخل ہو جاتا ہے۔“ ٦٤٢٩","",{"k":"مجمع الزوائد (٢١١٧)، صحيح۔"}],[6429,"سیدنا انس خلیل اللہ سے روایت ہے کہ ابو عمیر ان کا بھائی تھا، اس کا ایک پرندہ تھا، پس وہ مر گیا، نبی اے علی تم ہمارے ہاں تشریف لائے تو فرمایا: ”ابو عمیر کو کیا ہوا؟ انہوں نے عرض کیا: اس کا وہ پرندہ مر گیا ہے۔ پس آپ صلی اللہ علیہ وسلم مزاح کے طور پر اسے فرمانے لگے: ” ابو عمیر تمہارے (نغیر ) پرندے کو کیا ہوا؟ ابو عمیر تمہارے (غیر ) پرندے کو کیا ہوا؟ ان دونوں حدیثوں کو مؤمل بن عبد الرحمن سے صرف عبد الغنی بن عبد العزیز نے روایت کیا۔","",{"k":"صحیح بخاری (٦٢٠٣)، صحیح مسلم کتاب الاداب (٢١٥٠)۔"}],[6430,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ عمل علم سے اپنے مال کے بارے میں مشورہ طلب کیا جو کہ مجمع میں تھا یہ کہ وہ اسے صدقہ کر دیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تم اس کی پیداوار صدقہ کر دو اور اس کی اصل باقی رکھو، اسے بیع کیا جائے نہ میراث بنائی جائے۔ اس حدیث کو عبدالعزیز بن المطلب سے صرف ابراہیم بن سعد نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"صحيح بخاری، كيف يكتب (٢٧٧٢)، صحیح مسلم (١٦٣٢)۔","f":"سیدنا عمر ا ن کو خیبر میں زمین ملی تھی، جس کا نام مغ تھا۔ معلوم ہوا کہ کوئی بھی چیز اس طرح وقف کرنا کہ اس کی پیداوار اور منافع اللہ کی راہ میں صرف ہوتا رہے، مستحب و باعث اجر وفضیلت ہے۔ یہ بھی معلوم ہوا کہ وقف شدہ املاک کو نہ فروخت کیا جا سکتا ہے اور نہ ہی بطور وراثت تقسیم کیا جا سکتا ہے اور نہ ہی انہیں ہبہ کیا جا سکتا ہے۔ / ٠ / ٦٤٣١"}],[6431,"سیدنا عبداللہ ابن عمر با اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” ابلیس عراق میں داخل ہوا تو اس نے اپنی ضرورت پوری کی، شام میں داخل ہوا تو انہوں نے اسے پیچھے دھکیل دیا حتی کہ وہ بیسان تک پہنچ گیا اور مصر میں داخل ہوا وہاں اس نے انڈے اور بچے دیے اور اس کے سرکردہ چیلے خوب ہوئے۔“ اس حدیث کو زہری سے صرف عقیل نے اور عقیل سے صرف ابن لہیعہ اور یحیی بن ایوب نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔ ناد علامہ بیشمی رحمہ اللہ فرماتے ہیں: کہ اس کے راوی جو یعقوب بن عبد اللہ بن عتبہ، کا سیدنا","",{"k":"مجمع الزوائد (١٠/٦٠)، مجمع البحرين (٤٠٠٠)۔","f":"عبد اللہ بن عمر رضی اللہ عنہما سے سماع ثابت نہیں ہے۔"}],[6432,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قریب ہے کہ مسلمان مدینہ میں محصور کر دیے جائیں، حتی کہ ان کا دور ترین مورچہ سلاح کے مقام پر ہو گا۔“ اس حدیث کو عبید اللہ بن عمر سے صرف جریر بن حازم نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔ نان قیامت کے قریب ایسا ہو گا، اسلام اطراف عالم سے سمٹ سمٹا کر مدینہ میں محصور ہو جائے گا۔ جیسا کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (قیامت کے قریب ) ایمان مدینہ میں اس طرح سمٹ آئے گا جیسے سانپ سمٹ کر اپنے بل میں آجایا کرتا ہے۔ (بخاری، کتاب فضائل المدينه، رقم: ١٨٧٦) سلاح مقام، خیبر کے قریب ہے۔ دیکھئے (سنن ابی داؤد، رقم: ٤٣٠٠) ٦٤٣٣","",{"k":"سنن ابو داود، ودلائلها، رقم: ٥٠ (٤٢٥٠)، قال الشيخ الالباني: صحيح۔"}],[6433,"سیدہ عائشہ بیل للہا نے فرمایا: ”میں اور سیدہ حفصہ بنی ہوا نے نفلی روزے کی حالت میں صبح کی، پس ہمیں ہدیہ پیش کیا گیا، ہمیں اس کی بہت خواہش ہوئی تو ہم نے اسے کھا لیا۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے سیدہ عائشہ نیا الجھا نے فرمایا: ” سیدہ حفصہ بنا لوہا مجھ پر سبقت لے گئیں وہ اپنے باپ کی بیٹی تھیں۔ پس انہوں نے رسول اللہ مت تعلیم سے مسئلہ دریافت کیا تو آپ نے فرمایا: ” تم پر اور کچھ نہیں، پس تم اس کی جگہ ایک دن روزہ رکھ لو۔ اس حدیث کو یحیی بن سعید سے صرف جریر بن حازم نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"١٠/٠ تقدم تخريجه (٦٣٢١)۔"}],[6434,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ اور اس کے فرشتے سحری کھانے والوں پر رحمتیں بھیجتے ہیں۔ اس حدیث کو نافع سے صرف عبد اللہ بن سلیمان نے اور عبد اللہ بن سلیمان سے صرف عبد اللہ بن عیاش نے روایت کیا۔ اس میں ادریس بن بیٹی کا تفرد ہے، اور سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے۔ ایک دوسری حدیث میں ہے کہ سحری کا کھانا تناول کرنا بابرکت ہے اس کو چھوڑنا نہیں خواہ تم میں سے کوئی پانی کا صرف ایک گھونٹ ہی پی لے۔ کیونکہ یقیناً اللہ ذوالجلال اور اس کے فرشتے سحری تناول کرنے والوں پر رحمت بھیجتے ہیں۔ (ترغیب و ترہیب: ١٣٩/٣) علامہ منذری جاللہ نے اس حدیث کی اسناد کو قوی قرار دیا ہے۔ معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کو اس بات کی شدید خواہش تھی کہ امت کے لوگ سحری تناول کر کے اللہ ذوالجلال اور فرشتوں کی صلوٰۃ سے فیض یاب ہو جائیں، اس لیے تو مسلمانوں کو اس بات کی ترغیب دی کہ اگر وہ کچھ تناول نہ کر پائیں تو کم از کم پانی کا ایک گھونٹ پی کر سحری تناول کرنے والوں میں شامل ہو جائیں۔ شیخ عبد الرحمن البناء اللہ فرماتے ہیں: کہ اللہ ذوالجلال کی صلوٰۃ یہ ہے کہ وہ ان (سحری تناول کرنے والوں ) پر رحمت نازل فرماتا ہے اور فرشتوں کی صلوٰۃ یہ ہے کہ وہ ان کے لیے استغفار کرتے ہیں۔ اور سحری نہ کھانے والا اس وقت رحمت الہی اور فرشتوں کے استغفار سے محروم رہا۔","",{"k":"مجمع البحرين (١٥٠٦)، صحیح ترغیب و ترهيب (١٠٦٦)، ابن حبان (٣٤٦٧)، سلسله صحيحه، رقم: ١٦٥٤ اسناده حسن۔"}],[6435,"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا نے سیدہ خدیجہ بنی انہما نے بیان کیا، انہوں نے کہا: میں نے عرض کیا: اللہ کے رسول! میرے چچا کے بیٹے! کیا آپ اس طرح کر سکتے ہیں کہ جب وہ آپ مطلیے علیکم کے پاس آئے جو آپ کے پاس آتا ہے تو آپ اس کے متعلق مجھے بتائیں؟ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: خدیجہ! ہاں۔ سیدہ خدیجہ بنی اشیا نے فرمایا: ”ایک دن سیدنا جبریل علی سلام آپ صلی اللہ علیہ وسلم کے پاس آئے جبکہ میں آپ ملنے یام کے ہاں موجود تھی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” خدیجہ! یہ وہ میرے ساتھی ہیں جو میرے پاس آتے ہیں وہ آچکے ہیں۔ پس میں نے انہیں کہا: اٹھو اور میری دائیں ران پر بیٹھ جاؤ۔ پس وہ اٹھے اور میری دا ئیں ران پر بیٹھ گئے۔ میں نے انہیں کہا: کیا آپ اسے دیکھ رہے ہیں؟ انہوں نے کہا: ”ہاں۔“ میں نے انہیں کہا: اٹھ کر میری بائیں ران پر بیٹھ جائیں۔ پس وہ بیٹھ گئے۔ میں نے کہا: کیا آپ اسے دیکھ رہے ہیں؟ انہوں نے کہا: جی ہاں۔ میں نے انہیں کہا: اٹھیں اور میری گود میں بیٹھ جائیں، پس وہ بیٹھ گئے، انہوں نے انہیں کہا: کیا آپ انہیں دیکھ رہے ہیں؟ انہوں نے کہا: ”ہاں۔ خدیجہ بنی اٹھا نے فرمایا: پس میں نے چہرے سے کپڑا اتار دیا اور اوڑھنی پھینک دی، اور میں نے انہیں کہا: کیا آپ اسے دیکھ رہے ہیں؟ آپ نے فرمایا: ”نہیں۔“ میں نے آپ سے کہا: اللہ کی قسم! یہ معزز فرشتہ ہے، اللہ کی قسم! یہ کوئی شیطان نہیں، سیدہ خدیجہ ولی نیہا نے بیان کیا، میں نے ورقہ بن نوفل بن اسد بن عبد العزی بن قصی سے یہ واقعہ بیان کیا جس طرح اس کے متعلق محمد رسول اللہ صلی اللہ علیہ وسلم نے مجھے بتایا تھا تو ورقہ نے کہا: خدیجہ! تمہاری بات کچی اور درست ہے۔“ اس حدیث کو عمر بن عبد العزیز سے صرف اسماعیل بن ابوحکیم نے اور اسماعیل سے صرف حارث بن محمد الغبر ی نے روایت کیا۔ اس میں بیٹی بن سلیمان کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٥٦/٨)، مجمع البحرين (٣٤٩٧)، اسناده حسن۔","f":"(١) سیدہ خدیحہ نل لنا انتہائی غمگسار اور مشفق و مہربان تھیں۔\n(٢) سیدہ خدیجہ بنی اٹھا ہے انتہا فہم وفراست کی مالکہ تھیں۔\n(٣) نبی عالینام کو آپ منی اشیا سے گہرا تعلق تھا۔ ٦٤٣٦"}],[6436,"سیدہ ام سلمہ والی و با بیان کرتی ہیں۔ رسول اللہ صلی اللہ علیہ وسلم ن کی ایک چٹائی اور جائے نماز تھی جس پر آپ ملنے یا نماز پڑھا کرتے تھے۔ یہ حدیث سعید بن المسیب سے صرف اس اسناد سے مروی ہے۔ اس میں الحسن بن داود المنکدری کا تفرد ہے۔ ان حصیر بوریا کو کہتے ہیں اور خمرہ چھوٹے مصلے کو کہتے ہیں۔ معلوم ہوا کہ پیشانی کا براہ راست زمین پر یا مٹی پر نکا نا ضروری نہیں اور ان لوگوں کا رد ہوتا ہے جو کہتے ہیں کہ سجدہ کے لیے زمین کی مٹی شرط ہے۔","",{"k":"مجمع الزوائد (٥٧/٢)، مجمع البحرين (٧٠٧)۔"}],[6437,"سیدنا عمرو بن عوف المزنی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب مسواک نہ ہو تو مسواک کی جگہ انگلیاں کام دیتی ہیں۔“ اس حدیث کو کثیر بن عبد اللہ المزنی سے صرف ابوغزیہ نے روایت کیا۔ اس میں ہارون الفروی کا تفرد ہے۔ ور- ٦٤٣٨","",{"k":"مجمع الزوائد (٢/١٠٠)، سلسله ضعیفه (٢٤٧١)، ضعيف الجامع الصغير (٢٢٨٤)، مجمع البحرين (٧٨٥)، اسناده ضعيف۔"}],[6438,"مجاہد اللہ نے بیان کیا، ہم ایک حلقے میں بیٹھے ہوئے تھے، اس میں سیدنا عبد اللہ بن عمر رضی اللہ عنہما اور عبید بن عمیر بھی تھے۔ پس ایک آدمی ہمارے پاس آیا تو وہ ہمارے پاس کھڑا ہو گیا اور کہا: فلاں کی دعوت قبول کرو، فلاں کی دعوت قبول کرو، لوگوں نے اسے انتہائی ناپسند کیا۔ سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے اپنا سر جھکا لیا اور عبید بن عمیر نے اپنا سر اٹھا لیا اور کہا: ہمارے بھیجے ہمیں معاف کرو، ہمیں معاف کرو، پس،سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے اپنا سر اٹھایا اور فرمایا: ”ہمیں یہاں سے کھڑا کرو یہاں کوئی عافیت نہیں۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جسے دعوت دی جائے اور وہ قبول نہ کرے تو اس نے اللہ اور اس کے رسول کی نافرنی کی۔“ اس حدیث کو ابن عون سے صرف ابن المبارک نے روایت کیا۔ اس میں الحسین بن الحسن مروزی کا تفرد ہے۔","",{"k":"سنن ابو داود (٣٧٤١)، ضعيف الجامع الصغير (٥٥٧٩)، قال الشيخ الالباني: ضعيف۔"}],[6439,"رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام سیدنا ثوبان رضی اللہ عنہ نے بیان کیا، رسول اللہ سلم نے فرمایا: ”جب تم میں سے کوئی وتر پڑھے تو وہ (بعد میں ) دورکعتیں پڑھے، اگر وہ (رات کو ) اٹھ جائے تو مزید نماز پڑھ لے ورنہ وہ دونوں اس کے لیے کافی ہیں۔“ یہ حدیث سیدنا ثوبان رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"مجمع الزوائد: ٢/ ٢٤٦ سلسله صحیحه (١٩٩٣)، سنن دارمی (١٥٩٤)، مجمع البحرين (١١٠٦)۔","f":".. حدیث کا مطلب یہ ہے کہ جو آدمی وتر کے بعد دو رکعت نماز پڑھ لے اور بعد ازاں پچھلی رات اٹھ بیٹھا اور نماز پڑھی تو وہ سب سے افضل ہے اور اگر نہ اٹھ سکا اور تہجد کی نماز نہ پڑھ سکا تو وہ دورکعت اس کو تہجد کے ثواب سے کفایت کر لیں گی اور غالباً یہ سفر کی حالت میں ہے۔ کیونکہ نبی مکرم ما علیم نے یہ حدیث سفر کی حالت میں فرمائی تھی جیسا کہ مسند بزار میں ہے کہ ہم آنحضرت ملے تعلیم کے ساتھ سفر میں تھے تو آپ نے فرمایا کہ رات کا جا گنا بڑی محنت اور مشقت کا کام ہے۔ (شرح مشكاة مولنا اسماعیل سلفی: ١/ ٨٠٠)"}],[6440,"سیده فاطمه بنت رسول اللہ صلی اللہ علیہ وسلم نے اپنے والد رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”جمعہ میں ایک گھڑی ہے، بندہ مسلمان اس میں اللہ سے جو خیر طلب کرتا ہے اللہ اسے وہی عطا کر دیتا ہے۔“ یہ حدیث فاطمہ بنایا نہا سے صرف اس اسناد سے مروی ہے، اس میں المحار بی کا تفرد ہے۔ صحیح مسلم میں ہے کہ وہ گھڑی امام کے منبر پر بیٹھنے سے لے کر نماز پوری ہونے تک (کے درمیانی وقت میں ) ہے۔ (مسلم، کتاب الجمعة، رقم: ٨٥٣) سنن ابی داود میں ہے کہ وہ گھڑی نماز عصر اور غروب آفتاب کے درمیان وقت میں ہے۔ (ابو داؤد، رقم: ١٠٤٨) معلوم ہوا کہ فضائل جمعہ میں سے یہ ہے کہ اس میں ایک ایسی گھڑی ہے جس میں ہر (جائز) دعا کرنے والے کی دعا قبول کی جاتی ہے، یہ گھڑی کون سی ہے، اس کی تعیین میں اختلاف ہے، زیادہ ظاہر دو قول ہیں، جن کا بیان مذکورہ بالا دو احادیث میں ہوا ہے ان کے علاوہ بعض روایات میں اسے دن کی آخری گھڑی کہا گیا ہے۔ (مسلم، کتاب الجمعة، رقم: ٨٦٢) اور بعض میں اسے عصر کے بعد آخری گھڑی میں تلاش کرنے کا حکم دیا گیا ہے۔ (ابو داؤد، رقم: ٩٢٦) اس میں زیادہ مناسب قول یہ معلوم ہوتا ہے کہ اس گھڑی کو نماز جمعہ سے لے کر دن کے آخر تک تلاش کیا جائے اور اس دوران کثرت سے دعا کی کوشش کی جائے، جیسا کہ شیخ ابن جبرین اللہ نے اسی طرف اشارہ فرمایا ہے۔ (فتاویٰ اسلامیه: ١ / ٤٠٠) یہاں ایک اشکال موجود ہے اور وہ یہ کہ اس تمام وقت میں انسان نماز ادا نہیں کر سکتا۔ جبکہ مذکورہ بالا حدیث میں نماز پڑھتے ہوئے دعا کرنے کا ذکر ہے تو اس کا حل یہ بیان کیا گیا ہے کہ نماز کا انتظار بھی تو نماز ہی شمار ہوتا ہے۔","",{"k":"مجمع الزوائد (١٦٦/٢)، سنن ابو داود (١٠٤٨)، صحیح مسلم (٨٥٢)، مجمع البحرين (٩٤٩)۔"}],[6441,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، ہم سیدنا علی بن ابی طالب رضی اللہ عنہ اور سیدہ فاطمہ بنت رسول اللہ ملنے کی یمن کی شادی میں شریک ہوئے، ہم نے کوئی شادی نہیں دیکھی جس میں اس سے بہتر حیس ( کھجور اور گھی ملا کر تیار کیا گیا کھانا ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمارے لیے گھی ( زیتون ) اور کھجور کا کھانا تیار کیا۔ پس ہم نے کھایا، اور شادی کی رات ان دونوں کا بچھونا بھیڑ کی کھال کا تھا۔“ اس حدیث کو جعفر بن محمد سے صرف مسلم بن خالد الزنجی اور عبد اللہ بن میمون القداح نے روایت کیا۔ اس میں مسلم بن خالد سے میمون بن کلیب کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ اس میں مسلم بن خالد زنجی ضعیف ہے۔ ٦٤٤٢","",{"k":"مجمع الزوائد (٥٠/٤)، ضعیف ترغیب و ترهیب (١٢٧٢، ١٩٢٣)، اسناده ضعيف۔"}],[6442,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اللہ کا ایک فرشتہ ہے، اگر اسے کہا جائے: ساتوں آسمانوں اور ساتوں زمینوں کا ایک لقمہ بنائے تو وہ بنا لے، اس کی تسبیح پاک ہے تو جہاں بھی ہو۔ “ اس حدیث کو از واعی سے صرف بشر بن بکر نے روایت کیا۔ اس میں وہب اللہ بن رزق کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/٧٠)، سلسله ضعیفه (٣١٩٩)، مجمع البحرين، رقم: ٩٨٠)۔"}],[6443,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علی یتیم کا معمول تھا کہ جب سورج ڈھل جاتا تو آپ ملے جمعہ پڑھتے تھے۔ ہم واپس جاتے تو ہم سایہ نہیں پاتے تھے کہ ہم اس سے سایہ حاصل کرتے۔ اس حدیث کو سفیان بن بلال سے صرف بیٹی بن سلیمان نے روایت کیا۔: ٦٤٤٤","",{"k":"مجمع الزوائد (٢/١٨٣)، اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نبی مکرم مالے علم کا جمعہ زوال کے فوراً بعد ہوتا تھا۔ چونکہ خطبہ مختصر اور نماز قدرے لمبی ہوتی تھی، اس لیے صحابہ کرام بھی اہم واپسی پر دیواروں کا اتنا سایہ نہ پاتے تھے کہ اس سے سایہ حاصل کر سکتے، جیسا کہ صحیح مسلم میں ہے کہ ((وما نجد فينا نستظل به)) (مسلم، رقم: ٨٦٠) یعنی سایہ تو ہوتا تھا مگر بہت کم"}],[6444,"سیدنا زبیر بن العوام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ نے تم کو فرماتے ہوئے سنا: ” میرے گھر اور میرے منبر کے درمیان جو جگہ ہے وہ جنت کے باغوں میں سے ایک باغ ہے اور میرا منبر میرے حوض پر ہے۔“ اس حدیث کو موسی بن عقبہ سے صرف ابو غزیہ نے روایت کیا۔ اس میں ہارون الفروی کا تفرد ہے۔ اور ابن ابی ہند جس سے موسی بن عقبہ نے روایت کیا۔ وہ سعید بن ابی ہندا بو عبد اللہ ہیں۔ ٢:٦٤٤٥","",{"k":"عنه مجمع الزوائد (٩/٤)، مجمع البحرين (١٨٢٥)۔"}],[6445,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب تک چاہتے ذوالحلیفہ میں قیام کرتے تھے۔ پس جب آپ ملنے لیے یکم ارادہ فرماتے کہ احرام باندھیں تو آپ ملنے لیے تم مسجد میں نماز پڑھتے، پھر جس وقت آپ صلی اللہ علیہ وسلم کی سواری آپ صلی اللہ علیہ وسلم کو سیدھا لے کر کھڑی ہو جاتی تو آپ ملے تلبیہ پکارتے تھے۔ اس حدیث کو اوزاعی سے صرف بشر بن بکر نے روایت کیا۔ اس میں احمد بن سعید الہمدانی کا تفرد ہے۔ مدینہ والوں کا میقات ذوالحلیفہ ہے، اس کا نیا نام آبار علی ہے۔ یہ مدینہ منورہ کے قریب ہے اور مکہ معظمہ سے تقریباً ٤٥٠ کلومیٹر کے فاصلے پر ہے، ذوالحلیفہ میں جو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی، اس سے مراد نماز ظہر کی دو رکعت (نماز قصر) ہے، جیسا کہ (صحیح مسلم، کتاب الحج، رقم: ١٢٤٣) میں صراحت ہے۔ تاہم احرام باندھنے کے لیے دو نفل ادا کرنا سنت سے ثابت نہیں ہے۔","",{"k":"صحیح بخاری (١٥٤١)، صحیح مسلم، رقم: ١١٨٨ . فائدة۔"}],[6446,"سیدنا زید بن ثابت رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس چیز کی کثیر مقدار نشہ آور ہو تو اس کی قلیل مقدار بھی حرام ہے۔ یہ حدیث سیدنا زید بن ثابت بنی اہلیہ سے صرف اس اسناد سے مروی ہے۔ اس میں بیچی بن سلیمان بن نضلہ کا تفرد ہے۔","",{"k":"١。 مجمع الزوائد (٥٧/٥)۔"}],[6447,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ میم نے فرمایا: سورۃ الانعام نازل ہوئی جبکہ اس کے ساتھ دونوں کنارے بھرنے کے برابر فرشتے تھے، وہ بلند آواز سے تسبیح و تقدیس کر رہے تھے، جبکہ زمین کانپ رہی تھی، اور رسول اللہ نے عدیم سبحان اللہ العظیم، سبحان اللہ العظیم“ پڑھ رہے تھے۔“ اس حدیث کو ابو سہیل نافع بن مالک سے صرف عمر بن طلحہ نے اور عمر بن طلحہ سے صرف ابن ابی فدیک نے روایت کیا۔ اس میں احمد بن محمد السالمی کا تفرد ہے۔:٦٤٤٨ مذکورہ حدیث سے سورہ انعام کی اہمیت واضح ہوئی۔",""],[6448,"سیدنا اسعد بن زرارہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلیم کو دیکھا، ISES IS آپ صلی اللہ علیہ وسلم نے لوگوں کو خطاب فرمایا، آپ صلی اللہ علیہ وسلم نے انتہائی توجہ سے دیکھا تو سیدنا ابو بکر یا اللہ کو نہ دیکھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر، ابو بکر، بے شک روح القدس جبریل علیسلام نے ابھی ابھی مجھے بتایا کہ آپ صلی اللہ علیہ وسلم کی امت میں سے آپ تعلیم کے بعد سب سے بہتر سیدنا ابو بکر الصدیق رضی یہ ہیں۔“ یہ حدیث اسعد بن زرارہ سے صرف اس اسناد سے مروی ہے۔ اس میں ہارون الفروی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٤٤/٩)، البحرين (٣٦١٠)، اسناده ضعيف . مجمع۔"}],[6449,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کے ہاں سب سے افضل نماز نماز مغرب ہے اور جو شخص اس کے بعد دو رکعتیں پڑھتا ہے اللہ اس کے لیے جنت میں ایک گھر بنا دیتا ہے، وہ اس میں صبح و شام سیر کرتا ہے۔“ اس حدیث کو ہشام بن عروہ سے صرف عبد اللہ بن محمد بن یحیی بن عروہ نے روایت کیا۔ ٤٥٠","",{"k":"سلسله ضعیفه (٢٨٤١)۔"}],[6450,"سیدنا علی ضیا اللہ نے بیان کیا، رسول اللہ ملنے سلیم نے فرمایا: ”تین چیزیں وہ حق ہیں، جس کا اسلام میں کوئی حصہ ہے اللہ اس کو اس شخص کی طرح نہیں بنائے گا، جس کا اسلام میں کوئی حصہ نہیں، جو بندہ اللہ کو دوست بناتا ہے تو وہ اسے کسی اور کے سپرد نہیں کرتا اور جو شخص جس قوم سے محبت کرتا ہے اس کا حشر اس کے ساتھ ہو گا۔“ اس حدیث کو ابن عیینہ سے صرف محمد بن میمون نے روایت کیا اور اسماعیل بن ابی خالد سے صرف ابن عیینہ نے روایت کیا۔","",{"k":"مجمع الزوائد (١٠/٢٨٠)، صحیح ترغیب و ترهیب (٣٠٣٧)، مجمع البحرين (٤٩٨٣)۔"}],[6451,"سیدہ عائشہ بنی النیہا نے بیان کیا، ایک دن رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو آپ نے روٹی کا ٹکڑا گرا ہوا دیکھا تو آپ اس کی طرف چل کر گئے اور اسے پکڑ لیا، پھر اسے صاف کر کے کھالیا، پھر فرمایا: \"عائشہ! اللہ کی نعمتوں کی قدر کر، کیونکہ جب وہ کسی گھرانے سے چلی جاتی ہیں تو پھر وہ ان کے پاس واپس نہیں آتیں۔“ اس حدیث کو ہشام بن عروہ سے صرف عبد اللہ بن مصعب اور القاسم بن غصن نے روایت کیا۔ اس میں عبد اللہ بن مصعب بن یحیی بن سلیمان کا تفرد ہے اور القاسم بن غصن سے آدم بن ابی ایاس کا تفرد ہے۔","",{"k":"سنن ابن ماجه (٣٣٥٣)، قال الشيخ الالباني: ضعيف۔"}],[6452,"سیدنا نوفل بن معاویہ الدیلی یا اللہ بیان کرتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو تین سانسوں میں پیتے ہوئے دیکھا، آپ پہلے پر بسم اللہ پڑھتے اور آخری پر الحمد للہ کہتے تھے۔“ یہ حدیث سیدنا","",{"k":"کر مجمع الزوائد: ٥/ ٨١ مجمع البحرين (٤١٤٠)، اسناده ضعيف۔","f":"نوفل بن معاویہ بنی لینے سے صرف اس اسناد سے مروی ہے۔ اس میں الحسن بن داود المنکد ری کا تفرد ہے۔ مانده مذکورہ حدیث ضعیف ہے تاہم انسان کو سانس لے کر پانی پینا چاہیے اور برتن کو منہ سے الگ کر کے سانس لینا چاہیے، برتن میں سانس لینا درست نہیں ہے، جیسا کہ صحیح بخاری میں ہے کہ سیدنا ابو قتادہ فی الیہ سے روایت ہے کہ نبی مکرم ملے علیم نے اس بات سے منع فرما دیا ہے کہ برتن میں سانس لیا جائے۔:٦٤٥٣ (بخاری، كتاب الاشربة: ٥٦٣٠)"}],[6453,"سیدنا ابوبکر الصدیق رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی عالم کو فرماتے ہوئے سنا: ”اے اللہ! عمر بن خطاب کے ذریعے اسلام کو تقویت پہنچا۔“ یہ حدیث سیدنا ابو بکر بنی لینے سے صرف اس اسناد سے مروی ہے۔ اس میں الزبیر بن عباد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩/٦٥)، اسناده ضعیف، مجمع البحرين (٣٦٥٥)۔","f":"مذکورہ روایت ضعیف ہے۔ تاہم دوسری روایات سے ثابت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! ان دو بندوں ابو جہل اور عمر بن خطاب میں سے جو تجھے زیادہ محبوب ہے اس کے ذریعے اسلام کو قوت و عزت عطا فرما دے۔ (ترمذی، کتاب المناقب: ٣٦٨١، مسند احمد: ٢/ ٩٥، اسناده حسن لذاته) ایک دوسری روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! عمر بن خطاب کے ذریعے اسلام کو خصوصی عزت بخش دے۔ (مستدرك حاكم: ٣/ ٨٣- اسناده حسن لذاتہ) صحیح بخاری میں ہے کہ سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے کہا: کہ سیدنا عمر ضیا اللہ کے اسلام لانے کے بعد پھر ہمیں ہمیشہ عزت حاصل رہی۔:٦٤٥٤ (بخاری، کتاب المناقب، رقم: ٣٦٨٤)"}],[6454,"سیدہ عائشہ منی الجھا نے بیان کیا، رسول اللہ سلیم ہر سال اپنے آپ کو عرب کے قبائل پر پیش کیا کرتے تھے، کہ وہ آپ کو اپنی قوم کے پاس پناہ دیں حتی کہ آپ صلی اللہ علیہ وسلم اللہ کا کلام اور اپنی رسالت پہنچائیں اور ان کے لیے جنت ہوگی، پس عرب کے کسی قبیلے نے آپ ملنے کلام کی دعوت قبول نہ کی تھی کہ اللہ نے اپنے دین کے غلبے، اپنے نبی کی نصرت اور اپنے وعدے کی تنفیذ کا ارادہ فرمایا تو اللہ نے انہیں انصار کے قبیلے کی طرف بھیج دیا، پس انہوں نے آپ صلی اللہ علیہ وسلم کی دعوت قبول کی اور اللہ نے اپنے نبی صلی اللہ علیہ وسلم کے لیے اس کی ہجرت کا گھر بنا دیا۔ اس حدیث کو عبد الرحمن بن القاسم سے صرف سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے اور سیدنا عبد اللہ بن عمر ضی اللہ سے صرف اسحاق الفروی نے روایت کیا۔ اس میں ہارون الفروی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٤٢/٦)، مجمع البحرين (٢٧٤٢)، اسناده ضعيف۔"}],[6455,"سیدنا عبداللہ بن عروہ بن زبیر رضی اللہ عنہ نے بیان کیا، میں نے سیدنا عبد اللہ بن زبیر رضی اللہ عنہما کو سنا، جبکہ ہم ان کے ساتھ عمرہ کے لیے روانہ ہوئے تھے، جب ہم ٹیلے سے وادی میں اترے تو سیدنا عبداللہ ابن الزبیر بھی اللہ نے غسل کیا اور دو رکعتیں پڑھیں، ہم نے بھی ان کے ساتھ منسل کیا اور ان کے ساتھ دو رکعتیں پڑھیں، پھر انہوں نے تلبیہ پکارا، میں حاضر ہوں، اے اللہ! میں حاضر ہوں،، میں حاضر ہوں تیرا کوئی شریک نہیں میں حاضر ہوں، بے شک تمام حمد اور ساری نعمتیں تیرے ہی لیے ہیں اور بادشاہت، تیرا کوئی شریک نہیں۔ عبداللہ بن عروہ نے بیان کیا: میں نے عبداللہ ابن الزبیر فضل اللہ کو بیان کرتے ہوئے سنا: ”اللہ کی قسم! یہ رسول اللہ علیم کا تلبیہ ہے، رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح کیا، آپ نے نماز کے بعد احرام باندھا۔“ یہ حدیث سیدنا عبد اللہ ابن الزبیر ولی ال لینے سے صرف اس اسناد سے مروی ہے۔ اس میں بیٹی بن سلیمان ابن نضلہ کا تفرد ہے۔ علامہ بیشمی رحمہ اللہ فرماتے ہیں کہ اس کا راوی محمد بن عبد اللہ بن عرس: لم اجدہ۔ تاہم تلبیہ کے مذکورہ بالا الفاظ دوسری صحیح احادیث سے ثابت ہیں۔ دیکھئے حدیث وفوائد نمبر اور پیچھے احادیث گزر چکی ہیں کہ نبی معظم ملت علی ایم نے ذوالحلیفہ کے مقام پر دو رکعت نماز پڑھ کر احرام باندھا اور تلبیہ پکارا۔","",{"k":"مجمع الزوائد (٢٢٢٣)، مجمع البحرين (١٧٠١)۔"}],[6456,"سیدنا ابو ہریرہ ریلی لینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اپنے پڑوسی کے گھر میں جھانکتا ہے اور اپنے مسلمان بھائی کے ستر کو یا عورت کے بال یا اس کے جسم کے کسی حصے کو دیکھتا ہے تو اللہ پر حق ہے کہ وہ اسے جہنم میں داخل کرے۔“ یہ حدیث عمر بن عبد العزیز سے صرف اس اسناد سے مروی ہے۔ اس میں محمد بن عمر و بن سلمہ المرادی کا تفرد ہے۔ ٦٤٥٧","",{"k":"مجمع الزوائد: ٨/ ٠ الله مجمع البحرين (٢٨٩٦)، اسناده ضعيف۔"}],[6457,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم غزوہ خیبر کے دن تشریف لائے تو آپ ملنے کام سے عرض کیا گیا، اللہ کے رسول! گدھے ختم ہو گئے، پس رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابو طلحہ ضیا ال نینی کو حکم فرمایا تو انہوں نے اعلان کیا: اللہ اور اس کے رسول صلے علی تیم تمہیں گھر یلو گدھوں کے گوشت سے منع فرماتے ہیں، کیونکہ وہ پلید ہے۔ اس حدیث کو ابن عون سے صرف جریر بن حازم نے روایت کیا۔اس میں ابن وہب کا تفرد ہے۔","",{"k":"صحیح بخاری (٤١٩٩)، صحيح مسلم (١٩٤٠)۔"}],[6458,"سیدنا ابو داود نبی الیہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے، پس جب ہم ذوالحلیفہ پہنچے تو رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے اور دو رکعتیں پڑھیں، پھر آپ صلی اللہ علیہ وسلم نے نماز کے بعد حج و عمرہ کا ایک ساتھ احرام باندھا۔“ یہ حدیث سیدنا ابو داود رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں ہارون الفروی کا تفرد ہے۔ ٦٤٥٩","",{"k":"کر مجمع الزوائد (٣/٢٣٦)، مجمع البحرين (١٧٤٧)، اسناده ضعيف۔"}],[6459,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: ”ہر انسان کے لیے آسمان میں دو دروازے ہیں، ان میں سے اس کا عمل چڑھتا ہے اور اس کا رزق نازل ہوتا ہے، پس جب مومن آدمی فوت ہوتا ہے تو وہ اس پر روتے ہیں۔“ اس حدیث کو صفوان بن سلیم سے صرف ابراہیم بن المہاجر بن مسمار نے روایت کیا۔","",{"k":"کی سنن ترمذی (٣١٥٥)، ضعيف الجامع (٥٢١٤)، قال الشيخ الالباني : ضيعف۔"}],[6460,"سیدنا عقبہ بن عامر الجبنی فی اللہ بیان کرتے ہیں: میں نے رسول اللہ مانے ہم کو دیکھا آپ صلی اللہ علیہ وسلم نے اپنے چچا عباس رضی اللہ عنہ کا ہاتھ پکڑا، پھر فرمایا: \"عباس ( الله )! نبوت نہیں ہوگی، مگر اس کے بعد خلافت ہو گی اور آخری دور میں تیری اولاد سے سترہ حکمران بنیں گے۔ ان میں سے: سفاح، ان میں سے منصور، ان میں مہدی جبکہ وہ مہدی نہیں . ان میں سے جموح، ان میں سے عاقب، ان میں سے تیری اولاد سے واہن اور اس سے میری امت کے لیے ویل ( تباہی) ہے، وہ کس طرح اسے ہلاک کرے گا اور اس کے اعمال ختم کر دے گا، وہ اور اس کے پیروکار دین اسلام پر نہیں ہوں گے، پس جب اس کی بیعت کی جائے گی تو اٹھارہویں پر ان کی حکومت ختم ہو جائے گی اور اہل عرب اپنے گھروں سے نکلیں گے۔‘ یہ حدیث سیدنا عقبہ بن عامر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابن لہیعہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٨٧/٥)، مجمع البحرين (٢٥٢٣)، اسناده ضعیف ٥۔"}],[6461,"سیدنا عبد اللہ بن مسعود ضیا المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عباس رضی اللہ عنہ سے فرمایا: ”چا جان! دنیا ختم نہ ہو گی حتی کہ آخری دور میں ان کی حکومت کے انقطاع کے وقت تمہاری اولا د سے ایک آدمی بادشاہ بنے گا اور وہ اٹھارہواں ہے، اس کے ساتھ اندھا بہرا فتنہ ہوگا، ہر دس ہزار میں سے نو ہزار نوسو قتل کر دیے جائیں گے، ان میں سے تھوڑے سے بچیں گے اور عراق کی جگہ پر ان کا قتال ہوگا۔ راوی نے بیان کیا، سیدنا عباس رضی اللہ عنہ پڑے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: ” آپ کیوں روتے ہیں؟ وہ میرے امت کے شریر لوگ ہیں، وہ دین سے اس طرح نکل جائیں گے جس طرح تیر شکار سے پار ہو جاتا ہے، وہ دنیا کے طلب گار ہوں گے اور آخرت کی فکر نہ کریں گے۔ یہ حدیث سیدنا ابن مسعود بنی اہلیہ سے صرف اس اسناد سے مروی ہے۔: اس میں احمد بن محمد الیمامی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٨٨/٥)، مجمع البحرين (٢٥٢٤)، اسناده ضعيف۔"}],[6462,"سیدنا عبداللہ ابن عباس نی این جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے عصر کی نماز اینجا پڑھائی، جب آپ صلی اللہ علیہ وسلم چوتھی رکعت میں تھے تو سیدنا حسن و حسین نوای نینجا آئے اور رسول اللہ صلی اللہ علیہ وسلم کی پشت پر چڑھ گئے، آپ مطلئے علیم نے انہیں اپنے آگے بٹھا دیا، سیدنا حسن رضی اللہ عنہ آئے تو رسول اللہ صل علی نے سیدناحسن بنی اہلیہ کو اپنے دائیں کندھے پر بٹھا لیا اور سیدنا حسین بھی لینے کو اپنے بائیں کندھے پر۔ پھر فرمایا: ”لوگو! کیا میں تمہیں نانا اور نانی کے حوالے سے سب سے بہتر شخص کے متعلق نہ بتاؤں؟ کیا میں تمہیں چا اور پھوپھی کے حوالے سے سب سے بہتر شخص کے متعلق نہ بتاؤں؟ کیا میں تمہیں ماموں اور پھوپھی کے حوالے سے بہترین شخص کے متعلق نہ بتائیں؟ کیا میں تمہیں والد اور والدہ کے حوالے سے بہترین شخص کے متعلق نہ بتاؤں؟ وہ دونوں حسن و حسین نا اشنا ہیں۔ ان کے نانا رسول اللہ صلی اللہ علیہ وسلم اور نانی خدیجہ بنت خویلد علی الجھا ہیں۔ ان کی والدہ فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم ہیں اور والد علی بن ابی طالب نیل الیہ ہیں، ان کے بچا جعفر بن ابی طالب رضی اللہ عنہ اور پھوپھی ام ہانی بنت ابی طالب نوالا لیے ہیں، ان کے ماموں القاسم ابن رسول اللہ نے ہم ہیں اور ان کی خالہ زینب، رقیہ اور ام کلثوم بین این رسول اللہ لے علی یمن کی بیٹیاں ہیں، ان کا نانا جنت میں، ان کا والد جنتی، ان کی نانی جنتی، ان کی والدہ، ان کے چچا، ان کی پھوپھی جنتی ہیں، ان کی خالائیں جنتی، ان کے ماموں جنتی، وہ دونوں جنتی ہیں اور ان کی بہن جنتی ہے۔ اس حدیث کو عبد الرزاق سے صرف احمد بن محمد بن عمرو بن یونس الیمامی نے روایت کیا۔","",{"k":"لی الله ٣٧٨٦، اسناده ضعيف . مجمع الزوائد (٩/١٨٤)، كنز العمال (٣٤٢٧٨)، مجمع البحرين، رقم۔"}],[6463,"سیدنا ابو بکر الصدیق رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”ہر امت کا ایک امین ہوتا ہے اور اس امت کا امین ابو عبیدہ بن الجراح ہے۔ یہ حدیث سیدنا ابو بکر یا لینے سے صرف اس اسناد سے مروی ہے۔ اس میں الزبیر بن عباد المدنی کا تفرد ہے۔ ٦٤٦٤","",{"k":"٦٤٦٣ مجمع البحرين (٣٧٥٦)۔"}],[6464,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم، سیدنا ابو بکر اور سیدنا عم نا ہونا کے پیچھے نماز پڑھی، وہ جب نماز شروع کرتے تو رفع الیدین کرتے تھے۔ جب رکوع کے لیے اللہ اکبر کہتے تو رفع الیدین کرتے تھے اور جب (رکوع سے سر اٹھاتے اور سجدے کے لیے اللہ اکبر کہتے تو رفع الیدین کرتے تھے۔“ اس حدیث کو عبد الرحمن بن الاسود سے صرف لیث بن ابی سلیم نے روایت کیا۔ اس میں ابراہیم بن محمد اسلمی کا تفرد ہے۔","",{"k":"كر مجمع الزوائد (٢/١٠٢)، مجمع البحرین (٧٨٩)، اسناده ضعيف۔"}],[6465,"سیدنا سمرہ بن جندب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے حکم دیا گیا ہے کہ میں لوگوں سے قتال کروں حتی کہ وہ لا الہ الا اللہ کا اقرار کریں، پس جب وہ اس کا اقرار کر لیں گے تو وہ حق اسلام کے علاوہ اپنی جانیں اور اپنے اموال مجھ سے بچالیں گے اور ان کا حساب اللہ کے ذمے ہے۔“ اس حدیث کو مبارک بن فضالہ سے صرف عمر بن سہل المازنی نے روایت کیا۔ اس میں اسحاق بن الضیف کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/٢٥)، مجمع البحرين (٢٧)۔"}],[6466,"سیده ضباعہ بنت الزبیر بن عبد المطلب رویال الیہا نے بیان کیا: رسول اللہ صلی اللہ علیہ وسلم کا جوتا بیچ سے بار یک تھا۔ یہ حدیث سیدہ ضباعہ رضی اللہ عنہا سے صرف اس اسناد سے مروی ہے۔ اس میں الزبیر بن بکار کا تفرد ہے۔","",{"k":"مجمع ١٣٨/٥ الزوائد (٥/١٣٨)، مجمع البحرين (٤٢٣٠)، اسناده ضعيف۔"}],[6467,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے دو چتکبرے مینڈھوں کی قربانی کی، ایک اپنی اور اپنے گھرانے کی طرف سے اور دوسری اپنی اور اپنی امت میں سے اس شخص کی طرف ا سے جس نے قربانی نہ کی ہو۔ “ اس حدیث کو الزہری سے صرف عیسی بن عبد الرحمن نے اور عیسیٰ سے صرف عبد اللہ بن عیاش نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔ معلوم ہوا کہ ایک بکری کا قربانی کرنا سارے گھر کی طرف سے کفایت کر جائے گا،لیکن دوسرے لوگوں کے لیے ذبح کرنا یہ صرف رسول اللہ صلی اللہ علیہ وسلم کا خاصہ ہے۔","",{"k":"مجمع الزوائد (٤/٢٢)، مجمع البحرين (٨٤٤)۔"}],[6468,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو حجۃ الوداع میں فرماتے ہوئے سنا جبکہ آپ صلی اللہ علیہ وسلم اپنی اونٹنی پر تھے اور آپ صلی اللہ علیہ وسلم کا ہاتھ سیدنا علی نبی الیہ کے کندھے پر تھا، ” اے اللہ! کیا میں نے دین پہنچا دیا، اے اللہ! کیا میں نے دین پہنچا دیا، یہ میرا چچا زاد اور میری اولاد (حسن و حسین واہی) کا باپ ہے، اے اللہ! اس سے دشمنی رکھنے والے کو اوندھے منہ جہنم میں پھینک۔“ اس حدیث کو سیدنا عبد اللہ بن مر ضیا اللہ سے صرف اسماعیل بن یحی التمیمی نے روایت کیا۔ اس میں محمد بن سہل المازنی کا تفرد ہے۔ مذکورہ حدیث سے سیدنا علی ربی الیہ کی فضیلت ثابت ہوتی ہے کہ آپ نوال الیہ کے ساتھ دشمنی","",{"k":"كنز العمال (١٢٩١٤)۔","f":"رکھنا جہنم میں جانے کا سبب ہے۔ ٦٤٦٩"}],[6469,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دو صفوں، جماعتوں کے درمیان قتل ہونے والا بدترین مقتول ہے، جبکہ ان دونوں میں سے ایک بادشاہت کا طلب گار ہو۔“ اس حدیث کو محمد بن المنکد رسے صرف اسامہ بن زید نے اور اسامہ سے صرف ابن وہب نے روایت کیا، اس میں عبد الاول المعلم کا تفرد ہے۔ ٦٤٧٠","",{"k":"مجمع الزوائد (٢٩٢/٧)، ضعيف الجامع الصغير (٣٣٩٦)، مجمع البحرين (٤٣٥٤)۔"}],[6470,"نعیم الحجر بیان کرتے ہیں: میں نے مروان کو سیدنا ابو ہریرہ رضی اللہ عنہ سے کہتے ہوئے سنا: اللہ کی قسم! میں تم سے محبت کرتا ہوں، اگر تم حسن بن علی علی الیہ سے محبت نہ کرو۔ ابو ہریرہ میں اللہ نے مروان سے کہا: مجھے کیا ہے کہ میں ان سے محبت نہ کروں جبکہ میں نے ایک دن رسول اللہ نے تم کو دیکھا کہ آپ ان کے دروازے پر آئے تو کہا: ”حسن! تو حسن علی یہ باہر آئے تو آپ نے ان کے منہ کا بوسہ لیا اور ان کی زبان چوسی اور انہیں گلے لگایا۔ اللہ کی قسم! میں ان سے محبت کرتا رہوں گا۔ اس حدیث کو عمارہ بن غزیہ سے صرف بیٹی بن ایوب نے اور بیچی سے صرف اسحاق بن الفرات نے روایت کیا۔ اس میں احمد بن سعید الہمدانی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام بینی اسلیم اہل بیت سے محبت وعقیدت رکھتے تھے کہ اس محبت کے لیے حکمرانوں کے خوف اور لالچ کا بھی ڈر نہ ہوتا۔ (٢) مذکورہ بالا روایت سے حسنین کریمین رضای اینجا کی عظمت کا بھی اثبات ہوتا ہے۔ کتنے خوش نصیب وہ دونوں شہزادے تھے کہ جن کی زبان مبارک نبی معظم صلی اللہ علیہ وسلم چوسا کرتے تھے۔ صحابی رسول بیان کرتے ہیں کہ رایت رسول الله لم يمص لسانه او قال شفته الخ )) (مسند احمد، رقم: ١٦٧٩١، مجمع الزوائد: ٩/ ٨٠) ”میں نے دیکھا، رسول اللہ لے لیام سیدنا حسن نیل اللہ کی زبان یا ہونٹوں کو چوس رہے تھے اور اللہ ایسی زبان یا ہونٹ کو کبھی عذاب نہیں دے گا۔ پھر کیا ہمارے لیے یہ کافی نہیں کہ جن نواسوں سے نبی مکرم صلے ایام محبت پیار کرتے تھے اور ہمیں ان سے محبت پیار کرنے کی ترغیب دی گئی ہے، ہم اس نبی کی خاطر اپنی تحقیق بند کر کے اپنے دل میں سیدنا حسین رضی اللہ عنہما کی محبت کو جگہ دیں۔","",{"k":"کر مجمع الزوائد: ٩/ ١٨٠ . فائده۔"}],[6471,"ابراہیم بن سعد نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا، انہوں نے کہا: میں نے سیدنا عمار بن یاسر رضی لن لینے کو جنگ صفین میں ان کی شہادت کے دن یہ اعلان کرتے ہوئے سنا: میں نے الجبار سے ملاقات کی اور حورعین سے شادی کی۔ آج ہم محمد صلی اللہ علیہ وسلم کے چہیتوں اور ان کی جماعت سے ملاقات کریں گے۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھے وصیت فرمائی: دنیا سے تمہارا آخری توشہ دودھ کی لسی ہوگا۔“ یہ حدیث ابراہیم بن عبد الرحمن بن عوف سے صرف ان کے بیٹے کی روایت سے مروی ہے۔ اسے ابراہیم بن سعد سے صرف ابن وہب نے روایت کیا۔ اس میں حرملہ بن بیٹی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٩/٢٩٥)، مستدرك حاكم (٤٣٩/٣)، سلسه صحيحه (٣٢١٧)، مجمع البحرين (٣٨٤٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ دودھ میں پانی ملا کر پتلا کر کے پینا مستحب ہے۔ بلکہ آج کی سائنس نے تو اس کے بہت زیادہ فوائد بتائے ہیں، پیشاب کی جلن رکاوٹ اور پتھری کی علامات میں دودھ کی لسی اعلیٰ مشروب ہے۔ تفصیل کے لیے سنت نبوی اور جدید سائنس کا مطالعہ کریں۔ (٢) جنگ صفین میں سیدنا عمار فنی این شریک ہوئے اور مذکورہ بالا صفت والا دودھ پیا تو ان کو آپ صلی اللہ علیہ وسلم کی پیشن گوئی یاد آئی، پھر وہ مشروب پینے کے بعد شہید ہو گئے اور آپ صلی اللہ علیہ وسلم کی یہ پیشن گوئی پوری ہو گئی۔"}],[6472,"سیدنا زید بن خالد الجہنی بنی اہلیہ نے بیان کیا، رسول اللہ علیم نے مجھے بھیجا تو فرمایا: ”لوگوں کو خوشخبری سناؤ کہ جس نے یہ اقرار کیا کہ اللہ کے سوا کوئی معبود نہیں، وہ یکتا ہے اس کا کوئی شریک نہیں“ وہ جنت میں داخل ہو گا۔ اس حدیث کو ابو حرب بن زید بن خالد سے صرف بکیر بن عبد اللہ نے اور بکیر سے صرف اس کے بیٹے مخرمہ نے روایت کیا۔ اس میں قدامہ بن محمد الاشجعی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/١٨)، مجمع البحرين (١٧)۔","f":"مذکورہ حدیث سے کلمہ توحید کا اقرار کرنے والوں کی فضیلت واضح ہے۔ لیکن یہ کلمہ توحید اس وقت فائدہ دے گا جب خلوص دل سے تو حید کی گواہی دی جائے، جیسا کہ سیدنا معاذ ضی الیہ سے مروی ہے، یقیناً نبی رحمت علی علیم نے فرمایا: جس شخص نے لا الہ الا الله (کلمہ توحید ) کی گواہی دل کو خالص کرتے ہوئے دی وہ جنت میں داخل ہو گا۔“ (سلسله صحيحه، رقم: ٢٣٥٥) ٦٤٧٣"}],[6473,"سیدنا فضالہ بن عبید فضل اللہ بیان کرتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \" تم اسے برابر برابر لو“ یعنی سونے کے بدلے سونا اور چاندی کے بدلے چاندی۔“ اس حدیث کو بکیر بن عبد اللہ سے صرف مخرمہ نے روایت کیا۔ اس میں قدامہ بن محمد کا تفرد ہے۔",""],[6474,"سیدنا ابو ہریرہ ولی الیہ بیان کرتے ہیں، دو آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو ان میں سے ایک نے عرض کیا: اللہ کے رسول! میرے اور اس کے درمیان فیصلہ فرما دیں۔ میرا بیٹا اس کی اہلیہ کے ہاں ملازم تھا، میرا بیٹا کنوارا تھا، اس نے اس کے ساتھ زنا کرلیا، میں نے کسی بے علم شخص سے مسئلہ دریافت کیا تو انہوں نے مجھے بتایا کہ میرے بیٹے پر رجم کی سزا ہے، پس میں نے اس کی طرف سے اتنا اور اتنا فدیہ دے دیا، پھر میں نے اہل علم سے مسئلہ دریافت کیا تو انہوں نے مجھے بتایا کہ میرے بیٹے پر رجم کی سزا نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں تمہارے درمیان حق کے ساتھ فیصلہ کروں گا، تم نے جو کچھ اسے فدیے کے طور پر دیا ہے وہ اسے تمہیں واپس کرنا ہو گا، تمہارے بیٹے کو سو کوڑے مارے جائیں گے اور سال کی جلا وطنی ہوگی اور رہی اس کی اہلیہ تو اسے رجم کیا جائے گا۔ اس حدیث کو عمرو بن شعیب سے صرف بکیر بن عبد اللہ نے اور بکیر سے صرف مخرمہ نے اور مخرمہ سے صرف قدامہ بن محمد نے روایت کیا۔ اس میں احمد بن صالح کا تفرد ہے۔","",{"k":"صحیح بخاری کتاب الصلح (٢٦٩٥، ٦٩٦)، مسلم، سنن ابو داود (٤٤٤٥)۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے کہ کنوارے زانی کی سزا سو کوڑے اور ایک سال کی جلاوطنی ہے اور شادی شدہ زانی کی سزا رجم ہے۔ خلفائے راشدین عام صحابہ بھی نیم تابعین اور اکثر فقہا نے جلا وطنی کے حکم پر مسلسل عمل کیا ہے۔ (شرح السنة للبغوی: ٢٧٨/١٠) امام ابن منذر جماللہ نے کنوارے زانی کو جلا وطن کرنے پر اجماع نقل فرمایا ہے۔ (شرح فتح القدير: ٢٦/٥) جبکہ امام ابوحنیفہ ہاللہ کے نزدیک اسے جلا وطن کرنا واجب نہیں۔ (بداية المجتهد: ٢/ ٧٣٦، المغنى: ١٢/ ٣٢٢) امام شوکانی اللہ فرماتے ہیں کہ احادیث امام ابو حنیفہ اللہ کے موقف کے رد میں ہیں۔ (نیل الاوطار: ٥٢٥/٤)"}],[6475,"نبی سے یمن کی زوجہ محترمہ سیدہ ام سلمہ بنی نو با بیان کرتی ہیں: رسول اللہ صلی اللہ علیہ وسلم سے کہا گیا: اللہ کے رسول طلے تم! آپ ملے لیے تم نے سیدہ حمزہ رضی اللہ عنہا کی بیٹی کو پیغام نکاح کیوں نہ بھیجا؟ آپ ے علی ایم نے فرمایا: \"حمزہ میرے رضاعی بھائی ہیں۔ اس حدیث کو زہری سے ان کے بھائی نے روایت کیا اور ان کے بھائی سے صرف بکیر بن عبد اللہ نے اور بکیر سے صرف مخرمہ نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ رضاعت بھی حرمت میں نسب کے مانند ہے۔ رضاعت سے حرام ہونے والے رشتے یہ ہیں، رضاعی ماں، بہن، بیٹی، پھوپھی، خالہ، بھانجی اور بھتیجی۔ (تفسیر فتح القدیر: ١ / - فقه السنة: ٢/ ١٤٨) چونکہ سیدنا حمزہ رضی اللہ عنہ یہ رسول اللہ صلی اللہ علیہ وسلم کے چچا ہونے کے ساتھ ساتھ رضاعی بھائی بھی تھے۔ ان کو اور نبی کا اسلام کو ابولہب کی آزاد کردہ لونڈی ثویبہ نے دودھ پلایا تھا۔ اس طرح سیدنا حمزہ نبی اللہ کی بیٹی آپ ملنے سے یتیم کی رضاعی بھتیجی ہوئی، جو کہ نبی بھتیجی کی مانند ہی حرام ہے۔ اس لیے آپ ملنے کی یکم نے اس کے ساتھ شادی سے انکار کیا۔","",{"k":"صحیح مسلم (١٤٤٨)۔"}],[6476,"سيدنا سعد رضی اللہ عنہ بیان کرتے ہیں، رسول اللہ علیم کے دور میں دو بھائی تھے، ان میں سے ایک دوسرے سے افضل تھا، پس ان میں سے جو افضل تھا وہ فوت ہو گیا، پھر اس کے بعد دوسرا چالیس راتیں زندہ رہا اور پھر فوت ہوا۔ رسول اللہ صلی اللہ علیہ وسلم سے پہلے کی دوسرے پر فضیلت ذکر کی گئی تو آپ نے فرمایا: کیا اس (بعد والے) نے نمازیں نہیں پڑھیں؟ انہوں نے عرض کیا، جی ہاں، رسول اللہ علیم نے فرمایا: اس میں کوئی حرج کی بات نہ تھی؟ انہوں نے عرض کیا: جی ہاں، آپ نے فرمایا: تمہیں کیا معلوم اس کی نماز کہاں تک پہنچ گئی؟“ پھر اس وقت رسول اللہ سلیم نے فرمایا: ”نمازوں کی مثال کسی شخص کے دروازے پر شیریں پانی والی گہری نہر کے مانند ہے، وہ اس میں روزانہ پانچ مرتبہ غوطے لگاتا ہے، تم اس کے متعلق کیا خیال کرتے ہو کہ اس پر کوئی میل کچیل باقی رہ جائے گی؟ تمہیں کیا معلوم کہ اس کی نماز نے اسے کس مقام تک پہنچا دیا؟“ اس حدیث کو عامر بن سعد کے حوالے سے جو اس کے والد سے صرف بکیر بن عبد اللہ بن اشج نے اور بکیر سے صرف مخرمہ نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے اور زہری کے بھتیجے نے اسے زہری، عن صالح بن عبد اللہ بن ابی فروہ، عن عامر بن سعد، عن ابان بن عثمان عن ابیہ کی سند سے روایت کیا ہے۔","",{"k":"مجمع الزوائد (١/٢٩٧)، صحیح ابن خزیمه (٣١٠)، مسند احمد (١٧٧/١)، مجمع البحرين (٥٤٣)، قال شعیب الارناؤط اسناده قوی۔","f":"مذکورہ حدیث سے معلوم ہوا کہ لمبی زندگی مومن کے لیے رحمت جبکہ نیکیوں کی توفیق حاصل ہو۔ یہ بھی معلوم ہوا کہ انسان چند دنوں کی نماز اور دیگر اعمال کی وجہ سے بہت زیادہ مقام حاصل کر سکتا ہے۔ (٢) مذکورہ حدیث سے پانچوں نمازوں کی ادائیگی کی فضیلت اور اس کے فائدہ کا اثبات ہوتا ہے، ان سے انسان کے گنا دھل جاتے ہیں، لیکن اسی نماز سے جو سنت کے مطابق خشوع وخضوع کے ساتھ پابندی سے ادا کی جائے نہ کہ اپنے من مانے طریقے سے اور جب چاہا پڑھ لینے سے۔ ٦٤٧٧"}],[6477,"سیدنا عبد اللہ بن محمد ابن عقیل نے بیان کیا، سیدنا انس بن مالک فضل اللہ مدینہ تشریف لائے تو عمر بن عبد العزیز نے مجھے بھیجا اور کہا: ان سے اس حدیث کے متعلق جسے حجاج بن یوسف نے کچھ لوگوں کے متعلق بیان کیا تھا جو رسول اللہ صلی اللہ علیہ وسلم کے دور میں نکلے تھے اور آپ نے ان میں سے دو کی آنکھوں میں سلائیاں پھیری تھیں، دو کے اعضا کاٹے تھے اور دو کو سولی چڑھایا تھا۔ سیدنا انس صلی اللہ نے فرمایا: یہ وہ لوگ تھے کہ انہوں نے اسلام کا اقرار کیا اور مدینہ میں قیام کیا، پھر اسلام کو نا پسند کرتے ہوئے نکل گئے اور مشرکوں سے جاملے اور مدینے کے چرنے والے جانوروں کو لوٹا، پس وہ اسے ہانک کر لے گئے، نبی صلی اللہ علیہ وسلم کو ان کے متعلق بتایا گیا تو آپ صلی اللہ علیہ وسلم نے ان کی تلاش میں کچھ لوگ بھیجے اور انہوں نے انہیں گرفتار کر لیا، راوی نے بیان کیا: سیدنا عمر رضی اللہ عنہ نے انہیں جواب دیا، کاش! کہ آپ حجاج کو یہ حدیث بیان نہ کرتے، کہ وہ لوگ اسلام سے بیزار ہو گئے اور وہ مشرکوں سے جاملے ہیں اور انہوں نے مدینہ کے چرنے والے جان دار لوٹے، کیونکہ حجاج نے اس سے ان کو قتل کرنا جو حلال سمجھ لیا ہے جو اسلام سے خروج کا ارادہ رکھتے ہیں نہ وہ مشرکوں سے جاملے ہیں، سیدنا عمر رحمہ اللہ نے کہا: ان سے پوچھو: کیا نبی صلی اللہ علیہ وسلم خضاب لگایا کرتے تھے، کیونکہ ہم یہاں آپ کے بالوں میں سے کچھ بال دیکھتے ہیں کہ انہیں رنگ کیا ہوا ہے؟ سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ مالے علم کو بال کالے کرنے سے منع کیا گیا تھا۔ پس اگر میں شمار کروں تو میں نے آپ صلی اللہ علیہ وسلم کے سر اور داڑھی میں جو سفید بال شمار کیسے وہ پندرہ بھی نہ تھے، تم یہ جو بال دیکھتے ہو کہ انہیں رنگ کیا گیا ہے وہ تو خوشبو کی وجہ سے ہے جو رسول اللہ صلی اللہ علیہ وسلم کے بالوں میں لگائی گئی تھی۔“ اس حدیث کو عبد اللہ بن محمد سے صرف جعفر بن برقان نے روایت کیا۔ اس میں محمد ابن حمزة الرقی کا تفرد ہے۔","",{"k":"مجمع الزوائد: ٢٨٣/٦ . ل پیش۔"}],[6478,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی تعلیم نے فرمایا: ”مسلمان دوسرے مسلمان کا بھائی ہے، وہ اس سے خیانت کرتا ہے نہ اسے بے یارو مددگار چھوڑتا ہے۔ تمام مسلمان اپنے علاوہ دوسرے کے مقابلے میں ایک ہیں، ان کے خون برابر ہیں اور ان کا عام آدمی بھی امان دے سکتا ہے۔“ اس حدیث کو ابراہیم بن نافع سے صرف ابو القاسم بن ابی الزناد نے روایت کیا۔ اس میں سعید بن بیٹی کا تفرد ہے۔ مذکورہ حدیث میں مسلمانوں کو ایک خاندان کے افراد کی طرح رہنے کی ہدایات دی گئی ہے کہ جس طرح ایک شخص اپنے بیٹے، بھائی وغیرہ پر کوئی ظلم کرنا، مدد کے وقت اسے بے یارومددگار چھوڑ نا پسند نہیں کرتا، اسے کوئی حاجت ہو تو اسے پوری کرنے کی کسی تکلیف اور پریشانی میں مبتلا ہو تو اسے دور کرنے کی اور اس سے کوئی کوتا ہی غلطی ہو جائے تو اس کی پردہ پوشی کی سعی کرتا ہے۔ یہی معاملہ ایک مسلمان کا دوسرے مسلمان کے ساتھ ہونا چاہیے۔ اس سے اللہ ذوالجلال خوش ہوتا ہے اور اس کا بہترین صلہ اسے دنیا و آخرت میں عطا فرماتا ہے۔ ٦٤٧٩","",{"k":"مجمع الزوائد (٢٨٣/٦)۔"}],[6479,"سیدنا عبداللہ ابن عباس نبی انتہا سے روایت ہے کہ نبی ملے عالم نے سیدہ ضباعہ بنی ہویا کو حکم فرمایا کہ وہ حج میں شرط قائم کر لے اور یوں کہے: میرے احرام کھولنے کی جگہ وہی ہو گی جہاں تو مجھے روک لے گا۔‘ اس حدیث کو داود بن الحصین سے صرف ابراہیم بن اسماعیل نے روایت کیا۔ اس میں سعید بن بیٹی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ اگر انسان کو کوئی ایسا مرض لاحق ہو جو سفر اور ارکان حج کی ادا ئیگی کے لیے رکاوٹ بن سکتا ہو تو مشروط احرام بھی باندھ سکتا ہے۔ مشروط احرام باندھنے کا","",{"k":"صحيح مسلم (١٢٠٨)، سنن ابو داود (١٧٧٦)، سنن ترمذی (٩٤١)۔","f":"یہ ہوگا کہ اگر اسے راستے میں کوئی رکاوٹ پیش آ گئی اور احرام کھولنا پڑ گیا تو اس پر کوئی فدیہ لازم نہیں ہو گا۔ لیکن اگر اس نے شرط نہ لگائی اور کسی رکاوٹ کی وجہ سے احرام کھول دیا تو اس پر لازم ہے کہ قربانی کا جانور خرید کر کسی دوسرے کے ہاتھ مکہ روانہ کرے اور جب قربانی کے ذبح ہونے کا وقت ہو جائے تو احرام کھول دے۔ اگر قربانی بھیجا ممکن نہ ہو تو رکاوٹ کی جگہ پر ہی قربانی ذبح کر دے اور حجامت بنوا کر احرام کھول دے۔ سیدہ ضباعہ بنی اینجا رسول اللہ صلی اللہ علیہ وسلم کی چچا زاد بہن ہیں اور ان کی کنیت ام حکیم ہے۔ سیدہ ضباعہ بنت زبیر بنایا ہی جا نے یہ شرط تو لگائی، مگر رکاوٹ پیش نہ آئی تھی اور انہوں نے حج پورا کر لیا تھا۔"}],[6480,"سیدہ عائشہ نیا نیا نے بیان کیا، رسول اللہ نے تم اپنے گھر میں اسی طرح ہوتے تھے جس طرح تم میں سے کوئی اپنے گھر میں ہوتا ہے، آپ صلی اللہ علیہ وسلم اپنا کپڑ اسی لیتے تھے اور اسی طرح کام کاج کیا کرتے تھے جس طرح تم میں سے کوئی کام کاج کرتا ہے۔ اس حدیث کو ابن جریج سے صرف یحیی بن سعید نے روایت کیا۔ انده مذکورہ حدیث سے معلوم ہوا کہ نبی معظم ملے عام اپنے گھر میں تشریف لا کر اپنے گھر والوں کے کام کاج میں ہاتھ بٹاتے تھے۔ گویا ان کی خدمت میں لگ جاتے تھے اپنے جوتے مبارک بھی خود ہی گانٹھ لیتے تھے، اپنا کپڑا خود ہی سی لیتے اور اپنی بکری کا دودھ بھی خود دھو لیتے تھے۔ سبحان اللہ! نبی مکرم صلے علیکم کے مزاج مبارک میں کیا عاجزی انکساری اور تواضع تھی کہ ان کاموں کو اپنے ہاتھ سے بجالانا اپنی شان کے خلاف نہ سمجھتے تھے۔ آج ہم لوگوں کا یہ حال ہے کہ گھر کا کوئی کام اپنے ہاتھ سے کرنا اپنی شان کے خلاف سمجھتے ہیں، بلکہ عیب سمجھتے ہیں، بس گھر میں بیٹھ کر حکم چلاتے رہتے ہیں اور اگر کسی کام میں ذراسی دیر ہو جائے تو گھر والوں کی خیر نہیں ہوتی۔ ہم لوگوں کو رسول اللہ صلی اللہ علیہ وسلم کے مبارک طریقہ پر عمل کرنا چاہیے اور گھر کے کاموں میں ہاتھ بٹانا چاہیے تا کہ سارے کاموں کا بوجھ گھر والوں پر نہ پڑے۔","",{"k":"صحیح بخاری (٦٧٦)، سنن ترمذی (٢٤٨٩)، ادب المفرد (٥٤١، ٥٣٩)۔"}],[6481,"سیدنا انس بن مالک فی اللہ نے بیان کیا، سیدہ ام سلیم بنی الہا نے رسول اللہ من می کنم سے درخواست کی کہ آپ لئے یم ان کے گھر تشریف لائیں اور وہاں نماز پڑھیں، تا کہ ہم اس جگہ کو جائے نماز بنا لیں، پس آپ ملنے سلیم نے ایسے ہی کیا، آپ صلی اللہ علیہ وسلم ان کے ہاں آئے اور انہوں نے اپنی ایک چٹائی کا قصد کیا، اس پر پانی چھڑ کا تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی اور انہوں نے آ ملے نیم کے ساتھ نماز پڑھی۔“ اس حدیث کو بیٹی بن سعید الانصاری سے صرف یحیی بن سعید الاموی اور سلیمان بن کثیر نے روایت کیا۔ انون مذکورہ حدیث سے معلوم ہوا کہ چٹائی پر نماز پڑھنا جائز ہے اور ان لوگوں کا بھی رد ہوتا ہے جو کہتے ہیں کہ سجدہ مٹی پر کرنا چاہیے۔ چٹائی پر پانی کیوں چھڑ کا گیا،سنن ابی داؤد میں ہے کہ وہ چٹائی طویل استعمال سے کالی ہو گئی تھی۔ (ابو داؤد، رقم: ٦١٢)","",{"k":"سنن نسائي (١٤٢٧)، سنن ابو داود (٦١٢)۔","f":"٦٤٨٢"}],[6482,"سیدنا جابر بن عبد اللہ الانصاری رضی اللہ عنہما سے اللہ تعالیٰ کے فرمان: ”اللہ ان مومنوں سے راضی ہو گیا جب وہ درخت کے نیچے آپ کی بیعت کر رہے تھے۔“ کی تفسیر میں مروی ہے، انہوں نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کی اس بات پر بیعت کی کہ ہم فرار نہیں ہوں گے، اور ہم نے موت پر آپ کی بیعت نہیں کی تھی۔ اس حدیث کو اوزاعی سے صرف عیسی بن یونس نے روایت کیا۔ اس میں سعید بن بیٹی کا تفرد ہے۔","",{"k":"١٨٥٦ صحيح مسلم، رقم: سنن ترمذی (١٥٩١، ١٧٥٧)۔"}],[6483,"زر نے بیان کیا، سیدنا عمر بن خطاب رضی اللہ عنہ نے ہمیں شام میں خطاب کیا تو انہوں نے کہا: جس طرح میں تمہیں خطاب کرنے کے لیے کھڑا ہوں، اسی طرح رسول اللہ صلی اللہ علیہ وسلم ہمیں خطاب کرنے کے لیے کھڑے ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”میرے اصحاب کے ساتھ بھلائی کرنے میں میری وصیت قبول کرو، میرے اصحاب سے بھلائی کرنے میں میری وصیت قبول کرو، پھر ان کے ساتھ جو ان کے بعد آئیں، پھر ان کے ساتھ جو ان کے بعد آئیں، پھر جھوٹ عام ہو جائے گا، حتی کہ آدمی گواہی دے گا اس سے پہلے کہ اس سے (گواہی کا سوال کیا جائے اور قسم دے گا، اس سے پہلے کہ اس سے قسم طلب کی جائے۔ پس جو شخص جنت کے وسط میں رہنا چاہے تو وہ جماعت کے ساتھ رہے، جس شخص کو اس کی نیکی اچھی لگے اور اس کی برائی اسے بری لگے تو وہ مومن ہے۔“ اس حدیث کو عاصم سے صرف ابو بکر بن عیاش نے رویت کیا۔ اس میں سعید بن یحییٰ الاموی کا تفرد ہے۔ ٦٤٨٤","",{"k":"سنن ترمذی (٢١٦٥)، قال الشيخ الالبانی صحیح سنن ابن ماجه (٢٣٦٣)۔"}],[6484,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بیع کرنے والے دونوں افراد (بائع اور مشتری) کو اپنی بیع میں اختیار رہتا ہے جب تک وہ جدا نہ ہوں یا ( بیع کو منعقد کرنے یا فسخ کرنے کا اختیار ہو۔ اس حدیث کو یحیی بن سعید کے حوالے سے القاسم بن محمد سے صرف ابوضمرہ نے روایت کیا۔ اس میں الزبیرین بن بکار کا تفرد ہے۔","",{"k":"صحیح بخاری (٢١٠٩)، مسلم (١٥٣١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جب تک بائع اور مشتری ایک ہی مجلس میں ہوں انہیں بیچ فسخ کرنے کا اختیار ہے اور جب وہ جدا ہو جائیں تو پھر یہ اختیار ختم ہو جاتا ہے اور بیج پختہ ہو جاتی ہے لیکن اگر شرط قائم کی ہو تو اختیار باقی رہتا ہے۔ اختیار والے سودے سے مراد یہ ہے کہ بیچ کے وقت بائع نے مشتری کو اختیار دیا ہو یا مشتری نے اختیار کی شرط لگائی ہو تو پھر مقررہ پوری مدت ہونے تک دونوں کو اختیار ہوتا ہے چاہے وہ بیچ فسخ کر دیں یا منعقد کر دیں۔"}],[6485,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں، ابوطلحہ نبی الیہ نے مجھے حریرہ (ایک قسم کے کھانے) کے ساتھ رسول اللہ ملنے کی یمن کی خدمت میں بھیجا جو انہوں نے آپ کے لیے بنایا تھا، وہ اسے آپ کے لیے مختص کرتے تھے، فرمایا: ”جاؤ! رسول اللہ صلی اللہ علیہ وسلم کو میرے پاس آنے کی دعوت دو، انہوں نے بیان کیا، میں آپ کی طرف چلا، پس جب رسول اللہ صلی اللہ علیہ وسلم نے میری طرف دیکھا جبکہ آپ ملنے کی تم اپنے اصحاب میں تھے تو آپ نے میری طرف نظر جمائے رکھی حتیٰ کہ تمام حضرات نے میری طرف دیکھا، پس میں شرمندہ سا ہوا، آپ نے فرمایا: ”ابوطلحہ نے ہمیں بلا بھیجا ہے؟ میں نے عرض کیا: جی ہاں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اٹھو۔“ وہ تمام حضرات آپ کے ساتھ اٹھ کھڑے ہوئے، میں تیز تیز چلتا ہوا سیدنا ابوطلحہ فی لینے کے پاس آیا اور انہیں خبر بتائی، وہ رسول اللہ کی خدمت میں آئے اور عرض کیا: اللہ کے رسول! میں نے آپ صلی اللہ علیہ وسلم کے لیے کچھ تیار کیا ہے، جو کہ ان کے لیے کافی نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ” ان شاء اللہ ان کے لیے کافی ہو جائے گا۔ پس رسول اللہ صلی اللہ علیہ وسلم اندر تشریف لائے اور برکت کی دعا فرمائی، پھر فرمایا: ”دس افراد کو اندر آنے کی اجازت دو“ دس اندر آئے، انہوں نے کھانا کھایا حتیٰ کہ وہ سب سیر ہو گئے، پھر جو بچ گیا تھا آپ صلی اللہ علیہ وسلم نے اسے لے کر اکٹھا کیا، پھر اس میں برکت کی دعا فرمائی اور وہ پہلی مقدار جتنا ہو گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ تم لے لو۔“ اس حدیث کو سعد بن سعید سے صرف یحیی بن سعید الاموی نے روایت کیا۔","",{"k":"صحیح بخاری (٣٥٧٨)، مسلم (٢٠٤٠)۔"}],[6486,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھیں دن کی نسبت زیادہ تر انتیس روزے رکھے ہیں۔“ اس حدیث کو الجریری سے صرف القاسم بن مالک نے روایت کیا۔ اس میں مجاہد بن موسی کا تفرد ہے۔ سیدنا ابو ہریرہ بنی اہلیہ سے صرف اسی اسناد سے مروی ہے۔ ٦٤٨٧","",{"k":"کی سنن ابن ماجه (١٦٥٨)، قال الشيخ الالباني: حسن صحيح۔"}],[6487,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” گویا کہ میں موسیٰ بن عمران کا نام کو اس وادی میں قطوان کی دو چادروں میں احرام باندھے ہوئے دیکھ رہا ہوں۔“ اس حدیث کو عاصم سے صرف زید بن ابی انیسہ نے اور زید سے صرف یزید ابن سنان نے روایت کیا۔ اس میں بیٹی بن سعد الاموی کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم نے سیدنا موسیٰ کا لینا کو حالت احرام میں دیکھا، اس کی دو ہی صورتیں ممکن ہیں، جس طرح وہ دنیاوی زندگی میں عبادت کرتے، حج کرتے اور تلبیہ کہتے تھے تمثیلی طور پر ان کو اسی شکل میں آپ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا یا (٢) آپ صلی اللہ علیہ وسلم نے اپنے خواب میں اسی طرح دیکھا تھا۔ واللہ اعلم","",{"k":"مجمع الزوائد ٢٢١٣، صحيح الجامع الصغير (٤٤٦٨)، مسند ابی یعلی (٥٠٩٣)، مجمع البحرين (١٧٥٥)، اسناده حسن۔"}],[6488,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نبی نے یمن کی خدمت میں دس میں سے دسویں کی حیثیت سے حاضر ہوا تو انصار میں سے ایک آدمی آیا، اس نے عرض کیا: اللہ کے نبی صلی اللہ علیہ وسلم لوگوں میں سے سب سے زیادہ دانا اور سب سے زیادہ دور اندیش شخص کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ان میں سے موت کو بہت زیادہ یاد کرنے والا اور موت آنے سے پہلے موت کی خوب تیاری کرنے والا، ایسے لوگ دانا ہیں، وہ دنیا کا شرف اور آخرت کی عزت پا گئے۔“ اس حدیث کو مالک بن مغول سے صرف یحیی بن سعید الاموی نے روایت کیا۔","",{"k":"مجمع الزوائد (٣٠٩/١٠)، ضعیف ترغیب و ترهیب (١٩٤٦)، مجمع البحرين (٥٠٧٧)۔"}],[6489,"سیدنا انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے اجر مجھ پر پیش کیے گئے حتی کہ وہ تنکا جسے آدمی مسجد سے نکال باہر کرتا ہے اور میری امت کے گناہ مجھے پر پیش کیے گئے۔ میں نے اس سے بڑا کوئی گناہ نہیں دیکھا کہ آدمی کو کوئی آیت یا کوئی سورت عطا کی گئی اور پھر اس نے اسے بھلا دیا۔ اس حدیث کو ابن جریج، عن الزہری، عن انس کی سند سے صرف عبد المجید نے روایت کیا۔ اس میں محمد بن یزید الآ دمی کا تفرد ہے اور محمد بن یزید نے اسے عبدالمجید، عن ابن جریج، عن المطلب، عن انس کی سند سے روایت کیا۔","",{"k":"سنن ابو داود (٤٦١)، سنن ترمذی (٢٩١٦)، قال الشيخ الالباني: ضعيف۔"}],[6490,"سیدنا عبد اللہ بن علیم نبی اللہ نے بیان کیا، رسول اللہ علیم کا خط ہمارے پاس آیا کہ تم مردار کی کھال سے","",{"k":"سنن ابو داود (٤١٢٧)، قال الشيخ الالباني: صحيح۔","f":"اٹھاؤ نہ پٹھوں سے۔ اس حدیث کو عبد الملک بن عمیر سے صرف المسعودی نے اور المسعودی سے صرف اسماعیل بن عمر نے روایت کیا۔ اس میں محمد بن منصور الطوسی کا تفرد ہے۔"}],[6491,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما بیان کرتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جو شخص ((سبحان الله والحمد لله ولا اله الا الله والله اکبر )) پڑھتا ہے، اس کے لیے ہر حرف کے بدلے دس نیکیاں لکھ دی جاتی ہیں اور جو ناحق جھگڑے میں مدد کرتا ہے وہ اللہ کی ناراضی میں رہتا ہے حتیٰ کہ وہ اس سے دست کش ہو جائے۔ جس کی شفاعت اللہ کی حدود میں سے کسی حد کے نفاذ میں رکاوٹ بن جائے اس نے اس کے معاملے میں اللہ کی مخالفت کی اور جس نے کسی مومن مرد یا کسی مومن عورت پر بہتان لگایا اللہ قیامت کے دن اسے خون اور پیپ کے کیچڑ میں رکھے گاحتیٰ کہ وہ اس میں سے (وہ عیب) نکالے جو اس نے کہا تھا جبکہ وہ اسے نکال نہ پائے گا۔ اس حدیث کو عطاء الخراسانی کے حوالے سے حمران سے صرف القاسم بن ابی بزہ نے اور القاسم بن ابی بزہ سے صرف فطر نے اور فطر سے صرف عمار بن رزیق نے روایت کیا۔ اس میں ابوالجواب کا تفرد ہے۔ (١) مذکورہ روایت کا پہلا حصہ ضعیف ہے۔ (کتب له بكل حرف عشر حسنات)) یہاں تک دیکھئے (سلسله ضعیفه: ٥١٣٣، ضعیف ترغیب و ترهیب، رقم: ٩٥٣) (٢) معلوم ہوا کہ شرعی حد روکنے کے لیے سفارش کرنا حرام ہے۔ جب کسی مجرم کا معاملہ عدالت میں پہنچ چکا ہو اور اس پر حد نافذ کرنے کا فیصلہ کیا جا چکا ہو تو کسی کو کوئی حق نہیں پہنچتا کہ وہ اس کی حد کے سامنے روڑے اٹکائے۔ (٣) اسی طرح اس جھگڑے کا بھی یہی معاملہ ہے جس کی بابت جھگڑنے والے کو پتہ ہو کہ وہ باطل پر ہے۔ لیکن پھر بھی اپنی انانیت کے دفاع کا بھوت سوار کر کے یا کسی اور مقصد کے پیش نظر لڑائی جاری رکھے۔ (٤) معلوم ہوا کہ اللہ ذوالجلال مومنوں کو عزتیں اور عظمتیں عطا کرتا ہے اور پھر ان کی حفاظت بھی کرتا ہے لیکن جو آدمی مومن کی تو ہین کرنے کے درپے ہو جائے تو وہ اپنے جرم کی نوعیت کے لیے اتنا ضرور ذہن نشین کرے کہ ایک آدمی کو اللہ ذوالجلال عزت دینا چاہتا ہے اور وہ اسے ذلیل کرنا چاہتا ہے۔","",{"k":"کر مجمع الزوائد (١٠/٩١)، مجمع البحرين (٤٥٤٢)، اسناده حسن۔"}],[6492,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں سیدنا بلال رضی اللہ عنہ سے ملا تو میں نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے کعبہ میں نماز پڑھی؟ انہوں نے کہا: آپ ملنے کی یتیم نے دوستونوں کے درمیان دورکعتیں پڑھیں اور درمیانے ستون کو اپنی دائیں جانب کیا۔ اس حدیث کو یحیی بن جعدہ سے صرف عکرمہ بن خالد نے اور عکرمہ سے صرف عمار بن رزیق نے روایت کیا۔ اس میں ابوالجواب کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ کعبہ شریف میں داخل ہونا اور نماز پڑھنا درست ہے (٢) کعبہ شریف میں داخل ہونا حج یا عمرے کا حصہ نہیں۔ رسول اللہ صلے علی یتم کعبہ شریف میں اس وقت داخل ہوئے تھے جب مکہ فتح ہوا تھا۔ (فتح الباری: حدیث نمبر ١٦٠١) سنن ابی داؤد میں ہے کہ ان دنوں کعبہ شریف کے اندر چھ ستون تھے (ابو داؤد، رقم: ٢٠٢٣) تین ایک قطار میں تھے اور تین دوسری قطار میں تھے۔ ٦٤٩٣","",{"k":"صحیح بخاری (٤٦٨)۔"}],[6493,"سیدنا عمران بن حصین رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں داغ دینے سے منع فرمایا۔ پس ہم نے داغ دیا تو ہم کامیاب و کامران نہ ہوئے۔“ اس حدیث کی اسناد میں الحسین اور عمران بن حصین کے درمیان یونس بن عبید سے روایت کرنے والوں میں صرف علی بن عاصم نے کسی راوی کو داخل کیا ہے۔ ایک دوسری حدیث میں ہے کہ سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ سیدنا سعد بن","",{"k":"سنن ابو داود (٣٨٦٥)، سنن ترمذی (٢٠٤٩)، سنن ابن ماجه (٣٤٩٠)، قال الشيخ الالباني (١٠١١)۔","f":"معاذ ضیا اللہ کو تیر لگنے کے باعث جو زخم آیا تھا تو نبی معظم ملنے سلیم نے اس کو داغ لگوایا تھا۔ (مسلم، کتاب السلام، رقم: ٢٢٠٨، ابو داؤد: ٣٨٦٦) علماء کہتے ہیں: کہ منع کا مطلب یہ ہے کہ جہاں تک ہو سکے اس سے پر ہیز کیا جائے اور علاج کے دوسرے طریقے آزمائے جائیں، اگر کوئی چارہ نہ رہے تو پھر داغنے کی اجازت ہے، جیسا کہ دوسری حدیث سے ثابت ہوتا ہے۔ ٦٤٩٤"}],[6494,"سیدنا عبد الله بن بسر اسلمی رضی اللہ عنہ سے روایت ہے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے مجھے دیکھا ہے وہ دجال کو دیکھ لے گا یا وہ میری وفات کے قریب ہو گا۔“ اس حدیث کو معاویہ بن صالح سے صرف معن نے روایت کیا۔","",{"k":"مجمع الزوائد (٧٣٥٠)، مجمع البحرين (٤٤٩٩)، اسناده حسن۔"}],[6495,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے پاس یہ آیت: نه ده ”لوگو! زمین میں سے حلال پاکیزہ چیزیں کھاؤ تلاوت کی گئی تو سیدنا سعد بن ابی وقاص نبی الیہ کھڑے ہوئے اور عرض کیا: اللہ کے رسول! اللہ سے دعا فرمائیں کہ وہ مجھے مستجاب الدعوہ بنا دے تو نبی سے ہم نے انہیں فرمایا: سعد! اپنا کھانا پاکیزہ بنا لے تم مستجاب الدعوہ بن جاؤ گے۔ اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! وہ بندہ جو اپنے پیٹ میں حرام کا لقمہ داخل کرتا ہے اس کے چالیس روز کے عمل قبول نہیں کیے جاتے اور جس بندے کا گوشت حرام اور سود سے تیار ہوا ہو تو آگ اس کی زیادہ حق دار ہے۔“ یہ حدیث ابن جریج سے صرف اس اسناد سے مروی ہے۔ اس میں الاحتیاطی کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٠/٢٩١)، ضعیف ترغیب و ترهیب (١٠٧١)، سلسله ضعیفه (١٨١٢)، مجمع البحرين (٥٠٢٦)۔"}],[6496,"سیدہ عائشہ منی شن جا نے بیان کیا، ڈیڑھ ماہ گزر جاتا اور ہم رسول اللہ صلی اللہ علیہ وسلم کے گھر میں روشنی کے لیے آگ جلاتے تھے نہ کسی اور مقصد کے لیے۔ میں نے کہا: سبحان اللہ! آپ کس چیز کے سہارے زندہ رہتے تھے؟ انہوں نے فرمایا: پانی اور کھجور کے ذریعے، انصار ہمارے ہم سائے تھے، ان کے دودھ دینے والے جانور تھے، وہ ہمیں کبھی دودھ کا ہدیہ بھیج دیتے تھے۔ اس حدیث کو ابن عجلان، عن القعقاع، عن ابی صالح، عن ابی ہریرہ، عن عائشہ کی سند سے صرف بکر بن صدقہ نے روایت کیا۔ اس میں المنکد ری کا تفرد ہے۔ان کے علاوہ دیگر محدثین نے اسے بکر بن صدقہ، عن ابن عجلان عن القعقاع عن القاسم عن عائشہ کی سند سے روایت کیا ہے۔ مذکورہ حدیث میں نبی معظم صلی اللہ علیہ وسلم کے زہد استغنا، قناعت اور سادگی کا بیان ہے۔ نبی","",{"k":"صحیح بخاری (٢٥٦٧)۔","f":"الے علم کی حیات مبارکہ کے آخری سالوں میں رسول اللہ علیم کے سال بھر کے خرچ کے لیے کھجور میں اور جو وغیرہ اکٹھے دینا شروع کر دیے تھے، لیکن امہات المؤمنین سخاوت سے کام لیتے ہوئے جلد ہی خرچ کر دیتی تھیں۔ اس لیے اکثر روٹی، سالن اور گوشت وغیرہ کے بغیر گزارہ تھا، بعض اوقات کھجوریں بھی میسر نہ ہوتی تھیں۔"}],[6497,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی لئے علیم نے فرمایا: ”جنت میں حوریں گیت گاتی ہیں اور کہتی ہیں: ہم خوبصورت حوریں معزز ازواج کے لیے ہدیہ ہیں۔“ اس حدیث کو ابن ابی ذئب سے صرف ابن ابی فدیک نے روایت کیا۔ اس میں المنکدری کا تفرد ہے۔: ٦٤٩٨ مذکورہ حدیث سے معلوم ہوا کہ جنتی حوریں جنت میں نغمہ پڑھیں گی۔","",{"k":"مجمع الزوائد (١٠/٤١٩)، سلسله صحيحة (٣٠٠٢)، مجمع البحرين (٤٨٨٧)۔"}],[6498,"سیدنا عبد اللہ ابن عباس والی تنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”نفاس اور حیض والی عورت غسل کر کے احرام باندھے، وہ بیت اللہ کے طواف کے سوا تمام مناسک ادا کرے، اور جب پاک، صاف ہو جائے تو پھر بیت اللہ کا طواف کرے۔ اس حدیث کو خصیف سے صرف مروان بن شجاع نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ حائضہ اور نفاس والی عورت احرام باندھ سکتی ہے۔ تلبیہ پکارے اور تسبیحات استغفار اور اذکار میں مشغول رہے۔ لیکن بیت اللہ کے طواف کے علاوہ باقی ارکان ادا کرے اور جب حیض و نفاس سے پاک ہو جائے تو پھر طواف کرے۔:٦٤٩٩ ثنا","",{"k":"سنن ترمذی (٩٤٥)، سنن ابو داود (١٧٤٤)، قال الشيخ الالباني: صحيح۔"}],[6499,"سیدنا عبد اللہ بن عمر ضیا الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو میراث دور جاہلیت میں تقسیم کر دی گئی تو وہ جاہلیت کی تقسیم پر ہے اور جو میراث اسلام آ جانے پر تقسیم نہ ہوئی ہو تو وہ اسلام کی تقسیم پر ہوگی۔ اس حدیث کو نافع سے صرف عقیل نے اور عقیل سے صرف ابن لہیعہ نے روایت کیا۔ اس میں محمد بن رمح کا تفرد ہے۔ جو کام اسلام قبول کرنے سے پہلے خلاف اسلام کے گئے ہوں، اسلام لانے سے وہ معاف ہو جاتے ہیں۔ البتہ اگر ان کی اصلاح ممکن ہو تو اصلاح ضروری ہے، مثلاً اگر کسی کے نکاح میں دوعورتیں تھیں جو آپس میں بہنیں تھیں اسلام قبول کرنے سے پہلے ان سے اولاد ہوئی وہ جائز اولا د شمار ہو گی لیکن اسلام قبول کرنے کے بعد ان میں سے ایک کو طلاق دینا ضروری ہوگا۔","",{"k":"سنن ابن ماجه (٢٧٤٩)، قال الشيخ الالباني: صحيح۔"}],[6500,"سیدنا عبد اللہ بن الحارث بن جزء الزبیدی ضیا اللہ نے بیان کیا، میں پہلا شخص ہوں جس نے رسول اللہ علیم کو فرماتے ہوئے سنا: \"تم میں سے کوئی قبلہ کی سمت پیشاب نہ کرے۔“ اور میں پہلا شخص ہوں جس نے اسے لوگوں کو بیان کیا۔ اس حدیث کو الحسن بن ثوبان سے صرف رشدین نے روایت کیا۔ ان مذکورہ حدیث سے معلوم ہوا کہ پیشاب پاخانے کے وقت قبلہ کی طرف منہ نہیں کرنا: ٦٥٠١ چاہیے۔ اس سے معلوم ہوتا ہے کہ یہ پابندی کھلے مقام کے لیے ہے، چار دیواری میں نہیں ہے۔","",{"k":"سنن ابن ماجه (٣١٧)، قال الشيخ الالباني: صحيح۔"}],[6501,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، کچھ لوگ ان کی عیادت کے لیے ان کے ہاں آئے تو انہوں نے کہا: لونڈی! ہمارے ساتھیوں کے لیے کچھ لاؤ خواہ خشک کھجور ہی ہو۔ کیونکہ میں نے رسول اللہ علم کو فرماتے ہوئے سنا: ”اچھے اخلاق جنتی اعمال میں سے ہیں۔‘“ اس حدیث کو حمید سے صرف بیٹی بن ایوب نے اور بیٹی سے صرف طلق بن اسح نے روایت کیا۔ اس میں عبد الرحمن بن عبد اللہ بن عبد الحکم کا تفرد ہے۔ ٦٥٠٢","",{"k":"٢٩٢٥ مجمع الزوائد (١٢٨٠)، مجمع البحرين (٢٩٢٥)۔"}],[6502,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب آدم عالسلام سے وہ لغزش ہوئی تو انہوں نے عرش کی طرف سر اٹھایا تو کہا: میں محمد کے صدقے تجھ سے سوال کرتا ہوں تو مجھے بخش دے۔ پس اللہ نے ان کی طرف وحی کی۔ محمد ( لئے علیم ) کیا ہیں؟ اور محمد ( تعلیم ) کون ہیں؟ فرمایا: بابرکت ہے نام تیرا، جب تم نے مجھے پیدا فرمایا: میں نے اپنا سر آسمان کی طرف اٹھایا تو وہاں ((لا الہ الا الله محمد رسول اللہ لکھا ہوا تھا۔ پس میں نے جان لیا کہ تو نے جس کے نام کو اپنے نام کے ساتھ ملایا ہے اس سے بڑھ کر تیرے ہاں کسی کی قدر و منزلت نہیں۔ پس اللہ نے ان کی طرف وحی کی: اے آدم! وہ آپ کی اولاد میں سے آخری نبی ہیں۔ ان کی امت آپ کی اولاد میں سے آخری امت ہے۔ آدم اگر وہ نہ ہوتے تو میں آپ کو پیدا نہ کرتا۔“ اس حدیث کو زید بن اسلم سے صرف اس کے بیٹے عبد الرحمن نے اور اس کے بیٹے سے: صرف عبداللہ بن اسماعیل المدنی نے روایت کیا اور سیدنا عمر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٢٥٣/٨)، مجمع البحرين (٣٥١٨)، مستدرك حاكم ٢/ ٦٧٢، سلسة ضعيفه (٢٥)، موضوع۔"}],[6503,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے اجازت دی گئی کہ میں حاملین عرش میں سے ایک فرشتے کے متعلق بتاؤں،اس کے پاؤں نچلی زمین میں ہیں،اس کے سینگ پر عرش ہے، اس کے کان کے نچلے سرے سے لے کر اس کے کندھے تک پرندے کی سات سو سال کی پرواز جتنا فاصلہ ہے۔ وہ فرشتہ کہتا ہے: تو جہاں بھی ہو تو پاک ہے۔ اس حدیث کو محمد بن المنکدر کے حوالے سے انس بن مالک سے اس کے بیٹے منکدر نے روایت کیا۔ اس میں اس کے بیٹے کا تفرد ہے اور ابراہیم بن طہمان نے اسے موسی بن عقبہ عن محمد بن المنکد رعن جابر کی سند سے روایت کیا ہے۔ ٦٥٠٤","",{"k":"مجمع الزوائد (١/٨٠، ٤٤٢١)، مجمع البحرين (٦٧)، اسناده ضعيف . ٦١۔"}],[6504,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے رسول اللہ نے تم کو فرماتے ہوئے سنا: ”جس گھرانے سے کوئی فوت ہو جاتا ہے اور وہ اس کی موت کے بعد اس کی طرف سے صدقہ کرتے ہیں تو جبریل عالی سلام اسے نور کے طبق میں اس کی طرف ہدیہ کرتے ہیں۔ پھر قبر کے کنارے کھڑے ہو کر کہتے ہیں: گہری قبر والے! یہ ہدیہ تیرے گھر والوں نے تیری طرف ہدیہ کیا ہے پس تو اسے قبول کر، پس وہ اس کے پاس غمگد جاتا ہے، وہ اس سے خوش ہوتا ہے اور اس کے وہ پڑوسی بڑے نمکین ہوتے ہیں جنہیں کوئی چیز ہدیہ نہیں کی جاتی۔“ یہ حدیث سیدنا انس ویلا لینے سے صرف اس اسناد سے مروی ہے۔ اس میں ابن ابی فر یک کا تفرد ہے۔","",{"k":"مجمع البحرين (١٤٦١)، سلسله ضعيفه (٤٨٦)، قال الشيخ الالباني: موضوع۔"}],[6505,"سیدنا عبد المجید بن ابی عبس بن جبر نے اپنے والد سے، انہوں نے اس کے دادا سے روایت کیا کہ رسول اللہ صلی علی ایم نے فرمایا: ” احد یہ ایک پہاڑ ہے وہ ہم سے محبت کرتا ہے اور ہم اس سے محبت کرتے ہیں، وہ جنت کے دروازوں میں سے ایک دروازے پر ہے اور یہ غیر ( پہاڑ) ہے وہ ہم سے بغض رکھتا ہے اور ہم اس سے بغض رکھتے ہیں اور یہ جہنم کے دروازوں میں سے ایک دروازے پر ہے۔“ یہ حدیث ابوعبس بن جریر سے صرف اس اسناد سے مروی ہے۔ اس میں ابن ابی فدیک کا تفرد ہے۔","",{"k":"مجمع الزوائد (١٣/٤)، ضعيف الجامع الصغير (١٨٨)، مجمع البحرين (١٨٣٢)، اسناده ضعيف . ٦٥٠٦۔"}],[6506,"سیدنا ابو ہریرہ ضیا المیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے سیدنا ابراہیم علینا کی طرف وحی کہ میرے خلیل! اپنا اخلاق بہتر کر، خواہ کفار کے ساتھ ہو تم ابرار کی جگہ (جنت میں ) داخل ہو جاؤ گے، بے شک میری بات اس شخص کے لیے سبقت لے گئی ہے کہ جس کے اخلاق اچھے ہوں گے میں اسے اپنے عرش تلے سایہ دوں گا، اسے بہشت سے جام پلاؤں گا اور اسے اپنا قرب و پڑوس عطا کروں گا۔ اس حدیث کو سعید المقبری سے صرف ابو امیہ بن یعلی نے روایت کیا۔ اس میں مؤمل بن عبد الرحمن کا تفرد ہے اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ ٦٥٠٧","",{"k":"مجمع الزوائد (٢٠/٨)، سلسله ضعیفه (٣٣٤١)، ضعیف ترغیب و ترهيب (١٥٩٩)، مجمع البحرين (٢٩٨٣)، اسناده ضعيف۔"}],[6507,"سیدنا ابو ہریرہ ضیا المیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” دینار اور درہم اللہ کی زمین پر مہریں ہیں، جو اس کے مولا کی مہر لائے گا میں اس کی حاجت پوری کر دوں گا۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٤/٦٥)، ضعيف الجامع الصغير (٣٠٠٨)، مجمع البحرین اسناده ضعيف . ٦٥٠٨۔"}],[6508,"سیدنا معقل بن یسار رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم فرمایا کہ میں اپنی قوم کے درمیان فیصلہ کروں۔ میں نے عرض کیا: میں اچھی طرح فیصلہ نہیں کر سکتا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ان کے درمیان فیصلہ کر، کیونکہ اللہ قاضی کے ساتھ ہوتا ہے جب تک وہ عمداً نا انصافی نہ کرے۔“ یہ حدیث سیدنا معقل بن یسار رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابراہیم الصائغ کا تفرد ہے۔ ابو خالد الضمی جس سے ابراہیم الصائغ نے یہ حدیث روایت کی، وہ محمد بن خالد الضمی ہیں اور ابو داود نفیع بن الحارث ہیں۔ ٦٥٠٩","",{"k":"مجمع الزوائد (١٩٣/٤)، مجمع البحرين (٢١٤٠)، مسند احمد: ٢٦/٥ سلسله ضعيفه (٢٨٦٦)، ضعيف الجامع (١٦٦٣)۔"}],[6509,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو کوئی بات بیان کرے اور اس کے پاس چھینک مار دے تو وہ حق ہے۔ اس حدیث کو ابو الزناد سے صرف معاویہ بن بیٹی نے روایت کیا، اس میں بقیہ کا تفرد ہے اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ ٦٥١٠","",{"k":"مجمع الزوائد (٥٩/٨)، سلسله ضعيفه (١٣٦)، ضعيف الجامع الصغير (٥٥٥٦)، مجمع البحرين (٣٠٦٠)، قال الشيخ الالباني: موضوع۔"}],[6510,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، رسول اللہ صل علی نے فرمایا: قیامت کا دن ہو گا، اعلان کرنے والا اعلان کرے گا، اللہ کی مخالفت کرنے والے کھڑے ہوں، سن لو! وہ قدریہ ہیں۔ یہ حدیث سیدنا عمر نبی الیہ سے صرف اس اسناد سے مروی ہے۔ اس میں بقیہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٦/٧)، ضعيف الجامع الصغير (٦٦٣)، سلسله ضعيفه (٢٥٨٢)، مجمع البحرين (٣٢٧١)۔"}],[6511,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: قیامت کے دن جہنمی صف در صف پیش کیے جائیں گے۔ پس مؤمن ان کے پاس سے گزریں گے تو جہنمی شخص ایک مومن شخص کو دیکھے گا جسے اس نے دنیا میں پہچانا ہو گا تو وہ کہے گا: اے فلاں! کیا تجھے وہ دن یاد ہے کہ تم نے فلاں اور فلاں کام کے لیے مجھ سے مدد طلب کی تھی؟ اور وہ اسے کہے گا: کیا تجھے یاد ہے کہ میں نے تجھے فلاں اور فلاں چیز عطا کی تھی؟ پس مومن اسے یاد کرے گا تو وہ اس کے لیے اپنے رب سے سفارش کرے گا تو اس کے متعلق اس کی سفارش قبول کی جائے گی۔ اس حدیث کو اعمش سے صرف یوسف بن خالد اسمتی نے روایت کیا۔","",{"k":"کر مجمع الزوائد (٣٨٢/١٠)، مجمع البحرین (٤٨٢٨)، ابن ماجه (٣٦٨٥)، قال الشيخ الالباني: ضعيف۔"}],[6512,"سیدنا ابو سعید خدری نبیلہ سے روایت ہے کہ رسول اللہ ٹیم نے فرمایا: \"جو شخص اللہ کی راہ میں ایک دن روزہ رکھتا ہے، اللہ اسے جہنم سے ستر سال کی مسافت کے برابر دور کر دیتا ہے، جو شخص سرحد پر پہرہ دیتے ہوئے فوت ہو جاتا ہے، وہ قبر کے فتنے سے بچال یا جاتا ہے اور اس پر اس کا رزق جاری رہتا ہے۔“ اس حدیث کو ابوسعید المقبری سے صرف زہرہ بن معبد نے روایت کیا۔ اس میں رشدین کا تفرد ہے۔","",{"k":"٦٥١٣ م مجمع الزوائد (٥/٢٨٩)، مجمع البحرين (٢٦٣٨)، اسناده ضعيف۔"}],[6513,"سهل بن رافع بن خدیج نے اپنے والد سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم اس کے پاس سے گزرے تو آپ نے اسے آواز دی، وہ آپ کے پاس آئے اور آپ کے ساتھ چلے حتیٰ کہ مسجد میں آگئے، پھر وہ واپس گئے اور غسل کیا، پھر لوٹے تو نبی لئے علیم نے اسے دیکھا اس پر غسل کے نشانات تھے۔ نبی صلی اللہ علیہ وسلم نے ان سے غسل کا سبب پوچھا: تو انہوں نے کہا: میں نے آپ کی آواز سنی جبکہ میں اپنی اہلیہ سے جماع کر رہا تھا۔ پس میں فارغ ہونے سے پہلے اٹھ کھڑا ہوا، اس لیے میں نے غسل کیا۔ نبی ملنے صلی اللہ علیہ وسلم نے فرمایا: ”پانی (غسل) پانی (منی کے نکلنے) سے ہے۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کے بعد فرمایا: ” جب دونوں شرم گاہیں مل جائیں (اور انزال نہ بھی ہو ) تو غسل واجب ہو جاتا ہے۔ اس حدیث کو سہل بن رافع سے صرف موسی بن ایوب نے روایت کیا۔ اس میں رشدین کا تفرد ہے۔ Duckie","",{"k":"مجمع الزوائد (٢٦٦/١)، مجمع البحرين (٤٨٠)، اسناده ضعيف۔"}],[6514,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کی وفات کا وقت قریب آیا تو آپ ملے علی ام ہاتھ پھیلائے ہوئے یوں فرما رہے تھے: ” جبریل ( ایلام )! تم کہاں ہو؟“ پھر آپ صلے عدیم ہاتھ سمیٹ لیتے اور پھر انہیں پھیلاتے، آپ ملٹے علی تیم نے کئی بار ایسے کیا اور آپ صلی اللہ علیہ وسلم فرماتے تھے، ” جبریل! اپنے رب کے ہاں میری سفارش کر کہ وہ مجھ پر موت کو آسان کر دے۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے ذکر کیا کہ انہوں نے سیدہ عائشہ بنی انا کو فرماتے ہوئے سنا: میں نے جبریل عالی نام سے وہ کچھ سنا جو کسی اور کان نے نہیں سنا اور وہ کہہ رہے تھے: ”لبیک میں حاضر ہوں )۔ یہ حدیث سیدنا ابو ہریرہ رضی اللہ عنہ عن عائشہ ربنی اشیا سے صرف اس اسناد سے مروی ہے۔ اس میں ابوالطاہر بن السرح کا تفرد ہے۔ ٦٥١٥","",{"k":"الله مجمع الزوائد (٣٥/٩)، مجمع البحرين (١٢٣١)، اسناده ضعیف۔"}],[6515,"نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام سلمہ بنی اینجا سے روایت ہے کہ انہوں نے رسول اللہ علم کو فرماتے ہوئے سنا: \"جو شخص مسجد اقصیٰ سے مسجد حرام تک حج وعمرہ کا تلبیہ پکارتا ہے اس کے اگلے پچھلے تمام گناہ بخش دیے جاتے ہیں اور اس کے لیے جنت واجب ہو جاتی ہے۔“ یہ حدیث سیدہ ام سلمہ بنی النیہا سے صرف اس اسناد سے مروی ہے۔ اس میں ابن ابی فدیک کا تفرد ہے۔ ٦٥١٦","",{"k":"سنن ابو داود (١٧٤١)، سنن ابن ماجه (٣٠٠٢)، ضعيف الجامع الصغير (٥٤٩٣)، قال الشيخ الالباني: ضعيف۔"}],[6516,"سیدنا ابو بکر عبد اللہ بن صالح الہاشمی نے بیان کیا، میں نے اپنے والد کو اپنے والد سے بیان کرتے ہوئے سنا، انہوں نے کہا: میں نے سیدنا انس بن مالک رضی اللہ عنہ کے پیچھے ایک نماز پڑھی، اس میں وہ بھول گئے تو انہوں نے سلام پھیرنے کے بعد سجدہ ( سہو) کیا پھر ہماری طرف متوجہ ہو کر فرمایا: سن لو! میں نے اسی طرح کیا ہے جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے ہوئے دیکھا ہے۔“ اس حدیث کو صالح بن علی بن عبد اللہ بن عباس سے صرف ان کے بیٹے نے روایت کیا۔ اس میں ابوالطاہر بن السرح کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام بینی نسیم کا عمل نبی مکرم مالے علم کی سنت کے مطابق ہوتا تھا۔ ایک مسلمان محبت رسول کے لیے بھی یہ ہونا چاہیے کہ نبی معظم صلی اللہ علیہ وسلم کی سنت کے مطابق اپنی زندگی بسر کرے۔ (٢) مذکورہ حدیث سے یہ بھی معلوم ہوا کہ سجدہ سہو سیدنا انس رضی اللہ عنہ نے سلام پھیر نے کے بعد کیا اور دوسری احادیث جو پیچھے گزر چکی ہیں ان میں سلام سے پہلے سجدہ سہو نبی معظم صلی اللہ علیہ وسلم سے ثابت ہے۔ اس مسئلہ میں فقہا میں اختلاف ہے۔ احناف کا کہنا ہے کہ ہر سہو کا سجدہ سلام کے بعد ہی کیا جائے گا۔ امام شافعی رحمہ اللہ نے کہا: ہے کہ تمام سجدے سلام سے پہلے کیے جائیں گے۔ امام مالک ہمالہ نے کہا ہے: کہ نماز میں زیادتی کی صورت میں سلام کے بعد اور کمی کی صورت میں سلام سے پہلے کیے جائیں گے۔ امام احمد اللہ نے یہ موقف اپنایا ہے کہ سجدہ سہو کے متعلق جو کچھ احادیث میں وارد ہے اسی پر عمل کیا جائے گا اور جس صورت کے متعلق کچھ بھی وارد نہیں، اس میں سلام سے پہلے سجدے کیے جائیں گے۔ امام احمد ہمالہ کا موقف زیادہ راجح معلوم ہوتا ہے۔","",{"k":"معجم صغیر طبرانی (٤٣٧)۔"}],[6517,"سیدنا ابو قراد السلمی بیا اللہ نے بیان کیا، ہم رسول اللہ نے ان کے پاس تھے تو آپ نے پانی منگایا اور اس میں اپنا ہاتھ ڈبویا، پھر وضو کیا، ہم نے اسے تلاش کیا اور اسے گھونٹ گھونٹ پیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم نے جو کیا اس پر کس چیز نے تمہیں آمادہ کیا ہم نے عرض کیا: اللہ اور اس کے رسول صلے علم کی محبت نے، آپ ملل علیم نے فرمایا: ”اگر تم چاہتے ہو کہ اللہ اور اس کے رسول ملے تم تم سے محبت کریں تو جب تمہارے پاس امانت رکھی جائے تو اسے ادا کرو، جب تم بات کرو تو سچ بولو اور جو تمہارا ہم سایہ بنے اس کے ساتھ اچھی ہم سا ئیگی اپناؤ۔ یہ حدیث ابوقراد سے صرف اس اسناد سے مرد ہے۔ اس میں عبید بن واقد کا تفرد ہے۔ مذکورہ روایت ضعیف ہے۔ اس میں عبید بن واقد قیسی ضعیف ہے۔ تاہم حدیث کا دوسرا حصہ صحیح ہے۔ (دیکھئے:صحیح ترغیب و ترھیب: ٢٩٢٨) ورہ ٦٥١٨","",{"k":"مجمع الزوائد (٤/١٤٥)، صحیح ترغیب و ترهیب (٢٩٢٨)، مجمع البحرين (٢٠٩٠)۔"}],[6518,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو اپنے بھائی کو روٹی کھلاتا ہے حتی کہ اسے شکم سیر کر دیتا ہے اور اسے پلاتا ہے حتی کہ اسے سیراب کر دیتا ہے اللہ اسے جہنم سے سات خندق دور کر دیتا ہے۔ یہ حدیث عبد اللہ بن عمرو رضی اللہ عنہما سے صرف اس اسناد سے مروی ہے۔ اس میں: ادرلیس بن بیٹی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/١٣٠)، سلسله ضعیفه (٧٠)، مجمع البحرین (١٤٥٤)، ضعیف ترغیب و ترهیب (٥٥٣)، قال الشيخ الالبانى موضوع۔"}],[6519,"سیدنا عبد اللہ بن واقد بنی یہ بیان کرتے ہیں: خون (قتل) میں قسم رسول اللہ ملت علی ایم کے دور میں بھی تھی۔ یہ حدیث عبد اللہ بن واقد سے صرف اس اسناد سے مروی ہے۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٩١٦)، مجمع البحرين (٢٤٧٩)۔","f":"انون مذکورہ روایت میں عبد الملک بن ساریہ راوی ہے جس کے متعلق حافظ بیٹمی واللہ فرماتے ہیں: لم اجدہ۔ دیکھئے (مجمع الزوائد: ٢٩١/٦) تاہم خون کے مقدمے میں دوسری صحیح احادیث سے قسامت ثابت ہوتی ہے۔ دیکھئے: (صحیح بخاری، رقم: ٣١٧٣، ٧١٩٢، مسلم، رقم: ابو داؤد، رقم::٦٥٢٠ ٤٥٢٠) جمہورصحابہ و تابعین اس کے مشروع ہونے کے قائل ہیں۔ دیکھئے (نیل الاوطار: ٤٧٤/٤)"}],[6520,"سیدنا جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نے ایک عورت سے زنا کیا تو نبی سے ہم نے اس کے متعلق حکم فرمایا: تو اسے کوڑے مارے گئے . [ پھر آپ صلی اللہ علیہ وسلم کو بتایا گیا کہ وہ تو شادی شدہ ہے تو پھر آپ صلی اللہ علیہ وسلم نے حکم فرمایا تو اسے رجم کیا گیا۔ اس حدیث کو ابن جریج سے صرف ابن وہب نے روایت کیا۔ .٦","",{"k":"سنن ابو داود (٤٤٣٨، ٤٤٣٠)، قال الشيخ الالبانی: ضعیف الاسناد۔"}],[6521,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، ہم رسول اللہ مالٹے علیم کے ساتھ تھے، ہم کچھ نہیں جانتے تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر جلسے ( تشہد ) میں یہ دعا پڑھو: تمام قولی، بدنی اور مالی عبادتیں اللہ کے لیے ہیں، اے نبی! آپ پر سلام ہو، ہم پر اور اللہ کے صالح بندوں پر سلامتی ہو، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور اس کے رسول ہیں۔“ اس حدیث کو ابو اسحاق کے حوالے سے علقمہ سے صرف زید بن ابی انیسہ نے اور زید بن ابی انیسہ سے صرف عمرو بن الحارث نے روایت کیا، اس میں ابن وہب کا تفرد ہے۔","",{"k":"صحیح بخاری (٨٣٥)، مسلم (٤٠٢)۔"}],[6522,"سیدنا انس بن مالک الانصاری رضی اللہ عنہ نے بیان کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا کہ ان کی سواری انہیں لے کر ثنیہ سے اتری، جبکہ رسول اللہ صلی اللہ علیہ وسلم اکیلے چل رہے تھے۔ پس جب آسان راستے میں آئے تو آپ صلی اللہ علیہ وسلم ہنس دیے اور اللہ اکبر کہا: پس آپ صلی اللہ علیہ وسلم کے اللہ اکبر کہنے پر ہم نے بھی اللہ اکبر کہا: پھر ہم آپ صلی اللہ علیہ وسلم کے پاس پہنچ گئے تو لوگوں نے عرض کیا: اللہ کے رسول! ہم نے آپ صلی اللہ علیہ وسلم کے تکبیر کہنے پر اللہ اکبر کہا، جبکہ ہم یہ نہیں جانتے کہ آپ ملے لی ایم کس لیے ہنسے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: سیدنا جبریل عالینام میری اونٹنی کے آگے آگے تھے، جب سہل وادی میں اترے تو انہوں نے میری طرف توجہ کر کے فرمایا: خوش ہو جائیں اور اپنی امت کو بھی بشارت سنائیں کہ جس نے اقرار کر لیا کہ اللہ کے سوا کوئی معبود نہیں، وہ یکتا ہے اس کا کوئی شریک نہیں وہ جنت میں داخل ہو گا اور اللہ تعالیٰ نے اس پر جہنم کو حرام قرار دیا۔ پس میں ہنس دیا اور اللہ اکبر کہا، پس میں اس وجہ سے اپنی امت کے لیے خوش ہوا۔‘ اس حدیث کو زہری سے صرف عقیل نے اور عقیل سے صرف اسامہ بن روح نے روایت کیا۔ اس میں ابوالطاہر کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/٢٢)، مجمع البحرين (١٨)۔"}],[6523,"سیدنا عبداللہ ابن عمرنا اللہ نے بیان کیا، نبی صلی اللہ علیہ وسلم کی انگوٹھی مکمل طور پر چاندی کی تھی، پھر وہ سیدنا ابو بکر نبی الیہ کے پاس تھی، پھر سیدنا عمر نبی الیہ کے پاس تھی، پھر جب تک اللہ نے چاہا،سیدنا عثمان بنی اللہ کے پاس تھی، پھر عثمان رضی اللہ عنہ کے پاس سے گم ہو گئی۔ اس حدیث کو جابر سے صرف ابراہیم بن طہمان نے روایت کیا۔ اس میں معن بن عیسی کا تفرد ہے۔: صحیح بخاری میں ہے کہ وہ سیدنا عثمان خیا لینے سے ارلیس کے کنویں میں گری (اس کنویں میں انگوٹھی کو تلاش کیا گیا، لیکن وہ نہ مل سکی ) مزید دیکھئے: حدیث و","",{"k":"صحیح بخاری (٥٨٧٣)، مسلم (٩١/٥٤)۔","f":"نمبر ٢٤٣٨، ٦٥٢٤"}],[6524,"سعيد بن نافع نے بیان کیا، نبی صلی اللہ علیہ وسلم کے صحابی سیدنا ابو بشیر انصاری رضی اللہ عنہ نے مجھے دیکھا جبکہ میں سورج طلوع ہو جانے کے وقت نماز چاشت پڑھ رہا تھا۔ انہوں نے مجھ پر نکتہ چینی کی اور مجھے منع کیا۔ پھر کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم نماز نہ پڑھو حتی کہ سورج بلند ہو جائے، کیونکہ وہ شیطان کے سینگ سے طلوع ہوتا ہے۔“ اس حدیث کو بکیر بن عبد اللہ سے صرف اس کے بیٹے محترمہ نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے اور ابو بشیر سے صرف اس اسناد سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ سورج طلوع ہونے کے بعد کچھ دیر ٹھہر کر نماز اشراق ادا کرنی چاہیے تا کہ سورج بلند ہو جائے۔ ٦٥٢٥","",{"k":"مجمع الزوائد (٢/٢٢٦)، مسند احمد (٥/٢١٦)، مسند ابی یعلی (١٥٧٢)، مجمع البحرين (١٠٤٧)۔"}],[6525,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک آدمی رسول اللہ ملل علیم کے پاس آیا، اس نے وضو کیا اور اس نے اپنے پاؤں پر ناخن برابر جگہ چھوڑ دی تو رسول اللہ علیم نے اسے فرمایا: واپس جا اور اچھی طرح وضو کر۔“ اس حدیث کو قتادہ سے صرف جریر بن حازم نے روایت کیا۔ اس میں ابن","",{"k":"سنن ابو داود (١٣)، صحیح مسلم (٢٤٣)۔","f":"وہب کا تفرد ہے۔ ایک دوسری حدیث میں ہے کہ نبی مکرم ملل علیم نے ایک آدمی کی ایڑیوں میں خشک جگہ کر کہا کہ ان ایڑیوں کو آگ چھوئے گی۔ (ابو داؤد: ٩٧، صحیح الجامع الصغير، رقم: ١٢٤) معلوم ہوا کہ تمام اعضائے وضوء کو مکمل طور پر دھونا واجب ہے۔ اگر کسی ایک عضو کا کچھ حصہ خشک رہ گیا تو وضو مکمل نہیں ہو گا، جمہور اہل علم اسی کے قائل ہیں۔ مذکورہ بالا حدیث سے یہ بھی ثابت ہوا کہ وضو میں موالاۃ ( یعنی پے در پے اعضا دھونا ) واجب ہے، اگر ایسا نہ ہوتا تو آپ ملے عام اسے صرف پاؤں دھونے کا ہی حکم فرما دیتے۔ انہی احادیث کی روشنی میں ہی اہل سنت اور مجتہدین امت نے بالاتفاق پاؤں کے دھونے کو فرض قرار دیا۔ جو لوگ پاؤں کے دھونے کو فرض قرار نہیں دیتے اور مسح کے قائل ہیں، ان احادیث سے ان کے نظریے کی تردید ہوتی ہے۔ ٦٥٢٦"}],[6526,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے مسواک لازم کر لی حتی کہ مجھے اندیشہ ہوا کہ وہ میرے دانت نہ گرا دے۔“ یہ حدیث سیدہ عائشہ فی النھا سے صرف اس اسناد سے مروی ہے۔ اس میں ابن وہب کا تفرد ہے۔ اند اس میں راوی محمد بن رزیق بن جامع المصری ہے جس کے متعلق علامہ ہیثمی جراللہ","",{"k":"مجم اوسط طبرانی مو ابْنُ وَهْبٍ . ٧٨١ مجمع الزوائد ٢/ ٩٩، سنن کبری بیهقی (٤٩/٧)، مجمع البحرين، رقم۔","f":"فرماتے ہیں کہ لم اجدہ۔"}],[6527,"سیدنا ابو ہریرہ بیا نیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ اس امت کے لیے ہر سو سال پر ایک شخص کو مبعوث فرمائے گا جو اس کے لیے اس کے دین کی تجدید کرے گا۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"سنن ابو داود (٤٢٩١)، صحيح الجامع الصغير (١٨٧٤)، قال الشيخ الالباني: صحيح۔","f":"مذکورہ حدیث سے مقصود یہ ہے کہ ہر صدی کے اختتام پر ایسے اہل علم انسان ہوں گے جو کتاب وسنت کا احیا اور شرک و بدعت کا استیصال کریں گے، امت مسلمہ کے مجدد بصورت تبلیغ یا تالیف کتب یا بصورت تدریس الکتاب والسنہ کوشاں رہیں گے۔ ضروری نہیں کہ ایک وقت میں ایک ہی مجدد ہو بلکہ متعدد بھی ہو سکتے ہیں۔ (عون المعبود: ٤ / ١٧٨)"}],[6528,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ارادہ فرمایا کہ وہ عجمی بادشاہوں کے نام خطوط لکھیں۔ اس موقع پر آپ کے پاس موجود عجم کے کچھ لوگوں نے آپ سے عرض کیا: اللہ کے رسول! وہ لوگ مہر کے بغیر کوئی خط قبول نہیں کرتے۔ پس آپ صلی اللہ علیہ وسلم نے چاندی کی مہر بنوائی، گویا کہ میں اس کی سفیدی آپ صلی اللہ علیہ وسلم کی ہتھیلی میں دیکھ رہا ہوں، پھر آپ ملنے سلیم نے اس میں محمد رسول اللہ کندہ کرایا۔“","",{"k":"صحیح بخاری (٥٨٧٢)، مسلم (٩٢)۔"}],[6529,"سیدنا ابو ہریرہ ولی الین نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عزوجل نے فرمایا: میں شرکا کے شرک سے بے نیاز ہوں۔ پس جس نے کوئی عمل کیا اور اس میں میرے سوا کسی کو شریک ٹھہرایا تو میں اس سے لا تعلق ہوں وہ اس کے لیے ہے جس کے لیے اس نے شرک کیا۔“ ا کسی اور کو شریک کرنے کا مطلب ہے کہ دکھلاوے کے لیے کام کیا جائے، تاکہ اس کے ذریعے سے دنیوی مفاد حاصل کرے یا لوگوں کی نظروں میں منتقی و پارسا کہلائے۔ میں اس سے لاتعلق ہوں اس کا مطلب یہ ہے کہ میں اس کے عمل کو قبول نہیں کرتا، جیسا کہ ارشاد باری تعالیٰ ہے: الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَوةِ الدُّنْيَا (الكهف: ١٠٣) وہ لوگ کہ جن کی سعی دنیا کی زندگی میں گم ہوگئی۔“ دوسرے مقام پر فرمایا: فَمَنْ كَانَ يَرْجُوا لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا) (الكهف: ١١٠) پس جو آدمی اپنے رب سے ملاقات کی اُمید رکھتا ہو تو اسے چاہیے کہ وہ نیک عمل کرے۔“ عمل صالح سے مراد وہ عمل جو اللہ ذوالجلال کے لیے خالص ہو اور سنت نبوی کے مطابق ہو۔ مذکورہ حدیث میں دکھلاوے کو شرک سے تعبیر کر کے (کہ یہ بھی شرک خفی ہے ) اس کی شناعت و قباحت کو واضح کر دیا ہے۔ تاہم یہ شرک اصغر ہے جس کے مرتکب پر جنت حرام نہیں، جبکہ شرک اکبر و شرک صریح کا مرتکب دائی جہنمی ہے۔ اس پر جنت ہمیشہ کے لیے حرام ہے۔: و-ه-","",{"k":"مسلم کتاب الزهد (٢٩٨٥)۔"}],[6530,"سیدنا سعید بن زید نیا نہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دکھمبی (بنی اسرائیل پر نازل ہونے والی) من کے ضمن سے ہے اور اس کا پانی آنکھ کے لیے شفا ہے۔“ ٦٥٣١","",{"k":"عتبه، صحیح بخاری (٥٧٠٨)۔"}],[6531,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا کہ ہم میں سے کوئی کھڑا ہو کر جوتے پہنے اور یہ کہ کوئی ہڈی کے ساتھ استنجا کرے یا لید، گوبر کے ساتھ استنجا کرے۔“ ان احادیث کو ابراہیم بن طہمان سے صرف معن بن عیسی اور حفص بن عبد اللہ نے روایت کیا۔ البتہ عروہ بن علی کی جو روایت ہے اس میں یزید بن ابی حکیم نے ان دونوں کو اپنی روایت میں شریک کیا ہے۔ مذکورہ حدیث سے معلوم ہوا کہ جو تے بیٹھ کر پہنے چاہئیں، ظاہر ہے کہ یہ حکم ان جوتوں سے متعلق ہے جنہیں ہاتھ کی مدد سے پہنا ہوتا ہے، یعنی بوٹ وغیرہ اور جو جو تے بلا تکلف مثلاً چپل وغیرہ پہننے جا سکتے ہیں، ان کے لیے بیٹھنے کی کوئی وجہ نہیں۔ بعض علماء کے نزدیک یہ نہی تنزیہی ہے۔ یہ بھی معلوم ہوا کہ دین اسلام نے لوگوں کو زندگی گزارنے کے لیے ان کے ہر شعبہ میں رہنمائی کی ہے۔ مذکورہ بالا حدیث سے یہ بھی معلوم ہوا کہ گوبر اور ہڈی سے استنجا نہیں کرنا چاہیے۔ اس کی وضاحت سنن دار قطنی میں موجود ہے کہ ((انما لا يطهران)) (دار قطنی: ٥٦/١، اسناده صحیح) کیونکہ یہ دونوں پاک نہیں کرتے۔","",{"k":"سنن ترمذی، دار قطنی (٥٦/١، ٧٧٥)، قال الشيخ الالباني: صحيح۔"}],[6532,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہود و نصاری خضاب نہیں لگاتے، پس تم ان کی مخالفت کرو۔“ اس حدیث کو عروہ سے صرف ابو الاسود نے روایت کیا۔ اس میں ابن لہیعہ کا تفرد ہے۔ مطلب یہ ہے کہ داڑھی اور سر کے سفید بالوں کو زرد یا سرخ رنگ کے ساتھ رنگنا، البتہ ان کو سیاہ کرنا منع ہے۔ علماء نے اس حکم کو استحباب پر محمول کیا ہے، اس لیے داڑھی یا سر کے سفید بالوں کو رنگنا ضروری نہیں ہے، صرف بہتر ہے تاہم یہود و نصاریٰ کی مشابہت اختیار کرنا حرام ہے۔ جہاں نہ رنگنے سے مشابہت ہو گی، وہاں بالوں کو رنگنا ضروری ہوگا، ورنہ مستحب۔ ٦٥٣٣","",{"k":"صحیح بخاری، رقم: الله ٤١٢، صحیح مسلم (٢١٠٣)۔"}],[6533,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: ”اسلام کی بنیاد اس گواہی: کہ اللہ کے سوا کوئی معبود نہیں، نماز قائم کرنے، زکوۃ دینے، بیت اللہ کا حج کرنے اور رمضان کا روزہ رکھنے پر رکھی گئی ہے۔‘ اس حدیث کو خصیف سے صرف عبد العزیز بن عبد الرحمن نے روایت کیا۔ اس میں الحسین بن الفضل کا تفرد ہے۔","",{"k":"صحیح بخاری (٨)۔"}],[6534,"سيدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں، رسول اللہ سے ہم نے فرمایا: ” مظلوم کی بددعا","",{"k":"مسند احمد (٢/٤٥٧، ٨٥٤٣)، صحیح بخاری۔","f":"الله مذکورہ حدیث سے معلوم ہوا کہ مظلوم کی بد دعا سے بچنا چاہیے۔ مظلوم اس کو کہتے ہیں: جس پر ظلم کیا گیا ہو۔ ایک دوسری روایت میں ہے کہ سیدنا معاذ یا اللہ کو نبی معظم صلی اللہ علیہ وسلم نے چند نصیحتیں فرمائیں: ان میں سے ایک نصیحت یہ تھی، مظلوم کی بددعا سے بچنا، کیونکہ اس کے اور اللہ کے درمیان کوئی پردہ نہیں۔"}],[6535,"سیدنا ابو ہريرہ رضى اللہ ہم نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کتے کی قیمت حلال ہے نہ کا ہن کا نذرانہ اور زانیہ کی اجرت بھی حلال نہیں۔“ مذکورہ حدیث سے معلوم ہوا کہ کتے کی خرید و فروخت حرام ہے۔ جمہور علماء کے نزدیک یہ حکم عام ہے اور اس میں ہر قسم کے کتے شامل ہیں، چاہے وہ شکاری کتا ہو یا سدھایا ہوا یا کھیتوں وغیرہ کی حفاظت کی غرض سے لیا گیا ہو۔ لیکن بعض کے نزدیک ان کتوں کی خرید و فروخت اور ان کی قیمت جائز ہے جن ~ S کتوں کو رکھنے کی اجازت ہے جیسے شکار اور حفاظت کے لیے رکھے جانے والے کتے۔ (٢) اسی طرح کا ہن، عراف اور بھی جو لوگ ان کی طرح مستقبل کی خبریں بتا کر عوام کو بے وقوف بناتے اور ان سے پیسے بٹورتے ہیں، ان کی کمائی بھی حرام ہے اور ان کو دینا بھی نہیں چاہیے، کیونکہ جب ان کے لیے لینا جائز نہیں تو دینے والے کا دینا بھی جائز نہیں۔ (٣) بدکار عورت جو کچھ کماتی ہے، اسے مہر صرف اس کی ظاہری شکل کی وجہ سے کہا گیا ہے ورنہ یہ حرام ہے۔","",{"k":"سنن ابو داود (٣٤٨٤، ٥٥٦١)، قال الشيخ الالباني: صحيح۔"}],[6536,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کوئی متعدی بیماری ہے نہ کوئی بدشگونی ہے اور نظر کا لگنا حق ہے۔“ ان احادیث کو علی بن رباح سے صرف معروف بن سوید نے روایت کیا۔ ان میں ابن وہب کا تفرد ہے۔","",{"k":"صحیح بخاری (٥٧٠٧)۔","f":"اند. مذکورہ حدیث سے معلوم ہوا کہ بیماری ایک سے دوسرے کو نہیں لگتی بلکہ جس طرح پہلا شخص اللہ کی مشیت سے بیمار ہوا، دوسرا بھی اللہ کی مشیت ہی سے بیمار ہوا، بعض بیماریاں جو متعدی سمجھی جاتی ہیں، ان میں ان کے متعدی ہونے کا انکار نہیں ہے بلکہ صرف عقیدے کی درستی کی طرف توجہ دلائی گئی ہے کہ اس میں بھی اصل چیز اللہ کی مشیت ہی کو سمجھنا چاہیے نہ کہ کسی بیماری کو۔ کیونکہ اگر بیماری ہی اصل سبب ہو تو پھر ایک گھر میں متعدی مرض میں مبتلا ایک شخص کی وجہ سے گھر کے تمام افراد کو اس بیماری میں مبتلا ہونا چاہیے، جب کہ ایسا نہیں ہوتا، صرف ایک دو شخص ہی بیمار ہوتے ہیں، سب کے سب بیمار نہیں ہوتے، جس کے صاف معنی یہ ہیں کہ متعدی مرض میں بھی اصل سبب بیماری نہیں، اللہ کی مشیت اس کی تقدیر اور فیصلہ ہی ہے۔ اسی طرح ہسپتالوں میں ڈاکٹر جن کا چوبیس گھنٹے مریضوں کے ساتھ واسطہ رہتا ہے، اگر متعدی ہو تو کوئی ڈاکٹر بھی تندرست نہ ہو۔ (٢) اسی طرح بدشگونی لینے کا معاملہ ہے، اس کی بھی کوئی حقیقت نہیں ہے، اس لیے کچھ دیکھ کر دل میں اس قسم کا وسوسہ پیدا بھی ہو تو اسے اہمیت نہ دو، کیونکہ اس سے یہ بداعتقادی پیدا ہوتی ہے کہ فلاں چیز کی وجہ سے کام خراب ہو گیا، جبکہ فاعل اور مؤثر حقیقی صرف اللہ کی ذات ہے، اس لیے بدشگونی لینا حرام اور ناجائز ہے۔ (٣) مذکورہ حدیث سے معلوم ہوا کہ نظر برحق ہے اللہ تعالیٰ نے سیدنا یعقوب علی نام کی وہ نصیحت نقل کرتے ہوئے فرمایا، جو انہوں نے اپنے بیٹوں کو کی تھی۔ یبنی يبُنِيَّ لَا تَدْخُلُوا مِنْ بَابِ وَاحِدٍ وَ ادْخُلُوا مِنْ أَبْوَابٍ مُتَفَرِّقَةٍ (يوسف: ٦٧) ”اے میرے بیٹو! تم ایک ہی دروازے سے (شہر میں داخل نہ ہونا، بلکہ جدا جدا دروازوں سے داخل ہونا۔“ سیدنا عبد اللہ بن عباس رضی اللہ عنہما محمد بن کعب، ضحاک، مجاہد اور قتادہ اور سدی عبداللہ فرماتے ہیں: سیدنا یعقوب علینا نے ایک ہی دروازے سے داخل نہ ہونے کا حکم صرف اس لیے دیا تھا کہ انہیں اپنے بیٹوں کو نظر لگ جانے کا ڈر تھا، کیونکہ تمام بچے بہت خوبصورت بھلے اور جوان تھے۔ نظر بد وہ شے ہے جو شہسوار کو اس کی سواری سے گرا دیتی ہے۔ (تفسیر القرآن العظيم: ٤١٩/٢)"}],[6537,"سیدنا عقبہ بن عامر الجنی با لینہ نے بیان کیا، نبی نے ہم نے فرمایا: ” بکریوں کے باڑے میں نماز پڑھو اور اونٹوں کے باڑے میں نماز نہ پڑھو۔“ یہ حدیث سیدنا عقبہ بن عامر رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابن وہب کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٦/٢)، مجمع البحرين (٦٠٧)۔","f":"اند مذکورہ حدیث سے معلوم ہوا کہ اونٹوں کے باڑوں میں نماز نہیں پڑھنی چاہیے اور بکریوں کے باڑوں میں نماز پڑھنے کی رخصت ہے۔ دوسری حدیث میں اس کی وضاحت ملتی ہے سیدنا براء بن عازب رضی اللہ عنہما بیان کرتے ہیں: کہ رسول اللہ صلی اللہ علیہ وسلم سے اونٹوں کے باڑوں میں نماز کے متعلق پوچھا گیا تو آپ ل علم نے فرمایا: ان میں نماز نہ پڑھا کرو، بلاشبہ یہ شیاطین میں سے ہیں اور بکریوں کے باڑوں کے متعلق پوچھا گیا تو فرمایا: ان میں نماز پڑھ لیا کرو، بلاشبہ یہ بابرکت ہوتی ہیں۔ (ابو داؤد، رقم: ٤٩٣)"}],[6538,"سیدہ عائشہ نبی السنہا نے بیان کیا، رسول اللہ سے یم واضح طور پر انہیں فرمایا کرتے تھے: میں جبریل و میکائیل علیہ کے ایمان پر ہوں۔“ اس حدیث کو ایوب سے صرف الحسن بن ابی جعفر نے اور الحسن سے صرف عمر بن المغیرہ نے روایت کیا۔ اس میں بقیہ کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/٢٢١، ٢٢)، مجمع البحرين (٨٩)، اسناده ضعيف۔"}],[6539,"مالک بن عبیدہ الدیلی نے اپنے والد سے انہوں نے اس کے دادا سے روایت کیا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر بندے اللہ کے لیے رکوع نہ کرتے ہوں، دودھ پیتے بچے نہ ہوں اور چرتے ہوئے چوپائے نہ ہوں تو اللہ تم پر سخت عذاب نازل فرماتا اور پھر ریزہ ریزہ کر دیتا۔ یہ حدیث ابو عبیدہ الدیلی سے صرف اس اسناد سے مروی ہے۔ اس میں ابراہیم المنذ رکا تفرد ہے۔: لب و له وه و وره","",{"k":"مجمع الزوائد (١٠/٢٢٧)، مجمع البحرين (٥٠٨٥)، سلسله ضعیفه (٤٣٦٢)، ضعيف الجامع (٤٨٥٧)۔"}],[6540,"سیدنا علی بن علی الہلالی نے اپنے والد سے روایت کیا، انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا جبکہ آپ ملنے کی تم اپنے مرض وفات میں تھے، فاطمہ بنی الجھا آپ صلی اللہ علیہ وسلم کے سر کے پاس تھیں، پس وہ روئیں حتی کہ ان کی آواز بلند ہو گئی، رسول اللہ صلی اللہ علیہ وسلم نے اپنی نظر ان کی طرف اٹھائی تو آپ طل نعیم نے فرمایا: ”میری چہیتی فاطمہ! آپ کو کون سی چیز رلاتی ہے؟ انہوں نے عرض کیا: مجھے آپ صلی اللہ علیہ وسلم کے بعد نقصان کا اندیشہ ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”میری چہیتی! کیا تمہیں معلوم نہیں کہ اللہ نے ساری زمین کا جائزہ لیا اور اس نے اس میں سے تمہارے والد کا انتخاب کیا اور اسے اپنی رسالت کے ساتھ مبعوث کیا۔ پھر اس نے پوری زمین کا جائزہ لیا اور اس میں سے تمہارے شوہر کا انتخاب کیا اور میری طرف وحی کی کہ میں آپ کی اس سے شادی کروں۔‘ فاطمہ! ہم اہل بیت ہیں، اللہ نے ہمیں سات صفات عطا کی ہیں جو اس نے ہم سے پہلے کسی کو عطا کی ہیں نہ ہمارے بعد کسی کو دی جائیں گی۔ میں خاتم النبیین ہوں، اللہ کے ہاں سب سے زیادہ معزز نبی ہوں، پوری مخلوق سے اللہ کو زیادہ محبوب ہوں، میں تمہارا باپ ہوں، بہترین وصی، اللہ کو سب سے زیادہ محبوب، وہ تمہارے شوہر ہیں، ہمارا شہید سب سے بہتر شہید اور اللہ کو سب سے زیادہ محبوب وہ حمزہ بن عبد المطلب ہیں، وہ تمہارے والد کے چا اور تمہارے شوہر کے چچا ہیں اور ہم میں سے ایک ایسے ہیں جن کے دوسبر پر ہیں، وہ جنت میں فرشتوں کے ساتھ جہاں چاہتے ہیں پرواز کرتے ہیں اور وہ تمہارے والد کے چا زاد اور تمہارے شوہر کے بھائی ہیں اور ہم میں سے اس امت کے ایک سبط ہیں اور وہ دونوں تمہارے بیٹے حسن وحسن ہیں اور وہ دونوں جنتی نوجوانوں کے سردار ہیں اور ان دونوں کے والد اس ذات کی قسم جس نے مجھے حق کے ساتھ مبعوث فرمایا! ان دونوں سے بہتر ہیں۔ فاطمہ! اس ذات کی قسم جس نے مجھے حق کے ساتھ مبعوث فرمایا! ان دونوں میں سے اس امت کا ایک مہدی ہے۔ جب ساری دنیا خون ریزی اور فساد سے بھر جائے گی، فتنے ظاہر ہوں گے، راستے منقطع ہو جائیں گے، ایک دوسرے کو لوٹیں گے، بڑا چھوٹے پر رحم کرے گا نہ چھوٹا بڑے کی عزت کرے گا، پس اس وقت اللہ ان دونوں میں سے ایسے شخص کو مبعوث کرے گا جو گمراہی کے قلعے فتح کرے گا، بند دلوں کو نرم کر دے گا، وہ آخری دور میں دین کو قائم کرے گا، جس طرح میں نے پہلے زمانے میں قائم کیا تھا، وہ دنیا کو عدل سے اسی طرح بھر دے گا جس طرح وہ ظلم سے بھری ہوئی تھی۔ فاطمہ غم کرو نہ روڈ، بے شک اللہ تم پر بہت زیادہ مہربان اور مجھ سے زیادہ تم پر مشفق ہے۔ یہ اس لیے کہ تمہارا میرے ہاں جو مقام و مرتبہ ہے اور تمہارا میرے دل میں جو مقام ہے، اللہ نے تمہارے شوہر سے تمہاری شادی کرائی، وہ میرے اہل بیت میں حسب کے لحاظ سے سب سے زیادہ معزز، منصب کے لحاظ سے انتہائی عزیز، رعیت کے ساتھ انتہائی مہربان، انصاف کرنے میں انتہائی عادل، فیصلہ کرنے میں بہت زیادہ بصیرت رکھنے والے، میں نے اپنے رب سے درخواست کی کہ تم میرے اہل بیت میں سب سے پہلے مجھ سے آملو۔ سیدنا علی بن ابی طالب نیل الیہ نے بیان کیا، جب نبی صلی اللہ علیہ وسلم کی روح قبض کی گئی تو آپ ملنے یام کے بعد فاطمہ نی نی یا صرف پچہتر دن باقی رہیں حتی کہ اللہ نے انہیں آپ صلی اللہ علیہ وسلم سے ملا دیا۔ اس حدیث کو علی بن علی سے صرف سفیان بن عیینہ نے روایت کیا۔ اس میں الہیثم بن حبیب کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٥٣/٨)، مجمع البحرين (٣٥١٤)، مستدرك حاكم (١٤٠٣)، اسناده ضعیف۔"}],[6541,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو زیادہ باتیں کرتا ہے، زیادہ غلطیاں کرتا ہے اور جس کی زیادہ غلطیاں ہوں اس کے زیادہ گناہ ہوتے ہیں اور جس کے گناہ زیادہ ہوں، اس کی جہنم زیادہ حق دار ہے۔ پس جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو تو وہ خیر و بھلائی کی بات کرے یا پھر خاموش رہے۔ اس حدیث کو نافع سے صرف یحیی بن ابی کثیر نے اور بیٹی سے صرف عمر بن راشد نے، عمر سے صرف عیسی الغنجار نے عیسی سے صرف ابراہیم بن الاشعث نے روایت کیا۔ اس میں عبدہ بن عبد الرحیم کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٢/١٠)، مجمع البحرين (٥١٠٤)، سلسله ضعیفه (٤٦٤٣)، ضعيف الجامع الصغير (٥٨١٥)، اسناده ضعیف۔"}],[6542,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علیک یتیم نے ایک ایک بار وضو کیا۔ اس حدیث کو جعفر سے صرف حارث بن عمران نے روایت کیا۔","",{"k":"٦٥٤٢ کی سنن ترمذی، رقم: صحیح بخاری، مرة مرة، سنن ابو داود (١٣٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ وضو کے اعضاء کو ایک ایک بار بھی دھو لیا جائے تو وضو ہو جاتا ہے۔ اس طرح پیچھے احادیث گزر چکی ہیں کہ دو دو اور تین تین مرتبہ وضو کے اعضا دھونے بھی درست ہیں، کم از کم ایک مرتبہ زیادہ سے زیادہ تین مرتبہ اس سے زیادہ نہیں۔"}],[6543,"سیدنا ابو ہریرہ ریل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جنت میں موتی کا ایک محل ہے، اس میں کوئی ٹوٹ پھوٹ ہے، نہ کوئی بودا پین، اللہ نے اسے اپنے خلیل ابراہیم علینا) کے لیے تیار کیا ہے۔“ اس حدیث کو سماک سے صرف حماد بن سلمہ نے اور حماد سے صرف النضر بن شمیل اور یزید بن ہارون نے روایت کیا۔","",{"k":"کر مجمع البحرين (٣٥٩٤)، مجمع الزوائد (١٣٧٦٣)، اسناده ضعيف۔"}],[6544,"سیدہ عائشہ بین النہا سے روایت ہے کہ بنو بیاضہ کا آزاد کردہ غلام ابو ہند حجام تھا، وہ نبی ملنے میرینم کو پچھنے لگا تا تھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ” جسے پسند ہو کہ وہ ایسے شخص کو دیکھے جس کے دل میں اللہ نے ایمان نقش کر دیا ہے وہ ابو ہند کو دیکھ لے اور فرمایا: ”اس سے شادی کرو اور اس کی شادی کرا دو۔ “ (یعنی رشتوں کا لین دین کرو )۔“ اس حدیث کو زہری سے صرف زبیدی نے روایت کیا۔","",{"k":"مجمع الزوائد (٣٧٧/٩)، ابن عدی ضعفاء (٤/٣١٨)، مجمع البحرين (٣٨٩٦)۔"}],[6545,"سیدنا عبد الله بن عمر نیل الیہ نے بیان کیا کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ دریافت کیا: جبکہ آپ طائف سے واپس آتے ہوئے جعرانہ کے مقام پر تھے۔ انہوں نے عرض کیا: اللہ کے رسول! میں نے دور جاہلیت میں نذر مانی تھی کہ میں مسجد حرام میں ایک دن اعتکاف کروں گا، آپ کیا فرماتے ہیں؟ آپ نے فرمایا: ”جاؤ ایک دن اعتکاف کرو۔“ اور رسول اللہ صلی اللہ علیہ وسلم نے شمس میں سے انہیں ایک لونڈی عطا کی تھی، جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدی آزاد کیے تو انہوں نے انہیں یہ کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں آزاد کیا۔ انہوں نے پوچھا: یہ کیا ہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدی آزاد کر دیے ہیں۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: اس لونڈی کے پاس جاؤ اور اسے چھوڑ دو۔ اس حدیث کو جریر بن حازم سے صرف ابن وہب نے روایت کیا۔ خاندن و بخاری شریف میں ہے کہ سیدنا عمر رضی اللہ عنہ نے ایک رات اعتکاف کیا۔ معلوم ہوا کہ حالت کفر میں مانی ہوئی نذر حالت اسلام میں پوری کرنا لازم ہے۔ امام احمد، امام بخاری، امام ابن جریر اللہ اور شافعیہ کی ایک جماعت اسی کی قائل ہے۔ جبکہ جمہور کا کہنا ہے کہ کافر کی مانی ہوئی نذر منعقد ہی نہیں ہوتی، اس لیے قبول اسلام کے بعد اس پر نذر کو پورا کرنا بھی لازم نہیں، لیکن پہلا موقف ہی حدیث کے موافق ہونے پر راج ہے۔ شیخ عبد اللہ بسام جراللہ نے اسی کو ترجیح دی ہے۔ (توضیح الاحکام: ١٥٤/٧) یہ بھی معلوم ہوا کہ ایک رات کا بھی اعتکاف جائز ہے۔ یہ بھی معلوم ہوا کہ اعتکاف کے لیے روزہ شرط نہیں، کیونکہ روزہ اگر شرط ہوتا تو آپ ملنے میکنم سیدنا عمر نبی اللہ کو رات کے وقت اعتکاف بیٹھنے سے منع فرما دیتے۔ نیز جس روایت میں یہ ہے کہ روزے کے بغیر اعتکاف درست نہیں، وہ رسول اللہ صلی اللہ علیہ وسلم سے ثابت نہیں، (٢) رسول اللہ علیم نے جو قیدی آزاد کیے، دوسری روایات میں ہے کہ وہ قبیلہ ہوازن کے تھے تو سیدنا عمر رضی اللہ عنہ نے اعتکاف کی حالت میں لونڈی کو آزاد کر دیا۔ معلوم ہوا کہ حالت اعتکاف میں صدقہ و خیرات اور اس طرح کا مالی تصرف باعث اجر ہے۔","",{"k":"صحيح بخاری (٢٠٤٢)، صحیح مسلم (١٦٥٦)۔"}],[6546,"سیدنا ابوجبه البدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم غزوہ حنین کے دن جس طرف بھی دیکھتے آپ صلی اللہ علیہ وسلم کو ابوسفیان بن الحارث میلی لیے لڑتے ہوئے نظر آئے تو رسول اللہ تعلیم نے فرمایا: ’ابوسفیان میرے گھرانے کا بہتر شخص ہے۔‘یا فرمایا: ”میرے گھرانے کے بہتر افراد میں سے ہے۔“","",{"k":"کر مجمع الزوائد (٢٧٤/٩)، اسناده ضعيف۔"}],[6547,"سیدنا اسید بن حضیر رضی اللہ عنہ نے بیان کیا، میں چاندنی رات میں نماز پڑھ رہا تھا، میں نے اپنا گھوڑا باندھ رکھا تھا، پس وہ اچھلنے لگا تو میں گھبرا گیا، پس میں گھر میں چلا گیا، جب صبح ہوئی تو میں نے اس کا نبی مالے علم سے ذکر کیا، آپ ملاے علی تم نے فرمایا: ”وہ فرشتے تھے وہ رات کے آخری حصے میں تجھے سورۃ البقرہ پڑھتے ہوئے سننے آئے تھے۔“ سیدنا اسید نی ان کی آواز بہت اچھی تھی۔ اس حدیث کو عبید اللہ بن عمر سے صرف انس بن عیاض نے روایت کیا۔ اس میں ہارون الا یلی کا تفرد ہے۔","",{"k":"صحیح بخاری (٥٠١٨)، مسلم (٧٩٦)۔"}],[6548,"سیدنا عبد اللہ بن ابی اوفی ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم یہ دعا کیا کرتے تھے: ”اے اللہ! اولوں، برف اور ٹھنڈے پانی کے ذریعے میرے دل کو ٹھنڈا کر دے، مجھے گناہوں سے صاف کر دے، جس طرح تو نے سفید کپڑے کو میل کچیل سے صاف کر دیا۔‘ اس حدیث کو الحسن بن عبید اللہ سے صرف یوسف بن خالد نے روایت کیا۔","",{"k":"سنن ترمذی (٣٥٤٧)، قال الشيخ الالباني: صحيح۔","f":"اند کیونکہ غلطیوں اور گناہوں کا تعلق جہنم کی آگ سے ہے اور پانی آگ کو ختم کر دیتا ہے اس لیے پانی اور برف سے دھونے کی دعا کی جاتی ہے۔ گناہ کی تاثیر چونکہ گرم ہوتی ہے اس لیے ان الفاظ کو استعمال کیا جاتا ہے جس طرح یہ اشیا گرمی کو زائل کرتی ہیں، اسی طرح دعا سے گناہوں کی حدت جاتی رہتی ہے۔ مطلب یہ ہے کہ دل کو گناہوں سے پاک صاف کر کے اطمینان اور سکینت کی ٹھنڈک عطا فرما دے۔ ٦٥٤٩"}],[6549,"سیدنا علی نبی الیہ سے روایت ہے کہ سیدہ عائشہ بی اینجا بیان کیا کرتی تھیں: میں اور رسول اللہ صلے عام ایک برتن سے غسل جنابت کیا کرتے تھے۔ یہ حدیث سیدنا علی بن ابی طالب بنی اہلیہ کے حوالے سے سیدہ عائشہ منی این جہاں سے صرف اس اسناد سے مروی ہے، اس میں انس بن عیاض کا تفرد ہے۔ ٦٥٥٠","",{"k":"صحیح بخاری (٢٩٩)۔"}],[6550,"سيدنا قیس بن سعد بن عبادہ ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سواری کا مالک اس کے اگلے حصے، فرنٹ پر بیٹھنے کا زیادہ حق دار ہے۔“ اس حدیث کو حسین بن عبد اللہ بن ضمیرہ سے صرف انس بن عیاض نے روایت کیا۔ ٦٥٥١","",{"k":"مجمع البحرين (٣١٥٧)۔"}],[6551,"سیدہ عائشہ والی لویا نے فرمایا: جمعہ کے دن غسل کے بارے میں لوگوں نے بہت کچھ کہا، یہ معاملہ میرے گھر میں تھا، بالائی علاقے کے کچھ لوگ گرمی کے دن رسول اللہ علیم کے پاس آئے، انہوں نے اپنے نخلستان میں کام کیا تھا اور انہوں نے اون کے کپڑے پہن رکھے تھے، پس وہ آئے جبکہ ان سے بد بواٹھ رہی تھی تو رسول اللہ میم نے فرمایا: ”جب یہ (جمعہ کا دن ہو تو غسل کرو۔“ اس حدیث کو القاسم بن محمد سے صرف عمرو بن بیٹی نے، عمرو سے صرف اسماعیل بن رافع نے اور اسماعیل سے صرف الفضل بن العلاء نے روایت کیا۔ اس میں محمد بن ہشام السد وسی کا تفرد ہے۔","",{"k":"صحیح بخاری (٩٠٣)، مسلم (٨٤٧)۔"}],[6552,"سیدنا ابو موسی رضی اللہ عنہ نے بیان کیا، نبی لئے علیم دعا کیا کرتے تھے، ”اے اللہ! میری خطائیں، میری نادانی، میرے معاملے میں میرے اسراف اور وہ سب معاف کر دے، جسے تو مجھ سے زیادہ جانتا ہے۔ اے اللہ! میری دانستہ و نادانستہ لغزش میری بھول چوک اور میری خطائیں معاف کر دے اور یہ سب میری طرف سے ہے۔“","",{"k":"کر صحیح بخاری، دوس (٦٣٩٩)۔","f":"ناد معلوم ہوا کہ نبی معظم سے عام تمام گناہوں کی معافی کے باوجود بارگاہ الہی میں پھر بھی اپنی کوتاہیوں کی معافی کی درخواست کرتے تھے۔ اس میں امت کے لیے بہت بڑا سبق ہے۔ ایک سچے محبت رسول کو چاہیے کہ وہ تو بہ واستغفار سے غفلت نہ برتے بلکہ انتہائی عاجزی سے اپنے ہر قسم کے گناہوں کی معافی کی التجا کرتا رہے۔ مفصل دعا صحیح بخاری ومسلم میں موجود ہے، (دیکھئے: بخاری، رقم: ٦٣٩٨) ٦٥٥٣"}],[6553,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے ایسا کوئی شخص بھی نہیں جس کے اعمال اسے جنت میں داخل کرا دیں۔ کسی نے عرض کیا: اللہ کے رسول! آپ بھی نہیں؟ آپ مطلئے علیم نے فرمایا: ” میں بھی نہیں، مگر یہ کہ اللہ اپنی رحمت سے مجھے ڈھانپ لے گا۔‘“ ان دونوں حدیثوں کو ابو اسحاق سے صرف اشعث بن سوار نے روایت کیا۔ ان دونوں میں الفضل بن العلاء کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٥٦/١٠)، مجمع البحرين (٤٧٧٢)۔"}],[6554,"سیدنا انس بن مالک نبی اللہ نے بیان کیا، جب رسول اللہ صلی اللہ علیہ وسلم نے وفات پائی تو عرب ( کے کچھ قبائل ) مرتد ہو گئے تھے۔ سیدنا عم رضی اللہ عنہ نے فرمایا: \"ابو بکر ضیا اللہ! آپ تمام عربوں سے قتال کرنا چاہتے ہیں، جبکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مجھے حکم دیا گیا ہے کہ میں لوگوں سے قتال کروں حتی کہ وہ لا الہ الا اللہ کا اقرار کر لیں؟“ سیدنا ابو بکر رضی اللہ عنہ نے فرمایا: رسول اللہ علیم نے فرمایا ہے: ”جب وہ گواہی دیں کہ اللہ کے سوا کوئی معبود نہیں، نماز قائم کریں، زکوۃ ادا کریں تو انہوں نے اپنی جانیں اور اپنے اموال مجھ سے بچا لیے۔“ اللہ کی قسم! اگر انہوں نے بکری کا بچہ جسے وہ رسول اللہ صلی اللہ علیہ وسلم کو زکوۃ میں دیا کرتے تھے نہ دیا تو میں اس پر ان سے قتال کروں گا۔“ اس حدیث کو معمر سے صرف عمران القطان نے روایت کیا۔ اس میں عمرو بن عاصم کا تفرد ہے۔ نبی معظم ان کی وفات کے بعد قبائل عرب تین طرح سے کافر ہوئے تھے: ایک وہ لوگ تھے جو اسلام سے مرتد ہو کر مسیلمہ کذاب کے پیروکار ہو گئے تھے۔ دوسرے وہ تھے جنہوں نے نماز، زکاۃ اور دیگر احکام شریعت سے سرتابی کی تھی، تیسرے وہ تھے جنہوں نے صرف زکاۃ کی ادائیگی سے انکار کیا تھا۔ ان کا یہ انکار بھی کفر ہی کہلایا تھا۔ معلوم ہوا کہ زکاۃ واجب ہے۔ (٢) یہ بھی معلوم ہوا کہ بھیڑ، بکری کے بچے کی زکاۃ ان کے اصل کے ساتھ ہے، جب اصل پر سال گزر جائے گا تو اصل اور بچوں دونوں کو ملا کر زکاۃ لی جائے گی اور درست نہیں کہ بچوں پر بھی سال گزرے تو زکاۃ واجب ہو اور جب بچہ سال کا ہو جائے تو اس کو عناق نہیں کہا جا سکتا، اس لیے کے عناق اس بھیڑ کو کہتے ہیں جو سال سے کم ہے پس بچوں کے لیے الگ سے سال شمار نہیں ہو گا۔ فائد (مرعاة المفاتيح: ٤ - ٢٩/٥","",{"k":"صحیح بخاری (٣٩٢)۔"}],[6555,"سیدنا ابو ہریرہ بنی اہلیہ نے بیان کیا، رسول اللہ اے علی تم نے فرمایا: ”اللہ جسے نعمت عطا کرے تو وہ اللہ کا بہت زیادہ شکر ادا کرے۔ جس کے رنج و غم بڑھ جائیں وہ اللہ سے مغفرت طلب کرے۔ جس کے رزق میں کمی آجائے تو وہ کثرت سے لاحول ولا قوۃ الا رحمہ اللہ پڑھے۔ جو کسی کے ہاں مہمان ٹھہرے تو وہ ان کی اجازت سے روزہ رکھے۔ جو کسی کے گھر جائے تو وہ اسے جہاں بٹھا ئیں وہاں بیٹھے، کیونکہ وہ لوگ اپنے گھر کے پردے کے متعلق بہتر جانتے ہیں، وہ گناہ جو کرنے والے پر ناراضی کا باعث ہے، وہ کینہ، حسد، عبادت میں کسل مندی اور معیشت میں تنگی ہے۔ اس حدیث کو یحیی بن ابی کثیر سے صرف اوزاعی نے اور اوزاعی سے صرف یونس بن تمیم نے روایت کیا۔ اس میں محمد بن سلمہ المرادی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣/٢٠١)، مجمع البحرين (١٦١١)، اسناده ضعيف . الله۔"}],[6556,"سیدنا ابو ہریرہ بنی المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن اللہ ہر انسان کو اس کا گناہ یاد کرائے گا، وہ اگر چاہے تو اس پر اسے عذاب دے یا اس پر رحم فرمائے۔ البتہ سیدنا یچی بن زکریا ئایین) کا معاملہ الگ ہے۔ کیونکہ وہ سردار عورتوں سے بے رغبت اور نبی تھے۔ نبی صلی اللہ علیہ وسلم نے زمین سے ایک تنکا اٹھا کر فرمایا: ”ان کی شرم گاہ اس تنکے کے مانند تھی (یعنی وہ نہایت پاک دامن تھے )۔‘ اس حدیث کو محمد بن عجلان سے صرف لیٹ نے اور لیٹ سے صرف حجاج بن سلیمان نے روایت کیا۔ اس میں محمد بن سلمہ المرادی کا تفرد ہے۔","",{"k":"مجمع الزوائد (٢٠٩/٨)، كنز العمال (٣٢٤٢٨)، مجمع البحرين (٣٦٠٦)، اسناده ضعيف۔"}],[6557,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو زیادہ ہنستا ہے وہ اپنے حق سے کم تر سمجھا جاتا ہے۔ جو دل لگی میں بڑھ جاتا ہے اس کی شان وشوکت ختم ہو جاتی ہے۔ جو خالی پیٹ پانی پیتا ہے اس کی قوت کم پڑ جاتی ہے۔ جو زیادہ باتیں کرتا ہے اس کی لغزشیں بڑھ جاتی ہیں، جس کی لغزشیں زیادہ ہو جائیں، اس کی خطائیں بڑھ جاتی ہیں اور جس کی خطائیں زیادہ ہو جائیں تو جہنم اس کی زیادہ حق دار ہے۔ یہ حدیث رسول اللہ سے ہم سے صرف اس اسناد سے مروی ہے۔ اس میں عبدالاول المعلم کا تفرد ہے۔","",{"k":"مجمع الزوائد (٨٧/٥)، كنز العمال (٤٤٠١٦)، مجمع البحرين (٤١٤٨)۔","f":"قال الحافظ الهيثمي في اسناده من لم اعرفهم"}],[6558,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میری امت کے بہترین لوگ وہ ہیں جب وہ غلطی کرتے ہیں تو استغفار کرتے ہیں، جب نیکی کرتے ہیں تو خوش ہوتے ہیں اور جب سفر کرتے ہیں تو نماز قصر پڑھتے ہیں اور روزہ چھوڑ دیتے ہیں۔“ اس حدیث کو ابو الزبیر سے صرف ابن لہیعہ نے روایت کیا، اس میں عبد اللہ بن یحیی بن معبد المرادی کا تفرد ہے۔","",{"k":"البحرين، رقم: ٩٢١ . مجمع الزوائد (٢/١٥٧)، ضعيف الجامع الصغير (٢٩٠١)، مجمع۔"}],[6559,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، جب سیدنا جعفر بن ابی طالب رضی اللہ عنہ کے علاقے سے آئے تو رسول اللہ ما تم ان سے ملے۔ پس جب سیدنا جعفر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کی طرف دیکھا تو رسول اللہ ملنے کی خاطر وہ ایک پاؤں پر چلنے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کی پیشانی پر بوسہ دیا اور ان سے فرمایا: ”میرے پیارے: تم تخلیق و اخلاق کے حوالے سے مجھ سے سب سے زیادہ مشابہ ہو، تم اس مٹی سے پیدا کیے گئے جس سے میں پیدا کیا گیا۔ میرے پیارے! سرزمین حبشہ کے بعض عجائب کے بارے میں مجھے بتا ئیں۔ انہوں نے کہا: جی ہاں، اللہ کے رسول! میرے والدین آپ پر قربان ہوں، میں ایک دفعہ اس کے راستے میں ایک بڑھیا کے پاس کھڑا تھا اس کے سر پر ایک تھیلا تھا، ایک نوجوان اپنے گھوڑے کو دوڑا تا ہوا آیا، اسے دھکا دیا اور تھیلا اس کے سر سے گرا دیا، وہ سیدھی کھڑی رہی اور مسلسل اسے دیکھتی رہی اور وہ کہہ رہی تھی: تمہارے لیے کل تباہی ہونے والی ہے۔ جب بادشاہ اپنی کرسی پر بیٹھے گا وہ مظلوم کو ظالم سے بدلہ دلائے گا۔:٦٥٦٠ سیدنا جابر رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ سلیم کی طرف دیکھا کہ موٹے موٹے آنسو آپ ملے عام کی آنکھوں سے گر رہے ہیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ اس قوم کو پاک نہیں کرتا جہاں مظلوم آسانی کے ساتھ اپنا حق وصول نہیں کر سکتا۔ اس حدیث کو سفیان بن عیینہ سے صرف مکی بن عبد اللہ الرعینی نے روایت کیا۔","",{"k":"مجمع الزوائد (٥/٢٠٨)، مجمع البحرين (٢٥٥٨)، اسناده ضعيف۔"}],[6560,"سیدنا عبداللہ ابن عمر نبی المیہ نے بیان کیا، میں بدر کے کناروں پر جا رہا تھا کہ ایک آدمی گڑھے سے نکلا، اس کی گردن میں زنجیر تھی۔ اس نے مجھے آواز دی: عبداللہ! مجھے پانی پلا ؤ، عبد اللہ! مجھے پانی پلاؤ، میں نہیں جانتا کہ وہ میرے نام سے واقف تھا یا اس نے عرب کے بلانے کے انداز میں مجھے بلایا۔ اس گڑھے سے ایک سیاہ فام شخص نکلا۔ اس کے ہاتھ میں ایک کوڑا تھا۔ اس نے مجھے آواز دی۔ عبداللہ! اسے پانی نہ پلانا، وہ تو کافر ہے، پھر اسے کوڑا ماراحتی کہ وہ اپنے گڑھے میں واپس آ گیا۔ پس میں تیزی کے ساتھ نبی الٹے علیم کے پاس آیا اور آپ صلی اللہ علیہ وسلم کو بتایا تو آپ صلی اللہ علیہ وسلم نے مجھے فرمایا: وہ اللہ کا دشمن ابو جہل بن ہشام ہے اور یہ اس کا قیامت کے دن تک عذاب ہے۔ اس حدیث کو مالک بن مغول سے صرف عبد اللہ بن محمد بن المغیر ہ الکوفی نے روایت کیا۔","",{"k":"و مجمع الزوائد (٥٧/٣)، مجمع البحرين (٢٧٥٣)، اسناده ضعيف۔"}],[6561,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، میں رسول اللہ ملنے کی خدمت کیا کرتا تھا، انہوں نے بھنا ہوا چوزہ پیش کیا تو رسول اللہ ملے ہیم نے فرمایا: اے اللہ! اس شخص کو میرے پاس لا جو پوری مخلوق میں سے تجھے اور مجھے سب سے زیادہ محبوب ہو وہ اس چوزے میں سے میرے ساتھ کھائے۔‘ پس سیدنا علی فی ال لینے آئے اور انہوں نے دروازے پر دستک دی۔ سیدنا انس بنی اہلیہ نے کہا: کون ہے؟ انہوں نے کہا: علی میں نے کہا: نبی صلی اللہ علیہ وسلم ی مصروف ہیں، پس وہ واپس چلے گئے۔ پھر رسول اللہ صلی اللہ علیہ وسلم ایک جانب ہوئے اور آپ نے کھانا کھایا، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! اس شخص کو میرے پاس لا جو پوری مخلوق میں سے تجھے اور مجھے سب سے زیادہ محبوب ہو اور وہ اس چوزے میں سے میرے ساتھ کھائے۔‘ پس سیدنا علی رضی اللہ عنہ آئے، انہوں نے بہت زور سے دروازہ کھٹکھٹایا، رسول اللہ صلی اللہ علیہ وسلم نے سن لیا تو فرمایا: ”انس! کون ہے؟“ میں نے عرض کیا: سیدناعلی رضی اللہ عنہ آپ نے فرمایا: ” نہیں اندر لاؤ پس وہ اندر آئے تو رسول اللہ مالے سلیم نے فرمایا: ”میں نے Serie ٧. B تین بار اللہ سے دعا کی کہ وہ ایسے شخص کو میرے پاس لائے جو پوری مخلوق میں سے اسے اور مجھے سب سے زیادہ محبوب ہو، وہ اس چوزے میں سے میرے ساتھ کھائے۔“ سیدنا علی رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! میں تین بار آیا ہوں، ہر بار انس مجھے واپس کر دیتے رہے ہیں۔ رسول اللہ ملنے کی ایم نے فرمایا: تم نے جو کیا اس پر کس چیز نے تمہیں آمادہ کیا؟“ میں نے عرض کیا: میں نے چاہا کہ میری قوم میں سے کوئی آدمی اس دعوت، دعا کا مستحق ٹھہرے۔ رسول اللہ میم نے فرمایا: ” آدمی اپنی قوم کی محبت پر قابل ملامت نہیں۔“ اس حدیث کو یحیی بن سعید سے صرف سلیمان بن بلال نے اور سلیمان سے صرف یحیی بن حسان نے روایت کیا۔ اس میں محمد بن ابی غسان کا اپنے والد سے تفرد ہے۔","",{"k":"مجمع الزوائد (٩/١٢٥)، سنن ترمذی (٣٧٢١)، مجمع البحرين، رقم: ٣٧١٠ ٥-٥۔"}],[6562,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے لیے ایک نہر ہے جو صنعا اور ایلہ کے درمیانی مسافت کے برابر ہے، اس میں ستاروں کی تعداد کے برابر برتن ہیں، برف سے زیادہ ٹھنڈا، شہد سے زیادہ شیریں اور دودھ سے زیادہ سفید ہے، جو اس میں سے ایک گھونٹ پی لے گا، اسے کبھی پیاس نہیں لگے گی اور جو اسے نہیں پئے گا وہ کبھی سیراب نہیں ہو گا۔“ اس حدیث کو ابو بردہ سے صرف العرزمی نے اور العرزمی سے صرف داود بن ہلال نے روایت کیا۔ اس میں زہیر بن عباد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٦١، ٣٩٦)، مجمع البحرين (٤٨٣٢)۔"}],[6563,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ سلیم نے فرمایا: ”کوئی بندہ ایمان کی حقیقت کو نہیں پہنچ سکتا حتی کہ وہ اپنی زبان کو محفوظ رکھے۔ اس حدیث کو ہشام بن حسان سے صرف داود بن ہلال نے روایت کیا۔ اس میں زہیر بن عباد کا تفرد ہے۔","",{"k":"مجمع الزوائد (٣٠٢/١٠)، ضعیف ترغیب و ترهیب (١٧٠٤)، مجمع البحرين (٥١٠٠)۔"}],[6564,"سیدنا علی بن ابی طالب نیل الیہ سے روایت ہے کہ نبی ملنے کریم نے فرمایا: ”دودھ چھڑانے کے بعد اگر کوئی کسی عورت کا دودھ پی لے تو اس سے حرمت رضاعت ثابت نہیں ہوتی اور بلوغت کے بعد کوئی یتیمی نہیں۔“ اس حدیث کو علقمہ سے صرف ابراہیم نے، ابراہیم سے صرف ابان بن ثعلب نے، ابان سے صرف موسی بن عقبہ نے اور موسی سے صرف محمد بن جعفر نے روایت کیا۔ اس میں محمد بن عبید التنبان کا اپنے والد سے تفرد ہے اور ہم نے اسے صرف اس الشیخ سے روایت کیا ہے۔","",{"k":"کے طبرانی صغیر (٩٥١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رضاعت کی حرمت تب ثابت ہو گی جب بچہ دودھ پیتا ہوا اور بھی اس کا دودھ چھڑایا نہ ہو۔ جیسا کہ سیدنا ام سلمہ نی نیہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: صرف وہی رضاعت حرمت ثابت کرتی ہے جو انتڑیوں کو کھول دے۔‘((وکان قبل الفطام)) ” اور دودھ چھڑانے کی مدت ( یعنی دو سال کی عمر) سے پہلے ہو۔ “ (ترمذی، رقم: ١١٥٢، ارواء الغليل، رقم: ٢١٥٠، اسنادہ صحیح) ایک دوسری حدیث میں ہے کہ سیدنا جابر نبی الیہ سے مروی ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((لا مو رضاع بعد خطام) دودھ چھڑانے کی مدت کے بعد رضاعت ثابت نہیں ہوتی۔“ (ارواء الغليل، رقم: ١٢٤٤، اسناده حسن) (٢) یہ بھی معلوم ہوا کہ جب بچہ بالغ ہو جائے تو پھر یتیمی نہیں رہتی کیونکہ بچہ بالغ ہونے کے بعد اپنے امور کا خود ذمہ دار ہو جاتا ہے اور اس سے یتیمی کے احکام اٹھ جاتے ہیں۔ اگر وہ فی الواقع دانا اور سمجھ دار ہو تو خرید و فروخت اور نکاح وغیرہ کے معاملات میں اس کا اپنا فیصلہ راجح ہو گا۔ لیکن اگر ثابت ہو کہ ان معاملات میں وہ دانا نہیں ہے تو ولی ہی اس کا نگران رہے گا، جیسے کہ سورۃ النساء میں ہے: وَابْتَلُوا الْيَتمَى حَتَّى إِذَا بَلَغُوا النِّكَاحَ فَإِنْ أَنَسْتُمْ مِنْهُمْ رُشْدًا فَادْفَعُوا إِلَيْهِمْ أمْوَالَهُمْ (النساء: ٦) اور یتیموں کو ان کے بالغ ہو جانے تک سدھارتے اور آزماتے رہو، پھر اگر ان میں تم حسن تدبیر پاؤ تو انہیں ان کے مال سونپ دو۔“"}],[6565,"سیدہ عائشہ بنی النیہا نے بیان کیا، نبی ملنے میریم دو قبروں کے پاس سے گزرے کہ انہیں عذاب ہو رہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” ان دونوں قبر والوں کو عذاب دیا جا رہا ہے، انہیں کسی بڑے گناہ کی وجہ سے عذاب نہیں دیا جا رہا، ان میں سے ایک پیشاب کرتے وقت احتیاط نہیں کرتا تھا، جبکہ دوسرا چغل خور تھا۔“ پس آپ نے کھجور کی تازہ شاخ منگائی، اسے توڑا اور اسے اس پر اور اس پر رکھ دیا اور فرمایا: ” ہوسکتا ہے کہ ان کے خشک ہونے تک ان دونوں سے تخفیف کر دی جائے۔ اس حدیث کو منصور سے صرف عبیدہ بن حمید نے روایت کیا۔اس میں علی بن جعفر الاحمر کا تفرد ہے۔","",{"k":"مجمع الزوائد (١/٢٠٧)، مجمع البحرين (٣٦٣)، اسناده صحيح۔"}],[6566,"سیدنا انس بن مالک نبی اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم حرا ( پہاڑ ) پر تھے کہ اس نے جنبش کی تو نبی ملنے سلیم نے اسے پاؤں سے ٹھوکر مار کر فرمایا: ٹھہر جا تم پر ایک نبی، ایک صدیق اور دو شہید ہیں۔ اس پر نبی طلئے علیم، سیدنا ابو بکر اور سیدنا عمر وسیدنا عثمان بنی سلیم تھے۔ اس حدیث کو مطر سے صرف داود بن الزبرقان نے روایت کیا۔","",{"k":"صحیح بخاری، لو كنت متخذا (٣٦٧٣)، سنن ابو داود (٤٦٥١)۔","f":"انده مذکورہ حدیث سے سیدنا ابو بکر، سیدنا عمر اور سیدنا عثمان می بینیم کی فضیلت واضح ہے۔ یہ تینوں صحابہ اکثر مواقع پر نبی معظم نے تم کے ساتھ ہوتے تھے۔ حرا ایک پہاڑ ہے جو مکہ شہر سے تقریباً تین میل کے فاصلے پر ہے۔ نبی معظم بنی الیہ نے پاؤں مار کر فرمایا: ٹھہر جا تو وہ ٹھہر گیا، یہ آپ صلی اللہ علیہ وسلم کا معجزہ ہے۔ ٦٥٦٧"}],[6567,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”میرے اصحاب کو برا بھلا مت کہو، اگر تم میں سے کوئی احد ( پہاڑ) کے برابر سونا خرچ کرے تو وہ ان میں سے کسی ایک کے ایک مد ( تقریباً چھ سو گرام ) خرچ کرنے کو پہنچ سکتا ہے نہ اس کے نصف کو۔ “ اس حدیث کو محمد بن جمادہ کے حوالے سے ابوصالح سے صرف داود بن الزبرقان نے روایت کیا اور الحسن بن ابی جعفر نے اسے محمد بن جمادہ، عن: ٦٥٦٨ عطیہ عن ابی سعید کی سند سے روایت ہے۔","",{"k":"صحیح بخاری کتاب فضائل الصحابه، سنن ترمذی (٣٨٦١)۔"}],[6568,"سیدنا عبد اللہ بن انیس رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے شب قدر کے متعلق دریافت کیا؟ تو آپ ملالے علیم نے فرمایا: میں نے اسے دیکھا تھا، پس وہ مجھے بھلا دی گئی، اسے آخری نصف میں تلاش کر۔ پھر آپ نے دوبارہ فرمایا: ”اس ماہ کی تیسویں میں۔“ یہ حدیث عطیہ بن عبد اللہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابن ابی فدیک کا تفرد ہے۔ پیچھے احادیث گزر چکی ہیں کہ لیلۃ القدر رمضان کے آخری عشرے کی طاق راتوں میں ہے۔ جن میں مختلف راتوں کا تذکرہ ہے، اس کے متعلق امام شافعی اللہ کہتے ہیں: کہ جن مختلف راتوں میں لیلۃ القدر ہونے کا ذکر ہے وہ ہمیشہ کے لیے نہیں ہیں، بلکہ یہ حسب حال سوالوں کے جوابات تھے، مثلاً وہ کہتے کہ کیا ہم اسے فلاں رات میں تلاش کریں؟ آپ فرماتے: ہاں، فلاں رات میں تلاش کرو، (واللہ اعلم ) اور جس نے جو سنا اسی کا قائل رہا۔ ٦٥٦٩","",{"k":"١١٦٨ الله صحیح مسلم، رقم۔"}],[6569,"سیدہ عائشہ ولی الی با بیان کرتی ہیں: سیدہ سہلہ بنت سہیل نونی نی یا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں تو انہوں نے عرض کیا: اللہ کے رسول! میں سالم کے اپنے پاس آنے سے ابو حذیفہ کے چہرے پر ناراضی کے آثار دیکھتی ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اسے دودھ پلا دو۔“ اس نے عرض کیا: وہ تو داڑھی والا ہے، آپ اللہ کریم نے فرمایا: ” اسے (اپنا) دودھ پلا دو، ابو حذیفہ کے چہرے سے ناراضی ختم ہو جائے گی۔‘اس حدیث کو حمید بن نافع سے صرف بکیر بن عبد اللہ نے اور بکیر سے صرف اس کے بیٹے محترمہ نے روایت کیا۔ اس میں ابن وہب کا تفرد ہے۔ مذکورہ حدیث سے معلوم ہوا کہ بوقت ضرورت بڑی عمر کے لڑکے کو بھی دودھ پلانے سے حرمت ثابت ہو جاتی ہے، سیدنا علی، سیدہ عائشہ، عروہ بن زبیر بی ایم، امام عطاء، امام لیث، امام داؤد اور امام ابن حزم تیم اسی کے قائل ہیں۔ تفصیل کے لیے دیکھئے: (نیل الاوطار: ٤١٧/٤، المعلى بالآثار: ١٠/ ٢٠٢) جمہور علماء کا کہنا ہے کہ رضاعت وہی معتبر ہے جو دو سال کی عمر کے اندر اندر ہوئی ہو۔ ان کا کہنا ہے کہ اس معنی کی احادیث کثرت سے ہیں، جبکہ بڑے لڑکے کو دودھ پلانے کے متعلق صرف ایک حدیث سالم ہی ہے۔ سیدہ عائشہ بنایا ہوا کے علاوہ تمام ازواج مطہرات فنی این بھی اسی کی قائل تھیں، احتیاط بھی اسی میں ہے، بڑے آدمی کو دودھ پلانے سے گوشت نشو و نما پاتا ہے نہ ہڈیاں مضبوط ہوتی ہیں اور نہ ہی جسم کا کوئی حصہ بنتا ہے، حالانکہ یہی حرمت کے دو اسباب ہیں۔ جو احادیث میں مذکور ہیں۔ شیخ الاسلام ابن تیمیہ اللہ کا یہ موقف ہے کہ مسئلہ رضاعت میں بچپن کا اعتبار کیا جائے گا، الا کہ کوئی حاجت وضرورت پیش آ جائے، جیسا کہ بڑی عمر کے آدمی کی رضاعت کا مسئلہ ہے، ایسا شخص جسے کسی عورت کے پاس جانا بھی ضروری ہو اور اس عورت کا اس سے پردہ کرنا بھی دشوار ہو، جیسا کہ سیدنا سالم یا اللہ کا سیدنا ابو حذیفہ ضیا الیہ کی بیوی کے ساتھ معاملہ تھا۔ اس طرح کے بڑی عمر کے آدمی کو اگر عورت نے دودھ پلا دیا تو اس آدمی کے لیے دودھ پینا قابل تاثیر ہوگا، نیز ایسی صورت کے علاوہ دودھ پینے کی مدت بچپن کی عمر ہی ہے۔ (مجموع الفتاوی: ٣٤/ (٦٠) یہی زیادہ راجح معلوم ہوتا ہے۔ (اللہ اعلم","",{"k":"صحیح مسلم (١٤٥٣)، سنن نسائی (٣٣٢٠)۔"}],[6570,"سیدنا جابر بن عبد اللہ نبی الیہ نے بیان کیا، ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور اس نے عرض کیا: اللہ کے رسول! میرے والد نے میرا مال لے لیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جاؤ، اپنے والد کو میرے پاس لاؤ۔ پس سیدنا جبریل علیہ سلام نبی نے علی یتیم کے پاس آئے اور کہا: اللہ آپ کو سلام کہتا ہے اور فرماتا ہے: جب وہ بوڑھا شخص آپ صلی اللہ علیہ وسلم کے پاس آئے تو اس سے ایک چیز کے متعلق سوال کرنا، اس نے دل میں کوئی بات کہی میرے کانوں نے اسے نہ سنا۔ پس جب وہ بوڑھا شخص آیا تو نبی نے ہم نے اسے فرمایا: ”تمہارا بیٹا تمہاری شکایت کرتا رہا ہے کہ تم نے اس کا مال لے لیا ہے۔“ اس نے عرض کیا: اللہ کے رسول! اس سے پوچھیں: کیا اس نے اپنی صرف ایک پھوپھی یا اپنی خالہ یا میری ذات پر ہی خرچ کیا ہے؟ نبی صلی اللہ علیہ وسلم نے فرمایا: ”چھوڑو! ہمیں یہ نہ بتاؤ، مجھے اس چیز کے متعلق بتاؤ جو تم نے اپنے دل میں کہی ہے؟ جسے تمہارے کانوں نے نہ سناء اس بوڑھے شخص نے کہا: اللہ کی قسم! اللہ کے رسول! اللہ آپ صلی اللہ علیہ وسلم کے ذریعے ہمیں یقین میں بڑھاتا رہا۔ میں نے اپنے دل میں کہا: ایک چیز جسے میرے کانوں نے نہیں سنا، آپ نے فرمایا: ” کہو جب کہ میں سن رہا ہوں۔‘اس نے کہا: میں نے کہا۔ راوی نے بیان کیا، اس وقت نبی صلی اللہ علیہ وسلم نے اس کے بیٹے کے کپڑے کو پکڑا اور فرمایا ”تم اور تمہارا مال تمہارے والد کے لیے ہے۔ اس حدیث کو ان الفاظ اور شعر کے ساتھ المنکدر بن محمد بن المنکدر سے صرف عبداللہ بن نافع نے روایت کیا۔ اس میں عبید بن خلصہ کا تفرد ہے۔“ ٦٥٧١","",{"k":"مجمع الزوائد: ٤ / ١٥٥ مجمع البحرين (٢١٩٧)، اسناده ضعيف۔"}],[6571,"سیدہ عائشہ منی نیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ”اپنے والد اور اپنے بھائی کو بلا وحتی کہ میں تحریرلکھ دوں، مجھے اندیشہ ہے کہ کوئی کہنے والا کوئی اور بات کہے اور تمنا کرنے والا کوئی اور تمنا کرے، اللہ اور مومن صرف ابو بکر پر ہی متفق ہوں گے۔ اس حدیث کو الز ہری سے صرف صالح بن کیسان نے، اور صالح بن کیسان سے صرف ابراہیم بن سعد نے روایت کیا۔ اس میں یزید بن ہارون اور احمد بن ایوب کا تفرد ہے۔ ٦٥٧٢","",{"k":"کر صحيح بخاری (٥٦٦٦)، مسلم (٢٣٨٧)۔"}],[6572,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، میں نے عرض کیا: اللہ کے رسول! عمرہ واجب ہے، اس کی فرضیت حج کی فرضیت کی طرح ہے؟ آپ ملنے یا تم نے فرمایا: نہیں۔“ اگر تم عمرہ کرو تو وہ تمہارے لیے بہتر ہے۔ عبید اللہ جن سے یحیی بن ایوب نے اس حدیث کو روایت کیا، وہ عبید اللہ بن ابی جعفر ہیں۔ ابوالز بیر سے اس حدیث کو صرف عبید اللہ بن ابی جعفر نے روایت کیا۔ اس میں یحیی بن ایوب کا تفرد ہے۔ جبکہ وہ حجاج بن ارطاۃ کی روایت عن محمد بن المنکد رعن جابر کی سند سے مشہور","",{"k":"کی سنن ترمذی (٩٣١)، مسند احمد (٣١٦/٣)، قال شعیب الارناؤط اسناده ضعیف۔"}],[6573,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں اور مہاجر وہ ہے جو اللہ کی منع کردہ چیز ترک کر دے۔‘ اس حدیث کو مجالد سے صرف المسعودی نے روایت کیا۔","",{"k":"صحیح بخاری (١٠)، صحیح مسلم (٤٠)۔"}],[6574,"سیدنا عبداللہ ضیا اللہ نے بیان کیا، میں صادق و مصدوق ابوالقاسم نے کی بات کو یقینی جانتے ہوئے بیان کرتا ہوں کہ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ”جانوروں کے تھنوں میں دودھ روک کر ان کو فروخت کرنا دھو کہ رہی ہے اور کسی مسلمان کو دھوکہ دینا حلال نہیں۔“ اس حدیث کو جابر سے صرف المسعو دی نے روایت کیا۔","",{"k":"سنن ابن ماجه (٢٢٤١)، مسند احمد (١/٤٣٣)، قال الشيخ الالباني: ضعيف۔"}],[6575,"سیدنا معاذ بن جبل رزینی اہلیہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” مجھے تمہارے متعلق تین باتوں کا اندیشہ ہے اور وہ ہونے والی ہیں، عالم کی لغزش، منافق کا قرآن سے بحث و مباحثہ کرنا اور تم پر دنیا فراخ کر دی جائے گی۔“ اس حدیث کو عبد الملک بن عمر سے صرف عبدالحکیم بن منصور نے روایت کیا۔","",{"k":"مجمع الزوائد (١/١٧٦)، مجمع البحرين (٢٦٩)، اسناده ضعيف۔"}],[6576,"سیدنا ابولیلی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب کے درمیان مال غنیمت تقسیم کیا، آپ صلی اللہ علیہ وسلم نے ہر دس کے لیے ایک بکری مقرر کی۔“ اس حدیث کو غیلان بن جامع سے صرف یعلی بن الحارث نے روایت کیا، اس میں ان کے بیٹے بیٹی کا تفرد ہے اور ابن ابی لیلی سے صرف اسی اسناد سے مروی ہے۔ مند احمد میں ہے کہ غزوہ خیبر کے موقع پر ایسا کیا۔ معلوم ہوا کہ مال غنیمت کم ہو تو امیر ایک چیز میں ایک سے زیادہ آدمیوں کو شریک کر سکتا ہے۔ ٦٥٧٧","",{"k":"مجمع الزوائد (٣٤١/٥)، مسند احمد (٤/٣٤٨)، مجمع البحرين (٢٧٣٠)، اسناده صحيح۔"}],[6577,"سیدنا انس بن مالک فی اللہ نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فتح مکہ کے دن چار اشخاص، عبد العزی بن خطل، مقیس بن صبابہ الکنانی، عبد الله بن سعد بن ابی سرح اور ام سارہ عورت کے علاوہ تمام لوگوں کو امان دے دی۔ رہا عبد العزی تو اسے قتل کر دیا گیا، جبکہ وہ کعبہ کے غلافوں کو تھامے ہوئے تھا۔ راوی نے بیان کیا: انصار کے ایک آدمی نے نذر مانی کہ وہ جب بھی عبد اللہ بن سعد بن ابی سرح کو دیکھے گا تو وہ اسے قتل کرے گا اور وہ سیدنا عثمان بن عفان رضی اللہ عنہ کا رضاعی بھائی تھا۔ وہ اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آئے اور اس کی سفارش کی۔ پس جب اس انصاری شخص نے دیکھا تو اس نے تلوار حمائل کی، پھر اس کی تلاش میں نکلا، اس نے اسے رسول اللہ علیم کے حلقے میں پایا۔ پس وہ اسے قتل کرنے سے ڈر گیا، وہ تردد کا شکار ہو گیا اور اس پر پیش قدمی کرنا نا پسند کیا، کیونکہ وہ رسول اللہ صلی اللہ علیہ وسلم کے حلقے میں تھا۔ پس رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ بڑھایا اور اس کی بیعت لے لی۔ پھر انصاری سے فرمایا: میں نے تمہارا انتظار کیا کہ تم اپنی نذر پوری کر لو۔ “ اس نے عرض کیا: اللہ کے رسول! میں آپ صلی اللہ علیہ وسلم سے ڈر گیا۔ آپ صلی اللہ علیہ وسلم نے مجھے آنکھ سے اشارہ کیوں نہ کر دیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: کسی نبی کی شان نہیں کہ وہ آنکھ سے اشارہ کرے“ رہا مقیس تو اس کا ایک بھائی تھا، وہ غلطی سے رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ سے قتل ہو گیا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس کے ساتھ بنو فہر سے ایک آدمی بھیجا تا کہ وہ اس کے لیے انصار سے دیت حاصل کرے۔ پس جب اس کے لے دیت جمع کی گئی اور وہ لوٹا۔ پس فہری سو گیا تو قیس نے کود کر ایک پتھر پکڑا اور اس کے سر پر مار کر قتل کر دیا۔ پھر وہ واپس آیا اور کہہ رہا تھا: میں نے اپنا بدلہ لے لیا ہے، رہی ام سارہ تو وہ قریش کی آزاد کردہ لونڈی تھی۔ وہ رسول اللہ ہیم کے پاس آئی اور آپ سے اپنی ضرورت پیش کی، آپ نے اسے کچھ دے دیا۔ پھر ایک آدمی اس کے پاس آیا، اس نے مکہ والوں کے لیے ایک تحریر اسے پیش کی، وہ اس کے ذریعے ان کے ہاں تقرب چاہتا تھا تا کہ اس کے بال بچوں کی حفاظت کی جائے۔ اس کے بال بچے وہاں ( مکہ میں) تھے۔ پس سیدنا جبریل کی پسلام نے اس کے متعلق رسول اللہ ملت ایام کو بتا دیا۔ آپ نے عمر بن خطاب رضی اللہ عنہ اور علی بن ابی طالب نبی الیہ کو اس کے پیچھے بھیجا۔ پس وہ اسے جاملے، انہوں نے اس کی تلاشی لی لیکن اس سے کوئی چیز برآمد نہ کر سکے اور وہ واپس پلٹے، ان میں سے ایک نے اپنے ساتھی سے کہا: اللہ کی قسم! ہم نے جھوٹ بولا، نہ ہم سے جھوٹ بولا گیا، ہمیں اس کے پاس پھر لے چلیں۔ پس وہ دونوں اس کے پاس واپس گئے۔ انہوں نے اپنی تلوار میں سونتیں اور کہا: اللہ کی قسم! ہم تجھے موت سے دوچار کر دیں گے یا پھر تو وہ تحریر ہمارے حوالے کر دے گی، اس نے انکار کیا۔ پھر اس نے کہا: میں اس شرط پر وہ تمہارے حوالے کرتی ہوں کہ تم مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس واپس نہیں لے جاؤ گے۔ انہوں نے اس کی یہ شرط قبول کر لی۔ پس اس نے اپنے سر کا بندھن، رسی کھولی اور اپنی مینڈھیوں سے وہ تحریر نکال کر ان دونوں کے حوالے کر دی۔ وہ اسے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس لوٹے اور اسے آپ ملنے کے حوالے کیا۔ آپ نے اس آدمی (جس نے یہ تحریر دی تھی ) کو بلا بھیجا اور فرمایا: ”یہ تحریر کیا ہے؟ اس نے عرض کیا: اللہ کے رسول! میں آپ صلی اللہ علیہ وسلم کو بتا تا ہوں، میرے علاوہ آپ صلی اللہ علیہ وسلم کے ساتھ جتنے حضرات ہیں، ان کے مکہ میں رہنے والے رشتہ دار وغیرہ ہیں جو وہاں ان کے عیال کی حفاظت کرتے ہیں۔ پس میں نے یہ تحریر لکھی تا کہ وہ میرے عیال کا خیال رکھیں۔ تب اللہ نے یہ آیت ” مومنو! تم میرے اور اپنے دشمنوں کو دوست نہ بناؤ تم ان سے محبت کرتے ہو۔“ نازل ہوئی۔“ اس حدیث کے اول حصے قیس، ابن خطل اور عبد اللہ بن سعد کا حصہ کو قادہ عن انس سے صرف الحکم بن عبد الملک نے روایت کیا۔ اس میں الحسن بن بشر کا تفرد ہے۔","",{"k":"مجمع الزوائد (٦/١٦٨)، مجمع البحرين (٢٧٩٠)، اسناده ضعیف۔","f":"مذکورہ روایت ضعیف ہے۔ دیکھئے (ضعیف العقيلى: ١/ اور مجمع الزوائد: ١٦٨/٦) تاہم دوسری روایات حسن درجے کی ہیں، ان سے ثابت ہے، فتح مکہ کے موقع پر رسول اللہ من سلیم نے چار مردوں اور دو عورتوں کے سوا تمام لوگوں کو امان دے دی تھی۔\n(١) عبد الله بن خطل\n(٢) مقیس بن صبابه\n(٣) عکرمہ بن ابی جہل (٣) عبد اللہ بن سعد بن ابی سرح۔ عورتوں میں ابن خطل یا مقیس بن صبابہ کی لونڈیاں، قریبہ اور فرتنی، ان کے علاوہ اور بھی نام ملتے ہیں۔ دیکھئے (نسائی، کتاب المحاربه: ٤٠٧٢، سنن ابی داؤد: اسلام اور م - مستدرك حاكم: ٤٥/٣، مصنف ابن ابی شیبه ٤٠٥/٧، مسند ابی یعلی: ٤٢١/١) ابن خطل رمسلمانوں کا بہت بڑا دشمن تھا، اس نے مسلمانوں کو بے پناہ نقصان پہنچایا تھا،حافظ ابن حجر عسقلانی ہراللہ فتح الباری میں لکھتے ہیں: اس کی لونڈی بھی قتل کی گئی اور (یہ بھی قتل کیا گیا) اس لیے کہ وہ بھی اس کے جرائم میں شریک کارتھی۔ اسی طرح اس کی دوسری لونڈی ام سعد بھی قتل ہوئی۔ (٢) مقیس بن صبابہ کو لوگوں نے بازار میں جا کر قتل کر دیا (٣) عکرمہ بن ابی جہل یہاں سے بھاگ گئے اور بعد میں مسلمان ہو گئے\n(٤) عبد اللہ بن سعد بن ابی سرح، یہ ابتدا میں رسول اللہ صلی اللہ علیہ وسلم کے کاتب وحی تھے، بعد میں مرتد ہو گئے، اس لیے ان پر سختی کی بعد میں پھر دوبارہ مسلمان ہو گئے تھے، عورتوں میں لونڈیاں جو رسول اللہ ملنے سلیم کی ہجو کیا کرتی تھی، قریب قتل کی گئی اور خرتنی بھاگ گئی اور بعد میں مسلمان ہوگئی تھی۔"}],[6578,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی زلفیں دیکھ رہا ہوں وہ اس جگہ تک پڑتی تھیں، انہوں نے اپنے ہاتھ سے اپنی چھاتی پر اشارہ کیا۔“ اس حدیث کو سماک سے صرف عنبہ بن الا زہر نے روایت کیا۔ اس میں یونس بن بکیر کا تفرد ہے۔ بال مراد ہوتے ہیں۔:٦٥٧٩ مذکورہ روایت میں راوی ابن اسحاق مدلس ہے۔ جمہ سے مراد کندھوں تک پہنچنے والے",""],[6579,"سیدہ ربیع بنت معو زینی ال بیان کرتی ہیں: رسول اللہ ملے کی لکڑی پسند فرماتے","",{"k":"مجمع الزوائد (٣٨٥)، مجمع البحرين (٤٠٧٨)۔","f":"نان تا کڑی، پنجابی میں تر کو بھی کہتے ہیں اور کھیرے کو بھی۔ محمد فواد عبد الباقی مہراللہ نے بھی اس کے دونوں معنی خیار (کھیرا) اور مجو ( لکڑی) ذکر کیے ہیں۔ (حاشیه صحیح مسلم، باب اكل القثاء الخ: ٢٠٤٣) علامہ وحید الزماں جواللہ اور مولانا عبد الحکیم شاہجہان پوری جماللہ دونوں نے اس حدیث سے مراد لکڑی لی ہے۔ عصر حاضر میں بھی کھیرا اور تر کو سلاد کے لیے استعمال کیا جاتا ہے اور اس کو بہت پسند کیا جاتا ہے۔ طب مشرق کے اصولوں کے مطابق لکڑی سرد تا ثیر رکھتی ہے۔"}],[6580,": سیدہ صفیہ بنت حی ولی الہا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے بڑھ کر با اخلاق کسی کو نہیں دیکھا۔ میں نے آپ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم مجھے خیبر سے رات کے وقت اپنی اونٹنی پر اپنے پیچھے بٹھا کر لائے، میں اونگھنے لگی، میرا سر کجاوے کی پچھلی لکڑی کے ساتھ لگتا تو آپ ملے عام اپنے دست مبارک سے مجھے پکڑ کر فرماتے: ”اے! آہستہ، اے جی کی بیٹی! آہستہ حتی کہ جب آپ متعلم الصباء تشریف لائے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”صفیہ! میں نے تمہاری قوم کے ساتھ جو سلوک کیا میں اس پر تم سے معذرت کرتا ہوں، انہوں نے مجھے اس طرح کہا اور انہوں نے مجھے اس طرح کہا۔“ یہ حدیث سیدہ صفیہ بنایا تھا اسے صرف اس اسناد سے مروی ہے۔ اس میں یونس بن بکیر کا تفرد ہے۔","",{"k":"و و و ه و ور ! مجمع الزوائد (١٥/٩)، مجمع البحرين (٣٥٧٥)، مسند ابی یعلی (٧١٢٠)، اسناده ضعيف۔"}],[6581,"سیدنا حذیفہ بن الیمان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم نبوت و رحمت میں ہو، عنقریب خلافت و رحمت ہو گی، پھر اس طرح ہو گا اور اس طرح ہو گا، پھر ظالم بادشاہ ہوں گے، اور وہ شرابیں پئیں گے، ریشم پہنیں گے اور اس میں قیام قیامت تک ان کی مدد کی جائے گی۔“‘ اس حدیث کو العلاء بن المنہال سے صرف زید بن الحباب نے روایت کیا۔","",{"k":"سلسله ضعيفه (٣٠٥٥)، مجمع البحرين (٢٥٠٦)۔"}],[6582,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ” محبت اللہ کی طرف سے ہے اور تذکرہ آسمان میں ہے، پس جب اللہ کسی بندے سے محبت کرتا ہے تو وہ یوں فرماتا ہے: جبریل! تمہارا رب فلاں شخص سے محبت کرتا ہے، پس اس سے محبت کرو، فرمایا: جبریل علینا) اعلان کرتے ہیں، اس کے لیے زمین والوں پر محبت نازل کی جاتی ہے۔“ یہ حدیث سیدنا ابو امامہ نبی الیہ سے صرف اس اسناد سے مروی ہے۔ اس میں الله شریک کا تفرد ہے۔","",{"k":"٦٥٨٢ مجمع البحرين (٤٩٧٨)۔"}],[6583,"سيدنا حذیفہ نبی الیہ نے بیان کیا، مضر قبیلے والوں نے اللہ کے ہر بندے کو آزمائش میں ڈالا یا اسے قتل کیا، حتی کہ ( اللہ ایسے لشکر بھیجے گا کہ ) وہ انہیں ذلیل و رسوا کر دیں گے۔ راوی نے بیان کیا، انہوں نے کہا: آپ یہ بات بیان کرتے ہیں جبکہ آپ خود مصر قبیلے سے ہیں، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے جو فرمایا ہے وہ میں نہ کہوں؟“ اس حدیث کو الاعمش سے صرف عبد اللہ بن نمیر نے روایت کیا۔ مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ مضر کی مذمت بیان کی ہے۔ معلوم ہوا کہ محدثین کرام حدیث کے بیان کرنے میں خیانت نہیں کرتے تھے، بلکہ من وعن بیان کر دیتے۔سلسلہ صحیحہ میں یہ بھی ہے کہ اللہ تعالیٰ اپنے بندوں کے لشکروں کے ذریعے اس (مضر ) کی اس طرح گرفت کرے گا اور ایسے ذلیل کرے گا کہ وہ کسی نالہ کی دم نہ بچا سکے گا۔ (سلسله الصحيحه: ٢٧٥٢)","",{"k":"مجمع الزوائد (٣١٣/٧)، مسند احمد (٥/٣٩٥)، کنز العمال (٣١٣٤٠)، مستدرك حاكم (٤/٥١٧)، مجمع البحرين (٤٤٣١)۔"}],[6584,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو کسی مجلس میں بیٹھے اور وہاں اس کی لغزشیں زیادہ ہو جائیں اور وہ کھڑا ہونے سے پہلے یہ دعا پڑھ لے: پاک ہے تو ہمارے رب اپنی حمد کے ساتھ، تیرے سوا کوئی معبود نہیں، میں تجھ سے مغفرت طلب کرتا ہوں اور تیرے حضور تو بہ کرتا ہوں تو یہ اس کی اس مجلس میں ہونے والی لغزشوں کا کفارہ بن جائے گا۔ اس حدیث کی اسناد میں حجاج اور ابن جریج کے درمیان سفیان کو حجاج سے روایت کرنے والوں میں صرف یحی بن المبارک نے داخل کیا۔ ذکورہ حدیث سے معلوم ہوا کہ جب کسی مجلس میں بیٹھیں تو اٹھنے سے قبل دعا پڑھیں، اس کا","",{"k":"سنن ابو داود (٤٨٥٧، ١٢٢٧)، قال الشيخ الالباني: حسن۔","f":"یہ ہو گا کہ مجلس میں بیٹھ کر جو صغیرہ گناہ ہوئے ہوں گے، وہ معاف کر دیئے جائیں گے، لیکن ان گناہوں سے مراد صغیرہ ہیں، کبیرہ گناہ اور حقوق العباد سے متعلق گناہ نہیں، نبی معظم ملے علی کی لغزشوں سے پاک تھے، اس کے باوجود آپ ملے کہ تم یہ دعا پڑھتے تھے۔ جس سے مقصود اللہ کی حمد وثنا اور تسبیح و تعریف کرنا اور امت کو تعلیم دینا تھا۔ سنن ابی داؤد میں جو دعا ہے اس کے الفاظ یہ ہیں، ((سبحانك اللهم وبحمدك اشهد ان لا اله الا انت استغفرك واتوب اليك)) (ابو داؤد، رقم: ٤٨٥٩) ٦٥٨٥"}],[6585,"سیدنا بریدہ الاسلمی ضیا اہلیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ” بریدہ! کیا میں تمہیں چند کلمات نہ سکھاؤں، اللہ جس کے ساتھ خود بھلائی کا ارادہ کرتا ہے اسے وہ یہ کلمات سکھا دیتا ہے، پھر وہ انہیں کبھی نہیں بھولتا! میں نے عرض کیا: اللہ کے رسول! ضرور سکھائیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کہو: اے اللہ! میں یقیناً کمزور ہوں اپنی رضا میں میرے ضعف کو قوی کر دے، میری پیشانی کو خیر و بھلائی کی طرف لگا دے، اسلام کو میری انتہائی رضا مندی بنا دے۔ اے اللہ! میں ضعیف ہوں، پس مجھے قوی کر دے، میں ذلیل ہوں مجھے عزت بخش اور میں فقیر ہوں، مجھے غنی بنا دے۔ یہ حدیث سیدنا بریدہ نیا لینے سے صرف اس اسناد سے مروی ہے۔ اس میں العلاء بن مسیب کا تفرد ہے۔: الله","",{"k":"ع الزوائد (١٠/١٨٢)، سلسله ضعیفه (٣٣٥٩، ٤٠٦١)، مجمع البحرين (٤٦٨٩)، قال الشيخ الالباني موضوع۔"}],[6586,"سیدہ عائشہ بنی ہا نے بیان کیا، رسول اللہ سے ہم نے فرمایا: \"جو شخص اللہ کے لیے مسجد بناتا ہے، اللہ اس کے لیے جنت میں گھر بنا دیتا ہے۔“ اس حدیث کو عطاء سے صرف کثیر بن عبد الرحمن نے روایت کیا۔","",{"k":"مجمع الزوائد ٨/٢ مجمع البحرين (٤٦٨٩، ٥٨٦)۔"}],[6587,"سیدنا مسور بن مخرمہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، ظلم سے بچو! کیونکہ ظلم قیامت کے دن کئی تاریکیوں کا باعث ہوگا۔ یہ حدیث سیدنا مسور بن مخرمہ رضی اللہ عنہ سے صرف اس اسناد سے مروی ہے۔ اس میں سلیمان بن بلال کا تفرد ہے۔ مذکورہ بالا حدیث سے معلوم ہوا کہ ظلم سے بچنا چاہیے۔ ظلم کی مختلف اقسام ہیں۔ (١) اللہ تعالیٰ کے متعلق ظلم، اس کی سب سے بڑی قسمیں کفر، شرک اور نفاق ہیں، کیونکہ مشرک اللہ کا حق مخلوق کو دیتا ہے اسی لیے اللہ ذوالجلال نے فرمایا: إنَّ الشَّرُكَ لَظُلْمٌ عَظِيمٌ﴾ (لقمان: ١٣) (٢) لوگوں پر ظلم کرنا، اس کی مختلف اقسام کہ لوگوں کی جان یا مال یا عزت پر ظلم کرنا جو کہ ہر طرح حرام ہے۔ (٣) اپنی جان پر ظلم کرنا، جیسا کہ قرآن مجید میں ہے: فَينُهُمْ ظَالِمُ لِنَفْسِهِ (الفاطر: ٣٢) پھر ان میں سے بعض اپنی جان پر ظلم کرنے والے ہیں۔“ ٦٥٨٨","",{"k":"صحیح مسلم: ٨ م (٢٥٧٨، ٣٣٤٠)، صحیح بخاری، الزوائد: ٥ / ٠٥ مجمع كتاب المظالم، رقم: مجمع البحرين (٢٥٦١)۔"}],[6588,"سیدنا ابو الجوزاء نے بیان کیا، ہم سیدنا عبداللہ ابن عباس ریلی لا کے پاس گئے، انہوں نے بیع صرف کے متعلق ہمیں حکم دیا۔ پس میں ایک دفعہ ان کے پاس گیا، انہوں نے کہا، ہم تمہیں حکم دیتے تھے اور ہم تمہیں اس سے منع کرتے ہیں، میں نے کہا: ہم نے اس کے متعلق لوگوں کو جو حکم دیا ہے اس کا ہم کیا کریں؟ انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے ایسے شخص سے ملا ہوں جو اس کے متعلق مجھ سے زیادہ جانتا ہے۔ پس انہوں نے مجھے منع فرمایا، پس جس طرح انہوں نے مجھے منع فرمایا، اسی طرح میں نے تمہیں منع کر دیا۔ اس حدیث کو عقبہ بن ابی تثبیت سے صرف ابو ہلال نے روایت کیا اور وہ آدمی جوسیدنا عبداللہ ابن عباس رضی تنہا سے ملے تھے وہ ابوسعید تھے۔","",{"k":"سنن ابن ماجه (٢٢٥٨)، قال الشيخ الالباني: صحيح۔","f":"بیع صرف کا بیچ صرف کا مطلب یہ ہے کہ سونے کا چاندی سے یا چاندی کا سونے سے یا ایک ملک کی ت م کرنسی کا دوسرے ملک کی کرنسی سے تبادلہ۔ ایک ملک کی کرنسی ایک جنس ہے، دوسرے ملک کی کرنسی دوسری جنس ہے، اگر چہ ان کا نام ایک ہی ہو مثلاً پاکستانی روپیہ اور بھارتی روپیہ الگ الگ جنسیں ہیں، اس پر اتفاق ہے کہ مختلف اجناس کی کرنسی کی تبادلے میں ایک طرف سے نقد ادائیگی اور دوسری طرف سے ادا ئیگی کا وعدہ ناجائز ہے بلکہ دونوں طرف سے نقد ادائیگی شرط ہے، دوسری شرط یہ ہے کہ اگر جنس ایک ہو تو ان میں کمی و بیشی نہ کی جائے۔"}],[6589,"سیدنا ابو نجی بی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مسکین ہے،مسکین ہے، مسکین ہے، وہ شخص جس کی اہلیہ نہ ہو، خواہ وہ بہت مال دار ہو، وہ عورت مسکین ہے، مسکین ہے، مسکین ہے، جس کا شوہر نہ ہو، خواہ وہ بہت مال دار ہو۔ اس حدیث کو ہارون بن رئاب سے صرف محمد بن ثابت نے روایت کیا۔","",{"k":"٦٥٨٩ مجمع الزوائد (٤/٢٥٢)، ضعیف ترغیب و ترهیب (١٢٠٤)، مجمع البحرين (٢٢٣٨)، اسناده ضعیف . ٦٥٩٠۔"}],[6590,"سیدنا جابر بن عبد اللہ اور سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”غیبت زنا سے زیادہ سنگین ہے عرض کیا گیا: وہ کس طرح؟ آپ میم نے فرمایا: \"زانی زنا کرتا ہے پھر وہ توبہ کر لیتا ہے تو اللہ اس کی توبہ قبول فرما لیتا ہے، جبکہ غیبت کرنے والے کی بخشش نہیں ہوتی حتی کہ وہ اسے معاف کر دے جس کی اس نے غیبت کی ہے۔ اس حدیث کو الجریری سے صرف عباد بن کثیر نے روایت: ٦٥٩١ کیا۔ اس میں ابورجاء الخراسانی کا تفرد ہے اور رسول اللہ صلی اللہ علیہ وسلم سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٩١/٨)، ضعيف الجامع الصغير (٢٢٠٤)، مجمع البحرين (٤٩٥٩)، سلسله ضعيفه (١٨٤٦)۔"}],[6591,"سیدہ عائشہ منی اشیا نے بیان کیا، آل رسول اللہ صلی اللہ علیہ وسلم کا ایک جنگلی جانور تھا، وہ آگے پیچھے ہوتا تھا، پس جب رسول اللہ نے ایام تشریف لے آتے تو وہ ٹھہر جاتا تھا اور وہ بلبلاتا نہیں تھا کہ کہیں رسول اللہ صلی اللہ علیہ وسلم کو تکلیف نہ ہو۔ اس حدیث کو مجاہد سے صرف یونس بن ابو اسحاق نے روایت کیا اور سبہ عائشہ بنی المحیا سے صرف اس اسناد سے مروی ہے۔","",{"k":"مجمع الزوائد (٤/٩)، مسند ابی یعلی (٤٤٤١)، مجمع البحرين (٣٥٤٣)، اسناده صحيح۔","f":"رسیده مذکورہ حدیث سے معلوم ہوا کہ جانور بھی رسول اللہ صلی اللہ علیہ وسلم کا مقام و مرتبہ پہچانتے تھے اور ادب و احترام کرتے۔ یہ جانور مقام و مرتبہ کیوں نہ پہچانتے کہ جن جانوروں کے لیے رسول اللہ صلی علی ام رحمت بن کر آئے اور پھر ان کے ساتھ لوگوں کو بھی شفقت کرنے کا حکم دیا۔ امام احمد بن حنبل واللہ صحیح سند کے ساتھ اپنی مسند میں حدیث لائے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انصاری شخص کو منع کیا کہ وہ اونٹ کو تکلیف پہنچائے۔ آپ ملنے سلیم نے اسے کہا: اس جانور کے معاملے میں تو اللہ سے کیوں نہیں ڈرتا، وہ جانور کہ جس کے رب نے تجھے مالک بنایا ہے اس نے میرے پاس تیری شکایت کی ہے اور کہا ہے کہ تو اسے بھوکا رکھتا ہے، جبکہ کام پورا لیتا ہے۔ (مسند احمد: ١/ ٢٠٤، ٢٠٥، ابو داؤد، رقم: ٢٥٤٩)"}],[6592,"سیدہ عائشہ بنایا نہا سے روایت ہے انہوں نے عرض کیا: اللہ کے رسول! وہ کون سی چیز ہے جس کو روک لینا حلال نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”پانی، نمک اور آگ۔“ انہوں نے عرض کیا: یہ پانی جو ہے اسے ہم نے جان لیا تو نمک اور آگ کا کیا معاملہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے نمک دیا گویا کہ اس نے وہ تمام چیزیں صدقہ کیں جنہیں اس نمک نے عمدہ بنایا اور جس نے آگ دی تو گویا اس نے وہ تمام چیز میں صدقہ کیں، جو اس آگ نے پکائیں، جس نے کسی مسلمان کو پانی کا گھونٹ پلایا جہاں پانی موجود تھا تو گویا کہ اس نے غلام آزاد کیا اور جس نے کسی مسلمان کو ایسی جگہ پانی پلایا جہاں پانی نہ تھا تو گویا اس نے اسے زندگی بخش دی۔ زہیر بن مرزوق نے صرف اسے مسند روایت کیا۔ اس میں علی بن غراب کا تفرد ہے۔ ٦٥٩٣","",{"k":"وره وه و، ه و (١٤٣٨)، اسناده ضعيف . مجمع الزوائد (٣/١٣٣)، سنن ابن ماجه (٢٤٧٤)، مجمع البحرين۔"}],[6593,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم سیدنا سعد بن معاذ بنی اللہ کی قبر پر چڑھےتو فرمایا: \"اگر قبر کے دبانے سے کوئی شخص بچتا تو وہ سعد ہوتے، انہیں بھی ایک مرتبہ بھینچا گیا، پھر انہیں چھوڑ دیا گیا۔ اس حدیث کو ابو النصر سے صرف عمرو بن الحارث نے روایت کیا، اس میں ابن وہب کا تفرد ہے۔ پیچھے حدیث گزر چکی ہے۔ حدیث نمبر ٢٧٥٣۔ اگر قبر کے دبانے سے کوئی نجات پاسکتا تو یہ بچہ نجات پا جاتا۔ شیخ البانی ہراللہ نے مذکورہ حدیث پر ” ضمة القبر لا ينجو منها حتى الصبيان“ كى سرخی ثبت کی ہے۔ ان تمام روایات سے یہی معلوم ہوتا ہے کہ قبر ایک بار ضرور دبوچتی ہے۔ اللہ ذوالجلال ہمیں حفظ وامان میں رکھے۔ ( آمین ) اور تمام روایات کے سیاق و سباق کو دیکھا جائے تو یہی کہنا مناسب ہوگا کہ یہ عذاب کی ایک قسم ہے جس سے میت کو تکلیف ہوتی ہے۔ ٦٥٩٤","",{"k":"مجمع الزوائد (٤٦/٣)، مجمع البحرين (١٣١٢)، اسناده حسن۔"}],[6594,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، میں ایک دن رسول اللہ صلی اللہ علیہ وسلم کی معیت میں بازار گیا، پس آپ کپڑا بیچنے والوں کے پاس بیٹھ گئے، آپ نے چار درہموں میں شلوار میں خریدیں، بازار والوں کے لیے ایک وزن کرنے والا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ”وزن کرو اور جھکتا تول۔“ اس وزن کرنے والے نے کہا: یہ ایسی بات ہے جو میں نے کسی سے نہیں سنی۔ سیدنا ابو ہریرہ رضی لینہ نے بیان کیا، میں نے اسے کہا: دین کے معاملے میں تیرے لیے یہ جفا کافی ہے کہ تم اپنے نبی ملنے سے تم کونہیں پہچانتے، پس اس نے ترازو پھینک دیا، جلدی کے ساتھ نبی صلی اللہ علیہ وسلم کے دست مبارک کی طرف لپکا اور اسے بوسہ دیا تو رسول اللہ علیم نے اپنا ہاتھ اس سے چھڑا لیا اور فرمایا: اس طرح کا فعل عجمی لوگ اپنے بادشاہوں کے ساتھ کرتے ہیں، میں تم میں سے ایک آدمی ہوں، پس تول اور جھکتا تول۔“ اور رسول اللہ صلی اللہ علیہ وسلم نے شلواریں پکڑ لیں۔ سیدنا ابو ہریرہ بنی الیہ نے فرمایا: میں گیا تا کہ انہیں آپ سے اٹھالوں تو آپ نے فرمایا: ” چیز کا مالک اپنی چیز کو اٹھانے کا زیادہ حق دار ہے، مگر یہ کہ وہ ضعیف ہو اور وہ اسے اٹھا نہ سکتا ہو تو اس کا مسلمان بھائی اس کی مدد کرے۔“ میں نے عرض کیا: اللہ کے رسول! کیا آپ مے عینی شلوار، پاجامہ پہنتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں رات دن میں اور سفر و حضر میں، مجھے ستر ڈھانپنے کا حکم دیا گیا ہے، پس میں نے اس سے بہتر ستر ڈھانپنے والی کوئی چیز نہیں دیکھی۔“ اس حدیث کو سیدنا ابو ہریرہ رضی یا لینے سے صرف الاغر نے اور الاغر سے صرف عبد الرحمن بن زیاد نے روایت کیا۔ ٥٩٥","",{"k":"مجمع الزوائد (١٢١/٥)، مسند ابی یعلی (٦١٦٢)، اسناده ضعیف، منجم اوسط طبرانی٧ مجمع البحرين (٤٢٢٠)۔"}],[6595,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رات کا کھانا ترک نہ کرو، خواہ مٹھی بھر خشک کھجور میں ہوں، کیونکہ اسے ترک کرنا بڑھاپے کا سبب ہے۔ “یہ سیدنا انس بیانیہ سے صرف اس اسناد سے مروی ہے۔ اس میں ابن السماک کا تفرد ہے۔","",{"k":"٠ / ٨٠٨ ١٠ سنن ترمذى (١٨٥٦)، سنن ابن ماجه (٢٢٥٥)، قال الشيخ الالباني: ضعيف۔"}]]);